#define DEBUG_BREP_BOOLEAN 0

static const double BOOLEAN_ROUNDOFF_TOLERANCE_MULTIPLIER = 2.0;
static const double BOOLEAN_LOOP_CLOSURE_TOLERANCE_MULTIPLIER = 2.0;
static const double BOOLEAN_SOURCE_EDGE_ATTACHMENT_TOLERANCE_MULTIPLIER = 4.0;
static const double BOOLEAN_LOOP_RAY_LENGTH_MULTIPLIER = 2.0;
static const double BOOLEAN_AMBIGUOUS_BRIDGE_TOLERANCE_MULTIPLIER = 64.0;
static const double BOOLEAN_COLLAPSED_LOOP_ROUNDOFF_MULTIPLIER = 64.0;
/* A closed SSI completion may bridge a defect in the intersection curves,
 * but must remain below BRL-CAD's ordinary modeling-distance threshold. */
static const double BOOLEAN_SSI_COMPLETION_TOLERANCE = 0.8 * BN_TOL_DIST;
static const unsigned int BOOLEAN_INTERIOR_POLYGON_MAXIMUM_DEPTH = 48;
static const size_t BOOLEAN_INTERIOR_POLYGON_MAXIMUM_SUBDIVISIONS = 65536;
/*
 * A repaired edge has already been proved to contain both trims within its
 * assigned tolerance.  This transient tag prevents the general tolerance
 * measurement from repeating expensive closest-point searches.  It is
 * removed before a successful result leaves the Boolean implementation.
 */
static const int BOOLEAN_CERTIFIED_EDGE_TOLERANCE_TAG =
    std::numeric_limits<int>::min();
static thread_local BooleanManifoldShadowMetrics boolean_manifold_metrics;
static thread_local struct brep_boolean_failure_info *boolean_failure_info =
    NULL;
static thread_local int boolean_failure_face_index = -1;
static thread_local int boolean_failure_peer_face_index = -1;


static void
initialize_boolean_failure_info(struct brep_boolean_failure_info *failure)
{
    if (failure == NULL)
	return;
    const struct brep_boolean_failure_info initialized =
	BREP_BOOLEAN_FAILURE_INFO_INIT;
    *failure = initialized;
}


class BooleanFailureScope {
public:
    explicit BooleanFailureScope(struct brep_boolean_failure_info *failure)
	: m_previous_failure(boolean_failure_info),
	  m_previous_face(boolean_failure_face_index),
	  m_previous_peer_face(boolean_failure_peer_face_index)
    {
	initialize_boolean_failure_info(failure);
	boolean_failure_info = failure;
	boolean_failure_face_index = -1;
	boolean_failure_peer_face_index = -1;
    }

    ~BooleanFailureScope()
    {
	boolean_failure_info = m_previous_failure;
	boolean_failure_face_index = m_previous_face;
	boolean_failure_peer_face_index = m_previous_peer_face;
    }

private:
    struct brep_boolean_failure_info *m_previous_failure;
    int m_previous_face;
    int m_previous_peer_face;
};


class BooleanFailureFaceScope {
public:
    BooleanFailureFaceScope(int face_index, int peer_face_index = -1)
	: m_previous_face(boolean_failure_face_index),
	  m_previous_peer_face(boolean_failure_peer_face_index)
    {
	boolean_failure_face_index = face_index;
	boolean_failure_peer_face_index = peer_face_index;
    }

    ~BooleanFailureFaceScope()
    {
	boolean_failure_face_index = m_previous_face;
	boolean_failure_peer_face_index = m_previous_peer_face;
    }

private:
    int m_previous_face;
    int m_previous_peer_face;
};


static void
record_boolean_failure(enum brep_boolean_failure_stage stage,
    enum brep_boolean_failure_reason reason, int face_index = -1,
    int peer_face_index = -1, int edge_index = -1,
    int peer_edge_index = -1, double tolerance = 0.0)
{
    if (boolean_failure_info == NULL ||
	boolean_failure_info->stage != BREP_BOOLEAN_FAILURE_STAGE_NONE)
    {
	return;
    }
    boolean_failure_info->stage = stage;
    boolean_failure_info->reason = reason;
    boolean_failure_info->face_index = face_index >= 0 ? face_index :
	boolean_failure_face_index;
    boolean_failure_info->peer_face_index = peer_face_index >= 0 ?
	peer_face_index : boolean_failure_peer_face_index;
    if (edge_index >= 0 || boolean_failure_info->edge_index < 0)
	boolean_failure_info->edge_index = edge_index;
    if (peer_edge_index >= 0 || boolean_failure_info->peer_edge_index < 0)
	boolean_failure_info->peer_edge_index = peer_edge_index;
    boolean_failure_info->tolerance = tolerance;
}


static void
record_boolean_output_topology(const ON_Brep *brep)
{
    if (boolean_failure_info == NULL || brep == NULL)
	return;
    boolean_failure_info->output_naked_edges = 0;
    boolean_failure_info->output_nonmanifold_edges = 0;
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	const int trim_count = brep->m_E[edge_index].TrimCount();
	if (trim_count == 1) {
	    ++boolean_failure_info->output_naked_edges;
	} else if (trim_count != 2) {
	    ++boolean_failure_info->output_nonmanifold_edges;
	}
	if (trim_count != 2 && boolean_failure_info->edge_index < 0)
	    boolean_failure_info->edge_index = edge_index;
    }
}


static void
record_boolean_ambiguous_edge_matches(int count)
{
    if (boolean_failure_info != NULL && count > 0) {
	boolean_failure_info->ambiguous_edge_matches = std::max(
	    boolean_failure_info->ambiguous_edge_matches,
	    static_cast<size_t>(count));
    }
}


static void
record_boolean_edge_repair_failure(
    enum brep_boolean_failure_reason reason, const ON_Brep *brep,
    double tolerance = 0.0, int ambiguous_edge_matches = 0)
{
    record_boolean_output_topology(brep);
    record_boolean_ambiguous_edge_matches(ambiguous_edge_matches);
    record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_EDGE_REPAIR, reason,
	-1, -1, -1, -1, tolerance);
}


static void
record_boolean_intersection_candidates(size_t count)
{
    if (boolean_failure_info != NULL)
	boolean_failure_info->intersection_candidates += count;
}


static void
record_boolean_intersection_events(size_t count)
{
    if (boolean_failure_info != NULL)
	boolean_failure_info->intersection_events += count;
}


static void
record_boolean_projection_failure()
{
    if (boolean_failure_info != NULL)
	++boolean_failure_info->projection_failures;
}


void
boolean_manifold_shadow_metrics_reset()
{
    boolean_manifold_metrics = BooleanManifoldShadowMetrics();
}


BooleanManifoldShadowMetrics
boolean_manifold_shadow_metrics()
{
    return boolean_manifold_metrics;
}


const char *
ON_BooleanStatusDescription(int status)
{
    switch (status) {
	case BREP_BOOLEAN_FAILURE:
	    return "Boolean evaluation failed";
	case BREP_BOOLEAN_INVALID_INPUT:
	    return "invalid Boolean input";
	case BREP_BOOLEAN_INDETERMINATE:
	    return "Boolean result is indeterminate";
	case BREP_BOOLEAN_BUDGET_EXCEEDED:
	    return "Boolean work budget exceeded";
	case BREP_BOOLEAN_UNSUPPORTED:
	    return "unsupported Boolean input or operation";
	case BREP_BOOLEAN_INTERNAL_ERROR:
	    return "internal Boolean error";
	case BREP_BOOLEAN_SUCCESS:
	    return "Boolean evaluation succeeded";
	case BREP_BOOLEAN_EMPTY:
	    return "Boolean result is empty";
	default:
	    return "unknown Boolean result";
    }
}


