static double
boolean_coordinate_roundoff_tolerance(const ON_BoundingBox &bounds)
{
    if (!bounds.IsValid()) {
	return 0.0;
    }

    const double minimum_coordinate_scale = 1.0;
    double coordinate_scale = minimum_coordinate_scale;
    coordinate_scale = std::max(coordinate_scale, fabs(bounds.m_min.x));
    coordinate_scale = std::max(coordinate_scale, fabs(bounds.m_min.y));
    coordinate_scale = std::max(coordinate_scale, fabs(bounds.m_min.z));
    coordinate_scale = std::max(coordinate_scale, fabs(bounds.m_max.x));
    coordinate_scale = std::max(coordinate_scale, fabs(bounds.m_max.y));
    coordinate_scale = std::max(coordinate_scale, fabs(bounds.m_max.z));

    const double tolerance = BOOLEAN_ROUNDOFF_TOLERANCE_MULTIPLIER *
	std::max(ON_ZERO_TOLERANCE, ON_EPSILON * coordinate_scale);
    return std::isfinite(tolerance) ? tolerance : 0.0;
}


static double
boolean_loop_closure_tolerance(double point_tolerance)
{
    if (!(point_tolerance > 0.0) || !std::isfinite(point_tolerance)) {
	return 0.0;
    }

    // The two endpoints of a Boolean boundary may each carry point error.
    const double tolerance = BOOLEAN_LOOP_CLOSURE_TOLERANCE_MULTIPLIER *
	point_tolerance;
    return std::isfinite(tolerance) ? tolerance : 0.0;
}


struct IntersectPoint {
    ON_3dPoint m_pt;	// 3D intersection point
    double m_seg_t;	// param on the loop curve
    int m_loop_seg;	// which curve of the loop
    int m_ssx_curve;	// which intersection curve
    int m_curve_pos;	// rank on the chain
    double m_curve_t;	// param on the SSI curve
    enum {
	UNSET,
	IN_HIT,
	OUT_HIT,
	TANGENT
    } m_dir;		// dir is going inside/outside
    enum {
	NOT_A_LOOP_VERTEX,
	LOOP_VERTEX_AT_START,
	LOOP_VERTEX_AT_END
    } m_vertex_location;
    int m_split_li;	// between clx_points[m_split_li] and
			// clx_points[m_split_li+1]
			// after the outerloop is split
};


// A structure to represent the curve segments generated from surface-surface
// intersections, including some information needed by the connectivity graph
struct SSICurve {
    ON_Curve *m_curve;
    int m_source_face_index;
    int m_peer_face_index;

    SSICurve()
	: m_curve(NULL), m_source_face_index(-1), m_peer_face_index(-1)
    {}

    explicit SSICurve(ON_Curve *curve)
	: m_curve(curve), m_source_face_index(-1), m_peer_face_index(-1)
    {}

    SSICurve(ON_Curve *curve, int source_face_index, int peer_face_index)
	: m_curve(curve), m_source_face_index(source_face_index),
	  m_peer_face_index(peer_face_index)
    {}

    SSICurve(const SSICurve &other)
    {
	m_curve = other.m_curve ? other.m_curve->Duplicate() : NULL;
	m_source_face_index = other.m_source_face_index;
	m_peer_face_index = other.m_peer_face_index;
    }

    SSICurve &operator=(const SSICurve &other)
    {
	if (this != &other) {
	    ON_Curve *curve = other.m_curve ? other.m_curve->Duplicate() : NULL;
	    delete m_curve;
	    m_curve = curve;
	    m_source_face_index = other.m_source_face_index;
	    m_peer_face_index = other.m_peer_face_index;
	}
	return *this;
    }

    ~SSICurve()
    {
	delete m_curve;
	m_curve = NULL;
    }

    void Reset(ON_Curve *curve)
    {
	if (m_curve != curve) {
	    delete m_curve;
	    m_curve = curve;
	}
    }

    void SetProvenance(int source_face_index, int peer_face_index)
    {
	m_source_face_index = source_face_index;
	m_peer_face_index = peer_face_index;
    }
};


struct SharedSSICurve {
    int m_face_index[2];
    ON_Curve *m_curve;
    ON_Curve *m_parameter_curve[2];

    SharedSSICurve()
	: m_curve(NULL)
    {
	m_face_index[0] = m_face_index[1] = -1;
	m_parameter_curve[0] = m_parameter_curve[1] = NULL;
    }

    SharedSSICurve(
	int first_face,
	int second_face,
	ON_Curve *curve,
	ON_Curve *first_parameter_curve,
	ON_Curve *second_parameter_curve)
	: m_curve(curve)
    {
	m_face_index[0] = first_face;
	m_face_index[1] = second_face;
	m_parameter_curve[0] = first_parameter_curve;
	m_parameter_curve[1] = second_parameter_curve;
    }

    SharedSSICurve(const SharedSSICurve &other)
	: m_curve(other.m_curve ? other.m_curve->Duplicate() : NULL)
    {
	m_face_index[0] = other.m_face_index[0];
	m_face_index[1] = other.m_face_index[1];
	m_parameter_curve[0] = other.m_parameter_curve[0] ?
	    other.m_parameter_curve[0]->Duplicate() : NULL;
	m_parameter_curve[1] = other.m_parameter_curve[1] ?
	    other.m_parameter_curve[1]->Duplicate() : NULL;
    }

    SharedSSICurve &operator=(const SharedSSICurve &other)
    {
	if (this != &other) {
	    ON_Curve *curve = other.m_curve ? other.m_curve->Duplicate() : NULL;
	    ON_Curve *first_parameter_curve = other.m_parameter_curve[0] ?
		other.m_parameter_curve[0]->Duplicate() : NULL;
	    ON_Curve *second_parameter_curve = other.m_parameter_curve[1] ?
		other.m_parameter_curve[1]->Duplicate() : NULL;
	    delete m_curve;
	    delete m_parameter_curve[0];
	    delete m_parameter_curve[1];
	    m_curve = curve;
	    m_parameter_curve[0] = first_parameter_curve;
	    m_parameter_curve[1] = second_parameter_curve;
	    m_face_index[0] = other.m_face_index[0];
	    m_face_index[1] = other.m_face_index[1];
	}
	return *this;
    }

    ~SharedSSICurve()
    {
	delete m_curve;
	m_curve = NULL;
	delete m_parameter_curve[0];
	delete m_parameter_curve[1];
	m_parameter_curve[0] = m_parameter_curve[1] = NULL;
    }
};


struct CoplanarFacePair {
    int m_face_index[2];

    CoplanarFacePair()
    {
	m_face_index[0] = m_face_index[1] = -1;
    }

    CoplanarFacePair(int first_face, int second_face)
    {
	m_face_index[0] = first_face;
	m_face_index[1] = second_face;
    }
};


void
append_to_polycurve(ON_Curve *curve, ON_PolyCurve &polycurve);
// We link the SSICurves that share an endpoint, and form this new structure,
// which has many similar behaviors as ON_Curve, e.g. PointAt(), Reverse().
struct LinkedCurve {
private:
    ON_Curve *m_curve;	// an explicit storage of the whole curve
public:
    // The curves contained in this LinkedCurve, including
    // the information needed by the connectivity graph
    ON_ClassArray<SSICurve> m_ssi_curves;
    bool m_certified_same_boundary;

    // Default constructor
    LinkedCurve()
    {
	m_curve = NULL;
	m_certified_same_boundary = false;
    }

    LinkedCurve(const LinkedCurve &other)
    {
	m_curve = NULL;
	*this = other;
    }

    void Empty()
    {
	m_ssi_curves.Empty();
	delete m_curve;
	m_curve = NULL;
	m_certified_same_boundary = false;
    }

    ~LinkedCurve()
    {
	Empty();
    }

    LinkedCurve &operator= (const LinkedCurve &_lc)
    {
	if (this != &_lc) {
	    Empty();
	    m_ssi_curves = _lc.m_ssi_curves;
	    m_certified_same_boundary = _lc.m_certified_same_boundary;
	}
	return *this;
    }

    ON_3dPoint PointAtStart() const
    {
	if (m_ssi_curves.Count() && m_ssi_curves[0].m_curve != NULL) {
	    return m_ssi_curves[0].m_curve->PointAtStart();
	}
	return ON_3dPoint::UnsetPoint;
    }

    ON_3dPoint PointAtEnd() const
    {
	if (m_ssi_curves.Count() &&
	    m_ssi_curves.Last()->m_curve != NULL)
	{
	    return m_ssi_curves.Last()->m_curve->PointAtEnd();
	}
	return ON_3dPoint::UnsetPoint;
    }

    bool IsClosed() const
    {
	if (m_ssi_curves.Count() == 0) {
	    return false;
	}
	if (m_ssi_curves.Count() == 1) {
	    return m_ssi_curves[0].m_curve != NULL &&
		m_ssi_curves[0].m_curve->IsClosed();
	}
	const ON_3dPoint start = PointAtStart();
	const ON_3dPoint end = PointAtEnd();
	return start.IsValid() && end.IsValid() &&
	    start.DistanceTo(end) < ON_ZERO_TOLERANCE;
    }

    bool CloseNearZeroGap()
    {
	if (m_ssi_curves.Count() == 0) {
	    return false;
	}

	const ON_3dPoint start = PointAtStart();
	const ON_3dPoint end = PointAtEnd();
	if (!start.IsValid() || !end.IsValid() ||
	    end.DistanceTo(start) >= ON_ZERO_TOLERANCE)
	{
	    return false;
	}

	ON_Curve *last_curve = m_ssi_curves.Last()->m_curve;
	ON_Curve *closed_curve = last_curve ? last_curve->Duplicate() : NULL;
	if (closed_curve == NULL || !closed_curve->SetEndPoint(start) ||
	    !closed_curve->IsValid())
	{
	    delete closed_curve;
	    return false;
	}

	m_ssi_curves.Last()->Reset(closed_curve);
	delete m_curve;
	m_curve = NULL;
	return IsClosed();
    }

    bool IsValid() const
    {
	if (m_ssi_curves.Count() == 0) {
	    return false;
	}
	for (int i = 0; i < m_ssi_curves.Count(); ++i) {
	    if (m_ssi_curves[i].m_curve == NULL) {
		bu_log("The LinkedCurve contains a null segment.\n");
		return false;
	    }
	}
	// Check whether the curve has "gaps".
	for (int i = 1; i < m_ssi_curves.Count(); i++) {
	    const ON_3dPoint current_start =
		m_ssi_curves[i].m_curve->PointAtStart();
	    const ON_3dPoint previous_end =
		m_ssi_curves[i - 1].m_curve->PointAtEnd();
	    if (current_start.DistanceTo(previous_end) >= ON_ZERO_TOLERANCE) {
		bu_log("The LinkedCurve is not valid.\n");
		return false;
	    }
	}
	return true;
    }

    bool Reverse()
    {
	ON_ClassArray<SSICurve> reversed_curves = m_ssi_curves;
	int count = reversed_curves.Count();
	for (int i = 0; i < count; i++) {
	    if (reversed_curves[i].m_curve == NULL ||
		!reversed_curves[i].m_curve->Reverse())
	    {
		return false;
	    }
	}
	reversed_curves.Reverse();
	m_ssi_curves = reversed_curves;
	delete m_curve;
	m_curve = NULL;
	return true;
    }

    void Append(const LinkedCurve &lc)
    {
	if (lc.m_ssi_curves.Count() == 0) {
	    return;
	}
	delete m_curve;
	m_curve = NULL;
	m_certified_same_boundary = false;
	m_ssi_curves.Append(lc.m_ssi_curves.Count(), lc.m_ssi_curves.Array());
    }

    void Append(const SSICurve &sc)
    {
	delete m_curve;
	m_curve = NULL;
	m_certified_same_boundary = false;
	m_ssi_curves.Append(sc);
    }

    void AppendCurvesToArray(ON_SimpleArray<ON_Curve *> &arr) const
    {
	for (int i = 0; i < m_ssi_curves.Count(); i++) {
	    if (m_ssi_curves[i].m_curve != NULL) {
		arr.Append(m_ssi_curves[i].m_curve->Duplicate());
	    }
	}
    }

    const ON_Curve *Curve()
    {
	if (m_curve != NULL) {
	    return m_curve;
	}
	if (m_ssi_curves.Count() == 0 || !IsValid()) {
	    return NULL;
	}
	ON_PolyCurve *polycurve = new ON_PolyCurve;
	for (int i = 0; i < m_ssi_curves.Count(); i++) {
	    ON_Curve *duplicate = m_ssi_curves[i].m_curve->Duplicate();
	    if (duplicate == NULL) {
		delete polycurve;
		return NULL;
	    }
	    append_to_polycurve(duplicate, *polycurve);
	}
	m_curve = polycurve;
	return m_curve;
    }

    const ON_3dPoint PointAt(double t)
    {
	const ON_Curve *c = Curve();
	if (c == NULL) {
	    return ON_3dPoint::UnsetPoint;
	}
	return c->PointAt(t);
    }

    const ON_Interval Domain()
    {
	const ON_Curve *c = Curve();
	if (c == NULL) {
	    return ON_Interval::EmptyInterval;
	}
	return c->Domain();
    }

    bool SubCurves(double t1, double t2, ON_SimpleArray<ON_Curve *> &out)
    {
	const ON_Curve *curve = Curve();
	if (curve == NULL) {
	    return false;
	}

	ON_Interval requested_domain(t1, t2);
	requested_domain.MakeIncreasing();
	if (!requested_domain.IsIncreasing() ||
	    !curve->Domain().Includes(requested_domain))
	{
	    return false;
	}

	ON_SimpleArray<ON_Curve *> pieces;
	const auto discard_pieces = [&pieces]() {
	    for (int piece_index = 0; piece_index < pieces.Count();
		 ++piece_index)
	    {
		delete pieces[piece_index];
		pieces[piece_index] = NULL;
	    }
	    pieces.Empty();
	};

	const ON_PolyCurve *polycurve = ON_PolyCurve::Cast(curve);
	if (polycurve == NULL || polycurve->Count() < 1) {
	    try {
		ON_Curve *piece = sub_curve(curve, requested_domain.Min(),
		    requested_domain.Max());
		if (piece == NULL) {
		    return false;
		}
		pieces.Append(piece);
	    } catch (InvalidInterval &e) {
		bu_log("%s", e.what());
		return false;
	    }
	} else {
	    for (int segment_index = 0; segment_index < polycurve->Count();
		 ++segment_index)
	    {
		const ON_Curve *segment = polycurve->SegmentCurve(segment_index);
		const ON_Interval polycurve_segment_domain =
		    polycurve->SegmentDomain(segment_index);
		ON_Interval overlap;
		if (segment == NULL || !polycurve_segment_domain.IsIncreasing() ||
		    !overlap.Intersection(requested_domain,
			polycurve_segment_domain) || !overlap.IsIncreasing())
		{
		    continue;
		}
		const double overlap_scale = std::max(1.0, std::max(
		    fabs(polycurve_segment_domain.Min()),
		    fabs(polycurve_segment_domain.Max())));
		if (overlap.Length() <= 256.0 * ON_EPSILON * overlap_scale) {
		    continue;
		}

		const ON_Interval segment_domain = segment->Domain();
		if (!segment_domain.IsIncreasing()) {
		    discard_pieces();
		    return false;
		}
		const double segment_start = polycurve_segment_domain.
		    TransformParameterTo(segment_domain, overlap.Min());
		const double segment_end = polycurve_segment_domain.
		    TransformParameterTo(segment_domain, overlap.Max());
		if (!std::isfinite(segment_start) || !std::isfinite(segment_end)) {
		    discard_pieces();
		    return false;
		}

		try {
		    ON_Curve *piece = sub_curve(segment, segment_start,
			segment_end);
		    if (piece == NULL) {
			discard_pieces();
			return false;
		    }
		    pieces.Append(piece);
		} catch (InvalidInterval &e) {
		    bu_log("%s", e.what());
		    discard_pieces();
		    return false;
		}
	    }
	}

	if (pieces.Count() < 1) {
	    return false;
	}
	for (int piece_index = 1; piece_index < pieces.Count(); ++piece_index) {
	    if (pieces[piece_index - 1]->PointAtEnd().DistanceTo(
		    pieces[piece_index]->PointAtStart()) >= ON_ZERO_TOLERANCE)
	    {
		discard_pieces();
		return false;
	    }
	}

	out.Append(pieces.Count(), pieces.Array());
	pieces.Empty();
	return true;
    }

    bool Trim(double t1, double t2)
    {
	const ON_Curve *whole_curve = Curve();
	if (whole_curve == NULL) {
	    return false;
	}

	ON_Interval requested_domain(t1, t2);
	requested_domain.MakeIncreasing();
	const ON_Interval whole_domain = whole_curve->Domain();
	if (!requested_domain.IsIncreasing() ||
	    !whole_domain.Includes(requested_domain))
	{
	    return false;
	}

	ON_ClassArray<SSICurve> trimmed_curves;
	const ON_PolyCurve *polycurve = ON_PolyCurve::Cast(whole_curve);
	if (m_ssi_curves.Count() > 1 &&
	    (polycurve == NULL || polycurve->Count() != m_ssi_curves.Count()))
	{
	    return false;
	}

	for (int segment_index = 0;
	     segment_index < m_ssi_curves.Count(); ++segment_index)
	{
	    const SSICurve &source_segment = m_ssi_curves[segment_index];
	    if (source_segment.m_curve == NULL) {
		return false;
	    }

	    const ON_Interval whole_segment_domain = polycurve != NULL ?
		polycurve->SegmentDomain(segment_index) : whole_domain;
	    ON_Interval overlap;
	    if (!whole_segment_domain.IsIncreasing() ||
		!overlap.Intersection(requested_domain, whole_segment_domain) ||
		!overlap.IsIncreasing())
	    {
		continue;
	    }
	    const double overlap_scale = std::max(1.0, std::max(
		fabs(whole_segment_domain.Min()),
		fabs(whole_segment_domain.Max())));
	    if (overlap.Length() <= 256.0 * ON_EPSILON * overlap_scale) {
		continue;
	    }

	    const ON_Interval source_domain = source_segment.m_curve->Domain();
	    if (!source_domain.IsIncreasing()) {
		return false;
	    }
	    const double segment_start = whole_segment_domain.TransformParameterTo(
		source_domain, overlap.Min());
	    const double segment_end = whole_segment_domain.TransformParameterTo(
		source_domain, overlap.Max());
	    if (!std::isfinite(segment_start) || !std::isfinite(segment_end) ||
		!(segment_end > segment_start))
	    {
		return false;
	    }

	    ON_Curve *piece = NULL;
	    try {
		piece = sub_curve(source_segment.m_curve, segment_start,
		    segment_end);
	    } catch (InvalidInterval &) {
		return false;
	    }
	    if (piece == NULL || !piece->IsValid()) {
		delete piece;
		return false;
	    }

	    SSICurve &trimmed = trimmed_curves.AppendNew();
	    trimmed.Reset(piece);
	    trimmed.SetProvenance(source_segment.m_source_face_index,
		source_segment.m_peer_face_index);
	}

	LinkedCurve candidate;
	candidate.m_ssi_curves = trimmed_curves;
	if (!candidate.IsValid()) {
	    return false;
	}
	*this = candidate;
	return true;
    }
};


struct TrimmedFace {
    // curve segments in the face's outer loop
    ON_SimpleArray<ON_Curve *> m_outerloop;
    // several inner loops, each has some curves
    std::vector<ON_SimpleArray<ON_Curve *> > m_innerloop;
    const ON_BrepFace *m_face;
    enum {
	UNKNOWN = -1,
	NOT_BELONG = 0,
	BELONG = 1
    } m_belong_to_final;
    bool m_rev;

    // Default constructor
    TrimmedFace()
    {
	m_face = NULL;
	m_belong_to_final = UNKNOWN;
	m_rev = false;
    }

    ~TrimmedFace()
    {
	for (int i = 0; i < m_outerloop.Count(); i++) {
	    if (m_outerloop[i]) {
		delete m_outerloop[i];
		m_outerloop[i] = NULL;
	    }
	}
	for (unsigned int i = 0; i < m_innerloop.size(); i++) {
	    for (int j = 0; j < m_innerloop[i].Count(); j++) {
		if (m_innerloop[i][j]) {
		    delete m_innerloop[i][j];
		    m_innerloop[i][j] = NULL;
		}
	    }
	}
    }

    TrimmedFace *Duplicate() const
    {
	TrimmedFace *out = new TrimmedFace();
	out->m_face = m_face;
	for (int i = 0; i < m_outerloop.Count(); i++) {
	    if (m_outerloop[i]) {
		out->m_outerloop.Append(m_outerloop[i]->Duplicate());
	    }
	}
	out->m_innerloop = m_innerloop;
	for (unsigned int i = 0; i < m_innerloop.size(); i++) {
	    for (int j = 0; j < m_innerloop[i].Count(); j++) {
		if (m_innerloop[i][j]) {
		    out->m_innerloop[i][j] = m_innerloop[i][j]->Duplicate();
		}
	    }
	}
	return out;
    }
};


static int
loop_t_compare(const IntersectPoint *p1, const IntersectPoint *p2)
{
    // Use for sorting an array. Use strict FP comparison.
    if (p1->m_loop_seg != p2->m_loop_seg) {
	return p1->m_loop_seg - p2->m_loop_seg;
    }
    return p1->m_seg_t > p2->m_seg_t ? 1 : (p1->m_seg_t < p2->m_seg_t ? -1 : 0);
}


static int
curve_t_compare(const IntersectPoint *p1, const IntersectPoint *p2)
{
    // Use for sorting an array. Use strict FP comparison.
    return p1->m_curve_t > p2->m_curve_t ? 1 : (p1->m_curve_t < p2->m_curve_t ? -1 : 0);
}


/* Curve/curve intersection reports a shared loop vertex on each of
 * its incident segments.  Give both reports the same outgoing-segment
 * ownership so they can be safely recognized as one crossing. */
static void
canonicalize_outerloop_vertex_hit(
    const ON_SimpleArray<ON_Curve *> &outerloop,
    IntersectPoint &point)
{
    point.m_vertex_location = IntersectPoint::NOT_A_LOOP_VERTEX;

    const int loop_segment_count = outerloop.Count();
    if (loop_segment_count < 2 || point.m_loop_seg < 0 ||
	point.m_loop_seg >= loop_segment_count)
    {
	return;
    }

    ON_Curve *segment = outerloop[point.m_loop_seg];
    if (segment == NULL) {
	return;
    }

    const ON_Interval segment_domain = segment->Domain();
    const bool at_start = ON_NearZero(point.m_seg_t - segment_domain.Min(),
				      ON_ZERO_TOLERANCE);
    const bool at_end = ON_NearZero(point.m_seg_t - segment_domain.Max(),
				    ON_ZERO_TOLERANCE);
    if (!at_start && !at_end) {
	return;
    }

    const ON_3dPoint vertex = at_start ? segment->PointAtStart() :
	segment->PointAtEnd();
    if (point.m_pt.DistanceTo(vertex) > INTERSECTION_TOL) {
	return;
    }

    const int adjacent_segment = at_start ?
	(point.m_loop_seg == 0 ? loop_segment_count - 1 : point.m_loop_seg - 1) :
	(point.m_loop_seg + 1) % loop_segment_count;
    ON_Curve *adjacent = outerloop[adjacent_segment];
    if (adjacent == NULL) {
	return;
    }

    const ON_3dPoint adjacent_vertex = at_start ? adjacent->PointAtEnd() :
	adjacent->PointAtStart();
    if (vertex.DistanceTo(adjacent_vertex) > INTERSECTION_TOL) {
	return;
    }

    if (at_start) {
	point.m_pt = segment->PointAtStart();
	point.m_seg_t = segment_domain.Min();
	point.m_vertex_location = IntersectPoint::LOOP_VERTEX_AT_START;
	return;
    }

    point.m_loop_seg = adjacent_segment;
    point.m_pt = adjacent->PointAtStart();
    point.m_seg_t = adjacent->Domain().Min();
    point.m_vertex_location = IntersectPoint::LOOP_VERTEX_AT_END;
}


static bool
are_duplicate_outerloop_vertex_hits(
    const IntersectPoint &first,
    const IntersectPoint &second)
{
    if (first.m_vertex_location == IntersectPoint::NOT_A_LOOP_VERTEX ||
	second.m_vertex_location == IntersectPoint::NOT_A_LOOP_VERTEX ||
	first.m_vertex_location == second.m_vertex_location)
    {
	return false;
    }

    return first.m_loop_seg == second.m_loop_seg &&
	ON_NearZero(first.m_seg_t - second.m_seg_t, ON_ZERO_TOLERANCE) &&
	ON_NearZero(first.m_curve_t - second.m_curve_t, INTERSECTION_TOL) &&
	first.m_pt.DistanceTo(second.m_pt) <= INTERSECTION_TOL;
}


void
append_to_polycurve(ON_Curve *curve, ON_PolyCurve &polycurve)
{
    append_boolean_loop_curve_to_polycurve(curve, polycurve);
}


static void
close_small_gaps(
    ON_SimpleArray<ON_Curve *> &loop,
    double point_tolerance = INTERSECTION_TOL,
    const ON_Surface *surface = NULL,
    double surface_tolerance = INTERSECTION_TOL);


static bool
is_loop_valid(const ON_SimpleArray<ON_Curve *> &loop, double tolerance, ON_PolyCurve *polycurve = NULL)
{
    bool delete_curve = false;
    bool ret = true;

    if (loop.Count() == 0) {
	bu_log("The input loop is empty.\n");
	ret = false;
    }

    // First, use a ON_PolyCurve to represent the loop.
    if (ret) {
	if (polycurve == NULL) {
	    polycurve = new ON_PolyCurve;
	    if (polycurve) {
		delete_curve = true;
	    } else {
		ret = false;
	    }
	}
    }

    // Check the loop is continuous and closed or not.
    if (ret) {
	if (loop[0] != NULL) {
	    append_to_polycurve(loop[0]->Duplicate(), *polycurve);
	}
	for (int i = 1 ; i < loop.Count(); i++) {
	    const double gap = loop[i] && loop[i - 1] ?
		loop[i]->PointAtStart().DistanceTo(loop[i - 1]->PointAtEnd()) :
		ON_UNSET_VALUE;
	    if (loop[i] && loop[i - 1] && gap < ON_ZERO_TOLERANCE) {
		append_to_polycurve(loop[i]->Duplicate(), *polycurve);
	    } else {
		bu_log("The input loop is not continuous between curves %d/%d "
		    "(gap %.17g).\n", i - 1, i, gap);
		ret = false;
	    }
	}
    }
    const double closure_gap = ret ? polycurve->PointAtStart().DistanceTo(
	polycurve->PointAtEnd()) : 0.0;
    if (ret && closure_gap >= ON_ZERO_TOLERANCE)
    {
	bu_log("The input loop is not closed (gap %.17g).\n", closure_gap);
	ret = false;
    }

    if (ret) {
	// Check whether the loop is degenerated.
	ON_BoundingBox bbox = polycurve->BoundingBox();
	ret = !ON_NearZero(bbox.Diagonal().Length(), tolerance)
	    && !polycurve->IsLinear(tolerance);
    }

    if (delete_curve) {
	delete polycurve;
    }

    return ret;
}


static bool
loop_gap_is_surface_small(
    const ON_3dPoint &first_parameter,
    const ON_3dPoint &second_parameter,
    double parameter_tolerance,
    const ON_Surface *surface,
    double surface_tolerance)
{
    if (surface == NULL || !(parameter_tolerance > 0.0) ||
	!(surface_tolerance > 0.0) || !first_parameter.IsValid() ||
	!second_parameter.IsValid())
    {
	return false;
    }

    const double parameter_gap = first_parameter.DistanceTo(second_parameter);
    const double guarded_parameter_tolerance =
	BOOLEAN_AMBIGUOUS_BRIDGE_TOLERANCE_MULTIPLIER * parameter_tolerance;
    if (!std::isfinite(parameter_gap) ||
	parameter_gap > guarded_parameter_tolerance)
    {
	return false;
    }

    const ON_3dPoint first_point = surface->PointAt(first_parameter.x,
	first_parameter.y);
    const ON_3dPoint second_point = surface->PointAt(second_parameter.x,
	second_parameter.y);
    return first_point.IsValid() && second_point.IsValid() &&
	first_point.DistanceTo(second_point) <= surface_tolerance;
}


static bool
loop_requires_gap_normalization(
    const ON_SimpleArray<ON_Curve *> &loop,
    double closure_tolerance,
    const ON_Surface *surface = NULL,
    double surface_tolerance = INTERSECTION_TOL)
{
    if (!(closure_tolerance > 0.0) ||
	!std::isfinite(closure_tolerance))
    {
	return false;
    }

    for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	const ON_Curve *curve = loop[curve_index];
	const ON_Curve *next_curve = loop[(curve_index + 1) % loop.Count()];
	if (curve == NULL || next_curve == NULL) {
	    return false;
	}

	const double gap = curve->PointAtEnd().DistanceTo(
	    next_curve->PointAtStart());
	if (std::isfinite(gap) && gap >= ON_ZERO_TOLERANCE &&
	    (gap <= closure_tolerance || loop_gap_is_surface_small(
		curve->PointAtEnd(), next_curve->PointAtStart(),
		closure_tolerance, surface, surface_tolerance)))
	{
	    return true;
	}
    }

    return false;
}


class NormalizedBooleanLoop {
public:
    ~NormalizedBooleanLoop()
    {
	Clear();
    }

    bool
    Initialize(
	const ON_SimpleArray<ON_Curve *> &loop,
	double closure_tolerance,
	const ON_Surface *surface = NULL,
	double surface_tolerance = INTERSECTION_TOL)
    {
	if (!(closure_tolerance > 0.0) ||
	    !std::isfinite(closure_tolerance))
	{
	    return false;
	}

	for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	    ON_Curve *curve = loop[curve_index] ?
		loop[curve_index]->Duplicate() : NULL;
	    if (curve == NULL || !curve->IsValid()) {
		delete curve;
		Clear();
		return false;
	    }
	    m_loop.Append(curve);
	}

	close_small_gaps(m_loop, closure_tolerance, surface,
	    surface_tolerance);
	if (!is_loop_valid(m_loop, ON_ZERO_TOLERANCE)) {
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Boolean classification-loop normalization failed: %d curves, "
		    "closure tolerance %.17g, surface tolerance %.17g.\n",
		    m_loop.Count(), closure_tolerance, surface_tolerance);
		for (int curve_index = 0; curve_index < m_loop.Count();
		     ++curve_index)
		{
		    const ON_Curve *curve = m_loop[curve_index];
		    const ON_Curve *next_curve = m_loop[
			(curve_index + 1) % m_loop.Count()];
		    if (curve == NULL || next_curve == NULL)
			continue;
		    const ON_3dPoint end = curve->PointAtEnd();
		    const ON_3dPoint start = next_curve->PointAtStart();
		    const ON_3dPoint model_end = surface ? surface->PointAt(
			end.x, end.y) : ON_3dPoint::UnsetPoint;
		    const ON_3dPoint model_start = surface ? surface->PointAt(
			start.x, start.y) : ON_3dPoint::UnsetPoint;
		    const ON_ClassId *curve_class = curve->ClassId();
		    const ON_ClassId *next_class = next_curve->ClassId();
		    bu_log("  junction %d/%d: UV gap %.17g, model gap %.17g, "
			"UV (%.17g, %.17g) -> (%.17g, %.17g), classes %s/%s.\n",
			curve_index, (curve_index + 1) % m_loop.Count(),
			end.DistanceTo(start), model_end.DistanceTo(model_start),
			end.x, end.y, start.x, start.y,
			curve_class ? curve_class->ClassName() : "unknown",
			next_class ? next_class->ClassName() : "unknown");
		}
	    }
	    Clear();
	    return false;
	}

	return true;
    }

    const ON_SimpleArray<ON_Curve *> &
    Loop() const
    {
	return m_loop;
    }

private:
    void
    Clear()
    {
	for (int curve_index = 0; curve_index < m_loop.Count();
	     ++curve_index)
	{
	    delete m_loop[curve_index];
	    m_loop[curve_index] = NULL;
	}
	m_loop.Empty();
    }

    ON_SimpleArray<ON_Curve *> m_loop;
};


static const ON_SimpleArray<ON_Curve *> &
normalized_loop_for_point_classification(
    const ON_SimpleArray<ON_Curve *> &loop,
    double intersection_tolerance,
    NormalizedBooleanLoop &normalized_loop,
    const ON_Surface *surface = NULL,
    double surface_tolerance = INTERSECTION_TOL)
{
    const double closure_tolerance =
	boolean_loop_closure_tolerance(intersection_tolerance);
    if (!loop_requires_gap_normalization(loop, closure_tolerance, surface,
	    surface_tolerance)) {
	return loop;
    }

    if (!normalized_loop.Initialize(loop, closure_tolerance, surface,
	    surface_tolerance)) {
	throw InvalidGeometry("point classification given invalid loop\n");
    }

    return normalized_loop.Loop();
}


enum {
    OUTSIDE_OR_ON_LOOP,
    INSIDE_OR_ON_LOOP
};


static bool
curve_parameter_matches_point_with_tolerance(
    const ON_Curve *curve,
    double curve_parameter,
    const ON_3dPoint &point,
    double point_tolerance);


static bool
point_3d_to_curve_parameter_with_tolerance(
    const ON_3dPoint &point,
    const ON_Curve *curve,
    double point_tolerance,
    double &curve_parameter,
    bool report_failure = true);


static bool
canonicalize_boolean_intersection_parameter(
    const ON_Curve *curve,
    const ON_3dPoint &point,
    double point_tolerance,
    double &curve_parameter)
{
    if (curve_parameter_matches_point_with_tolerance(curve,
	    curve_parameter, point, point_tolerance))
    {
	return true;
    }

    double native_parameter = ON_UNSET_VALUE;
    if (!point_3d_to_curve_parameter_with_tolerance(point, curve,
	    point_tolerance, native_parameter, false))
    {
	return false;
    }

    curve_parameter = native_parameter;
    return true;
}


static int
intersect_boolean_curves(
    const ON_Curve *first_curve,
    const ON_Curve *second_curve,
    ON_SimpleArray<ON_X_EVENT> &events,
    double tolerance)
{
    if (first_curve == NULL || second_curve == NULL) {
	throw InvalidGeometry("Curve intersection given a null curve.\n");
    }
    ON_SimpleArray<ON_X_EVENT> candidates;
    const int event_count = ON_Intersect(first_curve, second_curve, candidates,
	tolerance);
    if (event_count == BREP_CCI_BUDGET_EXCEEDED) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_SURFACE_INTERSECTION,
	    BREP_BOOLEAN_FAILURE_REASON_WORK_BUDGET, -1, -1, -1, -1,
	    tolerance);
	throw BooleanBudgetExceeded(
	    "Curve intersection work limit exceeded.\n");
    }

    /* ON_Intersect may return parameters in the NURBS representation's
     * domain for curve classes whose native parameterization differs from
     * their NURBS form.  All Boolean consumers evaluate the original curves,
     * so normalize every reported endpoint before exposing the events. */
    for (int event_index = 0; event_index < candidates.Count(); ++event_index) {
	ON_X_EVENT event = candidates[event_index];
	const int endpoint_count = event.m_type == ON_X_EVENT::ccx_overlap ? 2 :
	    event.m_type == ON_X_EVENT::ccx_point ? 1 : 0;
	bool certified = endpoint_count > 0;
	for (int endpoint = 0; endpoint < endpoint_count; ++endpoint) {
	    if (!event.m_A[endpoint].IsValid() ||
		!event.m_B[endpoint].IsValid() ||
		event.m_A[endpoint].DistanceTo(event.m_B[endpoint]) > tolerance)
	    {
		certified = false;
		break;
	    }
	    const bool first_normalized =
		canonicalize_boolean_intersection_parameter(first_curve,
		    event.m_A[endpoint], tolerance, event.m_a[endpoint]);
	    const bool second_normalized =
		canonicalize_boolean_intersection_parameter(second_curve,
		    event.m_B[endpoint], tolerance, event.m_b[endpoint]);
	    if (!first_normalized || !second_normalized) {
		certified = false;
		break;
	    }
	}
	if (!certified) {
	    continue;
	}
	if (event.m_type == ON_X_EVENT::ccx_point) {
	    event.m_a[1] = event.m_a[0];
	    event.m_b[1] = event.m_b[0];
	}
	events.Append(event);
    }
    return events.Count();
}


static bool
is_point_on_normalized_loop(
    const ON_2dPoint &pt,
    const ON_SimpleArray<ON_Curve *> &loop,
    double intersection_tolerance);


static bool
point_loop_ray_location(
    const ON_2dPoint &pt,
    const ON_SimpleArray<ON_Curve *> &loop,
    const ON_2dVector &candidate_direction,
    double ray_length,
    double intersection_tolerance,
    int &location,
    int *ambiguity_reason = NULL)
{
    if (ambiguity_reason != NULL)
	*ambiguity_reason = 0;
    ON_2dVector ray_vector(candidate_direction);
    if (!ray_vector.Unitize()) {
	if (ambiguity_reason != NULL)
	    *ambiguity_reason = 1;
	return false;
    }

    const ON_2dPoint ray_end = pt + ray_vector * ray_length;
    ON_LineCurve ray(pt, ray_end);
    const ON_3dVector ray_direction = ray.m_line.Direction();
    const ON_3dPoint ray_start_3d(pt);
    const ON_3dPoint ray_end_3d(ray_end);
    std::vector<ON_3dPoint> crossings;

    for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	const ON_Curve *curve = loop[curve_index];
	if (curve == NULL) {
	    if (ambiguity_reason != NULL)
		*ambiguity_reason = 2;
	    return false;
	}

	const ON_3dPoint curve_start = curve->PointAtStart();
	const ON_3dPoint curve_end = curve->PointAtEnd();
	if (!curve_start.IsValid() || !curve_end.IsValid()) {
	    if (ambiguity_reason != NULL)
		*ambiguity_reason = 3;
	    return false;
	}

	ON_SimpleArray<ON_X_EVENT> events;
	intersect_boolean_curves(&ray, curve, events, intersection_tolerance);
	for (int event_index = 0; event_index < events.Count(); ++event_index) {
	    const ON_X_EVENT &event = events[event_index];
	    int event_ambiguity = 0;
	    if (event.m_type != ON_X_EVENT::ccx_point)
		event_ambiguity = 4;
	    else if (!event.m_A[0].IsValid() || !event.m_B[0].IsValid())
		event_ambiguity = 5;
	    else if (event.m_A[0].DistanceTo(event.m_B[0]) >
		    intersection_tolerance)
		event_ambiguity = 6;
	    else if (event.m_A[0].DistanceTo(ray_start_3d) <=
		    intersection_tolerance)
		event_ambiguity = 7;
	    else if (event.m_A[0].DistanceTo(ray_end_3d) <=
		    intersection_tolerance)
		event_ambiguity = 8;
	    else if (event.m_B[0].DistanceTo(curve_start) <=
		    intersection_tolerance)
		event_ambiguity = 9;
	    else if (event.m_B[0].DistanceTo(curve_end) <=
		    intersection_tolerance)
		event_ambiguity = 10;
	    if (event_ambiguity != 0)
	    {
		if (ambiguity_reason != NULL)
		    *ambiguity_reason = event_ambiguity;
		return false;
	    }

	    const ON_3dVector tangent = curve->TangentAt(event.m_b[0]);
	    if (!tangent.IsValid() || tangent.Length() <= ON_ZERO_TOLERANCE)
	    {
		if (ambiguity_reason != NULL)
		    *ambiguity_reason = 11;
		return false;
	    }
	    if (tangent.IsParallelTo(ray_direction, ANGLE_TOL)) {
		if (ambiguity_reason != NULL)
		    *ambiguity_reason = 12;
		return false;
	    }

	    for (size_t crossing_index = 0;
		 crossing_index < crossings.size(); ++crossing_index)
	    {
		if (crossings[crossing_index].DistanceTo(event.m_A[0]) <=
		    intersection_tolerance)
		{
		    if (ambiguity_reason != NULL)
			*ambiguity_reason = 13;
		    return false;
		}
	    }
	    crossings.push_back(event.m_A[0]);
	}
    }

    location = crossings.size() % 2 ? INSIDE_OR_ON_LOOP :
	OUTSIDE_OR_ON_LOOP;
    return true;
}


//   Returns whether the point is inside/on or outside/on the loop
//   boundary.
//
//   Throws InvalidGeometry if loop is invalid.
//
//   If you want to know whether this point is on the loop boundary,
//   call is_point_on_loop().
static int
point_loop_location(
    const ON_2dPoint &pt,
    const ON_SimpleArray<ON_Curve *> &loop,
    double intersection_tolerance = INTERSECTION_TOL,
    const ON_Surface *surface = NULL)
{
    if (!(intersection_tolerance > 0.0) ||
	!std::isfinite(intersection_tolerance))
    {
	throw InvalidGeometry("point_loop_location() given invalid tolerance\n");
    }

    NormalizedBooleanLoop normalized_loop;
    const ON_SimpleArray<ON_Curve *> &classification_loop =
	normalized_loop_for_point_classification(loop, intersection_tolerance,
	    normalized_loop, surface,
	    boolean_loop_closure_tolerance(INTERSECTION_TOL));

    ON_PolyCurve polycurve;
    if (!is_loop_valid(classification_loop, ON_ZERO_TOLERANCE, &polycurve)) {
	throw InvalidGeometry("point_loop_location() given invalid loop\n");
    }

    ON_BoundingBox bbox = polycurve.BoundingBox();
    if (!bbox.IsPointIn(pt)) {
	return OUTSIDE_OR_ON_LOOP;
    }
    if (is_point_on_normalized_loop(pt, classification_loop,
	intersection_tolerance))
    {
	return INSIDE_OR_ON_LOOP;
    }

    const ON_3dVector bbox_diagonal = bbox.Diagonal();
	const ON_2dVector bbox_diagonal_2d(bbox_diagonal.x, bbox_diagonal.y);
    const double bbox_diagonal_length = bbox_diagonal_2d.Length();
    if (!(bbox_diagonal_length > 0.0) ||
	!std::isfinite(bbox_diagonal_length))
    {
	throw InvalidGeometry("point_loop_location() given invalid loop bounds\n");
    }

    const double diagonal_ratio = sqrt(2.0);
    const ON_2dVector candidate_directions[] = {
	bbox_diagonal_2d,
	ON_2dVector(-bbox_diagonal_2d.y, bbox_diagonal_2d.x),
	ON_2dVector(1.0, diagonal_ratio),
	ON_2dVector(diagonal_ratio, -1.0),
	ON_2dVector(-1.0, diagonal_ratio),
	ON_2dVector(diagonal_ratio, 1.0)
    };
    const double ray_length = BOOLEAN_LOOP_RAY_LENGTH_MULTIPLIER *
	bbox_diagonal_length;
    int ambiguity_counts[14] = {};
    for (size_t direction_index = 0;
	 direction_index < sizeof(candidate_directions) /
	 sizeof(candidate_directions[0]); ++direction_index)
    {
	int location = OUTSIDE_OR_ON_LOOP;
	int ambiguity_reason = 0;
	if (point_loop_ray_location(pt, classification_loop,
		candidate_directions[direction_index], ray_length,
		intersection_tolerance, location, &ambiguity_reason))
	{
	    return location;
	}
	if (ambiguity_reason >= 0 && ambiguity_reason < 14)
	    ++ambiguity_counts[ambiguity_reason];
    }

    /* Loop vertices and curve tangencies invalidate an otherwise useful
     * parity ray.  Symmetric and repeatedly patterned geometry can defeat a
     * small fixed direction set, so continue with a deterministic irrational
     * angular sequence.  Each accepted result still comes only from the
     * strict, unambiguous crossing test above. */
    static const int alternate_direction_count = 64;
    const double golden_angle = ON_PI * (3.0 - std::sqrt(5.0));
    for (int direction_index = 0;
	 direction_index < alternate_direction_count; ++direction_index)
    {
	const double angle = (direction_index + 0.5) * golden_angle;
	const ON_2dVector direction(std::cos(angle), std::sin(angle));
	int location = OUTSIDE_OR_ON_LOOP;
	int ambiguity_reason = 0;
	if (point_loop_ray_location(pt, classification_loop, direction,
		ray_length, intersection_tolerance, location,
		&ambiguity_reason))
	{
	    return location;
	}
	if (ambiguity_reason >= 0 && ambiguity_reason < 14)
	    ++ambiguity_counts[ambiguity_reason];
    }
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("point_loop_location: point %.17g %.17g exhausted ray "
	    "directions; ambiguity counts", pt.x, pt.y);
	for (int reason = 1; reason < 14; ++reason) {
	    if (ambiguity_counts[reason] > 0)
		bu_log(" %d:%d", reason, ambiguity_counts[reason]);
	}
	bu_log(".\n");
    }

    throw InvalidGeometry(
	"point_loop_location() could not select an unambiguous ray\n");
}


// Returns whether or not point is on the loop boundary.
// Throws InvalidGeometry if loop is invalid.
static bool
is_point_on_normalized_loop(
    const ON_2dPoint &pt,
    const ON_SimpleArray<ON_Curve *> &loop,
    double intersection_tolerance = INTERSECTION_TOL)
{
    if (!(intersection_tolerance > 0.0) ||
	!std::isfinite(intersection_tolerance))
    {
	throw InvalidGeometry("is_point_on_loop() given invalid tolerance\n");
    }

    ON_PolyCurve polycurve;
    if (!is_loop_valid(loop, ON_ZERO_TOLERANCE, &polycurve)) {
	throw InvalidGeometry("is_point_on_loop() given invalid loop\n");
    }

    ON_3dPoint pt3d(pt);
    for (int i = 0; i < loop.Count(); ++i) {
	if (loop[i] == NULL) {
	    continue;
	}
	const ON_3dPoint start = loop[i]->PointAtStart();
	const ON_3dPoint end = loop[i]->PointAtEnd();
	if ((start.IsValid() && start.DistanceTo(pt3d) <=
		intersection_tolerance) ||
	    (end.IsValid() && end.DistanceTo(pt3d) <=
		intersection_tolerance))
	{
	    return true;
	}
	double curve_parameter = ON_UNSET_VALUE;
	if (point_3d_to_curve_parameter_with_tolerance(pt3d, loop[i],
		intersection_tolerance, curve_parameter, false))
	{
	    return true;
	}
	ON_ClassArray<ON_PX_EVENT> px_event;
	if (ON_Intersect(pt3d, *loop[i], px_event,
		 intersection_tolerance)) {
	    return true;
	}
    }
    return false;
}


static bool
is_point_on_loop(
    const ON_2dPoint &pt,
    const ON_SimpleArray<ON_Curve *> &loop,
    double intersection_tolerance = INTERSECTION_TOL)
{
    if (!(intersection_tolerance > 0.0) ||
	!std::isfinite(intersection_tolerance))
    {
	throw InvalidGeometry("is_point_on_loop() given invalid tolerance\n");
    }

    NormalizedBooleanLoop normalized_loop;
    const ON_SimpleArray<ON_Curve *> &classification_loop =
	normalized_loop_for_point_classification(loop, intersection_tolerance,
	    normalized_loop);

    ON_PolyCurve polycurve;
    if (!is_loop_valid(classification_loop, ON_ZERO_TOLERANCE, &polycurve)) {
	bu_log("is_point_on_loop(): classification tolerance %.17g, "
	    "closure tolerance %.17g, %d curves.\n",
	    intersection_tolerance,
	    boolean_loop_closure_tolerance(intersection_tolerance),
	    classification_loop.Count());
	throw InvalidGeometry("is_point_on_loop() given invalid loop\n");
    }

    return is_point_on_normalized_loop(pt, classification_loop,
	intersection_tolerance);
}


static bool
is_point_inside_loop(
    const ON_2dPoint &pt,
    const ON_SimpleArray<ON_Curve *> &loop,
    double intersection_tolerance = INTERSECTION_TOL)
{
    return point_loop_location(pt, loop, intersection_tolerance) ==
	INSIDE_OR_ON_LOOP && !is_point_on_loop(pt, loop,
	intersection_tolerance);
}


static bool
is_point_outside_loop(
    const ON_2dPoint &pt,
    const ON_SimpleArray<ON_Curve *> &loop,
    double intersection_tolerance = INTERSECTION_TOL)
{
    return point_loop_location(pt, loop, intersection_tolerance) ==
	OUTSIDE_OR_ON_LOOP && !is_point_on_loop(pt, loop,
	intersection_tolerance);
}


static bool
append_face_trim_loop(
    const ON_Brep *brep,
    int loop_index,
    ON_ClassArray<ON_SimpleArray<ON_Curve *> > &face_loops)
{
    if (brep == NULL || loop_index < 0 || loop_index >= brep->m_L.Count()) {
	return false;
    }

    const ON_BrepLoop &brep_loop = brep->m_L[loop_index];
    if (brep_loop.m_ti.Count() < 1) {
	return false;
    }

    ON_SimpleArray<ON_Curve *> loop_curves;
    for (int trim_position = 0; trim_position < brep_loop.m_ti.Count();
	 ++trim_position)
    {
	const int trim_index = brep_loop.m_ti[trim_position];
	if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
	    return false;
	}

	const ON_BrepTrim &trim = brep->m_T[trim_index];
	if (trim.m_c2i < 0 || trim.m_c2i >= brep->m_C2.Count() ||
	    brep->m_C2[trim.m_c2i] == NULL)
	{
	    return false;
	}

	loop_curves.Append(brep->m_C2[trim.m_c2i]);
    }

    face_loops.Append(loop_curves);
    return true;
}


static bool
face_trim_loops(
    const ON_Brep *brep,
    int face_index,
    ON_ClassArray<ON_SimpleArray<ON_Curve *> > &face_loops)
{
    face_loops.Empty();
    if (brep == NULL || face_index < 0 || face_index >= brep->m_F.Count()) {
	return false;
    }

    const ON_BrepFace &face = brep->m_F[face_index];
    if (face.m_li.Count() < 1) {
	return false;
    }

    int outer_loop_index = -1;
    for (int loop_position = 0; loop_position < face.m_li.Count();
	 ++loop_position)
    {
	const int loop_index = face.m_li[loop_position];
	if (loop_index < 0 || loop_index >= brep->m_L.Count()) {
	    return false;
	}

	const ON_BrepLoop &brep_loop = brep->m_L[loop_index];
	if (brep_loop.m_type == ON_BrepLoop::outer) {
	    if (outer_loop_index >= 0) {
		return false;
	    }
	    outer_loop_index = loop_index;
	}
    }

    if (outer_loop_index < 0 ||
	!append_face_trim_loop(brep, outer_loop_index, face_loops))
    {
	return false;
    }

    for (int loop_position = 0; loop_position < face.m_li.Count();
	 ++loop_position)
    {
	const int loop_index = face.m_li[loop_position];
	if (loop_index != outer_loop_index &&
	    !append_face_trim_loop(brep, loop_index, face_loops))
	{
	    return false;
	}
    }

    return true;
}


static bool
closed_curve_loci_coincident(
    const ON_Curve &first,
    const ON_Curve &second,
    double tolerance)
{
    if (!first.IsClosed() || !second.IsClosed() ||
	first.Dimension() != second.Dimension() || !(tolerance > 0.0) ||
	!std::isfinite(tolerance))
    {
	return false;
    }
    if (brep_curves_coincident(first, second, tolerance)) {
	return true;
    }

    ON_NurbsCurve second_nurbs;
    if (second.GetNurbForm(second_nurbs) <= 0 ||
	!second_nurbs.IsValid())
    {
	return false;
    }
    double seam_parameter = second_nurbs.Domain().Min();
    const ON_3dPoint first_start = first.PointAtStart();
    if (!first_start.IsValid() || !ON_NurbsCurve_GetClosestPoint(
	    &seam_parameter, &second_nurbs, first_start) ||
	second_nurbs.PointAt(seam_parameter).DistanceTo(first_start) > tolerance)
    {
	return false;
    }

    std::unique_ptr<ON_Curve> reseamed(second.DuplicateCurve());
    return reseamed && reseamed->ChangeClosedCurveSeam(seam_parameter) &&
	reseamed->IsValid() &&
	brep_curves_coincident(first, *reseamed, tolerance);
}


static ON_Curve *
boolean_surface_parameter_curve(const ON_Curve &curve);

static bool
append_parameter_isocurve_intervals(
    const ON_Curve &curve,
    int constant_direction,
    double constant_coordinate,
    int varying_direction,
    double tolerance,
    std::vector<ON_Interval> &intervals)
{
    const ON_BoundingBox bounds = curve.BoundingBox();
    if (bounds.IsValid() &&
	fabs(bounds.m_min[constant_direction] - constant_coordinate) <=
	    tolerance &&
	fabs(bounds.m_max[constant_direction] - constant_coordinate) <=
	    tolerance)
    {
	ON_Interval interval(bounds.m_min[varying_direction],
	    bounds.m_max[varying_direction]);
	if (interval.IsIncreasing() && interval.Length() > tolerance) {
	    intervals.push_back(interval);
	}
	return true;
    }

    const ON_PolyCurve *polycurve = ON_PolyCurve::Cast(&curve);
    if (polycurve != NULL) {
	for (int segment_index = 0; segment_index < polycurve->Count();
	     ++segment_index)
	{
	    const ON_Curve *segment = polycurve->SegmentCurve(segment_index);
	    if (segment == NULL || !append_parameter_isocurve_intervals(*segment,
		    constant_direction, constant_coordinate, varying_direction,
		    tolerance, intervals))
	    {
		return false;
	    }
	}
	return polycurve->Count() > 0;
    }

    const ON_PolylineCurve *polyline = ON_PolylineCurve::Cast(&curve);
    if (polyline != NULL) {
	if (polyline->m_pline.Count() < 2) {
	    return false;
	}
	for (int point_index = 0; point_index < polyline->m_pline.Count();
	     ++point_index)
	{
	    const ON_3dPoint &point = polyline->m_pline[point_index];
	    if (!point.IsValid() || fabs(point[constant_direction] -
		    constant_coordinate) > tolerance)
	    {
		return false;
	    }
	    if (point_index > 0) {
		ON_Interval interval(
		    polyline->m_pline[point_index - 1][varying_direction],
		    point[varying_direction]);
		interval.MakeIncreasing();
		if (interval.IsIncreasing() && interval.Length() > tolerance) {
		    intervals.push_back(interval);
		}
	    }
	}
	return true;
    }

    if (!curve.IsLinear(tolerance)) {
	return false;
    }
    const ON_3dPoint start = curve.PointAtStart();
    const ON_3dPoint end = curve.PointAtEnd();
    if (!start.IsValid() || !end.IsValid() ||
	fabs(start[constant_direction] - constant_coordinate) > tolerance ||
	fabs(end[constant_direction] - constant_coordinate) > tolerance)
    {
	return false;
    }
    ON_Interval interval(start[varying_direction], end[varying_direction]);
    interval.MakeIncreasing();
    if (interval.IsIncreasing() && interval.Length() > tolerance) {
	intervals.push_back(interval);
    }
    return true;
}


static bool
parameter_isocurve_is_covered_by_boundary_curves(
    const ON_Curve &curve,
    const std::vector<const ON_Curve *> &boundary_curves,
    const ON_Surface &surface,
    double tolerance)
{
    if (!(tolerance > 0.0) || !std::isfinite(tolerance)) {
	return false;
    }

    const ON_3dPoint start = curve.PointAtStart();
    const ON_3dPoint end = curve.PointAtEnd();
    if (!start.IsValid() || !end.IsValid()) {
	return false;
    }

    const double coordinate_change[2] = {
	fabs(end.x - start.x), fabs(end.y - start.y)
    };
    const int constant_direction = coordinate_change[0] <= tolerance ? 0 :
	(coordinate_change[1] <= tolerance ? 1 : -1);
    if (constant_direction < 0) {
	return false;
    }
    const int varying_direction = 1 - constant_direction;
    const double constant_coordinate = constant_direction == 0 ? start.x :
	start.y;
    const ON_Interval surface_domain = surface.Domain(constant_direction);
    if (!surface_domain.IsIncreasing() ||
	std::min(fabs(constant_coordinate - surface_domain.Min()),
	    fabs(constant_coordinate - surface_domain.Max())) > tolerance)
    {
	return false;
    }

    const double boundary_coordinate =
	fabs(constant_coordinate - surface_domain.Min()) <
	fabs(constant_coordinate - surface_domain.Max()) ?
	surface_domain.Min() : surface_domain.Max();
    std::vector<ON_Interval> targets;
    if (!append_parameter_isocurve_intervals(curve, constant_direction,
	    boundary_coordinate, varying_direction, tolerance, targets) ||
	targets.empty())
    {
	return false;
    }

    std::vector<ON_Interval> covered;
    for (const ON_Curve *boundary : boundary_curves) {
	std::unique_ptr<ON_Curve> parameter_curve(
	    boolean_surface_parameter_curve(*boundary));
	if (!parameter_curve) {
	    continue;
	}
	std::vector<ON_Interval> boundary_intervals;
	if (append_parameter_isocurve_intervals(*parameter_curve,
		constant_direction, boundary_coordinate, varying_direction,
		tolerance, boundary_intervals))
	{
	    covered.insert(covered.end(), boundary_intervals.begin(),
		boundary_intervals.end());
	}
    }
    if (covered.empty()) {
	return false;
    }

    std::sort(covered.begin(), covered.end(),
	[](const ON_Interval &first, const ON_Interval &second) {
	    return first.Min() < second.Min();
	});
    for (const ON_Interval &target : targets) {
	double covered_through = target.Min();
	for (const ON_Interval &interval : covered) {
	    if (interval.Max() < covered_through - tolerance) {
		continue;
	    }
	    if (interval.Min() > covered_through + tolerance) {
		break;
	    }
	    covered_through = std::max(covered_through, interval.Max());
	    if (covered_through + tolerance >= target.Max()) {
		break;
	    }
	}
	if (covered_through + tolerance < target.Max()) {
	    return false;
	}
    }
    return true;
}


static bool
parameter_curve_is_covered_by_boundary_curves(
    const ON_Curve &curve,
    const std::vector<const ON_Curve *> &boundary_curves,
    const ON_Surface &surface);


static bool
certified_boundary_curve_covers_ssi_interval(
    const ON_Curve &ssi_curve,
    const ON_Interval &ssi_interval,
    const ON_Curve &boundary_curve,
    const ON_Surface &surface,
    double parameter_space_tolerance,
    bool allow_complete_boundary_locus = false);


static ON_SimpleArray<ON_Interval>
get_curve_intervals_inside_or_on_face(
    ON_Curve *curve2D,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &face_loops,
    const ON_Surface *surface,
    double isect_tol)
{
    /* Certify boundary coincidence before asking the curve intersection and
     * point-in-loop paths to classify it.  In particular, a closed SSI can be
     * the same locus as a boundary loop assembled from several open arcs.
     * Intersecting those nearly identical representations can manufacture
     * many alternating inside/outside fragments. */
    if (curve2D != NULL && curve2D->IsClosed() && surface != NULL) {
	std::vector<const ON_Curve *> boundary_curves;
	for (int loop_index = 0; loop_index < face_loops.Count(); ++loop_index) {
	    for (int curve_index = 0;
		 curve_index < face_loops[loop_index].Count(); ++curve_index)
	    {
		if (face_loops[loop_index][curve_index] != NULL) {
		    boundary_curves.push_back(
			face_loops[loop_index][curve_index]);
		}
	    }
	}
	if (parameter_curve_is_covered_by_boundary_curves(*curve2D,
		boundary_curves, *surface))
	{
	    ON_SimpleArray<ON_Interval> complete;
	    complete.Append(curve2D->Domain());
	    if (DEBUG_BREP_BOOLEAN > 1) {
		bu_log("Boolean SSI parameter curve is certified on the complete "
		    "face boundary.\n");
	    }
	    return complete;
        }
    }

    // get curve-loop intersections
    ON_SimpleArray<double> isect_curve_t;
    ON_SimpleArray<ON_X_EVENT> ccx_events;
    std::vector<const ON_Curve *> fragmented_boundary_curves;

    for (int i = 0; i < face_loops.Count(); ++i) {
	for (int j = 0; j < face_loops[i].Count(); ++j) {
	    const int event_start = ccx_events.Count();
	    intersect_boolean_curves(curve2D, face_loops[i][j], ccx_events,
		isect_tol);
	    if (DEBUG_BREP_BOOLEAN && curve2D != NULL && curve2D->IsClosed()) {
		const int added_events = ccx_events.Count() - event_start;
		if (added_events > 16 && face_loops[i][j] != NULL) {
		    fragmented_boundary_curves.push_back(face_loops[i][j]);
		}
		bu_log("Boolean closed SSI boundary intersection loop %d curve %d "
		    "added %d events.\n", i, j, added_events);
		if (added_events > 16) {
		    int point_events = 0;
		    int overlap_events = 0;
		    ON_Interval first_event_range(ON_DBL_MAX, -ON_DBL_MAX);
		    ON_Interval second_event_range(ON_DBL_MAX, -ON_DBL_MAX);
		    for (int event_index = event_start;
			 event_index < ccx_events.Count(); ++event_index)
		    {
			const ON_X_EVENT &event = ccx_events[event_index];
			point_events += event.m_type ==
			    ON_X_EVENT::ccx_point;
			overlap_events += event.m_type ==
			    ON_X_EVENT::ccx_overlap;
			const int endpoint_count = event.m_type ==
			    ON_X_EVENT::ccx_overlap ? 2 : 1;
			for (int endpoint = 0; endpoint < endpoint_count; ++endpoint) {
			    first_event_range.m_t[0] = std::min(
				first_event_range.m_t[0], event.m_a[endpoint]);
			    first_event_range.m_t[1] = std::max(
				first_event_range.m_t[1], event.m_a[endpoint]);
			    second_event_range.m_t[0] = std::min(
				second_event_range.m_t[0], event.m_b[endpoint]);
			    second_event_range.m_t[1] = std::max(
				second_event_range.m_t[1], event.m_b[endpoint]);
			}
		    }
		    ON_NurbsCurve boundary_nurbs;
		    const int nurbs_form = face_loops[i][j] ?
			face_loops[i][j]->GetNurbForm(boundary_nurbs) : 0;
		    bu_log("  excessive boundary events: points %d overlaps %d; "
			"boundary class %s NURBS form/order/CVs %d/%d/%d.\n",
			point_events, overlap_events,
			face_loops[i][j] && face_loops[i][j]->ClassId() ?
			    face_loops[i][j]->ClassId()->ClassName() : "unknown",
			nurbs_form, nurbs_form > 0 ? boundary_nurbs.Order() : 0,
			nurbs_form > 0 ? boundary_nurbs.CVCount() : 0);
		    bu_log("  SSI event range %.17g -> %.17g of %.17g -> %.17g; "
			"boundary range %.17g -> %.17g of %.17g -> %.17g.\n",
			first_event_range.Min(), first_event_range.Max(),
			curve2D->Domain().Min(), curve2D->Domain().Max(),
			second_event_range.Min(), second_event_range.Max(),
			face_loops[i][j]->Domain().Min(),
			face_loops[i][j]->Domain().Max());
		    for (int event_index = event_start;
			 event_index < std::min(ccx_events.Count(), event_start + 8);
			 ++event_index)
		    {
			const ON_X_EVENT &event = ccx_events[event_index];
			bu_log("    event %d type %d A %.17g -> %.17g, "
			    "B %.17g -> %.17g.\n", event_index - event_start,
			    event.m_type, event.m_a[0], event.m_a[1],
			    event.m_b[0], event.m_b[1]);
		    }
		}
	    }
	}
    }

    // get a sorted list of just the parameters on the first curve
    // where it intersects the outerloop
    for (int i = 0; i < ccx_events.Count(); i++) {
	isect_curve_t.Append(ccx_events[i].m_a[0]);

	if (ccx_events[i].m_type == ON_X_EVENT::ccx_overlap) {
	    isect_curve_t.Append(ccx_events[i].m_a[1]);
	}
    }
    isect_curve_t.QuickSort(ON_CompareIncreasing);


    // insert start and end parameters so every part of the curve is tested
    isect_curve_t.Insert(0, curve2D->Domain().Min());
    isect_curve_t.Append(curve2D->Domain().Max());

    // if the midpoint of an interval is inside/on the face, keep the
    // entire interval
    ON_SimpleArray<ON_Interval> included_intervals;
    for (int i = 0; i < isect_curve_t.Count() - 1; i++) {
	ON_Interval interval(isect_curve_t[i], isect_curve_t[i + 1]);
	if (ON_NearZero(interval.Length(), isect_tol)) {
	    continue;
	}
	ON_2dPoint pt = curve2D->PointAt(interval.Mid());

	bool point_included = false;
	try {
	    // inside/on outerloop
	    if (!is_point_outside_loop(pt, face_loops[0], isect_tol)) {

		// outside/on innerloops
		point_included = true;
		for (int j = 1; j < face_loops.Count(); ++j) {
		    if (is_point_inside_loop(pt, face_loops[j], isect_tol)) {
			point_included = false;
			break;
		    }
		}
	    }
	} catch (InvalidGeometry &e) {
	    bu_log("%s", e.what());
	}
	if (point_included) {
	    included_intervals.Append(interval);
	}
    }

    /* A solver may represent one coincident conic arc as hundreds of point
     * events with alternating, artificial gaps.  The outer extent of the
     * included intervals is bounded by the face's transverse boundaries.  It
     * is safe to replace those fragments only when an individual trim curve
     * is certified equivalent to that complete SSI interval. */
    if (curve2D != NULL && curve2D->IsClosed() && surface != NULL &&
	included_intervals.Count() > 1 && !fragmented_boundary_curves.empty())
    {
	ON_Interval candidate(included_intervals[0].Min(),
	    included_intervals[included_intervals.Count() - 1].Max());
	for (size_t curve_index = 0;
	     curve_index < fragmented_boundary_curves.size(); ++curve_index)
	{
	    if (certified_boundary_curve_covers_ssi_interval(*curve2D,
		    candidate, *fragmented_boundary_curves[curve_index],
		    *surface, isect_tol, true))
	    {
		included_intervals.Empty();
		included_intervals.Append(candidate);
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean certified a fragmented closed SSI boundary "
			"interval %.17g -> %.17g.\n", candidate.Min(),
			candidate.Max());
		}
		break;
	    }
	}
    }

    // merge continuous intervals
    ON_SimpleArray<ON_Interval> final_intervals;
    for (int j, i = 0; i < included_intervals.Count(); i = j) {
	ON_Interval merged_interval = included_intervals[i];

	for (j = i + 1; j < included_intervals.Count(); ++j) {
	    ON_Interval &next = included_intervals[j];

	    if (ON_NearZero(next.Min() - merged_interval.Max(), isect_tol)) {
		ON_Interval new_interval = merged_interval;

		if (new_interval.Union(next)) {
		    merged_interval = new_interval;
		} else {
		    break;
		}
	    } else {
		break;
	    }
	}
	final_intervals.Append(merged_interval);
    }

    return final_intervals;
}


static bool
curve_intervals_cover_domain(
    const ON_SimpleArray<ON_Interval> &intervals,
    ON_Interval domain,
    double parameter_tolerance = 0.0)
{
    domain.MakeIncreasing();
    if (!domain.IsIncreasing() || !(parameter_tolerance >= 0.0) ||
	!std::isfinite(parameter_tolerance))
    {
	return false;
    }

    const double scale = std::max(1.0, fabs(domain.Length()));
    const double tolerance = std::max(ON_ZERO_TOLERANCE * scale,
	parameter_tolerance);
    std::vector<ON_Interval> normalized_intervals;
    normalized_intervals.reserve(intervals.Count());
    for (int interval_index = 0; interval_index < intervals.Count();
	 ++interval_index)
    {
	ON_Interval interval = intervals[interval_index];
	interval.MakeIncreasing();
	if (!interval.IsIncreasing() || interval.Min() < domain.Min() - tolerance ||
	    interval.Max() > domain.Max() + tolerance)
	{
	    return false;
	}
	if (interval.Length() > tolerance) {
	    normalized_intervals.push_back(interval);
	}
    }

    std::sort(normalized_intervals.begin(), normalized_intervals.end(),
	[](const ON_Interval &first, const ON_Interval &second) {
	    return first.Min() < second.Min();
	});

    double covered_maximum = domain.Min();
    for (size_t interval_index = 0;
	 interval_index < normalized_intervals.size(); ++interval_index)
    {
	const ON_Interval &interval = normalized_intervals[interval_index];
	if (interval.Min() > covered_maximum + tolerance) {
	    return false;
	}
	covered_maximum = std::max(covered_maximum, interval.Max());
    }

    return covered_maximum >= domain.Max() - tolerance;
}


struct IntervalPoints {
    ON_3dPoint min;
    ON_3dPoint mid;
    ON_3dPoint max;
};


class IntervalParams {
public:
    double min;
    double mid;
    double max;

    void
    MakeIncreasing(void)
    {
	if (min > mid) {
	    std::swap(min, mid);
	}
	if (mid > max) {
	    std::swap(mid, max);

	    if (min > mid) {
		std::swap(min, mid);
	    }
	}
    }
};


// given parameters in a curve interval, create new interval
// parameters that reflect the the non-degenerate (different
// dimensioned) curve interval used to generate the curve parameters
static IntervalParams
curve_interval_from_params(
    IntervalParams interval_t,
    const ON_Curve *curve)
{
    if (!curve->IsClosed()) {
	return interval_t;
    }

    if (interval_t.min > interval_t.max) {
	std::swap(interval_t.min, interval_t.max);
    }
    double min_t = interval_t.min;
    double max_t = interval_t.max;

    ON_Interval cdom = curve->Domain();
    if (!(min_t < max_t || min_t > max_t)) {
	// if endpoints are both at closed curve joint, put them at
	// either end of the curve domain
	if (ON_NearZero(cdom.Min() - min_t, ON_ZERO_TOLERANCE)) {
	    interval_t.max = cdom.Max();
	} else if (ON_NearZero(cdom.Max() - min_t, ON_ZERO_TOLERANCE)) {
	    interval_t.min = cdom.Min();
	}
    } else {
	// if interval doesn't include midpt, assume the point nearest
	// the seam needs to be on the opposite side of the domain
	ON_Interval curr(min_t, max_t);
	if (!curr.Includes(interval_t.mid)) {
	    if (fabs(cdom.Min() - min_t) > fabs(cdom.Max() - max_t)) {
		interval_t.max = cdom.Min();
	    } else {
		interval_t.min = cdom.Max();
	    }
	}
    }
    interval_t.MakeIncreasing();

    return interval_t;
}


enum seam_location {SEAM_NONE, SEAM_ALONG_V, SEAM_ALONG_U, SEAM_ALONG_UV};


// given interval points in surface uv space, create new interval
// points that reflect the non-degenerate curve parameter interval
// used to generate the input points
static IntervalPoints
uv_interval_from_points(
    IntervalPoints interval_pts,
    const ON_Surface *surf)
{
    ON_3dPoint &min_uv = interval_pts.min;
    ON_3dPoint &max_uv = interval_pts.max;

    ON_Interval udom = surf->Domain(0);
    ON_Interval vdom = surf->Domain(1);

    int seam_min = IsAtSeam(surf, min_uv, ON_ZERO_TOLERANCE);
    int seam_max = IsAtSeam(surf, max_uv, ON_ZERO_TOLERANCE);

    if ((seam_min && seam_max) && (min_uv == max_uv)) {
	// if uv endpoints are identical and on a seam
	// they need to be on opposite sides of the domain
	if (ON_NearZero(udom.Min() - min_uv[0], ON_ZERO_TOLERANCE) ||
	    ON_NearZero(udom.Max() - min_uv[0], ON_ZERO_TOLERANCE))
	{
	    // point on west/east edge becomes one point on west
	    // edge, one point on east edge
	    min_uv[0] = udom.Min();
	    max_uv[0] = udom.Max();
	} else if (ON_NearZero(vdom.Min() - min_uv[1], ON_ZERO_TOLERANCE) ||
		   ON_NearZero(vdom.Max() - min_uv[1], ON_ZERO_TOLERANCE))
	{
	    // point on south/north edge becomes one point on
	    // south edge, one point on north edge
	    min_uv[1] = vdom.Min();
	    max_uv[1] = vdom.Max();
	}
    } else if (!seam_min != !seam_max) { // XOR
	// if just one point is on a seam, make sure it's on the
	// correct side of the domain

	// get interval midpoint in uv space
	ON_ClassArray<ON_PX_EVENT> events;
	ON_3dPoint midpt = surf->PointAt(interval_pts.mid.x,
					 interval_pts.mid.y);
	ON_Intersect(midpt, *surf, events, INTERSECTION_TOL);

	if (events.Count() == 1) {
	    // Check that the non-seam parameter of the
	    // midpoint is between the non-seam parameters of
	    // the interval uv on the seam and the other
	    // interval uv. If the midpoint non-seam parameter
	    // is outside the interval we'll move the seam_uv
	    // to the other side of the domain.
	    //
	    // For example, if the surface has a seam at the
	    // west/east edge and we have seam_uv (0.0, .1)
	    // and other_uv (.5, .6) we'll check that the
	    // interval midpoint uv has a u in [0.0, .5].
	    //
	    // A midpoint of (.25, .25) would be okay. A
	    // midpoint of (.75, .25) would necessitate us
	    // moving the seam_uv from the west edge to the
	    // east edge, e.g (1.0, .1).
	    int seam = seam_min ? seam_min : seam_max;
	    ON_3dPoint &seam_uv = seam_min ? min_uv : max_uv;
	    ON_3dPoint other_uv = seam_min ? max_uv : min_uv;

	    double *seam_t = &seam_uv[1];
	    double seam_opp_t = vdom.Max() - seam_uv[1];
	    double other_t = other_uv[1];
	    double midpt_t = events[0].m_b[1];
	    if (seam != SEAM_ALONG_U) {
		seam_t = &seam_uv[0];
		seam_opp_t = udom.Max() - seam_uv[0];
		other_t = other_uv[0];
		midpt_t = events[0].m_b[0];
	    }

	    ON_Interval curr(*seam_t, other_t);
	    if (!curr.Includes(midpt_t)) {
		// need to flip the seam point to the other
		// side of the domain
		*seam_t = seam_opp_t;
	    }
	}
    }
    return interval_pts;
}


static IntervalPoints
interval_2d_to_uv(
    const ON_Interval &interval_2d,
    const ON_Curve *curve2d,
    const ON_Surface *surf)
{
    // initialize endpoints from evaluated surface uv points
    IntervalPoints pts;
    pts.min = curve2d->PointAt(interval_2d.Min());
    pts.mid = curve2d->PointAt(interval_2d.Mid());
    pts.max = curve2d->PointAt(interval_2d.Max());

    return uv_interval_from_points(pts, surf);
}


static std::pair<IntervalPoints, IntervalPoints>
interval_2d_to_2uv(
    const ON_Interval &interval_2d,
    const ON_Curve *curve2d,
    const ON_Surface *surf,
    double split_t)
{
    std::pair<IntervalPoints, IntervalPoints> out;

    ON_Interval left(interval_2d.Min(), split_t);
    ON_Interval right(split_t, interval_2d.Max());

    out.first = interval_2d_to_uv(left, curve2d, surf);
    out.second = interval_2d_to_uv(right, curve2d, surf);

    return out;
}


static IntervalPoints
points_uv_to_3d(
    const IntervalPoints &interval_uv,
    const ON_Surface *surf)
{
    // evaluate surface at uv points to get 3d interval points
    IntervalPoints pts_3d;
    pts_3d.min = surf->PointAt(interval_uv.min.x, interval_uv.min.y);
    pts_3d.mid = surf->PointAt(interval_uv.mid.x, interval_uv.mid.y);
    pts_3d.max = surf->PointAt(interval_uv.max.x, interval_uv.max.y);

    return pts_3d;
}


static bool
curve_parameter_matches_point_with_tolerance(
    const ON_Curve *curve,
    double curve_parameter,
    const ON_3dPoint &point,
    double point_tolerance)
{
    if (curve == NULL || !point.IsValid() ||
	!std::isfinite(curve_parameter) || !(point_tolerance > 0.0) ||
	!std::isfinite(point_tolerance))
    {
	return false;
    }

    const ON_Interval curve_domain = curve->Domain();
    if (!curve_domain.IsValid() || !curve_domain.Includes(curve_parameter)) {
	return false;
    }

    const ON_3dPoint curve_point = curve->PointAt(curve_parameter);
    return curve_point.IsValid() &&
	curve_point.DistanceTo(point) <= point_tolerance;
}


static bool
curve_parameter_matches_point(
    const ON_Curve *curve,
    double curve_parameter,
    const ON_3dPoint &point)
{
    return curve_parameter_matches_point_with_tolerance(curve,
	curve_parameter, point, INTERSECTION_TOL);
}


static bool
point_3d_to_curve_parameter_with_tolerance(
    const ON_3dPoint &point,
    const ON_Curve *curve,
    double point_tolerance,
    double &curve_parameter,
    bool report_failure)
{
    if (!point.IsValid() || curve == NULL || !(point_tolerance > 0.0) ||
	!std::isfinite(point_tolerance))
    {
	return false;
    }

    ON_ClassArray<ON_PX_EVENT> events;
    ON_Intersect(point, *curve, events, point_tolerance);
    if (events.Count() == 1 &&
	curve_parameter_matches_point_with_tolerance(curve,
	events[0].m_b[0], point, point_tolerance))
    {
	curve_parameter = events[0].m_b[0];
	return true;
    }
    if (events.Count() > 1) {
	/* A point at the seam of a closed curve may be reported once at each
	 * end of the parameter domain.  Those parameters identify the same
	 * geometric point and are not an ambiguous self-intersection.  Accept
	 * only that narrowly certified case; curve_interval_from_params() uses
	 * the interval midpoint to select the appropriate side of the seam. */
	ON_Interval domain = curve->Domain();
	domain.MakeIncreasing();
	const double parameter_scale = domain.IsIncreasing() ? std::max(1.0,
	    std::max(fabs(domain.Min()), fabs(domain.Max()))) : 1.0;
	const double parameter_tolerance = ON_ZERO_TOLERANCE * parameter_scale;
	bool seam_only = curve->IsClosed() && domain.IsIncreasing();
	for (int event_index = 0; seam_only && event_index < events.Count();
	     ++event_index)
	{
	    const double parameter = events[event_index].m_b[0];
	    seam_only = curve_parameter_matches_point_with_tolerance(curve,
		parameter, point, point_tolerance) &&
		(fabs(parameter - domain.Min()) <= parameter_tolerance ||
		 fabs(parameter - domain.Max()) <= parameter_tolerance);
	}
	if (seam_only) {
	    curve_parameter = domain.Min();
	    return true;
	}
	return false;
    }

    ON_NurbsCurve curve_nurbs;
    const int nurbs_form = curve->GetNurbForm(curve_nurbs);
    const int parameterized_nurbs_form = 1;
    const int reparameterized_nurbs_form = 2;
    if ((nurbs_form != parameterized_nurbs_form &&
	nurbs_form != reparameterized_nurbs_form) ||
	!curve_nurbs.Domain().IsValid())
    {
	return false;
    }

    double nurbs_parameter = curve_nurbs.Domain().Min();
    if (!ON_NurbsCurve_GetClosestPoint(&nurbs_parameter, &curve_nurbs,
	point, point_tolerance))
    {
	if (DEBUG_BREP_BOOLEAN && report_failure) {
	    double diagnostic_parameter = curve_nurbs.Domain().Min();
	    const bool diagnostic_found = ON_NurbsCurve_GetClosestPoint(
		&diagnostic_parameter, &curve_nurbs, point);
	    const ON_3dPoint diagnostic_point = diagnostic_found ?
		curve_nurbs.PointAt(diagnostic_parameter) : ON_3dPoint::UnsetPoint;
	    bu_log("Boolean curve parameter lookup exceeded tolerance %.17g: "
		"nearest %d at %.17g with distance %.17g.\n", point_tolerance,
		diagnostic_found, diagnostic_parameter,
		diagnostic_found && diagnostic_point.IsValid() ?
		    diagnostic_point.DistanceTo(point) : -1.0);
	}
	return false;
    }

    curve_parameter = nurbs_parameter;
    if (nurbs_form == reparameterized_nurbs_form &&
	!curve->GetCurveParameterFromNurbFormParameter(nurbs_parameter,
	&curve_parameter))
    {
	return false;
    }

    return curve_parameter_matches_point_with_tolerance(curve,
	curve_parameter, point, point_tolerance);
}


static bool
point_3d_to_curve_parameter(
    const ON_3dPoint &point,
    const ON_Curve *curve,
    double &curve_parameter)
{
    return point_3d_to_curve_parameter_with_tolerance(point, curve,
	INTERSECTION_TOL, curve_parameter);
}


static bool
get_face_boundary_curve_tolerances(
    const ON_Surface *surface,
    const ON_Curve *curve,
    double &intersection_tolerance,
    double &curve_parameter_tolerance);


static ON_Curve *
pushup_boolean_curve(const ON_Surface *surface, const ON_Curve &curve);

static ON_Curve *
pushup_boolean_trim_curve(const ON_Surface *surface, const ON_Curve &curve);

static ON_Curve *
pushup_affine_boolean_curve(const ON_Surface *surface, const ON_Curve &curve);

static bool
measure_curve_to_nurbs_distance(const ON_Curve *curve,
    const ON_NurbsCurve *nurbs, double &maximum_distance);

static double
boolean_model_repair_tolerance(const ON_BoundingBox &model_bounds);


static bool
is_point_inside_trimmed_face(const ON_2dPoint &pt, const TrimmedFace *tface);


static bool
intersection_point_matches_boundary_endpoint(
    const IntersectPoint &intersection_point,
    const BooleanBoundaryEndpointHit &endpoint,
    double intersection_tolerance,
    double curve_parameter_tolerance)
{
    return intersection_point.m_loop_seg == endpoint.m_boundary_curve_index &&
	std::fabs(intersection_point.m_seg_t - endpoint.m_boundary_parameter) <=
	intersection_tolerance &&
	std::fabs(intersection_point.m_curve_t - endpoint.m_curve_parameter) <=
	curve_parameter_tolerance &&
	intersection_point.m_pt.DistanceTo(endpoint.m_point) <=
	intersection_tolerance;
}


static bool
open_curve_endpoints_span_closed_surface_seam(
    const ON_Surface *surface,
    const ON_Curve *curve,
    double parameter_tolerance)
{
    if (surface == NULL || curve == NULL || !(parameter_tolerance > 0.0) ||
	!std::isfinite(parameter_tolerance))
    {
	return false;
    }

    const ON_3dPoint start = curve->PointAtStart();
    const ON_3dPoint end = curve->PointAtEnd();
    if (!start.IsValid() || !end.IsValid()) {
	return false;
    }

    for (int direction = 0; direction < 2; ++direction) {
	if (!surface->IsClosed(direction)) {
	    continue;
	}
	ON_Interval domain = surface->Domain(direction);
	domain.MakeIncreasing();
	if (!domain.IsIncreasing()) {
	    continue;
	}
	const double start_parameter = direction == 0 ? start.x : start.y;
	const double end_parameter = direction == 0 ? end.x : end.y;
	const bool opposite_seams =
	    (fabs(start_parameter - domain.Min()) <= parameter_tolerance &&
	     fabs(end_parameter - domain.Max()) <= parameter_tolerance) ||
	    (fabs(start_parameter - domain.Max()) <= parameter_tolerance &&
	     fabs(end_parameter - domain.Min()) <= parameter_tolerance);
	if (opposite_seams) {
	    return true;
	}
    }

    return false;
}


/* A full-domain parameter curve on a doubly periodic surface can be damaged by
 * extracting a nominal subcurve even when no clipping occurred.  Restrict the
 * preservation exception to curves that materially traverse a periodic
 * direction; local intersections continue through the ordinary repair path. */
static bool
open_curve_traverses_periodic_surface_domain(
    const ON_Surface *surface,
    const ON_Curve *curve)
{
    if (surface == NULL || curve == NULL) {
	return false;
    }
    if ((!surface->IsClosed(0) && !surface->IsPeriodic(0)) ||
	(!surface->IsClosed(1) && !surface->IsPeriodic(1)))
    {
	return false;
    }

    static const double minimum_domain_fraction = 0.125;
    const ON_BoundingBox bounds = curve->BoundingBox();
    if (!bounds.IsValid()) {
	return false;
    }
    for (int direction = 0; direction < 2; ++direction) {
	if (!surface->IsClosed(direction) && !surface->IsPeriodic(direction)) {
	    continue;
	}
	ON_Interval domain = surface->Domain(direction);
	domain.MakeIncreasing();
	const double curve_span = direction == 0 ?
	    bounds.m_max.x - bounds.m_min.x : bounds.m_max.y - bounds.m_min.y;
	if (domain.IsIncreasing() && std::isfinite(curve_span) &&
	    curve_span >= minimum_domain_fraction * domain.Length())
	{
	    return true;
	}
    }
    return false;
}


static bool
append_certified_open_curve_endpoint_hits(
    const TrimmedFace *orig_face,
    const ON_Curve *linked_curve,
    ON_SimpleArray<IntersectPoint> &intersection_points,
    bool allow_paired_seam = false)
{
    if (orig_face == NULL || orig_face->m_face == NULL ||
	linked_curve == NULL)
    {
	return false;
    }

    double intersection_tolerance = 0.0;
    double curve_parameter_tolerance = 0.0;
    if (!get_face_boundary_curve_tolerances(orig_face->m_face->SurfaceOf(),
	linked_curve, intersection_tolerance, curve_parameter_tolerance))
    {
	return false;
    }

    ON_Interval curve_domain = linked_curve->Domain();
    curve_domain.MakeIncreasing();
    if (!curve_domain.IsIncreasing()) {
	return false;
    }

    ON_SimpleArray<double> existing_parameters;
    for (int point_index = 0; point_index < intersection_points.Count();
	 ++point_index)
    {
	existing_parameters.Append(intersection_points[point_index].m_curve_t);
    }
    if (!boolean_curve_hits_are_endpoint_only(existing_parameters,
	curve_domain, curve_parameter_tolerance))
    {
	return false;
    }

    BooleanBoundaryEndpointHit endpoints[2];
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean endpoint certificate: intersection tolerance %.17g, "
	    "curve parameter tolerance %.17g, domain %.17g -> %.17g.\n",
	    intersection_tolerance, curve_parameter_tolerance,
	    curve_domain.Min(), curve_domain.Max());
	for (int endpoint_index = 0; endpoint_index < 2; ++endpoint_index) {
	    const double curve_parameter = endpoint_index == 0 ?
		curve_domain.Min() : curve_domain.Max();
	    const ON_3dPoint endpoint_point = linked_curve->PointAt(
		curve_parameter);
	    bu_log("  endpoint %d parameter %.17g point (%.17g, %.17g).\n",
		endpoint_index, curve_parameter, endpoint_point.x,
		endpoint_point.y);
	    for (int boundary_index = 0;
		 boundary_index < orig_face->m_outerloop.Count();
		 ++boundary_index)
	    {
		const ON_Curve *boundary = orig_face->m_outerloop[boundary_index];
		ON_ClassArray<ON_PX_EVENT> events;
		const bool intersected = boundary && ON_Intersect(endpoint_point,
		    *boundary, events, intersection_tolerance);
		bu_log("    boundary %d intersected %d events %d.\n",
		    boundary_index, intersected, events.Count());
		for (int event_index = 0; event_index < events.Count();
		     ++event_index)
		{
		    const ON_PX_EVENT &event = events[event_index];
		    const ON_3dVector curve_tangent = linked_curve->TangentAt(
			curve_parameter);
		    const ON_3dVector boundary_tangent = boundary->TangentAt(
			event.m_b[0]);
		    bu_log("      event %d type %d parameter %.17g, "
			"A distance %.17g, B distance %.17g, endpoint "
			"distances %.17g/%.17g, parallel %d.\n",
			event_index, event.m_type, event.m_b[0],
			event.m_A.DistanceTo(endpoint_point),
			event.m_B.DistanceTo(endpoint_point),
			event.m_B.DistanceTo(boundary->PointAtStart()),
			event.m_B.DistanceTo(boundary->PointAtEnd()),
			curve_tangent.IsParallelTo(boundary_tangent, ANGLE_TOL));
		}
	    }
	}
    }
    bool relaxed_endpoint_pair = false;
    if (!boolean_find_certified_open_curve_endpoint_pair(linked_curve,
	orig_face->m_outerloop, intersection_tolerance, endpoints))
    {
	const ON_Surface *surface = orig_face->m_face->SurfaceOf();
	const bool opposite_seam_pair =
	    open_curve_endpoints_span_closed_surface_seam(surface, linked_curve,
		intersection_tolerance);
	/* A simple arc connecting two distinct boundary curves partitions a face
	 * even when it approaches one boundary tangentially.  Exact endpoint
	 * incidence plus the dense interior check below distinguishes that case
	 * from a merely nearby or boundary-following curve.  Same-boundary
	 * tangencies remain restricted to explicitly certified seam pairs. */
	relaxed_endpoint_pair =
	    boolean_find_certified_open_curve_endpoint_pair(linked_curve,
		orig_face->m_outerloop, intersection_tolerance, endpoints, true,
		false);
	if (!relaxed_endpoint_pair &&
	    (opposite_seam_pair || allow_paired_seam))
	{
	    relaxed_endpoint_pair =
		boolean_find_certified_open_curve_endpoint_pair(linked_curve,
		    orig_face->m_outerloop, intersection_tolerance, endpoints,
		    true, allow_paired_seam);
	}
	if (!relaxed_endpoint_pair) {
	    return false;
	}
    }

    try {
	const int sample_count = relaxed_endpoint_pair ? 16 : 2;
	for (int sample = 1; sample < sample_count; ++sample) {
	    const ON_3dPoint point = linked_curve->PointAt(
		curve_domain.ParameterAt(static_cast<double>(sample) /
		    sample_count));
	    bool inside = false;
	    if (point.IsValid()) {
		inside = is_point_inside_loop(ON_2dPoint(point),
		    orig_face->m_outerloop, intersection_tolerance);
	    }
	    if (!point.IsValid() || !inside)
	    {
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean endpoint pair sample %d/%d at "
			"(%.17g, %.17g) is not inside.\n", sample,
			sample_count, point.x, point.y);
		}
		return false;
	    }
	}
    } catch (InvalidGeometry &) {
	return false;
    }

    bool appended_endpoint = false;
    for (int endpoint_index = 0; endpoint_index < 2; ++endpoint_index) {
	bool already_present = false;
	for (int point_index = 0; point_index < intersection_points.Count();
	     ++point_index)
	{
	    if (intersection_point_matches_boundary_endpoint(
		intersection_points[point_index], endpoints[endpoint_index],
		intersection_tolerance, curve_parameter_tolerance))
	    {
		already_present = true;
		break;
	    }
	}
	if (already_present) {
	    continue;
	}

	IntersectPoint endpoint;
	endpoint.m_pt = endpoints[endpoint_index].m_point;
	endpoint.m_seg_t = endpoints[endpoint_index].m_boundary_parameter;
	endpoint.m_curve_t = endpoints[endpoint_index].m_curve_parameter;
	endpoint.m_loop_seg = endpoints[endpoint_index].m_boundary_curve_index;
	intersection_points.Append(endpoint);
	appended_endpoint = true;
    }

    return appended_endpoint;
}


static IntervalParams
points_3d_to_params_3d(
    const IntervalPoints &pts_3d,
    const ON_Curve *curve3d)
{
    IntervalParams params_3d;
    const ON_BoundingBox model_bounds = curve3d ? curve3d->BoundingBox() :
	ON_BoundingBox::EmptyBoundingBox;
    const double mapping_tolerance = boolean_model_repair_tolerance(
	model_bounds);
    const bool minimum_mapped = point_3d_to_curve_parameter_with_tolerance(
	pts_3d.min, curve3d, mapping_tolerance, params_3d.min);
    const bool midpoint_mapped = point_3d_to_curve_parameter_with_tolerance(
	pts_3d.mid, curve3d, mapping_tolerance, params_3d.mid);
    const bool maximum_mapped = point_3d_to_curve_parameter_with_tolerance(
	pts_3d.max, curve3d, mapping_tolerance, params_3d.max);
    if (!minimum_mapped || !midpoint_mapped || !maximum_mapped)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean SSI point mapping failed at minimum/midpoint/maximum "
		"%d/%d/%d for points (%.17g %.17g %.17g), "
		"(%.17g %.17g %.17g), (%.17g %.17g %.17g).\n",
		minimum_mapped, midpoint_mapped, maximum_mapped,
		pts_3d.min.x, pts_3d.min.y, pts_3d.min.z,
		pts_3d.mid.x, pts_3d.mid.y, pts_3d.mid.z,
		pts_3d.max.x, pts_3d.max.y, pts_3d.max.z);
	}
	throw AlgorithmError("points_3d_to_params_3d: conversion failed\n");
    }

    return params_3d;
}


struct SSIPolylineCorrespondence {
    ON_Interval parameter_domain;
    ON_Interval spatial_domain;
    ON_Interval spatial_full_domain;
    bool has_terminal_spatial_closure;
};


static bool
certify_ssi_polyline_correspondence(
    const ON_Curve *curve2d,
    const ON_Curve *curve3d,
    const ON_Surface *surface,
    SSIPolylineCorrespondence &correspondence)
{
    const ON_PolylineCurve *parameter_polyline =
	ON_PolylineCurve::Cast(curve2d);
    const ON_PolylineCurve *spatial_polyline =
	ON_PolylineCurve::Cast(curve3d);
    if (parameter_polyline == NULL || spatial_polyline == NULL ||
	surface == NULL || parameter_polyline->Dimension() != 2 ||
	spatial_polyline->Dimension() != 3)
    {
	return false;
    }

    const int parameter_point_count = parameter_polyline->PointCount();
    const int spatial_point_count = spatial_polyline->PointCount();
    const bool has_terminal_spatial_closure = spatial_point_count ==
	parameter_point_count + 1;
    if (parameter_point_count < 2 ||
	(spatial_point_count != parameter_point_count &&
	 !has_terminal_spatial_closure) ||
	parameter_polyline->m_pline.Count() != parameter_point_count ||
	spatial_polyline->m_pline.Count() != spatial_point_count ||
	parameter_polyline->m_t.Count() != parameter_point_count ||
	spatial_polyline->m_t.Count() != spatial_point_count)
    {
	return false;
    }

    const double parameter_start = parameter_polyline->m_t[0];
    const double parameter_end =
	parameter_polyline->m_t[parameter_point_count - 1];
    const double spatial_start = spatial_polyline->m_t[0];
    const double spatial_end = spatial_polyline->m_t[parameter_point_count - 1];
    const double parameter_span = parameter_end - parameter_start;
    const double spatial_span = spatial_end - spatial_start;
    if (!(parameter_span > 0.0) || !(spatial_span > 0.0) ||
	!std::isfinite(parameter_span) || !std::isfinite(spatial_span))
    {
	return false;
    }

    double previous_parameter = parameter_start;
    double previous_spatial = spatial_start;
    for (int point_index = 0; point_index < parameter_point_count;
	 ++point_index)
    {
	const double parameter = parameter_polyline->m_t[point_index];
	const double spatial = spatial_polyline->m_t[point_index];
	if (!std::isfinite(parameter) || !std::isfinite(spatial) ||
	    (point_index > 0 && (parameter <= previous_parameter ||
		spatial <= previous_spatial)))
	{
	    return false;
	}

	const double parameter_fraction =
	    (parameter - parameter_start) / parameter_span;
	const double spatial_fraction =
	    (spatial - spatial_start) / spatial_span;
	if (!std::isfinite(parameter_fraction) || !std::isfinite(spatial_fraction) ||
	    !ON_NearZero(parameter_fraction - spatial_fraction,
		ON_ZERO_TOLERANCE))
	{
	    return false;
	}

	const ON_3dPoint &parameter_point =
	    parameter_polyline->m_pline[point_index];
	const ON_3dPoint &spatial_point = spatial_polyline->m_pline[point_index];
	if (!parameter_point.IsValid() || !spatial_point.IsValid()) {
	    return false;
	}
	const ON_3dPoint lifted_point = surface->PointAt(parameter_point.x,
	    parameter_point.y);
	if (!lifted_point.IsValid() ||
	    lifted_point.DistanceTo(spatial_point) > INTERSECTION_TOL)
	{
	    return false;
	}

	previous_parameter = parameter;
	previous_spatial = spatial;
    }

    if (has_terminal_spatial_closure) {
	const ON_3dPoint &closing_point =
	    spatial_polyline->m_pline[spatial_point_count - 1];
	if (!closing_point.IsValid() ||
	    closing_point.DistanceTo(spatial_polyline->m_pline[0]) >
	    INTERSECTION_TOL ||
	    !std::isfinite(spatial_polyline->m_t[spatial_point_count - 1]) ||
	    spatial_polyline->m_t[spatial_point_count - 1] <= spatial_end)
	{
	    return false;
	}
    }

    correspondence.parameter_domain.Set(parameter_start, parameter_end);
    correspondence.spatial_domain.Set(spatial_start, spatial_end);
    correspondence.spatial_full_domain.Set(spatial_start,
	spatial_polyline->m_t[spatial_point_count - 1]);
    correspondence.has_terminal_spatial_closure = has_terminal_spatial_closure;
    return true;
}


static bool
map_normalized_interval(
    const ON_Interval &interval,
    ON_Interval source_domain,
    ON_Interval target_domain,
    ON_Interval &mapped_interval)
{
    source_domain.MakeIncreasing();
    target_domain.MakeIncreasing();
    if (!interval.IsValid() || !source_domain.IsIncreasing() ||
	!target_domain.IsIncreasing())
    {
	return false;
    }

    const double source_span = source_domain.Length();
    if (!(source_span > 0.0) || !std::isfinite(source_span)) {
	return false;
    }

    const double source_scale = std::max(1.0, std::max(
	fabs(source_domain.Min()), fabs(source_domain.Max())));
    const double source_tolerance = ON_ZERO_TOLERANCE * source_scale;
    if (interval.Min() < source_domain.Min() - source_tolerance ||
	interval.Max() > source_domain.Max() + source_tolerance)
    {
	return false;
    }

    double minimum_fraction = (interval.Min() - source_domain.Min()) /
	source_span;
    double maximum_fraction = (interval.Max() - source_domain.Min()) /
	source_span;
    const double fraction_tolerance = source_tolerance / source_span;
    if (!std::isfinite(minimum_fraction) || !std::isfinite(maximum_fraction) ||
	minimum_fraction < -fraction_tolerance ||
	maximum_fraction > 1.0 + fraction_tolerance)
    {
	return false;
    }

    minimum_fraction = std::max(0.0, std::min(1.0, minimum_fraction));
    maximum_fraction = std::max(0.0, std::min(1.0, maximum_fraction));
    mapped_interval.Set(target_domain.ParameterAt(minimum_fraction),
	target_domain.ParameterAt(maximum_fraction));
    mapped_interval.MakeIncreasing();
    return mapped_interval.IsValid();
}


static std::vector<ON_Interval>
interval_2d_to_3d(
    const ON_Interval &interval,
    const ON_Curve *curve2d,
    const ON_Curve *curve3d,
    const ON_Surface *surf)
{
    std::vector<ON_Interval> intervals_3d;

    ON_Interval c2_dom = curve2d->Domain();
    ON_Interval c3_dom = curve3d->Domain();

    SSIPolylineCorrespondence correspondence;
    ON_Interval mapped_interval;
    if (certify_ssi_polyline_correspondence(curve2d, curve3d, surf,
	correspondence))
    {
	const bool covers_parameter_domain = ON_NearZero(interval.Min() -
	    correspondence.parameter_domain.Min(), ON_ZERO_TOLERANCE) &&
	    ON_NearZero(interval.Max() - correspondence.parameter_domain.Max(),
	    ON_ZERO_TOLERANCE);
	if (correspondence.has_terminal_spatial_closure &&
	    covers_parameter_domain)
	{
	    intervals_3d.push_back(correspondence.spatial_full_domain);
	    return intervals_3d;
	}
	if (map_normalized_interval(interval, correspondence.parameter_domain,
		correspondence.spatial_domain, mapped_interval))
	{
	    intervals_3d.push_back(mapped_interval);
	    return intervals_3d;
	}
    }

    c2_dom.MakeIncreasing();
    if (ON_NearZero(interval.Min() - c2_dom.Min(), ON_ZERO_TOLERANCE) &&
	ON_NearZero(interval.Max() - c2_dom.Max(), ON_ZERO_TOLERANCE))
    {
	// entire 2d domain equates to entire 3d domain
	c3_dom.MakeIncreasing();
	if (c3_dom.IsValid()) {
	    intervals_3d.push_back(c3_dom);
	}
    } else {
	// get 2d curve interval points as uv points
	IntervalPoints interval_uv =
	    interval_2d_to_uv(interval, curve2d, surf);

	// evaluate surface at uv points to get 3d interval points
	IntervalPoints pts_3d = points_uv_to_3d(interval_uv, surf);

	// convert 3d points into 3d curve parameters
	try {
	    std::vector<IntervalParams> int_params;

	    IntervalParams curve_t = points_3d_to_params_3d(pts_3d, curve3d);

	    if (curve3d->IsClosed()) {
		// get 3d seam point as surf point
		ON_3dPoint seam_pt = curve3d->PointAt(c3_dom.Min());

		ON_ClassArray<ON_PX_EVENT> events;
		ON_Intersect(seam_pt, *surf, events, INTERSECTION_TOL);

		if (events.Count() == 1) {
		    ON_3dPoint surf_pt = events[0].m_b;
		    std::vector<double> split_t;

		    // get surf point as 2d curve t
		    events.Empty();
		    ON_Intersect(surf_pt, *curve2d, events, INTERSECTION_TOL);
		    if (events.Count() == 1) {
			split_t.push_back(events[0].m_b[0]);
		    }

		    int surf_seam = IsAtSeam(surf, surf_pt, ON_ZERO_TOLERANCE);
		    if (surf_seam != SEAM_NONE) {
			// move surf_pt to other side of seam
			if (surf_seam == SEAM_ALONG_U || surf_seam == SEAM_ALONG_UV) {
			    ON_Interval vdom = surf->Domain(1);
			    if (ON_NearZero(surf_pt.y - vdom.Min(),
					    ON_ZERO_TOLERANCE)) {
				surf_pt.y = vdom.Max();
			    } else {
				surf_pt.y = vdom.Min();
			    }
			}
			if (surf_seam == SEAM_ALONG_V || surf_seam == SEAM_ALONG_UV) {
			    ON_Interval udom = surf->Domain(0);
			    if (ON_NearZero(surf_pt.x - udom.Min(),
					    ON_ZERO_TOLERANCE)) {
				surf_pt.x = udom.Max();
			    } else {
				surf_pt.x = udom.Min();
			    }
			}
			// get alternative surf point as 2d curve t
			events.Empty();
			ON_Intersect(surf_pt, *curve2d, events, INTERSECTION_TOL);
			if (events.Count() == 1) {
			    split_t.push_back(events[0].m_b[0]);
			}
		    }

		    // Split only when the 3D curve seam lies strictly inside this
		    // 2D interval.  Splitting at an endpoint creates a zero-length
		    // half which a closed-curve mapper can mistake for the complete
		    // domain; splitting at a parameter outside the interval creates
		    // an unrelated span.
		    for (size_t i = 0; i < split_t.size(); ++i) {
			ON_Interval parameter_interval = interval;
			parameter_interval.MakeIncreasing();
			const double parameter_scale = std::max(1.0, std::max(
			    fabs(parameter_interval.Min()),
			    fabs(parameter_interval.Max())));
			const double parameter_tolerance = ON_ZERO_TOLERANCE *
			    parameter_scale;
			if (DEBUG_BREP_BOOLEAN) {
			    bu_log("Boolean closed SSI seam candidate %.17g for "
				"parameter interval [%.17g, %.17g], mapped endpoints "
				"%.17g/%.17g and midpoint %.17g.\n", split_t[i],
				interval.Min(), interval.Max(), curve_t.min,
				curve_t.max, curve_t.mid);
			}

			if (parameter_interval.IsIncreasing() &&
			    split_t[i] > parameter_interval.Min() +
				parameter_tolerance &&
			    split_t[i] < parameter_interval.Max() -
				parameter_tolerance)
			{
			    // split 2d interval at seam point
			    std::pair<IntervalPoints, IntervalPoints> halves =
				interval_2d_to_2uv(interval, curve2d, surf,
						   split_t[i]);

			    // convert new intervals to 3d curve intervals
			    IntervalPoints left_3d, right_3d;
			    IntervalParams left_t, right_t;

			    left_3d = points_uv_to_3d(halves.first, surf);
			    left_t = points_3d_to_params_3d(left_3d, curve3d);
			    int_params.push_back(left_t);

			    right_3d = points_uv_to_3d(halves.second, surf);
			    right_t = points_3d_to_params_3d(right_3d, curve3d);
			    int_params.push_back(right_t);
			}
		    }
		}
	    }
	    if (int_params.empty()) {
		int_params.push_back(curve_t);
	    }

	    // get final 3d intervals
	    for (size_t i = 0; i < int_params.size(); ++i) {
		curve_t = curve_interval_from_params(int_params[i], curve3d);
		ON_Interval interval_3d(curve_t.min, curve_t.max);
		if (interval_3d.IsValid()) {
		    intervals_3d.push_back(interval_3d);
		}
	    }
	} catch (AlgorithmError &e) {
	    bu_log("%s", e.what());
	}
    }
    return intervals_3d;
}


// Convert parameter interval of a 3d curve into the equivalent parameter
// interval on a matching 2d face curve.
static ON_Interval
interval_3d_to_2d(
    const ON_Interval &interval,
    const ON_Curve *curve2d,
    const ON_Curve *curve3d,
    const ON_BrepFace *face)
{
    ON_Interval interval_2d;
    if (curve2d == NULL || curve3d == NULL || face == NULL) {
	return interval_2d;
    }

    ON_Interval whole_domain = curve3d->Domain();
    whole_domain.MakeIncreasing();
    if (!whole_domain.IsIncreasing()) {
	return interval_2d;
    }

    if (ON_NearZero(interval.Min() - whole_domain.Min(), ON_ZERO_TOLERANCE) &&
	ON_NearZero(interval.Max() - whole_domain.Max(), ON_ZERO_TOLERANCE))
    {
	interval_2d = curve2d->Domain();
	interval_2d.MakeIncreasing();
	return interval_2d;
    }

    const ON_Surface *surface = face->SurfaceOf();
    if (surface == NULL) {
	return interval_2d;
    }

    SSIPolylineCorrespondence correspondence;
    if (certify_ssi_polyline_correspondence(curve2d, curve3d, surface,
	correspondence) && map_normalized_interval(interval,
	correspondence.spatial_domain, correspondence.parameter_domain,
	interval_2d))
    {
	return interval_2d;
    }

    std::unique_ptr<ON_Curve> lifted_curve(pushup_boolean_curve(surface,
	*curve2d));
    if (lifted_curve) {
	ON_Interval parameter_domain = curve2d->Domain();
	ON_Interval lifted_domain = lifted_curve->Domain();
	parameter_domain.MakeIncreasing();
	lifted_domain.MakeIncreasing();
	const double domain_scale = std::max(1.0, std::max(
	    fabs(parameter_domain.Length()), fabs(lifted_domain.Length())));
	const double domain_tolerance = ON_ZERO_TOLERANCE * domain_scale;
	if (parameter_domain.IsIncreasing() && lifted_domain.IsIncreasing() &&
	    ON_NearZero(parameter_domain.Min() - lifted_domain.Min(),
	    domain_tolerance) && ON_NearZero(parameter_domain.Max() -
	    lifted_domain.Max(), domain_tolerance))
	{
	    IntervalParams lifted_parameters;
	    if (point_3d_to_curve_parameter(curve3d->PointAt(interval.Min()),
		lifted_curve.get(), lifted_parameters.min) &&
		point_3d_to_curve_parameter(curve3d->PointAt(interval.Mid()),
		lifted_curve.get(), lifted_parameters.mid) &&
		point_3d_to_curve_parameter(curve3d->PointAt(interval.Max()),
		lifted_curve.get(), lifted_parameters.max))
	    {
		lifted_parameters = curve_interval_from_params(lifted_parameters,
		    curve2d);
		interval_2d.Set(lifted_parameters.min,
		    lifted_parameters.max);
		if (interval_2d.IsValid()) {
		    return interval_2d;
		}
	    }
	}
    }

    IntervalPoints points;
    points.min = curve3d->PointAt(interval.Min());
    points.mid = curve3d->PointAt(interval.Mid());
    points.max = curve3d->PointAt(interval.Max());

    ON_ClassArray<ON_PX_EVENT> events;
    ON_Intersect(points.min, *surface, events, INTERSECTION_TOL);
    ON_Intersect(points.mid, *surface, events, INTERSECTION_TOL);
    ON_Intersect(points.max, *surface, events, INTERSECTION_TOL);

    if (events.Count() == 3) {
	IntervalPoints interval_uv;
	interval_uv.min = events[0].m_b;
	interval_uv.mid = events[1].m_b;
	interval_uv.max = events[2].m_b;

	interval_uv = uv_interval_from_points(interval_uv, surface);

	events.Empty();
	ON_Intersect(interval_uv.min, *curve2d, events, INTERSECTION_TOL);
	ON_Intersect(interval_uv.mid, *curve2d, events, INTERSECTION_TOL);
	ON_Intersect(interval_uv.max, *curve2d, events, INTERSECTION_TOL);

	if (events.Count() == 3) {
	    IntervalParams curve_parameters;
	    curve_parameters.min = events[0].m_b[0];
	    curve_parameters.mid = events[1].m_b[0];
	    curve_parameters.max = events[2].m_b[0];

	    curve_parameters = curve_interval_from_params(curve_parameters,
		curve2d);
	    interval_2d.Set(curve_parameters.min, curve_parameters.max);
	}
    }
    return interval_2d;
}


static bool
boolean_surface_native_parameter(const ON_Surface *surface, int direction,
	double &parameter)
{
    if (surface == NULL || direction < 0 || direction > 1 ||
	!std::isfinite(parameter))
    {
	return false;
    }
    const ON_Interval domain = surface->Domain(direction);
    if (domain.Includes(parameter))
	return true;
    /* OpenNURBS surfaces can evaluate finite parameters outside their
     * declared domains.  Boolean trims use that extrapolation for small
     * out-of-domain excursions (and planar support may be expanded later).
     * Normalize only genuinely periodic directions. */
    if (!surface->IsClosed(direction))
	return true;
    if (!(domain.Length() > ON_ZERO_TOLERANCE))
	return false;
    double offset = std::fmod(parameter - domain.Min(), domain.Length());
    if (offset < 0.0)
	offset += domain.Length();
    parameter = domain.Min() + offset;
    return true;
}


static ON_3dPoint
boolean_surface_point_at(const ON_Surface *surface, const ON_3dPoint &uv)
{
    if (surface == NULL || !uv.IsValid())
	return ON_3dPoint::UnsetPoint;
    double u = uv.x;
    double v = uv.y;
    if (!boolean_surface_native_parameter(surface, 0, u) ||
	!boolean_surface_native_parameter(surface, 1, v))
    {
	return ON_3dPoint::UnsetPoint;
    }
    return surface->PointAt(u, v);
}


static bool
parameter_curve_lifts_to_model_curve(
    const ON_Surface *surface,
    const ON_Curve *parameter_curve,
    const ON_Curve *model_curve,
    double tolerance,
    int *orientation = NULL)
{
    if (orientation != NULL)
	*orientation = -1;
    if (surface == NULL || parameter_curve == NULL || model_curve == NULL ||
	parameter_curve->Dimension() != 2 || model_curve->Dimension() != 3 ||
	!(tolerance > 0.0) || !std::isfinite(tolerance))
    {
	return false;
    }

    ON_Interval parameter_domain = parameter_curve->Domain();
    ON_Interval model_domain = model_curve->Domain();
    parameter_domain.MakeIncreasing();
    model_domain.MakeIncreasing();
    if (!parameter_domain.IsIncreasing() || !model_domain.IsIncreasing()) {
	return false;
    }

    /* Closed SSI curves have no distinguished seam.  openNURBS may return
     * the model curve and either parameter curve with different seam phases,
     * so comparing equal normalized parameters can report a large error even
     * when the lifted loci are identical.  Certify the complete closed loci
     * after reseaming, then recover orientation from the corresponding
     * tangents at the lifted curve's seam. */
    if (model_curve->IsClosed()) {
	std::unique_ptr<ON_Curve> lifted(pushup_boolean_trim_curve(surface,
	    *parameter_curve));
	ON_NurbsCurve model_nurbs;
	const bool lifted_valid = lifted && lifted->IsValid();
	double lifted_endpoint_distance = ON_UNSET_VALUE;
	bool lifted_closed = lifted_valid && lifted->IsClosed();
	if (lifted_valid) {
	    const ON_3dPoint lifted_start = lifted->PointAtStart();
	    const ON_3dPoint lifted_end = lifted->PointAtEnd();
	    if (lifted_start.IsValid() && lifted_end.IsValid()) {
		lifted_endpoint_distance = lifted_start.DistanceTo(lifted_end);
		/* A parameter curve crossing a periodic surface seam is open in
		 * parameter space even though its lift is a closed model-space
		 * curve.  Pushup sampling can leave its coincident endpoints a few
		 * floating-point units apart, making IsClosed() alone reject an
		 * otherwise certified SSI. */
		if (!lifted_closed && lifted_endpoint_distance <= tolerance) {
		    lifted_closed = lifted->SetEndPoint(lifted_start) &&
			lifted->IsClosed();
		}
	    }
	}
	const bool model_nurbs_valid =
	    model_curve->GetNurbForm(model_nurbs) > 0 && model_nurbs.IsValid();
	const bool loci_coincident = lifted_closed && model_nurbs_valid &&
	    closed_curve_loci_coincident(*model_curve, *lifted, tolerance);
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean closed SSI lift certification: parameter closed %d, "
		"lifted valid/closed %d/%d, endpoint distance %.17g, model "
		"NURBS valid %d, loci coincident %d at tolerance %.17g.\n",
		parameter_curve->IsClosed(), lifted_valid, lifted_closed,
		lifted_endpoint_distance,
		model_nurbs_valid, loci_coincident, tolerance);
	}
	if (!loci_coincident)
	{
	    return false;
	}

	const ON_3dPoint lifted_start = lifted->PointAtStart();
	double model_parameter = model_nurbs.Domain().Min();
	if (!lifted_start.IsValid() || !ON_NurbsCurve_GetClosestPoint(
		&model_parameter, &model_nurbs, lifted_start) ||
	    model_nurbs.PointAt(model_parameter).DistanceTo(lifted_start) >
		tolerance)
	{
	    return false;
	}

	ON_3dVector lifted_tangent = lifted->TangentAt(lifted->Domain().Min());
	ON_3dVector model_tangent = model_nurbs.TangentAt(model_parameter);
	if (!lifted_tangent.Unitize() || !model_tangent.Unitize()) {
	    return false;
	}
	const double tangent_dot = ON_DotProduct(lifted_tangent, model_tangent);
	if (!std::isfinite(tangent_dot) || fabs(tangent_dot) < 0.5) {
	    return false;
	}
	if (orientation != NULL)
	    *orientation = tangent_dot < 0.0 ? 1 : 0;
	return true;
    }

    const int sample_count = std::max(64, 2 * parameter_curve->SpanCount());
    for (int direction = 0; direction < 2; ++direction) {
	bool matches = true;
	for (int sample = 0; sample <= sample_count; ++sample) {
	    const double fraction = static_cast<double>(sample) / sample_count;
	    const ON_3dPoint uv = parameter_curve->PointAt(
		parameter_domain.ParameterAt(fraction));
	    const ON_3dPoint lifted = boolean_surface_point_at(surface, uv);
	    const ON_3dPoint model = model_curve->PointAt(
		model_domain.ParameterAt(direction ? 1.0 - fraction : fraction));
	    if (!uv.IsValid() || !lifted.IsValid() || !model.IsValid() ||
		lifted.DistanceTo(model) > tolerance)
	    {
		matches = false;
		break;
	    }
	}
	if (matches) {
	    if (orientation != NULL)
		*orientation = direction;
	    return true;
	}
    }

    /* A pullback polyline keeps the source-curve order but need not keep its
     * parameter speed: adaptive samples are reparameterized uniformly when
     * the polyline is constructed.  Compare its lifted locus to the model
     * curve by closest points, after requiring corresponding endpoints, so a
     * valid reparameterization is not rejected by the synchronized fast path
     * above. */
    if (!parameter_curve->IsClosed() && !model_curve->IsClosed()) {
	ON_NurbsCurve model_nurbs;
	if (model_curve->GetNurbForm(model_nurbs) > 0 &&
	    model_nurbs.IsValid())
	{
	    const ON_3dPoint lifted_start = boolean_surface_point_at(surface,
		parameter_curve->PointAtStart());
	    const ON_3dPoint lifted_end = boolean_surface_point_at(surface,
		parameter_curve->PointAtEnd());
	    const ON_3dPoint model_start = model_curve->PointAtStart();
	    const ON_3dPoint model_end = model_curve->PointAtEnd();
	    const bool forward = lifted_start.IsValid() && lifted_end.IsValid() &&
		model_start.IsValid() && model_end.IsValid() &&
		lifted_start.DistanceTo(model_start) <= tolerance &&
		lifted_end.DistanceTo(model_end) <= tolerance;
	    const bool reverse = lifted_start.IsValid() && lifted_end.IsValid() &&
		model_start.IsValid() && model_end.IsValid() &&
		lifted_start.DistanceTo(model_end) <= tolerance &&
		lifted_end.DistanceTo(model_start) <= tolerance;
	    if (forward || reverse) {
		bool matches = true;
		for (int sample = 0; sample <= sample_count; ++sample) {
		    const double fraction = static_cast<double>(sample) /
			sample_count;
		    const ON_3dPoint uv = parameter_curve->PointAt(
			parameter_domain.ParameterAt(fraction));
		    const ON_3dPoint lifted = boolean_surface_point_at(surface,
			uv);
		    double nearest = model_nurbs.Domain().ParameterAt(
			(reverse && !forward) ? 1.0 - fraction : fraction);
		    if (!uv.IsValid() || !lifted.IsValid() ||
			!ON_NurbsCurve_GetClosestPoint(&nearest, &model_nurbs,
			    lifted) ||
			lifted.DistanceTo(model_nurbs.PointAt(nearest)) > tolerance)
		    {
			matches = false;
			break;
		    }
		}
		if (matches) {
		    if (orientation != NULL)
			*orientation = reverse && !forward ? 1 : 0;
		    return true;
		}
	    }
	}
    }

    /* Pullback and SSI curves may trace the same locus with different
     * parameter speeds.  Equal normalized parameters are a useful fast path,
     * but they are not a geometric requirement.  Fall back to a certified
     * model-space curve comparison before rejecting a valid reparameterized
     * trim. */
    std::unique_ptr<ON_Curve> lifted(
	pushup_boolean_curve(surface, *parameter_curve));
    bool reversed = false;
    if (lifted && brep_curves_coincident(*lifted, *model_curve, tolerance,
	    &reversed))
    {
	if (orientation != NULL)
	    *orientation = reversed ? 1 : 0;
	return true;
    }
    return false;
}


static double
boolean_model_repair_tolerance(const ON_BoundingBox &model_bounds)
{
    const double model_extent = model_bounds.IsValid() ?
	model_bounds.Diagonal().Length() : 0.0;
    return std::min(1024.0 * INTERSECTION_TOL,
	std::max(INTERSECTION_TOL, 1.0e-4 * model_extent));
}


static bool
closed_curve_has_resolved_area(const ON_Curve &curve, double tolerance)
{
    if (!curve.IsClosed() || !(tolerance > 0.0) ||
	!std::isfinite(tolerance))
    {
	return false;
    }
    const ON_Interval domain = curve.Domain();
    const ON_BoundingBox bounds = curve.BoundingBox();
    if (!domain.IsIncreasing() || !bounds.IsValid() ||
	bounds.Diagonal().Length() <= 4.0 * tolerance)
    {
	return false;
    }

    static const int sample_count = 128;
    ON_3dPoint points[sample_count];
    ON_3dPoint centroid = ON_3dPoint::Origin;
    for (int sample = 0; sample < sample_count; ++sample) {
	points[sample] = curve.PointAt(domain.ParameterAt(
	    (double)sample / sample_count));
	if (!points[sample].IsValid())
	    return false;
	centroid += ON_3dVector(points[sample]);
    }
    centroid /= (double)sample_count;

    ON_3dVector area_vector = ON_3dVector::ZeroVector;
    double length = 0.0;
    for (int sample = 0; sample < sample_count; ++sample) {
	const ON_3dPoint &first = points[sample];
	const ON_3dPoint &second = points[(sample + 1) % sample_count];
	area_vector += ON_CrossProduct(first - centroid, second - centroid);
	length += first.DistanceTo(second);
    }
    return std::isfinite(length) && length > 4.0 * tolerance &&
	0.5 * area_vector.Length() > tolerance * length;
}


static bool
closed_profile_revolution_cylinder_surface_pair(const ON_Surface *first,
	const ON_Surface *second)
{
    if (first == NULL || second == NULL)
	return false;
    const ON_RevSurface *first_revolution = ON_RevSurface::Cast(first);
    const ON_RevSurface *second_revolution = ON_RevSurface::Cast(second);
    ON_Cylinder cylinder;
    return (first_revolution != NULL && first_revolution->m_curve != NULL &&
	first_revolution->m_curve->IsClosed() &&
	second->IsCylinder(&cylinder, INTERSECTION_TOL)) ||
	(second_revolution != NULL && second_revolution->m_curve != NULL &&
	 second_revolution->m_curve->IsClosed() &&
	 first->IsCylinder(&cylinder, INTERSECTION_TOL));
}


struct BooleanSurfaceParameterSample {
    double model_parameter;
    ON_2dPoint surface_parameter;
};


static bool
synchronized_surface_parameter_at(brlcad::PullbackContext &context,
	const ON_Surface *surface, const ON_3dPoint &model_point,
	const ON_2dPoint *reference, const bool surface_closed[2],
	const ON_Interval surface_domains[2], double tolerance,
	ON_2dPoint &surface_point)
{
    ON_3dPoint lifted_point;
    double distance = DBL_MAX;
    bool projected = false;
    if (reference != NULL && reference->IsValid()) {
	ON_2dPoint seed(*reference);
	for (int direction = 0; direction < 2; ++direction) {
	    double native_parameter = seed[direction];
	    if (!boolean_surface_native_parameter(surface, direction,
		    native_parameter))
	    {
		return false;
	    }
	    seed[direction] = native_parameter;
	}
	projected = context.SurfaceClosestPointFromSeed(surface, model_point,
	    seed, surface_point, lifted_point, distance, tolerance,
	    surface_closed, surface_domains,
	    std::max(ON_ZERO_TOLERANCE, 0.01 * tolerance));
    }
    if (!projected || !surface_point.IsValid() || !lifted_point.IsValid() ||
	!std::isfinite(distance) || distance > tolerance)
    {
	distance = DBL_MAX;
	projected = context.SurfaceClosestPoint(surface, model_point,
	    surface_point, lifted_point, distance, 0, ON_ZERO_TOLERANCE,
	    tolerance);
    }
    if (!projected || !surface_point.IsValid() || !lifted_point.IsValid() ||
	!std::isfinite(distance) || distance > tolerance)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_ClassId *surface_class = surface->ClassId();
	    bu_log("Boolean closed SSI surface projection failed on %s at "
		"%.17g %.17g %.17g from reference %.17g %.17g: "
		"projected %d, UV valid %d, lift valid %d, distance %.17g, "
		"tolerance %.17g.\n",
		surface_class ? surface_class->ClassName() : "unknown surface",
		model_point.x, model_point.y, model_point.z,
		reference ? reference->x : ON_UNSET_VALUE,
		reference ? reference->y : ON_UNSET_VALUE, projected,
		surface_point.IsValid(), lifted_point.IsValid(), distance,
		tolerance);
	}
	return false;
    }

    if (reference != NULL && reference->IsValid()) {
	for (int direction = 0; direction < 2; ++direction) {
	    if (!surface_closed[direction])
		continue;
	    const double period = surface_domains[direction].Length();
	    if (period > ON_ZERO_TOLERANCE) {
		surface_point[direction] += std::round(
		    ((*reference)[direction] - surface_point[direction]) /
		    period) * period;
	    }
	}
    }
    return true;
}


static double
synchronized_surface_interval_error(const ON_Surface *surface,
	const ON_Curve &model_curve,
	const BooleanSurfaceParameterSample &first,
	const BooleanSurfaceParameterSample &second)
{
    static const double fractions[7] = {
	0.125, 0.25, 0.375, 0.5, 0.625, 0.75, 0.875
    };
    double maximum_error = 0.0;
    for (int sample = 0; sample < 7; ++sample) {
	const double fraction = fractions[sample];
	const double parameter = (1.0 - fraction) * first.model_parameter +
	    fraction * second.model_parameter;
	const ON_3dPoint uv(
	    (1.0 - fraction) * first.surface_parameter.x +
		fraction * second.surface_parameter.x,
	    (1.0 - fraction) * first.surface_parameter.y +
		fraction * second.surface_parameter.y, 0.0);
	const ON_3dPoint lifted = boolean_surface_point_at(surface, uv);
	const ON_3dPoint model = model_curve.PointAt(parameter);
	if (!lifted.IsValid() || !model.IsValid())
	    return DBL_MAX;
	maximum_error = std::max(maximum_error, lifted.DistanceTo(model));
    }
    return maximum_error;
}


static ON_Curve *
synchronized_surface_parameter_curve(const ON_Surface *surface,
	const ON_Curve &model_curve, double tolerance)
{
    if (surface == NULL || !(tolerance > 0.0)) {
	if (DEBUG_BREP_BOOLEAN)
	    bu_log("Boolean closed SSI synchronized parameter curve rejected invalid input.\n");
	return NULL;
    }

    const ON_Interval model_domain = model_curve.Domain();
    const ON_Interval surface_domains[2] = {
	surface->Domain(0), surface->Domain(1)
    };
    const bool surface_closed[2] = {
	surface->IsClosed(0), surface->IsClosed(1)
    };
    if (!model_domain.IsIncreasing() ||
	!surface_domains[0].IsIncreasing() ||
	!surface_domains[1].IsIncreasing())
    {
	if (DEBUG_BREP_BOOLEAN)
	    bu_log("Boolean closed SSI synchronized parameter curve rejected invalid domains.\n");
	return NULL;
    }

    static const int initial_segment_count = 64;
    static const size_t maximum_sample_count = 16385;
    static const int maximum_refinement_passes = 16;
    const double refinement_tolerance = 0.5 * tolerance;
    brlcad::PullbackContext context;
    std::vector<BooleanSurfaceParameterSample> samples;
    samples.reserve(initial_segment_count + 1);
    for (int sample = 0; sample <= initial_segment_count; ++sample) {
	BooleanSurfaceParameterSample current;
	current.model_parameter = model_domain.ParameterAt(
	    (double)sample / initial_segment_count);
	const ON_3dPoint model_point = model_curve.PointAt(
	    current.model_parameter);
	const ON_2dPoint *reference = samples.empty() ? NULL :
	    &samples.back().surface_parameter;
	if (!model_point.IsValid() ||
	    !synchronized_surface_parameter_at(context, surface, model_point,
		reference, surface_closed, surface_domains, tolerance,
		current.surface_parameter))
	{
	    if (DEBUG_BREP_BOOLEAN)
		bu_log("Boolean closed SSI synchronized parameter curve projection failed at initial sample %d/%d and tolerance %.17g.\n",
		    sample, initial_segment_count, tolerance);
	    return NULL;
	}
	samples.push_back(current);
    }

    bool converged = false;
    for (int refinement = 0; refinement < maximum_refinement_passes;
	 ++refinement)
    {
	std::vector<BooleanSurfaceParameterSample> refined;
	refined.reserve(std::min(maximum_sample_count,
	    2 * samples.size() - 1));
	refined.push_back(samples.front());
	bool changed = false;
	for (size_t sample = 1; sample < samples.size(); ++sample) {
	    const BooleanSurfaceParameterSample &first = samples[sample - 1];
	    const BooleanSurfaceParameterSample &second = samples[sample];
	    if (synchronized_surface_interval_error(surface, model_curve,
		    first, second) > refinement_tolerance)
	    {
		if (refined.size() + samples.size() - sample + 1 >
			maximum_sample_count)
		{
		    if (DEBUG_BREP_BOOLEAN)
			bu_log("Boolean closed SSI synchronized parameter curve exceeded its sample budget.\n");
		    return NULL;
		}
		BooleanSurfaceParameterSample midpoint;
		midpoint.model_parameter = 0.5 * (first.model_parameter +
		    second.model_parameter);
		const ON_3dPoint model_point = model_curve.PointAt(
		    midpoint.model_parameter);
		const ON_2dPoint reference(
		    0.5 * (first.surface_parameter.x +
			second.surface_parameter.x),
		    0.5 * (first.surface_parameter.y +
			second.surface_parameter.y));
		if (!model_point.IsValid() ||
		    !synchronized_surface_parameter_at(context, surface,
			model_point, &reference, surface_closed, surface_domains,
			tolerance, midpoint.surface_parameter))
		{
		    if (DEBUG_BREP_BOOLEAN)
			bu_log("Boolean closed SSI synchronized parameter curve midpoint projection failed at refinement %d and tolerance %.17g.\n",
			    refinement, tolerance);
		    return NULL;
		}
		refined.push_back(midpoint);
		changed = true;
	    }
	    refined.push_back(second);
	}
	samples.swap(refined);
	if (!changed) {
	    converged = true;
	    break;
	}
    }
    if (!converged) {
	if (DEBUG_BREP_BOOLEAN)
	    bu_log("Boolean closed SSI synchronized parameter curve did not converge with %zu samples.\n",
		samples.size());
	return NULL;
    }

    ON_3dPointArray parameter_points;
    ON_SimpleArray<double> parameters;
    parameter_points.Reserve(static_cast<int>(samples.size()));
    parameters.Reserve(static_cast<int>(samples.size()));
    for (size_t sample = 0; sample < samples.size(); ++sample) {
	parameter_points.Append(ON_3dPoint(samples[sample].surface_parameter.x,
	    samples[sample].surface_parameter.y, 0.0));
	parameters.Append(samples[sample].model_parameter);
    }

    std::unique_ptr<ON_PolylineCurve> parameter_curve(
	new ON_PolylineCurve(parameter_points, parameters));
    if (!parameter_curve || !parameter_curve->ChangeDimension(2) ||
	!parameter_curve->IsValid() ||
	!parameter_curve_lifts_to_model_curve(surface, parameter_curve.get(),
	    &model_curve, tolerance))
    {
	if (DEBUG_BREP_BOOLEAN)
	    bu_log("Boolean closed SSI synchronized parameter curve failed final lift certification with %zu samples.\n",
		samples.size());
	return NULL;
    }
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean closed SSI synchronized parameter curve converged with "
	    "%zu samples at tolerance %.17g.\n", samples.size(), tolerance);
    }
    return parameter_curve.release();
}


static bool
repair_closed_ssi_parameter_curves(
	const ON_Surface *first_surface, const ON_Surface *second_surface,
	const ON_Curve *first_parameter_curve,
	const ON_Curve *second_parameter_curve,
	const ON_Curve &model_curve, double tolerance,
	std::unique_ptr<ON_Curve> &repaired_first_parameter_curve,
	std::unique_ptr<ON_Curve> &repaired_second_parameter_curve)
{
    if (first_surface == NULL || second_surface == NULL ||
	first_parameter_curve == NULL || second_parameter_curve == NULL ||
	!closed_curve_has_resolved_area(model_curve, tolerance))
    {
	return false;
    }

    int first_orientation = -1;
    int second_orientation = -1;
    const bool preserve_first = parameter_curve_lifts_to_model_curve(
	first_surface, first_parameter_curve, &model_curve, tolerance,
	&first_orientation);
    const bool preserve_second = parameter_curve_lifts_to_model_curve(
	second_surface, second_parameter_curve, &model_curve, tolerance,
	&second_orientation);

    std::unique_ptr<ON_Curve> first(preserve_first ?
	first_parameter_curve->DuplicateCurve() :
	synchronized_surface_parameter_curve(first_surface, model_curve,
	    tolerance));
    std::unique_ptr<ON_Curve> second(preserve_second ?
	second_parameter_curve->DuplicateCurve() :
	synchronized_surface_parameter_curve(second_surface, model_curve,
	    tolerance));
    if (!first || !second ||
	!parameter_curve_lifts_to_model_curve(first_surface, first.get(),
	    &model_curve, tolerance, &first_orientation) ||
	!parameter_curve_lifts_to_model_curve(second_surface, second.get(),
	    &model_curve, tolerance, &second_orientation))

	return false;

    if (first_orientation != second_orientation) {
	if (!second->Reverse() ||
	    !parameter_curve_lifts_to_model_curve(second_surface, second.get(),
		&model_curve, tolerance, &second_orientation) ||
	    first_orientation != second_orientation)
	{
	    return false;
	}
    }
    repaired_first_parameter_curve = std::move(first);
    repaired_second_parameter_curve = std::move(second);
    return true;
}


static double
parameter_curve_lift_maximum_error(
    const ON_Surface *surface,
    const ON_Curve *parameter_curve,
    const ON_Curve *model_curve,
    bool reversed);


static ON_Curve *
validated_ssi_parameter_subcurve(
    const ON_Surface *surface,
    ON_Curve *parameter_curve,
    const ON_Curve *model_curve)
{
    std::unique_ptr<ON_Curve> original(parameter_curve);
    if (surface == NULL || model_curve == NULL ||
	model_curve->Dimension() != 3 || !model_curve->IsValid() ||
	!model_curve->Domain().IsIncreasing())
    {
	return NULL;
    }

    if (parameter_curve_lifts_to_model_curve(surface, parameter_curve,
	model_curve, INTERSECTION_TOL))
    {
	return original.release();
    }

    const ON_BoundingBox model_bounds = model_curve ?
	model_curve->BoundingBox() : ON_BoundingBox::EmptyBoundingBox;
    const double repair_tolerance =
	boolean_model_repair_tolerance(model_bounds);

    std::string failure_reason;
    PullbackFailureReason failure = PullbackFailureReason::None;
    std::unique_ptr<ON_Curve> repaired(brlcad::pullback_curve(surface,
	model_curve, repair_tolerance, std::max(INTERSECTION_TOL,
	    0.25 * repair_tolerance), &failure_reason, &failure));
    if (!repaired || repaired->Dimension() != 2 || !repaired->IsValid())
    {
	record_boolean_projection_failure();
	bu_log("Unable to repair an SSI parameter subcurve (reason %d): %s\n",
	    static_cast<int>(failure), failure_reason.c_str());
	return NULL;
    }
    if (!parameter_curve_lifts_to_model_curve(surface, repaired.get(),
	model_curve, repair_tolerance))
    {
	const ON_ClassId *surface_class = surface->ClassId();
	const double original_direct = parameter_curve_lift_maximum_error(
	    surface, original.get(), model_curve, false);
	const double original_reverse = parameter_curve_lift_maximum_error(
	    surface, original.get(), model_curve, true);
	const double repaired_direct = parameter_curve_lift_maximum_error(
	    surface, repaired.get(), model_curve, false);
	const double repaired_reverse = parameter_curve_lift_maximum_error(
	    surface, repaired.get(), model_curve, true);
	bu_log("Rejected an SSI parameter subcurve whose repair does not lift "
	    "to the model curve within tolerance %.17g (%s; original direct/"
	    "reverse %.17g/%.17g, repaired %.17g/%.17g).\n",
	    repair_tolerance,
	    surface_class ? surface_class->ClassName() : "unknown surface",
	    original_direct, original_reverse, repaired_direct,
	    repaired_reverse);
	return NULL;
    }

    bu_log("Repaired an SSI parameter subcurve with model tolerance %.17g.\n",
	repair_tolerance);
    return repaired.release();
}


static bool
boolean_parameter_connector_is_pointlike(
    const ON_Surface *surface,
    const ON_3dPoint &from,
    const ON_3dPoint &to,
    const ON_3dPoint &model_point,
    double tolerance)
{
    if (surface == NULL || !from.IsValid() || !to.IsValid() ||
	!model_point.IsValid() || !(tolerance > 0.0) ||
	!std::isfinite(tolerance))
    {
	return false;
    }

    static const int sample_count = 16;
    for (int sample = 0; sample <= sample_count; ++sample) {
	const double fraction = static_cast<double>(sample) / sample_count;
	const ON_3dPoint parameter(
	    (1.0 - fraction) * from.x + fraction * to.x,
	    (1.0 - fraction) * from.y + fraction * to.y, 0.0);
	const ON_3dPoint lifted = boolean_surface_point_at(surface, parameter);
	if (!lifted.IsValid() || lifted.DistanceTo(model_point) > tolerance) {
	    return false;
	}
    }
    return true;
}


static bool
nearest_boolean_face_boundary_point(
    const ON_Surface *surface,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &face_loops,
    const ON_3dPoint &parameter_point,
    const ON_3dPoint &model_point,
    double tolerance,
    ON_3dPoint &boundary_parameter,
    ON_3dPoint &boundary_model)
{
    if (surface == NULL || !parameter_point.IsValid() ||
	!model_point.IsValid() || !(tolerance > 0.0))
    {
	return false;
    }

    bool found = false;
    double nearest_distance = std::numeric_limits<double>::infinity();
    for (int loop_index = 0; loop_index < face_loops.Count(); ++loop_index) {
	for (int curve_index = 0;
	     curve_index < face_loops[loop_index].Count(); ++curve_index)
	{
	    const ON_Curve *boundary = face_loops[loop_index][curve_index];
	    ON_NurbsCurve boundary_nurbs;
	    if (boundary == NULL || boundary->Dimension() != 2 ||
		boundary->GetNurbForm(boundary_nurbs) <= 0 ||
		!boundary_nurbs.IsValid())
	    {
		continue;
	    }

	    double boundary_t = boundary_nurbs.Domain().Mid();
	    if (!ON_NurbsCurve_GetClosestPoint(&boundary_t, &boundary_nurbs,
		parameter_point))
	    {
		continue;
	    }
	    const ON_3dPoint candidate_parameter =
		boundary_nurbs.PointAt(boundary_t);
	    if (!candidate_parameter.IsValid()) {
		continue;
	    }
	    const ON_3dPoint candidate_model =
		boolean_surface_point_at(surface, candidate_parameter);
	    if (!candidate_model.IsValid()) {
		continue;
	    }
	    const double distance = candidate_model.DistanceTo(model_point);
	    if (!std::isfinite(distance) || distance > tolerance ||
		!boolean_parameter_connector_is_pointlike(surface, parameter_point,
		    candidate_parameter, model_point, tolerance))
	    {
		continue;
	    }

	    if (found && candidate_model.DistanceTo(boundary_model) > tolerance) {
		return false;
	    }
	    if (!found || distance < nearest_distance) {
		found = true;
		nearest_distance = distance;
		boundary_parameter = candidate_parameter;
		boundary_model = candidate_model;
	    }
	}
    }
    return found;
}


/* An SSI fitter can stop within modeling tolerance of a trim boundary.  Snap
 * such endpoints only when one complete side has unique boundary evidence,
 * both surface connectors remain pointlike, and the repaired triplet retains
 * the original locus and orientation. */
static bool
repair_open_ssi_endpoints_to_face_boundaries(
    const ON_Surface *first_surface,
    const ON_Surface *second_surface,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &first_loops,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &second_loops,
    ON_Curve *&model_curve,
    ON_Curve *&first_parameter_curve,
    ON_Curve *&second_parameter_curve)
{
    if (first_surface == NULL || second_surface == NULL ||
	model_curve == NULL || first_parameter_curve == NULL ||
	second_parameter_curve == NULL || model_curve->IsClosed() ||
	first_parameter_curve->IsClosed() || second_parameter_curve->IsClosed())
    {
	return false;
    }

    const double tolerance = boolean_model_repair_tolerance(
	model_curve->BoundingBox());
    std::unique_ptr<ON_Curve> repaired_model(model_curve->DuplicateCurve());
    std::unique_ptr<ON_Curve> repaired_first(
	first_parameter_curve->DuplicateCurve());
    std::unique_ptr<ON_Curve> repaired_second(
	second_parameter_curve->DuplicateCurve());
    if (!repaired_model || !repaired_first || !repaired_second) {
	return false;
    }

    bool changed = false;
    brlcad::PullbackContext context;
    ON_3dPoint boundary_parameters[2][2];
    ON_3dPoint boundary_models[2][2];
    bool boundary_found[2][2] = {{false, false}, {false, false}};
    for (int endpoint = 0; endpoint < 2; ++endpoint) {
	const bool at_end = endpoint != 0;
	const ON_3dPoint model_point = at_end ? repaired_model->PointAtEnd() :
	    repaired_model->PointAtStart();
	const ON_3dPoint parameter_points[2] = {
	    at_end ? repaired_first->PointAtEnd() : repaired_first->PointAtStart(),
	    at_end ? repaired_second->PointAtEnd() : repaired_second->PointAtStart()
	};
	const ON_Surface *surfaces[2] = {first_surface, second_surface};
	const ON_ClassArray<ON_SimpleArray<ON_Curve *> > *loops[2] = {
	    &first_loops, &second_loops
	};
	for (int side = 0; side < 2; ++side) {
	    boundary_found[side][endpoint] = nearest_boolean_face_boundary_point(
		surfaces[side], *loops[side], parameter_points[side],
		model_point, tolerance, boundary_parameters[side][endpoint],
		boundary_models[side][endpoint]);
	}
    }
    const bool first_bounded = boundary_found[0][0] && boundary_found[0][1];
    const bool second_bounded = boundary_found[1][0] && boundary_found[1][1];
    if (!first_bounded && !second_bounded) {
	return false;
    }

    for (int endpoint = 0; endpoint < 2; ++endpoint) {
	const bool at_end = endpoint != 0;
	const ON_3dPoint model_point = at_end ? repaired_model->PointAtEnd() :
	    repaired_model->PointAtStart();
	const ON_3dPoint first_point = at_end ? repaired_first->PointAtEnd() :
	    repaired_first->PointAtStart();
	const ON_3dPoint second_point = at_end ? repaired_second->PointAtEnd() :
	    repaired_second->PointAtStart();
	const bool first_found = first_bounded && boundary_found[0][endpoint];
	const bool second_found = second_bounded && boundary_found[1][endpoint];
	if (!first_found && !second_found) {
	    return false;
	}
	if (first_found && second_found &&
	    boundary_models[0][endpoint].DistanceTo(
		boundary_models[1][endpoint]) > tolerance)
	{
	    return false;
	}

	const ON_3dPoint target_model = first_found ?
	    boundary_models[0][endpoint] : boundary_models[1][endpoint];
	ON_3dPoint target_parameters[2] = {
	    boundary_parameters[0][endpoint], boundary_parameters[1][endpoint]
	};
	const ON_Surface *surfaces[2] = {first_surface, second_surface};
	const ON_3dPoint original_parameters[2] = {first_point, second_point};
	const bool found_boundary[2] = {first_found, second_found};
	for (int side = 0; side < 2; ++side) {
	    if (found_boundary[side]) {
		continue;
	    }
	    const ON_Interval domains[2] = {
		surfaces[side]->Domain(0), surfaces[side]->Domain(1)
	    };
	    const bool closed[2] = {
		surfaces[side]->IsClosed(0) || surfaces[side]->IsPeriodic(0),
		surfaces[side]->IsClosed(1) || surfaces[side]->IsPeriodic(1)
	    };
	    ON_2dPoint projected;
	    const ON_2dPoint reference(original_parameters[side]);
	    if (!synchronized_surface_parameter_at(context, surfaces[side],
		    target_model, &reference, closed, domains, tolerance,
		    projected))
	    {
		return false;
	    }
	    target_parameters[side] = ON_3dPoint(projected.x, projected.y, 0.0);
	}
	if (!boolean_parameter_connector_is_pointlike(first_surface,
		first_point, target_parameters[0], target_model, tolerance) ||
	    !boolean_parameter_connector_is_pointlike(second_surface,
		second_point, target_parameters[1], target_model, tolerance))
	{
	    return false;
	}

	const bool endpoints_set = at_end ?
	    repaired_model->SetEndPoint(target_model) &&
		repaired_first->SetEndPoint(target_parameters[0]) &&
		repaired_second->SetEndPoint(target_parameters[1]) :
	    repaired_model->SetStartPoint(target_model) &&
		repaired_first->SetStartPoint(target_parameters[0]) &&
		repaired_second->SetStartPoint(target_parameters[1]);
	if (!endpoints_set) {
	    return false;
	}
	changed = true;
    }

    int first_orientation = -1;
    int second_orientation = -1;
    if (!changed || !repaired_model->IsValid() ||
	!repaired_first->IsValid() || !repaired_second->IsValid() ||
	!parameter_curve_lifts_to_model_curve(first_surface,
	    repaired_first.get(), repaired_model.get(), tolerance,
	    &first_orientation) ||
	!parameter_curve_lifts_to_model_curve(second_surface,
	    repaired_second.get(), repaired_model.get(), tolerance,
	    &second_orientation) || first_orientation != second_orientation ||
	!brep_curves_coincident(*model_curve, *repaired_model, tolerance))
    {
	return false;
    }

    delete model_curve;
    delete first_parameter_curve;
    delete second_parameter_curve;
    model_curve = repaired_model.release();
    first_parameter_curve = repaired_first.release();
    second_parameter_curve = repaired_second.release();
    return true;
}


/* Some surface/surface intersections return a model curve whose endpoints
 * are correct but whose fitted interior wanders off both surfaces.  The two
 * accompanying parameter curves may still describe the same intersection
 * locus accurately.  When their independent pushups coincide at the base
 * intersection tolerance, use that stronger paired evidence to replace the
 * defective open model curve. */
static bool
repair_open_ssi_model_subcurve_from_parameter_pair(
    const ON_Surface *first_surface,
    const ON_Surface *second_surface,
    ON_Curve *first_parameter_curve,
    ON_Curve *second_parameter_curve,
    ON_Curve *&model_curve)
{
    if (first_surface == NULL || second_surface == NULL ||
	first_parameter_curve == NULL || second_parameter_curve == NULL ||
	model_curve == NULL || model_curve->IsClosed() ||
	first_parameter_curve->Dimension() != 2 ||
	second_parameter_curve->Dimension() != 2)
    {
	return false;
    }

    std::unique_ptr<ON_Curve> first_lifted(pushup_boolean_curve(
	first_surface, *first_parameter_curve));
    std::unique_ptr<ON_Curve> second_lifted(pushup_boolean_curve(
	second_surface, *second_parameter_curve));
    if (!first_lifted || !second_lifted || !first_lifted->IsValid() ||
	!second_lifted->IsValid() || first_lifted->IsClosed() ||
	second_lifted->IsClosed())
    {
	return false;
    }

    bool pair_reversed = false;
    if (!brep_curves_coincident(*first_lifted, *second_lifted,
	    INTERSECTION_TOL, &pair_reversed))
    {
	return false;
    }

    const double endpoint_tolerance = boolean_model_repair_tolerance(
	model_curve->BoundingBox());
    const ON_3dPoint model_start = model_curve->PointAtStart();
    const ON_3dPoint model_end = model_curve->PointAtEnd();
    const auto endpoint_orientation = [model_start, model_end,
	endpoint_tolerance](const ON_Curve &curve, bool &reversed) {
	    const ON_3dPoint start = curve.PointAtStart();
	    const ON_3dPoint end = curve.PointAtEnd();
	    if (!model_start.IsValid() || !model_end.IsValid() ||
		!start.IsValid() || !end.IsValid())
	    {
		return false;
	    }
	    const double direct = std::max(start.DistanceTo(model_start),
		end.DistanceTo(model_end));
	    const double reverse = std::max(start.DistanceTo(model_end),
		end.DistanceTo(model_start));
	    if (std::min(direct, reverse) > endpoint_tolerance) {
		return false;
	    }
	    reversed = reverse < direct;
	    return true;
	};

    bool first_reversed = false;
    bool second_reversed = false;
    if (!endpoint_orientation(*first_lifted, first_reversed) ||
	!endpoint_orientation(*second_lifted, second_reversed) ||
	pair_reversed != (first_reversed != second_reversed))
    {
	return false;
    }

    if (first_reversed &&
	(!first_lifted->Reverse() || !first_parameter_curve->Reverse()))
    {
	return false;
    }
    if (second_reversed && !second_parameter_curve->Reverse()) {
	return false;
    }

    delete model_curve;
    model_curve = first_lifted.release();
    return true;
}


static void
debug_boolean_intervals(
    const char *label,
    const ON_SimpleArray<ON_Interval> &intervals)
{
    if (!DEBUG_BREP_BOOLEAN) {
	return;
    }

    bu_log("Boolean SSI %s has %d interval%s:", label, intervals.Count(),
	intervals.Count() == 1 ? "" : "s");
    for (int interval_index = 0; interval_index < intervals.Count();
	 ++interval_index)
    {
	bu_log(" [%.17g, %.17g]", intervals[interval_index].Min(),
	    intervals[interval_index].Max());
    }
    bu_log(".\n");
}


static void
debug_boolean_intervals(
    const char *label,
    const std::vector<ON_Interval> &intervals)
{
    if (!DEBUG_BREP_BOOLEAN) {
	return;
    }

    bu_log("Boolean SSI %s has %zu interval%s:", label, intervals.size(),
	intervals.size() == 1 ? "" : "s");
    for (size_t interval_index = 0; interval_index < intervals.size();
	 ++interval_index)
    {
	bu_log(" [%.17g, %.17g]", intervals[interval_index].Min(),
	    intervals[interval_index].Max());
    }
    bu_log(".\n");
}


static void
debug_boolean_curve(const char *label, const ON_Curve *curve)
{
    if (!DEBUG_BREP_BOOLEAN) {
	return;
    }
    if (curve == NULL) {
	bu_log("Boolean SSI %s is null.\n", label);
	return;
    }

    const ON_Interval domain = curve->Domain();
    const ON_3dPoint start = curve->PointAtStart();
    const ON_3dPoint end = curve->PointAtEnd();
    bu_log("Boolean SSI %s dimension %d domain [%.17g, %.17g], valid %d, "
	"closed %d, endpoint distance %.17g.\n", label, curve->Dimension(),
	domain.Min(), domain.Max(), curve->IsValid(), curve->IsClosed(),
	start.IsValid() && end.IsValid() ? start.DistanceTo(end) : -1.0);
}


static double
parameter_curve_lift_maximum_error(
    const ON_Surface *surface,
    const ON_Curve *parameter_curve,
    const ON_Curve *model_curve,
    bool reversed)
{
    if (surface == NULL || parameter_curve == NULL || model_curve == NULL) {
	return std::numeric_limits<double>::infinity();
    }

    ON_Interval parameter_domain = parameter_curve->Domain();
    ON_Interval model_domain = model_curve->Domain();
    parameter_domain.MakeIncreasing();
    model_domain.MakeIncreasing();
    if (!parameter_domain.IsIncreasing() || !model_domain.IsIncreasing()) {
	return std::numeric_limits<double>::infinity();
    }

    static const int sample_count = 64;
    double maximum_error = 0.0;
    for (int sample = 0; sample <= sample_count; ++sample) {
	const double fraction = static_cast<double>(sample) / sample_count;
	const ON_3dPoint uv = parameter_curve->PointAt(
	    parameter_domain.ParameterAt(fraction));
	const ON_3dPoint lifted = boolean_surface_point_at(surface, uv);
	const ON_3dPoint model = model_curve->PointAt(model_domain.ParameterAt(
	    reversed ? 1.0 - fraction : fraction));
	if (!uv.IsValid() || !lifted.IsValid() || !model.IsValid()) {
	    return std::numeric_limits<double>::infinity();
	}
	maximum_error = std::max(maximum_error, lifted.DistanceTo(model));
    }
    return maximum_error;
}


static double
parameter_curve_pair_lift_maximum_error(
    const ON_Surface *first_surface,
    const ON_Curve *first_parameter_curve,
    const ON_Surface *second_surface,
    const ON_Curve *second_parameter_curve,
    bool reversed)
{
    if (first_surface == NULL || first_parameter_curve == NULL ||
	second_surface == NULL || second_parameter_curve == NULL)
    {
	return std::numeric_limits<double>::infinity();
    }

    ON_Interval first_domain = first_parameter_curve->Domain();
    ON_Interval second_domain = second_parameter_curve->Domain();
    first_domain.MakeIncreasing();
    second_domain.MakeIncreasing();
    if (!first_domain.IsIncreasing() || !second_domain.IsIncreasing()) {
	return std::numeric_limits<double>::infinity();
    }

    static const int sample_count = 256;
    double maximum_error = 0.0;
    for (int sample = 0; sample <= sample_count; ++sample) {
	const double fraction = static_cast<double>(sample) / sample_count;
	const ON_3dPoint first_uv = first_parameter_curve->PointAt(
	    first_domain.ParameterAt(fraction));
	const ON_3dPoint second_uv = second_parameter_curve->PointAt(
	    second_domain.ParameterAt(reversed ? 1.0 - fraction : fraction));
	const ON_3dPoint first_lifted = boolean_surface_point_at(first_surface,
	    first_uv);
	const ON_3dPoint second_lifted = boolean_surface_point_at(second_surface,
	    second_uv);
	if (!first_uv.IsValid() || !second_uv.IsValid() ||
	    !first_lifted.IsValid() || !second_lifted.IsValid())
	{
	    return std::numeric_limits<double>::infinity();
	}
	maximum_error = std::max(maximum_error,
	    first_lifted.DistanceTo(second_lifted));
    }
    return maximum_error;
}


static bool
repair_closed_ssi_model_subcurve_from_parameter_pair(
    const ON_Surface *first_surface,
    const ON_Surface *second_surface,
    ON_Curve *first_parameter_curve,
    ON_Curve *second_parameter_curve,
    ON_Curve *&model_curve,
    double tolerance)
{
    if (first_surface == NULL || second_surface == NULL ||
	first_parameter_curve == NULL || second_parameter_curve == NULL ||
	model_curve == NULL || !model_curve->IsClosed() ||
	first_parameter_curve->Dimension() != 2 ||
	second_parameter_curve->Dimension() != 2 || !(tolerance > 0.0) ||
	!closed_curve_has_resolved_area(*model_curve,
	    std::min(tolerance, INTERSECTION_TOL)))
    {
	return false;
    }

    const double direct_error = parameter_curve_pair_lift_maximum_error(
	first_surface, first_parameter_curve, second_surface,
	second_parameter_curve, false);
    const double reverse_error = parameter_curve_pair_lift_maximum_error(
	first_surface, first_parameter_curve, second_surface,
	second_parameter_curve, true);
    if (std::min(direct_error, reverse_error) > tolerance) {
	if (DEBUG_BREP_BOOLEAN)
	    bu_log("Boolean closed SSI paired-model repair rejected lift errors %.17g/%.17g at tolerance %.17g.\n",
		direct_error, reverse_error, tolerance);
	return false;
    }

    std::unique_ptr<ON_Curve> first_lifted(pushup_boolean_trim_curve(
	first_surface, *first_parameter_curve));
    std::unique_ptr<ON_Curve> second_lifted(pushup_boolean_trim_curve(
	second_surface, *second_parameter_curve));
    if (!first_lifted || !second_lifted || !first_lifted->IsValid() ||
	!second_lifted->IsValid())
    {
	if (DEBUG_BREP_BOOLEAN)
	    bu_log("Boolean closed SSI paired-model repair could not sample valid lifts (%d/%d).\n",
		first_lifted && first_lifted->IsValid(),
		second_lifted && second_lifted->IsValid());
	return false;
    }

    const auto close_within_tolerance = [tolerance](ON_Curve &curve) {
	const ON_3dPoint start = curve.PointAtStart();
	const ON_3dPoint end = curve.PointAtEnd();
	if (!start.IsValid() || !end.IsValid())
	    return false;
	if (curve.IsClosed())
	    return true;
	return start.DistanceTo(end) <= tolerance &&
	    curve.SetEndPoint(start) && curve.IsClosed();
    };
    const bool first_closed = close_within_tolerance(*first_lifted);
    const bool second_closed = close_within_tolerance(*second_lifted);
    if (!first_closed && !second_closed && DEBUG_BREP_BOOLEAN) {
	ON_LineCurve first_connector(first_parameter_curve->PointAtEnd(),
	    first_parameter_curve->PointAtStart());
	ON_LineCurve second_connector(second_parameter_curve->PointAtEnd(),
	    second_parameter_curve->PointAtStart());
	first_connector.ChangeDimension(2);
	second_connector.ChangeDimension(2);
	const double connector_direct =
	    parameter_curve_pair_lift_maximum_error(first_surface,
		&first_connector, second_surface, &second_connector, false);
	const double connector_reverse =
	    parameter_curve_pair_lift_maximum_error(first_surface,
		&first_connector, second_surface, &second_connector, true);
	bu_log("Boolean closed SSI paired-model repair has open lifts with "
	    "endpoint distances %.17g/%.17g and connector pair errors "
	    "%.17g/%.17g at tolerance %.17g.\n",
	    first_lifted->PointAtStart().DistanceTo(first_lifted->PointAtEnd()),
	    second_lifted->PointAtStart().DistanceTo(second_lifted->PointAtEnd()),
	    connector_direct, connector_reverse, tolerance);
    }
    if (first_closed != second_closed) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean closed SSI paired-model repair found incompatible "
		"lift closure with endpoint distances %.17g/%.17g at "
		"tolerance %.17g.\n",
		first_lifted->PointAtStart().DistanceTo(first_lifted->PointAtEnd()),
		second_lifted->PointAtStart().DistanceTo(second_lifted->PointAtEnd()),
		tolerance);
	}
	return false;
    }

    bool pair_reversed = reverse_error < direct_error;
    const bool pair_coincident = first_closed ?
	closed_curve_loci_coincident(*first_lifted, *second_lifted,
	    tolerance) :
	brep_curves_coincident(*first_lifted, *second_lifted, tolerance,
	    &pair_reversed);
    if (!pair_coincident)
    {
	if (DEBUG_BREP_BOOLEAN)
	    bu_log("Boolean closed SSI paired-model repair rejected sampled lift loci at tolerance %.17g.\n",
		tolerance);
	return false;
    }

    if (pair_reversed &&
	(!second_parameter_curve->Reverse() || !second_lifted->Reverse()))
    {
	return false;
    }

    const ON_Interval model_domain = model_curve->Domain();
    if (!model_domain.IsIncreasing() ||
	!first_lifted->SetDomain(model_domain.Min(), model_domain.Max()))
    {
	return false;
    }
    delete model_curve;
    model_curve = first_lifted.release();
    return true;
}


static bool
parameter_curve_covers_trimmed_face(
    ON_Curve *parameter_curve,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &face_loops,
    const ON_Surface *surface,
    double &point_tolerance)
{
    point_tolerance = INTERSECTION_TOL;
    double parameter_tolerance = INTERSECTION_TOL;
    if (parameter_curve == NULL || surface == NULL ||
	parameter_curve->Dimension() != 2 || !parameter_curve->IsValid() ||
	!get_face_boundary_curve_tolerances(surface, parameter_curve,
	    point_tolerance, parameter_tolerance))
    {
	return false;
    }

    const ON_SimpleArray<ON_Interval> included =
	get_curve_intervals_inside_or_on_face(parameter_curve, face_loops,
	    surface, point_tolerance);
    return curve_intervals_cover_domain(included,
	parameter_curve->Domain(), parameter_tolerance);
}


static std::unique_ptr<ON_Curve>
complete_parameter_curve_with_endpoint_connector(const ON_Curve &curve)
{
    if (curve.Dimension() != 2 || !curve.IsValid() || curve.IsClosed() ||
	!curve.Domain().IsIncreasing())
    {
	return std::unique_ptr<ON_Curve>();
    }

    const ON_3dPoint start = curve.PointAtStart();
    const ON_3dPoint end = curve.PointAtEnd();
    if (!start.IsValid() || !end.IsValid() ||
	start.DistanceTo(end) <= ON_ZERO_TOLERANCE)
    {
	return std::unique_ptr<ON_Curve>();
    }

    std::unique_ptr<ON_PolyCurve> completed(new ON_PolyCurve());
    ON_Curve *core = curve.DuplicateCurve();
    if (core == NULL ||
	!append_boolean_loop_curve_to_polycurve(core, *completed))
    {
	return std::unique_ptr<ON_Curve>();
    }

    ON_LineCurve *connector = new ON_LineCurve(end, start);
    if (!connector->ChangeDimension(2) || !connector->IsValid()) {
	delete connector;
	return std::unique_ptr<ON_Curve>();
    }
    if (!append_boolean_loop_curve_to_polycurve(connector, *completed))
	return std::unique_ptr<ON_Curve>();
    if (!completed->IsValid() || !completed->IsClosed() ||
	!completed->Domain().IsIncreasing())
    {
	return std::unique_ptr<ON_Curve>();
    }
    return std::unique_ptr<ON_Curve>(completed.release());
}


static std::unique_ptr<ON_Curve>
complete_model_curve_with_connector(const ON_Curve &core,
    const ON_Curve &connector, double tolerance)
{
    if (core.Dimension() != 3 || connector.Dimension() != 3 ||
	!core.IsValid() || !connector.IsValid() || core.IsClosed() ||
	connector.IsClosed() || !(tolerance > 0.0))
    {
	return std::unique_ptr<ON_Curve>();
    }

    std::unique_ptr<ON_Curve> core_copy(core.DuplicateCurve());
    std::unique_ptr<ON_Curve> connector_copy(connector.DuplicateCurve());
    if (!core_copy || !connector_copy ||
	core_copy->PointAtEnd().DistanceTo(connector_copy->PointAtStart()) >
	    tolerance ||
	connector_copy->PointAtEnd().DistanceTo(core_copy->PointAtStart()) >
	    tolerance ||
	!connector_copy->SetStartPoint(core_copy->PointAtEnd()) ||
	!connector_copy->SetEndPoint(core_copy->PointAtStart()))
    {
	return std::unique_ptr<ON_Curve>();
    }

    std::unique_ptr<ON_PolyCurve> completed(new ON_PolyCurve());
    if (!append_boolean_loop_curve_to_polycurve(core_copy.release(),
	    *completed) ||
	!append_boolean_loop_curve_to_polycurve(connector_copy.release(),
	    *completed) || !completed->IsValid() || !completed->IsClosed() ||
	!completed->Domain().IsIncreasing())
    {
	return std::unique_ptr<ON_Curve>();
    }
    return std::unique_ptr<ON_Curve>(completed.release());
}


static bool
split_completed_curve_at_final_connector(const ON_Curve &curve,
    std::unique_ptr<ON_Curve> &core,
    std::unique_ptr<ON_Curve> &connector)
{
    const ON_PolyCurve *polycurve = ON_PolyCurve::Cast(&curve);
    if (polycurve == NULL || polycurve->Count() < 2 || !curve.IsClosed())
	return false;

    const int connector_index = polycurve->Count() - 1;
    const ON_Curve *connector_segment =
	polycurve->SegmentCurve(connector_index);
    if (connector_segment == NULL)
	return false;
    connector.reset(connector_segment->DuplicateCurve());

    if (connector_index == 1) {
	const ON_Curve *core_segment = polycurve->SegmentCurve(0);
	if (core_segment != NULL)
	    core.reset(core_segment->DuplicateCurve());
    } else {
	std::unique_ptr<ON_PolyCurve> core_polycurve(new ON_PolyCurve());
	for (int segment_index = 0; segment_index < connector_index;
	     ++segment_index)
	{
	    const ON_Curve *segment = polycurve->SegmentCurve(segment_index);
	    if (segment == NULL ||
		!append_boolean_loop_curve_to_polycurve(segment->DuplicateCurve(),
		    *core_polycurve))
	    {
		return false;
	    }
	}
	core.reset(core_polycurve.release());
    }

    return core && connector && core->IsValid() && connector->IsValid() &&
	!core->IsClosed() && !connector->IsClosed() &&
	core->Domain().IsIncreasing() && connector->Domain().IsIncreasing() &&
	core->PointAtEnd().DistanceTo(connector->PointAtStart()) <=
	    INTERSECTION_TOL &&
	connector->PointAtEnd().DistanceTo(core->PointAtStart()) <=
	    INTERSECTION_TOL;
}


/* Some closed surface intersections arrive with two mutually consistent open
 * parameter traces.  Replacing the closed model event with either open lift
 * loses the small final interval and leaves a topological hole.  Complete the
 * traces before face clipping only when their original loci agree at the SSI
 * tolerance, both straight UV connectors remain in their trimmed faces, and
 * the connector lifts disagree by less than a deliberately sub-modeling-
 * tolerance bound.  The resulting edge tolerance records that disagreement. */
static bool
complete_closed_ssi_parameter_pair(
    const ON_Surface *first_surface,
    const ON_Surface *second_surface,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &first_loops,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &second_loops,
    ON_SSX_EVENT *event,
    double &maximum_perturbation)
{
    maximum_perturbation = 0.0;
    if (first_surface == NULL || second_surface == NULL || event == NULL ||
	event->m_curve3d == NULL || event->m_curveA == NULL ||
	event->m_curveB == NULL || !event->m_curve3d->IsClosed() ||
	event->m_curveA->IsClosed() || event->m_curveB->IsClosed() ||
	event->m_curveA->Dimension() != 2 ||
	event->m_curveB->Dimension() != 2)
    {
	return false;
    }

    const auto rejected = [event](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean closed SSI pre-clipping completion rejected: %s "
		"(parameter endpoint distances %.17g/%.17g).\n", reason,
		event->m_curveA->PointAtStart().DistanceTo(
		    event->m_curveA->PointAtEnd()),
		event->m_curveB->PointAtStart().DistanceTo(
		    event->m_curveB->PointAtEnd()));
	}
	return false;
    };

    double first_point_tolerance = INTERSECTION_TOL;
    double second_point_tolerance = INTERSECTION_TOL;
    if (!parameter_curve_covers_trimmed_face(event->m_curveA, first_loops,
	    first_surface, first_point_tolerance) ||
	!parameter_curve_covers_trimmed_face(event->m_curveB, second_loops,
	    second_surface, second_point_tolerance))
    {
	return rejected("an original parameter trace leaves its trimmed face");
    }

    std::unique_ptr<ON_Curve> first_lifted(pushup_boolean_trim_curve(
	first_surface, *event->m_curveA));
    std::unique_ptr<ON_Curve> second_lifted(pushup_boolean_trim_curve(
	second_surface, *event->m_curveB));
    if (!first_lifted || !second_lifted || !first_lifted->IsValid() ||
	!second_lifted->IsValid() || first_lifted->IsClosed() ||
	second_lifted->IsClosed())
    {
	return rejected("an original parameter trace has no valid open lift");
    }
    const double direct_error = parameter_curve_pair_lift_maximum_error(
	first_surface, event->m_curveA, second_surface, event->m_curveB, false);
    const double reverse_error = parameter_curve_pair_lift_maximum_error(
	first_surface, event->m_curveA, second_surface, event->m_curveB, true);
    const bool reverse_second = reverse_error < direct_error;
    bool pair_reversed = false;
    if (std::min(direct_error, reverse_error) > INTERSECTION_TOL ||
	!brep_curves_coincident(*first_lifted, *second_lifted,
	    INTERSECTION_TOL, &pair_reversed) ||
	pair_reversed != reverse_second)
    {
	return rejected("the original parameter traces are not a matched SSI pair");
    }

    std::unique_ptr<ON_Curve> first_core(event->m_curveA->DuplicateCurve());
    std::unique_ptr<ON_Curve> second_core(event->m_curveB->DuplicateCurve());
    if (!first_core || !second_core ||
	(reverse_second &&
	    (!second_core->Reverse() || !second_lifted->Reverse())))
    {
	return rejected("the oriented parameter traces could not be copied");
    }

    ON_LineCurve first_connector(first_core->PointAtEnd(),
	first_core->PointAtStart());
    ON_LineCurve second_connector(second_core->PointAtEnd(),
	second_core->PointAtStart());
    if (!first_connector.ChangeDimension(2) ||
	!second_connector.ChangeDimension(2) || !first_connector.IsValid() ||
	!second_connector.IsValid())
    {
	return rejected("an endpoint connector is invalid");
    }
    const double connector_error = parameter_curve_pair_lift_maximum_error(
	first_surface, &first_connector, second_surface, &second_connector,
	false);
    if (!std::isfinite(connector_error) ||
	connector_error > BOOLEAN_SSI_COMPLETION_TOLERANCE)
    {
	return rejected("the endpoint connectors exceed the completion tolerance");
    }

    double first_connector_point_tolerance = INTERSECTION_TOL;
    double second_connector_point_tolerance = INTERSECTION_TOL;
    if (!parameter_curve_covers_trimmed_face(&first_connector, first_loops,
	    first_surface, first_connector_point_tolerance) ||
	!parameter_curve_covers_trimmed_face(&second_connector, second_loops,
	    second_surface, second_connector_point_tolerance))
    {
	return rejected("an endpoint connector leaves its trimmed face");
    }

    std::unique_ptr<ON_Curve> first_connector_lift(
	pushup_boolean_trim_curve(first_surface, first_connector));
    std::unique_ptr<ON_Curve> second_connector_lift(
	pushup_boolean_trim_curve(second_surface, second_connector));
    if (!first_connector_lift || !second_connector_lift ||
	!first_connector_lift->IsValid() ||
	!second_connector_lift->IsValid())
    {
	return rejected("an endpoint connector has no valid model-space lift");
    }

    std::unique_ptr<ON_Curve> completed_first(
	complete_parameter_curve_with_endpoint_connector(*first_core));
    std::unique_ptr<ON_Curve> completed_second(
	complete_parameter_curve_with_endpoint_connector(*second_core));
    if (!completed_first || !completed_second)
	return rejected("the completed parameter curves are invalid");

    double completed_first_point_tolerance = INTERSECTION_TOL;
    double completed_second_point_tolerance = INTERSECTION_TOL;
    if (!parameter_curve_covers_trimmed_face(completed_first.get(),
	    first_loops, first_surface, completed_first_point_tolerance) ||
	!parameter_curve_covers_trimmed_face(completed_second.get(),
	    second_loops, second_surface, completed_second_point_tolerance))
    {
	return rejected("a completed parameter curve leaves its trimmed face");
    }

    ON_Curve *first = completed_first.release();
    ON_Curve *second = completed_second.release();
    std::unique_ptr<ON_Curve> first_completed_lift(
	complete_model_curve_with_connector(*first_lifted,
	    *first_connector_lift, INTERSECTION_TOL));
    std::unique_ptr<ON_Curve> second_completed_lift(
	complete_model_curve_with_connector(*second_lifted,
	    *second_connector_lift, INTERSECTION_TOL));
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean closed SSI completed lift diagnostics: core/connector "
	    "gaps %.17g %.17g / %.17g %.17g, completed valid/closed/resolved "
	    "%d/%d/%d and %d/%d/%d, loci %d.\n",
	    first_lifted->PointAtEnd().DistanceTo(
		first_connector_lift->PointAtStart()),
	    first_connector_lift->PointAtEnd().DistanceTo(
		first_lifted->PointAtStart()),
	    second_lifted->PointAtEnd().DistanceTo(
		second_connector_lift->PointAtStart()),
	    second_connector_lift->PointAtEnd().DistanceTo(
		second_lifted->PointAtStart()),
	    first_completed_lift && first_completed_lift->IsValid(),
	    first_completed_lift && first_completed_lift->IsClosed(),
	    first_completed_lift && closed_curve_has_resolved_area(
		*first_completed_lift, INTERSECTION_TOL),
	    second_completed_lift && second_completed_lift->IsValid(),
	    second_completed_lift && second_completed_lift->IsClosed(),
	    second_completed_lift && closed_curve_has_resolved_area(
		*second_completed_lift, INTERSECTION_TOL),
	    first_completed_lift && second_completed_lift &&
		closed_curve_loci_coincident(*first_completed_lift,
		    *second_completed_lift,
		    BOOLEAN_SSI_COMPLETION_TOLERANCE));
    }
    if (!first_completed_lift || !second_completed_lift ||
	!first_completed_lift->IsValid() ||
	!second_completed_lift->IsValid() ||
	!first_completed_lift->IsClosed() ||
	!second_completed_lift->IsClosed() ||
	!closed_curve_has_resolved_area(*first_completed_lift,
	    INTERSECTION_TOL) ||
	!closed_curve_has_resolved_area(*second_completed_lift,
	    INTERSECTION_TOL))
    {
	delete first;
	delete second;
	return rejected("the completed parameter pair has no valid closed model curve");
    }

    const ON_Interval model_domain = event->m_curve3d->Domain();
    if (!model_domain.IsIncreasing() ||
	!first_completed_lift->SetDomain(model_domain.Min(), model_domain.Max()))
    {
	delete first;
	delete second;
	return rejected("the completed model curve domain could not be preserved");
    }
    ON_Curve *model = first_completed_lift.release();

    delete event->m_curve3d;
    delete event->m_curveA;
    delete event->m_curveB;
    event->m_curve3d = model;
    event->m_curveA = first;
    event->m_curveB = second;
    maximum_perturbation = connector_error;
    bu_log("Completed a defective closed SSI with a bounded parameter-space "
	"connector (maximum paired lift deviation %.17g, limit %.17g).\n",
	maximum_perturbation, BOOLEAN_SSI_COMPLETION_TOLERANCE);
    return true;
}


static bool
parameter_curve_endpoint_is_on_face_boundary(
    const ON_Curve &parameter_curve,
    bool end,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &face_loops,
    double point_tolerance)
{
    const ON_3dPoint point = end ? parameter_curve.PointAtEnd() :
	parameter_curve.PointAtStart();
    if (!point.IsValid())
	return false;

    try {
	for (int loop_index = 0; loop_index < face_loops.Count(); ++loop_index) {
	    if (is_point_on_loop(ON_2dPoint(point.x, point.y),
		    face_loops[loop_index], point_tolerance))
	    {
		return true;
	    }
	}
    } catch (InvalidGeometry &) {
	return false;
    }
    return false;
}


struct BooleanFaceBoundedOpenSSICandidate {
    std::unique_ptr<ON_Curve> m_model_curve;
    std::unique_ptr<ON_Curve> m_first_parameter_curve;
    std::unique_ptr<ON_Curve> m_second_parameter_curve;
};


/* A defective SSI event can pair the complete closed intersection of two
 * untrimmed surfaces with an open parameter curve that already describes the
 * portion bounded by one input face.  The ordinary closed-event path must
 * reject that inconsistent triplet, but discarding the valid open branch can
 * remove an entire result side face.  Recover only when one open parameter
 * curve independently lifts onto both surfaces, stays inside both trimmed
 * faces, and terminates on the boundary of at least one face at each end.
 * The other parameter curve is regenerated from that certified NURBS locus;
 * no polygonal Boolean geometry is used. */
static bool
build_face_bounded_open_ssi_candidate(
    bool source_is_first,
    const ON_Surface *first_surface,
    const ON_Surface *second_surface,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &first_loops,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &second_loops,
    const ON_Curve *first_parameter_curve,
    const ON_Curve *second_parameter_curve,
    double tolerance,
    BooleanFaceBoundedOpenSSICandidate &candidate)
{
    const auto rejected = [source_is_first](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean face-bounded open SSI candidate from side %d "
		"rejected: %s.\n", source_is_first ? 0 : 1, reason);
	}
	return false;
    };
    const ON_Surface *source_surface = source_is_first ? first_surface :
	second_surface;
    const ON_Surface *target_surface = source_is_first ? second_surface :
	first_surface;
    const ON_Curve *source_parameter_curve = source_is_first ?
	first_parameter_curve : second_parameter_curve;
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &source_loops =
	source_is_first ? first_loops : second_loops;
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &target_loops =
	source_is_first ? second_loops : first_loops;
    if (source_surface == NULL || target_surface == NULL ||
	source_parameter_curve == NULL || source_parameter_curve->IsClosed() ||
	!(tolerance > 0.0) || !std::isfinite(tolerance))
    {
	return rejected("the source parameter curve is not a valid open candidate");
    }

    double source_point_tolerance = INTERSECTION_TOL;
    if (!parameter_curve_covers_trimmed_face(
	    const_cast<ON_Curve *>(source_parameter_curve), source_loops,
	    source_surface, source_point_tolerance))
    {
	return rejected("the source parameter curve is not fully inside its face");
    }

    std::unique_ptr<ON_Curve> model_curve(pushup_boolean_trim_curve(
	source_surface, *source_parameter_curve));
    if (!model_curve || model_curve->Dimension() != 3 ||
	!model_curve->IsValid() || model_curve->IsClosed() ||
	!model_curve->Domain().IsIncreasing())
    {
	return rejected("the source parameter curve does not have a valid open lift");
    }
    const ON_3dPoint model_start = model_curve->PointAtStart();
    const ON_3dPoint model_end = model_curve->PointAtEnd();
    const ON_BoundingBox model_bounds = model_curve->BoundingBox();
    if (!model_start.IsValid() || !model_end.IsValid() ||
	!model_bounds.IsValid() || model_start.DistanceTo(model_end) <= tolerance ||
	model_bounds.Diagonal().Length() <= tolerance)
    {
	return rejected("the lifted candidate is unresolved at model tolerance");
    }

    std::string failure_reason;
    PullbackFailureReason failure = PullbackFailureReason::None;
    std::unique_ptr<ON_Curve> target_parameter_curve(
	brlcad::pullback_curve(target_surface, model_curve.get(), tolerance,
	    std::max(INTERSECTION_TOL, 0.25 * tolerance), &failure_reason,
	    &failure));
    if (!target_parameter_curve || target_parameter_curve->Dimension() != 2 ||
	!target_parameter_curve->IsValid())
    {
	record_boolean_projection_failure();
	return rejected("the lifted candidate cannot be pulled back to the other surface");
    }

    std::unique_ptr<ON_Curve> source_copy(
	source_parameter_curve->DuplicateCurve());
    int source_orientation = -1;
    int target_orientation = -1;
    if (!source_copy ||
	!parameter_curve_lifts_to_model_curve(source_surface,
	    source_copy.get(), model_curve.get(), tolerance,
	    &source_orientation) ||
	!parameter_curve_lifts_to_model_curve(target_surface,
	    target_parameter_curve.get(), model_curve.get(), tolerance,
	    &target_orientation))
    {
	return rejected("the repaired parameter curves do not lift to the candidate");
    }
    if (source_orientation != target_orientation) {
	if (!target_parameter_curve->Reverse() ||
	    !parameter_curve_lifts_to_model_curve(target_surface,
		target_parameter_curve.get(), model_curve.get(), tolerance,
		&target_orientation) || source_orientation != target_orientation)
	{
	    return rejected("the repaired parameter curves have incompatible orientations");
	}
    }
    std::unique_ptr<ON_Curve> target_lifted(pushup_boolean_trim_curve(
	target_surface, *target_parameter_curve));
    bool pair_reversed = false;
    if (!target_lifted || !target_lifted->IsValid() ||
	!brep_curves_coincident(*model_curve, *target_lifted, tolerance,
	    &pair_reversed) || pair_reversed)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const double paired_lift_error =
		parameter_curve_pair_lift_maximum_error(source_surface,
		    source_copy.get(), target_surface,
		    target_parameter_curve.get(), false);
	    bu_log("Boolean face-bounded open SSI candidate from side %d has "
		"paired lift error %.17g at tolerance %.17g; model %.17g "
		"%.17g %.17g -> %.17g %.17g %.17g.\n",
		source_is_first ? 0 : 1, paired_lift_error, tolerance,
		model_start.x, model_start.y, model_start.z, model_end.x,
		model_end.y, model_end.z);
	}
	return rejected("the repaired parameter-curve lifts do not coincide");
    }

    double target_point_tolerance = INTERSECTION_TOL;
    if (!parameter_curve_covers_trimmed_face(target_parameter_curve.get(),
	    target_loops, target_surface, target_point_tolerance))
    {
	return rejected("the repaired parameter curve is not fully inside the other face");
    }
    for (bool end : {false, true}) {
	if (!parameter_curve_endpoint_is_on_face_boundary(*source_copy, end,
		source_loops, source_point_tolerance) &&
	    !parameter_curve_endpoint_is_on_face_boundary(
		*target_parameter_curve, end, target_loops,
		target_point_tolerance))
	{
	    return rejected("a candidate endpoint is not on either face boundary");
	}
    }

    candidate.m_model_curve = std::move(model_curve);
    if (source_is_first) {
	candidate.m_first_parameter_curve = std::move(source_copy);
	candidate.m_second_parameter_curve = std::move(target_parameter_curve);
    } else {
	candidate.m_first_parameter_curve = std::move(target_parameter_curve);
	candidate.m_second_parameter_curve = std::move(source_copy);
    }
    return true;
}


static bool
repair_mismatched_closed_ssi_as_face_bounded_open_curve(
    const ON_Surface *first_surface,
    const ON_Surface *second_surface,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &first_loops,
    const ON_ClassArray<ON_SimpleArray<ON_Curve *> > &second_loops,
    ON_Curve *&first_parameter_curve,
    ON_Curve *&second_parameter_curve,
    ON_Curve *&model_curve,
    double tolerance)
{
    if (model_curve == NULL || !model_curve->IsClosed())
	return false;

    BooleanFaceBoundedOpenSSICandidate first_candidate;
    BooleanFaceBoundedOpenSSICandidate second_candidate;
    const bool first_valid = build_face_bounded_open_ssi_candidate(true,
	first_surface, second_surface, first_loops, second_loops,
	first_parameter_curve, second_parameter_curve, tolerance,
	first_candidate);
    const bool second_valid = build_face_bounded_open_ssi_candidate(false,
	first_surface, second_surface, first_loops, second_loops,
	first_parameter_curve, second_parameter_curve, tolerance,
	second_candidate);
    if (!first_valid && !second_valid)
	return false;

    BooleanFaceBoundedOpenSSICandidate *selected = first_valid ?
	&first_candidate : &second_candidate;
    if (first_valid && second_valid) {
	bool reversed = false;
	if (!brep_curves_coincident(*first_candidate.m_model_curve,
		*second_candidate.m_model_curve, tolerance, &reversed))
	{
	    return false;
	}
    }

    delete model_curve;
    delete first_parameter_curve;
    delete second_parameter_curve;
    model_curve = selected->m_model_curve.release();
    first_parameter_curve = selected->m_first_parameter_curve.release();
    second_parameter_curve = selected->m_second_parameter_curve.release();
    bu_log("Recovered a face-bounded open SSI from a mismatched closed "
	"event at model tolerance %.17g.\n", tolerance);
    return true;
}


static void
get_subcurves_inside_faces(
    ON_SimpleArray<ON_Curve *> &subcurves_3d,
    ON_SimpleArray<ON_Curve *> &subcurves_on1,
    ON_SimpleArray<ON_Curve *> &subcurves_on2,
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    int face_i1,
    int face_i2,
    ON_SSX_EVENT *event,
    bool &curve_covers_face1,
    bool &curve_covers_face2)
{
    // The ON_SSX_EVENT from SSI is the intersection of two whole surfaces.
    // We need to get the part that lies inside both trimmed patches.
    // (brep1's face[face_i1] and brep2's face[face_i2])
    curve_covers_face1 = false;
    curve_covers_face2 = false;
    if (event == NULL) {
	return;
    }

    if (event->m_curve3d == NULL || event->m_curveA == NULL || event->m_curveB == NULL) {
	return;
    }

    ON_ClassArray<ON_SimpleArray<ON_Curve *> > face1_loops;
    if (!face_trim_loops(brep1, face_i1, face1_loops)) {
	bu_log("get_subcurves_inside_faces(): invalid face_i1 (%d).\n", face_i1);
	return;
    }

    ON_ClassArray<ON_SimpleArray<ON_Curve *> > face2_loops;
    if (!face_trim_loops(brep2, face_i2, face2_loops)) {
	bu_log("get_subcurves_inside_faces(): invalid face_i2 (%d).\n", face_i2);
	return;
    }

    double completed_ssi_perturbation = 0.0;
    const bool completed_closed_parameter_pair =
	complete_closed_ssi_parameter_pair(
	    brep1->m_F[face_i1].SurfaceOf(),
	    brep2->m_F[face_i2].SurfaceOf(), face1_loops, face2_loops,
	    event, completed_ssi_perturbation);

    /* Curve clipping happens in each face's parameter space.  A model-space
     * tolerance used directly as a UV tolerance can be enormous on a
     * large, normalized surface: for example, an offset spheroid/plane
     * intersection can then lose a short but kilometer-scale end interval.
     * Convert the Boolean tolerance through each surface metric before
     * intersecting or classifying the parameter curves. */
    double first_point_tolerance = INTERSECTION_TOL;
    double first_curve_parameter_tolerance = INTERSECTION_TOL;
    double second_point_tolerance = INTERSECTION_TOL;
    double second_curve_parameter_tolerance = INTERSECTION_TOL;
    get_face_boundary_curve_tolerances(
	brep1->m_F[face_i1].SurfaceOf(), event->m_curveA,
	first_point_tolerance, first_curve_parameter_tolerance);
    get_face_boundary_curve_tolerances(
	brep2->m_F[face_i2].SurfaceOf(), event->m_curveB,
	second_point_tolerance, second_curve_parameter_tolerance);

    // find the intervals of the curves that are inside/on each face
    ON_SimpleArray<ON_Interval> intervals1, intervals2;

    intervals1 = get_curve_intervals_inside_or_on_face(event->m_curveA,
	face1_loops, brep1->m_F[face_i1].SurfaceOf(),
	first_point_tolerance);

    intervals2 = get_curve_intervals_inside_or_on_face(event->m_curveB,
	face2_loops, brep2->m_F[face_i2].SurfaceOf(),
	second_point_tolerance);

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean SSI clipping faces %d/%d.\n", face_i1, face_i2);
	debug_boolean_curve("model curve", event->m_curve3d);
	debug_boolean_curve("first parameter curve", event->m_curveA);
	debug_boolean_curve("second parameter curve", event->m_curveB);
	bu_log("Boolean SSI raw lift maximum errors direct/reverse %.17g/%.17g "
	    "and %.17g/%.17g.\n", parameter_curve_lift_maximum_error(
		brep1->m_F[face_i1].SurfaceOf(), event->m_curveA,
		event->m_curve3d, false), parameter_curve_lift_maximum_error(
		brep1->m_F[face_i1].SurfaceOf(), event->m_curveA,
		event->m_curve3d, true), parameter_curve_lift_maximum_error(
		brep2->m_F[face_i2].SurfaceOf(), event->m_curveB,
		event->m_curve3d, false), parameter_curve_lift_maximum_error(
		brep2->m_F[face_i2].SurfaceOf(), event->m_curveB,
		event->m_curve3d, true));
	bu_log("Boolean SSI parameter-pair lift maximum errors direct/reverse "
	    "%.17g/%.17g.\n", parameter_curve_pair_lift_maximum_error(
		brep1->m_F[face_i1].SurfaceOf(), event->m_curveA,
		brep2->m_F[face_i2].SurfaceOf(), event->m_curveB, false),
	    parameter_curve_pair_lift_maximum_error(
		brep1->m_F[face_i1].SurfaceOf(), event->m_curveA,
		brep2->m_F[face_i2].SurfaceOf(), event->m_curveB, true));
	debug_boolean_intervals("first raw inclusion", intervals1);
	debug_boolean_intervals("second raw inclusion", intervals2);
	if (event->m_curve3d->IsClosed() &&
	    !event->m_curveA->IsClosed() && !event->m_curveB->IsClosed())
	{
	    ON_LineCurve first_connector(event->m_curveA->PointAtEnd(),
		event->m_curveA->PointAtStart());
	    ON_LineCurve second_connector(event->m_curveB->PointAtEnd(),
		event->m_curveB->PointAtStart());
	    first_connector.ChangeDimension(2);
	    second_connector.ChangeDimension(2);
	    ON_SimpleArray<ON_Interval> first_connector_intervals =
		get_curve_intervals_inside_or_on_face(&first_connector,
		    face1_loops, brep1->m_F[face_i1].SurfaceOf(),
		    first_point_tolerance);
	    ON_SimpleArray<ON_Interval> second_connector_intervals =
		get_curve_intervals_inside_or_on_face(&second_connector,
		    face2_loops, brep2->m_F[face_i2].SurfaceOf(),
		    second_point_tolerance);
	    bu_log("Boolean closed SSI endpoint connectors cover faces %d/%d: "
		"%d/%d.\n", face_i1, face_i2,
		curve_intervals_cover_domain(first_connector_intervals,
		    first_connector.Domain(), first_curve_parameter_tolerance),
		curve_intervals_cover_domain(second_connector_intervals,
		    second_connector.Domain(), second_curve_parameter_tolerance));
	}
    }

    curve_covers_face1 = curve_intervals_cover_domain(intervals1,
	event->m_curveA->Domain(), first_curve_parameter_tolerance);
    curve_covers_face2 = curve_intervals_cover_domain(intervals2,
	event->m_curveB->Domain(), second_curve_parameter_tolerance);

    /* Keep the certified completion as two open SSI segments.  The ordinary
     * loop linker can then join the original trace and its connector on both
     * result faces.  Sending the same geometry through the one-edge closed SSI
     * path would require each split face to retain an independently closed
     * edge, which is not the topology represented by this repaired event. */
    if (completed_closed_parameter_pair && curve_covers_face1 &&
	curve_covers_face2)
    {
	std::unique_ptr<ON_Curve> model_core;
	std::unique_ptr<ON_Curve> model_connector;
	std::unique_ptr<ON_Curve> first_core;
	std::unique_ptr<ON_Curve> first_connector;
	std::unique_ptr<ON_Curve> second_core;
	std::unique_ptr<ON_Curve> second_connector;
	if (split_completed_curve_at_final_connector(*event->m_curve3d,
		model_core, model_connector) &&
	    split_completed_curve_at_final_connector(*event->m_curveA,
		first_core, first_connector) &&
	    split_completed_curve_at_final_connector(*event->m_curveB,
		second_core, second_connector))
	{
	    subcurves_3d.Append(model_core.release());
	    subcurves_on1.Append(first_core.release());
	    subcurves_on2.Append(second_core.release());
	    subcurves_3d.Append(model_connector.release());
	    subcurves_on1.Append(first_connector.release());
	    subcurves_on2.Append(second_connector.release());
	    return;
	}
    }

    /* SSI curves which certify at equal normalized parameters carry a
     * stronger correspondence than can be recovered by independently
     * projecting split points.  Keep that correspondence through clipping;
     * on high-curvature surfaces a closest-point lookup can otherwise choose
     * a numerically nearby but parametrically unrelated branch. */
    const bool first_synchronized =
	parameter_curve_lift_maximum_error(
	    brep1->m_F[face_i1].SurfaceOf(), event->m_curveA,
	    event->m_curve3d, false) <= INTERSECTION_TOL;
    const bool second_synchronized =
	parameter_curve_lift_maximum_error(
	    brep2->m_F[face_i2].SurfaceOf(), event->m_curveB,
	    event->m_curve3d, false) <= INTERSECTION_TOL;

    ON_Interval curve3d_domain = event->m_curve3d->Domain();
    curve3d_domain.MakeIncreasing();
    if (!curve3d_domain.IsIncreasing()) {
	return;
    }
    const double parameter_tolerance = ON_ZERO_TOLERANCE * std::max(1.0,
	fabs(curve3d_domain.Length()));
    const auto append_3d_intervals = [&curve3d_domain, parameter_tolerance](
	const ON_SimpleArray<ON_Interval> &parameter_intervals,
	const ON_Curve *parameter_curve,
	const ON_Curve *curve3d,
	const ON_BrepFace *face,
	bool synchronized,
	std::vector<ON_Interval> &curve_intervals)
	{
	    for (int interval_index = 0;
		 interval_index < parameter_intervals.Count(); ++interval_index)
	    {
		if (synchronized) {
		    ON_Interval mapped_interval;
		    if (map_normalized_interval(
			    parameter_intervals[interval_index],
			    parameter_curve->Domain(), curve3d_domain,
			    mapped_interval) && mapped_interval.IsIncreasing() &&
			mapped_interval.Length() > parameter_tolerance)
		    {
			curve_intervals.push_back(mapped_interval);
			continue;
		    }
		}
		const std::vector<ON_Interval> mapped_intervals =
		    interval_2d_to_3d(parameter_intervals[interval_index],
		    parameter_curve, curve3d, face);
		for (size_t mapped_index = 0;
		     mapped_index < mapped_intervals.size(); ++mapped_index)
		{
		    ON_Interval mapped_interval = mapped_intervals[mapped_index];
		    mapped_interval.MakeIncreasing();
		    if (!mapped_interval.IsIncreasing()) {
			continue;
		    }
		    mapped_interval.Set(std::max(mapped_interval.Min(),
			curve3d_domain.Min()), std::min(mapped_interval.Max(),
			curve3d_domain.Max()));
		    if (mapped_interval.Length() > parameter_tolerance) {
			curve_intervals.push_back(mapped_interval);
		    }
		}
	    }
	};

    std::vector<ON_Interval> curve_intervals1;
    std::vector<ON_Interval> curve_intervals2;
    append_3d_intervals(intervals1, event->m_curveA, event->m_curve3d,
	&brep1->m_F[face_i1], first_synchronized, curve_intervals1);
    append_3d_intervals(intervals2, event->m_curveB, event->m_curve3d,
	&brep2->m_F[face_i2], second_synchronized, curve_intervals2);
    if (DEBUG_BREP_BOOLEAN) {
	debug_boolean_intervals("first mapped inclusion", curve_intervals1);
	debug_boolean_intervals("second mapped inclusion", curve_intervals2);
    }

    std::vector<ON_Interval> common_intervals;
    for (size_t first_index = 0; first_index < curve_intervals1.size();
	 ++first_index)
    {
	for (size_t second_index = 0; second_index < curve_intervals2.size();
	     ++second_index)
	{
	    ON_Interval common_interval(std::max(
		curve_intervals1[first_index].Min(),
		curve_intervals2[second_index].Min()), std::min(
		curve_intervals1[first_index].Max(),
		curve_intervals2[second_index].Max()));
	    if (common_interval.Length() > parameter_tolerance) {
		common_intervals.push_back(common_interval);
	    }
	}
    }
    std::sort(common_intervals.begin(), common_intervals.end(),
	[](const ON_Interval &first, const ON_Interval &second) {
	    return first.Min() < second.Min();
	});

    std::vector<ON_Interval> merged_common_intervals;
    for (size_t interval_index = 0;
	 interval_index < common_intervals.size(); ++interval_index)
    {
	const ON_Interval &common_interval = common_intervals[interval_index];
	if (merged_common_intervals.empty() || common_interval.Min() >
	    merged_common_intervals.back().Max() + parameter_tolerance)
	{
	    merged_common_intervals.push_back(common_interval);
	} else {
	    ON_Interval &last_interval = merged_common_intervals.back();
	    last_interval.Set(last_interval.Min(), std::max(last_interval.Max(),
		common_interval.Max()));
	}
    }
    if (curve_covers_face1 && curve_covers_face2) {
	/* Boundary intersection arithmetic can clip a certified SSI a few
	 * model-space tolerance units short of a face seam.  If both parameter
	 * curves cover their complete domains at their metric-derived parameter
	 * tolerances, retain the complete synchronized triplet. */
	merged_common_intervals.clear();
	merged_common_intervals.push_back(curve3d_domain);
    }
    if (DEBUG_BREP_BOOLEAN) {
	debug_boolean_intervals("merged common inclusion",
	    merged_common_intervals);
    }

    /* SSI returns the model curve and both parameter curves as one matched
     * set.  Independently pulling back an unclipped closed event can choose a
     * different seam on either surface and turn a valid closed split into an
     * open parameter curve.  Only regenerate parameter curves after actual
     * clipping; otherwise retain the original SSI triplet. */
    const bool preserve_full_closed_event = event->m_curve3d->IsClosed() &&
	curve_covers_face1 && curve_covers_face2 &&
	merged_common_intervals.size() == 1 &&
	fabs(merged_common_intervals[0].Min() - curve3d_domain.Min()) <=
	    parameter_tolerance &&
	fabs(merged_common_intervals[0].Max() - curve3d_domain.Max()) <=
	    parameter_tolerance;
    const bool full_synchronized_event =
	first_synchronized && second_synchronized && curve_covers_face1 &&
	curve_covers_face2 && merged_common_intervals.size() == 1 &&
	fabs(merged_common_intervals[0].Min() - curve3d_domain.Min()) <=
	    parameter_tolerance &&
	fabs(merged_common_intervals[0].Max() - curve3d_domain.Max()) <=
	    parameter_tolerance;
    const bool preserve_first_synchronized_curve = full_synchronized_event &&
	open_curve_traverses_periodic_surface_domain(
	    brep1->m_F[face_i1].SurfaceOf(), event->m_curveA);
    const bool preserve_second_synchronized_curve = full_synchronized_event &&
	open_curve_traverses_periodic_surface_domain(
	    brep2->m_F[face_i2].SurfaceOf(), event->m_curveB);
    const bool preserve_full_synchronized_event =
	preserve_first_synchronized_curve || preserve_second_synchronized_curve;

    for (size_t interval_index = 0;
	 interval_index < merged_common_intervals.size(); ++interval_index)
    {
	const ON_Interval &common_interval = merged_common_intervals[interval_index];
	ON_Interval interval_on1;
	ON_Interval interval_on2;
	if (!first_synchronized || !map_normalized_interval(common_interval,
		event->m_curve3d->Domain(), event->m_curveA->Domain(),
		interval_on1))
	{
	    interval_on1 = interval_3d_to_2d(common_interval,
		event->m_curveA, event->m_curve3d, &brep1->m_F[face_i1]);
	}
	if (!second_synchronized || !map_normalized_interval(common_interval,
		event->m_curve3d->Domain(), event->m_curveB->Domain(),
		interval_on2))
	{
	    interval_on2 = interval_3d_to_2d(common_interval,
		event->m_curveB, event->m_curve3d, &brep2->m_F[face_i2]);
	}
	if (!interval_on1.IsValid() || !interval_on2.IsValid()) {
	    continue;
	}

	ON_Curve *subcurve_on1 = NULL;
	ON_Curve *subcurve_on2 = NULL;
	ON_Curve *subcurve_3d = NULL;
	try {
	    if (preserve_full_closed_event) {
		subcurve_3d = event->m_curve3d->DuplicateCurve();
		subcurve_on1 = event->m_curveA->DuplicateCurve();
		subcurve_on2 = event->m_curveB->DuplicateCurve();
	    } else {
		subcurve_3d = preserve_full_synchronized_event ?
		    event->m_curve3d->DuplicateCurve() :
		    sub_curve(event->m_curve3d, common_interval.Min(),
			common_interval.Max());
		subcurve_on1 = preserve_first_synchronized_curve ?
		    event->m_curveA->DuplicateCurve() :
		    sub_curve(event->m_curveA, interval_on1.Min(),
			interval_on1.Max());
		subcurve_on2 = preserve_second_synchronized_curve ?
		    event->m_curveB->DuplicateCurve() :
		    sub_curve(event->m_curveB, interval_on2.Min(),
			interval_on2.Max());
	    }
	} catch (InvalidInterval &e) {
	    bu_log("%s", e.what());
	}
	if (subcurve_3d == NULL || subcurve_on1 == NULL || subcurve_on2 == NULL) {
	    delete subcurve_3d;
	    delete subcurve_on1;
	    delete subcurve_on2;
	    continue;
	}
	if (subcurve_3d->Dimension() != 3 || !subcurve_3d->IsValid() ||
	    !subcurve_3d->Domain().IsIncreasing())
	{
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Rejected an invalid SSI model subcurve for faces %d/%d.\n",
		    face_i1, face_i2);
	    }
	    delete subcurve_3d;
	    delete subcurve_on1;
	    delete subcurve_on2;
	    continue;
	}

	const ON_Surface *first_surface = brep1->m_F[face_i1].SurfaceOf();
	const ON_Surface *second_surface = brep2->m_F[face_i2].SurfaceOf();
	if (preserve_full_synchronized_event) {
	    if (!preserve_first_synchronized_curve) {
		subcurve_on1 = validated_ssi_parameter_subcurve(first_surface,
		    subcurve_on1, subcurve_3d);
	    }
	    if (!preserve_second_synchronized_curve) {
		subcurve_on2 = validated_ssi_parameter_subcurve(second_surface,
		    subcurve_on2, subcurve_3d);
	    }
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Preserved synchronized periodic SSI parameter curves %d/%d.\n",
		    preserve_first_synchronized_curve,
		    preserve_second_synchronized_curve);
	    }
	} else if (!preserve_full_closed_event) {
	    if (DEBUG_BREP_BOOLEAN) {
		const ON_ClassId *first_class = first_surface ?
		    first_surface->ClassId() : NULL;
		const ON_ClassId *second_class = second_surface ?
		    second_surface->ClassId() : NULL;
		std::unique_ptr<ON_Curve> first_lifted(first_surface ?
		    pushup_boolean_curve(first_surface, *subcurve_on1) : NULL);
		std::unique_ptr<ON_Curve> second_lifted(second_surface ?
		    pushup_boolean_curve(second_surface, *subcurve_on2) : NULL);
		bool reversed = false;
		bu_log("Boolean clipped SSI surface classes %s/%s, lifted %d/%d, "
		    "paired coincidence at 1e-4/1e-3/model %d/%d/%d, "
		    "reversed %d.\n",
		    first_class ? first_class->ClassName() : "null",
		    second_class ? second_class->ClassName() : "null",
		    first_lifted ? 1 : 0, second_lifted ? 1 : 0,
		    first_lifted && second_lifted && brep_curves_coincident(
			*first_lifted, *second_lifted, 1.0e-4, &reversed),
		    first_lifted && second_lifted && brep_curves_coincident(
			*first_lifted, *second_lifted, 1.0e-3, &reversed),
		    first_lifted && second_lifted && brep_curves_coincident(
			*first_lifted, *second_lifted,
			boolean_model_repair_tolerance(subcurve_3d->BoundingBox()),
			&reversed), reversed);
	    }
	    bool preserve_paired_parameter_curves = false;
	    if (closed_profile_revolution_cylinder_surface_pair(first_surface,
		    second_surface))
	    {
		const double repair_tolerance = boolean_model_repair_tolerance(
		    subcurve_3d->BoundingBox());
		int first_orientation = -1;
		int second_orientation = -1;
		preserve_paired_parameter_curves =
		    parameter_curve_lifts_to_model_curve(first_surface,
			subcurve_on1, subcurve_3d, repair_tolerance,
			&first_orientation) &&
		    parameter_curve_lifts_to_model_curve(second_surface,
			subcurve_on2, subcurve_3d, repair_tolerance,
			&second_orientation) &&
		    first_orientation == second_orientation;
	    }
	    const bool repaired_paired_model_curve =
		!preserve_paired_parameter_curves &&
		repair_open_ssi_model_subcurve_from_parameter_pair(first_surface,
		    second_surface, subcurve_on1, subcurve_on2, subcurve_3d);
	    if (!preserve_paired_parameter_curves &&
		!repaired_paired_model_curve)
	    {
		subcurve_on1 = validated_ssi_parameter_subcurve(first_surface,
		    subcurve_on1, subcurve_3d);
		subcurve_on2 = validated_ssi_parameter_subcurve(second_surface,
		    subcurve_on2, subcurve_3d);
	    } else if (repaired_paired_model_curve && DEBUG_BREP_BOOLEAN) {
		bu_log("Replaced a defective open SSI model subcurve from its "
		    "certified parameter-curve pair.\n");
	    } else if (DEBUG_BREP_BOOLEAN) {
		bu_log("Preserved paired revolution/cylinder SSI parameter "
		    "curves within model tolerance.\n");
	    }
	} else if (preserve_full_closed_event) {
	    bool first_certified = completed_closed_parameter_pair ||
		parameter_curve_lifts_to_model_curve(
		    brep1->m_F[face_i1].SurfaceOf(), subcurve_on1,
		    subcurve_3d, INTERSECTION_TOL);
	    bool second_certified = completed_closed_parameter_pair ||
		parameter_curve_lifts_to_model_curve(
		    brep2->m_F[face_i2].SurfaceOf(), subcurve_on2,
		    subcurve_3d, INTERSECTION_TOL);
	    if (!first_certified || !second_certified) {
		const ON_BoundingBox model_bounds = subcurve_3d->BoundingBox();
		const double repair_tolerance =
		    boolean_model_repair_tolerance(model_bounds);
		std::unique_ptr<ON_Curve> repaired_on1;
		std::unique_ptr<ON_Curve> repaired_on2;
		if (repair_closed_ssi_model_subcurve_from_parameter_pair(
			brep1->m_F[face_i1].SurfaceOf(),
			brep2->m_F[face_i2].SurfaceOf(), subcurve_on1,
			subcurve_on2, subcurve_3d, repair_tolerance))
		{
		    first_certified = second_certified = true;
		    if (DEBUG_BREP_BOOLEAN) {
			bu_log("Replaced a defective closed SSI model subcurve "
			    "from its certified parameter-curve pair.\n");
		    }
	} else if (repair_closed_ssi_parameter_curves(
			brep1->m_F[face_i1].SurfaceOf(),
			brep2->m_F[face_i2].SurfaceOf(), subcurve_on1,
			subcurve_on2, *subcurve_3d, repair_tolerance,
			repaired_on1, repaired_on2))
		{
		    delete subcurve_on1;
		    delete subcurve_on2;
		    subcurve_on1 = repaired_on1.release();
		    subcurve_on2 = repaired_on2.release();
		    first_certified = second_certified = true;
		} else if (
		    repair_mismatched_closed_ssi_as_face_bounded_open_curve(
			brep1->m_F[face_i1].SurfaceOf(),
			brep2->m_F[face_i2].SurfaceOf(), face1_loops,
			face2_loops, subcurve_on1, subcurve_on2,
			subcurve_3d, repair_tolerance))
		{
		    first_certified = second_certified = true;
		}
	    }
	    if (!first_certified || !second_certified) {
		delete subcurve_on1;
		delete subcurve_on2;
		subcurve_on1 = NULL;
		subcurve_on2 = NULL;
	    } else if (DEBUG_BREP_BOOLEAN) {
		bu_log("Preserved the certified paired parameter curves of an "
		    "unclipped closed SSI event.\n");
	    }
	}
	if (subcurve_on1 == NULL || subcurve_on2 == NULL) {
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Rejected an uncertified SSI subcurve triplet for faces "
		    "%d/%d.\n", face_i1, face_i2);
	    }
	    delete subcurve_3d;
	    delete subcurve_on1;
	    delete subcurve_on2;
	    continue;
	}
	repair_open_ssi_endpoints_to_face_boundaries(first_surface,
	    second_surface, face1_loops, face2_loops, subcurve_3d,
	    subcurve_on1, subcurve_on2);
	if (DEBUG_BREP_BOOLEAN) {
	    debug_boolean_curve("clipped model curve", subcurve_3d);
	    debug_boolean_curve("clipped first parameter curve", subcurve_on1);
	    debug_boolean_curve("clipped second parameter curve", subcurve_on2);
	    const double first_direct_error = parameter_curve_lift_maximum_error(
		brep1->m_F[face_i1].SurfaceOf(), subcurve_on1, subcurve_3d,
		false);
	    const double first_reverse_error = parameter_curve_lift_maximum_error(
		brep1->m_F[face_i1].SurfaceOf(), subcurve_on1, subcurve_3d,
		true);
	    const double second_direct_error = parameter_curve_lift_maximum_error(
		brep2->m_F[face_i2].SurfaceOf(), subcurve_on2, subcurve_3d,
		false);
	    const double second_reverse_error = parameter_curve_lift_maximum_error(
		brep2->m_F[face_i2].SurfaceOf(), subcurve_on2, subcurve_3d,
		true);
	    bu_log("Boolean SSI clipped lift maximum errors direct/reverse "
		"%.17g/%.17g and %.17g/%.17g.\n", first_direct_error,
		first_reverse_error, second_direct_error, second_reverse_error);
	}

	subcurves_3d.Append(subcurve_3d);
	subcurves_on1.Append(subcurve_on1);
	subcurves_on2.Append(subcurve_on2);
    }
    return;
}


static double
bbox_diagonal_length(ON_Curve *curve)
{
    double len = 0.0;
    if (curve) {
	ON_BoundingBox bbox;
	if (curve->GetTightBoundingBox(bbox)) {
	    len = bbox.Diagonal().Length();
	} else {
	    len = curve->PointAtStart().DistanceTo(curve->PointAtEnd());
	}
    }
    return len;
}


static const int FACE_SOURCE_TAG_OFFSET = 1;


static bool
is_full_closed_ssi_event(
    const ON_SSX_EVENT &event,
    bool curve_covers_face1,
    bool curve_covers_face2)
{
    if (event.m_curve3d == NULL || event.m_curveA == NULL ||
	event.m_curveB == NULL || !event.m_curve3d->IsClosed() ||
	bbox_diagonal_length(event.m_curve3d) <= ON_ZERO_TOLERANCE)
    {
	return false;
    }
    return curve_covers_face1 && curve_covers_face2;
}


static bool
closed_curve_orientation_from_shared_ssi(
    const ON_Curve *curve,
    const ON_Curve *shared_curve,
    bool &reversed)
{
    reversed = false;
    if (curve == NULL || shared_curve == NULL || !shared_curve->IsClosed() ||
	!curve->Domain().IsValid() || !shared_curve->Domain().IsValid())
    {
	return false;
    }

    const double model_tolerance = boolean_model_repair_tolerance(
	shared_curve->BoundingBox());
    std::unique_ptr<ON_Curve> closed_curve;
    const ON_Curve *orientation_curve = curve;
    if (!curve->IsClosed()) {
	const ON_3dPoint start = curve->PointAtStart();
	const ON_3dPoint end = curve->PointAtEnd();
	if (!start.IsValid() || !end.IsValid() ||
	    start.DistanceTo(end) > model_tolerance)
	{
	    return false;
	}
	closed_curve.reset(curve->DuplicateCurve());
	if (!closed_curve || !closed_curve->SetEndPoint(start) ||
	    !closed_curve->IsClosed())
	{
	    return false;
	}
	orientation_curve = closed_curve.get();
    }

    const ON_3dPoint curve_start = orientation_curve->PointAtStart();
    const ON_3dPoint curve_end = orientation_curve->PointAtEnd();
    if (!curve_start.IsValid() || !curve_end.IsValid() ||
	curve_start.DistanceTo(curve_end) > INTERSECTION_TOL)
    {
	return false;
    }

    ON_NurbsCurve shared_nurbs;
    if (shared_curve->GetNurbForm(shared_nurbs) <= 0) {
	return false;
    }
    double shared_parameter = shared_nurbs.Domain().Min();
    if (!ON_NurbsCurve_GetClosestPoint(&shared_parameter, &shared_nurbs,
	curve_start)) {
	return false;
    }
    const ON_3dPoint shared_point = shared_nurbs.PointAt(shared_parameter);
    if (!shared_point.IsValid()) {
	return false;
    }

    ON_3dVector curve_tangent = orientation_curve->TangentAt(
	orientation_curve->Domain().Min());
    ON_3dVector shared_tangent = shared_nurbs.TangentAt(shared_parameter);
    if (curve_tangent.Unitize() && shared_tangent.Unitize()) {
	const double tangent_dot = ON_DotProduct(curve_tangent, shared_tangent);
	if (!ON_NearZero(tangent_dot, ON_ZERO_TOLERANCE)) {
	    reversed = tangent_dot < 0.0;
	    return true;
	}
    }

    /* A sampled pushup may be topologically closed by repeating its first
     * point.  The resulting endpoint tangent can be zero even though the
     * curve has a well-defined orientation everywhere else.  Compare
     * tangents at certified interior points before giving up. */
    static const double sample_fractions[] = {
	0.137, 0.317, 0.563, 0.811
    };
    const ON_Interval curve_domain = orientation_curve->Domain();
    for (double fraction : sample_fractions) {
	const double curve_parameter = curve_domain.ParameterAt(fraction);
	const ON_3dPoint curve_point = orientation_curve->PointAt(curve_parameter);
	shared_parameter = shared_nurbs.Domain().ParameterAt(fraction);
	if (!curve_point.IsValid() || !ON_NurbsCurve_GetClosestPoint(
		&shared_parameter, &shared_nurbs, curve_point) ||
	    shared_nurbs.PointAt(shared_parameter).DistanceTo(curve_point) >
		model_tolerance)
	{
	    continue;
	}

	curve_tangent = orientation_curve->TangentAt(curve_parameter);
	shared_tangent = shared_nurbs.TangentAt(shared_parameter);
	if (!curve_tangent.Unitize() || !shared_tangent.Unitize()) {
	    continue;
	}
	const double tangent_dot = ON_DotProduct(curve_tangent, shared_tangent);
	if (!ON_NearZero(tangent_dot, ON_ZERO_TOLERANCE)) {
	    reversed = tangent_dot < 0.0;
	    return true;
	}
    }
    return false;
}


static bool
open_curve_orientation_from_shared_ssi(
    const ON_Curve *curve,
    const ON_Curve *shared_curve,
    bool &reversed,
    double tolerance = INTERSECTION_TOL)
{
    reversed = false;
    if (curve == NULL || shared_curve == NULL || curve->Dimension() != 3 ||
	shared_curve->Dimension() != 3 || curve->IsClosed() ||
	shared_curve->IsClosed() || !curve->Domain().IsIncreasing() ||
	!shared_curve->Domain().IsIncreasing() || !(tolerance > 0.0) ||
	!std::isfinite(tolerance))
    {
	return false;
    }

    const ON_3dPoint curve_start = curve->PointAtStart();
    const ON_3dPoint curve_end = curve->PointAtEnd();
    const ON_3dPoint shared_start = shared_curve->PointAtStart();
    const ON_3dPoint shared_end = shared_curve->PointAtEnd();
    if (!curve_start.IsValid() || !curve_end.IsValid() ||
	!shared_start.IsValid() || !shared_end.IsValid() ||
	curve_start.DistanceTo(curve_end) <= ON_ZERO_TOLERANCE ||
	shared_start.DistanceTo(shared_end) <= ON_ZERO_TOLERANCE)
    {
	return false;
    }

    if (ON_CurvesAreEquivalent(curve, shared_curve, tolerance,
	false))
    {
	return curve_start.DistanceTo(shared_start) <= tolerance &&
	    curve_end.DistanceTo(shared_end) <= tolerance;
    }
    if (!ON_CurvesAreEquivalent(curve, shared_curve, tolerance,
	true) || curve_start.DistanceTo(shared_end) > tolerance ||
	curve_end.DistanceTo(shared_start) > tolerance)
    {
	return false;
    }

    reversed = true;
    return true;
}


static bool
closed_curves_are_equivalent(
    const ON_Curve *curve,
    const ON_Curve *shared_curve,
    double tolerance,
    bool &reversed)
{
    reversed = false;
    if (curve == NULL || shared_curve == NULL || !curve->IsClosed() ||
	!shared_curve->IsClosed() || !(tolerance > 0.0) ||
	!std::isfinite(tolerance))
    {
	return false;
    }

    const ON_Interval curve_domain = curve->Domain();
    const ON_Interval shared_domain = shared_curve->Domain();
    const ON_3dPoint curve_start = curve->PointAtStart();
    const ON_3dPoint shared_start = shared_curve->PointAtStart();
    if (!curve_domain.IsIncreasing() || !shared_domain.IsIncreasing() ||
	!curve_start.IsValid() || !shared_start.IsValid() ||
	curve_start.DistanceTo(shared_start) > tolerance)
    {
	return false;
    }

    ON_3dVector curve_tangent = curve->TangentAt(curve_domain.Min());
    ON_3dVector shared_tangent = shared_curve->TangentAt(shared_domain.Min());
    if (!curve_tangent.Unitize() || !shared_tangent.Unitize()) {
	return false;
    }

    const double tangent_dot = ON_DotProduct(curve_tangent, shared_tangent);
    if (ON_NearZero(tangent_dot, ON_ZERO_TOLERANCE)) {
	return false;
    }
    reversed = tangent_dot < 0.0;

    std::unique_ptr<ON_Curve> first_curve;
    std::unique_ptr<ON_Curve> second_curve;
    std::unique_ptr<ON_Curve> first_shared_curve;
    std::unique_ptr<ON_Curve> second_shared_curve;
    try {
	first_curve.reset(sub_curve(curve, curve_domain.Min(),
	    curve_domain.Mid()));
	second_curve.reset(sub_curve(curve, curve_domain.Mid(),
	    curve_domain.Max()));
	first_shared_curve.reset(sub_curve(shared_curve, shared_domain.Min(),
	    shared_domain.Mid()));
	second_shared_curve.reset(sub_curve(shared_curve, shared_domain.Mid(),
	    shared_domain.Max()));
    } catch (InvalidInterval &) {
	return false;
    }

    if (!first_curve || !second_curve || !first_shared_curve ||
	!second_shared_curve)
    {
	return false;
    }

    if (!reversed) {
	return ON_CurvesAreEquivalent(first_curve.get(),
	    first_shared_curve.get(), tolerance, false) &&
	    ON_CurvesAreEquivalent(second_curve.get(),
	    second_shared_curve.get(), tolerance, false);
    }

    return ON_CurvesAreEquivalent(first_curve.get(),
	second_shared_curve.get(), tolerance, true) &&
	ON_CurvesAreEquivalent(second_curve.get(),
	first_shared_curve.get(), tolerance, true);
}


static bool
curves_match_shared_parameter_curve(
    const ON_Curve *curve,
    const ON_Curve *shared_curve,
    double tolerance)
{
    if (curve == NULL || shared_curve == NULL ||
	curve->Dimension() != shared_curve->Dimension() ||
	!curve->Domain().IsValid() || !shared_curve->Domain().IsValid())
    {
	return false;
    }

    if (curve->IsClosed() != shared_curve->IsClosed()) {
	return false;
    }
    if (curve->IsClosed()) {
	bool reversed = false;
	return closed_curves_are_equivalent(curve, shared_curve, tolerance,
	    reversed);
    }

    return ON_CurvesAreEquivalent(curve, shared_curve, tolerance, false) ||
	ON_CurvesAreEquivalent(curve, shared_curve, tolerance, true);
}


static bool
open_parameter_curve_orientation_from_shared_ssi(
    const ON_Curve *curve,
    const ON_Curve *shared_curve,
    double tolerance,
    bool &reversed)
{
    reversed = false;
    if (curve == NULL || shared_curve == NULL ||
	curve->Dimension() != shared_curve->Dimension() || curve->IsClosed() ||
	shared_curve->IsClosed() || !curve->Domain().IsIncreasing() ||
	!shared_curve->Domain().IsIncreasing() || !(tolerance > 0.0) ||
	!std::isfinite(tolerance))
    {
	return false;
    }

    const ON_3dPoint curve_start = curve->PointAtStart();
    const ON_3dPoint curve_end = curve->PointAtEnd();
    const ON_3dPoint shared_start = shared_curve->PointAtStart();
    const ON_3dPoint shared_end = shared_curve->PointAtEnd();
    if (!curve_start.IsValid() || !curve_end.IsValid() ||
	!shared_start.IsValid() || !shared_end.IsValid())
    {
	return false;
    }

    const bool direct_endpoints = curve_start.DistanceTo(shared_start) <=
	tolerance && curve_end.DistanceTo(shared_end) <= tolerance;
    const bool reversed_endpoints = curve_start.DistanceTo(shared_end) <=
	tolerance && curve_end.DistanceTo(shared_start) <= tolerance;
    if (direct_endpoints && ON_CurvesAreEquivalent(curve, shared_curve,
	    tolerance, false))
    {
	return true;
    }
    if (reversed_endpoints && ON_CurvesAreEquivalent(curve, shared_curve,
	    tolerance, true))
    {
	reversed = true;
	return true;
    }
    return false;
}


static void
split_curve(ON_Curve *&left, ON_Curve *&right, const ON_Curve *in, double t)
{
    try {
	left = sub_curve(in, in->Domain().m_t[0], t);
    } catch (InvalidInterval &) {
	left = NULL;
    }
    try {
	right = sub_curve(in, t, in->Domain().m_t[1]);
    } catch (InvalidInterval &) {
	right = NULL;
    }
}


static double
configure_for_linking(
    LinkedCurve *&first,
    LinkedCurve *&second,
    LinkedCurve &in1,
    LinkedCurve &in2)
{
    double dist_s1s2 = in1.PointAtStart().DistanceTo(in2.PointAtStart());
    double dist_s1e2 = in1.PointAtStart().DistanceTo(in2.PointAtEnd());
    double dist_e1s2 = in1.PointAtEnd().DistanceTo(in2.PointAtStart());
    double dist_e1e2 = in1.PointAtEnd().DistanceTo(in2.PointAtEnd());

    double min_dist = std::min(dist_s1s2, dist_s1e2);
    min_dist = std::min(min_dist, dist_e1s2);
    min_dist = std::min(min_dist, dist_e1e2);

    first = second = NULL;
    if (dist_s1e2 <= min_dist) {
	first = &in2;
	second = &in1;
    } else if (dist_e1s2 <= min_dist) {
	first = &in1;
	second = &in2;
    } else if (dist_s1s2 <= min_dist) {
	if (in1.Reverse()) {
	    first = &in1;
	    second = &in2;
	}
    } else if (dist_e1e2 <= min_dist) {
	if (in2.Reverse()) {
	    first = &in1;
	    second = &in2;
	}
    }
    return min_dist;
}


struct LinkedCurveX {
    int ssi_idx_a;
    int ssi_idx_b;
    ON_SimpleArray<ON_X_EVENT> events;
};


static ON_ClassArray<LinkedCurve>
get_joinable_ssi_curves(const ON_ClassArray<SSICurve> &in)
{
    ON_ClassArray<SSICurve> curves = in;

    for (int i = 0; i < curves.Count(); ++i) {
	if (curves[i].m_curve == NULL || curves[i].m_curve->IsClosed()) {
	    continue;
	}
	for (int j = i + 1; j < curves.Count(); j++) {
	    if (curves[i].m_curve == NULL || curves[i].m_curve->IsClosed()) {
		break;
	    }
	    if (curves[j].m_curve == NULL || curves[j].m_curve->IsClosed()) {
		continue;
	    }
	    ON_Curve *icurve = curves[i].m_curve;
	    ON_Curve *jcurve = curves[j].m_curve;

	    ON_SimpleArray<ON_X_EVENT> events;
	    intersect_boolean_curves(icurve, jcurve, events,
		INTERSECTION_TOL);
	    if (events.Count() != 1) {
		continue;
	    }

	    ON_X_EVENT event = events[0];
	    if (event.m_type == ON_X_EVENT::ccx_overlap) {
		// curves from adjacent surfaces may overlap and have
		// common endpoints, but we don't want the linked
		// curve to double back on itself creating a
		// degenerate section
		ON_Interval dom[2], range[2];
		dom[0] = icurve->Domain();
		dom[1] = jcurve->Domain();
		range[0].Set(event.m_a[0], event.m_a[1]);
		range[1].Set(event.m_b[0], event.m_b[1]);

		// overlap endpoints that are near the endpoints
		// should be snapped to the endpoints
		for (int k = 0; k < 2; ++k) {
		    dom[k].MakeIncreasing();
		    range[k].MakeIncreasing();

		    for (int l = 0; l < 2; ++l) {
			if (ON_NearZero(dom[k].m_t[l] - range[k].m_t[l],
					ON_ZERO_TOLERANCE)) {
			    range[k].m_t[l] = dom[k].m_t[l];
			}
		    }
		}

		if (dom[0].Includes(range[0], true) ||
		    dom[1].Includes(range[1], true))
		{
		    // overlap is in the middle of one or both curves
		    continue;
		}

		// if one curve is completely contained by the other,
		// keep just the larger curve (or the first curve if
		// they're the same)
		if (dom[1] == range[1]) {
		    curves[j].Reset(NULL);
		    continue;
		}
		if (dom[0] == range[0]) {
		    curves[i].Reset(NULL);
		    continue;
		}

		// remove the overlapping portion from the end of one
		// curve so the curves meet at just a single point
		try {
		    double start = dom[0].m_t[0];
		    double end = range[0].m_t[0];
		    if (ON_NearZero(start - end, ON_ZERO_TOLERANCE)) {
			start = range[0].m_t[1];
			end = dom[0].m_t[1];
		    }
		    ON_Curve *isub = sub_curve(icurve, start, end);

		    if (isub) {
			curves[i].Reset(isub);
		    }
		} catch (InvalidInterval &e) {
		    bu_log("%s", e.what());
		}
	    } else {
		/* Curves which already meet at endpoints are ready for the
		 * linking pass below.  Re-splitting them at a numerically nearby
		 * CCX point can trim both curves short of their common endpoint
		 * and manufacture a connector gap.  True overlap events still
		 * take the de-duplication path above. */
		const double endpoint_distance = std::min(
		    std::min(icurve->PointAtStart().DistanceTo(
			    jcurve->PointAtStart()),
			icurve->PointAtStart().DistanceTo(
			    jcurve->PointAtEnd())),
		    std::min(icurve->PointAtEnd().DistanceTo(
			    jcurve->PointAtStart()),
			icurve->PointAtEnd().DistanceTo(
			    jcurve->PointAtEnd())));
		if (endpoint_distance <= INTERSECTION_TOL) {
		    continue;
		}

		// For a single intersection, assume that one or both
		// curve endpoints is just a little past where it
		// should be. Split the curves at the intersection,
		// and discard the portion with the smaller bbox
		// diagonal.
		ON_Curve *ileft, *iright, *jleft, *jright;
		ileft = iright = jleft = jright = NULL;
		split_curve(ileft, iright, icurve, event.m_a[0]);
		split_curve(jleft, jright, jcurve, event.m_b[0]);

		if (bbox_diagonal_length(ileft) <
		    bbox_diagonal_length(iright))
		{
		    std::swap(ileft, iright);
		}
		ON_Curve *isub = ileft;
		delete iright;

		if (bbox_diagonal_length(jleft) <
		    bbox_diagonal_length(jright))
		{
		    std::swap(jleft, jright);
		}
		ON_Curve *jsub = jleft;
		delete jright;

		if (isub && jsub) {
		    // replace the original ssi curves with the
		    // trimmed versions
		    curves[i].Reset(isub);
		    curves[j].Reset(jsub);
		    isub = jsub = NULL;
		}
		delete isub;
		delete jsub;
	    }
	}
    }

    ON_ClassArray<LinkedCurve> out;
    for (int i = 0; i < curves.Count(); ++i) {
	if (curves[i].m_curve != NULL) {
	    LinkedCurve linked;
	    linked.Append(curves[i]);
	    out.Append(linked);
	}
    }
    return out;
}


static double
periodic_parameter_shift(
    const ON_Surface *surface,
    const ON_Curve *curve,
    int direction,
    double parameter_tolerance)
{
    if (surface == NULL || curve == NULL || direction < 0 || direction > 1)
    {
	return 0.0;
    }

    ON_Interval surface_domain = surface->Domain(direction);
    surface_domain.MakeIncreasing();
    const ON_BoundingBox bounds = curve->BoundingBox();
    if (!surface_domain.IsIncreasing() || !bounds.IsValid()) {
	return 0.0;
    }
    const double period = surface_domain.Length();
    const double curve_minimum = direction == 0 ? bounds.m_min.x :
	bounds.m_min.y;
    const double curve_maximum = direction == 0 ? bounds.m_max.x :
	bounds.m_max.y;
    if (!(period > 0.0) || !std::isfinite(period) ||
	!std::isfinite(curve_minimum) || !std::isfinite(curve_maximum))
    {
	return 0.0;
    }

    const double minimum_multiple = ceil((surface_domain.Min() -
	parameter_tolerance - curve_minimum) / period);
    const double maximum_multiple = floor((surface_domain.Max() +
	parameter_tolerance - curve_maximum) / period);
    if (!std::isfinite(minimum_multiple) ||
	!std::isfinite(maximum_multiple) ||
	minimum_multiple > maximum_multiple)
    {
	return 0.0;
    }

    double multiple = 0.0;
    if (minimum_multiple > 0.0) {
	multiple = minimum_multiple;
    } else if (maximum_multiple < 0.0) {
	multiple = maximum_multiple;
    }
    const double shift = multiple * period;
    if (ZERO(shift) || !std::isfinite(shift)) {
	return 0.0;
    }

    ON_Interval curve_domain = curve->Domain();
    curve_domain.MakeIncreasing();
    if (!curve_domain.IsIncreasing()) {
	return 0.0;
    }
    const double samples[] = {
	curve_domain.Min(), curve_domain.Mid(), curve_domain.Max()
    };
    const bool closed_direction = surface->IsClosed(direction) ||
	surface->IsPeriodic(direction);
    for (size_t sample_index = 0;
	 sample_index < sizeof(samples) / sizeof(samples[0]); ++sample_index)
    {
	const ON_3dPoint parameter = curve->PointAt(samples[sample_index]);
	ON_3dPoint shifted_parameter(parameter);
	shifted_parameter[direction] += shift;
	const ON_3dPoint shifted_point = surface->PointAt(shifted_parameter.x,
	    shifted_parameter.y);
	if (!parameter.IsValid() || !shifted_point.IsValid() ||
	    shifted_parameter[direction] < surface_domain.Min() -
		parameter_tolerance ||
	    shifted_parameter[direction] > surface_domain.Max() +
		parameter_tolerance)
	{
	    return 0.0;
	}
	if (!closed_direction) {
	    const ON_3dPoint point = surface->PointAt(parameter.x, parameter.y);
	    if (!point.IsValid() ||
		point.DistanceTo(shifted_point) > INTERSECTION_TOL)
	    {
		return 0.0;
	    }
	}
    }

    return shift;
}


static void
normalize_periodic_ssi_parameter_curves(
    ON_ClassArray<SSICurve> &curves,
    const ON_Surface *surface,
    const ON_BoundingBox &model_bounds)
{
    if (surface == NULL) {
	return;
    }

    for (int curve_index = 0; curve_index < curves.Count(); ++curve_index) {
	ON_Curve *curve = curves[curve_index].m_curve;
	if (curve == NULL || curve->Dimension() < 2) {
	    continue;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_BoundingBox bounds = curve->BoundingBox();
	    bu_log("Periodic SSI candidate %d: U %.17g -> %.17g "
		"(closed %d periodic %d), V %.17g -> %.17g (closed %d "
		"periodic %d), bounds %.17g %.17g -> %.17g %.17g.\n",
		curve_index, surface->Domain(0).Min(), surface->Domain(0).Max(),
		surface->IsClosed(0), surface->IsPeriodic(0),
		surface->Domain(1).Min(), surface->Domain(1).Max(),
		surface->IsClosed(1), surface->IsPeriodic(1),
		bounds.m_min.x, bounds.m_min.y, bounds.m_max.x,
		bounds.m_max.y);
	}

	double point_tolerance = ON_ZERO_TOLERANCE;
	double curve_parameter_tolerance = ON_ZERO_TOLERANCE;
	get_face_boundary_curve_tolerances(surface, curve, point_tolerance,
	    curve_parameter_tolerance);
	const double model_tolerance =
	    boolean_model_repair_tolerance(model_bounds);
	ON_BoundingBox parameter_bounds;
	if (model_tolerance > 0.0 && std::isfinite(model_tolerance) &&
	    curve->GetTightBoundingBox(parameter_bounds) &&
	    parameter_bounds.IsValid())
	{
	    const ON_3dPoint start = curve->PointAtStart();
	    const ON_3dPoint end = curve->PointAtEnd();
	    for (int constant_direction = 0; constant_direction < 2;
		 ++constant_direction)
	    {
		const int varying_direction = 1 - constant_direction;
		const double constant = 0.5 *
		    (start[constant_direction] + end[constant_direction]);
		ON_3dPoint normalized_start(start);
		ON_3dPoint normalized_end(end);
		normalized_start[constant_direction] = constant;
		normalized_end[constant_direction] = constant;
		ON_LineCurve normalized_parameter(normalized_start, normalized_end);
		if ((!surface->IsClosed(varying_direction) &&
		     !surface->IsPeriodic(varying_direction)) ||
		    !start.IsValid() || !end.IsValid() ||
		    fabs(start[constant_direction] -
			end[constant_direction]) > point_tolerance ||
		    !normalized_parameter.ChangeDimension(2) ||
		    !normalized_parameter.SetDomain(curve->Domain().Min(),
			curve->Domain().Max()))
		{
		    continue;
		}
		std::unique_ptr<ON_Curve> original_lifted(
		    pushup_boolean_trim_curve(surface, *curve));
		std::unique_ptr<ON_Curve> normalized_lifted(
		    pushup_boolean_trim_curve(surface, normalized_parameter));
		bool reversed = false;
		if (!original_lifted || !normalized_lifted ||
		    !brep_curves_coincident(*original_lifted, *normalized_lifted,
			model_tolerance, &reversed) || reversed)
		{
		    continue;
		}
		curves[curve_index].Reset(normalized_parameter.DuplicateCurve());
		curve = curves[curve_index].m_curve;
		break;
	    }
	}
	const double first_shift = periodic_parameter_shift(surface, curve, 0,
	    point_tolerance);
	const double second_shift = periodic_parameter_shift(surface, curve, 1,
	    point_tolerance);
	if (ZERO(first_shift) && ZERO(second_shift)) {
	    continue;
	}

	ON_Curve *normalized = curve->DuplicateCurve();
	if (normalized == NULL || !normalized->Translate(ON_3dVector(first_shift,
		second_shift, 0.0)) || !normalized->IsValid())
	{
	    delete normalized;
	    continue;
	}
	curves[curve_index].Reset(normalized);
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Normalized periodic SSI curve %d by (%.17g, %.17g).\n",
		curve_index, first_shift, second_shift);
	}
    }
}


static bool
normalize_periodic_isoparametric_linked_curve(
    LinkedCurve &linked_curve,
    const ON_Surface *surface,
    const ON_BoundingBox &model_bounds)
{
    if (surface == NULL || linked_curve.IsClosed() ||
	linked_curve.m_ssi_curves.Count() < 2)
    {
	return false;
    }

    const ON_Curve *curve = linked_curve.Curve();
    double point_tolerance = 0.0;
    double curve_parameter_tolerance = 0.0;
    const double model_tolerance =
	boolean_model_repair_tolerance(model_bounds);
    if (!curve || !get_face_boundary_curve_tolerances(surface, curve,
	    point_tolerance, curve_parameter_tolerance) ||
	!(model_tolerance > 0.0) || !std::isfinite(model_tolerance))
    {
	return false;
    }

    const ON_3dPoint start = curve->PointAtStart();
    const ON_3dPoint end = curve->PointAtEnd();
    for (int varying_direction = 0; varying_direction < 2;
	 ++varying_direction)
    {
	const int constant_direction = 1 - varying_direction;
	ON_Interval varying_domain = surface->Domain(varying_direction);
	ON_Interval constant_domain = surface->Domain(constant_direction);
	varying_domain.MakeIncreasing();
	constant_domain.MakeIncreasing();
	const bool spans_period = varying_domain.IsIncreasing() &&
	    (surface->IsClosed(varying_direction) ||
	     surface->IsPeriodic(varying_direction)) &&
	    ((fabs(start[varying_direction] - varying_domain.Min()) <=
		point_tolerance &&
	      fabs(end[varying_direction] - varying_domain.Max()) <=
		point_tolerance) ||
	     (fabs(start[varying_direction] - varying_domain.Max()) <=
		point_tolerance &&
	      fabs(end[varying_direction] - varying_domain.Min()) <=
		point_tolerance));
	const double constant = 0.5 *
	    (start[constant_direction] + end[constant_direction]);
	if (!spans_period || !constant_domain.Includes(constant)) {
	    continue;
	}

	ON_3dPoint normalized_start(start);
	ON_3dPoint normalized_end(end);
	normalized_start[constant_direction] = constant;
	normalized_end[constant_direction] = constant;
	std::unique_ptr<ON_LineCurve> normalized(new ON_LineCurve(
	    normalized_start, normalized_end));
	if (!normalized->ChangeDimension(2) || !normalized->IsValid()) {
	    continue;
	}
	std::unique_ptr<ON_Curve> original_lifted(
	    pushup_boolean_trim_curve(surface, *curve));
	std::unique_ptr<ON_Curve> normalized_lifted(
	    pushup_boolean_trim_curve(surface, *normalized));
	bool reversed = false;
	bool coincident = original_lifted && normalized_lifted &&
	    brep_curves_coincident(*original_lifted, *normalized_lifted,
		model_tolerance, &reversed);
	if (!coincident && original_lifted && normalized_lifted &&
	    original_lifted->PointAtStart().DistanceTo(
		normalized_lifted->PointAtStart()) <= model_tolerance &&
	    original_lifted->PointAtEnd().DistanceTo(
		normalized_lifted->PointAtEnd()) <= model_tolerance)
	{
	    ON_NurbsCurve original_nurbs;
	    ON_NurbsCurve normalized_nurbs;
	    double maximum_distance = 0.0;
	    coincident = original_lifted->GetNurbForm(original_nurbs) > 0 &&
		normalized_lifted->GetNurbForm(normalized_nurbs) > 0 &&
		measure_curve_to_nurbs_distance(original_lifted.get(),
		    &normalized_nurbs, maximum_distance) &&
		measure_curve_to_nurbs_distance(normalized_lifted.get(),
		    &original_nurbs, maximum_distance) &&
		maximum_distance <= model_tolerance;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Periodic linked SSI normalization direction %d, constant "
		"%.17g, endpoints %.17g/%.17g, tolerance %.17g, "
		"lifted/coincident/reversed %d/%d/%d.\n", varying_direction,
		constant, start[constant_direction], end[constant_direction],
		model_tolerance, original_lifted && normalized_lifted,
		coincident, reversed);
	}
	if (!coincident || reversed)
	{
	    continue;
	}

	const int source_face = linked_curve.m_ssi_curves[0].m_source_face_index;
	const int peer_face = linked_curve.m_ssi_curves[0].m_peer_face_index;
	for (int segment = 1; segment < linked_curve.m_ssi_curves.Count();
	     ++segment)
	{
	    if (linked_curve.m_ssi_curves[segment].m_source_face_index !=
		    source_face ||
		linked_curve.m_ssi_curves[segment].m_peer_face_index != peer_face)
	    {
		return false;
	    }
	}
	LinkedCurve replacement;
	replacement.Append(SSICurve(normalized.release(), source_face, peer_face));
	linked_curve = replacement;
	return true;
    }
    return false;
}


struct BooleanLinkedCurveEndpoint {
    int m_curve_index;
    bool m_at_start;
    int m_source_face_index;
    int m_peer_face_index;
    ON_3dPoint m_parameter_point;
};


static bool
boolean_linked_curve_endpoint(
    ON_ClassArray<LinkedCurve> &curves,
    int curve_index,
    bool at_start,
    BooleanLinkedCurveEndpoint &endpoint)
{
    if (curve_index < 0 || curve_index >= curves.Count() ||
	curves[curve_index].m_ssi_curves.Count() < 1 ||
	curves[curve_index].IsClosed())
    {
	return false;
    }

    const SSICurve &source = at_start ?
	curves[curve_index].m_ssi_curves[0] :
	*curves[curve_index].m_ssi_curves.Last();
    if (source.m_curve == NULL) {
	return false;
    }

    endpoint.m_curve_index = curve_index;
    endpoint.m_at_start = at_start;
    endpoint.m_source_face_index = source.m_source_face_index;
    endpoint.m_peer_face_index = source.m_peer_face_index;
    endpoint.m_parameter_point = at_start ?
	curves[curve_index].PointAtStart() : curves[curve_index].PointAtEnd();
    return endpoint.m_parameter_point.IsValid();
}


static bool
boolean_global_face_reference(
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    int global_face_index,
    const ON_Brep *&brep,
    int &local_face_index)
{
    brep = NULL;
    local_face_index = -1;
    if (brep1 == NULL || brep2 == NULL || global_face_index < 0) {
	return false;
    }

    if (global_face_index < brep1->m_F.Count()) {
	brep = brep1;
	local_face_index = global_face_index;
    } else {
	brep = brep2;
	local_face_index = global_face_index - brep1->m_F.Count();
    }
    return local_face_index >= 0 && local_face_index < brep->m_F.Count();
}


static bool
boolean_face_edge_indices(
    const ON_Brep *brep,
    int face_index,
    std::set<int> &edge_indices)
{
    edge_indices.clear();
    if (brep == NULL || face_index < 0 || face_index >= brep->m_F.Count()) {
	return false;
    }

    const ON_BrepFace &face = brep->m_F[face_index];
    for (int loop_position = 0; loop_position < face.m_li.Count();
	 ++loop_position)
    {
	const int loop_index = face.m_li[loop_position];
	if (loop_index < 0 || loop_index >= brep->m_L.Count()) {
	    return false;
	}
	const ON_BrepLoop &loop = brep->m_L[loop_index];
	for (int trim_position = 0; trim_position < loop.m_ti.Count();
	     ++trim_position)
	{
	    const int trim_index = loop.m_ti[trim_position];
	    if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
		return false;
	    }
	    const int edge_index = brep->m_T[trim_index].m_ei;
	    if (edge_index >= 0 && edge_index < brep->m_E.Count()) {
		edge_indices.insert(edge_index);
	    }
	}
    }
    return !edge_indices.empty();
}


static const ON_BrepEdge *
boolean_unique_shared_source_edge(
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    int first_global_face,
    int second_global_face,
    int &edge_index)
{
    edge_index = -1;
    const ON_Brep *first_brep = NULL;
    const ON_Brep *second_brep = NULL;
    int first_face = -1;
    int second_face = -1;
    if (!boolean_global_face_reference(brep1, brep2, first_global_face,
	    first_brep, first_face) ||
	!boolean_global_face_reference(brep1, brep2, second_global_face,
	    second_brep, second_face) || first_brep != second_brep ||
	first_face == second_face)
    {
	return NULL;
    }

    std::set<int> first_edges;
    std::set<int> second_edges;
    if (!boolean_face_edge_indices(first_brep, first_face, first_edges) ||
	!boolean_face_edge_indices(second_brep, second_face, second_edges))
    {
	return NULL;
    }

    for (std::set<int>::const_iterator it = first_edges.begin();
	 it != first_edges.end(); ++it)
    {
	if (second_edges.find(*it) == second_edges.end()) {
	    continue;
	}
	if (edge_index >= 0) {
	    edge_index = -1;
	    return NULL;
	}
	edge_index = *it;
    }
    return edge_index >= 0 ? &first_brep->m_E[edge_index] : NULL;
}


static bool
boolean_parameter_point_is_on_closed_surface_seam(
    const ON_Surface *surface,
    const ON_3dPoint &point,
    double parameter_tolerance)
{
    if (surface == NULL || !point.IsValid() ||
	!(parameter_tolerance > 0.0) || !std::isfinite(parameter_tolerance))
    {
	return false;
    }

    for (int direction = 0; direction < 2; ++direction) {
	if (!surface->IsClosed(direction)) {
	    continue;
	}
	ON_Interval domain = surface->Domain(direction);
	domain.MakeIncreasing();
	if (!domain.IsIncreasing()) {
	    continue;
	}
	const double parameter = direction == 0 ? point.x : point.y;
	if (fabs(parameter - domain.Min()) <= parameter_tolerance ||
	    fabs(parameter - domain.Max()) <= parameter_tolerance)
	{
	    return true;
	}
    }
    return false;
}


static bool
boolean_source_edge_parameter_connector(
    const ON_BrepEdge *source_edge,
    const ON_Surface *surface,
    const TrimmedFace *face,
    const ON_3dPoint &first_parameter,
    const ON_3dPoint &second_parameter,
    double tolerance,
    std::unique_ptr<ON_Curve> &connector)
{
    connector.reset();
    if (source_edge == NULL || surface == NULL || face == NULL ||
	face->m_face == NULL || source_edge->IsClosed() ||
	!first_parameter.IsValid() || !second_parameter.IsValid() ||
	!(tolerance > 0.0) || !std::isfinite(tolerance))
    {
	return false;
    }

    const ON_3dPoint first_model = boolean_surface_point_at(surface,
	first_parameter);
    const ON_3dPoint second_model = boolean_surface_point_at(surface,
	second_parameter);
    double first_edge_parameter = ON_UNSET_VALUE;
    double second_edge_parameter = ON_UNSET_VALUE;
    const bool first_on_edge = first_model.IsValid() &&
	point_3d_to_curve_parameter_with_tolerance(first_model, source_edge,
	    tolerance, first_edge_parameter);
    const bool second_on_edge = second_model.IsValid() &&
	point_3d_to_curve_parameter_with_tolerance(second_model, source_edge,
	    tolerance, second_edge_parameter);
    if (!first_model.IsValid() || !second_model.IsValid() ||
	!first_on_edge || !second_on_edge)
    {
	return false;
    }

    ON_Interval source_domain = source_edge->Domain();
    source_domain.MakeIncreasing();
    const double parameter_scale = source_domain.IsIncreasing() ?
	std::max(1.0, source_domain.Length()) : 1.0;
    if (!source_domain.IsIncreasing() ||
	fabs(first_edge_parameter - second_edge_parameter) <=
	    128.0 * ON_EPSILON * parameter_scale)
    {
	return false;
    }

    std::unique_ptr<ON_Curve> model_connector;
    try {
	model_connector.reset(sub_curve(source_edge,
	    std::min(first_edge_parameter, second_edge_parameter),
	    std::max(first_edge_parameter, second_edge_parameter)));
    } catch (const InvalidInterval &) {
	return false;
    }
    if (!model_connector ||
	(first_edge_parameter > second_edge_parameter &&
	 !model_connector->Reverse()) || !model_connector->IsValid())
    {
	return false;
    }

    std::string failure_reason;
    PullbackFailureReason failure = PullbackFailureReason::None;
    std::unique_ptr<ON_Curve> parameter_connector(brlcad::pullback_curve(
	surface, model_connector.get(), tolerance,
	std::max(INTERSECTION_TOL, 0.25 * tolerance), &failure_reason,
	&failure));
    if (!parameter_connector || parameter_connector->Dimension() != 2 ||
	!parameter_connector->IsValid())
    {
	record_boolean_projection_failure();
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean source-edge connector pullback failed (reason %d): "
		"%s.\n", static_cast<int>(failure), failure_reason.c_str());
	}
	return false;
    }

    /* Select the periodic image closest to the linked-chain endpoint. */
    ON_3dPoint connector_start = parameter_connector->PointAtStart();
    ON_3dPoint connector_end = parameter_connector->PointAtEnd();
    double direct_error = std::max(
	boolean_surface_point_at(surface, connector_start).DistanceTo(first_model),
	boolean_surface_point_at(surface, connector_end).DistanceTo(second_model));
    double reverse_error = std::max(
	boolean_surface_point_at(surface, connector_start).DistanceTo(second_model),
	boolean_surface_point_at(surface, connector_end).DistanceTo(first_model));
    if (reverse_error < direct_error) {
	if (!parameter_connector->Reverse()) {
	    return false;
	}
	connector_start = parameter_connector->PointAtStart();
	connector_end = parameter_connector->PointAtEnd();
    }
    ON_3dVector shift(0.0, 0.0, 0.0);
    for (int direction = 0; direction < 2; ++direction) {
	if (!surface->IsClosed(direction) && !surface->IsPeriodic(direction)) {
	    continue;
	}
	ON_Interval domain = surface->Domain(direction);
	domain.MakeIncreasing();
	if (domain.IsIncreasing() && domain.Length() > ON_ZERO_TOLERANCE) {
	    shift[direction] = std::round((first_parameter[direction] -
		connector_start[direction]) / domain.Length()) * domain.Length();
	}
    }
    if ((!ZERO(shift.x) || !ZERO(shift.y)) &&
	!parameter_connector->Translate(shift))
    {
	return false;
    }

    connector_start = parameter_connector->PointAtStart();
    connector_end = parameter_connector->PointAtEnd();
    const ON_3dPoint lifted_start = boolean_surface_point_at(surface,
	connector_start);
    const ON_3dPoint lifted_end = boolean_surface_point_at(surface,
	connector_end);
    if (!lifted_start.IsValid() || !lifted_end.IsValid() ||
	lifted_start.DistanceTo(first_model) > tolerance ||
	lifted_end.DistanceTo(second_model) > tolerance ||
	!parameter_connector->SetStartPoint(first_parameter) ||
	!parameter_connector->SetEndPoint(second_parameter) ||
	!parameter_connector->IsValid())
    {
	return false;
    }

    int orientation = -1;
    if (!parameter_curve_lifts_to_model_curve(surface,
	    parameter_connector.get(), model_connector.get(), tolerance,
	    &orientation) || orientation != 0)
    {
	return false;
    }
    const ON_Interval connector_domain = parameter_connector->Domain();
    if (!connector_domain.IsIncreasing()) {
	return false;
    }
    static const int connector_samples = 64;
    try {
	for (int sample = 0; sample <= connector_samples; ++sample) {
	    const ON_3dPoint parameter = parameter_connector->PointAt(
		connector_domain.ParameterAt(static_cast<double>(sample) /
		    connector_samples));
	    if (!parameter.IsValid() || !is_point_inside_trimmed_face(
		    ON_2dPoint(parameter), face))
	    {
		return false;
	    }
	}
    } catch (const InvalidGeometry &) {
	return false;
    }

    connector = std::move(parameter_connector);
    return true;
}


static bool
boolean_certify_source_edge_connector(
    ON_ClassArray<LinkedCurve> &curves,
    const BooleanLinkedCurveEndpoint &first,
    const BooleanLinkedCurveEndpoint &second,
    const TrimmedFace *face,
    int source_face_index,
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    const ON_BoundingBox &model_bounds,
    int &source_edge_index,
    bool &use_source_edge_curve)
{
    source_edge_index = -1;
    use_source_edge_curve = false;
    const bool self_connector = first.m_curve_index == second.m_curve_index;
    const auto rejected = [&](const char *reason) {
	if (DEBUG_BREP_BOOLEAN && self_connector) {
	    bu_log("Boolean self-closing SSI chain %d on source face %d "
		"rejected: %s.\n", first.m_curve_index, source_face_index,
		reason);
	}
	return false;
    };
    if (face == NULL || face->m_face == NULL ||
	first.m_source_face_index != source_face_index ||
	second.m_source_face_index != source_face_index ||
	first.m_peer_face_index < 0 || second.m_peer_face_index < 0 ||
	first.m_peer_face_index == second.m_peer_face_index)
    {
	return rejected("endpoint provenance does not identify two peer faces");
    }

    const ON_Surface *surface = face->m_face->SurfaceOf();
    LinkedCurve &first_curve = curves[first.m_curve_index];
    LinkedCurve &second_curve = curves[second.m_curve_index];
    const ON_Curve *first_whole_curve = first_curve.Curve();
    const ON_Curve *second_whole_curve = second_curve.Curve();
    if (surface == NULL || first_whole_curve == NULL ||
	second_whole_curve == NULL)
    {
	return rejected("the face surface or linked curve is missing");
    }

    double first_point_tolerance = 0.0;
    double first_curve_tolerance = 0.0;
    double second_point_tolerance = 0.0;
    double second_curve_tolerance = 0.0;
    if (!get_face_boundary_curve_tolerances(surface, first_whole_curve,
	    first_point_tolerance, first_curve_tolerance) ||
	!get_face_boundary_curve_tolerances(surface, second_whole_curve,
	    second_point_tolerance, second_curve_tolerance))
    {
	return rejected("parameter tolerances could not be determined");
    }
    const double parameter_tolerance = std::max(first_point_tolerance,
	second_point_tolerance);
    if (boolean_parameter_point_is_on_closed_surface_seam(surface,
	    first.m_parameter_point, parameter_tolerance) ||
	boolean_parameter_point_is_on_closed_surface_seam(surface,
	    second.m_parameter_point, parameter_tolerance))
    {
	return rejected("an endpoint lies on a closed-surface seam");
    }

    const double repair_tolerance =
	boolean_model_repair_tolerance(model_bounds);
    if (!(repair_tolerance > 0.0) || !std::isfinite(repair_tolerance)) {
	return rejected("the model repair tolerance is invalid");
    }
    /* The connector may be a resolved interval of a source edge rather than
     * a tolerance-sized gap.  Use the stitching allowance only as its
     * distance-to-source bound; every sample must map monotonically to the
     * unique source edge shared by the two peer faces. */
    const double connector_tolerance = 2.0 * repair_tolerance;
    if (!std::isfinite(connector_tolerance)) {
	return rejected("the connector tolerance is invalid");
    }

    const ON_3dPoint first_model = surface->PointAt(first.m_parameter_point.x,
	first.m_parameter_point.y);
    const ON_3dPoint second_model = surface->PointAt(second.m_parameter_point.x,
	second.m_parameter_point.y);
    const double endpoint_gap = first_model.IsValid() && second_model.IsValid() ?
	first_model.DistanceTo(second_model) : std::numeric_limits<double>::max();
    if (!(endpoint_gap > ON_ZERO_TOLERANCE) ||
	!std::isfinite(endpoint_gap))
    {
	return rejected("the model-space endpoint gap is unresolved");
    }

    const ON_BrepEdge *source_edge = boolean_unique_shared_source_edge(brep1,
	brep2, first.m_peer_face_index, second.m_peer_face_index,
	source_edge_index);
    ON_Interval edge_domain = source_edge ? source_edge->Domain() :
	ON_Interval::EmptyInterval;
    edge_domain.MakeIncreasing();
    if (source_edge == NULL || !edge_domain.IsIncreasing()) {
	return rejected("the peer faces do not have one shared source edge");
    }

    if (self_connector) {
	std::unique_ptr<ON_Curve> source_connector;
	if (!boolean_source_edge_parameter_connector(source_edge, surface, face,
		first.m_parameter_point, second.m_parameter_point,
		connector_tolerance, source_connector))
	{
	    return rejected("the shared source-edge interval has no certified surface pullback");
	}
	use_source_edge_curve = true;
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean self-closing SSI chain %d on source face %d "
		"certified across source edge %d with model gap %.17g.\n",
		first.m_curve_index, source_face_index, source_edge_index,
		endpoint_gap);
	}
	return true;
    }

    static const int connector_samples = 32;
    std::vector<double> normalized_edge_parameters;
    normalized_edge_parameters.reserve(connector_samples + 1);
    for (int sample = 0; sample <= connector_samples; ++sample) {
	const double fraction = static_cast<double>(sample) / connector_samples;
	const ON_3dPoint parameter_point =
	    (1.0 - fraction) * first.m_parameter_point +
	    fraction * second.m_parameter_point;
	if (!parameter_point.IsValid() ||
	    !is_point_inside_trimmed_face(ON_2dPoint(parameter_point), face))
	{
	    return rejected("the connector leaves the trimmed source face");
	}

	const ON_3dPoint model_point = surface->PointAt(parameter_point.x,
	    parameter_point.y);
	double edge_parameter = ON_UNSET_VALUE;
	if (!model_point.IsValid() ||
	    !point_3d_to_curve_parameter_with_tolerance(model_point, source_edge,
		connector_tolerance, edge_parameter))
	{
	    return rejected("the connector does not follow the shared source edge");
	}
	const double normalized = edge_domain.NormalizedParameterAt(edge_parameter);
	if (!std::isfinite(normalized)) {
	    return rejected("the source-edge parameter is invalid");
	}
	normalized_edge_parameters.push_back(normalized);
    }

    const double edge_progress = normalized_edge_parameters.back() -
	normalized_edge_parameters.front();
    if (fabs(edge_progress) <= 128.0 * ON_EPSILON) {
	return rejected("the connector has no resolved source-edge progress");
    }
    const double direction = edge_progress > 0.0 ? 1.0 : -1.0;
    const double progress_tolerance = std::max(128.0 * ON_EPSILON,
	1.0e-5 * fabs(edge_progress));
    for (size_t sample = 1; sample < normalized_edge_parameters.size();
	 ++sample)
    {
	if (direction * (normalized_edge_parameters[sample] -
		normalized_edge_parameters[sample - 1]) < -progress_tolerance)
	{
	    return rejected("the connector is not monotone on the shared source edge");
	}
    }
    return true;
}


static bool
link_one_certified_source_edge_gap(
    ON_ClassArray<LinkedCurve> &curves,
    const TrimmedFace *face,
    int source_face_index,
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    const ON_BoundingBox &model_bounds)
{
    struct ConnectorCandidate {
	BooleanLinkedCurveEndpoint first;
	BooleanLinkedCurveEndpoint second;
	int source_edge_index;
	bool use_source_edge_curve;
    };

    std::vector<ConnectorCandidate> candidates;
    std::vector<int> endpoint_candidate_counts(2 * curves.Count(), 0);
    std::vector<int> curve_candidate_counts(curves.Count(), 0);
    for (int curve_index = 0; curve_index < curves.Count(); ++curve_index) {
	BooleanLinkedCurveEndpoint start;
	BooleanLinkedCurveEndpoint end;
	if (!boolean_linked_curve_endpoint(curves, curve_index, true, start) ||
	    !boolean_linked_curve_endpoint(curves, curve_index, false, end))
	{
	    continue;
	}

	int source_edge_index = -1;
	bool use_source_edge_curve = false;
	if (!boolean_certify_source_edge_connector(curves, start, end, face,
		source_face_index, brep1, brep2, model_bounds,
		source_edge_index, use_source_edge_curve))
	{
	    continue;
	}

	ConnectorCandidate candidate;
	candidate.first = start;
	candidate.second = end;
	candidate.source_edge_index = source_edge_index;
	candidate.use_source_edge_curve = use_source_edge_curve;
	candidates.push_back(candidate);
	endpoint_candidate_counts[2 * curve_index]++;
	endpoint_candidate_counts[2 * curve_index + 1]++;
	curve_candidate_counts[curve_index]++;
    }
    for (int first_curve = 0; first_curve < curves.Count(); ++first_curve) {
	for (int second_curve = first_curve + 1;
	     second_curve < curves.Count(); ++second_curve)
	{
	    for (int first_end = 0; first_end < 2; ++first_end) {
		for (int second_end = 0; second_end < 2; ++second_end) {
		    BooleanLinkedCurveEndpoint first;
		    BooleanLinkedCurveEndpoint second;
		    if (!boolean_linked_curve_endpoint(curves, first_curve,
			    first_end == 0, first) ||
			!boolean_linked_curve_endpoint(curves, second_curve,
			    second_end == 0, second))
		    {
			continue;
		    }

		    int source_edge_index = -1;
		    bool use_source_edge_curve = false;
		    if (!boolean_certify_source_edge_connector(curves, first,
			    second, face, source_face_index, brep1, brep2,
			    model_bounds, source_edge_index,
			    use_source_edge_curve))
		    {
			continue;
		    }

		    ConnectorCandidate candidate;
		    candidate.first = first;
		    candidate.second = second;
		    candidate.source_edge_index = source_edge_index;
		    candidate.use_source_edge_curve = use_source_edge_curve;
		    candidates.push_back(candidate);
		    endpoint_candidate_counts[2 * first_curve + first_end]++;
		    endpoint_candidate_counts[2 * second_curve + second_end]++;
		    curve_candidate_counts[first_curve]++;
		    curve_candidate_counts[second_curve]++;
		}
	    }
	}
    }

    for (size_t candidate_index = 0; candidate_index < candidates.size();
	 ++candidate_index)
    {
	const ConnectorCandidate &candidate = candidates[candidate_index];
	const int first_endpoint = 2 * candidate.first.m_curve_index +
	    (candidate.first.m_at_start ? 0 : 1);
	const int second_endpoint = 2 * candidate.second.m_curve_index +
	    (candidate.second.m_at_start ? 0 : 1);
	if (endpoint_candidate_counts[first_endpoint] != 1 ||
	    endpoint_candidate_counts[second_endpoint] != 1 ||
	    curve_candidate_counts[candidate.first.m_curve_index] != 1 ||
	    curve_candidate_counts[candidate.second.m_curve_index] != 1)
	{
	    continue;
	}
	if (candidate.first.m_curve_index == candidate.second.m_curve_index) {
	    LinkedCurve &curve = curves[candidate.first.m_curve_index];
	    const ON_3dPoint connector_start = curve.PointAtEnd();
	    const ON_3dPoint connector_end = curve.PointAtStart();
	    int source_edge_index = -1;
	    const ON_BrepEdge *source_edge = boolean_unique_shared_source_edge(
		brep1, brep2, candidate.first.m_peer_face_index,
		candidate.second.m_peer_face_index, source_edge_index);
	    std::unique_ptr<ON_Curve> connector;
	    if (!candidate.use_source_edge_curve ||
		!boolean_source_edge_parameter_connector(source_edge,
		    face->m_face->SurfaceOf(), face, connector_start,
		    connector_end,
		    2.0 * boolean_model_repair_tolerance(model_bounds),
		    connector))
	    {
		return false;
	    }
	    LinkedCurve closed;
	    closed.Append(curve);
	    closed.Append(SSICurve(connector.release(), source_face_index, -1));
	    if (!closed.IsValid() || !closed.IsClosed()) {
		return false;
	    }
	    ON_SimpleArray<ON_Curve *> loop_segments;
	    for (int segment_index = 0;
		 segment_index < closed.m_ssi_curves.Count(); ++segment_index)
	    {
		loop_segments.Append(
		    closed.m_ssi_curves[segment_index].m_curve);
	    }
	    if (!is_loop_valid(loop_segments, ON_ZERO_TOLERANCE) ||
		loop_is_degenerate(loop_segments))
	    {
		return false;
	    }
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Closed Boolean SSI chain %d on source face %d across "
		    "source edge %d: (%.17g, %.17g) -> (%.17g, %.17g).\n",
		    candidate.first.m_curve_index, source_face_index,
		    candidate.source_edge_index, connector_start.x,
		    connector_start.y, connector_end.x, connector_end.y);
	    }
	    curve = closed;
	    return true;
	}

	LinkedCurve &first = curves[candidate.first.m_curve_index];
	LinkedCurve &second = curves[candidate.second.m_curve_index];
	if (candidate.first.m_at_start && !first.Reverse()) {
	    return false;
	}
	if (!candidate.second.m_at_start && !second.Reverse()) {
	    return false;
	}

	const ON_3dPoint connector_start = first.PointAtEnd();
	const ON_3dPoint connector_end = second.PointAtStart();
	LinkedCurve joined;
	joined.Append(first);
	joined.Append(SSICurve(new ON_LineCurve(connector_start, connector_end),
	    source_face_index, -1));
	joined.Append(second);
	if (!joined.IsValid()) {
	    return false;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Certified Boolean SSI connector on source face %d across "
		"source edge %d: (%.17g, %.17g) -> (%.17g, %.17g).\n",
		source_face_index, candidate.source_edge_index,
		connector_start.x, connector_start.y, connector_end.x,
		connector_end.y);
	}
	first = joined;
	second.Empty();
	return true;
    }
    return false;
}


struct BooleanSeamChain {
    int m_curve_index;
    int m_direction;
    int m_side;
    int m_boundary_curve_index;
    int m_peer_face_index[2];
    BooleanBoundaryEndpointHit m_hits[2];
    ON_3dPoint m_model_endpoint[2];
};


static bool
boolean_closed_surface_seam_chain(
    ON_ClassArray<LinkedCurve> &curves,
    int curve_index,
    const TrimmedFace *face,
    int source_face_index,
    BooleanSeamChain &seam_chain)
{
    if (face == NULL || face->m_face == NULL || curve_index < 0 ||
	curve_index >= curves.Count() ||
	curves[curve_index].m_ssi_curves.Count() < 1)
    {
	return false;
    }

    const ON_Surface *surface = face->m_face->SurfaceOf();
    if (surface == NULL ||
	(!surface->IsClosed(0) && !surface->IsClosed(1)) ||
	curves[curve_index].IsClosed())
    {
	return false;
    }
    const ON_Curve *curve = curves[curve_index].Curve();
    double parameter_tolerance = 0.0;
    double curve_parameter_tolerance = 0.0;
    if (curve == NULL ||
	!get_face_boundary_curve_tolerances(surface, curve,
	    parameter_tolerance, curve_parameter_tolerance) ||
	!boolean_find_certified_open_curve_endpoint_pair(curve,
	    face->m_outerloop, parameter_tolerance, seam_chain.m_hits, true,
	    true) || seam_chain.m_hits[0].m_boundary_curve_index !=
	    seam_chain.m_hits[1].m_boundary_curve_index)
    {
	return false;
    }

    const SSICurve &first_segment = curves[curve_index].m_ssi_curves[0];
    const SSICurve &last_segment = *curves[curve_index].m_ssi_curves.Last();
    if (first_segment.m_source_face_index != source_face_index ||
	last_segment.m_source_face_index != source_face_index ||
	first_segment.m_peer_face_index < 0 ||
	last_segment.m_peer_face_index < 0)
    {
	return false;
    }

    const ON_3dPoint endpoint[2] = {
	curve->PointAtStart(), curve->PointAtEnd()
    };
    int seam_direction = -1;
    int seam_side = -1;
    for (int direction = 0; direction < 2; ++direction) {
	if (!surface->IsClosed(direction)) {
	    continue;
	}
	ON_Interval domain = surface->Domain(direction);
	domain.MakeIncreasing();
	if (!domain.IsIncreasing()) {
	    continue;
	}
	const double first_parameter = direction == 0 ? endpoint[0].x :
	    endpoint[0].y;
	const double second_parameter = direction == 0 ? endpoint[1].x :
	    endpoint[1].y;
	for (int side = 0; side < 2; ++side) {
	    const double boundary_parameter = side == 0 ? domain.Min() :
		domain.Max();
	    if (fabs(first_parameter - boundary_parameter) <=
		    parameter_tolerance &&
		fabs(second_parameter - boundary_parameter) <=
		    parameter_tolerance)
	    {
		if (seam_direction >= 0) {
		    return false;
		}
		seam_direction = direction;
		seam_side = side;
	    }
	}
    }
    if (seam_direction < 0) {
	return false;
    }

    const int boundary_index = seam_chain.m_hits[0].m_boundary_curve_index;
    const ON_Curve *boundary = boundary_index >= 0 &&
	boundary_index < face->m_outerloop.Count() ?
	face->m_outerloop[boundary_index] : NULL;
    if (boundary == NULL) {
	return false;
    }
    ON_Interval seam_domain = surface->Domain(seam_direction);
    seam_domain.MakeIncreasing();
    const double seam_parameter = seam_side == 0 ? seam_domain.Min() :
	seam_domain.Max();
    static const int boundary_samples = 16;
    for (int sample = 0; sample <= boundary_samples; ++sample) {
	const double fraction = static_cast<double>(sample) / boundary_samples;
	const double boundary_parameter =
	    (1.0 - fraction) * seam_chain.m_hits[0].m_boundary_parameter +
	    fraction * seam_chain.m_hits[1].m_boundary_parameter;
	const ON_3dPoint point = boundary->PointAt(boundary_parameter);
	const double parameter = seam_direction == 0 ? point.x : point.y;
	if (!point.IsValid() ||
	    fabs(parameter - seam_parameter) > parameter_tolerance)
	{
	    return false;
	}
    }

    seam_chain.m_curve_index = curve_index;
    seam_chain.m_direction = seam_direction;
    seam_chain.m_side = seam_side;
    seam_chain.m_boundary_curve_index = boundary_index;
    seam_chain.m_peer_face_index[0] = first_segment.m_peer_face_index;
    seam_chain.m_peer_face_index[1] = last_segment.m_peer_face_index;
    for (int endpoint_index = 0; endpoint_index < 2; ++endpoint_index) {
	seam_chain.m_model_endpoint[endpoint_index] = surface->PointAt(
	    endpoint[endpoint_index].x, endpoint[endpoint_index].y);
	if (!seam_chain.m_model_endpoint[endpoint_index].IsValid()) {
	    return false;
	}
    }
    return true;
}


static bool
boolean_seam_paths_lift_coincidently(
    const BooleanSeamChain &first,
    const BooleanSeamChain &second,
    const TrimmedFace *face,
    bool reverse_second,
    double model_tolerance)
{
    if (face == NULL || face->m_face == NULL ||
	first.m_boundary_curve_index < 0 ||
	first.m_boundary_curve_index >= face->m_outerloop.Count() ||
	second.m_boundary_curve_index < 0 ||
	second.m_boundary_curve_index >= face->m_outerloop.Count())
    {
	return false;
    }
    const ON_Surface *surface = face->m_face->SurfaceOf();
    const ON_Curve *first_boundary =
	face->m_outerloop[first.m_boundary_curve_index];
    const ON_Curve *second_boundary =
	face->m_outerloop[second.m_boundary_curve_index];
    if (surface == NULL || first_boundary == NULL || second_boundary == NULL) {
	return false;
    }

    static const int seam_samples = 32;
    for (int sample = 0; sample <= seam_samples; ++sample) {
	const double fraction = static_cast<double>(sample) / seam_samples;
	const double second_fraction = reverse_second ? 1.0 - fraction :
	    fraction;
	const double first_parameter =
	    (1.0 - fraction) * first.m_hits[0].m_boundary_parameter +
	    fraction * first.m_hits[1].m_boundary_parameter;
	const double second_parameter =
	    (1.0 - second_fraction) * second.m_hits[0].m_boundary_parameter +
	    second_fraction * second.m_hits[1].m_boundary_parameter;
	const ON_3dPoint first_uv = first_boundary->PointAt(first_parameter);
	const ON_3dPoint second_uv = second_boundary->PointAt(second_parameter);
	const ON_3dPoint first_model = first_uv.IsValid() ?
	    surface->PointAt(first_uv.x, first_uv.y) : ON_3dPoint::UnsetPoint;
	const ON_3dPoint second_model = second_uv.IsValid() ?
	    surface->PointAt(second_uv.x, second_uv.y) : ON_3dPoint::UnsetPoint;
	if (!first_model.IsValid() || !second_model.IsValid() ||
	    first_model.DistanceTo(second_model) > model_tolerance)
	{
	    return false;
	}
    }
    return true;
}


static bool
boolean_seam_chains_are_paired(
    const BooleanSeamChain &first,
    const BooleanSeamChain &second,
    const TrimmedFace *face,
    double model_tolerance)
{
    if (first.m_direction != second.m_direction ||
	first.m_side == second.m_side ||
	first.m_peer_face_index[0] < 0 || first.m_peer_face_index[1] < 0 ||
	first.m_peer_face_index[0] == first.m_peer_face_index[1])
    {
	return false;
    }

    const bool direct =
	first.m_peer_face_index[0] == second.m_peer_face_index[0] &&
	first.m_peer_face_index[1] == second.m_peer_face_index[1] &&
	first.m_model_endpoint[0].DistanceTo(second.m_model_endpoint[0]) <=
	    model_tolerance &&
	first.m_model_endpoint[1].DistanceTo(second.m_model_endpoint[1]) <=
	    model_tolerance;
    const bool reversed =
	first.m_peer_face_index[0] == second.m_peer_face_index[1] &&
	first.m_peer_face_index[1] == second.m_peer_face_index[0] &&
	first.m_model_endpoint[0].DistanceTo(second.m_model_endpoint[1]) <=
	    model_tolerance &&
	first.m_model_endpoint[1].DistanceTo(second.m_model_endpoint[0]) <=
	    model_tolerance;
    if (direct == reversed) {
	return false;
    }
    return boolean_seam_paths_lift_coincidently(first, second, face,
	reversed, model_tolerance);
}


static void
certify_paired_closed_surface_seam_curves(
    ON_ClassArray<LinkedCurve> &curves,
    const TrimmedFace *face,
    int source_face_index,
    const ON_BoundingBox &model_bounds)
{
    std::vector<BooleanSeamChain> seam_chains;
    for (int curve_index = 0; curve_index < curves.Count(); ++curve_index) {
	curves[curve_index].m_certified_same_boundary = false;
	BooleanSeamChain seam_chain;
	if (boolean_closed_surface_seam_chain(curves, curve_index, face,
		source_face_index, seam_chain))
	{
	    seam_chains.push_back(seam_chain);
	}
    }

    const double model_tolerance =
	boolean_model_repair_tolerance(model_bounds);
    if (!(model_tolerance > 0.0) || !std::isfinite(model_tolerance)) {
	return;
    }

    std::vector<int> partner_count(seam_chains.size(), 0);
    std::vector<std::pair<size_t, size_t> > pairs;
    for (size_t first = 0; first < seam_chains.size(); ++first) {
	for (size_t second = first + 1; second < seam_chains.size(); ++second) {
	    if (!boolean_seam_chains_are_paired(seam_chains[first],
		    seam_chains[second], face, model_tolerance))
	    {
		continue;
	    }
	    pairs.push_back(std::make_pair(first, second));
	    partner_count[first]++;
	    partner_count[second]++;
	}
    }

    for (size_t pair_index = 0; pair_index < pairs.size(); ++pair_index) {
	const size_t first = pairs[pair_index].first;
	const size_t second = pairs[pair_index].second;
	if (partner_count[first] != 1 || partner_count[second] != 1) {
	    continue;
	}
	curves[seam_chains[first].m_curve_index].m_certified_same_boundary = true;
	curves[seam_chains[second].m_curve_index].m_certified_same_boundary = true;
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Certified paired Boolean SSI seam chains %d/%d on source "
		"face %d in surface direction %d.\n",
		seam_chains[first].m_curve_index,
		seam_chains[second].m_curve_index, source_face_index,
		seam_chains[first].m_direction);
	}
    }
}


/* Surface intersections at a shared edge can report the same closed model
 * curve twice: once as a full seam-to-seam isoparametric curve and again as
 * two open pieces from the adjacent peer face.  Greedy endpoint linking then
 * makes a closed UV path which runs along the same line in both directions.
 * It is correctly zero-area in parameter space, but on a surface closed in
 * the varying direction either seam-to-seam path is the nondegenerate closed
 * model-space loop which partitions the face.
 *
 * Keep a single full-period representative only after proving that the whole
 * linked path is a collinear retrace, every segment is the same isoparametric
 * locus, and the representative's seam endpoints coincide in model space.
 */
static bool
reduce_periodic_isoparametric_retrace(
    LinkedCurve &linked_curve,
    const TrimmedFace *face,
    const ON_BoundingBox &model_bounds)
{
    if (face == NULL || face->m_face == NULL ||
	linked_curve.m_ssi_curves.Count() < 2 || !linked_curve.IsClosed())
    {
	return false;
    }

    const ON_Surface *surface = face->m_face->SurfaceOf();
    if (surface == NULL) {
	return false;
    }

    ON_SimpleArray<ON_Curve *> linked_segments;
    for (int segment_index = 0;
	 segment_index < linked_curve.m_ssi_curves.Count(); ++segment_index)
    {
	ON_Curve *segment = linked_curve.m_ssi_curves[segment_index].m_curve;
	if (segment == NULL) {
	    return false;
	}
	linked_segments.Append(segment);
    }
    if (!loop_is_degenerate(linked_segments)) {
	return false;
    }

    const double model_tolerance =
	boolean_model_repair_tolerance(model_bounds);
    if (!(model_tolerance > 0.0) || !std::isfinite(model_tolerance)) {
	return false;
    }

    int representative_index = -1;
    int varying_direction = -1;
    int fixed_direction = -1;
    double fixed_parameter = ON_UNSET_VALUE;
    double parameter_tolerance = 0.0;
    for (int segment_index = 0;
	 segment_index < linked_curve.m_ssi_curves.Count(); ++segment_index)
    {
	const ON_Curve *segment =
	    linked_curve.m_ssi_curves[segment_index].m_curve;
	const ON_Surface::ISO iso = surface->IsIsoparametric(*segment);
	const int candidate_varying = iso == ON_Surface::x_iso ? 1 :
	    (iso == ON_Surface::y_iso ? 0 : -1);
	if (candidate_varying < 0 ||
	    (!surface->IsClosed(candidate_varying) &&
	     !surface->IsPeriodic(candidate_varying)))
	{
	    continue;
	}

	double point_tolerance = 0.0;
	double curve_parameter_tolerance = 0.0;
	if (!get_face_boundary_curve_tolerances(surface, segment,
		point_tolerance, curve_parameter_tolerance) ||
	    !(point_tolerance > 0.0) || !std::isfinite(point_tolerance))
	{
	    continue;
	}

	ON_Interval surface_domain = surface->Domain(candidate_varying);
	surface_domain.MakeIncreasing();
	const ON_3dPoint start = segment->PointAtStart();
	const ON_3dPoint end = segment->PointAtEnd();
	const bool spans_forward =
	    fabs(start[candidate_varying] - surface_domain.Min()) <=
		point_tolerance &&
	    fabs(end[candidate_varying] - surface_domain.Max()) <=
		point_tolerance;
	const bool spans_reverse =
	    fabs(start[candidate_varying] - surface_domain.Max()) <=
		point_tolerance &&
	    fabs(end[candidate_varying] - surface_domain.Min()) <=
		point_tolerance;
	const int candidate_fixed = 1 - candidate_varying;
	if (!surface_domain.IsIncreasing() || !start.IsValid() || !end.IsValid() ||
	    (!spans_forward && !spans_reverse) ||
	    fabs(start[candidate_fixed] - end[candidate_fixed]) >
		point_tolerance)
	{
	    continue;
	}

	const ON_3dPoint model_start = surface->PointAt(start.x, start.y);
	const ON_3dPoint model_end = surface->PointAt(end.x, end.y);
	if (!model_start.IsValid() || !model_end.IsValid() ||
	    model_start.DistanceTo(model_end) > model_tolerance)
	{
	    continue;
	}

	representative_index = segment_index;
	varying_direction = candidate_varying;
	fixed_direction = candidate_fixed;
	fixed_parameter = 0.5 * (start[candidate_fixed] +
	    end[candidate_fixed]);
	parameter_tolerance = point_tolerance;
	break;
    }
    if (representative_index < 0) {
	return false;
    }

    ON_Interval varying_domain = surface->Domain(varying_direction);
    varying_domain.MakeIncreasing();
    static const int sample_count = 16;
    for (int segment_index = 0;
	 segment_index < linked_curve.m_ssi_curves.Count(); ++segment_index)
    {
	const ON_Curve *segment =
	    linked_curve.m_ssi_curves[segment_index].m_curve;
	const ON_Surface::ISO iso = surface->IsIsoparametric(*segment);
	if ((varying_direction == 0 && iso != ON_Surface::y_iso) ||
	    (varying_direction == 1 && iso != ON_Surface::x_iso))
	{
	    return false;
	}
	const ON_Interval segment_domain = segment->Domain();
	if (!segment_domain.IsIncreasing()) {
	    return false;
	}
	for (int sample = 0; sample <= sample_count; ++sample) {
	    const ON_3dPoint parameter = segment->PointAt(
		segment_domain.ParameterAt(static_cast<double>(sample) /
		    sample_count));
	    if (!parameter.IsValid() ||
		fabs(parameter[fixed_direction] - fixed_parameter) >
		    parameter_tolerance ||
		parameter[varying_direction] < varying_domain.Min() -
		    parameter_tolerance ||
		parameter[varying_direction] > varying_domain.Max() +
		    parameter_tolerance)
	    {
		return false;
	    }
	    ON_3dPoint representative_parameter(parameter);
	    representative_parameter[fixed_direction] = fixed_parameter;
	    const ON_3dPoint model_point = surface->PointAt(parameter.x,
		parameter.y);
	    const ON_3dPoint representative_point = surface->PointAt(
		representative_parameter.x, representative_parameter.y);
	    if (!model_point.IsValid() || !representative_point.IsValid() ||
		model_point.DistanceTo(representative_point) > model_tolerance)
	    {
		return false;
	    }
	}
    }

    /* Prefer the complementary seam-to-seam chain when it is valid.  It
     * retains intermediate vertices supplied by the adjacent peer face, so
     * the later shared-SSI repair can split and mate that peer's closed edge.
     * The single full-period event remains the conservative fallback. */
    LinkedCurve replacement;
    for (int segment_offset = 1;
	 segment_offset < linked_curve.m_ssi_curves.Count(); ++segment_offset)
    {
	const int segment_index = (representative_index + segment_offset) %
	    linked_curve.m_ssi_curves.Count();
	replacement.Append(linked_curve.m_ssi_curves[segment_index]);
    }
    const ON_3dPoint replacement_start = replacement.PointAtStart();
    const ON_3dPoint replacement_end = replacement.PointAtEnd();
    const bool replacement_spans_period = replacement.IsValid() &&
	!replacement.IsClosed() && replacement_start.IsValid() &&
	replacement_end.IsValid() &&
	((fabs(replacement_start[varying_direction] - varying_domain.Min()) <=
	      parameter_tolerance &&
	  fabs(replacement_end[varying_direction] - varying_domain.Max()) <=
	      parameter_tolerance) ||
	 (fabs(replacement_start[varying_direction] - varying_domain.Max()) <=
	      parameter_tolerance &&
	  fabs(replacement_end[varying_direction] - varying_domain.Min()) <=
	      parameter_tolerance)) &&
	fabs(replacement_start[fixed_direction] - fixed_parameter) <=
	    parameter_tolerance &&
	fabs(replacement_end[fixed_direction] - fixed_parameter) <=
	    parameter_tolerance;
    if (!replacement_spans_period) {
	replacement.Empty();
	replacement.Append(linked_curve.m_ssi_curves[representative_index]);
    }
    linked_curve = replacement;
    return !linked_curve.IsClosed();
}


struct BooleanPeriodicChainJoin {
    int m_first_curve;
    int m_second_curve;
    bool m_first_at_start;
    bool m_second_at_start;
    int m_seam_direction;
};


static bool
boolean_certify_periodic_chain_join(
    ON_ClassArray<LinkedCurve> &curves,
    int first_curve_index,
    int second_curve_index,
    const TrimmedFace *face,
    int source_face_index,
    const ON_BoundingBox &model_bounds,
    BooleanPeriodicChainJoin &candidate)
{
    if (face == NULL || face->m_face == NULL ||
	first_curve_index < 0 || second_curve_index < 0 ||
	first_curve_index >= curves.Count() ||
	second_curve_index >= curves.Count() ||
	first_curve_index == second_curve_index ||
	curves[first_curve_index].m_ssi_curves.Count() < 1 ||
	curves[second_curve_index].m_ssi_curves.Count() < 1 ||
	curves[first_curve_index].IsClosed() ||
	curves[second_curve_index].IsClosed())
    {
	return false;
    }

    const ON_Surface *surface = face->m_face->SurfaceOf();
    const ON_Curve *first_curve = curves[first_curve_index].Curve();
    const ON_Curve *second_curve = curves[second_curve_index].Curve();
    double first_point_tolerance = 0.0;
    double first_curve_tolerance = 0.0;
    double second_point_tolerance = 0.0;
    double second_curve_tolerance = 0.0;
    if (surface == NULL || first_curve == NULL || second_curve == NULL ||
	(!surface->IsClosed(0) && !surface->IsPeriodic(0) &&
	 !surface->IsClosed(1) && !surface->IsPeriodic(1)) ||
	!get_face_boundary_curve_tolerances(surface, first_curve,
	    first_point_tolerance, first_curve_tolerance) ||
	!get_face_boundary_curve_tolerances(surface, second_curve,
	    second_point_tolerance, second_curve_tolerance))
    {
	return false;
    }
    const double parameter_tolerance = std::max(first_point_tolerance,
	second_point_tolerance);
    if (!(parameter_tolerance > 0.0) ||
	!std::isfinite(parameter_tolerance))
    {
	return false;
    }

    /* Do not use periodic equivalence to pull an unwrapped or duplicate SSI
	 * representation into this chain.  The only gap being repaired here must
	 * already be an ordinary, near-exact UV endpoint match inside the face's
	 * rectangular parameter domain. */
    const ON_Curve *candidate_curves[2] = {first_curve, second_curve};
    for (int curve_index = 0; curve_index < 2; ++curve_index) {
	const ON_BoundingBox bounds = candidate_curves[curve_index]->BoundingBox();
	if (!bounds.IsValid()) {
	    return false;
	}
	for (int direction = 0; direction < 2; ++direction) {
	    ON_Interval domain = surface->Domain(direction);
	    domain.MakeIncreasing();
	    const double minimum = direction == 0 ? bounds.m_min.x :
		bounds.m_min.y;
	    const double maximum = direction == 0 ? bounds.m_max.x :
		bounds.m_max.y;
	    if (!domain.IsIncreasing() ||
		minimum < domain.Min() - parameter_tolerance ||
		maximum > domain.Max() + parameter_tolerance)
	    {
		return false;
	    }
	}
    }

    bool first_at_start = false;
    bool second_at_start = false;
    int matching_endpoint_pairs = 0;
    for (int first_end = 0; first_end < 2; ++first_end) {
	const ON_3dPoint first_point = first_end == 0 ?
	    curves[first_curve_index].PointAtStart() :
	    curves[first_curve_index].PointAtEnd();
	for (int second_end = 0; second_end < 2; ++second_end) {
	    const ON_3dPoint second_point = second_end == 0 ?
		curves[second_curve_index].PointAtStart() :
		curves[second_curve_index].PointAtEnd();
	    if (first_point.IsValid() && second_point.IsValid() &&
		first_point.DistanceTo(second_point) < ON_ZERO_TOLERANCE)
	    {
		first_at_start = first_end == 0;
		second_at_start = second_end == 0;
		matching_endpoint_pairs++;
	    }
	}
    }
    if (matching_endpoint_pairs != 1) {
	return false;
    }

    BooleanLinkedCurveEndpoint first_join;
    BooleanLinkedCurveEndpoint second_join;
    BooleanLinkedCurveEndpoint first_seam;
    BooleanLinkedCurveEndpoint second_seam;
    if (!boolean_linked_curve_endpoint(curves, first_curve_index,
	    first_at_start, first_join) ||
	!boolean_linked_curve_endpoint(curves, second_curve_index,
	    second_at_start, second_join) ||
	!boolean_linked_curve_endpoint(curves, first_curve_index,
	    !first_at_start, first_seam) ||
	!boolean_linked_curve_endpoint(curves, second_curve_index,
	    !second_at_start, second_seam) ||
	first_join.m_source_face_index != source_face_index ||
	second_join.m_source_face_index != source_face_index ||
	first_seam.m_source_face_index != source_face_index ||
	second_seam.m_source_face_index != source_face_index ||
	first_join.m_peer_face_index < 0 ||
	first_join.m_peer_face_index != second_join.m_peer_face_index ||
	first_seam.m_peer_face_index < 0 ||
	first_seam.m_peer_face_index != second_seam.m_peer_face_index)
    {
	return false;
    }

    int seam_direction = -1;
    for (int direction = 0; direction < 2; ++direction) {
	if (!surface->IsClosed(direction) && !surface->IsPeriodic(direction)) {
	    continue;
	}
	ON_Interval domain = surface->Domain(direction);
	domain.MakeIncreasing();
	if (!domain.IsIncreasing()) {
	    continue;
	}
	const double first_parameter =
	    first_seam.m_parameter_point[direction];
	const double second_parameter =
	    second_seam.m_parameter_point[direction];
	const bool opposite_sides =
	    (fabs(first_parameter - domain.Min()) <= parameter_tolerance &&
	     fabs(second_parameter - domain.Max()) <= parameter_tolerance) ||
	    (fabs(first_parameter - domain.Max()) <= parameter_tolerance &&
	     fabs(second_parameter - domain.Min()) <= parameter_tolerance);
	if (!opposite_sides) {
	    continue;
	}
	if (seam_direction >= 0) {
	    return false;
	}
	seam_direction = direction;
    }
    if (seam_direction < 0) {
	return false;
    }

    const double model_tolerance =
	boolean_model_repair_tolerance(model_bounds);
    const ON_3dPoint first_join_model = surface->PointAt(
	first_join.m_parameter_point.x, first_join.m_parameter_point.y);
    const ON_3dPoint second_join_model = surface->PointAt(
	second_join.m_parameter_point.x, second_join.m_parameter_point.y);
    const ON_3dPoint first_seam_model = surface->PointAt(
	first_seam.m_parameter_point.x, first_seam.m_parameter_point.y);
    const ON_3dPoint second_seam_model = surface->PointAt(
	second_seam.m_parameter_point.x, second_seam.m_parameter_point.y);
    if (!(model_tolerance > 0.0) || !std::isfinite(model_tolerance) ||
	!first_join_model.IsValid() || !second_join_model.IsValid() ||
	!first_seam_model.IsValid() || !second_seam_model.IsValid() ||
	first_join_model.DistanceTo(second_join_model) > model_tolerance ||
	first_seam_model.DistanceTo(second_seam_model) > model_tolerance)
    {
	return false;
    }

    candidate.m_first_curve = first_curve_index;
    candidate.m_second_curve = second_curve_index;
    candidate.m_first_at_start = first_at_start;
    candidate.m_second_at_start = second_at_start;
    candidate.m_seam_direction = seam_direction;
    return true;
}


static bool
link_one_certified_periodic_boundary_chain(
    ON_ClassArray<LinkedCurve> &curves,
    const TrimmedFace *face,
    int source_face_index,
    const ON_BoundingBox &model_bounds)
{
    std::vector<BooleanPeriodicChainJoin> candidates;
    std::vector<int> curve_candidate_counts(curves.Count(), 0);
    for (int first_curve = 0; first_curve < curves.Count(); ++first_curve) {
	for (int second_curve = first_curve + 1;
	     second_curve < curves.Count(); ++second_curve)
	{
	    BooleanPeriodicChainJoin candidate;
	    if (!boolean_certify_periodic_chain_join(curves, first_curve,
		    second_curve, face, source_face_index, model_bounds,
		    candidate))
	    {
		continue;
	    }
	    candidates.push_back(candidate);
	    curve_candidate_counts[first_curve]++;
	    curve_candidate_counts[second_curve]++;
	}
    }

    for (size_t candidate_index = 0; candidate_index < candidates.size();
	 ++candidate_index)
    {
	const BooleanPeriodicChainJoin &candidate = candidates[candidate_index];
	if (curve_candidate_counts[candidate.m_first_curve] != 1 ||
	    curve_candidate_counts[candidate.m_second_curve] != 1)
	{
	    continue;
	}

	LinkedCurve &first = curves[candidate.m_first_curve];
	LinkedCurve &second = curves[candidate.m_second_curve];
	if (candidate.m_first_at_start && !first.Reverse()) {
	    return false;
	}
	if (!candidate.m_second_at_start && !second.Reverse()) {
	    return false;
	}
	if (first.PointAtEnd().DistanceTo(second.PointAtStart()) >=
	    ON_ZERO_TOLERANCE)
	{
	    return false;
	}

	LinkedCurve joined;
	joined.Append(first);
	joined.Append(second);
	if (!joined.IsValid() || joined.IsClosed()) {
	    return false;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Certified periodic Boolean SSI chain join on source face "
		"%d between curves %d/%d in surface direction %d.\n",
		source_face_index, candidate.m_first_curve,
		candidate.m_second_curve, candidate.m_seam_direction);
	}
	first = joined;
	second.Empty();
	return true;
    }
    return false;
}


struct BooleanLiftedEndpointLoopPair {
    int m_first_curve;
    int m_second_curve;
    bool m_reverse_second;
    double m_join_gap;
    double m_closure_gap;
};


static bool
boolean_lifted_endpoint_connector_is_pointlike(
    const TrimmedFace *face,
    const ON_3dPoint &first_parameter,
    const ON_3dPoint &second_parameter,
    double parameter_tolerance,
    double model_tolerance,
    double &model_gap)
{
    model_gap = std::numeric_limits<double>::max();
    if (face == NULL || face->m_face == NULL ||
	!first_parameter.IsValid() || !second_parameter.IsValid() ||
	!(parameter_tolerance > 0.0) ||
	!std::isfinite(parameter_tolerance) || !(model_tolerance > 0.0) ||
	!std::isfinite(model_tolerance))
    {
	return false;
    }

    const ON_Surface *surface = face->m_face->SurfaceOf();
    if (surface == NULL) {
	return false;
    }

    /* This repair is for local gaps whose UV size is exaggerated by a
     * closed surface's metric, not for distant parameter points which happen
     * to lift nearby.  Seam-spanning chains have their own stricter repair. */
    for (int direction = 0; direction < 2; ++direction) {
	ON_Interval domain = surface->Domain(direction);
	domain.MakeIncreasing();
	if (!domain.IsIncreasing() ||
	    first_parameter[direction] < domain.Min() - parameter_tolerance ||
	    first_parameter[direction] > domain.Max() + parameter_tolerance ||
	    second_parameter[direction] < domain.Min() - parameter_tolerance ||
	    second_parameter[direction] > domain.Max() + parameter_tolerance ||
	    fabs(first_parameter[direction] - second_parameter[direction]) >
		8.0 * parameter_tolerance)
	{
	    return false;
	}
    }

    const ON_3dPoint first_model = surface->PointAt(first_parameter.x,
	first_parameter.y);
    const ON_3dPoint second_model = surface->PointAt(second_parameter.x,
	second_parameter.y);
    model_gap = first_model.IsValid() && second_model.IsValid() ?
	first_model.DistanceTo(second_model) :
	std::numeric_limits<double>::max();
    if (!std::isfinite(model_gap) || model_gap > model_tolerance) {
	return false;
    }

    static const int connector_samples = 32;
    for (int sample = 1; sample < connector_samples; ++sample) {
	const double fraction = static_cast<double>(sample) /
	    connector_samples;
	const ON_3dPoint parameter =
	    (1.0 - fraction) * first_parameter +
	    fraction * second_parameter;
	const ON_3dPoint model = parameter.IsValid() ?
	    surface->PointAt(parameter.x, parameter.y) :
	    ON_3dPoint::UnsetPoint;
	try {
	    if (!parameter.IsValid() || !model.IsValid() ||
		model.DistanceTo(first_model) > model_tolerance ||
		model.DistanceTo(second_model) > model_tolerance ||
		!is_point_inside_trimmed_face(ON_2dPoint(parameter), face))
	    {
		return false;
	    }
	} catch (InvalidGeometry &) {
	    return false;
	}
    }
    return true;
}


static bool
boolean_certify_lifted_endpoint_loop_pair(
    ON_ClassArray<LinkedCurve> &curves,
    int first_curve_index,
    int second_curve_index,
    const TrimmedFace *face,
    int source_face_index,
    const ON_BoundingBox &model_bounds,
    BooleanLiftedEndpointLoopPair &candidate)
{
    if (face == NULL || face->m_face == NULL ||
	first_curve_index < 0 || first_curve_index >= curves.Count() ||
	second_curve_index < 0 || second_curve_index >= curves.Count() ||
	first_curve_index == second_curve_index ||
	curves[first_curve_index].m_ssi_curves.Count() < 1 ||
	curves[second_curve_index].m_ssi_curves.Count() < 1 ||
	curves[first_curve_index].IsClosed() ||
	curves[second_curve_index].IsClosed())
    {
	return false;
    }

    const ON_Surface *surface = face->m_face->SurfaceOf();
    const ON_Curve *first_curve = curves[first_curve_index].Curve();
    const ON_Curve *second_curve = curves[second_curve_index].Curve();
    double first_point_tolerance = 0.0;
    double first_curve_tolerance = 0.0;
    double second_point_tolerance = 0.0;
    double second_curve_tolerance = 0.0;
    if (surface == NULL || first_curve == NULL || second_curve == NULL ||
	(!surface->IsClosed(0) && !surface->IsPeriodic(0) &&
	 !surface->IsClosed(1) && !surface->IsPeriodic(1)) ||
	!get_face_boundary_curve_tolerances(surface, first_curve,
	    first_point_tolerance, first_curve_tolerance) ||
	!get_face_boundary_curve_tolerances(surface, second_curve,
	    second_point_tolerance, second_curve_tolerance))
    {
	return false;
    }
    const double parameter_tolerance = std::max(first_point_tolerance,
	second_point_tolerance);
    const double model_tolerance = 2.0 *
	boolean_model_repair_tolerance(model_bounds);
    if (!(parameter_tolerance > 0.0) ||
	!std::isfinite(parameter_tolerance) || !(model_tolerance > 0.0) ||
	!std::isfinite(model_tolerance))
    {
	return false;
    }

    BooleanLinkedCurveEndpoint first[2];
    BooleanLinkedCurveEndpoint second[2];
    if (!boolean_linked_curve_endpoint(curves, first_curve_index, true,
	    first[0]) ||
	!boolean_linked_curve_endpoint(curves, first_curve_index, false,
	    first[1]) ||
	!boolean_linked_curve_endpoint(curves, second_curve_index, true,
	    second[0]) ||
	!boolean_linked_curve_endpoint(curves, second_curve_index, false,
	    second[1]))
    {
	return false;
    }
    for (int endpoint = 0; endpoint < 2; ++endpoint) {
	if (first[endpoint].m_source_face_index != source_face_index ||
	    second[endpoint].m_source_face_index != source_face_index)
	{
	    return false;
	}
    }

    const auto pairing_is_certified = [&](bool reverse_second,
	double &join_gap, double &closure_gap) {
	const int second_join = reverse_second ? 1 : 0;
	const int second_closure = 1 - second_join;
	if (first[1].m_peer_face_index < 0 ||
	    first[0].m_peer_face_index < 0 ||
	    first[1].m_peer_face_index !=
		second[second_join].m_peer_face_index ||
	    first[0].m_peer_face_index !=
		second[second_closure].m_peer_face_index)
	{
	    return false;
	}
	return boolean_lifted_endpoint_connector_is_pointlike(face,
		first[1].m_parameter_point,
		second[second_join].m_parameter_point, parameter_tolerance,
		model_tolerance, join_gap) &&
	    boolean_lifted_endpoint_connector_is_pointlike(face,
		second[second_closure].m_parameter_point,
		first[0].m_parameter_point, parameter_tolerance,
		model_tolerance, closure_gap);
    };

    double direct_join_gap = 0.0;
    double direct_closure_gap = 0.0;
    double reversed_join_gap = 0.0;
    double reversed_closure_gap = 0.0;
    const bool direct = pairing_is_certified(false, direct_join_gap,
	direct_closure_gap);
    const bool reversed = pairing_is_certified(true, reversed_join_gap,
	reversed_closure_gap);
    if (direct == reversed) {
	return false;
    }

    candidate.m_first_curve = first_curve_index;
    candidate.m_second_curve = second_curve_index;
    candidate.m_reverse_second = reversed;
    candidate.m_join_gap = reversed ? reversed_join_gap : direct_join_gap;
    candidate.m_closure_gap = reversed ? reversed_closure_gap :
	direct_closure_gap;
    return true;
}


static bool
boolean_parameter_curve_locus_within_model_ball(
    const ON_Surface *surface,
    const ON_Curve *curve,
    const ON_3dPoint &center,
    double parameter_tolerance,
    double model_tolerance)
{
    if (surface == NULL || curve == NULL || !center.IsValid() ||
	!(parameter_tolerance > 0.0) ||
	!std::isfinite(parameter_tolerance) || !(model_tolerance > 0.0) ||
	!std::isfinite(model_tolerance))
    {
	return false;
    }

    ON_Interval curve_domain = curve->Domain();
    curve_domain.MakeIncreasing();
    const ON_BoundingBox parameter_bounds = curve->BoundingBox();
    if (!curve_domain.IsIncreasing() || !parameter_bounds.IsValid() ||
	parameter_bounds.m_max.x - parameter_bounds.m_min.x >
	    8.0 * parameter_tolerance ||
	parameter_bounds.m_max.y - parameter_bounds.m_min.y >
	    8.0 * parameter_tolerance)
    {
	return false;
    }

    static const int locus_samples = 64;
    for (int sample = 0; sample <= locus_samples; ++sample) {
	const ON_3dPoint parameter = curve->PointAt(
	    curve_domain.ParameterAt(static_cast<double>(sample) /
		locus_samples));
	const ON_3dPoint model = parameter.IsValid() ?
	    surface->PointAt(parameter.x, parameter.y) :
	    ON_3dPoint::UnsetPoint;
	if (!parameter.IsValid() || !model.IsValid() ||
	    model.DistanceTo(center) > model_tolerance)
	{
	    return false;
	}
    }
    return true;
}


static bool
normalize_boolean_lifted_endpoint_loop(
    LinkedCurve &closed,
    const TrimmedFace *face,
    const ON_BoundingBox &model_bounds)
{
    if (face == NULL || face->m_face == NULL || !closed.IsClosed() ||
	closed.m_ssi_curves.Count() < 3)
    {
	return false;
    }

    const ON_Surface *surface = face->m_face->SurfaceOf();
    const ON_Curve *whole_curve = closed.Curve();
    double parameter_tolerance = 0.0;
    double curve_parameter_tolerance = 0.0;
    const double model_tolerance =
	boolean_model_repair_tolerance(model_bounds);
    if (surface == NULL || whole_curve == NULL ||
	!get_face_boundary_curve_tolerances(surface, whole_curve,
	    parameter_tolerance, curve_parameter_tolerance) ||
	!(parameter_tolerance > 0.0) ||
	!std::isfinite(parameter_tolerance) || !(model_tolerance > 0.0) ||
	!std::isfinite(model_tolerance))
    {
	return false;
    }

    const int segment_count = closed.m_ssi_curves.Count();
    std::vector<bool> pointlike(segment_count, false);
    std::vector<int> survivors;
    for (int segment_index = 0; segment_index < segment_count;
	 ++segment_index)
    {
	const ON_Curve *segment =
	    closed.m_ssi_curves[segment_index].m_curve;
	const ON_3dPoint start_parameter = segment ?
	    segment->PointAtStart() : ON_3dPoint::UnsetPoint;
	const ON_3dPoint start_model = start_parameter.IsValid() ?
	    surface->PointAt(start_parameter.x, start_parameter.y) :
	    ON_3dPoint::UnsetPoint;
	pointlike[segment_index] = start_model.IsValid() &&
	    boolean_parameter_curve_locus_within_model_ball(surface, segment,
		start_model, parameter_tolerance, model_tolerance);
	if (!pointlike[segment_index]) {
	    survivors.push_back(segment_index);
	}
    }
    if (survivors.size() == static_cast<size_t>(segment_count)) {
	return true;
    }
    if (survivors.size() < 2) {
	return false;
    }

    std::vector<std::unique_ptr<ON_Curve> > replacement_curves;
    replacement_curves.reserve(survivors.size());
    for (size_t survivor = 0; survivor < survivors.size(); ++survivor) {
	const ON_Curve *source =
	    closed.m_ssi_curves[survivors[survivor]].m_curve;
	replacement_curves.push_back(std::unique_ptr<ON_Curve>(
	    source ? source->DuplicateCurve() : NULL));
	if (!replacement_curves.back() ||
	    !replacement_curves.back()->IsValid())
	{
	    return false;
	}
    }

    for (size_t survivor = 0; survivor < survivors.size(); ++survivor) {
	const size_t next_survivor = (survivor + 1) % survivors.size();
	const int current_index = survivors[survivor];
	const int next_index = survivors[next_survivor];
	int skipped_index = (current_index + 1) % segment_count;
	if (skipped_index == next_index) {
	    continue;
	}

	const ON_3dPoint current_end =
	    replacement_curves[survivor]->PointAtEnd();
	const ON_3dPoint next_start =
	    replacement_curves[next_survivor]->PointAtStart();
	double endpoint_gap = 0.0;
	if (!boolean_lifted_endpoint_connector_is_pointlike(face, current_end,
		next_start, parameter_tolerance, model_tolerance,
		endpoint_gap))
	{
	    return false;
	}
	const ON_3dPoint join_parameter = 0.5 * (current_end + next_start);
	const ON_3dPoint join_model = surface->PointAt(join_parameter.x,
	    join_parameter.y);
	if (!join_parameter.IsValid() || !join_model.IsValid()) {
	    return false;
	}

	for (; skipped_index != next_index;
	     skipped_index = (skipped_index + 1) % segment_count)
	{
	    if (!pointlike[skipped_index] ||
		!boolean_parameter_curve_locus_within_model_ball(surface,
		    closed.m_ssi_curves[skipped_index].m_curve, join_model,
		    parameter_tolerance, model_tolerance))
	    {
		return false;
	    }
	}

	if (!replacement_curves[survivor]->SetEndPoint(join_parameter) ||
	    !replacement_curves[next_survivor]->SetStartPoint(join_parameter) ||
	    !replacement_curves[survivor]->IsValid() ||
	    !replacement_curves[next_survivor]->IsValid())
	{
	    return false;
	}
    }

    static const int deformation_samples = 64;
    for (size_t survivor = 0; survivor < survivors.size(); ++survivor) {
	const ON_Curve *original =
	    closed.m_ssi_curves[survivors[survivor]].m_curve;
	const ON_Curve *replacement = replacement_curves[survivor].get();
	ON_Interval original_domain = original->Domain();
	ON_Interval replacement_domain = replacement->Domain();
	original_domain.MakeIncreasing();
	replacement_domain.MakeIncreasing();
	if (!original_domain.IsIncreasing() ||
	    !replacement_domain.IsIncreasing())
	{
	    return false;
	}
	for (int sample = 0; sample <= deformation_samples; ++sample) {
	    const double fraction = static_cast<double>(sample) /
		deformation_samples;
	    const ON_3dPoint original_parameter = original->PointAt(
		original_domain.ParameterAt(fraction));
	    const ON_3dPoint replacement_parameter = replacement->PointAt(
		replacement_domain.ParameterAt(fraction));
	    const ON_3dPoint original_model = original_parameter.IsValid() ?
		surface->PointAt(original_parameter.x, original_parameter.y) :
		ON_3dPoint::UnsetPoint;
	    const ON_3dPoint replacement_model =
		replacement_parameter.IsValid() ? surface->PointAt(
		    replacement_parameter.x, replacement_parameter.y) :
		ON_3dPoint::UnsetPoint;
	    if (!original_model.IsValid() || !replacement_model.IsValid() ||
		original_model.DistanceTo(replacement_model) > model_tolerance)
	    {
		return false;
	    }
	}
    }

    LinkedCurve normalized;
    for (size_t survivor = 0; survivor < survivors.size(); ++survivor) {
	const SSICurve &source = closed.m_ssi_curves[survivors[survivor]];
	normalized.Append(SSICurve(replacement_curves[survivor].release(),
	    source.m_source_face_index, source.m_peer_face_index));
    }
    if (!normalized.IsValid() || !normalized.IsClosed()) {
	return false;
    }

    ON_SimpleArray<ON_Curve *> loop_segments;
    for (int segment_index = 0;
	 segment_index < normalized.m_ssi_curves.Count(); ++segment_index)
    {
	loop_segments.Append(normalized.m_ssi_curves[segment_index].m_curve);
    }
    if (!is_loop_valid(loop_segments, ON_ZERO_TOLERANCE) ||
	loop_is_degenerate(loop_segments))
    {
	return false;
    }

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean lifted-endpoint loop removed %d model-point-sized "
	    "segments at tolerance %.17g.\n",
	    segment_count - static_cast<int>(survivors.size()),
	    model_tolerance);
    }
    closed = normalized;
    return true;
}


static bool
close_one_certified_lifted_endpoint_loop_pair(
    ON_ClassArray<LinkedCurve> &curves,
    const TrimmedFace *face,
    int source_face_index,
    const ON_BoundingBox &model_bounds)
{
    std::vector<BooleanLiftedEndpointLoopPair> candidates;
    std::vector<int> candidate_counts(curves.Count(), 0);
    for (int first_curve = 0; first_curve < curves.Count(); ++first_curve) {
	for (int second_curve = first_curve + 1;
	     second_curve < curves.Count(); ++second_curve)
	{
	    BooleanLiftedEndpointLoopPair candidate;
	    if (!boolean_certify_lifted_endpoint_loop_pair(curves,
		    first_curve, second_curve, face, source_face_index,
		    model_bounds, candidate))
	    {
		continue;
	    }
	    candidates.push_back(candidate);
	    candidate_counts[first_curve]++;
	    candidate_counts[second_curve]++;
	}
    }

    for (size_t candidate_index = 0; candidate_index < candidates.size();
	 ++candidate_index)
    {
	const BooleanLiftedEndpointLoopPair &candidate =
	    candidates[candidate_index];
	if (candidate_counts[candidate.m_first_curve] != 1 ||
	    candidate_counts[candidate.m_second_curve] != 1)
	{
	    continue;
	}

	LinkedCurve first = curves[candidate.m_first_curve];
	LinkedCurve second = curves[candidate.m_second_curve];
	if (candidate.m_reverse_second && !second.Reverse()) {
	    return false;
	}

	LinkedCurve closed;
	closed.Append(first);
	if (first.PointAtEnd().DistanceTo(second.PointAtStart()) >=
		ON_ZERO_TOLERANCE)
	{
	    closed.Append(SSICurve(new ON_LineCurve(first.PointAtEnd(),
		    second.PointAtStart())));
	}
	closed.Append(second);
	if (second.PointAtEnd().DistanceTo(first.PointAtStart()) >=
		ON_ZERO_TOLERANCE)
	{
	    closed.Append(SSICurve(new ON_LineCurve(second.PointAtEnd(),
		    first.PointAtStart())));
	}
	if (!closed.IsValid() || !closed.IsClosed()) {
	    return false;
	}
	if (!normalize_boolean_lifted_endpoint_loop(closed, face,
		model_bounds))
	{
	    return false;
	}

	ON_SimpleArray<ON_Curve *> loop_segments;
	for (int segment_index = 0;
	     segment_index < closed.m_ssi_curves.Count(); ++segment_index)
	{
	    loop_segments.Append(closed.m_ssi_curves[segment_index].m_curve);
	}
	if (!is_loop_valid(loop_segments, ON_ZERO_TOLERANCE) ||
	    loop_is_degenerate(loop_segments))
	{
	    return false;
	}

	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Closed Boolean SSI chains %d/%d on source face %d from "
		"uniquely paired lifted endpoints (model gaps %.17g/%.17g).\n",
		candidate.m_first_curve, candidate.m_second_curve,
		source_face_index, candidate.m_join_gap,
		candidate.m_closure_gap);
	}
	curves[candidate.m_first_curve] = closed;
	curves[candidate.m_second_curve].Empty();
	return true;
    }
    return false;
}


/* Two open intersection chains can jointly partition a face with a hole even
 * though neither chain partitions it alone.  This occurs when each chain runs
 * from the outer boundary to the same inner trimming loop.  It is seen both
 * when a transverse intersection crosses a closed surface's parameter seam
 * and when two distinct planar cuts bound a sector of an annular face.  Pair
 * only uniquely certified fragments and close them with paths already present
 * on the inner and outer loops, turning the annular cut into an ordinary
 * closed face partition. */
struct BooleanInnerLoopEndpoint {
    bool m_at_start;
    bool m_on_outer_loop;
    int m_inner_loop_index;
    BooleanBoundaryEndpointHit m_hit;

    BooleanInnerLoopEndpoint()
	: m_at_start(false), m_on_outer_loop(false),
	  m_inner_loop_index(-1)
    {}
};


static bool
boolean_find_near_boundary_endpoint_hit(
    const ON_Curve *curve,
    double curve_parameter,
    const ON_SimpleArray<ON_Curve *> &boundary,
    const ON_Surface *surface,
    double parameter_tolerance,
    BooleanBoundaryEndpointHit &hit)
{
    if (curve == NULL || surface == NULL || boundary.Count() < 1 ||
	!(parameter_tolerance > 0.0) || !std::isfinite(parameter_tolerance))
    {
	return false;
    }

    ON_Interval curve_domain = curve->Domain();
    curve_domain.MakeIncreasing();
    if (!curve_domain.IsIncreasing() ||
	!boolean_curve_parameter_is_endpoint(curve_parameter, curve_domain,
	    ON_ZERO_TOLERANCE))
    {
	return false;
    }

    const ON_3dPoint endpoint = curve->PointAt(curve_parameter);
    const ON_3dPoint model_endpoint = endpoint.IsValid() ?
	surface->PointAt(endpoint.x, endpoint.y) : ON_3dPoint::UnsetPoint;
    if (!endpoint.IsValid() || !model_endpoint.IsValid()) {
	return false;
    }

    bool found = false;
    for (int boundary_index = 0; boundary_index < boundary.Count();
	 ++boundary_index)
    {
	const ON_Curve *boundary_curve = boundary[boundary_index];
	double boundary_parameter = ON_UNSET_VALUE;
	if (boundary_curve == NULL ||
	    !point_3d_to_curve_parameter_with_tolerance(endpoint,
		boundary_curve, parameter_tolerance, boundary_parameter, false))
	{
	    continue;
	}

	ON_Interval boundary_domain = boundary_curve->Domain();
	boundary_domain.MakeIncreasing();
	const ON_3dPoint boundary_point = boundary_curve->PointAt(
	    boundary_parameter);
	const ON_3dPoint model_boundary = boundary_point.IsValid() ?
	    surface->PointAt(boundary_point.x, boundary_point.y) :
	    ON_3dPoint::UnsetPoint;
	if (!boundary_domain.IsIncreasing() ||
	    !boundary_domain.Includes(boundary_parameter) ||
	    !boundary_point.IsValid() || !model_boundary.IsValid() ||
	    endpoint.DistanceTo(boundary_point) > parameter_tolerance ||
	    model_endpoint.DistanceTo(model_boundary) > INTERSECTION_TOL ||
	    boundary_point.DistanceTo(boundary_curve->PointAtStart()) <=
		parameter_tolerance ||
	    boundary_point.DistanceTo(boundary_curve->PointAtEnd()) <=
		parameter_tolerance)
	{
	    continue;
	}

	const ON_3dVector curve_tangent = curve->TangentAt(curve_parameter);
	const ON_3dVector boundary_tangent =
	    boundary_curve->TangentAt(boundary_parameter);
	if (curve_tangent.Length() <= ON_ZERO_TOLERANCE ||
	    boundary_tangent.Length() <= ON_ZERO_TOLERANCE ||
	    curve_tangent.IsParallelTo(boundary_tangent, ANGLE_TOL) != 0)
	{
	    continue;
	}

	if (found) {
	    return false;
	}
	hit.m_point = boundary_point;
	hit.m_boundary_curve_index = boundary_index;
	hit.m_boundary_parameter = boundary_parameter;
	hit.m_curve_parameter = curve_parameter;
	found = true;
    }
    return found;
}


/* A one-curve closed trim has one topological seam vertex represented by both
 * ends of its parameter domain.  The ordinary endpoint finder deliberately
 * rejects boundary vertices because a multi-curve loop can make their path
 * ownership ambiguous.  For a single closed trim there is only one canonical
 * choice, so represent the seam by the start of that curve. */
static bool
boolean_find_closed_boundary_seam_endpoint_hit(
    const ON_Curve *curve,
    double curve_parameter,
    const ON_SimpleArray<ON_Curve *> &boundary,
    const ON_Surface *surface,
    double parameter_tolerance,
    BooleanBoundaryEndpointHit &hit)
{
    if (curve == NULL || surface == NULL || boundary.Count() != 1 ||
	boundary[0] == NULL || !boundary[0]->IsClosed() ||
	!(parameter_tolerance > 0.0) || !std::isfinite(parameter_tolerance))
    {
	return false;
    }

    ON_Interval curve_domain = curve->Domain();
    ON_Interval boundary_domain = boundary[0]->Domain();
    curve_domain.MakeIncreasing();
    boundary_domain.MakeIncreasing();
    if (!curve_domain.IsIncreasing() || !boundary_domain.IsIncreasing() ||
	!boolean_curve_parameter_is_endpoint(curve_parameter, curve_domain,
	    ON_ZERO_TOLERANCE))
    {
	return false;
    }

    const ON_3dPoint endpoint = curve->PointAt(curve_parameter);
    const ON_3dPoint seam = boundary[0]->PointAt(boundary_domain.Min());
    const ON_3dPoint model_endpoint = endpoint.IsValid() ?
	surface->PointAt(endpoint.x, endpoint.y) : ON_3dPoint::UnsetPoint;
    const ON_3dPoint model_seam = seam.IsValid() ?
	surface->PointAt(seam.x, seam.y) : ON_3dPoint::UnsetPoint;
    const ON_3dVector curve_tangent = curve->TangentAt(curve_parameter);
    const ON_3dVector boundary_tangent =
	boundary[0]->TangentAt(boundary_domain.Min());
    if (!endpoint.IsValid() || !seam.IsValid() ||
	!model_endpoint.IsValid() || !model_seam.IsValid() ||
	endpoint.DistanceTo(seam) > parameter_tolerance ||
	model_endpoint.DistanceTo(model_seam) > INTERSECTION_TOL ||
	curve_tangent.Length() <= ON_ZERO_TOLERANCE ||
	boundary_tangent.Length() <= ON_ZERO_TOLERANCE ||
	curve_tangent.IsParallelTo(boundary_tangent, ANGLE_TOL) != 0)
    {
	return false;
    }

    hit.m_point = seam;
    hit.m_boundary_curve_index = 0;
    hit.m_boundary_parameter = boundary_domain.Min();
    hit.m_curve_parameter = curve_parameter;
    return true;
}


static bool
boolean_find_inner_loop_endpoint(
    LinkedCurve &curve,
    bool at_start,
    const TrimmedFace *face,
    double parameter_tolerance,
    BooleanInnerLoopEndpoint &endpoint,
    bool allow_near_hit = false,
    bool allow_closed_loop_seam = false)
{
    const ON_Curve *geometry = curve.Curve();
    if (geometry == NULL || face == NULL || face->m_face == NULL ||
	!(parameter_tolerance > 0.0) || !std::isfinite(parameter_tolerance))
    {
	return false;
    }

    ON_Interval domain = geometry->Domain();
    domain.MakeIncreasing();
    if (!domain.IsIncreasing()) {
	return false;
    }
    const double curve_parameter = at_start ? domain.Min() : domain.Max();

    int hit_count = 0;
    BooleanInnerLoopEndpoint candidate;
    candidate.m_at_start = at_start;
    BooleanBoundaryEndpointHit hit;
    const auto find_hit = [geometry, curve_parameter, face,
	parameter_tolerance, allow_near_hit, allow_closed_loop_seam](
	    const ON_SimpleArray<ON_Curve *> &boundary,
	    BooleanBoundaryEndpointHit &boundary_hit) -> bool
    {
	if (boolean_find_exact_boundary_endpoint_hit(geometry,
		curve_parameter, boundary, parameter_tolerance, boundary_hit))
	{
	    return true;
	}
	if (allow_near_hit && boolean_find_near_boundary_endpoint_hit(
		geometry, curve_parameter, boundary, face->m_face->SurfaceOf(),
		parameter_tolerance, boundary_hit))
	{
	    return true;
	}
	return allow_closed_loop_seam &&
	    boolean_find_closed_boundary_seam_endpoint_hit(geometry,
		curve_parameter, boundary, face->m_face->SurfaceOf(),
		parameter_tolerance, boundary_hit);
    };
    if (find_hit(face->m_outerloop, hit))
    {
	candidate.m_on_outer_loop = true;
	candidate.m_hit = hit;
	++hit_count;
    }
    for (size_t loop_index = 0; loop_index < face->m_innerloop.size();
	 ++loop_index)
    {
	if (!find_hit(face->m_innerloop[loop_index], hit))
	{
	    continue;
	}
	candidate.m_on_outer_loop = false;
	candidate.m_inner_loop_index = static_cast<int>(loop_index);
	candidate.m_hit = hit;
	++hit_count;
    }

    if (hit_count != 1) {
	return false;
    }
    endpoint = candidate;
    return true;
}


static bool
boolean_append_loop_path(
    LinkedCurve &path,
    const ON_SimpleArray<ON_Curve *> &loop,
    const BooleanBoundaryEndpointHit &from,
    const BooleanBoundaryEndpointHit &to,
    double parameter_tolerance)
{
    if (loop.Count() < 1 || from.m_boundary_curve_index < 0 ||
	from.m_boundary_curve_index >= loop.Count() ||
	to.m_boundary_curve_index < 0 ||
	to.m_boundary_curve_index >= loop.Count())
    {
	return false;
    }

    const auto append_piece = [&path, parameter_tolerance](
	const ON_Curve *curve, double first, double second) -> bool
    {
	if (curve == NULL || !std::isfinite(first) ||
	    !std::isfinite(second) || second < first)
	{
	    return false;
	}
	if (second - first <= parameter_tolerance) {
	    return true;
	}

	std::unique_ptr<ON_Curve> piece;
	ON_Interval domain = curve->Domain();
	domain.MakeIncreasing();
	if (!domain.IsIncreasing() || !domain.Includes(first) ||
	    !domain.Includes(second))
	{
	    return false;
	}
	if (fabs(first - domain.Min()) <= parameter_tolerance &&
	    fabs(second - domain.Max()) <= parameter_tolerance)
	{
	    piece.reset(curve->DuplicateCurve());
	} else {
	    try {
		piece.reset(sub_curve(curve, first, second));
	    } catch (InvalidInterval &) {
		return false;
	    }
	}
	if (!piece || !piece->IsValid()) {
	    return false;
	}
	path.Append(SSICurve(piece.release()));
	return true;
    };

    int curve_index = from.m_boundary_curve_index;
    double curve_parameter = from.m_boundary_parameter;
    bool wrapped = false;
    for (int step = 0; step <= loop.Count(); ++step) {
	const ON_Curve *curve = loop[curve_index];
	if (curve == NULL) {
	    return false;
	}
	ON_Interval domain = curve->Domain();
	domain.MakeIncreasing();
	if (!domain.IsIncreasing() || !domain.Includes(curve_parameter)) {
	    return false;
	}

	const bool at_destination = curve_index ==
	    to.m_boundary_curve_index &&
	    (wrapped || curve_index != from.m_boundary_curve_index ||
	     to.m_boundary_parameter > curve_parameter + parameter_tolerance);
	if (at_destination) {
	    return append_piece(curve, curve_parameter,
		to.m_boundary_parameter);
	}

	if (!append_piece(curve, curve_parameter, domain.Max())) {
	    return false;
	}
	curve_index = (curve_index + 1) % loop.Count();
	if (loop[curve_index] == NULL) {
	    return false;
	}
	curve_parameter = loop[curve_index]->Domain().Min();
	wrapped = true;
	if (curve_index == to.m_boundary_curve_index) {
	    return append_piece(loop[curve_index], curve_parameter,
		to.m_boundary_parameter);
	}
    }
    return false;
}


struct BooleanOuterInnerLoopPair {
    int m_first_curve;
    int m_second_curve;
    BooleanInnerLoopEndpoint m_first_outer;
    BooleanInnerLoopEndpoint m_first_inner;
    BooleanInnerLoopEndpoint m_second_outer;
    BooleanInnerLoopEndpoint m_second_inner;
    bool m_periodic;

    BooleanOuterInnerLoopPair()
	: m_first_curve(-1), m_second_curve(-1), m_periodic(false)
    {}
};


static bool
boolean_certify_outer_inner_loop_pair(
    ON_ClassArray<LinkedCurve> &curves,
    int first_curve_index,
    int second_curve_index,
    const TrimmedFace *face,
    int source_face_index,
    const ON_BoundingBox &model_bounds,
    BooleanOuterInnerLoopPair &candidate)
{
    if (face == NULL || face->m_face == NULL ||
	face->m_innerloop.empty() || first_curve_index < 0 ||
	second_curve_index < 0 || first_curve_index >= curves.Count() ||
	second_curve_index >= curves.Count() ||
	first_curve_index == second_curve_index ||
	curves[first_curve_index].IsClosed() ||
	curves[second_curve_index].IsClosed())
    {
	return false;
    }

    const ON_Surface *surface = face->m_face->SurfaceOf();
    const ON_Curve *first_curve = curves[first_curve_index].Curve();
    const ON_Curve *second_curve = curves[second_curve_index].Curve();
    double first_point_tolerance = 0.0;
    double first_curve_tolerance = 0.0;
    double second_point_tolerance = 0.0;
    double second_curve_tolerance = 0.0;
    if (surface == NULL || first_curve == NULL || second_curve == NULL ||
	!get_face_boundary_curve_tolerances(surface, first_curve,
	    first_point_tolerance, first_curve_tolerance) ||
	!get_face_boundary_curve_tolerances(surface, second_curve,
	    second_point_tolerance, second_curve_tolerance))
    {
	return false;
    }
    const double parameter_tolerance = std::max(first_point_tolerance,
	second_point_tolerance);

    BooleanInnerLoopEndpoint first_endpoints[2];
    BooleanInnerLoopEndpoint second_endpoints[2];
    if (!boolean_find_inner_loop_endpoint(curves[first_curve_index],
	    true, face, parameter_tolerance, first_endpoints[0], false, true) ||
	!boolean_find_inner_loop_endpoint(curves[first_curve_index],
	    false, face, parameter_tolerance, first_endpoints[1], false, true) ||
	!boolean_find_inner_loop_endpoint(curves[second_curve_index],
	    true, face, parameter_tolerance, second_endpoints[0], false, true) ||
	!boolean_find_inner_loop_endpoint(curves[second_curve_index],
	    false, face, parameter_tolerance, second_endpoints[1], false, true))
    {
	return false;
    }

    int first_outer_index = first_endpoints[0].m_on_outer_loop ? 0 : 1;
    int second_outer_index = second_endpoints[0].m_on_outer_loop ? 0 : 1;
    if (first_endpoints[0].m_on_outer_loop ==
	    first_endpoints[1].m_on_outer_loop ||
	second_endpoints[0].m_on_outer_loop ==
	    second_endpoints[1].m_on_outer_loop)
    {
	return false;
    }
    const BooleanInnerLoopEndpoint &first_outer =
	first_endpoints[first_outer_index];
    const BooleanInnerLoopEndpoint &first_inner =
	first_endpoints[1 - first_outer_index];
    const BooleanInnerLoopEndpoint &second_outer =
	second_endpoints[second_outer_index];
    const BooleanInnerLoopEndpoint &second_inner =
	second_endpoints[1 - second_outer_index];
    if (first_inner.m_inner_loop_index < 0 ||
	first_inner.m_inner_loop_index != second_inner.m_inner_loop_index)
    {
	return false;
    }

    BooleanLinkedCurveEndpoint first_outer_provenance;
    BooleanLinkedCurveEndpoint first_inner_provenance;
    BooleanLinkedCurveEndpoint second_outer_provenance;
    BooleanLinkedCurveEndpoint second_inner_provenance;
    if (!boolean_linked_curve_endpoint(curves, first_curve_index,
	    first_outer.m_at_start, first_outer_provenance) ||
	!boolean_linked_curve_endpoint(curves, first_curve_index,
	    first_inner.m_at_start, first_inner_provenance) ||
	!boolean_linked_curve_endpoint(curves, second_curve_index,
	    second_outer.m_at_start, second_outer_provenance) ||
	!boolean_linked_curve_endpoint(curves, second_curve_index,
	    second_inner.m_at_start, second_inner_provenance) ||
	first_outer_provenance.m_source_face_index != source_face_index ||
	first_inner_provenance.m_source_face_index != source_face_index ||
	second_outer_provenance.m_source_face_index != source_face_index ||
	second_inner_provenance.m_source_face_index != source_face_index ||
	first_outer_provenance.m_peer_face_index < 0 ||
	first_outer_provenance.m_peer_face_index !=
	    first_inner_provenance.m_peer_face_index ||
	second_outer_provenance.m_peer_face_index < 0 ||
	second_outer_provenance.m_peer_face_index !=
	    second_inner_provenance.m_peer_face_index)
    {
	return false;
    }

    const ON_3dPoint first_parameter = first_outer.m_hit.m_point;
    const ON_3dPoint second_parameter = second_outer.m_hit.m_point;
    const int first_peer = first_outer_provenance.m_peer_face_index;
    const int second_peer = second_outer_provenance.m_peer_face_index;
    const bool separated_inner_endpoints =
	first_inner.m_hit.m_point.DistanceTo(second_inner.m_hit.m_point) >
	parameter_tolerance;

    bool periodic_pair = false;
    if (first_peer == second_peer && separated_inner_endpoints &&
	(surface->IsClosed(0) || surface->IsClosed(1)))
    {
	int seam_direction = -1;
	for (int direction = 0; direction < 2; ++direction) {
	    if (!surface->IsClosed(direction)) {
		continue;
	    }
	    ON_Interval domain = surface->Domain(direction);
	    domain.MakeIncreasing();
	    const bool opposite = domain.IsIncreasing() &&
		((fabs(first_parameter[direction] - domain.Min()) <=
		      parameter_tolerance &&
		  fabs(second_parameter[direction] - domain.Max()) <=
		      parameter_tolerance) ||
		 (fabs(first_parameter[direction] - domain.Max()) <=
		      parameter_tolerance &&
		  fabs(second_parameter[direction] - domain.Min()) <=
		      parameter_tolerance));
	    if (!opposite || fabs(first_parameter[1 - direction] -
		    second_parameter[1 - direction]) > parameter_tolerance)
	    {
		continue;
	    }
	    if (seam_direction >= 0) {
		return false;
	    }
	    seam_direction = direction;
	}
	const double model_tolerance =
	    boolean_model_repair_tolerance(model_bounds);
	const ON_3dPoint first_model = surface->PointAt(first_parameter.x,
	    first_parameter.y);
	const ON_3dPoint second_model = surface->PointAt(second_parameter.x,
	    second_parameter.y);
	periodic_pair = seam_direction >= 0 && model_tolerance > 0.0 &&
	    first_model.IsValid() && second_model.IsValid() &&
	    first_model.DistanceTo(second_model) <= model_tolerance;
    }

    bool planar_pair = false;
    ON_Plane plane;
    /* Two unique outer-to-inner arcs partition an annular face whether they
     * came from one peer face or two.  Provenance consistency is established
     * per arc above; requiring different peers incorrectly rejects a single
     * periodic cutter crossing the annulus twice. */
    if (!periodic_pair &&
	face->m_innerloop.size() == 1 &&
	curves[first_curve_index].m_ssi_curves.Count() == 1 &&
	curves[second_curve_index].m_ssi_curves.Count() == 1 &&
	surface->IsPlanar(&plane) && separated_inner_endpoints &&
	first_outer.m_hit.m_point.DistanceTo(second_outer.m_hit.m_point) >
	    parameter_tolerance)
    {
	int open_curve_count = 0;
	for (int curve_index = 0; curve_index < curves.Count(); ++curve_index) {
	    if (curves[curve_index].m_ssi_curves.Count() > 0 &&
		!curves[curve_index].IsClosed())
	    {
		++open_curve_count;
	    }
	}
	planar_pair = open_curve_count == 2;
    }
    if (!periodic_pair && !planar_pair) {
	return false;
    }

    candidate.m_first_curve = first_curve_index;
    candidate.m_second_curve = second_curve_index;
    candidate.m_first_outer = first_outer;
    candidate.m_first_inner = first_inner;
    candidate.m_second_outer = second_outer;
    candidate.m_second_inner = second_inner;
    candidate.m_periodic = periodic_pair;
    return true;
}


static bool
close_one_certified_outer_inner_loop_pair(
    ON_ClassArray<LinkedCurve> &curves,
    const TrimmedFace *face,
    int source_face_index,
    const ON_BoundingBox &model_bounds)
{
    std::vector<BooleanOuterInnerLoopPair> candidates;
    std::vector<int> candidate_counts(curves.Count(), 0);
    for (int first_curve = 0; first_curve < curves.Count(); ++first_curve) {
	for (int second_curve = first_curve + 1;
	     second_curve < curves.Count(); ++second_curve)
	{
	    BooleanOuterInnerLoopPair candidate;
	    if (!boolean_certify_outer_inner_loop_pair(curves, first_curve,
		    second_curve, face, source_face_index, model_bounds,
		    candidate))
	    {
		continue;
	    }
	    candidates.push_back(candidate);
	    candidate_counts[first_curve]++;
	    candidate_counts[second_curve]++;
	}
    }

    for (size_t candidate_index = 0; candidate_index < candidates.size();
	 ++candidate_index)
    {
	const BooleanOuterInnerLoopPair &candidate =
	    candidates[candidate_index];
	if (candidate_counts[candidate.m_first_curve] != 1 ||
	    candidate_counts[candidate.m_second_curve] != 1)
	{
	    continue;
	}

	LinkedCurve first = curves[candidate.m_first_curve];
	LinkedCurve second = curves[candidate.m_second_curve];
	if (!candidate.m_first_outer.m_at_start && !first.Reverse()) {
	    return false;
	}
	if (candidate.m_second_outer.m_at_start && !second.Reverse()) {
	    return false;
	}

	const ON_Surface *surface = face->m_face->SurfaceOf();
	double first_point_tolerance = 0.0;
	double first_curve_tolerance = 0.0;
	double second_point_tolerance = 0.0;
	double second_curve_tolerance = 0.0;
	if (!get_face_boundary_curve_tolerances(surface, first.Curve(),
		first_point_tolerance, first_curve_tolerance) ||
	    !get_face_boundary_curve_tolerances(surface, second.Curve(),
		second_point_tolerance, second_curve_tolerance))
	{
	    return false;
	}
	const double parameter_tolerance = std::max(first_point_tolerance,
	    second_point_tolerance);

	LinkedCurve closed;
	closed.Append(first);
	const ON_SimpleArray<ON_Curve *> &inner_loop = face->m_innerloop[
	    candidate.m_first_inner.m_inner_loop_index];
	if (!boolean_append_loop_path(closed, inner_loop,
		candidate.m_first_inner.m_hit,
		candidate.m_second_inner.m_hit, parameter_tolerance))
	{
	    return false;
	}
	closed.Append(second);
	if (!boolean_append_loop_path(closed, face->m_outerloop,
		candidate.m_second_outer.m_hit,
		candidate.m_first_outer.m_hit, parameter_tolerance) ||
	    !closed.IsValid() || !closed.IsClosed())
	{
	    return false;
	}

	ON_SimpleArray<ON_Curve *> loop_segments;
	for (int segment_index = 0;
	     segment_index < closed.m_ssi_curves.Count(); ++segment_index)
	{
	    loop_segments.Append(closed.m_ssi_curves[segment_index].m_curve);
	}
	if (!is_loop_valid(loop_segments, ON_ZERO_TOLERANCE) ||
	    loop_is_degenerate(loop_segments))
	{
	    return false;
	}

	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Closed %s Boolean SSI fragments %d/%d on source face %d "
		"through inner loop %d.\n",
		candidate.m_periodic ? "periodic" : "planar annular",
		candidate.m_first_curve, candidate.m_second_curve,
		source_face_index,
		candidate.m_first_inner.m_inner_loop_index);
	}
	curves[candidate.m_first_curve] = closed;
	curves[candidate.m_second_curve].Empty();
	return true;
    }
    return false;
}


/* A later Boolean can cut across a hole created by an earlier operation.  In
 * that case one open SSI chain can have both endpoints in the interior of the
 * same existing inner loop.  The outer-loop splitter cannot close that chain,
 * and retaining the original inner loop leaves the adjacent source face with
 * a full edge opposite a genuinely partial edge.
 *
 * Close only a chain whose two boundary hits and SSI provenance are
 * unambiguous.  Following the inner loop from the SSI end back to its start
 * replaces the affected portion of the old hole boundary with the new cut;
 * it does not bridge or erase any model-space gap.
 */
static bool
close_one_certified_inner_loop_chain(
    ON_ClassArray<LinkedCurve> &curves,
    const TrimmedFace *face,
    int source_face_index)
{
    if (face == NULL || face->m_face == NULL || face->m_innerloop.empty()) {
	return false;
    }

    const ON_Surface *surface = face->m_face->SurfaceOf();
    if (surface == NULL) {
	return false;
    }

    for (int curve_index = 0; curve_index < curves.Count(); ++curve_index) {
	LinkedCurve &curve = curves[curve_index];
	const ON_Curve *geometry = curve.Curve();
	double point_tolerance = 0.0;
	double curve_tolerance = 0.0;
	if (geometry == NULL || curve.IsClosed() ||
	    !get_face_boundary_curve_tolerances(surface, geometry,
		point_tolerance, curve_tolerance))
	{
	    continue;
	}

	BooleanInnerLoopEndpoint endpoints[2];
	const bool found_start = boolean_find_inner_loop_endpoint(
	    curve, true, face, point_tolerance, endpoints[0], true);
	const bool found_end = boolean_find_inner_loop_endpoint(
	    curve, false, face, point_tolerance, endpoints[1], true);
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Inner-loop SSI candidate %d on source face %d: endpoints "
		"found %d/%d, outer %d/%d, loops %d/%d, tolerance %.17g.\n",
		curve_index, source_face_index, found_start, found_end,
		found_start ? endpoints[0].m_on_outer_loop : -1,
		found_end ? endpoints[1].m_on_outer_loop : -1,
		found_start ? endpoints[0].m_inner_loop_index : -1,
		found_end ? endpoints[1].m_inner_loop_index : -1,
		point_tolerance);
	}
	if (!found_start || !found_end ||
	    endpoints[0].m_on_outer_loop || endpoints[1].m_on_outer_loop ||
	    endpoints[0].m_inner_loop_index < 0 ||
	    endpoints[0].m_inner_loop_index !=
		endpoints[1].m_inner_loop_index ||
	    endpoints[0].m_hit.m_point.DistanceTo(
		endpoints[1].m_hit.m_point) <= point_tolerance)
	{
	    continue;
	}

	int peer_face_index = -1;
	bool provenance_is_consistent = curve.m_ssi_curves.Count() > 0;
	for (int segment_index = 0;
	     provenance_is_consistent &&
		 segment_index < curve.m_ssi_curves.Count();
	     ++segment_index)
	{
	    const SSICurve &segment = curve.m_ssi_curves[segment_index];
	    if (segment.m_curve == NULL ||
		segment.m_source_face_index != source_face_index ||
		segment.m_peer_face_index < 0 ||
		(peer_face_index >= 0 &&
		 segment.m_peer_face_index != peer_face_index))
	    {
		provenance_is_consistent = false;
		break;
	    }
	    peer_face_index = segment.m_peer_face_index;
	}
	if (!provenance_is_consistent || peer_face_index < 0) {
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Inner-loop SSI candidate %d on source face %d rejected "
		    "for inconsistent provenance (peer %d).\n", curve_index,
		    source_face_index, peer_face_index);
	    }
	    continue;
	}

	LinkedCurve closed;
	for (int segment_index = 0;
	     segment_index < curve.m_ssi_curves.Count(); ++segment_index)
	{
	    const SSICurve &source_segment = curve.m_ssi_curves[segment_index];
	    std::unique_ptr<ON_Curve> snapped(
		source_segment.m_curve->DuplicateCurve());
	    const bool snap_start = segment_index == 0;
	    const bool snap_end =
		segment_index == curve.m_ssi_curves.Count() - 1;
	    if (!snapped ||
		(snap_start &&
		 !snapped->SetStartPoint(endpoints[0].m_hit.m_point)) ||
		(snap_end && !snapped->SetEndPoint(endpoints[1].m_hit.m_point)) ||
		!snapped->IsValid())
	    {
		closed.Empty();
		break;
	    }
	    closed.Append(SSICurve(snapped.release(),
		source_segment.m_source_face_index,
		source_segment.m_peer_face_index));
	}
	if (!closed.IsValid()) {
	    continue;
	}
	const ON_SimpleArray<ON_Curve *> &inner_loop =
	    face->m_innerloop[endpoints[0].m_inner_loop_index];
	const bool appended = boolean_append_loop_path(closed, inner_loop,
	    endpoints[1].m_hit, endpoints[0].m_hit, point_tolerance);
	const bool valid = appended && closed.IsValid();
	const bool is_closed = valid && closed.IsClosed();
	if (!appended || !valid || !is_closed)
	{
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Inner-loop SSI candidate %d on source face %d could not "
		    "close: appended %d, valid %d, closed %d.\n", curve_index,
		    source_face_index, appended, valid, is_closed);
	    }
	    continue;
	}

	ON_SimpleArray<ON_Curve *> loop_segments;
	for (int segment_index = 0;
	     segment_index < closed.m_ssi_curves.Count(); ++segment_index)
	{
	    loop_segments.Append(closed.m_ssi_curves[segment_index].m_curve);
	}
	if (!is_loop_valid(loop_segments, ON_ZERO_TOLERANCE) ||
	    loop_is_degenerate(loop_segments))
	{
	    continue;
	}

	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Closed Boolean SSI chain %d on source face %d through "
		"inner loop %d (peer face %d).\n", curve_index,
		source_face_index, endpoints[0].m_inner_loop_index,
		peer_face_index);
	}
	curves[curve_index] = closed;
	return true;
    }
    return false;
}


static ON_ClassArray<LinkedCurve>
link_curves(
    const ON_ClassArray<SSICurve> &in,
    const TrimmedFace *face,
    int source_face_index,
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    const ON_BoundingBox &model_bounds)
{
    // There might be two reasons why we need to link these curves.
    // 1) They are from intersections with two different surfaces.
    // 2) They are not continuous in the other surface's UV domain.

	ON_ClassArray<LinkedCurve> tmp = get_joinable_ssi_curves(in);

    // As usual, we use a greedy approach.
    for (int i = 0; i < tmp.Count(); i++) {
	for (int j = 0; j < tmp.Count(); j++) {
	    if (tmp[i].m_ssi_curves.Count() == 0 || tmp[i].IsClosed()) {
		break;
	    }

	    if (tmp[j].m_ssi_curves.Count() == 0 || tmp[j].IsClosed() || j == i) {
		continue;
	    }
	    LinkedCurve *c1 = NULL, *c2 = NULL;
	    double dist = configure_for_linking(c1, c2, tmp[i], tmp[j]);

	    if (dist > INTERSECTION_TOL) {
		continue;
	    }

	    if (c1 != NULL && c2 != NULL) {
		LinkedCurve new_curve;
		new_curve.Append(*c1);
		if (dist > ON_ZERO_TOLERANCE) {
		    /* FIXME: memory leak, we never delete the ON_LineCurve */
		    new_curve.Append(SSICurve(new ON_LineCurve(c1->PointAtEnd(), c2->PointAtStart())));
		}
		new_curve.Append(*c2);
		tmp[i] = new_curve;
		tmp[j].Empty();
	    }

	    // Check whether tmp[i] is closed within a tolerance
	    if (tmp[i].PointAtStart().DistanceTo(tmp[i].PointAtEnd()) < INTERSECTION_TOL && !tmp[i].IsClosed()) {
		// make IsClosed() true
		/* FIXME: memory leak, we never delete the ON_LineCurve */
		tmp[i].Append(SSICurve(new ON_LineCurve(tmp[i].PointAtEnd(), tmp[i].PointAtStart())));
	    }

	}

	if (tmp[i].m_ssi_curves.Count() != 0 && !tmp[i].IsClosed() &&
	    tmp[i].PointAtStart().DistanceTo(tmp[i].PointAtEnd()) <
	    ON_ZERO_TOLERANCE)
	{
	    tmp[i].CloseNearZeroGap();
	}

    }

    while (link_one_certified_periodic_boundary_chain(tmp, face,
	source_face_index, model_bounds))
    {
	/* Recompute uniqueness after every certified merge. */
    }

    while (link_one_certified_source_edge_gap(tmp, face, source_face_index,
	brep1, brep2, model_bounds))
    {
	/* Recompute candidates after every merge so endpoint uniqueness remains
	 * a property of the current set of open chains. */
    }

    for (int curve_index = 0; curve_index < tmp.Count(); ++curve_index) {
	normalize_periodic_isoparametric_linked_curve(tmp[curve_index],
	    face && face->m_face ? face->m_face->SurfaceOf() : NULL,
	    model_bounds);
    }

    while (close_one_certified_lifted_endpoint_loop_pair(tmp, face,
	source_face_index, model_bounds))
    {
	/* Recompute uniqueness after every model-space-certified closure. */
    }

    while (close_one_certified_outer_inner_loop_pair(tmp, face,
	source_face_index, model_bounds))
    {
	/* Recompute pair uniqueness after every closed annular partition. */
    }

    while (close_one_certified_inner_loop_chain(tmp, face,
	source_face_index))
    {
	/* Recompute after every closure because closed chains are no longer
	 * candidates for attachment to an existing inner loop. */
    }

    for (int curve_index = 0; curve_index < tmp.Count(); ++curve_index) {
	if (reduce_periodic_isoparametric_retrace(tmp[curve_index], face,
		model_bounds) && DEBUG_BREP_BOOLEAN)
	{
	    bu_log("Reduced a closed periodic isoparametric SSI retrace on "
		"source face %d to one seam-to-seam curve.\n",
		source_face_index);
	}
    }

    certify_paired_closed_surface_seam_curves(tmp, face, source_face_index,
	model_bounds);

    // Append the remaining curves to out.
    ON_ClassArray<LinkedCurve> out;
    for (int i = 0; i < tmp.Count(); i++) {
	if (tmp[i].m_ssi_curves.Count() != 0) {
	    out.Append(tmp[i]);
	}
    }

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("link_curves(): %d curves remaining.\n", out.Count());
    }

    return out;
}


class BooleanLoopTolerance {
public:
    const ON_Surface *surface;
    double point;
    double curve_parameter;

    BooleanLoopTolerance(const ON_Surface *parameter_surface = NULL)
	: surface(parameter_surface), point(INTERSECTION_TOL),
	  curve_parameter(INTERSECTION_TOL)
    {
    }
};


static bool
update_boolean_loop_tolerance(
    const ON_Surface *surface,
    const ON_SimpleArray<ON_Curve *> &loop,
    BooleanLoopTolerance &tolerance)
{
    if (surface == NULL || loop.Count() < 1) {
	return false;
    }

    for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	double point_tolerance = 0.0;
	double curve_parameter_tolerance = 0.0;
	if (!get_face_boundary_curve_tolerances(surface, loop[curve_index],
		point_tolerance, curve_parameter_tolerance))
	{
	    return false;
	}
	tolerance.point = std::min(tolerance.point, point_tolerance);
	tolerance.curve_parameter = std::min(tolerance.curve_parameter,
	    curve_parameter_tolerance);
    }

    return true;
}


static BooleanLoopTolerance
boolean_loop_tolerance_for_surface(
    const ON_Surface *surface,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop)
{
    BooleanLoopTolerance metric_tolerance(surface);
    if (update_boolean_loop_tolerance(surface, first_loop, metric_tolerance) &&
	update_boolean_loop_tolerance(surface, second_loop, metric_tolerance))
    {
	return metric_tolerance;
    }

    // Preserve legacy scalar tolerances while retaining the surface needed to
    // certify parameter-space intersections.
    return BooleanLoopTolerance(surface);
}


static bool
boolean_intersection_event_endpoint_has_shared_surface_point(
    const ON_X_EVENT &event,
    int endpoint,
    const BooleanLoopTolerance &tolerance)
{
    if (endpoint < 0 || endpoint > 1) {
	return false;
    }
    if (tolerance.surface == NULL) {
	return true;
    }

    const ON_3dPoint first_point = tolerance.surface->PointAt(
	event.m_A[endpoint].x, event.m_A[endpoint].y);
    const ON_3dPoint second_point = tolerance.surface->PointAt(
	event.m_B[endpoint].x, event.m_B[endpoint].y);
    return first_point.IsValid() && second_point.IsValid() &&
	first_point.DistanceTo(second_point) <= INTERSECTION_TOL;
}


static bool
boolean_intersection_event_has_shared_surface_point(
    const ON_X_EVENT &event,
    const BooleanLoopTolerance &tolerance)
{
    return boolean_intersection_event_endpoint_has_shared_surface_point(event,
	0, tolerance);
}


static bool
is_point_on_loop_on_surface(
    const ON_2dPoint &point,
    const ON_SimpleArray<ON_Curve *> &loop,
    double intersection_tolerance,
    const ON_Surface *surface)
{
    if (surface == NULL) {
	return is_point_on_loop(point, loop, intersection_tolerance);
    }
    if (!(intersection_tolerance > 0.0) ||
	!std::isfinite(intersection_tolerance))
    {
	throw InvalidGeometry("is_point_on_loop() given invalid tolerance\n");
    }

    const ON_3dPoint lifted_point = surface->PointAt(point.x, point.y);
    if (!lifted_point.IsValid()) {
	return false;
    }
    const ON_3dPoint point3d(point);
    const double candidate_parameter_tolerance = std::max(
	intersection_tolerance, INTERSECTION_TOL);
    const auto point_on_curves = [&](const ON_SimpleArray<ON_Curve *> &curves) {
	for (int curve_index = 0; curve_index < curves.Count(); ++curve_index) {
	if (curves[curve_index] == NULL) {
	    continue;
	}
	    ON_ClassArray<ON_PX_EVENT> events;
	    if (ON_Intersect(point3d, *curves[curve_index], events,
		    candidate_parameter_tolerance))
	    {
		for (int event_index = 0; event_index < events.Count();
		     ++event_index)
		{
		    const ON_3dPoint event_point(events[event_index].m_B);
		    const ON_3dPoint lifted_curve_point = surface->PointAt(
			event_point.x, event_point.y);
		    if (lifted_curve_point.IsValid() &&
			lifted_point.DistanceTo(lifted_curve_point) <=
			    INTERSECTION_TOL)
		    {
			return true;
		    }
		}
	    }

	    /* ON_Intersect can omit a point lying on a curve endpoint or on a
	     * numerically coincident span.  Keep the closest-point search as a
	     * recovery path, after the substantially cheaper ordinary query. */
	    double closest_parameter = ON_UNSET_VALUE;
	    if (point_3d_to_curve_parameter_with_tolerance(point3d,
		    curves[curve_index], candidate_parameter_tolerance,
		    closest_parameter, false))
	    {
		const ON_3dPoint curve_point = curves[curve_index]->PointAt(
		    closest_parameter);
		const ON_3dPoint lifted_curve_point = surface->PointAt(
		    curve_point.x, curve_point.y);
		if (lifted_curve_point.IsValid() &&
		    lifted_point.DistanceTo(lifted_curve_point) <=
			INTERSECTION_TOL)
		{
		    return true;
		}
	    }
	}
	return false;
    };

    // A normalized periodic loop may move a seam to the opposite side of the
    // surface domain.  Preserve raw trim membership before classifying with
    // the normalized loop.
    if (point_on_curves(loop)) {
	return true;
    }

    NormalizedBooleanLoop normalized_loop;
    const ON_SimpleArray<ON_Curve *> &classification_loop =
	normalized_loop_for_point_classification(loop, intersection_tolerance,
	    normalized_loop, surface,
	    boolean_loop_closure_tolerance(INTERSECTION_TOL));

    ON_PolyCurve polycurve;
    if (!is_loop_valid(classification_loop, ON_ZERO_TOLERANCE, &polycurve)) {
	bu_log("is_point_on_loop_on_surface(): classification tolerance %.17g, "
	    "closure tolerance %.17g, %d curves.\n",
	    intersection_tolerance,
	    boolean_loop_closure_tolerance(intersection_tolerance),
	    classification_loop.Count());
	for (int curve_index = 0; curve_index < classification_loop.Count();
	     ++curve_index)
	{
	    const ON_Curve *curve = classification_loop[curve_index];
	    const ON_Curve *next_curve = classification_loop[
		(curve_index + 1) % classification_loop.Count()];
	    if (curve == NULL || next_curve == NULL)
		continue;
	    const ON_3dPoint end = curve->PointAtEnd();
	    const ON_3dPoint start = next_curve->PointAtStart();
	    const ON_3dPoint end_3d = surface->PointAt(end.x, end.y);
	    const ON_3dPoint start_3d = surface->PointAt(start.x, start.y);
	    bu_log("  loop gap %d/%d: parameter %.17g, model %.17g.\n",
		curve_index, (curve_index + 1) % classification_loop.Count(),
		end.DistanceTo(start), end_3d.DistanceTo(start_3d));
	}
	throw InvalidGeometry("is_point_on_loop() given invalid loop\n");
    }
    return point_on_curves(classification_loop);
}


class CurvePoint {
public:
    static constexpr size_t UNSET_NODE = std::numeric_limits<size_t>::max();

    int source_loop;
    int loop_index;
    double curve_t;
    ON_2dPoint pt;
    BooleanLoopTolerance tolerance;
    size_t node_id;

    enum Location {
	BOUNDARY,
	INSIDE,
	OUTSIDE
    } location;

    static CurvePoint::Location
    PointLoopLocation(
	ON_2dPoint pt,
	const ON_SimpleArray<ON_Curve *> &loop,
	const BooleanLoopTolerance &tolerance);

    CurvePoint(
	int loop,
	int li,
	double pt_t,
	ON_Curve *curve,
	const ON_SimpleArray<ON_Curve *> &other_loop,
	const BooleanLoopTolerance &loop_tolerance)
	: source_loop(loop), loop_index(li), curve_t(pt_t),
	  tolerance(loop_tolerance), node_id(UNSET_NODE)
    {
	pt = curve->PointAt(curve_t);
	location = PointLoopLocation(pt, other_loop, tolerance);
    }

    CurvePoint(
	int loop,
	int li,
	double t,
	ON_2dPoint p,
	CurvePoint::Location l,
	const BooleanLoopTolerance &loop_tolerance)
	: source_loop(loop), loop_index(li), curve_t(t), pt(p), location(l),
	  tolerance(loop_tolerance), node_id(UNSET_NODE)
    {
    }

    bool
    operator<(const CurvePoint &other) const
    {
	if (source_loop != other.source_loop) {
	    return source_loop < other.source_loop;
	}

	if (loop_index != other.loop_index) {
	    return loop_index < other.loop_index;
	}

	return curve_t < other.curve_t;
    }

    bool
    HasSameCurveParameter(const CurvePoint &other) const
    {
	if (source_loop != other.source_loop || loop_index != other.loop_index) {
	    return false;
	}

	const double parameter_tolerance = std::max(
	    tolerance.curve_parameter, other.tolerance.curve_parameter);
	return ON_NearZero(curve_t - other.curve_t, parameter_tolerance) &&
	    *this == other;
    }

    bool
    operator==(const CurvePoint &other) const
    {
	const double point_tolerance = std::max(tolerance.point,
	    other.tolerance.point);
	if (!ON_NearZero(pt.DistanceTo(other.pt), point_tolerance)) {
	    return false;
	}

	if (tolerance.surface != other.tolerance.surface) {
	    return false;
	}
	if (tolerance.surface == NULL) {
	    return true;
	}

	const ON_3dPoint first_point = tolerance.surface->PointAt(pt.x, pt.y);
	const ON_3dPoint second_point = tolerance.surface->PointAt(other.pt.x,
	    other.pt.y);
	return first_point.IsValid() && second_point.IsValid() &&
	    first_point.DistanceTo(second_point) <= INTERSECTION_TOL;
    }

    bool
    operator!=(const CurvePoint &other) const
    {
	return !(*this == other);
    }

    bool
    HasSameTopologyNode(const CurvePoint &other) const
    {
	if (node_id != UNSET_NODE && other.node_id != UNSET_NODE) {
	    return node_id == other.node_id;
	}
	return *this == other;
    }
};


class BooleanArrangementNodes {
public:
    size_t
    Node(const CurvePoint &point)
    {
	for (size_t reference_index = 0;
	     reference_index < m_references.size(); ++reference_index)
	{
	    const CurvePoint &reference = m_references[reference_index];
	    const double parameter_scale = std::max(1.0, std::max(
		fabs(reference.curve_t), fabs(point.curve_t)));
	    const double parameter_tolerance = std::max(std::max(
		reference.tolerance.curve_parameter,
		point.tolerance.curve_parameter),
		8.0 * ON_EPSILON * parameter_scale);
	    if (reference.source_loop == point.source_loop &&
		reference.loop_index == point.loop_index &&
		ON_NearZero(reference.curve_t - point.curve_t,
		    parameter_tolerance) && reference == point)
	    {
		return Find(reference.node_id);
	    }
	}

	const size_t node_id = m_parents.size();
	m_parents.push_back(node_id);
	CurvePoint reference(point);
	reference.node_id = node_id;
	m_references.push_back(reference);
	return node_id;
    }

    void
    Join(size_t first_node, size_t second_node)
    {
	const size_t first_root = Find(first_node);
	const size_t second_root = Find(second_node);
	if (first_root != second_root) {
	    m_parents[second_root] = first_root;
	}
    }

    bool
    JoinWithinTolerance(size_t first_node, size_t second_node,
	double tolerance_multiplier)
    {
	const size_t first_root = Find(first_node);
	const size_t second_root = Find(second_node);
	if (first_root == CurvePoint::UNSET_NODE ||
	    second_root == CurvePoint::UNSET_NODE ||
	    !(tolerance_multiplier > 0.0) ||
	    !std::isfinite(tolerance_multiplier))
	{
	    return false;
	}
	if (first_root == second_root) {
	    return true;
	}

	/* A sequence of individually short arcs must not grow one topology node
	 * without bound through union-find transitivity.  Admit a merge only when
	 * every registered point in the two existing clusters remains within the
	 * same metric bound. */
	for (size_t first_index = 0; first_index < m_references.size();
	     ++first_index)
	{
	    const CurvePoint &first = m_references[first_index];
	    if (Find(first.node_id) != first_root) {
		continue;
	    }
	    for (size_t second_index = 0; second_index < m_references.size();
		 ++second_index)
	    {
		const CurvePoint &second = m_references[second_index];
		if (Find(second.node_id) != second_root ||
		    !first.pt.IsValid() || !second.pt.IsValid() ||
		    first.tolerance.surface != second.tolerance.surface)
		{
		    if (Find(second.node_id) == second_root &&
			(!first.pt.IsValid() || !second.pt.IsValid() ||
			 first.tolerance.surface != second.tolerance.surface))
		    {
			return false;
		    }
		    continue;
		}

		double distance = first.pt.DistanceTo(second.pt);
		double maximum_distance = tolerance_multiplier * std::max(
		    first.tolerance.point, second.tolerance.point);
		if (first.tolerance.surface != NULL) {
		    const ON_3dPoint first_model = first.tolerance.surface->PointAt(
			first.pt.x, first.pt.y);
		    const ON_3dPoint second_model = second.tolerance.surface->PointAt(
			second.pt.x, second.pt.y);
		    if (!first_model.IsValid() || !second_model.IsValid()) {
			return false;
		    }
		    distance = first_model.DistanceTo(second_model);
		    maximum_distance = tolerance_multiplier * INTERSECTION_TOL;
		}
		if (!std::isfinite(distance) || !std::isfinite(maximum_distance) ||
		    distance > maximum_distance)
		{
		    return false;
		}
	    }
	}

	m_parents[second_root] = first_root;
	return true;
    }

    size_t
    Canonical(size_t node_id)
    {
	return Find(node_id);
    }

private:
    size_t
    Find(size_t node_id)
    {
	if (node_id >= m_parents.size()) {
	    return CurvePoint::UNSET_NODE;
	}
	if (m_parents[node_id] != node_id) {
	    m_parents[node_id] = Find(m_parents[node_id]);
	}
	return m_parents[node_id];
    }

    std::vector<size_t> m_parents;
    std::vector<CurvePoint> m_references;
};


CurvePoint::Location
CurvePoint::PointLoopLocation(
    ON_2dPoint point,
    const ON_SimpleArray<ON_Curve *> &loop,
    const BooleanLoopTolerance &tolerance)
{
    if (is_point_on_loop_on_surface(point, loop, tolerance.point,
	tolerance.surface)) {
	return CurvePoint::BOUNDARY;
    }

    if (point_loop_location(point, loop, tolerance.point,
	    tolerance.surface) ==
	OUTSIDE_OR_ON_LOOP)
    {
	return CurvePoint::OUTSIDE;
    }
    return CurvePoint::INSIDE;
}


class CurveSegment {
public:
    ON_SimpleArray<ON_Curve *> orig_loop;
    CurvePoint from, to;
    BooleanLoopTolerance tolerance;
    bool reversed;
    enum Location {
	BOUNDARY,
	INSIDE,
	OUTSIDE
    } location;

    CurveSegment(
	ON_SimpleArray<ON_Curve *> &loop,
	CurvePoint f,
	CurvePoint t,
	CurveSegment::Location l)
	: orig_loop(loop), from(f), to(t), tolerance(f.tolerance),
	  reversed(false), location(l)
    {
	if (!orig_loop.Capacity()) {
	    size_t c = (from.loop_index > to.loop_index) ? from.loop_index : to.loop_index;
	    orig_loop.SetCapacity(c + 1);
	}
    }

    void
    Reverse(void)
    {
	std::swap(from, to);
	reversed = !reversed;
    }

    ON_Curve *
    Curve(void) const
    {
	if (reversed) {
	    CurveSegment forward(*this);
	    std::swap(forward.from, forward.to);
	    forward.reversed = false;
	    ON_Curve *curve = forward.Curve();
	    if (curve == NULL || !curve->Reverse()) {
		delete curve;
		return NULL;
	    }
	    return curve;
	}

	ON_Curve *from_curve = orig_loop[from.loop_index];
	ON_Curve *to_curve = orig_loop[to.loop_index];
	ON_Interval from_dom = from_curve->Domain();
	ON_Interval to_dom = to_curve->Domain();

	// if endpoints are on the same curve, just get the part between them
	if (from.loop_index == to.loop_index) {
	    ON_Curve *seg_curve =
		sub_curve(from_curve, from.curve_t, to.curve_t);
	    return seg_curve;
	}
	// if endpoints are on different curves, we may need a subcurve of
	// just the 'from' curve, just the 'to' curve, or both
	if (ON_NearZero(from.curve_t - from_dom.m_t[1],
		tolerance.curve_parameter)) {
	    // starting at end of 'from' same as starting at start of 'to'
	    ON_Curve *seg_curve = sub_curve(to_curve, to_dom.m_t[0],
					    to.curve_t);
	    return seg_curve;
	}
	if (ON_NearZero(to.curve_t - to_dom.m_t[0],
		tolerance.curve_parameter)) {
	    // ending at start of 'to' same as ending at end of 'from'
	    ON_Curve *seg_curve = sub_curve(from_curve, from.curve_t,
					    from_dom.m_t[1]);
	    return seg_curve;
	}
	ON_PolyCurve *pcurve = new ON_PolyCurve();
	append_to_polycurve(sub_curve(from_curve, from.curve_t,
				      from_dom.m_t[1]), *pcurve);
	append_to_polycurve(sub_curve(to_curve, to_dom.m_t[0], to.curve_t),
			    *pcurve);
	return pcurve;
    }

    bool
    IsDegenerate(bool *certified_tolerance_scale = NULL,
	double tolerance_multiplier = 1.0)
    {
	if (certified_tolerance_scale != NULL) {
	    *certified_tolerance_scale = false;
	}
	std::unique_ptr<ON_Curve> segment_curve;
	try {
	    segment_curve.reset(Curve());
	} catch (InvalidInterval &) {
	    return true;
	}
	if (!segment_curve) {
	    return true;
	}

	const ON_Curve *metric_curve = segment_curve.get();
	double metric_tolerance = tolerance.point;
	std::unique_ptr<ON_Curve> lifted_curve;
	if (tolerance.surface != NULL) {
	    // Parameter distance does not bound physical extent on distorted
	    // surfaces, so use the lifted curve to preserve meaningful cuts.
	    lifted_curve.reset(pushup_boolean_curve(tolerance.surface,
		*segment_curve));
	    if (!lifted_curve) {
		return false;
	    }
	    metric_curve = lifted_curve.get();
	    metric_tolerance = INTERSECTION_TOL;
	}

	double extent = 0.0;
	if (metric_curve->IsLinear(metric_tolerance)) {
	    extent = metric_curve->PointAtStart().DistanceTo(
		metric_curve->PointAtEnd());
	} else {
	    double min[3] = {0.0, 0.0, 0.0};
	    double max[3] = {0.0, 0.0, 0.0};

	    if (!metric_curve->GetBBox(min, max, true)) {
		return false;
	    }
	    extent = DIST_PNT_PNT(min, max);
	}
	const double extent_tolerance = metric_tolerance * tolerance_multiplier;
	const bool is_tolerance_scale = tolerance_multiplier > 0.0 &&
	    std::isfinite(extent_tolerance) && extent < extent_tolerance;
	if (certified_tolerance_scale != NULL) {
	    *certified_tolerance_scale = is_tolerance_scale;
	}
	return is_tolerance_scale;
    }

    bool
    operator<(const CurveSegment &other) const
    {
	return from < other.from;
    }
};


class BooleanOverlapSpan {
public:
    int first_curve_index;
    int second_curve_index;
    ON_Interval first_parameters;
    ON_Interval second_parameters;
    ON_2dPoint first_points[2];
    ON_2dPoint second_points[2];
    double first_parameter_tolerance;
    double second_parameter_tolerance;

    BooleanOverlapSpan(int first_curve, int second_curve,
	const ON_X_EVENT &event)
	: first_curve_index(first_curve), second_curve_index(second_curve),
	  first_parameters(event.m_a[0], event.m_a[1]),
	  second_parameters(event.m_b[0], event.m_b[1]),
	  first_parameter_tolerance(0.0), second_parameter_tolerance(0.0)
    {
	first_points[0] = event.m_A[0];
	first_points[1] = event.m_A[1];
	second_points[0] = event.m_B[0];
	second_points[1] = event.m_B[1];
	/* Keep each parameter paired with the point evaluated at that
	 * parameter.  ON_X_EVENT overlap intervals may be decreasing when the
	 * two curves have opposite directions.  Sorting only the interval swaps
	 * its parameter endpoints without swapping the corresponding UV points;
	 * endpoint normalization can then join the wrong topology nodes and
	 * inflate the span tolerance until adjacent segments look coincident. */
	if (first_parameters.IsDecreasing()) {
	    first_parameters.MakeIncreasing();
	    std::swap(first_points[0], first_points[1]);
	}
	if (second_parameters.IsDecreasing()) {
	    second_parameters.MakeIncreasing();
	    std::swap(second_points[0], second_points[1]);
	}
    }

    void
    NormalizeEndpoints(std::multiset<CurvePoint> &first_curve_points,
	std::multiset<CurvePoint> &second_curve_points,
	BooleanArrangementNodes &nodes)
    {
	NormalizeEndpoints(1, first_curve_index, first_parameters, first_points,
	    first_parameter_tolerance, first_curve_points, nodes);
	NormalizeEndpoints(2, second_curve_index, second_parameters,
	    second_points, second_parameter_tolerance, second_curve_points,
	    nodes);
    }

    bool
    Contains(const CurveSegment &segment) const
    {
	if (segment.from.loop_index != segment.to.loop_index) {
	    return false;
	}

	const ON_Interval &parameters = segment.from.source_loop == 1 ?
	    first_parameters : second_parameters;
	const int span_curve_index = segment.from.source_loop == 1 ?
	    first_curve_index : second_curve_index;
	if (segment.from.loop_index != span_curve_index) {
	    return false;
	}

	const double span_parameter_tolerance = segment.from.source_loop == 1 ?
	    first_parameter_tolerance : second_parameter_tolerance;
	const double parameter_scale = std::max(1.0, std::max(
	    fabs(parameters.Min()), fabs(parameters.Max())));
	const double parameter_tolerance = std::max(
	    std::max(segment.tolerance.curve_parameter, span_parameter_tolerance),
	    16.0 * ON_ZERO_TOLERANCE * parameter_scale);
	return segment.from.curve_t >= parameters.Min() - parameter_tolerance &&
	    segment.from.curve_t <= parameters.Max() + parameter_tolerance &&
	    segment.to.curve_t >= parameters.Min() - parameter_tolerance &&
	    segment.to.curve_t <= parameters.Max() + parameter_tolerance;
    }

private:
    static void
    NormalizeEndpoints(int source_loop, int curve_index,
	ON_Interval &parameters, const ON_2dPoint points[2],
	double &parameter_tolerance, std::multiset<CurvePoint> &curve_points,
	BooleanArrangementNodes &nodes)
    {
	for (int endpoint_index = 0; endpoint_index < 2; ++endpoint_index) {
	    for (std::multiset<CurvePoint>::const_iterator candidate =
		 curve_points.begin(); candidate != curve_points.end(); ++candidate)
	    {
		if (candidate->source_loop != source_loop ||
		    candidate->loop_index != curve_index)
		{
		    continue;
		}

		CurvePoint endpoint(source_loop, curve_index,
		    parameters[endpoint_index], points[endpoint_index],
		    CurvePoint::BOUNDARY, candidate->tolerance);
		if (!(endpoint == *candidate)) {
		    continue;
		}

		const size_t endpoint_node = nodes.Node(endpoint);
		nodes.Join(endpoint_node, candidate->node_id);
		const double parameter_difference = fabs(candidate->curve_t -
		    parameters[endpoint_index]);
		const double parameter_scale = std::max(1.0, std::max(
		    fabs(candidate->curve_t),
		    fabs(parameters[endpoint_index])));
		const double parameter_match_tolerance = std::max(
		    candidate->tolerance.curve_parameter,
		    16.0 * ON_ZERO_TOLERANCE * parameter_scale);
		/* A closed curve's domain endpoints are the same topology point but
		 * are a full parameter period apart.  Join those topology nodes, but
		 * do not expand the overlap interval by that period. */
		if (parameter_difference <= parameter_match_tolerance) {
		    parameter_tolerance = std::max(parameter_tolerance,
			parameter_difference);
		}
	    }
	}
    }

};


static bool
overlap_event_covers_curve_domains(const ON_X_EVENT &event,
    const ON_Curve *first_curve, const ON_Curve *second_curve,
    double first_parameter_tolerance, double second_parameter_tolerance);


static int
arrangement_segment_node_orientation(const CurveSegment &first,
    const CurveSegment &second)
{
    if (first.from.HasSameTopologyNode(second.from) &&
	first.to.HasSameTopologyNode(second.to))
    {
	return 1;
    }
    if (first.from.HasSameTopologyNode(second.to) &&
	first.to.HasSameTopologyNode(second.from))
    {
	return -1;
    }
    return 0;
}


static bool
arrangement_segments_share_overlap_span(const CurveSegment &first,
    const CurveSegment &second,
    const std::vector<BooleanOverlapSpan> &spans)
{
    if (first.from.source_loop == second.from.source_loop) {
	return false;
    }
    for (size_t span_index = 0; span_index < spans.size(); ++span_index) {
	if (spans[span_index].Contains(first) &&
	    spans[span_index].Contains(second))
	{
	    return true;
	}
    }
    return false;
}


static bool
arrangement_curves_have_certified_model_coincidence(
    const CurveSegment &first,
    const ON_Curve &first_curve,
    const CurveSegment &second,
    const ON_Curve &second_curve,
    int node_orientation)
{
    if (node_orientation == 0 || first.tolerance.surface == NULL ||
	second.tolerance.surface == NULL)
    {
	return false;
    }

    std::unique_ptr<ON_Curve> first_lifted(pushup_boolean_trim_curve(
	first.tolerance.surface, first_curve));
    std::unique_ptr<ON_Curve> second_lifted(pushup_boolean_trim_curve(
	second.tolerance.surface, second_curve));
    if (!first_lifted || !second_lifted) {
	return false;
    }

    const ON_BoundingBox first_bounds = first_lifted->BoundingBox();
    const ON_BoundingBox second_bounds = second_lifted->BoundingBox();
    if (!first_bounds.IsValid() || !second_bounds.IsValid() ||
	fabs(first_bounds.m_min.x - second_bounds.m_min.x) >
	    INTERSECTION_TOL ||
	fabs(first_bounds.m_min.y - second_bounds.m_min.y) >
	    INTERSECTION_TOL ||
	fabs(first_bounds.m_min.z - second_bounds.m_min.z) >
	    INTERSECTION_TOL ||
	fabs(first_bounds.m_max.x - second_bounds.m_max.x) >
	    INTERSECTION_TOL ||
	fabs(first_bounds.m_max.y - second_bounds.m_max.y) >
	    INTERSECTION_TOL ||
	fabs(first_bounds.m_max.z - second_bounds.m_max.z) >
	    INTERSECTION_TOL)
    {
	return false;
    }

    const ON_Interval first_domain = first_lifted->Domain();
    const ON_Interval second_domain = second_lifted->Domain();
    if (!first_domain.IsIncreasing() || !second_domain.IsIncreasing()) {
	return false;
    }

    /* These segments already have the same arrangement endpoints.  At the
     * modeling tolerance independently fitted, very short curves can have
     * noisy endpoint derivatives even when their complete model-space loci
     * coincide.  Let the bounded whole-curve test below certify coincidence
     * and orientation; an endpoint tangent is not an additional topological
     * certificate here. */
    bool reversed = false;
    return brep_curves_coincident(*first_lifted,
	*second_lifted, INTERSECTION_TOL, &reversed) &&
	reversed == (node_orientation < 0);
}


static int
arrangement_segment_coincidence_orientation(const CurveSegment &first,
    const CurveSegment &second,
    const std::vector<BooleanOverlapSpan> &spans)
{
    const int node_orientation = arrangement_segment_node_orientation(first,
	second);
    if (node_orientation == 0) {
	return 0;
    }
    if (arrangement_segments_share_overlap_span(first, second, spans)) {
	return node_orientation;
    }

    std::unique_ptr<ON_Curve> first_curve;
    std::unique_ptr<ON_Curve> second_curve;
    try {
	first_curve.reset(first.Curve());
	second_curve.reset(second.Curve());
    } catch (InvalidInterval &) {
	return 0;
    }
    if (!first_curve || !second_curve) {
	return 0;
    }

    const double tolerance = std::max(INTERSECTION_TOL,
	std::max(first.tolerance.point, second.tolerance.point));
    if (ON_CurvesAreEquivalent(first_curve.get(), second_curve.get(),
	tolerance, node_orientation < 0))
    {
	return node_orientation;
    }
    if (first.from.source_loop != second.from.source_loop &&
	arrangement_curves_have_certified_model_coincidence(first, *first_curve,
	    second, *second_curve, node_orientation))
    {
	return node_orientation;
    }

    ON_SimpleArray<ON_X_EVENT> events;
    intersect_boolean_curves(first_curve.get(), second_curve.get(), events,
	tolerance);
    for (int event_index = 0; event_index < events.Count(); ++event_index) {
	if (overlap_event_covers_curve_domains(events[event_index],
		first_curve.get(), second_curve.get(),
		std::max(INTERSECTION_TOL,
		    first.tolerance.curve_parameter),
		std::max(INTERSECTION_TOL,
		    second.tolerance.curve_parameter)))
	{
	    return node_orientation;
	}
    }
    if (DEBUG_BREP_BOOLEAN) {
	const ON_Interval first_domain = first_curve->Domain();
	const ON_Interval second_domain = second_curve->Domain();
	bu_log("Coincidence rejected for source %d curve %d %.17g -> %.17g "
	    "and source %d curve %d %.17g -> %.17g, nodes %zu -> %zu, "
	    "orientation %d, point tolerance %.17g, parameter tolerances "
	    "%.17g/%.17g, events %d.\n",
	    first.from.source_loop, first.from.loop_index,
	    first.from.curve_t, first.to.curve_t,
	    second.from.source_loop, second.from.loop_index,
	    second.from.curve_t, second.to.curve_t,
	    first.from.node_id, first.to.node_id, node_orientation, tolerance,
	    first.tolerance.curve_parameter,
	    second.tolerance.curve_parameter, events.Count());
	for (int event_index = 0; event_index < events.Count(); ++event_index) {
	    bu_log("  event %d type %d, first %.17g -> %.17g, second "
		"%.17g -> %.17g.\n", event_index,
		static_cast<int>(events[event_index].m_type),
		events[event_index].m_a[0], events[event_index].m_a[1],
		events[event_index].m_b[0], events[event_index].m_b[1]);
	}
	if (first_domain.IsIncreasing() && second_domain.IsIncreasing()) {
	    for (int sample = 0; sample <= 4; ++sample) {
		const double fraction = 0.25 * sample;
		const ON_3dPoint first_point = first_curve->PointAt(
		    first_domain.ParameterAt(fraction));
		const ON_3dPoint second_point = second_curve->PointAt(
		    second_domain.ParameterAt(node_orientation > 0 ? fraction :
			1.0 - fraction));
		ON_3dPoint first_model = first_point;
		ON_3dPoint second_model = second_point;
		if (first.tolerance.surface != NULL)
		    first_model = first.tolerance.surface->PointAt(first_point.x,
			first_point.y);
		if (second.tolerance.surface != NULL)
		    second_model = second.tolerance.surface->PointAt(second_point.x,
			second_point.y);
		bu_log("  sample %.2f UV distance %.17g, model distance %.17g, "
		    "first (%.17g, %.17g), second (%.17g, %.17g).\n",
		    fraction, first_point.DistanceTo(second_point),
		    first_model.DistanceTo(second_model), first_point.x,
		    first_point.y, second_point.x, second_point.y);
	    }
	}
	if (first.tolerance.surface != NULL && second.tolerance.surface != NULL) {
	    std::unique_ptr<ON_Curve> first_lifted(pushup_boolean_trim_curve(
		first.tolerance.surface, *first_curve));
	    std::unique_ptr<ON_Curve> second_lifted(pushup_boolean_trim_curve(
		second.tolerance.surface, *second_curve));
	    if (first_lifted && second_lifted) {
		const double first_extent = first_lifted->BoundingBox().Diagonal().Length();
		const double second_extent = second_lifted->BoundingBox().Diagonal().Length();
		bu_log("  lifted extents %.17g/%.17g; coincident at "
		    "1e-4/2e-4/5e-4/1e-3/2e-3: %d/%d/%d/%d/%d.\n",
		    first_extent, second_extent,
		    brep_curves_coincident(*first_lifted, *second_lifted, 1.0e-4),
		    brep_curves_coincident(*first_lifted, *second_lifted, 2.0e-4),
		    brep_curves_coincident(*first_lifted, *second_lifted, 5.0e-4),
		    brep_curves_coincident(*first_lifted, *second_lifted, 1.0e-3),
		    brep_curves_coincident(*first_lifted, *second_lifted, 2.0e-3));
	    }
	}
    }
    return 0;
}


class BooleanArrangement {
public:
    static const size_t UNSET_EDGE = std::numeric_limits<size_t>::max();

    struct Edge {
	enum SelectionBasis {
	    NOT_SELECTED,
	    CLASSIFIED_NONCOINCIDENT,
	    COINCIDENT_GROUP,
	    COINCIDENT_OVERLAP,
	    SAMPLED_BOUNDARY,
	    SAMPLED_NO_TRANSITION,
	    CERTIFIED_PERIODIC_BOUNDARY
	};

	CurveSegment segment;
	size_t paired_edge;
	size_t coincident_group;
	size_t next_edge;
	const char *selection_reason;
	SelectionBasis selection_basis;
	bool selected;
	bool consumed;

	Edge(const CurveSegment &input_segment)
	    : segment(input_segment), paired_edge(UNSET_EDGE),
	      coincident_group(UNSET_EDGE), next_edge(UNSET_EDGE),
	      selection_reason("not classified"), selection_basis(NOT_SELECTED),
	      selected(false), consumed(false)
	{
	}
    };

    struct EndpointIncidence {
	size_t edge_index;
	bool outgoing;
	double angle;

	EndpointIncidence(size_t edge, bool is_outgoing, double ray_angle)
	    : edge_index(edge), outgoing(is_outgoing), angle(ray_angle)
	{
	}
    };

    void
    Add(const std::multiset<CurveSegment> &segments)
    {
	for (std::multiset<CurveSegment>::const_iterator segment =
	     segments.begin(); segment != segments.end(); ++segment)
	{
	    edges.push_back(Edge(*segment));
	}
    }

    void
    BuildCoincidentEdgeGroups(const std::vector<BooleanOverlapSpan> &spans)
    {
	std::vector<size_t> parents(edges.size());
	for (size_t edge_index = 0; edge_index < edges.size(); ++edge_index) {
	    parents[edge_index] = edge_index;
	    edges[edge_index].paired_edge = UNSET_EDGE;
	    edges[edge_index].coincident_group = UNSET_EDGE;
	}

	auto root = [&parents](size_t edge_index) {
	    size_t result = edge_index;
	    while (parents[result] != result) {
		result = parents[result];
	    }
	    while (parents[edge_index] != edge_index) {
		const size_t next = parents[edge_index];
		parents[edge_index] = result;
		edge_index = next;
	    }
	    return result;
	};

	for (size_t first_edge = 0; first_edge < edges.size(); ++first_edge) {
	    for (size_t second_edge = first_edge + 1;
		 second_edge < edges.size(); ++second_edge)
	    {
		if (arrangement_segment_coincidence_orientation(
			edges[first_edge].segment, edges[second_edge].segment,
			spans) == 0)
		{
		    continue;
		}
		const size_t first_root = root(first_edge);
		const size_t second_root = root(second_edge);
		if (first_root != second_root) {
		    parents[second_root] = first_root;
		}
	    }
	}

	std::map<size_t, size_t> group_sizes;
	for (size_t edge_index = 0; edge_index < edges.size(); ++edge_index) {
	    ++group_sizes[root(edge_index)];
	}
	std::map<size_t, size_t> group_ids;
	for (std::map<size_t, size_t>::const_iterator group =
	     group_sizes.begin(); group != group_sizes.end(); ++group)
	{
	    if (group->second > 1) {
		group_ids[group->first] = group_ids.size();
	    }
	}
	for (size_t edge_index = 0; edge_index < edges.size(); ++edge_index) {
	    const size_t edge_root = root(edge_index);
	    std::map<size_t, size_t>::const_iterator group =
		group_ids.find(edge_root);
	    if (group != group_ids.end()) {
		edges[edge_index].coincident_group = group->second;
	    }
	}

	for (size_t first_edge = 0; first_edge < edges.size(); ++first_edge) {
	    if (edges[first_edge].segment.from.source_loop != 1 ||
		edges[first_edge].coincident_group == UNSET_EDGE ||
		edges[first_edge].paired_edge != UNSET_EDGE)
	    {
		continue;
	    }
	    for (size_t second_edge = 0; second_edge < edges.size();
		 ++second_edge)
	    {
		if (edges[second_edge].segment.from.source_loop != 2 ||
		    edges[second_edge].coincident_group !=
			edges[first_edge].coincident_group ||
		    edges[second_edge].paired_edge != UNSET_EDGE)
		{
		    continue;
		}
		edges[first_edge].paired_edge = second_edge;
		edges[second_edge].paired_edge = first_edge;
		break;
	    }
	}
    }

    void
    BuildEndpointIncidences()
    {
	endpoint_incidences.clear();
	node_points.clear();
	for (size_t edge_index = 0; edge_index < edges.size(); ++edge_index) {
	    const Edge &edge = edges[edge_index];
	    std::unique_ptr<ON_Curve> curve(edge.segment.Curve());
	    if (!curve) {
		continue;
	    }
	    ON_3dVector start_ray = curve->TangentAt(curve->Domain().Min());
	    ON_3dVector end_ray = curve->TangentAt(curve->Domain().Max());
	    const double start_angle = atan2(start_ray.y, start_ray.x);
	    const double end_angle = atan2(-end_ray.y, -end_ray.x);
	    node_points[edge.segment.from.node_id] = edge.segment.from.pt;
	    node_points[edge.segment.to.node_id] = edge.segment.to.pt;
	    endpoint_incidences[edge.segment.from.node_id].push_back(
		EndpointIncidence(edge_index, true, start_angle));
	    endpoint_incidences[edge.segment.to.node_id].push_back(
		EndpointIncidence(edge_index, false, end_angle));
	}
	for (std::map<size_t, std::vector<EndpointIncidence> >::iterator node =
	     endpoint_incidences.begin(); node != endpoint_incidences.end(); ++node)
	{
	    std::sort(node->second.begin(), node->second.end(),
		[](const EndpointIncidence &first, const EndpointIncidence &second) {
		    return first.angle < second.angle;
		});
	}
    }

    std::vector<Edge> edges;
	std::map<size_t, std::vector<EndpointIncidence> > endpoint_incidences;
	std::map<size_t, ON_2dPoint> node_points;
};


static bool
construct_loops_from_arrangement(BooleanArrangement &arrangement,
    std::list<ON_SimpleArray<ON_Curve *> > &out);

static bool
arrangement_sector_state(const ON_2dPoint &node_point,
    ON_2dVector first_ray, ON_2dVector second_ray,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    const BooleanLoopTolerance &tolerance, op_type operation,
    bool &contains);


static bool
arrangement_material_transition(
    const BooleanArrangement::Edge &incoming,
    const BooleanArrangement::Edge &outgoing,
    const ON_2dPoint &node_point,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    const BooleanLoopTolerance &tolerance, op_type operation,
    double &continuation_score)
{
    std::unique_ptr<ON_Curve> incoming_curve(incoming.segment.Curve());
    std::unique_ptr<ON_Curve> outgoing_curve(outgoing.segment.Curve());
    if (!incoming_curve || !outgoing_curve) {
	return false;
    }

    ON_3dVector incoming_tangent = incoming_curve->TangentAt(
	incoming_curve->Domain().Max());
    ON_3dVector outgoing_tangent = outgoing_curve->TangentAt(
	outgoing_curve->Domain().Min());
    if (!incoming_tangent.Unitize() || !outgoing_tangent.Unitize()) {
	return false;
    }
    continuation_score = incoming_tangent * outgoing_tangent;

    bool sector_contains = false;
    return arrangement_sector_state(node_point,
	ON_2dVector(-incoming_tangent.x, -incoming_tangent.y),
	ON_2dVector(outgoing_tangent.x, outgoing_tangent.y), first_loop,
	second_loop, tolerance, operation, sector_contains) && sector_contains;
}


/* A selected boundary edge must participate in a directed cycle of locally
 * certified material transitions.  Tolerance-scale slivers can leave a
 * balanced set of selected edges whose only possible continuation crosses a
 * sector containing no result material.  Retain the independently certified
 * cycles and discard only edges that cannot occur in any such cycle. */
static bool
prune_arrangement_edges_without_closed_material_paths(
    BooleanArrangement &arrangement,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    const BooleanLoopTolerance &tolerance, op_type operation)
{
    const size_t edge_count = arrangement.edges.size();
    std::vector<std::vector<size_t> > transitions(edge_count);
    std::vector<bool> retained(edge_count, false);
    size_t selected_count = 0;

    for (size_t incoming_index = 0; incoming_index < edge_count;
	 ++incoming_index)
    {
	const BooleanArrangement::Edge &incoming =
	    arrangement.edges[incoming_index];
	if (!incoming.selected) {
	    continue;
	}
	++selected_count;
	if (incoming.segment.from.HasSameTopologyNode(incoming.segment.to)) {
	    retained[incoming_index] = true;
	    continue;
	}

	std::map<size_t, ON_2dPoint>::const_iterator node_point =
	    arrangement.node_points.find(incoming.segment.to.node_id);
	std::map<size_t, std::vector<BooleanArrangement::EndpointIncidence> >
	    ::const_iterator incidences = arrangement.endpoint_incidences.find(
		incoming.segment.to.node_id);
	if (node_point == arrangement.node_points.end() ||
	    !node_point->second.IsValid() ||
	    incidences == arrangement.endpoint_incidences.end())
	{
	    continue;
	}

	size_t selected_incoming_count = 0;
	std::vector<size_t> outgoing_edges;
	for (size_t incidence_index = 0;
	     incidence_index < incidences->second.size(); ++incidence_index)
	{
	    const BooleanArrangement::EndpointIncidence &incidence =
		incidences->second[incidence_index];
	    if (incidence.edge_index >= edge_count) {
		continue;
	    }
	    const BooleanArrangement::Edge &incident_edge =
		arrangement.edges[incidence.edge_index];
	    if (!incident_edge.selected ||
		incident_edge.segment.from.HasSameTopologyNode(
		    incident_edge.segment.to))
	    {
		continue;
	    }
	    if (incidence.outgoing) {
		outgoing_edges.push_back(incidence.edge_index);
	    } else {
		++selected_incoming_count;
	    }
	}
	if (selected_incoming_count == 1 && outgoing_edges.size() == 1) {
	    if (outgoing_edges.front() != incoming_index) {
		transitions[incoming_index].push_back(outgoing_edges.front());
	    }
	    continue;
	}

	for (size_t outgoing_index = 0; outgoing_index < outgoing_edges.size();
	     ++outgoing_index)
	{
	    if (outgoing_edges[outgoing_index] == incoming_index) {
		continue;
	    }
	    const BooleanArrangement::Edge &outgoing =
		arrangement.edges[outgoing_edges[outgoing_index]];
	    double continuation_score = 0.0;
	    if (arrangement_material_transition(incoming, outgoing,
		    node_point->second, first_loop, second_loop, tolerance,
		    operation, continuation_score))
	    {
		transitions[incoming_index].push_back(
		    outgoing_edges[outgoing_index]);
	    }
	}
    }

    for (size_t start_edge = 0; start_edge < edge_count; ++start_edge) {
	if (!arrangement.edges[start_edge].selected || retained[start_edge]) {
	    continue;
	}

	std::vector<bool> visited(edge_count, false);
	std::vector<size_t> pending(transitions[start_edge]);
	while (!pending.empty() && !retained[start_edge]) {
	    const size_t edge_index = pending.back();
	    pending.pop_back();
	    if (edge_index == start_edge) {
		retained[start_edge] = true;
		break;
	    }
	    if (edge_index >= edge_count || visited[edge_index]) {
		continue;
	    }
	    visited[edge_index] = true;
	    pending.insert(pending.end(), transitions[edge_index].begin(),
		transitions[edge_index].end());
	}
    }

    size_t retained_count = 0;
    std::map<size_t, int> node_balance;
    for (size_t edge_index = 0; edge_index < edge_count; ++edge_index) {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected || !retained[edge_index]) {
	    continue;
	}
	++retained_count;
	if (!edge.segment.from.HasSameTopologyNode(edge.segment.to)) {
	    ++node_balance[edge.segment.from.node_id];
	    --node_balance[edge.segment.to.node_id];
	}
    }
    if (retained_count == 0 || retained_count == selected_count) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("loop_boolean: closed material path pruning retained %zu of "
		"%zu selected edges; no pruning attempted.\n", retained_count,
		selected_count);
	}
	return false;
    }
    for (std::map<size_t, int>::const_iterator node = node_balance.begin();
	 node != node_balance.end(); ++node)
    {
	if (node->second != 0) {
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("loop_boolean: closed material path pruning would leave "
		    "node %zu with balance %d.\n", node->first,
		    node->second);
	    }
	    return false;
	}
    }

    for (size_t edge_index = 0; edge_index < edge_count; ++edge_index) {
	BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (edge.selected && !retained[edge_index]) {
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("loop_boolean: pruning edge %zu without a closed material "
		    "transition path.\n", edge_index);
	    }
	    edge.selected = false;
	    edge.selection_basis = BooleanArrangement::Edge::NOT_SELECTED;
	    edge.selection_reason =
		"selected edge has no closed material transition path";
	}
    }
    return true;
}


static void
report_arrangement_transition_failure(
    const BooleanArrangement &arrangement,
    size_t edge_index,
    const char *reason)
{
    size_t selected_edge_count = 0;
    for (size_t diagnostic_edge_index = 0;
	 diagnostic_edge_index < arrangement.edges.size();
	 ++diagnostic_edge_index)
    {
	const BooleanArrangement::Edge &diagnostic_edge =
	    arrangement.edges[diagnostic_edge_index];
	if (diagnostic_edge.selected) {
	    ++selected_edge_count;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("loop_boolean: diagnostic edge %zu, %s (%s), source %d "
		"curve %d, node %zu -> %zu, parameter %.17g -> %.17g, "
		"point (%.17g, %.17g) -> (%.17g, %.17g).\n",
		diagnostic_edge_index,
		diagnostic_edge.selected ? "selected" : "not selected",
		diagnostic_edge.selection_reason,
		diagnostic_edge.segment.from.source_loop,
		diagnostic_edge.segment.from.loop_index,
		diagnostic_edge.segment.from.node_id,
		diagnostic_edge.segment.to.node_id,
		diagnostic_edge.segment.from.curve_t,
		diagnostic_edge.segment.to.curve_t,
		diagnostic_edge.segment.from.pt.x,
		diagnostic_edge.segment.from.pt.y,
		diagnostic_edge.segment.to.pt.x,
		diagnostic_edge.segment.to.pt.y);
	}
    }
    bu_log("loop_boolean: arrangement has %zu edges (%zu selected) at "
	"transition failure.\n", arrangement.edges.size(), selected_edge_count);
    if (edge_index >= arrangement.edges.size()) {
	bu_log("loop_boolean: arrangement transition failure for invalid edge "
	    "%zu: %s.\n", edge_index, reason);
	return;
    }

    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
    bu_log("loop_boolean: arrangement edge %zu has no result transition "
	"at node %zu: %s (source loop %d curve %d, parameter %.17g -> "
	"%.17g, topology node %zu -> %zu).\n", edge_index,
	edge.segment.to.node_id, reason, edge.segment.from.source_loop,
	edge.segment.from.loop_index, edge.segment.from.curve_t,
	edge.segment.to.curve_t, edge.segment.from.node_id,
	edge.segment.to.node_id);

    std::map<size_t, std::vector<BooleanArrangement::EndpointIncidence> >
	::const_iterator incidences = arrangement.endpoint_incidences.find(
	    edge.segment.to.node_id);
    if (incidences == arrangement.endpoint_incidences.end()) {
	bu_log("loop_boolean: arrangement node %zu has no incidences.\n",
	    edge.segment.to.node_id);
	return;
    }

    for (size_t incidence_index = 0;
	 incidence_index < incidences->second.size(); ++incidence_index)
    {
	const BooleanArrangement::EndpointIncidence &incidence =
	    incidences->second[incidence_index];
	if (incidence.edge_index >= arrangement.edges.size()) {
	    bu_log("loop_boolean: arrangement node %zu incidence %zu "
		"references invalid edge %zu.\n", edge.segment.to.node_id,
		incidence_index, incidence.edge_index);
	    continue;
	}
	const BooleanArrangement::Edge &candidate =
	    arrangement.edges[incidence.edge_index];
	const ON_2dPoint incident_point = incidence.outgoing ?
	    candidate.segment.from.pt : candidate.segment.to.pt;
	bu_log("loop_boolean: arrangement node %zu incidence %zu: edge %zu, "
	    "%s, %s (%s), coincident group %zu, paired edge %zu, source "
	    "loop %d curve %d, topology "
	    "node %zu -> %zu, parameter %.17g -> %.17g, point "
	    "(%.17g, %.17g), angle %.17g.\n",
	    edge.segment.to.node_id,
	    incidence_index,
	    incidence.edge_index, incidence.outgoing ? "outgoing" : "incoming",
	    candidate.selected ? "selected" : "not selected",
	    candidate.selection_reason, candidate.coincident_group,
	    candidate.paired_edge,
	    candidate.segment.from.source_loop,
	    candidate.segment.from.loop_index, candidate.segment.from.node_id,
	    candidate.segment.to.node_id, candidate.segment.from.curve_t,
	    candidate.segment.to.curve_t, incident_point.x, incident_point.y,
	    incidence.angle);
    }
}


static bool
build_arrangement_transitions(BooleanArrangement &arrangement,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    const BooleanLoopTolerance &tolerance, op_type operation)
{
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	arrangement.edges[edge_index].next_edge = BooleanArrangement::UNSET_EDGE;
    }

    for (std::map<size_t,
	 std::vector<BooleanArrangement::EndpointIncidence> >::const_iterator
	 node = arrangement.endpoint_incidences.begin();
	 node != arrangement.endpoint_incidences.end(); ++node)
    {
	std::vector<size_t> incoming_edges;
	std::vector<size_t> outgoing_edges;
	for (size_t incidence_index = 0;
	     incidence_index < node->second.size(); ++incidence_index)
	{
	    const BooleanArrangement::EndpointIncidence &incidence =
		node->second[incidence_index];
	    if (incidence.edge_index >= arrangement.edges.size()) {
		bu_log("loop_boolean: arrangement node %zu references invalid "
		    "edge %zu while building transitions.\n", node->first,
		    incidence.edge_index);
		return false;
	    }
	    const BooleanArrangement::Edge &edge =
		arrangement.edges[incidence.edge_index];
	    if (!edge.selected ||
		edge.segment.from.HasSameTopologyNode(edge.segment.to))
	    {
		continue;
	    }
	    if (incidence.outgoing) {
		outgoing_edges.push_back(incidence.edge_index);
	    } else {
		incoming_edges.push_back(incidence.edge_index);
	    }
	}

	std::sort(incoming_edges.begin(), incoming_edges.end());
	std::sort(outgoing_edges.begin(), outgoing_edges.end());
	if (incoming_edges.size() != outgoing_edges.size()) {
	    bu_log("loop_boolean: arrangement node %zu has %zu selected "
		"incoming edges and %zu selected outgoing edges.\n", node->first,
		incoming_edges.size(), outgoing_edges.size());
	    for (size_t incoming_index = 0;
		 incoming_index < incoming_edges.size(); ++incoming_index)
	    {
		bu_log("loop_boolean: unmatched incoming edge %zu at node %zu.\n",
		    incoming_edges[incoming_index], node->first);
	    }
	    for (size_t outgoing_index = 0;
		 outgoing_index < outgoing_edges.size(); ++outgoing_index)
	    {
		bu_log("loop_boolean: unmatched outgoing edge %zu at node %zu.\n",
		    outgoing_edges[outgoing_index], node->first);
	    }
	    report_arrangement_transition_failure(arrangement,
		incoming_edges.empty() ? BooleanArrangement::UNSET_EDGE :
		incoming_edges.front(), "selected node incidence is unbalanced");
	    return false;
	}
	if (incoming_edges.empty()) {
	    continue;
	}
	if (incoming_edges.size() == 1) {
	    arrangement.edges[incoming_edges.front()].next_edge =
		outgoing_edges.front();
	    continue;
	}
	const size_t edge_count = incoming_edges.size();

	/* Overlap endpoints can be joined transitively into one topology node
	 * even when that node represents two distinct, tolerance-separated
	 * points at the ends of a shared edge.  If the actual curve endpoints
	 * provide a unique continuous pairing, use it before asking the angular
	 * material-sector classifier to disambiguate a true multi-edge vertex. */
	std::vector<size_t> continuous_outgoing(edge_count,
	    BooleanArrangement::UNSET_EDGE);
	std::vector<size_t> continuous_incoming_count(edge_count, 0);
	std::vector<size_t> continuous_outgoing_count(edge_count, 0);
	for (size_t incoming_index = 0; incoming_index < edge_count;
	     ++incoming_index)
	{
	    const BooleanArrangement::Edge &incoming =
		arrangement.edges[incoming_edges[incoming_index]];
	    for (size_t outgoing_index = 0; outgoing_index < edge_count;
		 ++outgoing_index)
	    {
		if (incoming_edges[incoming_index] ==
		    outgoing_edges[outgoing_index])
		{
		    continue;
		}
		const BooleanArrangement::Edge &outgoing =
		    arrangement.edges[outgoing_edges[outgoing_index]];
		if (incoming.segment.to != outgoing.segment.from) {
		    continue;
		}
		continuous_outgoing[incoming_index] = outgoing_index;
		++continuous_incoming_count[incoming_index];
		++continuous_outgoing_count[outgoing_index];
	    }
	}
	bool unique_continuous_pairing = true;
	for (size_t edge_index = 0; edge_index < edge_count; ++edge_index) {
	    if (continuous_incoming_count[edge_index] != 1 ||
		continuous_outgoing_count[edge_index] != 1)
	    {
		unique_continuous_pairing = false;
		break;
	    }
	}
	if (unique_continuous_pairing) {
	    for (size_t incoming_index = 0; incoming_index < edge_count;
		 ++incoming_index)
	    {
		arrangement.edges[incoming_edges[incoming_index]].next_edge =
		    outgoing_edges[continuous_outgoing[incoming_index]];
	    }
	    continue;
	}

	std::map<size_t, ON_2dPoint>::const_iterator node_point =
	    arrangement.node_points.find(node->first);
	if (node_point == arrangement.node_points.end() ||
	    !node_point->second.IsValid())
	{
	    report_arrangement_transition_failure(arrangement,
		incoming_edges.front(), "arrangement node point is missing or invalid");
	    return false;
	}

	std::vector<std::vector<double> > costs(edge_count,
	    std::vector<double>(edge_count, 0.0));
	std::vector<std::vector<bool> > eligible(edge_count,
	    std::vector<bool>(edge_count, false));
	std::vector<size_t> incoming_candidate_counts(edge_count, 0);
	std::vector<size_t> outgoing_candidate_counts(edge_count, 0);
	const double invalid_cost = 4.0 * static_cast<double>(edge_count + 1);
	for (size_t incoming_index = 0; incoming_index < edge_count;
	     ++incoming_index)
	{
	    const BooleanArrangement::Edge &incoming =
		arrangement.edges[incoming_edges[incoming_index]];
	    for (size_t outgoing_index = 0; outgoing_index < edge_count;
		 ++outgoing_index)
	    {
		costs[incoming_index][outgoing_index] = invalid_cost;
		if (incoming_edges[incoming_index] ==
		    outgoing_edges[outgoing_index])
		{
		    continue;
		}
		const BooleanArrangement::Edge &outgoing =
		    arrangement.edges[outgoing_edges[outgoing_index]];
		double score = 0.0;
		const bool material_transition = arrangement_material_transition(
		    incoming, outgoing, node_point->second, first_loop,
		    second_loop, tolerance, operation, score);
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("loop_boolean: transition candidate %zu -> %zu at "
			"node %zu score %.17g, material %d.\n",
			incoming_edges[incoming_index],
			outgoing_edges[outgoing_index], node->first, score,
			material_transition);
		}
		if (!material_transition) {
		    continue;
		}
		eligible[incoming_index][outgoing_index] = true;
		costs[incoming_index][outgoing_index] = -score;
		++incoming_candidate_counts[incoming_index];
		++outgoing_candidate_counts[outgoing_index];
	    }
	}

	bool missing_candidate = false;
	for (size_t incoming_index = 0; incoming_index < edge_count;
	     ++incoming_index)
	{
	    if (incoming_candidate_counts[incoming_index] != 0) {
		continue;
	    }
	    missing_candidate = true;
	    bu_log("loop_boolean: unmatched incoming edge %zu at node %zu has "
		"no eligible outgoing transition.\n",
		incoming_edges[incoming_index], node->first);
	}
	for (size_t outgoing_index = 0; outgoing_index < edge_count;
	     ++outgoing_index)
	{
	    if (outgoing_candidate_counts[outgoing_index] != 0) {
		continue;
	    }
	    missing_candidate = true;
	    bu_log("loop_boolean: unmatched outgoing edge %zu at node %zu has "
		"no eligible incoming transition.\n",
		outgoing_edges[outgoing_index], node->first);
	}
	if (missing_candidate) {
	    report_arrangement_transition_failure(arrangement,
		incoming_edges.front(),
		"no complete set of material-bounding transitions exists");
	    return false;
	}

	// Solve the square maximum-score assignment as a minimum-cost matching.
	// Sorted edge indices and strict comparisons make equal-score choices
	// deterministic.  The invalid cost is larger than the total range of any
	// all-eligible matching; an invalid assignment therefore proves that no
	// eligible perfect matching exists.
	std::vector<double> row_potential(edge_count + 1, 0.0);
	std::vector<double> column_potential(edge_count + 1, 0.0);
	std::vector<size_t> column_row(edge_count + 1, 0);
	std::vector<size_t> previous_column(edge_count + 1, 0);
	for (size_t row = 1; row <= edge_count; ++row) {
	    column_row[0] = row;
	    size_t current_column = 0;
	    std::vector<double> minimum_cost(edge_count + 1,
		std::numeric_limits<double>::infinity());
	    std::vector<bool> used_column(edge_count + 1, false);
	    do {
		used_column[current_column] = true;
		const size_t current_row = column_row[current_column];
		double delta = std::numeric_limits<double>::infinity();
		size_t next_column = 0;
		for (size_t column = 1; column <= edge_count; ++column) {
		    if (used_column[column]) {
			continue;
		    }
		    const double reduced_cost = costs[current_row - 1][column - 1]
			- row_potential[current_row] - column_potential[column];
		    if (reduced_cost < minimum_cost[column]) {
			minimum_cost[column] = reduced_cost;
			previous_column[column] = current_column;
		    }
		    if (minimum_cost[column] < delta) {
			delta = minimum_cost[column];
			next_column = column;
		    }
		}
		if (!std::isfinite(delta) || next_column == 0) {
		    report_arrangement_transition_failure(arrangement,
			incoming_edges[row - 1],
			"transition matching could not find an augmenting path");
		    return false;
		}
		for (size_t column = 0; column <= edge_count; ++column) {
		    if (used_column[column]) {
			row_potential[column_row[column]] += delta;
			column_potential[column] -= delta;
		    } else {
			minimum_cost[column] -= delta;
		    }
		}
		current_column = next_column;
	    } while (column_row[current_column] != 0);

	    do {
		const size_t preceding_column = previous_column[current_column];
		column_row[current_column] = column_row[preceding_column];
		current_column = preceding_column;
	    } while (current_column != 0);
	}

	std::vector<size_t> assigned_column(edge_count,
	    BooleanArrangement::UNSET_EDGE);
	for (size_t column = 1; column <= edge_count; ++column) {
	    if (column_row[column] != 0) {
		assigned_column[column_row[column] - 1] = column - 1;
	    }
	}
	bool complete_matching = true;
	std::vector<bool> matched_outgoing(edge_count, false);
	for (size_t incoming_index = 0; incoming_index < edge_count;
	     ++incoming_index)
	{
	    const size_t outgoing_index = assigned_column[incoming_index];
	    if (outgoing_index >= edge_count ||
		!eligible[incoming_index][outgoing_index])
	    {
		complete_matching = false;
		bu_log("loop_boolean: unmatched incoming edge %zu at node %zu "
		    "has no edge in the optimal eligible assignment.\n",
		    incoming_edges[incoming_index], node->first);
		continue;
	    }
	    matched_outgoing[outgoing_index] = true;
	    arrangement.edges[incoming_edges[incoming_index]].next_edge =
		outgoing_edges[outgoing_index];
	}
	for (size_t outgoing_index = 0; outgoing_index < edge_count;
	     ++outgoing_index)
	{
	    if (!matched_outgoing[outgoing_index]) {
		complete_matching = false;
		bu_log("loop_boolean: unmatched outgoing edge %zu at node %zu "
		    "has no predecessor in the optimal eligible assignment.\n",
		    outgoing_edges[outgoing_index], node->first);
	    }
	}
	if (!complete_matching) {
	    report_arrangement_transition_failure(arrangement,
		incoming_edges.front(),
		"eligible transition graph has no perfect matching");
	    return false;
	}
    }

    std::vector<size_t> transition_indegree(arrangement.edges.size(), 0);
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected ||
	    edge.segment.from.HasSameTopologyNode(edge.segment.to))
	{
	    continue;
	}
	if (edge.next_edge == BooleanArrangement::UNSET_EDGE ||
	    edge.next_edge >= arrangement.edges.size() ||
	    !arrangement.edges[edge.next_edge].selected ||
	    !edge.segment.to.HasSameTopologyNode(
		arrangement.edges[edge.next_edge].segment.from))
	{
	    report_arrangement_transition_failure(arrangement, edge_index,
		"assigned successor is missing, invalid, or discontinuous");
	    return false;
	}
	++transition_indegree[edge.next_edge];
    }
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected ||
	    edge.segment.from.HasSameTopologyNode(edge.segment.to))
	{
	    continue;
	}
	if (transition_indegree[edge_index] != 1) {
	    bu_log("loop_boolean: selected outgoing edge %zu has %zu assigned "
		"predecessors at node %zu.\n", edge_index,
		transition_indegree[edge_index], edge.segment.from.node_id);
	    report_arrangement_transition_failure(arrangement, edge_index,
		transition_indegree[edge_index] == 0 ?
		"selected outgoing edge has no predecessor" :
		"selected outgoing edge has multiple predecessors");
	    return false;
	}
    }
    if (DEBUG_BREP_BOOLEAN && arrangement.edges.size() > 64) {
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    if (!edge.selected ||
		edge.next_edge == BooleanArrangement::UNSET_EDGE ||
		edge.next_edge >= arrangement.edges.size())
	    {
		continue;
	    }
	    const BooleanArrangement::Edge &next =
		arrangement.edges[edge.next_edge];
	    std::map<size_t, std::vector<BooleanArrangement::EndpointIncidence> >
		::const_iterator incidences = arrangement.endpoint_incidences.find(
		    edge.segment.to.node_id);
	    const size_t incidence_count = incidences ==
		arrangement.endpoint_incidences.end() ? 0 :
		incidences->second.size();
	    if (incidence_count <= 2 &&
		edge.segment.from.source_loop == next.segment.from.source_loop &&
		edge.segment.from.loop_index == next.segment.from.loop_index)
	    {
		continue;
	    }
	    const ON_2dPoint node_point = arrangement.node_points.find(
		edge.segment.to.node_id) == arrangement.node_points.end() ?
		ON_2dPoint::UnsetPoint :
		arrangement.node_points.find(edge.segment.to.node_id)->second;
	    if (!node_point.IsValid() || fabs(node_point.x) > 1.0e-3 ||
		fabs(node_point.y) > 1.0e-2)
	    {
		continue;
	    }
	    bu_log("loop_boolean: transition edge %zu -> %zu at node %zu "
		"(%.17g, %.17g), %zu incidences; source %d curve %d "
		"(%.17g -> %.17g, %s, group %zu) to source %d curve %d "
		"(%.17g -> %.17g, %s, group %zu).\n",
		edge_index, edge.next_edge, edge.segment.to.node_id,
		node_point.x, node_point.y, incidence_count,
		edge.segment.from.source_loop, edge.segment.from.loop_index,
		edge.segment.from.curve_t, edge.segment.to.curve_t,
		edge.selection_reason, edge.coincident_group,
		next.segment.from.source_loop, next.segment.from.loop_index,
		next.segment.from.curve_t, next.segment.to.curve_t,
		next.selection_reason, next.coincident_group);
	    if (incidence_count > 2) {
		for (size_t incidence_index = 0;
		     incidence_index < incidences->second.size();
		     ++incidence_index)
		{
		    const BooleanArrangement::EndpointIncidence &incidence =
			incidences->second[incidence_index];
		    const BooleanArrangement::Edge &candidate =
			arrangement.edges[incidence.edge_index];
		    bu_log("loop_boolean:   incidence edge %zu %s, %s (%s), "
			"source %d curve %d, %.17g -> %.17g, group %zu.\n",
			incidence.edge_index,
			incidence.outgoing ? "outgoing" : "incoming",
			candidate.selected ? "selected" : "not selected",
			candidate.selection_reason,
			candidate.segment.from.source_loop,
			candidate.segment.from.loop_index,
			candidate.segment.from.curve_t,
			candidate.segment.to.curve_t,
			candidate.coincident_group);
		}
	    }
	}
	for (std::map<size_t, ON_2dPoint>::const_iterator node =
		 arrangement.node_points.begin();
	     node != arrangement.node_points.end(); ++node)
	{
	    if (!node->second.IsValid() || fabs(node->second.x) > 1.0e-3 ||
		fabs(node->second.y) > 1.0e-2)
	    {
		continue;
	    }
	    std::map<size_t,
		std::vector<BooleanArrangement::EndpointIncidence> >::const_iterator
		incidences = arrangement.endpoint_incidences.find(node->first);
	    if (incidences == arrangement.endpoint_incidences.end()) {
		continue;
	    }
	    bu_log("loop_boolean: target node %zu (%.17g, %.17g), %zu "
		"incidences.\n", node->first, node->second.x, node->second.y,
		incidences->second.size());
	    for (size_t incidence_index = 0;
		 incidence_index < incidences->second.size(); ++incidence_index)
	    {
		const BooleanArrangement::EndpointIncidence &incidence =
		    incidences->second[incidence_index];
		const BooleanArrangement::Edge &candidate =
		    arrangement.edges[incidence.edge_index];
		bu_log("loop_boolean:   target incidence edge %zu %s, %s (%s), "
		    "source %d curve %d, %.17g -> %.17g, node %zu -> %zu, "
		    "group %zu.\n", incidence.edge_index,
		    incidence.outgoing ? "outgoing" : "incoming",
		    candidate.selected ? "selected" : "not selected",
		    candidate.selection_reason,
		    candidate.segment.from.source_loop,
		    candidate.segment.from.loop_index,
		    candidate.segment.from.curve_t,
		    candidate.segment.to.curve_t,
		    candidate.segment.from.node_id,
		    candidate.segment.to.node_id,
		    candidate.coincident_group);
	    }
	}
    }
    return true;
}


class LoopBooleanResult {
public:
    std::vector<ON_SimpleArray<ON_Curve *> > outerloops;
    std::vector<ON_SimpleArray<ON_Curve *> > innerloops;

    void ClearOuterloops() {
	for (size_t i = 0; i < outerloops.size(); ++i) {
	    for (int j = 0; j < outerloops[i].Count(); ++j) {
		delete outerloops[i][j];
	    }
	}
    }
    void ClearInnerloops() {
	for (size_t i = 0; i < innerloops.size(); ++i) {
	    for (int j = 0; j < innerloops[i].Count(); ++j) {
		delete innerloops[i][j];
	    }
	}
    }
};


#define LOOP_DIRECTION_CCW  1
#define LOOP_DIRECTION_CW  -1
#define LOOP_DIRECTION_NONE 0

static bool
close_small_gap(
    ON_SimpleArray<ON_Curve *> &loop,
    int curr,
    int next,
    double point_tolerance,
    const ON_Surface *surface,
    double surface_tolerance)
{
    if (loop[curr] == NULL || loop[next] == NULL) {
	return false;
    }

    ON_3dPoint end_curr = loop[curr]->PointAtEnd();
    ON_3dPoint start_next = loop[next]->PointAtStart();

    double gap = end_curr.DistanceTo(start_next);
    if (gap >= ON_ZERO_TOLERANCE &&
	(gap <= point_tolerance || loop_gap_is_surface_small(end_curr,
	    start_next, point_tolerance, surface, surface_tolerance)))
    {
	ON_Curve *closing_seg = new ON_LineCurve(end_curr, start_next);
	loop.Insert(next, closing_seg);
	return true;
    }
    return false;
}


static void
close_small_gaps(
    ON_SimpleArray<ON_Curve *> &loop,
    double point_tolerance,
    const ON_Surface *surface,
    double surface_tolerance)
{
    if (loop.Count() == 0) {
	return;
    }
    for (int i = 0; i < loop.Count() - 1; ++i) {
	if (close_small_gap(loop, i, i + 1, point_tolerance, surface,
		surface_tolerance)) {
	    ++i;
	}
    }
    close_small_gap(loop, loop.Count() - 1, 0, point_tolerance, surface,
	surface_tolerance);
}


ON_Curve *
get_loop_curve(const ON_SimpleArray<ON_Curve *> &loop)
{
    ON_PolyCurve *pcurve = new ON_PolyCurve();
    for (int i = 0; i < loop.Count(); ++i) {
	append_to_polycurve(loop[i]->Duplicate(), *pcurve);
    }
    return pcurve;
}


std::list<ON_SimpleArray<ON_Curve *> >::iterator
find_innerloop(std::list<ON_SimpleArray<ON_Curve *> > &loops)
{
    std::list<ON_SimpleArray<ON_Curve *> >::iterator k;
    for (k = loops.begin(); k != loops.end(); ++k) {
	ON_Curve *loop_curve = get_loop_curve(*k);

	if (ON_ClosedCurveOrientation(*loop_curve, NULL) == LOOP_DIRECTION_CW) {
	    delete loop_curve;
	    return k;
	}
	delete loop_curve;
    }
    return loops.end();
}


bool
set_loop_direction(ON_SimpleArray<ON_Curve *> &loop, int dir)
{
    ON_Curve *curve = get_loop_curve(loop);
    int curr_dir = ON_ClosedCurveOrientation(*curve, NULL);
    delete curve;

    if (curr_dir == LOOP_DIRECTION_NONE) {
	// can't set the correct direction
	return false;
    }
    if (curr_dir != dir) {
	// need reverse
	for (int i = 0; i < loop.Count(); ++i) {
	    if (!loop[i]->Reverse()) {
		return false;
	    }
	}
	loop.Reverse();
    }
    // curve already has the correct direction
    return true;
}


void
add_point_to_set(std::multiset<CurvePoint> &set, CurvePoint pt)
{
    size_t matching_point_count = 0;
    for (std::multiset<CurvePoint>::const_iterator curve_point = set.begin();
	 curve_point != set.end(); ++curve_point)
    {
	if (curve_point->HasSameCurveParameter(pt) &&
	    ++matching_point_count == 2)
	{
	    return;
	}
    }

    set.insert(pt);
}


static void
canonicalize_arrangement_nodes(
    std::multiset<CurvePoint> &points,
    BooleanArrangementNodes &nodes)
{
	std::multiset<CurvePoint> registered_points;
	for (std::multiset<CurvePoint>::const_iterator point = points.begin();
	     point != points.end(); ++point)
	{
	    CurvePoint registered_point(*point);
	    const size_t registered_node = nodes.Node(registered_point);
	    if (registered_point.node_id != CurvePoint::UNSET_NODE) {
		nodes.Join(registered_point.node_id, registered_node);
	    }
	    registered_point.node_id = registered_node;
	    registered_points.insert(registered_point);
	}

    std::multiset<CurvePoint> canonical_points;
    for (std::multiset<CurvePoint>::const_iterator point =
	 registered_points.begin(); point != registered_points.end(); ++point)
    {
	CurvePoint canonical_point(*point);
	canonical_point.node_id = nodes.Canonical(canonical_point.node_id);
	canonical_points.insert(canonical_point);
    }
	points.swap(canonical_points);
}


/* Dropping a certified tolerance-scale arc without identifying its endpoints
 * leaves an artificial topological gap: one selected edge ends at one node
 * and its continuation begins at the other.  Join only arcs whose physical
 * extent was measured successfully; malformed or unprojectable curves remain
 * failures rather than becoming topology merges. */
static void
join_tolerance_scale_arrangement_nodes(
    const std::multiset<CurvePoint> &points,
    ON_SimpleArray<ON_Curve *> &loop,
    const ON_SimpleArray<ON_Curve *> &other_loop,
    const std::vector<BooleanOverlapSpan> &overlap_spans,
    BooleanArrangementNodes &nodes)
{
    if (points.size() < 2) {
	return;
    }

    const bool single_closed_boundary =
	(loop.Count() == 1 && loop[0] != NULL && loop[0]->IsClosed()) ||
	(other_loop.Count() == 1 && other_loop[0] != NULL &&
	 other_loop[0]->IsClosed());

    std::multiset<CurvePoint>::const_iterator current = points.begin();
    std::multiset<CurvePoint>::const_iterator next = current;
    ++next;
    for (; next != points.end(); ++current, ++next) {
	CurveSegment segment(loop, *current, *next, CurveSegment::BOUNDARY);
	bool base_certified = false;
	if (segment.IsDegenerate(&base_certified)) {
	    if (base_certified &&
		current->node_id != CurvePoint::UNSET_NODE &&
		next->node_id != CurvePoint::UNSET_NODE)
	    {
		(void)nodes.JoinWithinTolerance(current->node_id,
		    next->node_id,
		    BOOLEAN_LOOP_CLOSURE_TOLERANCE_MULTIPLIER);
	    }
	    continue;
	}

	bool closure_certified = false;
	if (!segment.IsDegenerate(&closure_certified,
		BOOLEAN_LOOP_CLOSURE_TOLERANCE_MULTIPLIER) ||
	    !closure_certified)
	{
	    continue;
	}

	/* A certified overlap fragment, or a subdivision of a one-curve closed
	 * loop, is real boundary between nearby events.  Preserve it unless it
	 * meets the same ordinary degeneracy threshold used by make_segments().
	 * Other short spans may use the two-endpoint loop-closure allowance. */
	bool boundary_fragment = false;
	if (current->location == CurvePoint::BOUNDARY &&
	    next->location == CurvePoint::BOUNDARY)
	{
	    boundary_fragment = single_closed_boundary;
	    for (size_t span_index = 0;
		 !boundary_fragment && span_index < overlap_spans.size();
		 ++span_index)
	    {
		boundary_fragment = overlap_spans[span_index].Contains(segment);
	    }
	}
	if (!boundary_fragment &&
	    current->node_id != CurvePoint::UNSET_NODE &&
	    next->node_id != CurvePoint::UNSET_NODE)
	{
	    (void)nodes.JoinWithinTolerance(current->node_id, next->node_id,
		BOOLEAN_LOOP_CLOSURE_TOLERANCE_MULTIPLIER);
	}
    }
}


std::multiset<CurveSegment>
make_segments(
    std::multiset<CurvePoint> &curve1_points,
    ON_SimpleArray<ON_Curve *> &loop1,
    ON_SimpleArray<ON_Curve *> &loop2,
    const BooleanLoopTolerance &tolerance)
{
    std::multiset<CurveSegment> out;

    std::multiset<CurvePoint>::iterator first = curve1_points.begin();
    std::multiset<CurvePoint>::iterator curr = first;
    std::multiset<CurvePoint>::iterator next = ++curve1_points.begin();

    for (; next != curve1_points.end(); ++curr, ++next) {
	CurvePoint from = *curr;
	CurvePoint to = *next;
	CurveSegment new_seg(loop1, from, to, CurveSegment::BOUNDARY);

	if (new_seg.IsDegenerate()) {
	    continue;
	}

	if (from.HasSameTopologyNode(to)) {
	    // A whole closed curve with no intervening intersection node has a
	    // uniform relationship to the other loop.  Its coincident seam
	    // endpoints are a particularly poor classification sample (periodic
	    // curves commonly place the seam at an extremum), so classify an
	    // interior curve parameter instead.
	    ON_Curve *segment_curve = loop1[from.loop_index];
	    const double end_t = from.loop_index == to.loop_index ?
		to.curve_t : segment_curve->Domain().Max();
	    const ON_2dPoint segment_midpoint = segment_curve->PointAt(
		ON_Interval(from.curve_t, end_t).Mid());
	    const CurvePoint::Location midpoint_location =
		CurvePoint::PointLoopLocation(segment_midpoint, loop2, tolerance);
	    if (midpoint_location == CurvePoint::INSIDE) {
		new_seg.location = CurveSegment::INSIDE;
	    } else if (midpoint_location == CurvePoint::OUTSIDE) {
		new_seg.location = CurveSegment::OUTSIDE;
	    }
	} else if (from.location == CurvePoint::BOUNDARY &&
	    to.location == CurvePoint::BOUNDARY)
	{
	    ON_Curve *seg_curve = loop1[from.loop_index];

	    double end_t = to.curve_t;
	    if (from.loop_index != to.loop_index) {
		end_t = seg_curve->Domain().m_t[1];
	    }
	    ON_2dPoint seg_midpt = seg_curve->PointAt(
		ON_Interval(from.curve_t, end_t).Mid());

	CurvePoint::Location midpt_location =
	    CurvePoint::PointLoopLocation(seg_midpt, loop2, tolerance);

	    if (midpt_location == CurvePoint::INSIDE) {
		new_seg.location = CurveSegment::INSIDE;
	    } else if (midpt_location == CurvePoint::OUTSIDE) {
		new_seg.location = CurveSegment::OUTSIDE;
	    }
	} else if (from.location == CurvePoint::INSIDE ||
		   to.location == CurvePoint::INSIDE)
	{
	    new_seg.location = CurveSegment::INSIDE;
	} else if (from.location == CurvePoint::OUTSIDE ||
		   to.location == CurvePoint::OUTSIDE)
	{
	    new_seg.location = CurveSegment::OUTSIDE;
	}
	out.insert(new_seg);
    }
    return out;
}


static bool
overlap_spans_curve_domain(
    double first_parameter,
    double second_parameter,
    ON_Interval domain,
    double parameter_tolerance)
{
    if (!domain.IsValid() || !(parameter_tolerance > 0.0) ||
	!std::isfinite(parameter_tolerance))
    {
	return false;
    }

    domain.MakeIncreasing();
    const double overlap_minimum = std::min(first_parameter, second_parameter);
    const double overlap_maximum = std::max(first_parameter, second_parameter);
    return ON_NearZero(overlap_minimum - domain.Min(), parameter_tolerance) &&
	ON_NearZero(overlap_maximum - domain.Max(), parameter_tolerance);
}


static bool
overlap_spans_curve_domain(
    double first_parameter,
    double second_parameter,
    ON_Interval domain)
{
    const double parameter_tolerance = ON_ZERO_TOLERANCE * std::max(1.0,
	fabs(domain.Length()));
    return overlap_spans_curve_domain(first_parameter, second_parameter,
	domain, parameter_tolerance);
}


static bool
overlap_event_covers_curve_domains(const ON_X_EVENT &event,
				   const ON_Curve *first_curve,
				   const ON_Curve *second_curve,
				   double first_parameter_tolerance,
				   double second_parameter_tolerance)
{
    if (event.m_type != ON_X_EVENT::ccx_overlap || first_curve == NULL ||
	second_curve == NULL)
    {
	return false;
    }

    return overlap_spans_curve_domain(event.m_a[0], event.m_a[1],
	first_curve->Domain(), first_parameter_tolerance) &&
	overlap_spans_curve_domain(event.m_b[0], event.m_b[1],
	second_curve->Domain(), second_parameter_tolerance);
}


static bool
segments_are_reverse_equivalent(const CurveSegment &first,
				const CurveSegment &second)
{
    std::unique_ptr<ON_Curve> first_curve;
    std::unique_ptr<ON_Curve> second_curve;
    try {
	first_curve.reset(first.Curve());
	second_curve.reset(second.Curve());
    } catch (InvalidInterval &) {
	return false;
    }

    if (!first_curve || !second_curve) {
	return false;
    }
    if (ON_CurvesAreEquivalent(first_curve.get(), second_curve.get(),
	first.tolerance.point, true))
    {
	return true;
    }

    ON_SimpleArray<ON_X_EVENT> events;
    intersect_boolean_curves(first_curve.get(), second_curve.get(), events,
	first.tolerance.point);
    return events.Count() == 1 && overlap_event_covers_curve_domains(events[0],
	first_curve.get(), second_curve.get(),
	first.tolerance.curve_parameter,
	second.tolerance.curve_parameter);
}


void
set_append_segment(
    std::multiset<CurveSegment> &out,
    const CurveSegment &seg)
{
    std::multiset<CurveSegment>::iterator i;
    for (i = out.begin(); i != out.end(); ++i) {
	if (i->from.HasSameTopologyNode(seg.to) &&
	    i->to.HasSameTopologyNode(seg.from))
	{
	    if (segments_are_reverse_equivalent(*i, seg)) {
		out.erase(i);
		return;
	    }
	}
    }
    out.insert(seg);
}


void
set_append_segments_at_location(
    std::multiset<CurveSegment> &out,
    std::multiset<CurveSegment> &in,
    CurveSegment::Location location,
    bool reversed_segs_cancel)
{
    std::multiset<CurveSegment>::iterator i;
    if (reversed_segs_cancel) {
	for (i = in.begin(); i != in.end(); ++i) {
	    if (i->location == location) {
		set_append_segment(out, *i);
	    }
	}
    } else {
	for (i = in.begin(); i != in.end(); ++i) {
	    if (i->location == location) {
		out.insert(*i);
	    }
	}
    }
}


std::multiset<CurveSegment>
find_similar_segments(
    std::multiset<CurveSegment> &set,
    const CurveSegment &seg)
{
    std::multiset<CurveSegment> out;

    const bool have_node_identity = seg.from.node_id != CurvePoint::UNSET_NODE &&
	seg.to.node_id != CurvePoint::UNSET_NODE;

    std::multiset<CurveSegment>::iterator i;
    for (i = set.begin(); i != set.end(); ++i) {
	const bool matching_nodes = have_node_identity &&
	    i->from.node_id != CurvePoint::UNSET_NODE &&
	    i->to.node_id != CurvePoint::UNSET_NODE &&
	    ((i->from.node_id == seg.from.node_id &&
	      i->to.node_id == seg.to.node_id) ||
	     (i->from.node_id == seg.to.node_id &&
	      i->to.node_id == seg.from.node_id));
	const bool matching_geometry = !have_node_identity &&
	    (((i->from == seg.from) && (i->to == seg.to)) ||
	     ((i->from == seg.to) && (i->to == seg.from)));
	if (matching_nodes || matching_geometry)
	{
	    out.insert(*i);
	}
    }
    return out;
}


static std::multiset<CurveSegment>
get_op_segments(
    std::multiset<CurveSegment> &curve1_segments,
    std::multiset<CurveSegment> &curve2_segments,
    op_type op)
{
    std::multiset<CurveSegment> out;

    std::multiset<CurveSegment> c1_boundary_segs;
    set_append_segments_at_location(c1_boundary_segs, curve1_segments,
				    CurveSegment::BOUNDARY, false);

    std::multiset<CurveSegment> c2_boundary_segs;
    set_append_segments_at_location(c2_boundary_segs, curve2_segments,
				    CurveSegment::BOUNDARY, false);

    if (op == BOOLEAN_INTERSECT) {
	set_append_segments_at_location(out, curve1_segments,
					CurveSegment::INSIDE, true);

	set_append_segments_at_location(out, curve2_segments,
					CurveSegment::INSIDE, true);

	std::multiset<CurveSegment>::iterator i;
	for (i = c1_boundary_segs.begin(); i != c1_boundary_segs.end(); ++i) {
	    std::multiset<CurveSegment> curve1_matches =
		find_similar_segments(c1_boundary_segs, *i);

	    std::multiset<CurveSegment> curve2_matches =
		find_similar_segments(c2_boundary_segs, *i);

	    if (curve1_matches.size() != 1 || curve2_matches.size() != 1) {
		continue;
	    }
	    if (curve1_matches.begin()->from == curve2_matches.begin()->from) {
		out.insert(*i);
	    }
	}
    } else if (op == BOOLEAN_DIFF) {
	set_append_segments_at_location(out, curve1_segments,
					CurveSegment::OUTSIDE, true);

	set_append_segments_at_location(out, curve2_segments,
					CurveSegment::INSIDE, true);

	std::multiset<CurveSegment>::iterator i;
	for (i = c1_boundary_segs.begin(); i != c1_boundary_segs.end(); ++i) {
	    std::multiset<CurveSegment> curve1_matches =
		find_similar_segments(c1_boundary_segs, *i);

	    std::multiset<CurveSegment> curve2_matches =
		find_similar_segments(c2_boundary_segs, *i);

	    if (curve1_matches.size() > 1) {
		continue;
	    }
	    if (curve1_matches.begin()->from == curve2_matches.begin()->from ||
		curve2_matches.size() > 1)
	    {
		out.insert(*i);
	    }
	}
    } else if (op == BOOLEAN_UNION) {
	set_append_segments_at_location(out, curve1_segments,
					CurveSegment::OUTSIDE, true);

	set_append_segments_at_location(out, curve2_segments,
					CurveSegment::OUTSIDE, true);

	std::multiset<CurveSegment>::iterator i;
	for (i = c1_boundary_segs.begin(); i != c1_boundary_segs.end(); ++i) {
	    std::multiset<CurveSegment> curve1_matches =
		find_similar_segments(c1_boundary_segs, *i);

	    std::multiset<CurveSegment> curve2_matches =
		find_similar_segments(c2_boundary_segs, *i);

	    if (curve1_matches.size() > 1 && curve2_matches.size() > 1) {
		continue;
	    }

	    std::multiset<CurveSegment>::iterator a, b;
	    for (a = curve1_matches.begin(); a != curve1_matches.end(); ++a) {

		b = curve2_matches.begin();
		for (; b != curve2_matches.end(); ++b) {
		    if (a->from == b->from) {
			out.insert(*i);
		    }
		}
	    }
	}
    }

    return out;
}


static bool
boolean_result_contains(op_type operation, bool first_inside,
    bool second_inside)
{
    switch (operation) {
	case BOOLEAN_INTERSECT:
	    return first_inside && second_inside;
	case BOOLEAN_DIFF:
	    return first_inside && !second_inside;
	case BOOLEAN_UNION:
	    return first_inside || second_inside;
	default:
	    return false;
    }
}


static bool
arrangement_segment_side_location(const ON_2dPoint &point,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    const BooleanLoopTolerance &tolerance, bool &first_inside,
    bool &second_inside)
{
    const CurvePoint::Location first_location =
	CurvePoint::PointLoopLocation(point, first_loop, tolerance);
    const CurvePoint::Location second_location =
	CurvePoint::PointLoopLocation(point, second_loop, tolerance);
    if (first_location == CurvePoint::BOUNDARY ||
	second_location == CurvePoint::BOUNDARY)
    {
	return false;
    }

    first_inside = first_location == CurvePoint::INSIDE;
    second_inside = second_location == CurvePoint::INSIDE;
    return true;
}


static bool
arrangement_sector_state(const ON_2dPoint &node_point,
    ON_2dVector first_ray, ON_2dVector second_ray,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    const BooleanLoopTolerance &tolerance, op_type operation,
    bool &contains)
{
    if (!node_point.IsValid() || !first_ray.Unitize() ||
	!second_ray.Unitize())
    {
	return false;
    }

    ON_2dVector direction = first_ray + second_ray;
    if (!direction.Unitize()) {
	return false;
    }

    const double base_offset = boolean_loop_closure_tolerance(
	tolerance.point);
    if (!(base_offset > 0.0) || !std::isfinite(base_offset)) {
	return false;
    }
    for (int attempt = 0; attempt < 8; ++attempt) {
	const double offset = base_offset * (1 << attempt);
	bool first_inside = false, second_inside = false;
	if (arrangement_segment_side_location(node_point + direction * offset,
	    first_loop, second_loop, tolerance, first_inside, second_inside))
	{
	    contains = boolean_result_contains(operation, first_inside,
		second_inside);
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("loop_boolean: sector at (%.17g, %.17g), direction "
		    "(%.17g, %.17g), attempt %d, offset %.17g, inside "
		    "%d/%d, result %d.\n", node_point.x, node_point.y,
		    direction.x, direction.y, attempt, offset, first_inside,
		    second_inside, contains);
		for (int diagnostic_attempt = attempt + 1;
		     diagnostic_attempt < 8; ++diagnostic_attempt)
		{
		    const double diagnostic_offset = base_offset *
			(1 << diagnostic_attempt);
		    bool diagnostic_first_inside = false;
		    bool diagnostic_second_inside = false;
		    if (!arrangement_segment_side_location(node_point + direction *
			    diagnostic_offset, first_loop, second_loop, tolerance,
			    diagnostic_first_inside, diagnostic_second_inside))
		    {
			bu_log("loop_boolean: sector diagnostic attempt %d, "
			    "offset %.17g remains on a boundary.\n",
			    diagnostic_attempt, diagnostic_offset);
			continue;
		    }
		    bu_log("loop_boolean: sector diagnostic attempt %d, "
			"offset %.17g, inside %d/%d, result %d.\n",
			diagnostic_attempt, diagnostic_offset,
			diagnostic_first_inside, diagnostic_second_inside,
			boolean_result_contains(operation,
			    diagnostic_first_inside,
			    diagnostic_second_inside));
		}
	    }
	    return true;
	}
    }
    return false;
}


static bool
arrangement_segment_transition(
    const CurveSegment &segment,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    op_type operation,
    CurveSegment &selected_segment)
{
    std::unique_ptr<ON_Curve> curve;
    try {
	curve.reset(segment.Curve());
    } catch (InvalidInterval &) {
	return false;
    }
    if (!curve) {
	return false;
    }

    const ON_Interval domain = curve->Domain();
    const double parameter = domain.Mid();
    const ON_2dPoint point = curve->PointAt(parameter);
    const ON_3dVector tangent = curve->TangentAt(parameter);
    ON_2dVector normal(-tangent.y, tangent.x);
    if (!domain.IsIncreasing() || !point.IsValid() || !normal.Unitize()) {
	return false;
    }

    const double base_offset = boolean_loop_closure_tolerance(
	segment.tolerance.point);
    if (!(base_offset > 0.0) || !std::isfinite(base_offset)) {
	return false;
    }

    for (int attempt = 0; attempt < 8; ++attempt) {
	const double offset = base_offset * (1 << attempt);
	bool first_inside_left = false, second_inside_left = false;
	bool first_inside_right = false, second_inside_right = false;
	if (!arrangement_segment_side_location(point + normal * offset,
		first_loop, second_loop, segment.tolerance, first_inside_left,
		second_inside_left) ||
	    !arrangement_segment_side_location(point - normal * offset,
		first_loop, second_loop, segment.tolerance, first_inside_right,
		second_inside_right))
	{
	    continue;
	}

	const bool left_contains = boolean_result_contains(operation,
	    first_inside_left, second_inside_left);
	const bool right_contains = boolean_result_contains(operation,
	    first_inside_right, second_inside_right);
	if (left_contains == right_contains) {
	    return false;
	}

	selected_segment = segment;
	if (!left_contains) {
	    selected_segment.Reverse();
	}
	return true;
    }
    return false;
}


static void
append_owned_arrangement_segment(std::multiset<CurveSegment> &selected,
    const CurveSegment &candidate)
{
    for (std::multiset<CurveSegment>::const_iterator segment =
	 selected.begin(); segment != selected.end(); ++segment)
    {
	if (segment->from.HasSameTopologyNode(candidate.from) &&
	    segment->to.HasSameTopologyNode(candidate.to) &&
	    segments_are_reverse_equivalent(*segment, candidate))
	{
	    return;
	}
    }
    selected.insert(candidate);
}


static const BooleanOverlapSpan *
arrangement_overlap_span(const CurveSegment &segment,
    const std::vector<BooleanOverlapSpan> &overlap_spans)
{
    for (size_t span_index = 0; span_index < overlap_spans.size();
	 ++span_index)
    {
	if (overlap_spans[span_index].Contains(segment)) {
	    return &overlap_spans[span_index];
	}
    }
    return NULL;
}


static bool
arrangement_coincident_transition(const CurveSegment &segment,
    const ON_3dVector &second_tangent, op_type operation,
    CurveSegment &selected_segment)
{
    if (segment.from.source_loop != 1 || !second_tangent.IsValid()) {
	return false;
    }

    std::unique_ptr<ON_Curve> first_curve;
    try {
	first_curve.reset(segment.Curve());
    } catch (InvalidInterval &) {
	return false;
    }
    if (!first_curve) {
	return false;
    }

    const ON_3dVector first_tangent = first_curve->TangentAt(
	first_curve->Domain().Mid());
    if (!first_tangent.IsValid() || !second_tangent.IsValid()) {
	return false;
    }

    const bool same_direction = first_tangent * second_tangent >= 0.0;
    const bool first_inside_left = true;
    const bool second_inside_left = operation == BOOLEAN_DIFF ?
	!same_direction : same_direction;
    const bool first_inside_right = !first_inside_left;
    const bool second_inside_right = !second_inside_left;
    const bool left_contains = boolean_result_contains(operation,
	first_inside_left, second_inside_left);
    const bool right_contains = boolean_result_contains(operation,
	first_inside_right, second_inside_right);
    if (left_contains == right_contains) {
	return false;
    }

    selected_segment = segment;
    if (!left_contains) {
	selected_segment.Reverse();
    }
    return true;
}


static bool
arrangement_overlap_span_transition(const CurveSegment &segment,
    const BooleanOverlapSpan &span,
    const ON_SimpleArray<ON_Curve *> &second_loop, op_type operation,
    CurveSegment &selected_segment)
{
    if (span.second_curve_index < 0 ||
	span.second_curve_index >= second_loop.Count())
    {
	return false;
    }

    const ON_3dVector second_tangent = second_loop[span.second_curve_index]->
	TangentAt(span.second_parameters.Mid());
    return arrangement_coincident_transition(segment, second_tangent,
	operation, selected_segment);
}


static bool
select_arrangement_coincident_group(BooleanArrangement &arrangement,
    size_t group_index, op_type operation)
{
    size_t first_edge = BooleanArrangement::UNSET_EDGE;
    size_t second_edge = BooleanArrangement::UNSET_EDGE;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (edge.coincident_group != group_index) {
	    continue;
	}
	if (edge.segment.from.source_loop == 1 &&
	    first_edge == BooleanArrangement::UNSET_EDGE)
	{
	    first_edge = edge_index;
	} else if (edge.segment.from.source_loop == 2 &&
	    second_edge == BooleanArrangement::UNSET_EDGE)
	{
	    second_edge = edge_index;
	}
    }
    if (first_edge == BooleanArrangement::UNSET_EDGE ||
	second_edge == BooleanArrangement::UNSET_EDGE)
    {
	return false;
    }

    std::unique_ptr<ON_Curve> second_curve;
    try {
	second_curve.reset(arrangement.edges[second_edge].segment.Curve());
    } catch (InvalidInterval &) {
	second_curve.reset();
    }
    CurveSegment selected_segment = arrangement.edges[first_edge].segment;
    const bool selected = second_curve && arrangement_coincident_transition(
	arrangement.edges[first_edge].segment,
	second_curve->TangentAt(second_curve->Domain().Mid()), operation,
	selected_segment);

    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (edge.coincident_group != group_index) {
	    continue;
	}
	edge.selected = false;
	edge.selection_basis = BooleanArrangement::Edge::NOT_SELECTED;
	edge.selection_reason = selected ?
	    "coincident edge group represented by another edge" :
	    "coincident edge group does not bound result material";
    }
    if (selected) {
	BooleanArrangement::Edge &representative = arrangement.edges[first_edge];
	representative.segment = selected_segment;
	representative.selected = true;
	representative.selection_basis =
	    BooleanArrangement::Edge::COINCIDENT_GROUP;
	representative.selection_reason = "owned coincident edge group boundary";
    }
    return true;
}


static bool
arrangement_noncoincident_segment_owned(const CurveSegment &segment,
    op_type operation)
{
    if (segment.location == CurveSegment::BOUNDARY) {
	return false;
    }

    const bool inside_other = segment.location == CurveSegment::INSIDE;
    if (segment.from.source_loop == 1) {
	return (operation == BOOLEAN_INTERSECT && inside_other) ||
	    (operation == BOOLEAN_DIFF && !inside_other) ||
	    (operation == BOOLEAN_UNION && !inside_other);
    }

    return (operation == BOOLEAN_INTERSECT && inside_other) ||
	(operation == BOOLEAN_DIFF && inside_other) ||
	(operation == BOOLEAN_UNION && !inside_other);
}


static void
select_arrangement_edges(BooleanArrangement &arrangement,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    const std::vector<BooleanOverlapSpan> &overlap_spans,
    op_type operation)
{
    std::vector<bool> handled_groups(arrangement.edges.size(), false);
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const size_t group_index = arrangement.edges[edge_index].coincident_group;
	if (group_index == BooleanArrangement::UNSET_EDGE ||
	    handled_groups[group_index])
	{
	    continue;
	}
	if (select_arrangement_coincident_group(arrangement, group_index,
		operation))
	{
	    handled_groups[group_index] = true;
	}
    }

    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (edge.coincident_group != BooleanArrangement::UNSET_EDGE &&
	    handled_groups[edge.coincident_group])
	{
	    continue;
	}
	CurveSegment selected_segment = edge.segment;
	if (arrangement_noncoincident_segment_owned(edge.segment, operation)) {
	    edge.selected = true;
	    edge.selection_basis =
		BooleanArrangement::Edge::CLASSIFIED_NONCOINCIDENT;
	    edge.selection_reason = "owned noncoincident result boundary";
	    continue;
	}
	const BooleanOverlapSpan *overlap_span = arrangement_overlap_span(
	    edge.segment, overlap_spans);
	if (overlap_span != NULL) {
	    if (edge.segment.from.source_loop == 1 &&
		arrangement_overlap_span_transition(edge.segment, *overlap_span,
		    second_loop, operation, selected_segment))
	    {
		edge.segment = selected_segment;
		edge.selected = true;
		edge.selection_basis =
		    BooleanArrangement::Edge::COINCIDENT_OVERLAP;
		edge.selection_reason = "owned coincident overlap boundary";
	    } else if (edge.segment.from.source_loop != 1) {
		edge.selection_reason =
		    "coincident overlap represented by source loop 1";
	    } else {
		edge.selection_reason =
		    "coincident overlap does not bound result material";
	    }
	    continue;
	}
	if (edge.segment.location == CurveSegment::BOUNDARY &&
	    arrangement_segment_transition(edge.segment, first_loop, second_loop,
	    operation, selected_segment))
	{
	    edge.segment = selected_segment;
	    edge.selected = true;
	    edge.selection_basis = BooleanArrangement::Edge::SAMPLED_BOUNDARY;
	    edge.selection_reason = "owned sampled boundary transition";
	} else if (edge.segment.location == CurveSegment::BOUNDARY) {
	    edge.selection_basis =
		BooleanArrangement::Edge::SAMPLED_NO_TRANSITION;
	    edge.selection_reason =
		"boundary samples do not change result membership";
	} else {
	    edge.selection_reason = "noncoincident segment is not owned by result";
	}
    }
}


static bool
arrangement_parameter_is_endpoint(double parameter, ON_Interval domain,
    double parameter_tolerance, bool &at_start, bool &at_end)
{
    at_start = false;
    at_end = false;
    if (!domain.IsIncreasing() || !std::isfinite(parameter) ||
	!(parameter_tolerance > 0.0) || !std::isfinite(parameter_tolerance))
    {
	return false;
    }

    const double parameter_scale = std::max(1.0, std::max(
	fabs(domain.Min()), fabs(domain.Max())));
    const double tolerance = std::max(parameter_tolerance,
	16.0 * ON_ZERO_TOLERANCE * parameter_scale);
    at_start = ON_NearZero(parameter - domain.Min(), tolerance);
    at_end = ON_NearZero(parameter - domain.Max(), tolerance);
    return at_start || at_end;
}


static bool
arrangement_segments_have_only_shared_endpoint_intersections(
    const CurveSegment &first, const CurveSegment &second)
{
    std::unique_ptr<ON_Curve> first_curve;
    std::unique_ptr<ON_Curve> second_curve;
    try {
	first_curve.reset(first.Curve());
	second_curve.reset(second.Curve());
    } catch (InvalidInterval &) {
	return false;
    }
    if (!first_curve || !second_curve ||
	!first_curve->Domain().IsIncreasing() ||
	!second_curve->Domain().IsIncreasing())
    {
	return false;
    }

    ON_SimpleArray<ON_X_EVENT> events;
    intersect_boolean_curves(first_curve.get(), second_curve.get(), events,
	std::max(INTERSECTION_TOL,
	    std::max(first.tolerance.point, second.tolerance.point)));
    for (int event_index = 0; event_index < events.Count(); ++event_index) {
	const ON_X_EVENT &event = events[event_index];
	if (event.m_type == ON_X_EVENT::ccx_overlap) {
	    return false;
	}

	bool first_start = false, first_end = false;
	bool second_start = false, second_end = false;
	if (!arrangement_parameter_is_endpoint(event.m_a[0],
		first_curve->Domain(), first.tolerance.curve_parameter,
		first_start, first_end) ||
	    !arrangement_parameter_is_endpoint(event.m_b[0],
		second_curve->Domain(), second.tolerance.curve_parameter,
		second_start, second_end) ||
	    !((first_start && second_start) || (first_end && second_end)))
	{
	    return false;
	}
    }

    return true;
}


/* Return 1 when the second arc is consistently left of the first, -1 when it
 * is consistently right, and 0 when their relative side cannot be certified.
 * Use a roundoff-scale threshold rather than the loop classification tolerance:
 * these arcs are ambiguous precisely because their separation is smaller than
 * that classification tolerance. */
static int
arrangement_segment_relative_side(const CurveSegment &first,
    const CurveSegment &second)
{
    std::unique_ptr<ON_Curve> first_curve;
    std::unique_ptr<ON_Curve> second_curve;
    try {
	first_curve.reset(first.Curve());
	second_curve.reset(second.Curve());
    } catch (InvalidInterval &) {
	return 0;
    }
    if (!first_curve || !second_curve ||
	!first_curve->Domain().IsIncreasing() ||
	!second_curve->Domain().IsIncreasing())
    {
	return 0;
    }

    const double sample_fractions[] = {0.25, 0.5, 0.75};
    const double side_tolerance_multiplier = 64.0;
    int relative_side = 0;
    for (size_t sample_index = 0;
	 sample_index < sizeof(sample_fractions) / sizeof(sample_fractions[0]);
	 ++sample_index)
    {
	const double first_parameter = first_curve->Domain().ParameterAt(
	    sample_fractions[sample_index]);
	const double second_parameter = second_curve->Domain().ParameterAt(
	    sample_fractions[sample_index]);
	const ON_3dPoint first_point = first_curve->PointAt(first_parameter);
	const ON_3dPoint second_point = second_curve->PointAt(second_parameter);
	const ON_3dVector first_curve_tangent = first_curve->TangentAt(
	    first_parameter);
	const ON_3dVector second_curve_tangent = second_curve->TangentAt(
	    second_parameter);
	ON_2dVector first_tangent(first_curve_tangent.x,
	    first_curve_tangent.y);
	ON_2dVector second_tangent(second_curve_tangent.x,
	    second_curve_tangent.y);
	if (!first_point.IsValid() || !second_point.IsValid() ||
	    !first_curve_tangent.IsValid() ||
	    !second_curve_tangent.IsValid() || !first_tangent.Unitize() ||
	    !second_tangent.Unitize())
	{
	    return 0;
	}

	const double tangent_dot = first_tangent.x * second_tangent.x +
	    first_tangent.y * second_tangent.y;
	if (!(tangent_dot > 0.0)) {
	    return 0;
	}

	double coordinate_scale = 1.0;
	coordinate_scale = std::max(coordinate_scale, fabs(first_point.x));
	coordinate_scale = std::max(coordinate_scale, fabs(first_point.y));
	coordinate_scale = std::max(coordinate_scale, fabs(second_point.x));
	coordinate_scale = std::max(coordinate_scale, fabs(second_point.y));
	const double side_tolerance = side_tolerance_multiplier * ON_EPSILON *
	    coordinate_scale;
	if (!std::isfinite(side_tolerance)) {
	    return 0;
	}

	const ON_2dVector separation(second_point.x - first_point.x,
	    second_point.y - first_point.y);
	const double first_cross = first_tangent.x * separation.y -
	    first_tangent.y * separation.x;
	const double second_cross = second_tangent.x * separation.y -
	    second_tangent.y * separation.x;
	if (fabs(first_cross) <= side_tolerance ||
	    fabs(second_cross) <= side_tolerance ||
	    (first_cross > 0.0) != (second_cross > 0.0))
	{
	    return 0;
	}

	const int sample_side = first_cross > 0.0 ? 1 : -1;
	if (relative_side != 0 && relative_side != sample_side) {
	    return 0;
	}
	relative_side = sample_side;
    }

    return relative_side;
}


static bool
arrangement_segment_is_tolerance_scale(const CurveSegment &segment)
{
    if (!(segment.tolerance.point > 0.0) ||
	!std::isfinite(segment.tolerance.point))
    {
	return false;
    }

    std::unique_ptr<ON_Curve> curve;
    try {
	curve.reset(segment.Curve());
    } catch (InvalidInterval &) {
	return false;
    }
    if (!curve) {
	return false;
    }

    const ON_BoundingBox bounds = curve->BoundingBox();
    if (!bounds.IsValid()) {
	return false;
    }
    const double maximum_extent =
	BOOLEAN_AMBIGUOUS_BRIDGE_TOLERANCE_MULTIPLIER *
	segment.tolerance.point;
    const double extent = bounds.Diagonal().Length();
    return std::isfinite(maximum_extent) && std::isfinite(extent) &&
	extent <= maximum_extent;
}


static bool
select_tolerance_scale_sampled_boundary_bridge(
    BooleanArrangement &arrangement, size_t excess_incoming_node,
    size_t excess_outgoing_node)
{
    std::vector<size_t> candidates;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected &&
	    edge.segment.from.node_id == excess_incoming_node &&
	    edge.segment.to.node_id == excess_outgoing_node)
	{
	    candidates.push_back(edge_index);
	}
    }
    if (candidates.size() != 1) {
	return false;
    }

    BooleanArrangement::Edge &candidate = arrangement.edges[candidates[0]];
    if (candidate.selection_basis !=
	    BooleanArrangement::Edge::SAMPLED_NO_TRANSITION ||
	!arrangement_segment_is_tolerance_scale(candidate.segment))
    {
	return false;
    }

    size_t predecessor = BooleanArrangement::UNSET_EDGE;
    size_t successor = BooleanArrangement::UNSET_EDGE;
    size_t incoming_at_start = 0;
    size_t outgoing_at_start = 0;
    size_t incoming_at_end = 0;
    size_t outgoing_at_end = 0;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected || edge.segment.from.HasSameTopologyNode(
		edge.segment.to))
	{
	    continue;
	}
	if (edge.segment.to.node_id == excess_incoming_node) {
	    predecessor = edge_index;
	    ++incoming_at_start;
	}
	if (edge.segment.from.node_id == excess_incoming_node) {
	    ++outgoing_at_start;
	}
	if (edge.segment.to.node_id == excess_outgoing_node) {
	    ++incoming_at_end;
	}
	if (edge.segment.from.node_id == excess_outgoing_node) {
	    successor = edge_index;
	    ++outgoing_at_end;
	}
    }
    if (incoming_at_start != 1 || outgoing_at_start != 0 ||
	incoming_at_end != 0 || outgoing_at_end != 1 ||
	predecessor == BooleanArrangement::UNSET_EDGE ||
	successor == BooleanArrangement::UNSET_EDGE)
    {
	return false;
    }

    const BooleanArrangement::Edge &previous = arrangement.edges[predecessor];
    const BooleanArrangement::Edge &next = arrangement.edges[successor];
    const int candidate_source = candidate.segment.from.source_loop;
    if (candidate_source != candidate.segment.to.source_loop ||
	previous.selection_basis != BooleanArrangement::Edge::COINCIDENT_GROUP ||
	next.selection_basis != BooleanArrangement::Edge::COINCIDENT_GROUP ||
	previous.segment.from.source_loop == candidate_source ||
	next.segment.from.source_loop == candidate_source ||
	previous.segment.from.source_loop != next.segment.from.source_loop ||
	previous.paired_edge >= arrangement.edges.size() ||
	next.paired_edge >= arrangement.edges.size())
    {
	return false;
    }

    const BooleanArrangement::Edge &previous_pair =
	arrangement.edges[previous.paired_edge];
    const BooleanArrangement::Edge &next_pair =
	arrangement.edges[next.paired_edge];
    if (previous_pair.selected || next_pair.selected ||
	previous_pair.segment.from.source_loop != candidate_source ||
	next_pair.segment.from.source_loop != candidate_source ||
	previous_pair.coincident_group != previous.coincident_group ||
	next_pair.coincident_group != next.coincident_group ||
	(previous_pair.segment.from.node_id != excess_incoming_node &&
	 previous_pair.segment.to.node_id != excess_incoming_node) ||
	(next_pair.segment.from.node_id != excess_outgoing_node &&
	 next_pair.segment.to.node_id != excess_outgoing_node))
    {
	return false;
    }

    candidate.selected = true;
    candidate.selection_basis = BooleanArrangement::Edge::SAMPLED_BOUNDARY;
    candidate.selection_reason =
	"sampled boundary closes coincident result chain";
    return true;
}


/* An SSI overlap can terminate on a source boundary that departs from it by
 * no more than the accumulated endpoint tolerance.  The overlap selector
 * then retains the SSI arc, while side sampling correctly finds no material
 * transition on the reverse source arc.  Together they bound only a
 * tolerance-width sliver, but leaving the SSI arc selected produces one
 * excess outgoing and one excess incoming arrangement node.
 *
 * Do not repair that imbalance from topology alone.  Require the operation
 * to be an intersection, the dangling arc to be an overlap boundary, the
 * unique reverse arc to have independently sampled no transition, and their
 * complete lifted loci to be reverse-coincident within the same two-endpoint
 * bound used for loop closure.  Restricting the proof to a shared affine
 * surface avoids treating a small parameter-space gap as a small model-space
 * gap on a distorted surface. */
static bool
prune_tolerance_width_dangling_intersection_sliver(
    BooleanArrangement &arrangement, size_t selected_index,
    size_t excess_outgoing_node, size_t excess_incoming_node,
    op_type operation)
{
    if (operation != BOOLEAN_INTERSECT ||
	selected_index >= arrangement.edges.size())
    {
	return false;
    }

    BooleanArrangement::Edge &selected = arrangement.edges[selected_index];
    if (!selected.selected ||
	selected.selection_basis != BooleanArrangement::Edge::COINCIDENT_OVERLAP ||
	selected.segment.location != CurveSegment::BOUNDARY ||
	selected.segment.from.node_id != excess_outgoing_node ||
	selected.segment.to.node_id != excess_incoming_node ||
	selected.segment.from.HasSameTopologyNode(selected.segment.to))
    {
	return false;
    }

    size_t reverse_index = BooleanArrangement::UNSET_EDGE;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (edge.selected ||
	    edge.segment.from.node_id != excess_incoming_node ||
	    edge.segment.to.node_id != excess_outgoing_node)
	{
	    continue;
	}
	if (reverse_index != BooleanArrangement::UNSET_EDGE) {
	    return false;
	}
	reverse_index = edge_index;
    }
    if (reverse_index == BooleanArrangement::UNSET_EDGE) {
	return false;
    }

    const BooleanArrangement::Edge &reverse = arrangement.edges[reverse_index];
    if (reverse.selection_basis !=
	    BooleanArrangement::Edge::SAMPLED_NO_TRANSITION ||
	reverse.segment.location != CurveSegment::BOUNDARY ||
	selected.segment.from.source_loop == reverse.segment.from.source_loop ||
	selected.segment.tolerance.surface == NULL ||
	selected.segment.tolerance.surface != reverse.segment.tolerance.surface)
    {
	return false;
    }

    std::unique_ptr<ON_Curve> selected_parameter;
    std::unique_ptr<ON_Curve> reverse_parameter;
    try {
	selected_parameter.reset(selected.segment.Curve());
	reverse_parameter.reset(reverse.segment.Curve());
    } catch (InvalidInterval &) {
	return false;
    }
    if (!selected_parameter || !reverse_parameter) {
	return false;
    }

    std::unique_ptr<ON_Curve> selected_model(pushup_affine_boolean_curve(
	selected.segment.tolerance.surface, *selected_parameter));
    std::unique_ptr<ON_Curve> reverse_model(pushup_affine_boolean_curve(
	reverse.segment.tolerance.surface, *reverse_parameter));
    if (!selected_model || !reverse_model) {
	return false;
    }

    ON_BoundingBox bounds = selected_model->BoundingBox();
    const ON_BoundingBox reverse_bounds = reverse_model->BoundingBox();
    if (!bounds.IsValid() || !reverse_bounds.IsValid()) {
	return false;
    }
    bounds.Set(reverse_bounds.m_min, true);
    bounds.Set(reverse_bounds.m_max, true);
    const double proof_tolerance = std::min(
	boolean_loop_closure_tolerance(INTERSECTION_TOL),
	boolean_model_repair_tolerance(bounds));
    bool reversed = false;
    if (!(proof_tolerance > 0.0) || !std::isfinite(proof_tolerance) ||
	!brep_curves_coincident(*selected_model, *reverse_model,
	    proof_tolerance, &reversed) || !reversed)
    {
	return false;
    }

    selected.selected = false;
    selected.selection_basis = BooleanArrangement::Edge::NOT_SELECTED;
    selected.selection_reason =
	"certified tolerance-width dangling intersection sliver was pruned";
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("loop_boolean: pruned dangling affine intersection sliver edge "
	    "%zu opposite edge %zu at tolerance %.17g.\n", selected_index,
	    reverse_index, proof_tolerance);
    }
    return true;
}


static bool
prune_certified_affine_open_sliver(
    BooleanArrangement &arrangement,
    size_t excess_incoming_node,
    size_t excess_outgoing_node,
    op_type operation)
{
    if (operation != BOOLEAN_INTERSECT) {
	return false;
    }

    size_t bridge_index = BooleanArrangement::UNSET_EDGE;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (edge.selected ||
	    edge.segment.from.node_id != excess_incoming_node ||
	    edge.segment.to.node_id != excess_outgoing_node)
	{
	    continue;
	}
	if (bridge_index != BooleanArrangement::UNSET_EDGE) {
	    return false;
	}
	bridge_index = edge_index;
    }
    if (bridge_index == BooleanArrangement::UNSET_EDGE) {
	return false;
    }

    const BooleanArrangement::Edge &bridge = arrangement.edges[bridge_index];
    if (bridge.segment.location != CurveSegment::OUTSIDE ||
	bridge.selection_basis != BooleanArrangement::Edge::NOT_SELECTED)
    {
	return false;
    }

    std::vector<size_t> path;
    size_t node = excess_outgoing_node;
    std::set<size_t> visited_nodes;
    while (node != excess_incoming_node) {
	if (!visited_nodes.insert(node).second ||
	    path.size() >= arrangement.edges.size())
	{
	    return false;
	}
	size_t outgoing = BooleanArrangement::UNSET_EDGE;
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    if (!edge.selected || edge.segment.from.node_id != node ||
		edge.segment.from.HasSameTopologyNode(edge.segment.to))
	    {
		continue;
	    }
	    if (outgoing != BooleanArrangement::UNSET_EDGE) {
		return false;
	    }
	    outgoing = edge_index;
	}
	if (outgoing == BooleanArrangement::UNSET_EDGE) {
	    return false;
	}
	path.push_back(outgoing);
	node = arrangement.edges[outgoing].segment.to.node_id;
    }
    if (path.size() != 3) {
	return false;
    }

    const BooleanArrangement::Edge &first_connector =
	arrangement.edges[path[0]];
    const BooleanArrangement::Edge &spine = arrangement.edges[path[1]];
    const BooleanArrangement::Edge &second_connector =
	arrangement.edges[path[2]];
    const int bridge_source = bridge.segment.from.source_loop;
    const int connector_source = first_connector.segment.from.source_loop;
    if (bridge_source != bridge.segment.to.source_loop ||
	spine.segment.from.source_loop != bridge_source ||
	spine.segment.to.source_loop != bridge_source ||
	connector_source == bridge_source ||
	first_connector.segment.to.source_loop != connector_source ||
	second_connector.segment.from.source_loop != connector_source ||
	second_connector.segment.to.source_loop != connector_source ||
	first_connector.selection_basis !=
	    BooleanArrangement::Edge::CLASSIFIED_NONCOINCIDENT ||
	second_connector.selection_basis !=
	    BooleanArrangement::Edge::CLASSIFIED_NONCOINCIDENT ||
	first_connector.segment.location != CurveSegment::INSIDE ||
	second_connector.segment.location != CurveSegment::INSIDE ||
	(spine.selection_basis != BooleanArrangement::Edge::COINCIDENT_GROUP &&
	 spine.selection_basis != BooleanArrangement::Edge::COINCIDENT_OVERLAP))
    {
	return false;
    }

    const ON_Surface *surface = bridge.segment.tolerance.surface;
    if (surface == NULL || first_connector.segment.tolerance.surface != surface ||
	spine.segment.tolerance.surface != surface ||
	second_connector.segment.tolerance.surface != surface)
    {
	return false;
    }

    const auto lifted_segment = [](const CurveSegment &segment) {
	std::unique_ptr<ON_Curve> parameter_curve;
	try {
	    parameter_curve.reset(segment.Curve());
	} catch (InvalidInterval &) {
	    parameter_curve.reset();
	}
	return std::unique_ptr<ON_Curve>(parameter_curve ?
	    pushup_affine_boolean_curve(segment.tolerance.surface,
		*parameter_curve) : NULL);
    };
    std::unique_ptr<ON_Curve> bridge_curve(lifted_segment(bridge.segment));
    std::unique_ptr<ON_Curve> first_connector_curve(
	lifted_segment(first_connector.segment));
    std::unique_ptr<ON_Curve> spine_curve(lifted_segment(spine.segment));
    std::unique_ptr<ON_Curve> second_connector_curve(
	lifted_segment(second_connector.segment));
    if (!bridge_curve || !first_connector_curve || !spine_curve ||
	!second_connector_curve)
    {
	return false;
    }

    ON_BoundingBox bounds = bridge_curve->BoundingBox();
    const ON_BoundingBox spine_bounds = spine_curve->BoundingBox();
    if (!bounds.IsValid() || !spine_bounds.IsValid()) {
	return false;
    }
    bounds.Set(spine_bounds.m_min, true);
    bounds.Set(spine_bounds.m_max, true);
    const double maximum_tolerance = boolean_model_repair_tolerance(bounds);
    double proof_tolerance = std::min(maximum_tolerance, INTERSECTION_TOL);
    bool certified = false;
    while (true) {
	bool reversed = false;
	const ON_3dPoint bridge_start = bridge_curve->PointAtStart();
	const ON_3dPoint bridge_end = bridge_curve->PointAtEnd();
	certified = bridge_start.IsValid() && bridge_end.IsValid() &&
	    brep_curves_coincident(*bridge_curve, *spine_curve,
		proof_tolerance, &reversed) && reversed &&
	    brep_curve_locus_within_ball(*first_connector_curve,
		bridge_end, proof_tolerance) &&
	    brep_curve_locus_within_ball(*second_connector_curve,
		bridge_start, proof_tolerance);
	if (certified || proof_tolerance >= maximum_tolerance) {
	    break;
	}
	proof_tolerance = std::min(maximum_tolerance,
	    2.0 * proof_tolerance);
    }
    if (!certified) {
	return false;
    }

    for (size_t path_index = 0; path_index < path.size(); ++path_index) {
	BooleanArrangement::Edge &edge = arrangement.edges[path[path_index]];
	edge.selected = false;
	edge.selection_basis = BooleanArrangement::Edge::NOT_SELECTED;
	edge.selection_reason =
	    "certified tolerance-width open intersection sliver was pruned";
    }
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("loop_boolean: pruned certified affine open sliver edges "
	    "%zu/%zu/%zu opposite edge %zu at tolerance %.17g.\n",
	    path[0], path[1], path[2], bridge_index, proof_tolerance);
    }
    return true;
}


/* An intersection can collapse to a tolerance-width open sliver when one
 * source loop contributes one selected inside edge and the other source loop
 * contributes an unselected outside path between the same endpoints.  Do not
 * infer an empty result from topology alone: lift both sides through their
 * common affine parameter surface and require a reversed model-space
 * coincidence proof. */
static bool
certify_single_edge_affine_intersection_sliver(
    const BooleanArrangement &arrangement,
    op_type operation)
{
    if (operation != BOOLEAN_INTERSECT) {
	return false;
    }

    size_t selected_index = BooleanArrangement::UNSET_EDGE;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected) {
	    continue;
	}
	if (selected_index != BooleanArrangement::UNSET_EDGE ||
	    edge.segment.from.HasSameTopologyNode(edge.segment.to))
	{
	    return false;
	}
	selected_index = edge_index;
    }
    if (selected_index == BooleanArrangement::UNSET_EDGE) {
	return false;
    }

    const BooleanArrangement::Edge &selected =
	arrangement.edges[selected_index];
    if (selected.selection_basis !=
	    BooleanArrangement::Edge::CLASSIFIED_NONCOINCIDENT ||
	selected.segment.location != CurveSegment::INSIDE ||
	selected.segment.from.source_loop != selected.segment.to.source_loop)
    {
	return false;
    }

    const int selected_source = selected.segment.from.source_loop;
    const int path_source = selected_source == 1 ? 2 :
	(selected_source == 2 ? 1 : 0);
    if (path_source == 0) {
	return false;
    }

    std::vector<size_t> path;
    std::set<size_t> visited_nodes;
    size_t node = selected.segment.to.node_id;
    while (node != selected.segment.from.node_id) {
	if (!visited_nodes.insert(node).second ||
	    path.size() >= arrangement.edges.size())
	{
	    return false;
	}

	size_t outgoing = BooleanArrangement::UNSET_EDGE;
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    if (edge.segment.from.source_loop != path_source ||
		edge.segment.to.source_loop != path_source ||
		edge.segment.from.node_id != node ||
		edge.segment.from.HasSameTopologyNode(edge.segment.to))
	    {
		continue;
	    }
	    if (outgoing != BooleanArrangement::UNSET_EDGE) {
		return false;
	    }
	    outgoing = edge_index;
	}
	if (outgoing == BooleanArrangement::UNSET_EDGE) {
	    return false;
	}

	const BooleanArrangement::Edge &edge = arrangement.edges[outgoing];
	if (edge.selected ||
	    edge.selection_basis != BooleanArrangement::Edge::NOT_SELECTED ||
	    edge.segment.location != CurveSegment::OUTSIDE)
	{
	    return false;
	}
	path.push_back(outgoing);
	node = edge.segment.to.node_id;
    }
    if (path.empty()) {
	return false;
    }

    const ON_Surface *surface = selected.segment.tolerance.surface;
    if (surface == NULL) {
	return false;
    }
    for (size_t path_index = 0; path_index < path.size(); ++path_index) {
	if (arrangement.edges[path[path_index]].segment.tolerance.surface !=
		surface)
	{
	    return false;
	}
    }

    const auto lifted_segment = [](const CurveSegment &segment) {
	std::unique_ptr<ON_Curve> parameter_curve;
	try {
	    parameter_curve.reset(segment.Curve());
	} catch (InvalidInterval &) {
	    parameter_curve.reset();
	}
	return std::unique_ptr<ON_Curve>(parameter_curve ?
	    pushup_affine_boolean_curve(segment.tolerance.surface,
		*parameter_curve) : NULL);
    };

    std::unique_ptr<ON_Curve> selected_curve(
	lifted_segment(selected.segment));
    if (!selected_curve) {
	return false;
    }
    const ON_BoundingBox selected_bounds = selected_curve->BoundingBox();
    const double selected_extent = selected_bounds.IsValid() ?
	selected_bounds.Diagonal().Length() : 0.0;
    if (!(selected_extent >= INTERSECTION_TOL) ||
	!std::isfinite(selected_extent))
    {
	return false;
    }

    ON_PolyCurve path_curve;
    for (size_t path_index = 0; path_index < path.size(); ++path_index) {
	std::unique_ptr<ON_Curve> lifted(
	    lifted_segment(arrangement.edges[path[path_index]].segment));
	if (!lifted) {
	    return false;
	}
	const ON_BoundingBox segment_bounds = lifted->BoundingBox();
	const double segment_extent = segment_bounds.IsValid() ?
	    segment_bounds.Diagonal().Length() : 0.0;
	if (!(segment_extent >= INTERSECTION_TOL) ||
	    !std::isfinite(segment_extent))
	{
	    return false;
	}
	if (!append_boolean_loop_curve_to_polycurve(lifted.release(),
		path_curve))
	{
	    return false;
	}
    }
    const ON_BoundingBox path_bounds = path_curve.BoundingBox();
    const double path_extent = path_bounds.IsValid() ?
	path_bounds.Diagonal().Length() : 0.0;
    if (!(path_extent >= INTERSECTION_TOL) || !std::isfinite(path_extent) ||
	!path_curve.IsValid() || !path_curve.Domain().IsIncreasing())
    {
	return false;
    }

    ON_BoundingBox proof_bounds = selected_bounds;
    proof_bounds.Set(path_bounds.m_min, true);
    proof_bounds.Set(path_bounds.m_max, true);
    const ON_BoundingBox surface_bounds = surface->BoundingBox();
    const double surface_repair_tolerance =
	boolean_model_repair_tolerance(surface_bounds);
    const double candidate_extent = proof_bounds.IsValid() ?
	proof_bounds.Diagonal().Length() : 0.0;
    /* The ordinary repair tolerance may be intentionally generous on a large
     * model.  A disappearing intersection sliver needs a tighter proof: use
     * the geometric mean of the base and surface-scale repair tolerances, and
     * never use a tolerance larger than the complete candidate itself. */
    const double maximum_tolerance = std::min(candidate_extent,
	sqrt(INTERSECTION_TOL * surface_repair_tolerance));
    if (!(maximum_tolerance >= INTERSECTION_TOL) ||
	!std::isfinite(maximum_tolerance))
    {
	return false;
    }

    double proof_tolerance = INTERSECTION_TOL;
    while (true) {
	bool reversed = false;
	const bool coincident = brep_curves_coincident(*selected_curve,
	    path_curve, proof_tolerance, &reversed);
	if (coincident && reversed) {
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("loop_boolean: certified empty affine intersection sliver "
		    "edge %zu against %zu-edge opposite path at tolerance "
		    "%.17g (candidate extent %.17g, surface repair limit "
		    "%.17g).\n", selected_index, path.size(), proof_tolerance,
		    candidate_extent, surface_repair_tolerance);
	    }
	    return true;
	}
	if (proof_tolerance >= maximum_tolerance) {
	    return false;
	}
	proof_tolerance = std::min(maximum_tolerance,
	    2.0 * proof_tolerance);
    }
}


/* A tolerance-ambiguous sample can produce exactly one excess outgoing node
 * and one excess incoming node.  Resolve only two certified configurations:
 * remove one of two shadowing selected arcs, or restore one tolerance-scale
 * rejected boundary that joins two selected coincident-group boundaries. */
/* A periodic cut can be represented as an open UV path whose endpoints are
 * opposite copies of the same surface seam.  The planar inside test may reject
 * that path even though its lift is a closed model-space boundary. */
static bool
arrangement_path_spans_one_periodic_domain(
    const BooleanArrangement &arrangement,
    const std::vector<size_t> &path,
    const ON_Surface *surface,
    double parameter_tolerance)
{
    if (path.size() < 2 || surface == NULL ||
	!(parameter_tolerance > 0.0) || !std::isfinite(parameter_tolerance))
    {
	return false;
    }

    const ON_2dPoint start =
	arrangement.edges[path.front()].segment.from.pt;
    const ON_2dPoint end = arrangement.edges[path.back()].segment.to.pt;
    int spanning_direction = -1;
    for (int direction = 0; direction < 2; ++direction) {
	if (!surface->IsClosed(direction) && !surface->IsPeriodic(direction)) {
	    continue;
	}
	ON_Interval domain = surface->Domain(direction);
	domain.MakeIncreasing();
	const bool opposite_sides =
	    (fabs(start[direction] - domain.Min()) <= parameter_tolerance &&
	     fabs(end[direction] - domain.Max()) <= parameter_tolerance) ||
	    (fabs(start[direction] - domain.Max()) <= parameter_tolerance &&
	     fabs(end[direction] - domain.Min()) <= parameter_tolerance);
	if (!opposite_sides) {
	    continue;
	}
	if (spanning_direction >= 0) {
	    return false;
	}
	spanning_direction = direction;
    }
    if (spanning_direction < 0 ||
	fabs(start[1 - spanning_direction] - end[1 - spanning_direction]) >
	    parameter_tolerance)
    {
	return false;
    }

    static const int samples_per_segment = 32;
    ON_BoundingBox bounds = ON_BoundingBox::EmptyBoundingBox;
    ON_3dPoint first_model_point = ON_3dPoint::UnsetPoint;
    ON_3dPoint previous_model_end = ON_3dPoint::UnsetPoint;
    double maximum_join_gap = 0.0;
    for (size_t path_index = 0; path_index < path.size(); ++path_index) {
	const CurveSegment &segment =
	    arrangement.edges[path[path_index]].segment;
	std::unique_ptr<ON_Curve> parameter_curve;
	try {
	    parameter_curve.reset(segment.Curve());
	} catch (InvalidInterval &) {
	    return false;
	}
	if (!parameter_curve || !parameter_curve->Domain().IsIncreasing()) {
	    return false;
	}
	const ON_Interval domain = parameter_curve->Domain();
	for (int sample = 0; sample <= samples_per_segment; ++sample) {
	    const ON_3dPoint parameter = parameter_curve->PointAt(
		domain.ParameterAt(static_cast<double>(sample) /
		    samples_per_segment));
	    const ON_3dPoint model = surface->PointAt(parameter.x, parameter.y);
	    if (!parameter.IsValid() || !model.IsValid()) {
		return false;
	    }
	    if (path_index == 0 && sample == 0)
		first_model_point = model;
	    if (path_index > 0 && sample == 0)
		maximum_join_gap = std::max(maximum_join_gap,
		    previous_model_end.DistanceTo(model));
	    bounds.Set(model, true);
	    if (sample == samples_per_segment)
		previous_model_end = model;
	}
    }

    const double model_tolerance = boolean_model_repair_tolerance(bounds);
    return bounds.IsValid() && first_model_point.IsValid() &&
	previous_model_end.IsValid() && maximum_join_gap <= model_tolerance &&
	bounds.Diagonal().Length() > model_tolerance &&
	first_model_point.DistanceTo(previous_model_end) <=
	    model_tolerance;
}


static bool
select_certified_periodic_boundary_path(BooleanArrangement &arrangement,
    size_t excess_incoming_node, size_t excess_outgoing_node,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    const BooleanLoopTolerance &tolerance, op_type operation)
{
    if (operation != BOOLEAN_INTERSECT) {
	return false;
    }

    size_t first_selected = BooleanArrangement::UNSET_EDGE;
    size_t last_selected = BooleanArrangement::UNSET_EDGE;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected) {
	    continue;
	}
	if (edge.segment.from.node_id == excess_outgoing_node) {
	    if (first_selected != BooleanArrangement::UNSET_EDGE) return false;
	    first_selected = edge_index;
	}
	if (edge.segment.to.node_id == excess_incoming_node) {
	    if (last_selected != BooleanArrangement::UNSET_EDGE) return false;
	    last_selected = edge_index;
	}
    }
    if (first_selected == BooleanArrangement::UNSET_EDGE ||
	last_selected == BooleanArrangement::UNSET_EDGE)
    {
	return false;
    }
    const int selected_source = arrangement.edges[first_selected].segment.
	from.source_loop;
    if (selected_source != arrangement.edges[last_selected].segment.from.
	    source_loop)
    {
	return false;
    }
    const int source_loop = selected_source == 1 ? 2 :
	(selected_source == 2 ? 1 : 0);
    if (source_loop == 0) {
	return false;
    }

    std::set<size_t> selected_nodes;
    size_t selected_node = excess_outgoing_node;
    size_t selected_inside_edges = 0;
    while (selected_node != excess_incoming_node) {
	if (!selected_nodes.insert(selected_node).second) {
	    return false;
	}
	size_t selected_edge = BooleanArrangement::UNSET_EDGE;
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    if (!edge.selected || edge.segment.from.node_id != selected_node ||
		edge.segment.from.HasSameTopologyNode(edge.segment.to))
	    {
		continue;
	    }
	    if (selected_edge != BooleanArrangement::UNSET_EDGE) {
		return false;
	    }
	    selected_edge = edge_index;
	}
	if (selected_edge == BooleanArrangement::UNSET_EDGE) {
	    return false;
	}
	const BooleanArrangement::Edge &edge = arrangement.edges[selected_edge];
	if (edge.segment.from.source_loop != selected_source) {
	    return false;
	}
	if (edge.selection_basis ==
		BooleanArrangement::Edge::CLASSIFIED_NONCOINCIDENT) {
	    if (edge.segment.location != CurveSegment::INSIDE) {
		return false;
	    }
	    ++selected_inside_edges;
	} else if (edge.selection_basis !=
		BooleanArrangement::Edge::COINCIDENT_GROUP &&
	    edge.selection_basis != BooleanArrangement::Edge::COINCIDENT_OVERLAP)
	{
	    return false;
	}
	selected_node = edge.segment.to.node_id;
    }
    if (selected_inside_edges > 1) {
	return false;
    }

    std::vector<size_t> path;
    std::set<size_t> visited_nodes;
    size_t node = excess_incoming_node;
    int loop_index = -1;
    const ON_Surface *surface = NULL;
    while (node != excess_outgoing_node) {
	if (!visited_nodes.insert(node).second ||
	    path.size() >= arrangement.edges.size())
	{
	    return false;
	}

	size_t candidate_index = BooleanArrangement::UNSET_EDGE;
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    if (edge.selected || edge.segment.from.node_id != node ||
		edge.segment.from.HasSameTopologyNode(edge.segment.to) ||
		edge.selection_basis != BooleanArrangement::Edge::NOT_SELECTED ||
		edge.segment.location != CurveSegment::OUTSIDE)
	    {
		continue;
	    }
	    if (edge.segment.from.source_loop != source_loop ||
		(!path.empty() &&
		(edge.segment.from.source_loop != source_loop ||
		 edge.segment.from.loop_index != loop_index ||
		 edge.segment.tolerance.surface != surface)))
	    {
		continue;
	    }
	    if (candidate_index != BooleanArrangement::UNSET_EDGE) {
		return false;
	    }
	    candidate_index = edge_index;
	}
	if (candidate_index == BooleanArrangement::UNSET_EDGE) {
	    return false;
	}

	const BooleanArrangement::Edge &candidate =
	    arrangement.edges[candidate_index];
	if (path.empty()) {
	    loop_index = candidate.segment.from.loop_index;
	    surface = candidate.segment.tolerance.surface;
	}
	path.push_back(candidate_index);
	node = candidate.segment.to.node_id;
    }

    for (size_t path_index = 1; path_index < path.size(); ++path_index) {
	const size_t path_node =
	    arrangement.edges[path[path_index]].segment.from.node_id;
	size_t incoming_count = 0;
	size_t outgoing_count = 0;
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    if (edge.selected ||
		edge.segment.from.source_loop != source_loop ||
		edge.segment.from.loop_index != loop_index ||
		edge.selection_basis != BooleanArrangement::Edge::NOT_SELECTED ||
		edge.segment.location != CurveSegment::OUTSIDE)
	    {
		continue;
	    }
	    if (edge.segment.to.node_id == path_node) ++incoming_count;
	    if (edge.segment.from.node_id == path_node) ++outgoing_count;
	}
	if (incoming_count != 1 || outgoing_count != 1) {
	    return false;
	}
    }

    if ((source_loop != 1 && source_loop != 2) || surface == NULL ||
	!arrangement_path_spans_one_periodic_domain(arrangement, path, surface,
	    boolean_loop_closure_tolerance(tolerance.point)))
    {
	return false;
    }
    const BooleanArrangement::Edge &first = arrangement.edges[first_selected];
    const BooleanArrangement::Edge &last = arrangement.edges[last_selected];
    if (first.selection_basis != BooleanArrangement::Edge::COINCIDENT_GROUP ||
	last.selection_basis != BooleanArrangement::Edge::COINCIDENT_GROUP ||
	first.segment.from.source_loop == source_loop ||
	last.segment.from.source_loop != first.segment.from.source_loop ||
	first.paired_edge >= arrangement.edges.size() ||
	last.paired_edge >= arrangement.edges.size() ||
	arrangement.edges[first.paired_edge].segment.from.source_loop !=
	    source_loop ||
	arrangement.edges[last.paired_edge].segment.from.source_loop != source_loop)
    {
	return false;
    }

    BooleanArrangement trial(arrangement);
    for (size_t path_index = 0; path_index < path.size(); ++path_index) {
	BooleanArrangement::Edge &edge = trial.edges[path[path_index]];
	edge.selected = true;
	edge.selection_basis = BooleanArrangement::Edge::CERTIFIED_PERIODIC_BOUNDARY;
	edge.selection_reason = "certified periodic boundary path";
    }
    trial.BuildEndpointIncidences();
    if (!build_arrangement_transitions(trial, first_loop, second_loop,
	    tolerance, operation))
    {
	return false;
    }
    std::list<ON_SimpleArray<ON_Curve *> > trial_loops;
    if (!construct_loops_from_arrangement(trial, trial_loops) ||
	trial_loops.empty())
    {
	return false;
    }
    for (std::list<ON_SimpleArray<ON_Curve *> >::iterator loop =
	 trial_loops.begin(); loop != trial_loops.end(); ++loop)
    {
	for (int curve_index = 0; curve_index < loop->Count(); ++curve_index)
	    delete (*loop)[curve_index];
    }
    for (size_t edge_index = 0; edge_index < trial.edges.size(); ++edge_index)
	trial.edges[edge_index].consumed = false;
    arrangement = trial;
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("loop_boolean: selected certified %zu-edge periodic boundary path.\n",
	    path.size());
    }
    return true;
}


static bool
resolve_ambiguous_sampled_boundary_conflicts(BooleanArrangement &arrangement,
    const ON_SimpleArray<ON_Curve *> &first_loop,
    const ON_SimpleArray<ON_Curve *> &second_loop,
    const BooleanLoopTolerance &tolerance, op_type operation)
{
    std::map<size_t, int> node_balance;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected || edge.segment.from.HasSameTopologyNode(
		edge.segment.to))
	{
	    continue;
	}
	++node_balance[edge.segment.from.node_id];
	--node_balance[edge.segment.to.node_id];
    }

    size_t excess_outgoing_node = CurvePoint::UNSET_NODE;
    size_t excess_incoming_node = CurvePoint::UNSET_NODE;
    for (std::map<size_t, int>::const_iterator node = node_balance.begin();
	 node != node_balance.end(); ++node)
    {
	if (node->second == 0) {
	    continue;
	}
	if (node->second == 1 &&
	    excess_outgoing_node == CurvePoint::UNSET_NODE)
	{
	    excess_outgoing_node = node->first;
	} else if (node->second == -1 &&
	    excess_incoming_node == CurvePoint::UNSET_NODE)
	{
	    excess_incoming_node = node->first;
	} else {
	    return false;
	}
    }
    if (excess_outgoing_node == CurvePoint::UNSET_NODE ||
	excess_incoming_node == CurvePoint::UNSET_NODE)
    {
	return false;
    }

    {
	std::vector<size_t> connectors;
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    const bool connects_nodes =
		(edge.segment.from.node_id == excess_incoming_node &&
		 edge.segment.to.node_id == excess_outgoing_node) ||
		(edge.segment.from.node_id == excess_outgoing_node &&
		 edge.segment.to.node_id == excess_incoming_node);
	    if (connects_nodes)
		connectors.push_back(edge_index);
	}
	if (connectors.size() == 3) {
	    const size_t group = arrangement.edges[connectors[0]].coincident_group;
	    bool common_group = group != BooleanArrangement::UNSET_EDGE;
	    for (size_t edge_index : connectors) {
		const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
		common_group = common_group && !edge.selected &&
		    edge.segment.location == CurveSegment::BOUNDARY &&
		    edge.selection_basis == BooleanArrangement::Edge::NOT_SELECTED &&
		    edge.coincident_group == group;
	    }

	    size_t first_spur = BooleanArrangement::UNSET_EDGE;
	    size_t second_spur = BooleanArrangement::UNSET_EDGE;
	    size_t boundary = BooleanArrangement::UNSET_EDGE;
	    for (size_t first = 0; common_group && first < connectors.size(); ++first) {
		for (size_t second = first + 1; second < connectors.size(); ++second) {
		    const CurveSegment &a = arrangement.edges[connectors[first]].segment;
		    const CurveSegment &b = arrangement.edges[connectors[second]].segment;
		    if (a.from.source_loop != b.from.source_loop)
			continue;
		    if (first_spur != BooleanArrangement::UNSET_EDGE) {
			common_group = false;
			break;
		    }
		    first_spur = connectors[first];
		    second_spur = connectors[second];
		}
	    }
	    for (size_t edge_index : connectors) {
		if (edge_index != first_spur && edge_index != second_spur)
		    boundary = edge_index;
	    }

	    size_t predecessor = BooleanArrangement::UNSET_EDGE;
	    size_t successor = BooleanArrangement::UNSET_EDGE;
	    for (size_t edge_index = 0; common_group &&
		 edge_index < arrangement.edges.size(); ++edge_index)
	    {
		const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
		if (!edge.selected || edge.segment.from.HasSameTopologyNode(edge.segment.to))
		    continue;
		if (edge.segment.to.node_id == excess_incoming_node) {
		    if (predecessor != BooleanArrangement::UNSET_EDGE) common_group = false;
		    predecessor = edge_index;
		}
		if (edge.segment.from.node_id == excess_outgoing_node) {
		    if (successor != BooleanArrangement::UNSET_EDGE) common_group = false;
		    successor = edge_index;
		}
	    }

	    if (common_group && first_spur != BooleanArrangement::UNSET_EDGE &&
		boundary != BooleanArrangement::UNSET_EDGE &&
		predecessor != BooleanArrangement::UNSET_EDGE &&
		successor != BooleanArrangement::UNSET_EDGE)
	    {
		const CurveSegment &first = arrangement.edges[first_spur].segment;
		const CurveSegment &second = arrangement.edges[second_spur].segment;
		const CurveSegment &bridge = arrangement.edges[boundary].segment;
		const int source = arrangement.edges[predecessor].segment.from.source_loop;
		std::unique_ptr<ON_Curve> first_curve;
		std::unique_ptr<ON_Curve> second_curve;
		try {
		    first_curve.reset(first.Curve());
		    second_curve.reset(second.Curve());
		} catch (InvalidInterval &) {
		    first_curve.reset();
		    second_curve.reset();
		}
		const ON_3dPoint first_model = bridge.tolerance.surface ?
		    bridge.tolerance.surface->PointAt(bridge.from.pt.x,
			bridge.from.pt.y) : ON_3dPoint::UnsetPoint;
		const ON_3dPoint second_model = bridge.tolerance.surface ?
		    bridge.tolerance.surface->PointAt(bridge.to.pt.x,
			bridge.to.pt.y) : ON_3dPoint::UnsetPoint;
		if (source == arrangement.edges[successor].segment.from.source_loop &&
		    bridge.from.source_loop == source && bridge.to.source_loop == source &&
		    arrangement_segment_node_orientation(first, second) == -1 &&
		    first_curve && second_curve && first_model.IsValid() &&
		    second_model.IsValid() &&
		    first_model.DistanceTo(second_model) <=
			boolean_loop_closure_tolerance(tolerance.point) &&
		    arrangement_curves_have_certified_model_coincidence(first,
			*first_curve, second, *second_curve, -1))
		{
		    for (size_t edge_index = 0; edge_index < arrangement.edges.size(); ++edge_index) {
			BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
			if (edge.segment.from.node_id == excess_outgoing_node)
			    edge.segment.from.node_id = excess_incoming_node;
			if (edge.segment.to.node_id == excess_outgoing_node)
			    edge.segment.to.node_id = excess_incoming_node;
		    }
		    return true;
		}
	    }
	}
    }

    std::vector<size_t> duplicate_candidates;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (edge.selected &&
	    edge.segment.from.node_id == excess_outgoing_node &&
	    edge.segment.to.node_id == excess_incoming_node)
	{
	    duplicate_candidates.push_back(edge_index);
	}
    }
    if (duplicate_candidates.empty()) {
	if (select_certified_periodic_boundary_path(arrangement,
		excess_incoming_node, excess_outgoing_node, first_loop,
		second_loop, tolerance, operation))
	{
	    return true;
	}
	if (select_tolerance_scale_sampled_boundary_bridge(arrangement,
		excess_incoming_node, excess_outgoing_node))
	{
	    return true;
	}
	return prune_certified_affine_open_sliver(arrangement,
	    excess_incoming_node, excess_outgoing_node, operation);
    }
    if (duplicate_candidates.size() == 1 &&
	prune_tolerance_width_dangling_intersection_sliver(arrangement,
	    duplicate_candidates[0], excess_outgoing_node,
	    excess_incoming_node, operation))
    {
	return true;
    }
    if (duplicate_candidates.size() != 2) {
	return false;
    }

    BooleanArrangement::Edge &first =
	arrangement.edges[duplicate_candidates[0]];
    BooleanArrangement::Edge &second =
	arrangement.edges[duplicate_candidates[1]];
    if (first.segment.from.source_loop == second.segment.from.source_loop ||
	arrangement_segment_node_orientation(first.segment, second.segment) != 1 ||
	!arrangement_segments_have_only_shared_endpoint_intersections(
	    first.segment, second.segment))
    {
	return false;
    }

    BooleanArrangement::Edge *sampled = NULL;
    if (first.selection_basis ==
	    BooleanArrangement::Edge::CLASSIFIED_NONCOINCIDENT &&
	second.selection_basis == BooleanArrangement::Edge::SAMPLED_BOUNDARY)
    {
	sampled = &second;
    } else if (first.selection_basis ==
	    BooleanArrangement::Edge::SAMPLED_BOUNDARY &&
	second.selection_basis ==
	    BooleanArrangement::Edge::CLASSIFIED_NONCOINCIDENT)
    {
	sampled = &first;
    }
    if (sampled != NULL) {
	sampled->selected = false;
	sampled->selection_basis = BooleanArrangement::Edge::NOT_SELECTED;
	sampled->selection_reason =
	    "sampled boundary shadowed by classified result boundary";
	return true;
    }

    if (first.selection_basis != BooleanArrangement::Edge::SAMPLED_BOUNDARY ||
	second.selection_basis != BooleanArrangement::Edge::SAMPLED_BOUNDARY)
    {
	return false;
    }

    const int second_side = arrangement_segment_relative_side(first.segment,
	second.segment);
    if (second_side == 0) {
	return false;
    }

    BooleanArrangement::Edge *discarded = NULL;
    const char *selection_reason = NULL;
    if (operation == BOOLEAN_INTERSECT || operation == BOOLEAN_DIFF) {
	/* Result material is locally left of each selected edge.  AND-like
	 * operations retain the leftmost of two parallel boundaries. */
	discarded = second_side > 0 ? &first : &second;
	selection_reason =
	    "right sampled boundary shadowed by left result boundary";
    } else if (operation == BOOLEAN_UNION) {
	/* Union retains the rightmost boundary enclosing either left side. */
	discarded = second_side > 0 ? &second : &first;
	selection_reason =
	    "left sampled boundary shadowed by right result boundary";
    } else {
	return false;
    }

    discarded->selected = false;
    discarded->selection_basis = BooleanArrangement::Edge::NOT_SELECTED;
    discarded->selection_reason = selection_reason;
    return true;
}


static bool
balance_arrangement_edge_orientations(BooleanArrangement &arrangement,
    bool report_failure, int *failure_edge, int *failure_balance)
{
    if (failure_edge != NULL)
	*failure_edge = -1;
    if (failure_balance != NULL)
	*failure_balance = 0;
    std::map<size_t, int> node_balance;
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected || edge.segment.from.HasSameTopologyNode(
		edge.segment.to))
	{
	    continue;
	}
	++node_balance[edge.segment.from.node_id];
	--node_balance[edge.segment.to.node_id];
    }

    bool changed = true;
    while (changed) {
	changed = false;
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    if (!edge.selected || edge.segment.from.HasSameTopologyNode(
		    edge.segment.to))
	    {
		continue;
	    }

	    const size_t from_node = edge.segment.from.node_id;
	    const size_t to_node = edge.segment.to.node_id;
	    const int from_balance = node_balance[from_node];
	    const int to_balance = node_balance[to_node];
	    const int current_imbalance = std::abs(from_balance) +
		std::abs(to_balance);
	    const int reversed_imbalance = std::abs(from_balance - 2) +
		std::abs(to_balance + 2);
	    if (reversed_imbalance >= current_imbalance) {
		continue;
	    }

	    edge.segment.Reverse();
	    node_balance[from_node] -= 2;
	    node_balance[to_node] += 2;
	    changed = true;
	}
    }

    bool balanced = true;
    for (std::map<size_t, int>::const_iterator node = node_balance.begin();
	 node != node_balance.end(); ++node)
    {
	if (node->second == 0)
	    continue;
	balanced = false;
	if (!report_failure) {
	    continue;
	}
	if (failure_balance != NULL && *failure_balance == 0)
	    *failure_balance = node->second;
	size_t incoming = 0;
	size_t outgoing = 0;
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    if (!edge.selected)
		continue;
	    if (failure_edge != NULL && *failure_edge < 0 &&
		(edge.segment.from.node_id == node->first ||
		 edge.segment.to.node_id == node->first))
	    {
		*failure_edge = static_cast<int>(edge_index);
	    }
	    if (edge.segment.from.node_id == node->first)
		++outgoing;
	    if (edge.segment.to.node_id == node->first)
		++incoming;
	}
	bu_log("loop_boolean: arrangement node %zu remains unbalanced "
	    "after orientation repair: %zu outgoing, %zu incoming, balance %d.\n",
	    node->first, outgoing, incoming, node->second);
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	    if (edge.segment.from.node_id != node->first &&
		edge.segment.to.node_id != node->first)
	    {
		continue;
	    }
	    bu_log("loop_boolean: unbalanced node %zu incident edge %zu: %s, "
		"source loop %d curve %d, node %zu -> %zu, parameter %.17g "
		"-> %.17g, location %d, coincident group %zu, paired edge %zu, "
		"reason %s.\n", node->first, edge_index,
		edge.selected ? "selected" : "not selected",
		edge.segment.from.source_loop, edge.segment.from.loop_index,
		edge.segment.from.node_id, edge.segment.to.node_id,
		edge.segment.from.curve_t, edge.segment.to.curve_t,
		static_cast<int>(edge.segment.location), edge.coincident_group,
		edge.paired_edge,
		edge.selection_reason);
	}
    }
    return balanced;
}


static void
free_constructed_boolean_loop(ON_SimpleArray<ON_Curve *> &loop)
{
    for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	delete loop[curve_index];
	loop[curve_index] = NULL;
    }
}


static void
free_constructed_boolean_loops(
    std::list<ON_SimpleArray<ON_Curve *> > &loops)
{
    for (std::list<ON_SimpleArray<ON_Curve *> >::iterator loop =
	loops.begin(); loop != loops.end(); ++loop)
    {
	free_constructed_boolean_loop(*loop);
    }
    loops.clear();
}


static bool
arrangement_segment_follows(const CurveSegment &previous,
    const CurveSegment &candidate)
{
    if (previous.from.source_loop != candidate.from.source_loop ||
	previous.orig_loop.Count() <= 0)
    {
	return false;
    }

    int expected_curve = previous.to.loop_index;
    const ON_Interval domain = previous.orig_loop[expected_curve]->Domain();
    if (!previous.reversed && ON_NearZero(previous.to.curve_t - domain.Max(),
	previous.tolerance.curve_parameter))
    {
	expected_curve = (expected_curve + 1) % previous.orig_loop.Count();
    } else if (previous.reversed && ON_NearZero(
	previous.to.curve_t - domain.Min(), previous.tolerance.curve_parameter))
    {
	expected_curve = (expected_curve + previous.orig_loop.Count() - 1) %
	    previous.orig_loop.Count();
    }

    return candidate.from.loop_index == expected_curve;
}


static std::multiset<CurveSegment>::iterator
arrangement_successor(const CurveSegment &previous,
    std::multiset<CurveSegment> &segments)
{
    std::multiset<CurveSegment>::iterator candidate = segments.end();
    std::multiset<CurveSegment>::iterator continuation = segments.end();
    for (std::multiset<CurveSegment>::iterator segment = segments.begin();
	 segment != segments.end(); ++segment)
    {
	if (!segment->from.HasSameTopologyNode(previous.to)) {
	    continue;
	}
	if (candidate != segments.end()) {
	    candidate = segments.end();
	}
	else {
	    candidate = segment;
	}
	if (arrangement_segment_follows(previous, *segment)) {
	    if (continuation != segments.end()) {
		return segments.end();
	    }
	    continuation = segment;
	}
    }
    return continuation != segments.end() ? continuation : candidate;
}


static bool
construct_loops_from_segments(
    std::multiset<CurveSegment> &segments,
    std::list<ON_SimpleArray<ON_Curve *> > &out)
{
    while (!segments.empty()) {
	std::vector<std::multiset<CurveSegment>::iterator> loop_segs;
	std::vector<CurvePoint> visited_points;

	std::multiset<CurveSegment>::iterator curr_seg, prev_seg;
	curr_seg = segments.begin();

	loop_segs.push_back(curr_seg);
	visited_points.push_back(curr_seg->from);
	visited_points.push_back(curr_seg->to);

	bool closed_curve = curr_seg->from.HasSameTopologyNode(curr_seg->to);
	while (!closed_curve) {
	    // look for a segment that connects to the previous
	    prev_seg = curr_seg;
	    curr_seg = arrangement_successor(*prev_seg, segments);

	    if (curr_seg == segments.end()) {
		// no segment connects to the prev one
		break;
	    } else {
		// Extend our loop with the joining segment.
		// If we've visited its endpoint before, then the loop
		// is now closed.
		loop_segs.push_back(curr_seg);
		visited_points.push_back(curr_seg->to);
		closed_curve = false;
		for (std::vector<CurvePoint>::const_iterator point =
		     visited_points.begin(); point != visited_points.end() - 1;
		     ++point)
		{
		    if (point->HasSameTopologyNode(curr_seg->to)) {
			closed_curve = true;
			break;
		    }
		}
	    }
	}

	if (closed_curve) {
	    // find the segment the closing segment connected to (it
	    // may not be the first segment)
	    size_t i;
	    for (i = 0; i < loop_segs.size(); ++i) {
		if (loop_segs[i]->from.HasSameTopologyNode(
			loop_segs.back()->to))
		{
		    break;
		}
	    }
	    if (i == loop_segs.size()) {
		free_constructed_boolean_loops(out);
		return false;
	    }
	    // Form a curve from the closed chain of segments.
	    // Remove the used segments from the available set.
	    ON_SimpleArray<ON_Curve *> loop;
	    for (; i < loop_segs.size(); ++i) {
		try {
		    ON_Curve *curve = loop_segs[i]->Curve();
		    if (curve == NULL) {
			free_constructed_boolean_loop(loop);
			free_constructed_boolean_loops(out);
			return false;
		    }
		    loop.Append(curve);
		} catch (InvalidInterval &e) {
		    bu_log("%s", e.what());
		    free_constructed_boolean_loop(loop);
		    free_constructed_boolean_loops(out);
		    return false;
		}
		segments.erase(loop_segs[i]);
	    }
	    out.push_back(loop);
	} else {
	    free_constructed_boolean_loops(out);
	    return false;
	}
	loop_segs.clear();
	visited_points.clear();
    }
    return true;
}


std::multiset<CurvePoint>
get_loop_points(
    int source_loop,
    ON_SimpleArray<ON_Curve *> loop1,
    ON_SimpleArray<ON_Curve *> loop2,
    const BooleanLoopTolerance &tolerance,
    BooleanArrangementNodes &nodes)
{
    std::multiset<CurvePoint> out;

    if (loop1.Count() <= 0)
	return out;

    ON_Curve *loop1_seg = loop1[0];
    CurvePoint first_point(source_loop, 0, loop1_seg->Domain().m_t[0],
	loop1_seg, loop2, tolerance);
    first_point.node_id = nodes.Node(first_point);
    out.insert(first_point);

    for (int i = 0; i < loop1.Count(); ++i) {
	loop1_seg = loop1[i];
	CurvePoint point(source_loop, i, loop1_seg->Domain().m_t[1],
	    loop1_seg, loop2, tolerance);
	point.node_id = nodes.Node(point);
	const int next_curve_index = (i + 1) % loop1.Count();
	const double next_curve_start =
	    loop1[next_curve_index]->Domain().m_t[0];
	CurvePoint next_point(source_loop, next_curve_index, next_curve_start,
	    loop1[next_curve_index]->PointAt(next_curve_start), point.location,
	    tolerance);
	nodes.Join(point.node_id, nodes.Node(next_point));
	out.insert(point);
    }

    return out;
}


/* Curve intersection routines can omit an endpoint which lies on the interior
 * of the other loop's curve, particularly when the curves are coincident up
 * to that endpoint and then separate.  Point classification still correctly
 * identifies the endpoint as BOUNDARY, but without a corresponding point on
 * the other curve make_segments() applies one midpoint classification across
 * both the coincident and separated portions.  Recover only endpoint hits
 * certified both in parameter space and on the common model surface. */
static void
add_missing_boundary_endpoint_projections(
    const std::multiset<CurvePoint> &source_points,
    int target_source_loop,
    const ON_SimpleArray<ON_Curve *> &target_loop,
    const BooleanLoopTolerance &tolerance,
    BooleanArrangementNodes &nodes,
    std::multiset<CurvePoint> &target_points)
{
    const double candidate_tolerance = std::max(tolerance.point,
	INTERSECTION_TOL);
    if (!(candidate_tolerance > 0.0) ||
	!std::isfinite(candidate_tolerance))
    {
	return;
    }

    for (std::multiset<CurvePoint>::const_iterator source =
	 source_points.begin(); source != source_points.end(); ++source)
    {
	if (source->location != CurvePoint::BOUNDARY ||
	    source->node_id == CurvePoint::UNSET_NODE ||
	    !source->pt.IsValid())
	{
	    continue;
	}

	const ON_3dPoint parameter_point(source->pt.x, source->pt.y, 0.0);
	const ON_3dPoint model_point = tolerance.surface != NULL ?
	    tolerance.surface->PointAt(source->pt.x, source->pt.y) :
	    parameter_point;
	if (!model_point.IsValid()) {
	    continue;
	}

	for (int curve_index = 0; curve_index < target_loop.Count();
	     ++curve_index)
	{
	    const ON_Curve *curve = target_loop[curve_index];
	    double curve_parameter = ON_UNSET_VALUE;
	    if (curve == NULL) {
		continue;
	    }
	    const ON_BoundingBox curve_bounds = curve->BoundingBox();
	    if (!curve_bounds.IsValid() ||
		parameter_point.x < curve_bounds.m_min.x - candidate_tolerance ||
		parameter_point.x > curve_bounds.m_max.x + candidate_tolerance ||
		parameter_point.y < curve_bounds.m_min.y - candidate_tolerance ||
		parameter_point.y > curve_bounds.m_max.y + candidate_tolerance ||
		!point_3d_to_curve_parameter_with_tolerance(parameter_point,
		    curve, candidate_tolerance, curve_parameter, false))
	    {
		continue;
	    }

	    const ON_3dPoint projected_point = curve->PointAt(curve_parameter);
	    if (!projected_point.IsValid()) {
		continue;
	    }
	    const ON_3dPoint projected_model_point = tolerance.surface != NULL ?
		tolerance.surface->PointAt(projected_point.x,
		    projected_point.y) : projected_point;
	    if (!projected_model_point.IsValid() ||
		model_point.DistanceTo(projected_model_point) > INTERSECTION_TOL)
	    {
		continue;
	    }

	    CurvePoint projected(target_source_loop, curve_index,
		curve_parameter, ON_2dPoint(projected_point),
		CurvePoint::BOUNDARY, tolerance);
	    projected.node_id = nodes.Node(projected);
	    nodes.Join(source->node_id, projected.node_id);
	    add_point_to_set(target_points, projected);
	}
    }
}


// separate outerloops and innerloops
static LoopBooleanResult
make_result_from_loops(const std::list<ON_SimpleArray<ON_Curve *> > &loops)
{
    LoopBooleanResult out;

    std::list<ON_SimpleArray<ON_Curve *> >::const_iterator li;
    for (li = loops.begin(); li != loops.end(); ++li) {
	ON_Curve *loop_curve = get_loop_curve(*li);

	int dir = ON_ClosedCurveOrientation(*loop_curve, NULL);

	if (dir == LOOP_DIRECTION_CCW) {
	    out.outerloops.push_back(*li);
	} else if (dir == LOOP_DIRECTION_CW) {
	    out.innerloops.push_back(*li);
	}
	delete loop_curve;
    }

    return out;
}


// Get the result of a boolean combination of two loops. Based on the
// algorithm from this paper:
//
// Margalit, Avraham and Gary D. Knott. 1989. "An Algorithm for
// Computing the Union, Intersection or Difference of two Polygons."
// Computers & Graphics 13:167-183.
//
// gvu.gatech.edu/people/official/jarek/graphics/papers/04PolygonBooleansMargalit.pdf
static LoopBooleanResult
loop_boolean_impl(
    const ON_SimpleArray<ON_Curve *> &l1,
    const ON_SimpleArray<ON_Curve *> &l2,
    op_type op,
    const BooleanLoopTolerance &tolerance,
    bool recover_missing_boundary_endpoints)
{
    LoopBooleanResult out;

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("loop_boolean: operation %d, loop sizes %d/%d, point tolerance "
	    "%.17g, parameter tolerance %.17g.\n", static_cast<int>(op),
	    l1.Count(), l2.Count(), tolerance.point,
	    tolerance.curve_parameter);
    }

    if (op != BOOLEAN_INTERSECT &&
	op != BOOLEAN_DIFF &&
	op != BOOLEAN_UNION)
    {
	bu_log("loop_boolean: unsupported operation\n");
	return out;
    }

    if (l1.Count() <= 0 || l2.Count() <= 0) {
	bu_log("loop_boolean: one or more empty loops\n");
	return out;
    }

    // copy input loops
    ON_SimpleArray<ON_Curve *> loop1, loop2;
    for (int i = 0; i < l1.Count(); ++i) {
	loop1.Append(l1[i]->Duplicate());
    }
    for (int i = 0; i < l2.Count(); ++i) {
	loop2.Append(l2[i]->Duplicate());
    }

    // set curve directions based on operation
    int loop1_dir, loop2_dir;

    loop1_dir = loop2_dir = LOOP_DIRECTION_CCW;
    if (op == BOOLEAN_DIFF) {
	loop2_dir = LOOP_DIRECTION_CW;
    }

    if (!set_loop_direction(loop1, loop1_dir) ||
	!set_loop_direction(loop2, loop2_dir))
    {
	bu_log("loop_boolean: couldn't standardize curve directions\n");

	for (int i = 0; i < l1.Count(); ++i) {
	    delete loop1[i];
	}
	for (int i = 0; i < l2.Count(); ++i) {
	    delete loop2[i];
	}
	return out;
    }

    // get curve endpoints and intersection points for each loop
    std::multiset<CurvePoint> loop1_points, loop2_points;
    BooleanArrangementNodes nodes;
    std::vector<BooleanOverlapSpan> overlap_spans;

    loop1_points = get_loop_points(1, loop1, loop2, tolerance, nodes);
    loop2_points = get_loop_points(2, loop2, loop1, tolerance, nodes);

    if (recover_missing_boundary_endpoints) {
	/* Preserve the original endpoint sets while adding reciprocal split
	 * points.  Newly projected points must not recursively seed additional
	 * projections. */
	const std::multiset<CurvePoint> loop1_endpoints(loop1_points);
	const std::multiset<CurvePoint> loop2_endpoints(loop2_points);
	add_missing_boundary_endpoint_projections(loop1_endpoints, 2, loop2,
	    tolerance, nodes, loop2_points);
	add_missing_boundary_endpoint_projections(loop2_endpoints, 1, loop1,
	    tolerance, nodes, loop1_points);
    }

    for (int i = 0; i < loop1.Count(); ++i) {
	for (int j = 0; j < loop2.Count(); ++j) {
	    ON_SimpleArray<ON_X_EVENT> x_events;
	    intersect_boolean_curves(loop1[i], loop2[j], x_events,
		tolerance.point);

	for (int k = 0; k < x_events.Count(); ++k) {
		if (x_events[k].m_type == ON_X_EVENT::ccx_overlap) {
		    const bool distinct_first_parameters =
			std::fabs(x_events[k].m_a[1] - x_events[k].m_a[0]) >
			tolerance.curve_parameter;
		    const bool distinct_second_parameters =
			std::fabs(x_events[k].m_b[1] - x_events[k].m_b[0]) >
			tolerance.curve_parameter;
		    if (!distinct_first_parameters || !distinct_second_parameters ||
			!boolean_intersection_event_endpoint_has_shared_surface_point(
			    x_events[k], 0, tolerance) ||
			!boolean_intersection_event_endpoint_has_shared_surface_point(
			    x_events[k], 1, tolerance))
		    {
			continue;
		    }
		    overlap_spans.push_back(BooleanOverlapSpan(i, j,
			x_events[k]));
		    for (int endpoint = 0; endpoint < 2; ++endpoint) {
			CurvePoint first_point(1, i, x_events[k].m_a[endpoint],
			    x_events[k].m_A[endpoint], CurvePoint::BOUNDARY,
			    tolerance);
			CurvePoint second_point(2, j, x_events[k].m_b[endpoint],
			    x_events[k].m_B[endpoint], CurvePoint::BOUNDARY,
			    tolerance);
			first_point.node_id = nodes.Node(first_point);
			second_point.node_id = nodes.Node(second_point);
			nodes.Join(first_point.node_id, second_point.node_id);
			add_point_to_set(loop1_points, first_point);
			add_point_to_set(loop2_points, second_point);
		    }
		    continue;
		}

		if (!boolean_intersection_event_has_shared_surface_point(
			x_events[k], tolerance))
		{
		    continue;
		}

		CurvePoint first_point(1, i, x_events[k].m_a[0],
		    x_events[k].m_A[0], CurvePoint::BOUNDARY, tolerance);
		CurvePoint second_point(2, j, x_events[k].m_b[0],
		    x_events[k].m_B[0], CurvePoint::BOUNDARY, tolerance);
		first_point.node_id = nodes.Node(first_point);
		second_point.node_id = nodes.Node(second_point);
		nodes.Join(first_point.node_id, second_point.node_id);
		add_point_to_set(loop1_points, first_point);
		add_point_to_set(loop2_points, second_point);

	    }
	}
    }

	for (size_t span_index = 0; span_index < overlap_spans.size();
	 ++span_index)
    {
	overlap_spans[span_index].NormalizeEndpoints(loop1_points, loop2_points,
	    nodes);
    }

	    join_tolerance_scale_arrangement_nodes(loop1_points, loop1, loop2,
		overlap_spans, nodes);
	    join_tolerance_scale_arrangement_nodes(loop2_points, loop2, loop1,
		overlap_spans, nodes);
    canonicalize_arrangement_nodes(loop1_points, nodes);
    canonicalize_arrangement_nodes(loop2_points, nodes);

    // classify segments and determine which belong in the result
    std::multiset<CurveSegment> loop1_segments, loop2_segments;
    loop1_segments = make_segments(loop1_points, loop1, loop2, tolerance);
    loop2_segments = make_segments(loop2_points, loop2, loop1, tolerance);

    BooleanArrangement arrangement;
    arrangement.Add(loop1_segments);
    arrangement.Add(loop2_segments);
    arrangement.BuildCoincidentEdgeGroups(overlap_spans);

    select_arrangement_edges(arrangement, loop1, loop2, overlap_spans, op);
    resolve_ambiguous_sampled_boundary_conflicts(arrangement, loop1, loop2,
	tolerance, op);
	if (certify_single_edge_affine_intersection_sliver(arrangement, op)) {
	    free_constructed_boolean_loop(loop1);
	    free_constructed_boolean_loop(loop2);
	    return out;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
		 edge_index++)
	    {
		const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
		std::unique_ptr<ON_Curve> curve;
		try {
		    curve.reset(edge.segment.Curve());
		} catch (InvalidInterval &) {
		    curve.reset();
		}
		const ON_3dPoint midpoint = curve ?
		    curve->PointAt(curve->Domain().Mid()) : ON_3dPoint::UnsetPoint;
		ON_3dPoint model_midpoint = midpoint;
		if (midpoint.IsValid() && edge.segment.tolerance.surface != NULL)
		    model_midpoint = edge.segment.tolerance.surface->PointAt(
			midpoint.x, midpoint.y);
		bu_log("loop_boolean: edge %zu %s, source %d curve %d, node %zu "
		    "-> %zu, parameter %.17g -> %.17g, location %d, group %zu, "
		    "midpoint (%.17g, %.17g), model midpoint (%.17g, %.17g, "
		    "%.17g), reason %s.\n", edge_index,
		    edge.selected ? "selected" : "not selected",
		    edge.segment.from.source_loop, edge.segment.from.loop_index,
		    edge.segment.from.node_id, edge.segment.to.node_id,
		    edge.segment.from.curve_t, edge.segment.to.curve_t,
		    static_cast<int>(edge.segment.location), edge.coincident_group,
		    midpoint.x, midpoint.y, model_midpoint.x, model_midpoint.y,
		    model_midpoint.z, edge.selection_reason);
	    }
	}
	int unbalanced_edge = -1;
	int unbalanced_balance = 0;
	if (!balance_arrangement_edge_orientations(arrangement,
		recover_missing_boundary_endpoints, &unbalanced_edge,
		&unbalanced_balance))
	{
	    if (!recover_missing_boundary_endpoints) {
		free_constructed_boolean_loop(loop1);
		free_constructed_boolean_loop(loop2);
		return loop_boolean_impl(l1, l2, op, tolerance, true);
	    }
	    enum brep_boolean_failure_reason reason =
		BREP_BOOLEAN_FAILURE_REASON_ARRANGEMENT_UNBALANCED;
	    if (unbalanced_balance < 0) {
		reason = BREP_BOOLEAN_FAILURE_REASON_ARRANGEMENT_EXCESS_INCOMING;
	    } else if (unbalanced_balance > 0) {
		reason = BREP_BOOLEAN_FAILURE_REASON_ARRANGEMENT_EXCESS_OUTGOING;
	    }
	    record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_TRIM_ARRANGEMENT,
		reason, -1, -1, unbalanced_edge, -1, tolerance.point);
	    throw GeometryGenerationError(
		"loop_boolean: selected arrangement edges are not node-balanced.\n");
    }
    arrangement.BuildEndpointIncidences();
    bool transitions_built = false;
    BooleanArrangement closed_path_arrangement(arrangement);
    if (prune_arrangement_edges_without_closed_material_paths(
	    closed_path_arrangement, loop1, loop2, tolerance, op))
    {
	closed_path_arrangement.BuildEndpointIncidences();
	if (build_arrangement_transitions(closed_path_arrangement, loop1, loop2,
		tolerance, op))
	{
	    arrangement = closed_path_arrangement;
	    transitions_built = true;
	}
    }
    if (!transitions_built && !build_arrangement_transitions(arrangement,
	    loop1, loop2, tolerance, op))
    {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_TRIM_ARRANGEMENT,
	    BREP_BOOLEAN_FAILURE_REASON_ARRANGEMENT_TRANSITION, -1, -1,
	    -1, -1, tolerance.point);
	throw GeometryGenerationError(
	    "loop_boolean: unable to build result transitions.\n");
    }
    // build result
    std::list<ON_SimpleArray<ON_Curve *> > new_loops;

    const bool have_closed_loops = construct_loops_from_arrangement(
	arrangement, new_loops);
    for (int i = 0; i < l1.Count(); ++i) {
	delete loop1[i];
    }
    for (int i = 0; i < l2.Count(); ++i) {
	delete loop2[i];
    }
    if (!have_closed_loops) {
	throw GeometryGenerationError(
	    "loop_boolean: unable to construct closed result loops.\n");
    }

    std::list<ON_SimpleArray<ON_Curve *> >::iterator li;
    for (li = new_loops.begin(); li != new_loops.end(); ++li) {
	close_small_gaps(*li,
	    boolean_loop_closure_tolerance(tolerance.point));
    }

    out = make_result_from_loops(new_loops);

    return out;
}


LoopBooleanResult
loop_boolean(
    const ON_SimpleArray<ON_Curve *> &l1,
    const ON_SimpleArray<ON_Curve *> &l2,
    op_type op,
    const BooleanLoopTolerance &tolerance)
{
    return loop_boolean_impl(l1, l2, op, tolerance, false);
}


std::list<ON_SimpleArray<ON_Curve *> >
innerloops_inside_outerloop(
    const ON_Surface *surface,
    const ON_SimpleArray<ON_Curve *> &outerloop_curve,
    const std::vector<ON_SimpleArray<ON_Curve *> > &innerloop_curves)
{
    std::list<ON_SimpleArray<ON_Curve *> > out;

    for (size_t i = 0; i < innerloop_curves.size(); ++i) {
	LoopBooleanResult new_loops;
	new_loops = loop_boolean(outerloop_curve, innerloop_curves[i],
			 BOOLEAN_INTERSECT, boolean_loop_tolerance_for_surface(
			     surface, outerloop_curve, innerloop_curves[i]));

	// grab outerloops
	for (size_t j = 0; j < new_loops.outerloops.size(); ++j) {
	    set_loop_direction(new_loops.outerloops[j], LOOP_DIRECTION_CW);
	    out.push_back(new_loops.outerloops[j]);
	}
	new_loops.ClearInnerloops();
    }
    return out;
}


TrimmedFace *
make_face_from_loops(
    const TrimmedFace *orig_face,
    const ON_SimpleArray<ON_Curve *> &outerloop,
    const std::vector<ON_SimpleArray<ON_Curve *> > &innerloops)
{
    TrimmedFace *face = new TrimmedFace();

    face->m_face = orig_face->m_face;
    face->m_outerloop.Append(outerloop.Count(), outerloop.Array());

    // TODO: the innerloops found here can't be inside any other
    // outerloop, and should be removed from the innerloop set in the
    // interest of efficiency
    std::list<ON_SimpleArray<ON_Curve *> > new_innerloops;
    new_innerloops = innerloops_inside_outerloop(orig_face->m_face ?
	orig_face->m_face->SurfaceOf() : NULL, outerloop, innerloops);

    std::list<ON_SimpleArray<ON_Curve *> >::iterator i;
    for (i = new_innerloops.begin(); i != new_innerloops.end(); ++i) {
	face->m_innerloop.push_back(*i);
    }
    return face;
}


static LoopBooleanResult
combine_loops(
    const TrimmedFace *orig_face,
    const LoopBooleanResult &new_loops)
{
    // Intersections always produce a single outerloop.
    //
    // Subtractions may produce multiple outerloops, or a single
    // outerloop that optionally includes a single innerloop.
    //
    // So, the possible results are:
    // 1) Single outerloop.
    // 2) Multiple outerloops.
    // 3) Single outerloop with single innerloop.

    // First we'll combine the old and new innerloops.
    std::vector<ON_SimpleArray<ON_Curve *> > merged_innerloops;
    if (new_loops.innerloops.size() == 1) {
	// If the result has an innerloop, it may overlap any of the
	// original innerloops. We'll union all overlapping loops with
	// the new innerloop.
	ON_SimpleArray<ON_Curve *> candidate_innerloop(new_loops.innerloops[0]);

	for (size_t i = 0; i < orig_face->m_innerloop.size(); ++i) {
	    LoopBooleanResult merged = loop_boolean(candidate_innerloop,
					    orig_face->m_innerloop[i], BOOLEAN_UNION,
		boolean_loop_tolerance_for_surface(orig_face->m_face ?
	    orig_face->m_face->SurfaceOf() : NULL, candidate_innerloop,
	    orig_face->m_innerloop[i]));

	    if (merged.outerloops.size() == 1) {
		candidate_innerloop = merged.outerloops[0];
	    } else {
		merged_innerloops.push_back(orig_face->m_innerloop[i]);
		merged.ClearOuterloops();
	    }
	}
	merged_innerloops.push_back(candidate_innerloop);
    } else if (!orig_face->m_innerloop.empty()) {
	for (size_t i = 0; i < orig_face->m_innerloop.size(); ++i) {
	    merged_innerloops.push_back(orig_face->m_innerloop[i]);
	}
    }

    // Next we'll attempt to subtract all merged innerloops from each
    // new outerloop to get the final set of loops. For each
    // subtraction, there are four possibilities:
    // 1) The innerloop is outside the outerloop, and the result is
    //    the original outerloop.
    // 2) The innerloop completely encloses the outerloop, and the
    //    result is empty.
    // 3) The innerloop is completely contained by the outerloop, and
    //    the result is the input outerloop and innerloop.
    // 4) The innerloop overlaps the outerloop, and the result is one
    //    or more outerloops.
    LoopBooleanResult out;
    for (size_t i = 0; i < new_loops.outerloops.size(); ++i) {

	std::list<ON_SimpleArray<ON_Curve *> >::iterator part, next_part;
	std::list<ON_SimpleArray<ON_Curve *> > outerloop_parts;

	// start with the original outerloop
	outerloop_parts.push_back(new_loops.outerloops[i]);

	// attempt to subtract all innerloops from it, and from
	// whatever subparts of it are created along the way
	for (size_t j = 0; j < merged_innerloops.size(); ++j) {

	    part = outerloop_parts.begin();
	    for (; part != outerloop_parts.end(); part = next_part) {
		LoopBooleanResult diffed = loop_boolean(*part,
						merged_innerloops[j], BOOLEAN_DIFF,
		    boolean_loop_tolerance_for_surface(orig_face->m_face ?
		orig_face->m_face->SurfaceOf() : NULL, *part,
		merged_innerloops[j]));

		next_part = part;
		++next_part;

		if (diffed.innerloops.size() == 1) {
		    // The outerloop part contains the innerloop, so
		    // the innerloop belongs in the final set.
		    //
		    // Note that any innerloop added here will remains
		    // completely inside an outerloop part even if the
		    // part list changes. In order for a subsequent
		    // subtraction to put any part of it outside an
		    // outerloop, that later innerloop would have to
		    // overlap this one, in which case, the innerloops
		    // would have been unioned together in the
		    // previous merging step.
		    out.innerloops.push_back(diffed.innerloops[0]);
		} else {
		    // outerloop part has been erased, modified, or
		    // split, so we need to remove it
		    for (int k = 0; k < part->Count(); ++k) {
			delete (*part)[k];
		    }
		    outerloop_parts.erase(part);

		    // add any new parts for subsequent subtractions
		    for (size_t k = 0; k < diffed.outerloops.size(); ++k) {
			outerloop_parts.push_front(diffed.outerloops[k]);
		    }
		}
	    }
	}

	// whatever parts of the outerloop that remain after
	// subtracting all innerloops belong in the final set
	part = outerloop_parts.begin();
	for (; part != outerloop_parts.end(); ++part) {
	    out.outerloops.push_back(*part);
	}
    }
    return out;
    // Only thing left to do is make a face from each outerloop. If
    // one of the innerloops is inside the outerloop, make it part of
    // the face and remove it for consideration for other faces.
}


static void
append_faces_from_loops(
    ON_SimpleArray<TrimmedFace *> &out,
    const TrimmedFace *orig_face,
    const LoopBooleanResult &new_loops)
{
    std::vector<TrimmedFace *> o;
    LoopBooleanResult combined_loops = combine_loops(orig_face, new_loops);

    // make a face from each outerloop, using appropriate innerloops
    for (size_t i = 0; i < combined_loops.outerloops.size(); ++i) {
	o.push_back(make_face_from_loops(orig_face,
					combined_loops.outerloops[i],
					combined_loops.innerloops));
    }
    for (size_t i = 0; i < o.size(); i++) {
	out.Append(o[i]);
    }
}


static bool
linked_curve_interval_locations(
    LinkedCurve &linked_curve,
    double first_parameter,
    double second_parameter,
    const ON_SimpleArray<ON_Curve *> &outerloop,
    const BooleanLoopTolerance &tolerance,
    bool &found_inside,
    bool &found_outside)
{
    found_inside = false;
    found_outside = false;
    ON_Interval interval(first_parameter, second_parameter);
    interval.MakeIncreasing();
    if (!interval.IsIncreasing() ||
	interval.Length() <= tolerance.curve_parameter)
    {
	return false;
    }

    static const unsigned int maximum_divisions = 32;
    bool sampled = false;
    for (unsigned int divisions = 2; divisions <= maximum_divisions;
	 divisions *= 2)
    {
	for (unsigned int numerator = 1; numerator < divisions;
	     numerator += 2)
	{
	    const double parameter = interval.ParameterAt(
		static_cast<double>(numerator) / divisions);
	    const ON_3dPoint point = linked_curve.PointAt(parameter);
	    if (!point.IsValid()) {
		continue;
	    }
	    sampled = true;
	    const CurvePoint::Location location = CurvePoint::PointLoopLocation(
		ON_2dPoint(point), outerloop, tolerance);
	    found_inside = found_inside || location == CurvePoint::INSIDE;
	    found_outside = found_outside || location == CurvePoint::OUTSIDE;
	}
    }

    return sampled;
}


static CurvePoint::Location
linked_curve_interval_face_location(
    LinkedCurve &linked_curve,
    double first_parameter,
    double second_parameter,
    const ON_SimpleArray<ON_Curve *> &outerloop,
    const BooleanLoopTolerance &tolerance)
{
    bool found_inside = false;
    bool found_outside = false;
    if (!linked_curve_interval_locations(linked_curve, first_parameter,
	    second_parameter, outerloop, tolerance, found_inside,
	    found_outside) || found_inside == found_outside)
    {
	return CurvePoint::BOUNDARY;
    }

    if (found_inside) {
	return CurvePoint::INSIDE;
    }
    if (found_outside) {
	return CurvePoint::OUTSIDE;
    }
    return CurvePoint::BOUNDARY;
}


static bool
linked_curve_interval_is_face_boundary(
    LinkedCurve &linked_curve,
    double first_parameter,
    double second_parameter,
    const ON_SimpleArray<ON_Curve *> &outerloop,
    const BooleanLoopTolerance &tolerance)
{
    ON_Interval interval(first_parameter, second_parameter);
    interval.MakeIncreasing();
    if (!interval.IsIncreasing() ||
	interval.Length() <= tolerance.curve_parameter)
    {
	return false;
    }

    std::vector<std::unique_ptr<ON_Curve> > lifted_boundaries;
    if (tolerance.surface != NULL) {
	for (int curve_index = 0; curve_index < outerloop.Count();
	     ++curve_index)
	{
	    if (outerloop[curve_index] == NULL) {
		continue;
	    }
	    std::unique_ptr<ON_Curve> lifted(pushup_boolean_curve(
		tolerance.surface, *outerloop[curve_index]));
	    if (lifted) {
		lifted_boundaries.push_back(std::move(lifted));
	    }
	}
	if (lifted_boundaries.empty()) {
	    return false;
	}
    }

    static const unsigned int maximum_divisions = 32;
    bool sampled = false;
    for (unsigned int divisions = 2; divisions <= maximum_divisions;
	 divisions *= 2)
    {
	for (unsigned int numerator = 1; numerator < divisions;
	     numerator += 2)
	{
	    const double parameter = interval.ParameterAt(
		static_cast<double>(numerator) / divisions);
	    const ON_3dPoint parameter_point = linked_curve.PointAt(parameter);
	    if (!parameter_point.IsValid()) {
		return false;
	    }
	    sampled = true;
	    if (tolerance.surface == NULL) {
		if (!is_point_on_normalized_loop(ON_2dPoint(parameter_point),
			outerloop, tolerance.point))
		{
		    return false;
		}
		continue;
	    }

	    const ON_3dPoint lifted_point = tolerance.surface->PointAt(
		parameter_point.x, parameter_point.y);
	    if (!lifted_point.IsValid()) {
		return false;
	    }
	    bool matched = false;
	    for (size_t curve_index = 0;
		 curve_index < lifted_boundaries.size() && !matched;
		 ++curve_index)
	    {
		double boundary_parameter = 0.0;
		matched = point_3d_to_curve_parameter_with_tolerance(
		    lifted_point, lifted_boundaries[curve_index].get(),
		    INTERSECTION_TOL, boundary_parameter);
	    }
	    if (!matched) {
		return false;
	    }
	}
    }
    return sampled;
}


struct BooleanSourceBoundaryAttachment {
    int m_boundary_curve_index;
    int m_source_trim_index;
    int m_source_edge_index;
    double m_curve_parameter;
    double m_boundary_parameter;
    ON_3dPoint m_boundary_point;
    bool m_needs_connector;

    BooleanSourceBoundaryAttachment()
	: m_boundary_curve_index(-1), m_source_trim_index(-1),
	  m_source_edge_index(-1), m_curve_parameter(ON_UNSET_VALUE),
	  m_boundary_parameter(ON_UNSET_VALUE),
	  m_boundary_point(ON_3dPoint::UnsetPoint),
	  m_needs_connector(false)
    {}
};


static bool
boolean_closest_curve_parameter(
    const ON_Curve &curve,
    const ON_3dPoint &point,
    double &curve_parameter,
    ON_3dPoint &curve_point)
{
    curve_parameter = ON_UNSET_VALUE;
    curve_point = ON_3dPoint::UnsetPoint;
    if (!point.IsValid()) {
	return false;
    }

    ON_NurbsCurve nurbs;
    const int nurbs_form = curve.GetNurbForm(nurbs);
    if (nurbs_form <= 0 || !nurbs.IsValid() ||
	!nurbs.Domain().IsIncreasing())
    {
	return false;
    }

    double nurbs_parameter = nurbs.Domain().Min();
    if (!ON_NurbsCurve_GetClosestPoint(&nurbs_parameter, &nurbs, point)) {
	return false;
    }

    curve_parameter = nurbs_parameter;
    if (nurbs_form != 1 &&
	!curve.GetCurveParameterFromNurbFormParameter(nurbs_parameter,
	    &curve_parameter))
    {
	return false;
    }

    if (!std::isfinite(curve_parameter) ||
	!curve.Domain().Includes(curve_parameter))
    {
	return false;
    }
    curve_point = curve.PointAt(curve_parameter);
    return curve_point.IsValid();
}


static const ON_BrepTrim *
boolean_source_trim_for_outer_boundary(
    const TrimmedFace *face,
    int boundary_curve_index,
    int &trim_index,
    const ON_BrepEdge *&edge)
{
    trim_index = -1;
    edge = NULL;
    if (face == NULL || face->m_face == NULL ||
	boundary_curve_index < 0 ||
	boundary_curve_index >= face->m_outerloop.Count())
    {
	return NULL;
    }

    const ON_BrepFace &source_face = *face->m_face;
    const ON_Brep *source_brep = source_face.Brep();
    if (source_brep == NULL || source_face.m_face_index < 0 ||
	source_face.m_face_index >= source_brep->m_F.Count() ||
	&source_brep->m_F[source_face.m_face_index] != face->m_face ||
	source_face.m_li.Count() < 1)
    {
	return NULL;
    }

    const int outer_loop_index = source_face.m_li[0];
    if (outer_loop_index < 0 || outer_loop_index >= source_brep->m_L.Count()) {
	return NULL;
    }
    const ON_BrepLoop &outer_loop = source_brep->m_L[outer_loop_index];
    if (outer_loop.m_type != ON_BrepLoop::outer ||
	outer_loop.m_ti.Count() != face->m_outerloop.Count())
    {
	return NULL;
    }

    trim_index = outer_loop.m_ti[boundary_curve_index];
    if (trim_index < 0 || trim_index >= source_brep->m_T.Count()) {
	return NULL;
    }
    const ON_BrepTrim &trim = source_brep->m_T[trim_index];
    const ON_Curve *source_parameter_curve = trim.TrimCurveOf();
    const ON_Curve *boundary_curve = face->m_outerloop[boundary_curve_index];
    bool reversed = false;
    const bool curves_coincident = source_parameter_curve != NULL &&
	boundary_curve != NULL && brep_curves_coincident(*boundary_curve,
	    *source_parameter_curve, 0.0, &reversed);

    if (DEBUG_BREP_BOOLEAN && (source_face.m_face_index == 13 ||
	    source_face.m_face_index == 20))
    {
	bu_log("Boolean source boundary %d face %d trim %d trim-face %d type "
	    "%d edge %d/%d, curves %d/%d, coincident %d reversed %d.\n",
	    boundary_curve_index, source_face.m_face_index, trim_index,
	    trim.FaceIndexOf(), static_cast<int>(trim.m_type), trim.m_ei,
	    source_brep->m_E.Count(),
	    source_parameter_curve != NULL, boundary_curve != NULL,
	    curves_coincident, reversed);
    }
    if (trim.FaceIndexOf() != source_face.m_face_index ||
	trim.m_type == ON_BrepTrim::singular || trim.m_ei < 0 ||
	trim.m_ei >= source_brep->m_E.Count() ||
	source_parameter_curve == NULL || boundary_curve == NULL ||
	!curves_coincident || reversed)
    {
	return NULL;
    }

    edge = &source_brep->m_E[trim.m_ei];
    if (edge->EdgeCurveOf() == NULL || !edge->Domain().IsIncreasing() ||
	(!edge->IsClosed() && edge->PointAtStart().DistanceTo(
	    edge->PointAtEnd()) <= ON_ZERO_TOLERANCE))
    {
	edge = NULL;
	return NULL;
    }
    return &trim;
}


static bool
boolean_parameter_curve_lies_in_source_edge_tube(
    const ON_Surface *surface,
    const ON_Curve &parameter_curve,
    const ON_BrepEdge &source_edge,
    double model_tolerance)
{
    if (surface == NULL || parameter_curve.Dimension() < 2 ||
	!(model_tolerance > 0.0) || !std::isfinite(model_tolerance))
    {
	return false;
    }

    std::unique_ptr<ON_Curve> lifted_curve(
	pushup_boolean_curve(surface, parameter_curve));
    if (!lifted_curve || !lifted_curve->IsValid()) {
	return false;
    }

    double source_parameters[2] = {ON_UNSET_VALUE, ON_UNSET_VALUE};
    ON_3dPoint source_points[2] = {
	ON_3dPoint::UnsetPoint, ON_3dPoint::UnsetPoint
    };
    const ON_3dPoint lifted_endpoints[2] = {
	lifted_curve->PointAtStart(), lifted_curve->PointAtEnd()
    };
    for (int endpoint_index = 0; endpoint_index < 2; ++endpoint_index) {
	if (!boolean_closest_curve_parameter(source_edge,
		lifted_endpoints[endpoint_index], source_parameters[endpoint_index],
		source_points[endpoint_index]) ||
	    source_points[endpoint_index].DistanceTo(
		lifted_endpoints[endpoint_index]) > model_tolerance)
	{
	    return false;
	}
    }

    ON_Interval source_domain = source_edge.Domain();
    source_domain.MakeIncreasing();
    const double normalized_first = source_domain.NormalizedParameterAt(
	source_parameters[0]);
    const double normalized_second = source_domain.NormalizedParameterAt(
	source_parameters[1]);
    static const double parameter_roundoff_multiplier = 128.0;
    if (fabs(normalized_second - normalized_first) <=
	    parameter_roundoff_multiplier * ON_EPSILON)
    {
	return brep_curve_locus_within_ball(*lifted_curve,
	    source_edge.PointAt(0.5 * (source_parameters[0] +
		    source_parameters[1])), model_tolerance);
    }

    std::unique_ptr<ON_Curve> source_piece;
    try {
	source_piece.reset(sub_curve(&source_edge,
	    std::min(source_parameters[0], source_parameters[1]),
	    std::max(source_parameters[0], source_parameters[1])));
    } catch (InvalidInterval &) {
	return false;
    }
    return source_piece && source_piece->IsValid() &&
	brep_curves_coincident(*lifted_curve, *source_piece, model_tolerance);
}


static std::unique_ptr<ON_Curve>
boolean_linked_curve_subcurve(
    LinkedCurve &linked_curve,
    double first_parameter,
    double second_parameter)
{
    ON_SimpleArray<ON_Curve *> pieces;
    if (!linked_curve.SubCurves(first_parameter, second_parameter, pieces)) {
	return std::unique_ptr<ON_Curve>();
    }
    if (pieces.Count() == 1) {
	return std::unique_ptr<ON_Curve>(pieces[0]);
    }

    std::unique_ptr<ON_PolyCurve> joined(new ON_PolyCurve());
    for (int piece_index = 0; piece_index < pieces.Count(); ++piece_index) {
	append_to_polycurve(pieces[piece_index], *joined);
    }
    return std::unique_ptr<ON_Curve>(joined.release());
}


static bool
boolean_linked_curve_interval_lies_in_source_edge_tube(
    LinkedCurve &linked_curve,
    double first_parameter,
    double second_parameter,
    const ON_Surface *surface,
    const ON_BrepEdge &source_edge,
    double model_tolerance)
{
    ON_SimpleArray<ON_Curve *> pieces;
    if (!linked_curve.SubCurves(first_parameter, second_parameter, pieces) ||
	pieces.Count() < 1)
    {
	return false;
    }

    bool certified = true;
    for (int piece_index = 0; piece_index < pieces.Count(); ++piece_index) {
	std::unique_ptr<ON_Curve> piece(pieces[piece_index]);
	if (!piece || !boolean_parameter_curve_lies_in_source_edge_tube(surface,
		*piece, source_edge, model_tolerance))
	{
	    certified = false;
	}
    }
    return certified;
}


static bool
boolean_boundary_attachment_is_interior(
    const ON_Curve &boundary_curve,
    double boundary_parameter,
    const ON_BrepEdge &source_edge,
    const ON_3dPoint &model_point,
    double parameter_tolerance,
    double model_tolerance)
{
    ON_Interval boundary_domain = boundary_curve.Domain();
    boundary_domain.MakeIncreasing();
    if (!boundary_domain.IsIncreasing() ||
	!boundary_domain.Includes(boundary_parameter) ||
	!model_point.IsValid())
    {
	return false;
    }

    const ON_3dPoint boundary_point = boundary_curve.PointAt(
	boundary_parameter);
    if (!boundary_point.IsValid() ||
	boundary_point.DistanceTo(boundary_curve.PointAtStart()) <=
	    parameter_tolerance ||
	boundary_point.DistanceTo(boundary_curve.PointAtEnd()) <=
	    parameter_tolerance)
    {
	return false;
    }

    double edge_parameter = ON_UNSET_VALUE;
    ON_3dPoint edge_point = ON_3dPoint::UnsetPoint;
    if (!boolean_closest_curve_parameter(source_edge, model_point,
	    edge_parameter, edge_point) ||
	edge_point.DistanceTo(model_point) > model_tolerance)
    {
	return false;
    }

    ON_Interval edge_domain = source_edge.Domain();
    edge_domain.MakeIncreasing();
    const double normalized = edge_domain.NormalizedParameterAt(edge_parameter);
    static const double endpoint_parameter_margin = 128.0 * ON_EPSILON;
    return std::isfinite(normalized) &&
	normalized > endpoint_parameter_margin &&
	normalized < 1.0 - endpoint_parameter_margin;
}


static bool
boolean_connector_stays_in_face(
    const TrimmedFace *face,
    const ON_Curve &connector,
    int target_boundary_index,
    const ON_3dPoint &target,
    double parameter_tolerance)
{
    if (face == NULL || !target.IsValid() || target_boundary_index < 0 ||
	target_boundary_index >= face->m_outerloop.Count())
    {
	return false;
    }

    bool found_target = false;
    for (int boundary_index = 0;
	 boundary_index < face->m_outerloop.Count(); ++boundary_index)
    {
	ON_SimpleArray<ON_X_EVENT> events;
	intersect_boolean_curves(&connector, face->m_outerloop[boundary_index],
	    events, parameter_tolerance);
	for (int event_index = 0; event_index < events.Count(); ++event_index) {
	    const ON_X_EVENT &event = events[event_index];
	    if (event.m_type != ON_X_EVENT::ccx_point ||
		event.m_A[0].DistanceTo(target) > parameter_tolerance ||
		boundary_index != target_boundary_index)
	    {
		return false;
	    }
	    found_target = true;
	}
    }
    for (size_t loop_index = 0; loop_index < face->m_innerloop.size();
	 ++loop_index)
    {
	for (int boundary_index = 0;
	     boundary_index < face->m_innerloop[loop_index].Count();
	     ++boundary_index)
	{
	    ON_SimpleArray<ON_X_EVENT> events;
	    intersect_boolean_curves(&connector,
		face->m_innerloop[loop_index][boundary_index], events,
		parameter_tolerance);
	    if (events.Count() > 0) {
		return false;
	    }
	}
    }
    if (!found_target) {
	return false;
    }

    static const int connector_samples = 32;
    const ON_Interval connector_domain = connector.Domain();
    for (int sample = 1; sample < connector_samples; ++sample) {
	const ON_3dPoint point = connector.PointAt(connector_domain.ParameterAt(
	    static_cast<double>(sample) / connector_samples));
	try {
	    if (!point.IsValid() || !is_point_inside_trimmed_face(
		    ON_2dPoint(point), face))
	    {
		return false;
	    }
	} catch (InvalidGeometry &) {
	    return false;
	}
    }
    return true;
}


static bool
boolean_same_boundary_attachment(
    const BooleanSourceBoundaryAttachment &first,
    const BooleanSourceBoundaryAttachment &second,
    double curve_parameter_tolerance,
    double point_tolerance)
{
    return first.m_boundary_curve_index == second.m_boundary_curve_index &&
	first.m_source_trim_index == second.m_source_trim_index &&
	first.m_source_edge_index == second.m_source_edge_index &&
	first.m_needs_connector == second.m_needs_connector &&
	fabs(first.m_curve_parameter - second.m_curve_parameter) <=
	    curve_parameter_tolerance &&
	first.m_boundary_point.DistanceTo(second.m_boundary_point) <=
	    point_tolerance;
}


static void
boolean_append_unique_boundary_attachment(
    std::vector<BooleanSourceBoundaryAttachment> &attachments,
    const BooleanSourceBoundaryAttachment &candidate,
    double curve_parameter_tolerance,
    double point_tolerance)
{
    for (size_t attachment_index = 0;
	 attachment_index < attachments.size(); ++attachment_index)
    {
	if (boolean_same_boundary_attachment(attachments[attachment_index],
		candidate, curve_parameter_tolerance, point_tolerance))
	{
	    return;
	}
    }
    attachments.push_back(candidate);
}


static bool
boolean_find_unique_source_boundary_attachment(
    const TrimmedFace *face,
    LinkedCurve &linked_curve,
    bool at_start,
    const BooleanLoopTolerance &split_tolerance,
    double model_tolerance,
    BooleanSourceBoundaryAttachment &attachment)
{
    const ON_Surface *surface = face && face->m_face ?
	face->m_face->SurfaceOf() : NULL;
    const ON_Curve *linked_geometry = linked_curve.Curve();
    ON_Interval linked_domain = linked_geometry ? linked_geometry->Domain() :
	ON_Interval::EmptyInterval;
    linked_domain.MakeIncreasing();
    if (surface == NULL || linked_geometry == NULL ||
	!linked_domain.IsIncreasing())
    {
	return false;
    }

    const double endpoint_parameter = at_start ? linked_domain.Min() :
	linked_domain.Max();
    const ON_3dPoint endpoint = linked_geometry->PointAt(endpoint_parameter);
    const ON_3dPoint model_endpoint = endpoint.IsValid() ?
	surface->PointAt(endpoint.x, endpoint.y) : ON_3dPoint::UnsetPoint;
    if (!endpoint.IsValid() || !model_endpoint.IsValid()) {
	return false;
    }

    std::vector<BooleanSourceBoundaryAttachment> intersections;
    std::vector<BooleanSourceBoundaryAttachment> overlap_attachments;
    bool has_overlap = false;
    for (int boundary_index = 0;
	 boundary_index < face->m_outerloop.Count(); ++boundary_index)
    {
	int trim_index = -1;
	const ON_BrepEdge *source_edge = NULL;
	const ON_BrepTrim *source_trim =
	    boolean_source_trim_for_outer_boundary(face, boundary_index,
		trim_index, source_edge);
	const ON_Curve *boundary_curve = face->m_outerloop[boundary_index];
	if (source_trim == NULL || source_edge == NULL ||
	    boundary_curve == NULL)
	{
	    if (DEBUG_BREP_BOOLEAN && (face->m_face->m_face_index == 13 ||
		    face->m_face->m_face_index == 20))
	    {
		bu_log("Boolean source-boundary attachment face %d endpoint %d "
		    "boundary %d has no source trim/edge (%d/%d/%d).\n",
		    face->m_face->m_face_index, at_start ? 0 : 1,
		    boundary_index, source_trim != NULL, source_edge != NULL,
		    boundary_curve != NULL);
	    }
	    continue;
	}

	ON_SimpleArray<ON_X_EVENT> events;
	intersect_boolean_curves(boundary_curve, linked_geometry, events,
	    split_tolerance.point);
	for (int event_index = 0; event_index < events.Count(); ++event_index) {
	    const ON_X_EVENT &event = events[event_index];
	    if (event.m_type == ON_X_EVENT::ccx_overlap) {
		if (!source_edge->IsClosed()) {
		    continue;
		}

		const int attachment_endpoint = at_start ?
		    (event.m_b[0] > event.m_b[1] ? 0 : 1) :
		    (event.m_b[0] < event.m_b[1] ? 0 : 1);
		const double linked_parameter = event.m_b[attachment_endpoint];
		const double boundary_parameter = event.m_a[attachment_endpoint];
		const ON_3dPoint boundary_point = boundary_curve->PointAt(
		    boundary_parameter);
		const ON_3dPoint model_point = boundary_point.IsValid() ?
		    surface->PointAt(boundary_point.x, boundary_point.y) :
		    ON_3dPoint::UnsetPoint;
		if (!linked_domain.Includes(linked_parameter) ||
		    !boolean_boundary_attachment_is_interior(*boundary_curve,
			boundary_parameter, *source_edge, model_point,
			split_tolerance.point, model_tolerance))
		{
		    continue;
		}

		const double tail_start = at_start ? linked_domain.Min() :
		    linked_parameter;
		const double tail_end = at_start ? linked_parameter :
		    linked_domain.Max();
		if (!boolean_linked_curve_interval_lies_in_source_edge_tube(
			linked_curve, tail_start, tail_end, surface, *source_edge,
			model_tolerance))
		{
		    continue;
		}
		has_overlap = true;

		BooleanSourceBoundaryAttachment candidate;
		candidate.m_boundary_curve_index = boundary_index;
		candidate.m_source_trim_index = trim_index;
		candidate.m_source_edge_index = source_trim->m_ei;
		candidate.m_curve_parameter = linked_parameter;
		candidate.m_boundary_parameter = boundary_parameter;
		candidate.m_boundary_point = boundary_point;
		candidate.m_needs_connector = false;
		boolean_append_unique_boundary_attachment(overlap_attachments,
		    candidate, split_tolerance.curve_parameter,
		    split_tolerance.point);
		continue;
	    }
	    if (event.m_type != ON_X_EVENT::ccx_point)
	    {
		continue;
	    }

	    const ON_3dPoint intersection_point = event.m_A[0];
	    double boundary_parameter = event.m_a[0];
	    double linked_parameter = event.m_b[0];
	    if ((!curve_parameter_matches_point_with_tolerance(boundary_curve,
		     boundary_parameter, intersection_point,
		     split_tolerance.point) &&
		 !point_3d_to_curve_parameter_with_tolerance(intersection_point,
		     boundary_curve, split_tolerance.point,
		     boundary_parameter)) ||
		(!curve_parameter_matches_point_with_tolerance(linked_geometry,
		     linked_parameter, intersection_point, split_tolerance.point) &&
		 !point_3d_to_curve_parameter_with_tolerance(intersection_point,
		     linked_geometry, split_tolerance.point, linked_parameter)) ||
		!boundary_curve->Domain().Includes(boundary_parameter) ||
		!linked_domain.Includes(linked_parameter))
	    {
		continue;
	    }

	    const ON_3dPoint boundary_point = boundary_curve->PointAt(
		boundary_parameter);
	    const ON_3dPoint model_point = surface->PointAt(boundary_point.x,
		boundary_point.y);
	    const bool interior = boolean_boundary_attachment_is_interior(*boundary_curve,
		    boundary_parameter, *source_edge, model_point,
		    split_tolerance.point, model_tolerance);
	    if (!interior)
	    {
		continue;
	    }

	    const double tail_start = at_start ? linked_domain.Min() :
		linked_parameter;
	    const double tail_end = at_start ? linked_parameter :
		linked_domain.Max();
	    if (tail_end - tail_start > split_tolerance.curve_parameter) {
		std::unique_ptr<ON_Curve> tail(boolean_linked_curve_subcurve(
		    linked_curve, tail_start, tail_end));
		const bool in_tube = tail &&
		    boolean_parameter_curve_lies_in_source_edge_tube(surface,
			*tail, *source_edge, model_tolerance);
		if (!in_tube)
		{
		    continue;
		}
	    }

	    BooleanSourceBoundaryAttachment candidate;
	    candidate.m_boundary_curve_index = boundary_index;
	    candidate.m_source_trim_index = trim_index;
	    candidate.m_source_edge_index = source_trim->m_ei;
	    candidate.m_curve_parameter = linked_parameter;
	    candidate.m_boundary_parameter = boundary_parameter;
	    candidate.m_boundary_point = boundary_point;
	    const ON_3dPoint curve_point = linked_geometry->PointAt(linked_parameter);
	    candidate.m_needs_connector = curve_point.DistanceTo(boundary_point) >
		ON_ZERO_TOLERANCE;
	    if (candidate.m_needs_connector) {
		ON_LineCurve connector(curve_point, boundary_point);
		if (!connector.IsValid() ||
		    !boolean_parameter_curve_lies_in_source_edge_tube(surface,
			connector, *source_edge, model_tolerance))
		{
		    continue;
		}
	    }
	    boolean_append_unique_boundary_attachment(intersections, candidate,
		split_tolerance.curve_parameter, split_tolerance.point);
	}
    }

    if (has_overlap) {
	if (overlap_attachments.size() == 1 && intersections.empty()) {
	    attachment = overlap_attachments[0];
	    return true;
	}
	return false;
    }
    if (intersections.size() > 1) {
	return false;
    }
    if (intersections.size() == 1) {
	attachment = intersections[0];
	return true;
    }

    std::vector<BooleanSourceBoundaryAttachment> connectors;
    for (int boundary_index = 0;
	 boundary_index < face->m_outerloop.Count(); ++boundary_index)
    {
	int trim_index = -1;
	const ON_BrepEdge *source_edge = NULL;
	const ON_BrepTrim *source_trim =
	    boolean_source_trim_for_outer_boundary(face, boundary_index,
		trim_index, source_edge);
	const ON_Curve *boundary_curve = face->m_outerloop[boundary_index];
	if (source_trim == NULL || source_edge == NULL ||
	    boundary_curve == NULL)
	{
	    if (DEBUG_BREP_BOOLEAN && (face->m_face->m_face_index == 13 ||
		    face->m_face->m_face_index == 20))
	    {
		bu_log("Boolean source-boundary connector face %d endpoint %d "
		    "boundary %d has no source trim/edge (%d/%d/%d).\n",
		    face->m_face->m_face_index, at_start ? 0 : 1,
		    boundary_index, source_trim != NULL, source_edge != NULL,
		    boundary_curve != NULL);
	    }
	    continue;
	}

	double boundary_parameter = ON_UNSET_VALUE;
	ON_3dPoint boundary_point = ON_3dPoint::UnsetPoint;
	if (!boolean_closest_curve_parameter(*boundary_curve, endpoint,
		boundary_parameter, boundary_point) ||
	    endpoint.DistanceTo(boundary_point) <= split_tolerance.point)
	{
	    continue;
	}
	const ON_3dPoint model_point = surface->PointAt(boundary_point.x,
	    boundary_point.y);
	if (!model_point.IsValid()) {
	    continue;
	}
	const double connector_length = model_endpoint.DistanceTo(model_point);
	const bool interior = boolean_boundary_attachment_is_interior(*boundary_curve,
		boundary_parameter, *source_edge, model_point,
		split_tolerance.point, model_tolerance);
	if (!std::isfinite(connector_length) || !interior)
	{
	    continue;
	}

	ON_LineCurve connector(endpoint, boundary_point);
	const bool in_face = connector.IsValid() &&
	    boolean_connector_stays_in_face(face, connector, boundary_index,
		boundary_point, split_tolerance.point);
	const bool in_tube = connector.IsValid() &&
	    boolean_parameter_curve_lies_in_source_edge_tube(surface,
		connector, *source_edge, model_tolerance);
	const bool point_sized_exterior = in_tube &&
	    connector_length <= BREP_EDGE_MISS_TOLERANCE;
	if (DEBUG_BREP_BOOLEAN && face->m_face->m_face_index >= 0) {
	    bu_log("Boolean source-boundary attachment face %d endpoint %d "
		"boundary %d: UV gap %.17g, model gap %.17g, interior %d, "
		"in face/tube %d/%d.\n", face->m_face->m_face_index,
		at_start ? 0 : 1, boundary_index,
		endpoint.DistanceTo(boundary_point), connector_length, interior,
		in_face, in_tube);
	}
	if (!connector.IsValid() || !in_tube ||
	    (!in_face && !point_sized_exterior))
	{
	    continue;
	}
	BooleanSourceBoundaryAttachment candidate;
	candidate.m_boundary_curve_index = boundary_index;
	candidate.m_source_trim_index = trim_index;
	candidate.m_source_edge_index = source_trim->m_ei;
	candidate.m_curve_parameter = endpoint_parameter;
	candidate.m_boundary_parameter = boundary_parameter;
	candidate.m_boundary_point = boundary_point;
	candidate.m_needs_connector = true;
	boolean_append_unique_boundary_attachment(connectors, candidate,
	    split_tolerance.curve_parameter, split_tolerance.point);
    }

    if (connectors.size() != 1) {
	return false;
    }
    attachment = connectors[0];
    return true;
}


static bool
boolean_same_closed_source_edge_attachments_are_distinct(
    const TrimmedFace *face,
    const BooleanSourceBoundaryAttachment endpoints[2],
    const BooleanLoopTolerance &split_tolerance)
{
    const ON_Brep *source_brep = face && face->m_face ?
	face->m_face->Brep() : NULL;
    const ON_Surface *surface = face && face->m_face ?
	face->m_face->SurfaceOf() : NULL;
    const int source_edge_index = endpoints[0].m_source_edge_index;
    if (source_brep == NULL || surface == NULL || source_edge_index < 0 ||
	source_edge_index >= source_brep->m_E.Count() ||
	source_edge_index != endpoints[1].m_source_edge_index ||
	!source_brep->m_E[source_edge_index].IsClosed() ||
	endpoints[0].m_boundary_point.DistanceTo(
	    endpoints[1].m_boundary_point) <= split_tolerance.point)
    {
	return false;
    }

    const ON_3dPoint first_model = surface->PointAt(
	endpoints[0].m_boundary_point.x, endpoints[0].m_boundary_point.y);
    const ON_3dPoint second_model = surface->PointAt(
	endpoints[1].m_boundary_point.x, endpoints[1].m_boundary_point.y);
    if (!first_model.IsValid() || !second_model.IsValid() ||
	first_model.DistanceTo(second_model) <= ON_ZERO_TOLERANCE)
    {
	return false;
    }

    if (endpoints[0].m_boundary_curve_index ==
	endpoints[1].m_boundary_curve_index)
    {
	const int boundary_index = endpoints[0].m_boundary_curve_index;
	if (boundary_index < 0 || boundary_index >= face->m_outerloop.Count()) {
	    return false;
	}
	double point_tolerance = 0.0;
	double parameter_tolerance = 0.0;
	if (!get_face_boundary_curve_tolerances(surface,
		face->m_outerloop[boundary_index], point_tolerance,
		parameter_tolerance) ||
	    fabs(endpoints[0].m_boundary_parameter -
		endpoints[1].m_boundary_parameter) <= parameter_tolerance)
	{
	    return false;
	}
    }

    return true;
}


static bool
boolean_align_same_boundary_attachments_to_linked_segments(
    const TrimmedFace *face,
    LinkedCurve &curve,
    BooleanSourceBoundaryAttachment endpoints[2],
    double model_tolerance,
    const BooleanLoopTolerance &split_tolerance)
{
    const ON_Surface *surface = face && face->m_face ?
	face->m_face->SurfaceOf() : NULL;
    const ON_Brep *source_brep = face && face->m_face ?
	face->m_face->Brep() : NULL;
    const ON_PolyCurve *polycurve = ON_PolyCurve::Cast(curve.Curve());
    const int source_edge_index = endpoints[0].m_source_edge_index;
    if (surface == NULL || source_brep == NULL || polycurve == NULL ||
	polycurve->Count() != curve.m_ssi_curves.Count() ||
	polycurve->Count() < 2 || source_edge_index < 0 ||
	source_edge_index >= source_brep->m_E.Count())
    {
	return false;
    }

    const ON_BrepEdge &source_edge = source_brep->m_E[source_edge_index];
    int first_retained = 0;
    while (first_retained < polycurve->Count()) {
	const ON_Curve *segment = polycurve->SegmentCurve(first_retained);
	if (segment == NULL || !boolean_parameter_curve_lies_in_source_edge_tube(
		surface, *segment, source_edge, model_tolerance))
	{
	    break;
	}
	++first_retained;
    }
    int last_retained = polycurve->Count() - 1;
    while (last_retained >= first_retained) {
	const ON_Curve *segment = polycurve->SegmentCurve(last_retained);
	if (segment == NULL || !boolean_parameter_curve_lies_in_source_edge_tube(
		surface, *segment, source_edge, model_tolerance))
	{
	    break;
	}
	--last_retained;
    }
    if (first_retained > last_retained) {
	return false;
    }

    const double retained_parameters[2] = {
	polycurve->SegmentDomain(first_retained).Min(),
	polycurve->SegmentDomain(last_retained).Max()
    };
    for (int endpoint_index = 0; endpoint_index < 2; ++endpoint_index) {
	const int boundary_index = endpoints[endpoint_index].m_boundary_curve_index;
	if (boundary_index < 0 || boundary_index >= face->m_outerloop.Count() ||
	    face->m_outerloop[boundary_index] == NULL)
	{
	    return false;
	}
	const ON_3dPoint curve_point = polycurve->PointAt(
	    retained_parameters[endpoint_index]);
	double boundary_parameter = ON_UNSET_VALUE;
	ON_3dPoint boundary_point = ON_3dPoint::UnsetPoint;
	if (!curve_point.IsValid() || !boolean_closest_curve_parameter(
		*face->m_outerloop[boundary_index], curve_point,
		boundary_parameter, boundary_point) ||
	    curve_point.DistanceTo(boundary_point) > split_tolerance.point)
	{
	    return false;
	}
	endpoints[endpoint_index].m_curve_parameter =
	    retained_parameters[endpoint_index];
	endpoints[endpoint_index].m_boundary_parameter = boundary_parameter;
	endpoints[endpoint_index].m_boundary_point = boundary_point;
	endpoints[endpoint_index].m_needs_connector = false;
    }
    return endpoints[1].m_curve_parameter - endpoints[0].m_curve_parameter >
	split_tolerance.curve_parameter;
}


static bool
boolean_trim_same_closed_edge_boundary_tails(
    const TrimmedFace *face,
    LinkedCurve &curve,
    BooleanSourceBoundaryAttachment endpoints[2],
    double model_tolerance,
    const BooleanLoopTolerance &split_tolerance)
{
    const ON_Surface *surface = face->m_face->SurfaceOf();
    const ON_BrepEdge &source_edge =
	face->m_face->Brep()->m_E[endpoints[0].m_source_edge_index];
    const ON_Curve *geometry = curve.Curve();
    if (geometry == NULL) {
	return false;
    }

    BooleanSourceBoundaryAttachment replacements[2];
    bool found[2] = {false, false};
    for (int boundary_index = 0; boundary_index < face->m_outerloop.Count();
	 ++boundary_index)
    {
	if (boundary_index != endpoints[0].m_boundary_curve_index &&
	    boundary_index != endpoints[1].m_boundary_curve_index)
	{
	    continue;
	}
	ON_SimpleArray<ON_X_EVENT> events;
	intersect_boolean_curves(face->m_outerloop[boundary_index], geometry,
	    events, split_tolerance.point);
	for (int event_index = 0; event_index < events.Count(); ++event_index) {
	    const ON_X_EVENT &event = events[event_index];
	    if (event.m_type != ON_X_EVENT::ccx_overlap) {
		continue;
	    }
	    for (int endpoint_index = 0; endpoint_index < 2; ++endpoint_index) {
		const bool at_start = endpoint_index == 0;
		const int event_endpoint = at_start ?
		    (event.m_b[0] > event.m_b[1] ? 0 : 1) :
		    (event.m_b[0] < event.m_b[1] ? 0 : 1);
		const double linked_parameter = event.m_b[event_endpoint];
		const ON_Interval domain = geometry->Domain();
		const double tail_start = at_start ? domain.Min() : linked_parameter;
		const double tail_end = at_start ? linked_parameter : domain.Max();
		if (tail_end - tail_start <= split_tolerance.curve_parameter) {
		    continue;
		}
		const bool in_tube =
		    boolean_linked_curve_interval_lies_in_source_edge_tube(curve,
			tail_start, tail_end, surface, source_edge,
			model_tolerance);
		if (!in_tube)
		{
		    continue;
		}
		if (found[endpoint_index]) {
		    return false;
		}
		replacements[endpoint_index] = endpoints[endpoint_index];
		replacements[endpoint_index].m_boundary_curve_index = boundary_index;
		replacements[endpoint_index].m_curve_parameter = linked_parameter;
		replacements[endpoint_index].m_boundary_parameter =
		    event.m_a[event_endpoint];
		replacements[endpoint_index].m_boundary_point = event.m_A[event_endpoint];
		replacements[endpoint_index].m_needs_connector = false;
		found[endpoint_index] = true;
	    }
	}
    }
    if (!found[0] || !found[1] ||
	replacements[1].m_curve_parameter - replacements[0].m_curve_parameter <=
	    split_tolerance.curve_parameter ||
	!curve.Trim(replacements[0].m_curve_parameter,
	    replacements[1].m_curve_parameter))
    {
	return false;
    }
    endpoints[0] = replacements[0];
    endpoints[1] = replacements[1];
    return true;
}


static bool
attach_open_ssi_to_source_boundaries(
    const TrimmedFace *face,
    LinkedCurve &linked_curve,
    const BooleanLoopTolerance &split_tolerance)
{
    const ON_Surface *surface = face && face->m_face ?
	face->m_face->SurfaceOf() : NULL;
    const ON_Brep *source_brep = face && face->m_face ?
	face->m_face->Brep() : NULL;
    const ON_Curve *linked_geometry = linked_curve.Curve();
    if (surface == NULL || source_brep == NULL || linked_geometry == NULL ||
	linked_curve.IsClosed())
    {
	return false;
    }

    BooleanBoundaryEndpointHit original_hits[2];
    if (boolean_find_certified_open_curve_endpoint_pair(linked_geometry,
	face->m_outerloop, split_tolerance.point, original_hits))
    {
	return false;
    }

    const double attachment_tolerance =
	BOOLEAN_SOURCE_EDGE_ATTACHMENT_TOLERANCE_MULTIPLIER *
	boolean_model_repair_tolerance(source_brep->BoundingBox());
    if (!(attachment_tolerance > 0.0) ||
	!std::isfinite(attachment_tolerance))
    {
	return false;
    }

    BooleanSourceBoundaryAttachment endpoints[2];
    const bool found_start = boolean_find_unique_source_boundary_attachment(
	face, linked_curve, true, split_tolerance, attachment_tolerance,
	endpoints[0]);
    const bool found_end = boolean_find_unique_source_boundary_attachment(
	face, linked_curve, false, split_tolerance, attachment_tolerance,
	endpoints[1]);
    if (DEBUG_BREP_BOOLEAN && (!found_start || !found_end)) {
	bu_log("Boolean source-boundary attachment face %d found endpoints "
	    "%d/%d.\n", face->m_face->m_face_index, found_start, found_end);
    }
    if (!found_start || !found_end ||
	endpoints[1].m_curve_parameter - endpoints[0].m_curve_parameter <=
	    split_tolerance.curve_parameter)
    {
	return false;
    }
    const bool same_source_edge = endpoints[0].m_source_edge_index ==
	endpoints[1].m_source_edge_index;
    if (same_source_edge &&
	!boolean_same_closed_source_edge_attachments_are_distinct(face,
	    endpoints, split_tolerance))
    {
	return false;
    }

    LinkedCurve core = linked_curve;
    ON_Interval original_domain = core.Domain();
    original_domain.MakeIncreasing();
    const bool trim_start = endpoints[0].m_curve_parameter >
	original_domain.Min() + split_tolerance.curve_parameter;
    const bool trim_end = endpoints[1].m_curve_parameter <
	original_domain.Max() - split_tolerance.curve_parameter;
    if ((trim_start || trim_end) &&
	!core.Trim(endpoints[0].m_curve_parameter,
	    endpoints[1].m_curve_parameter))
    {
	return false;
    }

    LinkedCurve repaired;
    const SSICurve &first_source = linked_curve.m_ssi_curves[0];
    const SSICurve &last_source = *linked_curve.m_ssi_curves.Last();
    if (endpoints[0].m_needs_connector) {
	repaired.Append(SSICurve(new ON_LineCurve(endpoints[0].m_boundary_point,
	    core.PointAtStart()), first_source.m_source_face_index, -1));
    }
    repaired.Append(core);
    if (endpoints[1].m_needs_connector) {
	repaired.Append(SSICurve(new ON_LineCurve(core.PointAtEnd(),
	    endpoints[1].m_boundary_point), last_source.m_source_face_index,
	    -1));
    }
    if (same_source_edge) {
	LinkedCurve normalized = repaired;
	BooleanSourceBoundaryAttachment normalized_endpoints[2] = {
	    endpoints[0], endpoints[1]
	};
	if (boolean_align_same_boundary_attachments_to_linked_segments(face,
		normalized, normalized_endpoints, attachment_tolerance,
		split_tolerance) ||
	    boolean_trim_same_closed_edge_boundary_tails(face, normalized,
		normalized_endpoints, attachment_tolerance, split_tolerance))
	{
	    repaired = normalized;
	    endpoints[0] = normalized_endpoints[0];
	    endpoints[1] = normalized_endpoints[1];
	}
    }
    if (!repaired.IsValid()) {
	return false;
    }
	if (same_source_edge) {
	    repaired.m_certified_same_boundary = true;
	}

    ON_SimpleArray<IntersectPoint> certified_hits;
    if (!append_certified_open_curve_endpoint_hits(face, repaired.Curve(),
	certified_hits, same_source_edge) || certified_hits.Count() != 2 ||
	certified_hits[0].m_loop_seg != endpoints[0].m_boundary_curve_index ||
	certified_hits[1].m_loop_seg != endpoints[1].m_boundary_curve_index ||
	certified_hits[0].m_pt.DistanceTo(endpoints[0].m_boundary_point) >
	    split_tolerance.point ||
	certified_hits[1].m_pt.DistanceTo(endpoints[1].m_boundary_point) >
	    split_tolerance.point)
    {
	return false;
    }

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Attached Boolean SSI on source face %d to edges %d/%d "
	    "(trimmed %d/%d, connected %d/%d) at model tolerance %.17g.\n",
	    face->m_face->m_face_index, endpoints[0].m_source_edge_index,
	    endpoints[1].m_source_edge_index, trim_start, trim_end,
	    endpoints[0].m_needs_connector, endpoints[1].m_needs_connector,
	    attachment_tolerance);
    }
    linked_curve = repaired;
    return true;
}


/* Curve/curve intersection may report a short overlap when an SSI leaves a
 * face boundary tangentially.  Such an overlap is only an endpoint incidence,
 * not a boundary segment of the partition, when its complete model-space
 * locus is contained in the ordinary intersection-tolerance ball around that
 * endpoint.  Recognizing only terminal, certified point-sized overlaps lets
 * the endpoint-pair fallback below recover the opposite boundary hit without
 * treating a genuine boundary-coincident SSI as an interior partition. */
static bool
boolean_terminal_ssi_overlap_is_pointlike(
    const TrimmedFace *face,
    LinkedCurve &linked_curve,
    const ON_Interval &overlap_interval,
    const BooleanLoopTolerance &split_tolerance)
{
    const ON_Surface *surface = face && face->m_face ?
	face->m_face->SurfaceOf() : NULL;
    const ON_Curve *linked_geometry = linked_curve.Curve();
    ON_Interval linked_domain = linked_geometry ? linked_geometry->Domain() :
	ON_Interval::EmptyInterval;
    ON_Interval overlap = overlap_interval;
    linked_domain.MakeIncreasing();
    overlap.MakeIncreasing();
    if (surface == NULL || linked_geometry == NULL ||
	!linked_domain.IsIncreasing() || !overlap.IsValid())
    {
	return false;
    }

    const bool at_start = overlap.Min() <= linked_domain.Min() +
	split_tolerance.curve_parameter;
    const bool at_end = overlap.Max() >= linked_domain.Max() -
	split_tolerance.curve_parameter;
    if (at_start == at_end) {
	return false;
    }

    if (!overlap.IsIncreasing() ||
	overlap.Length() <= split_tolerance.curve_parameter)
    {
	return true;
    }

    std::unique_ptr<ON_Curve> parameter_piece(
	boolean_linked_curve_subcurve(linked_curve, overlap.Min(),
	    overlap.Max()));
    std::unique_ptr<ON_Curve> model_piece(parameter_piece ?
	pushup_boolean_curve(surface, *parameter_piece) : NULL);
    const ON_3dPoint endpoint_parameter = linked_geometry->PointAt(
	at_start ? linked_domain.Min() : linked_domain.Max());
    const ON_3dPoint endpoint = endpoint_parameter.IsValid() ?
	surface->PointAt(endpoint_parameter.x, endpoint_parameter.y) :
	ON_3dPoint::UnsetPoint;
    return model_piece && model_piece->IsValid() && endpoint.IsValid() &&
	brep_curve_locus_within_ball(*model_piece, endpoint, INTERSECTION_TOL);
}


/* Turn an open curve into a closed curve by using segments from the
 * face outerloop to connect its endpoints.
 *
 * Returns false on failure, true otherwise.
 */
std::vector<ON_SimpleArray<ON_Curve *> >
split_face_into_loops(
    const TrimmedFace *orig_face,
    LinkedCurve &linked_curve)
{
    std::vector<ON_SimpleArray<ON_Curve *> > out;

    if (linked_curve.IsClosed()) {
	ON_SimpleArray<ON_Curve *> loop;
	for (int i = 0; i < orig_face->m_outerloop.Count(); ++i) {
	    loop.Append(orig_face->m_outerloop[i]->Duplicate());
	}
	out.push_back(loop);
	return out;
    }

    ON_SimpleArray<ON_Curve *> linked_segments;
    for (int segment_index = 0;
	 segment_index < linked_curve.m_ssi_curves.Count(); ++segment_index)
    {
	if (linked_curve.m_ssi_curves[segment_index].m_curve != NULL) {
	    linked_segments.Append(
		linked_curve.m_ssi_curves[segment_index].m_curve);
	}
    }
    const BooleanLoopTolerance split_tolerance =
	boolean_loop_tolerance_for_surface(
	    orig_face->m_face ? orig_face->m_face->SurfaceOf() : NULL,
	    orig_face->m_outerloop, linked_segments);
    attach_open_ssi_to_source_boundaries(orig_face, linked_curve,
	split_tolerance);
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("split_face_into_loops: UV point tolerance %.17g.\n",
	    split_tolerance.point);
    }

    /* We followed the algorithms described in:
     * S. Krishnan, A. Narkhede, and D. Manocha. BOOLE: A System to Compute
     * Boolean Combinations of Sculptured Solids. Technical Report TR95-008,
     * Department of Computer Science, University of North Carolina, 1995.
     * Appendix B: Partitioning a Simple Polygon using Non-Intersecting
     * Chains.
     */

    // Get the intersection points between the SSI curves and the outerloop.
    ON_SimpleArray<IntersectPoint> clx_points;
    bool intersects_outerloop = false;
    bool has_outerloop_overlap = false;
    std::vector<ON_Interval> outerloop_overlap_intervals;
    const ON_Curve *linked_geometry = linked_curve.Curve();
    if (linked_geometry == NULL) {
	throw InvalidGeometry(
	    "Face splitting given an invalid linked intersection curve.\n");
    }
    for (int i = 0; i < orig_face->m_outerloop.Count(); i++) {
	const ON_Curve *boundary_curve = orig_face->m_outerloop[i];
	if (boundary_curve == NULL) {
	    throw InvalidGeometry(
		"Face splitting given a null outer-loop curve.\n");
	}
	ON_SimpleArray<ON_X_EVENT> x_events;
	intersect_boolean_curves(boundary_curve, linked_geometry,
		x_events, split_tolerance.point);

	for (int j = 0; j < x_events.Count(); j++) {
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("split_face_into_loops: boundary %d event %d/%d type %d "
		    "boundary %.17g -> %.17g, linked %.17g -> %.17g, "
		    "point %.17g %.17g.\n", i, j, x_events.Count(),
		    static_cast<int>(x_events[j].m_type),
		    x_events[j].m_a[0], x_events[j].m_a[1],
		    x_events[j].m_b[0], x_events[j].m_b[1],
		    x_events[j].m_A[0].x, x_events[j].m_A[0].y);
	    }
	    if (x_events[j].m_type == ON_X_EVENT::ccx_overlap) {
		ON_Interval overlap(x_events[j].m_b[0], x_events[j].m_b[1]);
		overlap.MakeIncreasing();
		if (boolean_terminal_ssi_overlap_is_pointlike(orig_face,
			linked_curve, overlap, split_tolerance))
		{
		    if (DEBUG_BREP_BOOLEAN) {
			bu_log("split_face_into_loops: treated terminal overlap "
			    "%.17g -> %.17g as one endpoint incidence.\n",
			    overlap.Min(), overlap.Max());
		    }
		    continue;
		}
		intersects_outerloop = true;
		has_outerloop_overlap = true;
		if (overlap.IsIncreasing()) {
		    outerloop_overlap_intervals.push_back(overlap);
		}
		continue;
	    }

	    const ON_3dPoint intersection_point = x_events[j].m_A[0];
	    double boundary_parameter = x_events[j].m_a[0];
	    if (!curve_parameter_matches_point_with_tolerance(boundary_curve,
		boundary_parameter, intersection_point, split_tolerance.point) &&
		!point_3d_to_curve_parameter_with_tolerance(intersection_point,
		    boundary_curve, split_tolerance.point, boundary_parameter))
	    {
		continue;
	    }
	    double linked_parameter = x_events[j].m_b[0];
	    if (!curve_parameter_matches_point_with_tolerance(linked_geometry,
		linked_parameter, intersection_point, split_tolerance.point) &&
		!point_3d_to_curve_parameter_with_tolerance(intersection_point,
		    linked_geometry, split_tolerance.point, linked_parameter))
	    {
		continue;
	    }

	    IntersectPoint tmp_pt;
	    tmp_pt.m_pt = intersection_point;
	    tmp_pt.m_seg_t = boundary_parameter;
	    tmp_pt.m_curve_t = linked_parameter;
	    tmp_pt.m_loop_seg = i;
	    clx_points.Append(tmp_pt);
	    intersects_outerloop = true;
	}
    }

    std::vector<double> hit_parameters;
    for (int point_index = 0; point_index < clx_points.Count();
	 ++point_index)
    {
	hit_parameters.push_back(clx_points[point_index].m_curve_t);
    }
    std::sort(hit_parameters.begin(), hit_parameters.end());
    hit_parameters.erase(std::unique(hit_parameters.begin(),
	hit_parameters.end(), [&split_tolerance](double first, double second) {
	    return fabs(first - second) <= split_tolerance.curve_parameter;
	}), hit_parameters.end());
    for (size_t parameter_index = 1;
	 parameter_index < hit_parameters.size(); ++parameter_index)
    {
	bool found_inside = false;
	bool found_outside = false;
	try {
	    const bool sampled = linked_curve_interval_locations(linked_curve,
		    hit_parameters[parameter_index - 1],
		    hit_parameters[parameter_index], orig_face->m_outerloop,
		    split_tolerance, found_inside, found_outside);
	    if (DEBUG_BREP_BOOLEAN) {
		const ON_3dPoint midpoint = linked_curve.PointAt(
		    0.5 * (hit_parameters[parameter_index - 1] +
			hit_parameters[parameter_index]));
		bu_log("split_face_into_loops: interval %.17g -> %.17g, "
		    "midpoint (%.17g, %.17g), sampled %d, inside %d, "
		    "outside %d.\n",
		    hit_parameters[parameter_index - 1],
		    hit_parameters[parameter_index], midpoint.x, midpoint.y,
		    sampled, found_inside, found_outside);
	    }
	    const bool boundary_interval = sampled && !found_inside &&
		(!found_outside || linked_curve_interval_is_face_boundary(
		    linked_curve, hit_parameters[parameter_index - 1],
		    hit_parameters[parameter_index], orig_face->m_outerloop,
		    split_tolerance));
	    if (boundary_interval)
	    {
		outerloop_overlap_intervals.push_back(ON_Interval(
		    hit_parameters[parameter_index - 1],
		    hit_parameters[parameter_index]));
		has_outerloop_overlap = true;
	    }
	} catch (InvalidGeometry &) {
	    continue;
	}
    }

    if (!outerloop_overlap_intervals.empty()) {
	std::sort(outerloop_overlap_intervals.begin(),
	    outerloop_overlap_intervals.end(),
	    [](const ON_Interval &first, const ON_Interval &second) {
		return first.Min() < second.Min();
	    });
	std::vector<ON_Interval> merged_overlaps;
	for (size_t overlap_index = 0;
	     overlap_index < outerloop_overlap_intervals.size();
	     ++overlap_index)
	{
	    const ON_Interval &overlap =
		outerloop_overlap_intervals[overlap_index];
	    if (merged_overlaps.empty() || overlap.Min() >
		merged_overlaps.back().Max() + split_tolerance.curve_parameter)
	    {
		merged_overlaps.push_back(overlap);
	    } else {
		merged_overlaps.back().m_t[1] = std::max(
		    merged_overlaps.back().Max(), overlap.Max());
	    }
	}

	const ON_Interval linked_domain = linked_curve.Domain();
	std::vector<ON_Interval> collapsible_overlaps;
	for (size_t overlap_index = 0; overlap_index < merged_overlaps.size();
	     ++overlap_index)
	{
	    const ON_Interval &overlap = merged_overlaps[overlap_index];
	    if (overlap.Min() <= linked_domain.Min() +
		    split_tolerance.curve_parameter ||
		overlap.Max() >= linked_domain.Max() -
		    split_tolerance.curve_parameter)
	    {
		continue;
	    }

	    double previous_parameter = linked_domain.Min();
	    double next_parameter = linked_domain.Max();
	    for (int point_index = 0; point_index < clx_points.Count();
		 ++point_index)
	    {
		const double parameter = clx_points[point_index].m_curve_t;
		if (parameter < overlap.Min() &&
		    parameter > previous_parameter)
		{
		    previous_parameter = parameter;
		}
		if (parameter > overlap.Max() && parameter < next_parameter) {
		    next_parameter = parameter;
		}
	    }

	    try {
		const CurvePoint::Location previous_location =
		    linked_curve_interval_face_location(linked_curve,
			previous_parameter, overlap.Min(),
			orig_face->m_outerloop, split_tolerance);
		const CurvePoint::Location next_location =
		    linked_curve_interval_face_location(linked_curve,
			overlap.Max(), next_parameter,
			orig_face->m_outerloop, split_tolerance);
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("split_face_into_loops: overlap %.17g -> %.17g, "
			"adjacent %.17g -> %.17g location %d and %.17g -> "
			"%.17g location %d.\n", overlap.Min(), overlap.Max(),
			previous_parameter, overlap.Min(), previous_location,
			overlap.Max(), next_parameter, next_location);
		}
		if (previous_location == CurvePoint::INSIDE &&
		    next_location == CurvePoint::INSIDE)
		{
		    collapsible_overlaps.push_back(overlap);
		}
	    } catch (InvalidGeometry &) {
		continue;
	    }
	}

	for (int point_index = clx_points.Count() - 1; point_index >= 0;
	     --point_index)
	{
	    for (size_t overlap_index = 0;
		 overlap_index < collapsible_overlaps.size(); ++overlap_index)
	    {
		const ON_Interval &overlap =
		    collapsible_overlaps[overlap_index];
		const double parameter = clx_points[point_index].m_curve_t;
		if (parameter >= overlap.Min() -
			split_tolerance.curve_parameter &&
		    parameter <= overlap.Max() +
			split_tolerance.curve_parameter)
		{
		    clx_points.Remove(point_index);
		    break;
		}
	    }
	}
    }

    bool has_certified_endpoint_pair = false;
    if (!has_outerloop_overlap && clx_points.Count() < 2) {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_Curve *curve = linked_curve.Curve();
	    const ON_3dPoint start = curve ? curve->PointAtStart() :
		ON_3dPoint::UnsetPoint;
	    const ON_3dPoint end = curve ? curve->PointAtEnd() :
		ON_3dPoint::UnsetPoint;
	    const ON_Surface *surface = orig_face && orig_face->m_face ?
		orig_face->m_face->SurfaceOf() : NULL;
	    bu_log("split_face_into_loops: endpoint fallback with %d raw hits, "
		"overlap %d, curve (%.17g, %.17g) -> (%.17g, %.17g), "
		"surface closed %d/%d periodic %d/%d.\n",
		clx_points.Count(), has_outerloop_overlap, start.x, start.y,
		end.x, end.y, surface ? surface->IsClosed(0) : 0,
		surface ? surface->IsClosed(1) : 0,
		surface ? surface->IsPeriodic(0) : 0,
		surface ? surface->IsPeriodic(1) : 0);
	}
	has_certified_endpoint_pair =
	    append_certified_open_curve_endpoint_hits(orig_face,
		linked_curve.Curve(), clx_points,
		linked_curve.m_certified_same_boundary);
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("split_face_into_loops: endpoint fallback certified %d, "
		"now %d hits.\n", has_certified_endpoint_pair,
		clx_points.Count());
	}
	if (has_certified_endpoint_pair) {
	    intersects_outerloop = true;
	}
    }

    for (int i = 0; i < clx_points.Count(); ++i) {
	canonicalize_outerloop_vertex_hit(orig_face->m_outerloop, clx_points[i]);
    }
    clx_points.QuickSort(curve_t_compare);
    for (int i = clx_points.Count() - 1; i > 0; --i) {
	if (are_duplicate_outerloop_vertex_hits(clx_points[i - 1], clx_points[i])) {
	    clx_points.Remove(i);
	}
    }

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("split_face_into_loops: %d canonical hits, intersects %d, "
	    "certified endpoints %d.\n", clx_points.Count(),
	    intersects_outerloop, has_certified_endpoint_pair);
    }

    // can't close curves that don't partition the face
    if (!intersects_outerloop || clx_points.Count() < 2 ||
	(has_certified_endpoint_pair && clx_points.Count() != 2))
    {
	ON_SimpleArray<ON_Curve *> loop;
	for (int i = 0; i < orig_face->m_outerloop.Count(); ++i) {
	    loop.Append(orig_face->m_outerloop[i]->Duplicate());
	}
	out.push_back(loop);
	return out;
    }

    // rank these intersection points
    for (int i = 0; i < clx_points.Count(); i++) {
	clx_points[i].m_curve_pos = i;
    }

    // classify intersection points
    ON_SimpleArray<IntersectPoint> new_pts;
    double curve_min_t = linked_curve.Domain().Min();
    double curve_max_t = linked_curve.Domain().Max();

    for (int i = 0; i < clx_points.Count(); i++) {
	bool is_first_ipt = (i == 0);
	bool is_last_ipt = (i == (clx_points.Count() - 1));

	IntersectPoint *ipt = &clx_points[i];
	double curve_t = ipt->m_curve_t;

	// If the point is on the boundary, we treat it with the same
	// way as it's outside.
	// For example, the prev side is inside, and the next's on
	// boundary, that point should be IntersectPoint::OUT, the
	// same as the next's outside the loop.
	// Other cases are similar.
	bool prev_in, next_in;
	try {
	    const double previous_parameter = is_first_ipt ? curve_min_t :
		clx_points[i - 1].m_curve_t;
	    const double next_parameter = is_last_ipt ? curve_max_t :
		clx_points[i + 1].m_curve_t;
	    prev_in = linked_curve_interval_face_location(linked_curve,
		previous_parameter, curve_t, orig_face->m_outerloop,
		split_tolerance) == CurvePoint::INSIDE;
	    next_in = linked_curve_interval_face_location(linked_curve,
		curve_t, next_parameter, orig_face->m_outerloop,
		split_tolerance) == CurvePoint::INSIDE;
	} catch (InvalidGeometry &e) {
	    bu_log("%s", e.what());
	    // not a loop
	    ipt->m_dir = IntersectPoint::UNSET;
	    continue;
	}
	if (is_first_ipt && ON_NearZero(curve_t - curve_min_t)) {
	    ipt->m_dir = next_in ? IntersectPoint::IN_HIT : IntersectPoint::OUT_HIT;
	    continue;
	}
	if (is_last_ipt && ON_NearZero(curve_t - curve_max_t)) {
	    ipt->m_dir = prev_in ? IntersectPoint::OUT_HIT : IntersectPoint::IN_HIT;
	    continue;
	}
	if (prev_in && next_in) {
	    // tangent point, both sides in, duplicate that point
	    new_pts.Append(*ipt);
	    new_pts.Last()->m_dir = IntersectPoint::TANGENT;
	    new_pts.Last()->m_curve_pos = ipt->m_curve_pos;
	    ipt->m_dir = IntersectPoint::TANGENT;
	} else if (!prev_in && !next_in) {
	    // tangent point, both sides out, useless
	    ipt->m_dir = IntersectPoint::UNSET;
	} else if (prev_in && !next_in) {
	    // transversal point, going outside
	    ipt->m_dir = IntersectPoint::OUT_HIT;
	} else {
	    // transversal point, going inside
	    ipt->m_dir = IntersectPoint::IN_HIT;
	}
    }

    clx_points.Append(new_pts.Count(), new_pts.Array());
    clx_points.QuickSort(loop_t_compare);

    // Split the outer loop.
    ON_SimpleArray<ON_Curve *> outerloop_segs;
    int clx_i = 0;
    for (int loop_seg = 0; loop_seg < orig_face->m_outerloop.Count(); loop_seg++) {
	ON_Curve *remainder = orig_face->m_outerloop[loop_seg]->Duplicate();
	if (remainder == NULL) {
	    bu_log("ON_Curve::Duplicate() failed.\n");
	    return out;
	}
	for (; clx_i < clx_points.Count() && clx_points[clx_i].m_loop_seg == loop_seg; clx_i++) {
	    IntersectPoint &ipt = clx_points[clx_i];
	    ON_Curve *portion_before_ipt = NULL;
	    if (remainder) {
		double start_t = remainder->Domain().Min();
		double end_t = remainder->Domain().Max();
		if (ON_NearZero(ipt.m_seg_t - end_t)) {
		    // Can't call Split() if ipt is at start (that
		    // case is handled by the initialization) or ipt
		    // is at end (handled here).
		    portion_before_ipt = remainder;
		    remainder = NULL;
		} else if (!ON_NearZero(ipt.m_seg_t - start_t)) {
		    if (!remainder->Split(ipt.m_seg_t, portion_before_ipt, remainder)) {
			bu_log("Split failed.\n");
			bu_log("Domain: [%f, %f]\n", end_t, start_t);
			bu_log("m_seg_t: %f\n", ipt.m_seg_t);
		    }
		}
	    }
	    if (portion_before_ipt) {
		outerloop_segs.Append(portion_before_ipt);
	    }
	    ipt.m_split_li = outerloop_segs.Count() - 1;
	}
	if (remainder) {
	    outerloop_segs.Append(remainder);
	}
    }

    // Append the first element at the last to handle some special cases.
    if (clx_points.Count()) {
	clx_points.Append(clx_points[0]);
	clx_points.Last()->m_loop_seg += orig_face->m_outerloop.Count();
	for (int i = 0; i <= clx_points[0].m_split_li; i++) {
	    ON_Curve *dup = outerloop_segs[i]->Duplicate();
	    if (dup == NULL) {
		bu_log("ON_Curve::Duplicate() failed.\n");
		for (int j = 0; j < outerloop_segs.Count(); ++j) {
		    delete outerloop_segs[j];
		}
		return out;
	    }
	    outerloop_segs.Append(dup);
	}
	clx_points.Last()->m_split_li = outerloop_segs.Count() - 1;
    }

    if (DEBUG_BREP_BOOLEAN) {
	for (int segment_index = 0;
	     segment_index < linked_curve.m_ssi_curves.Count();
	     ++segment_index)
	{
	    const ON_Curve *segment =
		linked_curve.m_ssi_curves[segment_index].m_curve;
	    if (segment == NULL) {
		continue;
	    }
	    const ON_3dPoint start = segment->PointAtStart();
	    const ON_3dPoint end = segment->PointAtEnd();
	    bu_log("split_face_into_loops: linked piece %d: "
		"(%.17g, %.17g) -> (%.17g, %.17g).\n", segment_index,
		start.x, start.y, end.x, end.y);
	}
	for (int i = 0; i < clx_points.Count(); i++) {
	    IntersectPoint &ipt = clx_points[i];
	    bu_log("clx_points[%d](count = %d): m_curve_pos = %d, "
		"m_dir = %d, curve_t = %.17g, loop_seg = %d, seg_t = "
		"%.17g, point = (%.17g, %.17g).\n", i, clx_points.Count(),
		ipt.m_curve_pos, ipt.m_dir, ipt.m_curve_t,
		ipt.m_loop_seg, ipt.m_seg_t, ipt.m_pt.x, ipt.m_pt.y);
	}
    }

    std::stack<int> s;
    for (int i = 0; i < clx_points.Count(); i++) {
	if (clx_points[i].m_dir == IntersectPoint::UNSET) {
	    continue;
	}
	if (s.empty()) {
	    s.push(i);
	    continue;
	}
	const IntersectPoint &p = clx_points[s.top()];
	const IntersectPoint &q = clx_points[i];

	if (loop_t_compare(&p, &q) > 0 || q.m_split_li < p.m_split_li) {
	    bu_log("stack error or sort failure.\n");
	    bu_log("s.top() = %d, i = %d\n", s.top(), i);
	    bu_log("p->m_split_li = %d, q->m_split_li = %d\n", p.m_split_li, q.m_split_li);
	    bu_log("p->m_loop_seg = %d, q->m_loop_seg = %d\n", p.m_loop_seg, q.m_loop_seg);
	    bu_log("p->m_seg_t = %g, q->m_seg_t = %g\n", p.m_seg_t, q.m_seg_t);
	    continue;
	}
	if (q.m_curve_pos - p.m_curve_pos == 1 &&
	    q.m_dir != IntersectPoint::IN_HIT &&
	    p.m_dir != IntersectPoint::OUT_HIT)
	{
	    s.pop();
	} else if (p.m_curve_pos - q.m_curve_pos == 1 &&
		   p.m_dir != IntersectPoint::IN_HIT &&
		   q.m_dir != IntersectPoint::OUT_HIT)
	{
	    s.pop();
	} else {
	    s.push(i);
	    continue;
	}

	// need to form a new loop
	ON_SimpleArray<ON_Curve *> newloop;
	int curve_count = q.m_split_li - p.m_split_li;
	for (int j = p.m_split_li + 1; j <= q.m_split_li; j++) {
	    // No need to duplicate the curve, because the pointer
	    // in the array 'outerloop_segs' will be moved out later.
	    newloop.Append(outerloop_segs[j]);
	}

	// The curves on the outer loop is from p to q, so the curves on the
	// SSI curve should be from q to p (to form a loop)
	double t1 = p.m_curve_t, t2 = q.m_curve_t;
	bool need_reverse = true;
	if (t1 > t2) {
	    std::swap(t1, t2);
	    need_reverse = false;
	}
	ON_SimpleArray<ON_Curve *> segments_on_SSI;
	if (!linked_curve.SubCurves(t1, t2, segments_on_SSI)) {
	    bu_log("sub_curve() failed.\n");
	    continue;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("split_face_into_loops: extracted %d pieces from %d linked "
		"SSI curves over %.17g -> %.17g.\n", segments_on_SSI.Count(),
		linked_curve.m_ssi_curves.Count(), t1, t2);
	}
	if (need_reverse) {
	    bool reversed = true;
	    for (int segment_index = 0;
		 segment_index < segments_on_SSI.Count(); ++segment_index)
	    {
		if (!segments_on_SSI[segment_index]->Reverse()) {
		    reversed = false;
		    break;
		}
	    }
	    if (!reversed) {
		bu_log("Reverse failed.\n");
		for (int segment_index = 0;
		     segment_index < segments_on_SSI.Count(); ++segment_index)
		{
		    delete segments_on_SSI[segment_index];
		}
		continue;
	    }
	    segments_on_SSI.Reverse();
	}

	ON_SimpleArray<ON_Curve *> reverse_segments_on_SSI;
	bool reverse_segments_valid = true;
	for (int segment_index = segments_on_SSI.Count() - 1;
	     segment_index >= 0; --segment_index)
	{
	    ON_Curve *reverse_segment =
		segments_on_SSI[segment_index]->Duplicate();
	    if (reverse_segment == NULL || !reverse_segment->Reverse()) {
		delete reverse_segment;
		reverse_segments_valid = false;
		break;
	    }
	    reverse_segments_on_SSI.Append(reverse_segment);
	}
	if (!reverse_segments_valid) {
	    bu_log("Reverse failed.\n");
	    for (int segment_index = 0;
		 segment_index < reverse_segments_on_SSI.Count(); ++segment_index)
	    {
		delete reverse_segments_on_SSI[segment_index];
	    }
	    for (int segment_index = 0;
		 segment_index < segments_on_SSI.Count(); ++segment_index)
	    {
		delete segments_on_SSI[segment_index];
	    }
	    continue;
	}

	newloop.Append(segments_on_SSI.Count(), segments_on_SSI.Array());
	if (DEBUG_BREP_BOOLEAN) {
	    for (int segment_index = 0; segment_index < newloop.Count();
		 ++segment_index)
	    {
		const ON_Curve *segment = newloop[segment_index];
		const ON_Curve *next = newloop[
		    (segment_index + 1) % newloop.Count()];
		if (segment == NULL || next == NULL)
		    continue;
		const ON_3dPoint start = segment->PointAtStart();
		const ON_3dPoint end = segment->PointAtEnd();
		const ON_3dPoint next_start = next->PointAtStart();
		bu_log("split_face_into_loops: pre-close loop curve %d "
		    "(%.17g, %.17g) -> (%.17g, %.17g), next gap %.17g.\n",
		    segment_index, start.x, start.y, end.x, end.y,
		    end.DistanceTo(next_start));
	    }
	}
	close_small_gaps(newloop, split_tolerance.point);

	// Replace the outer-loop path with the same SSI pieces in the opposite
	// direction.  Keeping each piece distinct preserves shared topology for
	// the face assembled on the other side of the intersection.
	ON_SimpleArray<ON_Curve *> updated_outerloop;
	for (int segment_index = 0; segment_index <= p.m_split_li;
	     ++segment_index)
	{
	    updated_outerloop.Append(outerloop_segs[segment_index]);
	}
	updated_outerloop.Append(reverse_segments_on_SSI.Count(),
	    reverse_segments_on_SSI.Array());
	for (int segment_index = q.m_split_li + 1;
	     segment_index < outerloop_segs.Count(); ++segment_index)
	{
	    updated_outerloop.Append(outerloop_segs[segment_index]);
	}
	outerloop_segs = updated_outerloop;

	const int split_index_delta = reverse_segments_on_SSI.Count() -
	    curve_count;
	for (int j = i + 1; j < clx_points.Count(); j++) {
	    clx_points[j].m_split_li += split_index_delta;
	}

	// append the new loop if it's valid
	if (is_loop_valid(newloop, ON_ZERO_TOLERANCE)) {
	    ON_SimpleArray<ON_Curve *> loop;
	    loop.Append(newloop.Count(), newloop.Array());
	    out.push_back(loop);
	} else {
	    for (int j = 0; j < newloop.Count(); j++) {
		delete newloop[j];
	    }
	}
    }

    // Remove the duplicated segments before the first intersection point.
    if (clx_points.Count()) {
	for (int i = 0; i <= clx_points[0].m_split_li; i++) {
	    delete outerloop_segs[0];
	    outerloop_segs[0] = NULL;
	    outerloop_segs.Remove(0);
	}
    }

    if (!out.empty()) {
	// The remaining part after splitting some parts out.
	close_small_gaps(outerloop_segs, split_tolerance.point);
	if (is_loop_valid(outerloop_segs, ON_ZERO_TOLERANCE)) {
	    ON_SimpleArray<ON_Curve *> loop;
	    loop.Append(outerloop_segs.Count(), outerloop_segs.Array());
	    out.push_back(loop);
	} else {
	    for (int i = 0; i < outerloop_segs.Count(); i++)
		if (outerloop_segs[i]) {
		    delete outerloop_segs[i];
		}
	}
    }
    return out;
}


void
free_loops(std::vector<ON_SimpleArray<ON_Curve *> > &loops)
{
    for (size_t i = 0; i < loops.size(); ++i) {
	for (int j = 0; j < loops[i].Count(); ++j) {
	    delete loops[i][j];
	    loops[i][j] = NULL;
	}
    }
}


// It might be worth investigating the following approach to building a set of faces from the splitting
// in order to achieve robustness in the final result:
//
// A) trim the raw SSI curves with the trimming loops from both faces and get "final" curve segments in
//    3D and both 2D parametric spaces.  Consolidate curves where different faces created the same curve.
// B) assemble the new 2D segments and whatever pieces are needed from the existing trimming curves to
//    form new 2D loops (which must be non-self-intersecting), whose roles in A and B respectively
//    would be determined by the boolean op and each face's role within it.
// C) build "representative polygons" for all the 2D loops in each face, new and old - representative in
//    this case meaning that the intersection behavior of the general loops is accurately duplicated
//    by the polygons, which should be assurable by identifying and using all 2D curve intersections and possibly
//    horizontal and vertical tangents - and use clipper to perform the boolean ops.  Using the resulting polygons,
//    deduce and assemble the final trimming loops (and face or faces) created from A and B respectively.

// Note that the 2D information alone cannot be enough to decide *which* faces created from these splits
// end up in the final brep.  A case to think about here is the case of two spheres intersecting -
// depending on A, the exact trimming
// loop in B may need to either define the small area as a new face, or everything BUT the small area
// as a new face - different A spheres may either almost fully contain B or just intersect it.  That case
// would seem to suggest that we do need some sort of inside/outside test, since B doesn't have enough
// information to determine which face is to be saved without consulting A.  Likewise, A may either save
// just the piece inside the loop or everything outside it, depending on B.  This is the same situation we
// were in with the original face sets.
//
// A possible improvement here might be to calculate the best fit plane of the intersection curve and rotate
// both the faces in question and A so that that plane is centered at the origin with the normal in z+.
// In that orientation, axis aligned bounding box tests can be made that will be as informative
// as possible, and may allow many inside/outside decisions to be made without an explicit raytrace.  Coplanar
// faces will have to be handled differently, but for convex cases there should be enough information to decide.
// Concave cases may require a raytrace, but there is one other possible approach - if, instead of using the
// whole brep and face bounding boxes we start with the bounding box of the intersection curve and construct
// the sub-box that 'slices' through the parent bbox to the furthest wall in the opposite direction from the
// surface normal, then see which of the two possible
// faces' bounding boxes removes the most volume from that box when subtracted, we may be able to decide
// (say, for a subtraction) which face is cutting deeper.  It's not clear to me yet if such an approach would
// work or would scale to complex cases, but it may be worth thinking about.
static ON_SimpleArray<TrimmedFace *>
split_trimmed_face(
    const TrimmedFace *orig_face,
    ON_ClassArray<LinkedCurve> &ssx_curves)
{
    ON_SimpleArray<TrimmedFace *> out;
    out.Append(orig_face->Duplicate());

    if (ssx_curves.Count() == 0) {
	// no curves, no splitting
	return out;
    }

    ON_Curve *face_outerloop = get_loop_curve(orig_face->m_outerloop);
    if (!face_outerloop->IsClosed()) {
	if (DEBUG_BREP_BOOLEAN && orig_face->m_face) {
	    const ON_Surface *surface = orig_face->m_face->SurfaceOf();
	    const ON_3dPoint start = face_outerloop->PointAtStart();
	    const ON_3dPoint end = face_outerloop->PointAtEnd();
	    const ON_3dPoint model_start = surface && start.IsValid() ?
		surface->PointAt(start.x, start.y) : ON_3dPoint::UnsetPoint;
	    const ON_3dPoint model_end = surface && end.IsValid() ?
		surface->PointAt(end.x, end.y) : ON_3dPoint::UnsetPoint;
	    bu_log("split_trimmed_face: source face %d outer loop is open, "
		"UV gap %.17g, model gap %.17g, curves %d.\n",
		orig_face->m_face->m_face_index, start.DistanceTo(end),
		model_start.DistanceTo(model_end), orig_face->m_outerloop.Count());
	}
	// need closed outerloop
	delete face_outerloop;
	return out;
    }
    delete face_outerloop;

    for (int i = 0; i < ssx_curves.Count(); ++i) {
	std::vector<ON_SimpleArray<ON_Curve *> > ssx_loops;
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_Curve *diagnostic_curve = ssx_curves[i].Curve();
	    const ON_3dPoint diagnostic_start = diagnostic_curve ?
		diagnostic_curve->PointAtStart() : ON_3dPoint::UnsetPoint;
	    const ON_3dPoint diagnostic_end = diagnostic_curve ?
		diagnostic_curve->PointAtEnd() : ON_3dPoint::UnsetPoint;
	    bu_log("split_trimmed_face: source face %d curve %d has %d "
		"segments, linked closed %d, curve closed %d, dimension %d, "
		"endpoints (%.17g, %.17g, %.17g) -> "
		"(%.17g, %.17g, %.17g).\n",
		orig_face && orig_face->m_face ?
		    orig_face->m_face->m_face_index : -1,
		i, ssx_curves[i].m_ssi_curves.Count(),
		ssx_curves[i].IsClosed(),
		diagnostic_curve ? diagnostic_curve->IsClosed() : 0,
		diagnostic_curve ? diagnostic_curve->Dimension() : 0,
		diagnostic_start.x, diagnostic_start.y, diagnostic_start.z,
		diagnostic_end.x, diagnostic_end.y, diagnostic_end.z);
	    const ON_Surface *diagnostic_surface = orig_face && orig_face->m_face ?
		orig_face->m_face->SurfaceOf() : NULL;
	    for (int segment_index = 0;
		 segment_index < ssx_curves[i].m_ssi_curves.Count();
		 ++segment_index)
	    {
		const SSICurve &segment = ssx_curves[i].m_ssi_curves[segment_index];
		const ON_3dPoint segment_start = segment.m_curve ?
		    segment.m_curve->PointAtStart() : ON_3dPoint::UnsetPoint;
		const ON_3dPoint segment_end = segment.m_curve ?
		    segment.m_curve->PointAtEnd() : ON_3dPoint::UnsetPoint;
		bu_log("  segment %d source/peer %d/%d, closed %d, iso %d, "
		    "endpoints (%.17g, %.17g) -> (%.17g, %.17g).\n",
		    segment_index, segment.m_source_face_index,
		    segment.m_peer_face_index,
		    segment.m_curve ? segment.m_curve->IsClosed() : 0,
		    diagnostic_surface && segment.m_curve ?
			diagnostic_surface->IsIsoparametric(*segment.m_curve) : 0,
		    segment_start.x, segment_start.y, segment_end.x,
		    segment_end.y);
	    }
	}

	// get current ssx curve as closed loops
	if (ssx_curves[i].IsClosed()) {
	    ON_SimpleArray<ON_Curve *> loop;
	    ssx_curves[i].AppendCurvesToArray(loop);
	    ssx_loops.push_back(loop);
	} else {
	    ssx_loops = split_face_into_loops(orig_face, ssx_curves[i]);
	}

	// combine each intersection loop with the original face (or
	// the previous iteration of split faces) to create new split
	// faces
	ON_SimpleArray<TrimmedFace *> next_out;
	for (size_t j = 0; j < ssx_loops.size(); ++j) {
	    if (loop_is_degenerate(ssx_loops[j])) {
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("split_trimmed_face: source face %d curve %d loop %zu "
			"is degenerate.\n", orig_face && orig_face->m_face ?
			orig_face->m_face->m_face_index : -1, i, j);
		}
		continue;
	    }

	    for (int k = 0; k < out.Count(); ++k) {
		LoopBooleanResult intersect_loops, diff_loops;

		// get the portion of the face outerloop inside the
		// ssx loop
		intersect_loops = loop_boolean(out[k]->m_outerloop,
					       ssx_loops[j], BOOLEAN_INTERSECT,
		    boolean_loop_tolerance_for_surface(orig_face->m_face ?
		orig_face->m_face->SurfaceOf() : NULL, out[k]->m_outerloop,
			ssx_loops[j]));

		if (ssx_curves[i].IsClosed()) {
		    if (intersect_loops.outerloops.empty()) {
			// no intersection, just keep the face as-is
			next_out.Append(out[k]->Duplicate());
			continue;
		    }

		    // for a naturally closed ssx curve, we also need
		    // the portion outside the loop
		    diff_loops = loop_boolean(out[k]->m_outerloop, ssx_loops[j],
					      BOOLEAN_DIFF,
			boolean_loop_tolerance_for_surface(orig_face->m_face ?
			    orig_face->m_face->SurfaceOf() : NULL,
			    out[k]->m_outerloop, ssx_loops[j]));

		    append_faces_from_loops(next_out, out[k], diff_loops);
		    diff_loops.ClearInnerloops();
		}
		append_faces_from_loops(next_out, out[k], intersect_loops);
		intersect_loops.ClearInnerloops();
	    }
	}
	free_loops(ssx_loops);

	if (next_out.Count() > 0) {
	    // replace previous faces with the new ones
	    for (int j = 0; j < out.Count(); ++j) {
		delete out[j];
	    }
	    out.Empty();

	    out.Append(next_out.Count(), next_out.Array());
	}
    }

    for (int i = 0; i < out.Count(); ++i) {
	close_small_gaps(out[i]->m_outerloop);
	for (size_t j = 0; j < out[i]->m_innerloop.size(); ++j) {
	    close_small_gaps(out[i]->m_innerloop[j]);
	}
    }

    // Curve dumps can contain tens of thousands of control points.  Keep the
    // structural diagnostics above enabled without making routine DEBUG runs
    // I/O-bound.
    if (DEBUG_BREP_BOOLEAN > 1) {
	bu_log("Split to %d faces.\n", out.Count());
	for (int i = 0; i < out.Count(); i++) {
	    bu_log("Trimmed Face %d:\n", i);
	    bu_log("outerloop:\n");
	    ON_wString wstr;
	    ON_TextLog textlog(wstr);
	    textlog.PushIndent();
	    for (int j = 0; j < out[i]->m_outerloop.Count(); j++) {
		textlog.Print("Curve %d\n", j);
		out[i]->m_outerloop[j]->Dump(textlog);
	    }
	    if (ON_String(wstr).Array()) {
		bu_log("%s", ON_String(wstr).Array());
	    }

	    for (unsigned int j = 0; j < out[i]->m_innerloop.size(); j++) {
		bu_log("innerloop %d:\n", j);
		ON_wString wstr2;
		ON_TextLog textlog2(wstr2);
		textlog2.PushIndent();
		for (int k = 0; k < out[i]->m_innerloop[j].Count(); k++) {
		    textlog2.Print("Curve %d\n", k);
		    out[i]->m_innerloop[j][k]->Dump(textlog2);
		}
		if (ON_String(wstr2).Array()) {
		    bu_log("%s", ON_String(wstr2).Array());
		}
	    }
	}
    }
    return out;
}


static bool
cylinders_have_same_locus(const ON_Surface *first_surface,
	const ON_Surface *second_surface, double tolerance)
{
    if (first_surface == NULL || second_surface == NULL ||
	!(tolerance > 0.0) || !std::isfinite(tolerance))
    {
	return false;
    }

    ON_Cylinder first;
    ON_Cylinder second;
    if (!first_surface->IsCylinder(&first, tolerance) ||
	!second_surface->IsCylinder(&second, tolerance) ||
	!first.IsValid() || !second.IsValid() ||
	fabs(first.circle.radius - second.circle.radius) > tolerance)
    {
	return false;
    }

    ON_3dVector first_axis = first.Axis();
    ON_3dVector second_axis = second.Axis();
    if (!first_axis.Unitize() || !second_axis.Unitize() ||
	first_axis.IsParallelTo(second_axis, ON_ZERO_TOLERANCE) == 0)
    {
	return false;
    }

    const ON_3dVector center_offset = second.Center() - first.Center();
    const ON_3dVector axis_offset = first_axis *
	ON_DotProduct(center_offset, first_axis);
    return (center_offset - axis_offset).Length() <= tolerance;
}


static bool
cones_have_same_locus(const ON_Surface *first_surface,
	const ON_Surface *second_surface, double tolerance)
{
    if (first_surface == NULL || second_surface == NULL ||
	!(tolerance > 0.0) || !std::isfinite(tolerance))
    {
	return false;
    }

    ON_Cone first;
    ON_Cone second;
    if (!first_surface->IsCone(&first, tolerance) ||
	!second_surface->IsCone(&second, tolerance) ||
	!first.IsValid() || !second.IsValid() ||
	first.ApexPoint().DistanceTo(second.ApexPoint()) > tolerance ||
	fabs(first.AngleInRadians() - second.AngleInRadians()) > ANGLE_TOL)
    {
	return false;
    }

    ON_3dVector first_axis = first.Axis();
    ON_3dVector second_axis = second.Axis();
    return first_axis.Unitize() && second_axis.Unitize() &&
	first_axis.IsParallelTo(second_axis, ANGLE_TOL) != 0;
}


static bool
is_same_surface(const ON_Surface *surf1, const ON_Surface *surf2)
{
    // Approach: Get their NURBS forms, and compare their CVs.
    // If their CVs are all the same (location and weight), they are
    // regarded as the same surface.

    if (surf1 == NULL || surf2 == NULL) {
	return false;
    }
    /* NURBS control nets include the finite parameter domains.  Cylinders
     * with the same infinite locus but different trimmed heights therefore
     * need an analytic comparison; sending them to general SSI causes an
     * unbounded refinement of their two-dimensional overlap. */
    if (cylinders_have_same_locus(surf1, surf2, INTERSECTION_TOL) ||
	cones_have_same_locus(surf1, surf2, INTERSECTION_TOL))
    {
	return true;
    }
    /*
    // Deal with two planes, if that's what we have - in that case
    // the determination can be more general than the CV comparison
    ON_Plane surf1_plane, surf2_plane;
    if (surf1->IsPlanar(&surf1_plane) && surf2->IsPlanar(&surf2_plane)) {
    ON_3dVector surf1_normal = surf1_plane.Normal();
    ON_3dVector surf2_normal = surf2_plane.Normal();
    if (surf1_normal.IsParallelTo(surf2_normal) == 1) {
    if (surf1_plane.DistanceTo(surf2_plane.Origin()) < ON_ZERO_TOLERANCE) {
    return true;
    } else {
    return false;
    }
    } else {
    return false;
    }
    }
    */

    ON_NurbsSurface nurbs_surf1, nurbs_surf2;
    if (!surf1->GetNurbForm(nurbs_surf1) || !surf2->GetNurbForm(nurbs_surf2)) {
	return false;
    }

    if (nurbs_surf1.Degree(0) != nurbs_surf2.Degree(0)
	|| nurbs_surf1.Degree(1) != nurbs_surf2.Degree(1)) {
	return false;
    }

    if (nurbs_surf1.CVCount(0) != nurbs_surf2.CVCount(0)
	|| nurbs_surf1.CVCount(1) != nurbs_surf2.CVCount(1)) {
	return false;
    }

    for (int i = 0; i < nurbs_surf1.CVCount(0); i++) {
	for (int j = 0; j < nurbs_surf2.CVCount(1); j++) {
	    ON_4dPoint cvA, cvB;
	    nurbs_surf1.GetCV(i, j, cvA);
	    nurbs_surf2.GetCV(i, j, cvB);
	    if (cvA != cvB) {
		return false;
	    }
	}
    }

    if (nurbs_surf1.KnotCount(0) != nurbs_surf2.KnotCount(0)
	|| nurbs_surf1.KnotCount(1) != nurbs_surf2.KnotCount(1)) {
	return false;
    }

    for (int i = 0; i < nurbs_surf1.KnotCount(0); i++) {
	if (!ON_NearZero(nurbs_surf1.m_knot[0][i] - nurbs_surf2.m_knot[0][i])) {
	    return false;
	}
    }

    for (int i = 0; i < nurbs_surf1.KnotCount(1); i++) {
	if (!ON_NearZero(nurbs_surf1.m_knot[1][i] - nurbs_surf2.m_knot[1][i])) {
	    return false;
	}
    }

    return true;
}


static bool
planar_surfaces_are_coplanar(
    const ON_Surface *first_surface,
    const ON_Surface *second_surface)
{
    if (first_surface == NULL || second_surface == NULL) {
	return false;
    }

    ON_Plane first_plane;
    ON_Plane second_plane;
    if (!first_surface->IsPlanar(&first_plane) ||
	!second_surface->IsPlanar(&second_plane) ||
	first_plane.Normal().IsParallelTo(second_plane.Normal(), ANGLE_TOL) == 0)
    {
	return false;
    }
    const ON_Interval first_u = first_surface->Domain(0);
    const ON_Interval first_v = first_surface->Domain(1);
    const ON_Interval second_u = second_surface->Domain(0);
    const ON_Interval second_v = second_surface->Domain(1);
    if (!first_u.IsIncreasing() || !first_v.IsIncreasing() ||
	!second_u.IsIncreasing() || !second_v.IsIncreasing())
    {
	return false;
    }

    const auto surface_within_plane = [](const ON_Surface *surface,
	const ON_Interval &u, const ON_Interval &v, const ON_Plane &plane) {
	for (int u_end = 0; u_end < 2; ++u_end) {
	    for (int v_end = 0; v_end < 2; ++v_end) {
		const ON_3dPoint point = surface->PointAt(
		    u_end == 0 ? u.Min() : u.Max(),
		    v_end == 0 ? v.Min() : v.Max());
		if (!point.IsValid() ||
		    fabs(plane.DistanceTo(point)) > INTERSECTION_TOL)
		{
		    return false;
		}
	    }
	}
	return true;
    };

    // Parallelism alone is insufficient for bounded faces: planes accepted
    // by the angular tolerance may separate by more than the point tolerance
    // across their domains, leaving a real sliver that must be intersected.
    return surface_within_plane(first_surface, first_u, first_v,
	second_plane) && surface_within_plane(second_surface, second_u,
	second_v, first_plane);
}


static bool
planar_surface_parameter_transform(
    const ON_Surface *source_surface,
    const ON_Surface *target_surface,
    ON_Xform &parameter_transform)
{
    if (source_surface == NULL || target_surface == NULL) {
	return false;
    }

    const ON_Interval source_u_domain = source_surface->Domain(0);
    const ON_Interval source_v_domain = source_surface->Domain(1);
    const ON_Interval target_u_domain = target_surface->Domain(0);
    const ON_Interval target_v_domain = target_surface->Domain(1);
    if (!source_u_domain.IsValid() || !source_v_domain.IsValid() ||
	!target_u_domain.IsValid() || !target_v_domain.IsValid())
    {
	return false;
    }

    const ON_2dPoint source_parameter(source_u_domain.Mid(),
	source_v_domain.Mid());
    const ON_2dPoint target_parameter(target_u_domain.Mid(),
	target_v_domain.Mid());
    ON_3dPoint source_point;
    ON_3dPoint target_point;
    ON_3dVector source_du;
    ON_3dVector source_dv;
    ON_3dVector target_du;
    ON_3dVector target_dv;
    if (!source_surface->Ev1Der(source_parameter.x, source_parameter.y,
	source_point, source_du, source_dv) ||
	!target_surface->Ev1Der(target_parameter.x, target_parameter.y,
	target_point, target_du, target_dv) || !source_point.IsValid() ||
	!target_point.IsValid())
    {
	return false;
    }

    const double target_uu = ON_DotProduct(target_du, target_du);
    const double target_uv = ON_DotProduct(target_du, target_dv);
    const double target_vv = ON_DotProduct(target_dv, target_dv);
    const double determinant = target_uu * target_vv - target_uv * target_uv;
    const double determinant_scale = target_uu * target_vv;
    if (!std::isfinite(determinant) || !std::isfinite(determinant_scale) ||
	determinant <= ON_EPSILON * determinant_scale)
    {
	return false;
    }

    const double source_u_target_u = ON_DotProduct(source_du, target_du);
    const double source_u_target_v = ON_DotProduct(source_du, target_dv);
    const double source_v_target_u = ON_DotProduct(source_dv, target_du);
    const double source_v_target_v = ON_DotProduct(source_dv, target_dv);
    const double transform_uu = (source_u_target_u * target_vv -
	source_u_target_v * target_uv) / determinant;
    const double transform_uv = (source_v_target_u * target_vv -
	source_v_target_v * target_uv) / determinant;
    const double transform_vu = (source_u_target_v * target_uu -
	source_u_target_u * target_uv) / determinant;
    const double transform_vv = (source_v_target_v * target_uu -
	source_v_target_u * target_uv) / determinant;

    const ON_3dVector reference_offset = source_point - target_point;
    const double offset_target_u = ON_DotProduct(reference_offset, target_du);
    const double offset_target_v = ON_DotProduct(reference_offset, target_dv);
    const double reference_u = (offset_target_u * target_vv -
	offset_target_v * target_uv) / determinant;
    const double reference_v = (offset_target_v * target_uu -
	offset_target_u * target_uv) / determinant;
    const double transform_u0 = target_parameter.x + reference_u - transform_uu *
	source_parameter.x - transform_uv * source_parameter.y;
    const double transform_v0 = target_parameter.y + reference_v - transform_vu *
	source_parameter.x - transform_vv * source_parameter.y;
    if (!std::isfinite(transform_uu) || !std::isfinite(transform_uv) ||
	!std::isfinite(transform_vu) || !std::isfinite(transform_vv) ||
	!std::isfinite(reference_u) || !std::isfinite(reference_v) ||
	!std::isfinite(transform_u0) || !std::isfinite(transform_v0))
    {
	return false;
    }

    parameter_transform = ON_Xform::IdentityTransformation;
    parameter_transform.m_xform[0][0] = transform_uu;
    parameter_transform.m_xform[0][1] = transform_uv;
    parameter_transform.m_xform[0][3] = transform_u0;
    parameter_transform.m_xform[1][0] = transform_vu;
    parameter_transform.m_xform[1][1] = transform_vv;
    parameter_transform.m_xform[1][3] = transform_v0;
    return true;
}


static bool
map_planar_parameter(
    const ON_Xform &parameter_transform,
    const ON_2dPoint &source_parameter,
    ON_2dPoint &target_parameter)
{
    if (!source_parameter.IsValid()) {
	return false;
    }

    target_parameter.x = parameter_transform.m_xform[0][0] *
	source_parameter.x + parameter_transform.m_xform[0][1] *
	source_parameter.y + parameter_transform.m_xform[0][3];
    target_parameter.y = parameter_transform.m_xform[1][0] *
	source_parameter.x + parameter_transform.m_xform[1][1] *
	source_parameter.y + parameter_transform.m_xform[1][3];
    return target_parameter.IsValid();
}


static bool
curves_have_matching_full_overlap(
    const ON_Curve *first_curve,
    const ON_Curve *second_curve)
{
    if (first_curve == NULL || second_curve == NULL) {
	return false;
    }

    if (!first_curve->IsLinear(INTERSECTION_TOL) ||
	!second_curve->IsLinear(INTERSECTION_TOL))
    {
	return false;
    }

    const ON_3dPoint first_start = first_curve->PointAtStart();
    const ON_3dPoint first_end = first_curve->PointAtEnd();
    const ON_3dPoint second_start = second_curve->PointAtStart();
    const ON_3dPoint second_end = second_curve->PointAtEnd();
    if (!first_start.IsValid() || !first_end.IsValid() ||
	!second_start.IsValid() || !second_end.IsValid())
    {
	return false;
    }

    const bool same_direction =
	first_start.DistanceTo(second_start) <= INTERSECTION_TOL &&
	first_end.DistanceTo(second_end) <= INTERSECTION_TOL;
    const bool opposite_direction =
	first_start.DistanceTo(second_end) <= INTERSECTION_TOL &&
	first_end.DistanceTo(second_start) <= INTERSECTION_TOL;
    return same_direction || opposite_direction;
}


static bool
brep_loops_have_matching_boundaries(
    const ON_BrepLoop &first_loop,
    const ON_BrepLoop &second_loop)
{
    if (first_loop.m_type != second_loop.m_type ||
	first_loop.m_type != ON_BrepLoop::outer &&
	first_loop.m_type != ON_BrepLoop::inner ||
	first_loop.TrimCount() != second_loop.TrimCount())
    {
	return false;
    }

    std::vector<bool> matched_second_trims(second_loop.TrimCount(), false);
    for (int first_index = 0;
	 first_index < first_loop.TrimCount();
	 ++first_index)
    {
	const ON_BrepTrim *first_trim = first_loop.Trim(first_index);
	if (first_trim == NULL || first_trim->m_type == ON_BrepTrim::singular) {
	    return false;
	}

	const ON_Curve *first_curve = first_trim->EdgeCurveOf();
	bool matched = false;
	for (int second_index = 0;
	     second_index < second_loop.TrimCount() && !matched;
	     ++second_index)
	{
	    if (matched_second_trims[second_index]) {
		continue;
	    }

	    const ON_BrepTrim *second_trim = second_loop.Trim(second_index);
	    if (second_trim == NULL || second_trim->m_type == ON_BrepTrim::singular ||
		!curves_have_matching_full_overlap(first_curve,
		    second_trim->EdgeCurveOf()))
	    {
		continue;
	    }

	    matched_second_trims[second_index] = true;
	    matched = true;
	}
	if (!matched) {
	    return false;
	}
    }

    return true;
}


static bool
brep_faces_have_matching_planar_boundaries(
    const ON_BrepFace &first_face,
    const ON_BrepFace &second_face)
{
    if (first_face.LoopCount() != second_face.LoopCount()) {
	return false;
    }

    std::vector<bool> matched_second_loops(second_face.LoopCount(), false);
    for (int first_index = 0;
	 first_index < first_face.LoopCount();
	 ++first_index)
    {
	const ON_BrepLoop *first_loop = first_face.Loop(first_index);
	if (first_loop == NULL) {
	    return false;
	}

	bool matched = false;
	for (int second_index = 0;
	     second_index < second_face.LoopCount() && !matched;
	     ++second_index)
	{
	    if (matched_second_loops[second_index]) {
		continue;
	    }

	    const ON_BrepLoop *second_loop = second_face.Loop(second_index);
	    if (second_loop == NULL ||
		!brep_loops_have_matching_boundaries(*first_loop, *second_loop))
	    {
		continue;
	    }

	    matched_second_loops[second_index] = true;
	    matched = true;
	}
	if (!matched) {
	    return false;
	}
    }

    return true;
}


static const ON_PolyCurve *
multi_segment_polycurve(const ON_Curve *curve)
{
    const ON_PolyCurve *polycurve = ON_PolyCurve::Cast(curve);
    if (polycurve == NULL || polycurve->Count() <= 1)
    {
	return NULL;
    }

    return polycurve;
}


static bool
is_singular_boolean_trim_curve(
    const ON_Surface &surface,
    const ON_Curve &parameter_curve,
    const ON_Curve &curve,
    ON_Surface::ISO &iso)
{
    iso = surface.IsIsoparametric(parameter_curve);
    if (curve.IsClosed() || (iso != ON_Surface::S_iso &&
	iso != ON_Surface::E_iso && iso != ON_Surface::N_iso &&
	iso != ON_Surface::W_iso))
    {
	return false;
    }

    const ON_BoundingBox bounds = curve.BoundingBox();
    const double roundoff_tolerance =
	boolean_coordinate_roundoff_tolerance(bounds);
    return roundoff_tolerance > 0.0 &&
	bounds.Diagonal().Length() <= roundoff_tolerance;
}


static ON_Curve *
boolean_surface_parameter_curve(const ON_Curve &curve)
{
    if (curve.Dimension() == 2) {
	return curve.Duplicate();
    }
    if (curve.Dimension() != 3) {
	return NULL;
    }

    ON_NurbsCurve parameter_curve;
    if (curve.GetNurbForm(parameter_curve) != 1 ||
	parameter_curve.Dimension() != 3)
    {
	return NULL;
    }

    for (int control_vertex_index = 0;
	 control_vertex_index < parameter_curve.CVCount();
	 ++control_vertex_index)
    {
	ON_4dPoint control_vertex;
	if (!parameter_curve.GetCV(control_vertex_index, control_vertex) ||
	    !ON_NearZero(control_vertex.z, ON_ZERO_TOLERANCE))
	{
	    return NULL;
	}
    }

    if (!parameter_curve.ChangeDimension(2)) {
	return NULL;
    }

    return new ON_NurbsCurve(parameter_curve);
}


static ON_Curve *
pushup_affine_boolean_curve(
    const ON_Surface *surface,
    const ON_Curve &curve)
{
    if (curve.Dimension() != 2) {
	return NULL;
    }

    AffinePlanarSurface affine_surface;
    /* Evaluation of a truly affine surface at very large model coordinates
     * can leave its four corners a few ulps short of exact parallelogram
     * closure.  That is representation roundoff, not surface curvature.  Use
     * the Boolean coordinate floor here while the SSI recognizers retain the
     * affine helper's strict default. */
    const double closure_tolerance =
	boolean_coordinate_roundoff_tolerance(surface->BoundingBox());
    if (!(closure_tolerance > 0.0) ||
	!affine_planar_surface_mapping(surface, affine_surface,
	    closure_tolerance))
    {
	return NULL;
    }

    ON_NurbsCurve lifted_curve;
    if (curve.GetNurbForm(lifted_curve) <= 0 ||
	!lifted_curve.ChangeDimension(3))
    {
	return NULL;
    }

    for (int control_vertex_index = 0;
	 control_vertex_index < lifted_curve.CVCount();
	 ++control_vertex_index)
    {
	ON_4dPoint parameter_vertex;
	if (!lifted_curve.GetCV(control_vertex_index, parameter_vertex) ||
	    !std::isfinite(parameter_vertex.w) ||
	    fabs(parameter_vertex.w) <= ON_ZERO_TOLERANCE)
	{
	    return NULL;
	}

	const ON_3dPoint point = surface->PointAt(
	    parameter_vertex.x / parameter_vertex.w,
	    parameter_vertex.y / parameter_vertex.w);
	if (!point.IsValid() || !lifted_curve.SetCV(control_vertex_index,
		ON_4dPoint(point.x * parameter_vertex.w,
		point.y * parameter_vertex.w, point.z * parameter_vertex.w,
		parameter_vertex.w)))
	{
	    return NULL;
	}
    }

    return lifted_curve.IsValid() ? new ON_NurbsCurve(lifted_curve) : NULL;
}


static ON_Curve *
pushup_boolean_polyline_curve(
    const ON_Surface *surface,
    const ON_Curve &curve)
{
    const ON_PolylineCurve *polyline = ON_PolylineCurve::Cast(&curve);
    if (surface == NULL || polyline == NULL || curve.Dimension() != 2 ||
	polyline->m_pline.Count() < 2 ||
	polyline->m_t.Count() != polyline->m_pline.Count())
    {
	return NULL;
    }

    ON_3dPointArray points;
    points.Reserve(polyline->m_pline.Count());
    for (int point_index = 0; point_index < polyline->m_pline.Count();
	 ++point_index)
    {
	const ON_3dPoint &parameter_point = polyline->m_pline[point_index];
	const ON_3dPoint model_point = surface->PointAt(parameter_point.x,
	    parameter_point.y);
	if (!parameter_point.IsValid() || !model_point.IsValid())
	    return NULL;
	points.Append(model_point);
    }

    static const double fractions[3] = {0.25, 0.5, 0.75};
    for (int point_index = 1; point_index < points.Count(); ++point_index) {
	const double first_parameter = polyline->m_t[point_index - 1];
	const double second_parameter = polyline->m_t[point_index];
	for (int sample_index = 0; sample_index < 3; ++sample_index) {
	    const double fraction = fractions[sample_index];
	    const double parameter = (1.0 - fraction) * first_parameter +
		fraction * second_parameter;
	    const ON_3dPoint uv = curve.PointAt(parameter);
	    const ON_3dPoint surface_point = surface->PointAt(uv.x, uv.y);
	    const ON_3dPoint chord_point =
		(1.0 - fraction) * points[point_index - 1] +
		fraction * points[point_index];
	    if (!uv.IsValid() || !surface_point.IsValid() ||
		!chord_point.IsValid() ||
		surface_point.DistanceTo(chord_point) > INTERSECTION_TOL)
	    {
		return NULL;
	    }
	}
    }

    ON_PolylineCurve *lifted = new ON_PolylineCurve(points, polyline->m_t);
    if (!lifted->IsValid()) {
	delete lifted;
	return NULL;
    }
    return lifted;
}


static ON_Curve *
pushup_boolean_curve(const ON_Surface *surface, const ON_Curve &curve)
{
    if (surface == NULL) {
	return NULL;
    }

    std::unique_ptr<ON_Curve> parameter_curve(
	boolean_surface_parameter_curve(curve));
    if (!parameter_curve) {
	return NULL;
    }

    /* An affine planar surface maps every parameter-space NURBS control
     * vertex exactly into model space.  Prefer that construction to the
     * general pushup fitter: at very large coordinate scales the fitter can
     * return a formally valid curve with matching endpoints but a materially
     * displaced interior. */
    ON_Curve *lifted_curve = pushup_affine_boolean_curve(surface,
	*parameter_curve);
    if (lifted_curve != NULL) {
	return lifted_curve;
    }

    lifted_curve = pushup_boolean_polyline_curve(surface, *parameter_curve);
    if (lifted_curve != NULL) {
	return lifted_curve;
    }

    lifted_curve = ON_Surface_Pushup(surface, *parameter_curve,
	NULL);
    if (lifted_curve != NULL) {
	if (lifted_curve->IsValid()) {
	    return lifted_curve;
	}

	ON_NurbsCurve lifted_nurbs;
	const int nurbs_form = lifted_curve->GetNurbForm(lifted_nurbs);
	delete lifted_curve;
	if (nurbs_form > 0 && lifted_nurbs.IsValid()) {
	    return new ON_NurbsCurve(lifted_nurbs);
	}
    }
    return NULL;
}


static bool
append_shared_open_ssi_curve(
    ON_ClassArray<SharedSSICurve> &shared_curves,
    int first_source_face,
    int second_source_face,
    const ON_BrepFace &first_face,
    const ON_BrepFace &second_face,
    const ON_Curve &model_subcurve,
    const ON_Curve &first_subcurve,
    const ON_Curve &second_subcurve)
{
    if (first_source_face < 0 || second_source_face < 0 ||
	first_source_face == second_source_face)
    {
	bu_log("Unable to record shared open SSI for invalid faces %d/%d.\n",
	    first_source_face, second_source_face);
	return false;
    }

    const ON_Surface *first_surface = first_face.SurfaceOf();
    const ON_Surface *second_surface = second_face.SurfaceOf();
    if (first_surface == NULL || second_surface == NULL) {
	bu_log("Unable to record shared open SSI faces %d/%d: missing "
	    "surface.\n", first_source_face, second_source_face);
	return false;
    }

    std::unique_ptr<ON_Curve> model_curve(model_subcurve.Duplicate());
    if (!model_curve || model_curve->Dimension() != 3 ||
	model_curve->IsClosed() || !model_curve->Domain().IsIncreasing() ||
	!model_curve->IsValid())
    {
	bu_log("Unable to record shared open SSI faces %d/%d: invalid model "
	    "subcurve.\n", first_source_face, second_source_face);
	return false;
    }

    std::unique_ptr<ON_Curve> first_parameter_curve(
	boolean_surface_parameter_curve(first_subcurve));
    std::unique_ptr<ON_Curve> second_parameter_curve(
	boolean_surface_parameter_curve(second_subcurve));
    if (!first_parameter_curve || !second_parameter_curve) {
	bu_log("Unable to record shared open SSI faces %d/%d: invalid "
	    "parameter curve.\n", first_source_face, second_source_face);
	return false;
    }

    shared_curves.Append(SharedSSICurve(first_source_face,
	second_source_face, model_curve.release(),
	first_parameter_curve.release(), second_parameter_curve.release()));
    const SharedSSICurve &recorded = *shared_curves.Last();
    const ON_3dPoint first_start = recorded.m_parameter_curve[0]->PointAtStart();
    const ON_3dPoint first_end = recorded.m_parameter_curve[0]->PointAtEnd();
    const ON_3dPoint second_start = recorded.m_parameter_curve[1]->PointAtStart();
    const ON_3dPoint second_end = recorded.m_parameter_curve[1]->PointAtEnd();
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Recorded shared open SSI %d for faces %d/%d, UV0 %.17g "
		"%.17g -> %.17g %.17g, UV1 %.17g %.17g -> %.17g %.17g.\n",
		shared_curves.Count() - 1, first_source_face, second_source_face,
		first_start.x, first_start.y, first_end.x, first_end.y,
		second_start.x, second_start.y, second_end.x, second_end.y);
    }
    return true;
}


struct SharedSSICurveMatch {
    int m_curve_index;
    bool m_reversed;

    SharedSSICurveMatch()
	: m_curve_index(-1),
	  m_reversed(false)
	{}

    bool
    IsSet() const
    {
	return m_curve_index >= 0;
    }
};


struct SharedSSIEndpointVertex {
    int m_curve_index;
    int m_endpoint_index;
    int m_vertex_index;

    SharedSSIEndpointVertex(int curve_index, int endpoint_index)
	: m_curve_index(curve_index),
	  m_endpoint_index(endpoint_index),
	  m_vertex_index(-1)
	{}
};


struct SharedSSIOutputEdge {
    int m_curve_index;
    int m_source_face_index;
    int m_edge_index;

    SharedSSIOutputEdge(
	int curve_index,
	int source_face_index,
	int edge_index)
	: m_curve_index(curve_index),
	  m_source_face_index(source_face_index),
	  m_edge_index(edge_index)
	{}
};


class BooleanSharedTopology {
public:
    BooleanSharedTopology(const ON_ClassArray<SharedSSICurve> &shared_curves)
	: m_shared_curves(shared_curves)
    {
	for (int curve_index = 0; curve_index < m_shared_curves.Count();
	     ++curve_index)
	{
	    const SharedSSICurve &shared_curve = m_shared_curves[curve_index];
	    if (shared_curve.m_curve == NULL || shared_curve.m_curve->IsClosed()) {
		continue;
	    }
	    m_endpoint_vertices.push_back(SharedSSIEndpointVertex(curve_index,
		0));
	    m_endpoint_vertices.push_back(SharedSSIEndpointVertex(curve_index,
		1));
	}
    }

    bool
    IsSharedParameterCurve(
	const ON_BrepFace &face,
	int source_face_index,
	const ON_Curve &curve) const
    {
	SharedSSICurveMatch match;
	return FindSharedParameterCurve(face, source_face_index, curve, match);
    }

    bool
    FindSharedParameterCurve(
	const ON_BrepFace &face,
	int source_face_index,
	const ON_Curve &curve,
	SharedSSICurveMatch &match) const
    {
	match = SharedSSICurveMatch();
	const ON_Surface *surface = face.SurfaceOf();
	if (source_face_index < 0 || surface == NULL) {
	    return false;
	}

	double parameter_tolerance = 0.0;
	double curve_parameter_tolerance = 0.0;
	if (!get_face_boundary_curve_tolerances(surface, &curve,
		parameter_tolerance, curve_parameter_tolerance) ||
	    !(parameter_tolerance > 0.0) ||
	    !std::isfinite(parameter_tolerance))
	{
	    return false;
	}

	bool found = false;
	for (int curve_index = 0; curve_index < m_shared_curves.Count();
	     ++curve_index)
	{
	    const SharedSSICurve &shared_curve = m_shared_curves[curve_index];
	    if (shared_curve.m_curve == NULL || shared_curve.m_curve->IsClosed()) {
		continue;
	    }

	    int parameter_curve_index = -1;
	    if (shared_curve.m_face_index[0] == source_face_index) {
		parameter_curve_index = 0;
	    } else if (shared_curve.m_face_index[1] == source_face_index) {
		parameter_curve_index = 1;
	    }
	    if (parameter_curve_index < 0 ||
		shared_curve.m_parameter_curve[parameter_curve_index] == NULL)
	    {
		continue;
	    }

	    bool parameter_reversed = false;
	    const bool parameter_match =
		open_parameter_curve_orientation_from_shared_ssi(&curve,
		    shared_curve.m_parameter_curve[parameter_curve_index],
		    parameter_tolerance, parameter_reversed);
	    const double model_tolerance = boolean_model_repair_tolerance(
		shared_curve.m_curve->BoundingBox());
	    std::unique_ptr<ON_Curve> lifted_curve(
		pushup_boolean_curve(surface, curve));
	    bool model_reversed = false;
	    const bool model_match = lifted_curve && brep_curves_coincident(
		*lifted_curve, *shared_curve.m_curve, model_tolerance,
		&model_reversed);
	    if (!parameter_match && !model_match) {
		continue;
	    }

	    if (found) {
		match = SharedSSICurveMatch();
		return false;
	    }
	    match.m_curve_index = curve_index;
	    match.m_reversed = parameter_match ? parameter_reversed :
		model_reversed;
	    found = true;
	}

	return found;
    }

    ON_Curve *
    DuplicateSharedModelCurve(const SharedSSICurveMatch &match) const
    {
	if (!match.IsSet() || match.m_curve_index >= m_shared_curves.Count()) {
	    return NULL;
	}
	const SharedSSICurve &shared_curve =
	    m_shared_curves[match.m_curve_index];
	if (shared_curve.m_curve == NULL || shared_curve.m_curve->IsClosed() ||
	    shared_curve.m_curve->Dimension() != 3 ||
	    !shared_curve.m_curve->Domain().IsIncreasing())
	{
	    return NULL;
	}

	ON_Curve *curve = shared_curve.m_curve->Duplicate();
	if (curve == NULL || (match.m_reversed && !curve->Reverse()) ||
	    !curve->IsValid())
	{
	    delete curve;
	    return NULL;
	}
	return curve;
    }

    bool
    MergeVertices(
	ON_Brep *brep,
	int keep_vertex,
	int remove_vertex,
	double tolerance)
    {
	if (keep_vertex == remove_vertex) {
	    return true;
	}
	if (brep == NULL || keep_vertex < 0 ||
	    keep_vertex >= brep->m_V.Count() || remove_vertex < 0 ||
	    remove_vertex >= brep->m_V.Count() || !(tolerance > 0.0) ||
	    !std::isfinite(tolerance))
	{
	    return false;
	}

	ON_BrepVertex &keep = brep->m_V[keep_vertex];
	ON_BrepVertex &remove = brep->m_V[remove_vertex];
	if (keep.m_vertex_index != keep_vertex ||
	    remove.m_vertex_index != remove_vertex)
	{
	    return false;
	}
	const double separation = keep.Point().DistanceTo(remove.Point());
	if (!keep.Point().IsValid() || !remove.Point().IsValid() ||
	    !std::isfinite(separation) || separation > tolerance)
	{
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Boolean shared endpoint vertices %d/%d are separated "
		    "by %.17g (tolerance %.17g).\n", keep_vertex,
		    remove_vertex, separation, tolerance);
	    }
	    return false;
	}
	keep.m_tolerance = std::isfinite(keep.m_tolerance) &&
	    keep.m_tolerance >= 0.0 ?
	    std::max(keep.m_tolerance, separation) : separation;
	remove.m_tolerance = std::isfinite(remove.m_tolerance) &&
	    remove.m_tolerance >= 0.0 ?
	    std::max(remove.m_tolerance, separation) : separation;
	if (!brep->CombineCoincidentVertices(keep, remove)) {
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Unable to combine Boolean shared endpoint vertices "
		    "%d/%d separated by %.17g.\n", keep_vertex,
		    remove_vertex, separation);
	    }
	    return false;
	}
	for (size_t endpoint_index = 0;
	     endpoint_index < m_endpoint_vertices.size(); ++endpoint_index)
	{
	    if (m_endpoint_vertices[endpoint_index].m_vertex_index ==
		    remove_vertex)
	    {
		m_endpoint_vertices[endpoint_index].m_vertex_index = keep_vertex;
	    }
	}
	return true;
    }

    bool
    ResolveSharedEndpointVertex(
	ON_Brep *brep,
	int source_face_index,
	const ON_3dPoint &point,
	double tolerance,
	int continuity_vertex_index,
	int &vertex_index,
	bool &matched)
    {
	vertex_index = -1;
	matched = false;
	if (brep == NULL || source_face_index < 0 || !point.IsValid() ||
	    !(tolerance > 0.0) || !std::isfinite(tolerance))
	{
	    return true;
	}
	if (continuity_vertex_index < -1 ||
	    continuity_vertex_index >= brep->m_V.Count())
	{
	    return false;
	}
	std::vector<size_t> candidate_endpoints;
	size_t nearest_endpoint = std::numeric_limits<size_t>::max();
	double nearest_distance = std::numeric_limits<double>::infinity();
	for (size_t endpoint_array_index = 0;
	     endpoint_array_index < m_endpoint_vertices.size();
	     ++endpoint_array_index)
	{
	    const SharedSSIEndpointVertex &endpoint =
		m_endpoint_vertices[endpoint_array_index];
	    const SharedSSICurve &shared_curve =
		m_shared_curves[endpoint.m_curve_index];
	    if ((shared_curve.m_face_index[0] != source_face_index &&
		 shared_curve.m_face_index[1] != source_face_index) ||
		shared_curve.m_curve == NULL)
	    {
		continue;
	    }
	    const ON_3dPoint endpoint_point = shared_curve.m_curve->PointAt(
		endpoint.m_endpoint_index == 0 ?
		shared_curve.m_curve->Domain().Min() :
		shared_curve.m_curve->Domain().Max());
	    if (endpoint_point.IsValid()) {
		const double distance = endpoint_point.DistanceTo(point);
		if (distance <= tolerance) {
		    candidate_endpoints.push_back(endpoint_array_index);
		    if (distance < nearest_distance) {
			nearest_distance = distance;
			nearest_endpoint = endpoint_array_index;
		    }
		}
	    }
	}

	if (candidate_endpoints.empty() ||
	    nearest_endpoint == std::numeric_limits<size_t>::max())
	{
	    return true;
	}

	const SharedSSIEndpointVertex &nearest =
	    m_endpoint_vertices[nearest_endpoint];
	const SharedSSICurve &nearest_curve =
	    m_shared_curves[nearest.m_curve_index];
	const ON_3dPoint nearest_point = nearest_curve.m_curve->PointAt(
	    nearest.m_endpoint_index == 0 ? nearest_curve.m_curve->Domain().Min() :
	    nearest_curve.m_curve->Domain().Max());
	std::vector<size_t> matching_endpoints;
	for (size_t candidate_index = 0;
	     candidate_index < candidate_endpoints.size(); ++candidate_index)
	{
	    const size_t endpoint_array_index =
		candidate_endpoints[candidate_index];
	    const SharedSSIEndpointVertex &endpoint =
		m_endpoint_vertices[endpoint_array_index];
	    const SharedSSICurve &shared_curve =
		m_shared_curves[endpoint.m_curve_index];
	    const ON_3dPoint endpoint_point = shared_curve.m_curve->PointAt(
		endpoint.m_endpoint_index == 0 ?
		shared_curve.m_curve->Domain().Min() :
		shared_curve.m_curve->Domain().Max());
	    if (endpoint_point.DistanceTo(nearest_point) <= ON_ZERO_TOLERANCE) {
		matching_endpoints.push_back(endpoint_array_index);
	    }
	}
	matched = !matching_endpoints.empty();

	// The shared endpoint and both adjacent loop endpoints may each carry
	// intersection error.  Candidate selection stays at one intersection
	// tolerance; only a topologically proven loop junction receives the
	// additional two-endpoint allowance.
	const double continuity_tolerance = tolerance +
	    boolean_loop_closure_tolerance(tolerance);

	int shared_vertex_index = -1;
	for (size_t match_index = 0; match_index < matching_endpoints.size();
	     ++match_index)
	{
	    const int endpoint_vertex_index = m_endpoint_vertices[
		matching_endpoints[match_index]].m_vertex_index;
	    if (endpoint_vertex_index < 0) {
		continue;
	    }
	    if (endpoint_vertex_index >= brep->m_V.Count())
	    {
		return false;
	    }
	    if (shared_vertex_index < 0) {
		shared_vertex_index = endpoint_vertex_index;
	    } else if (shared_vertex_index != endpoint_vertex_index &&
		!MergeVertices(brep, shared_vertex_index, endpoint_vertex_index,
		    continuity_tolerance))
	    {
		return false;
	    }
	}
	vertex_index = shared_vertex_index;
	if (continuity_vertex_index >= 0) {
	    if (vertex_index >= 0 && vertex_index != continuity_vertex_index) {
		if (!MergeVertices(brep, vertex_index, continuity_vertex_index,
			continuity_tolerance)) {
		    return false;
		}
	    } else {
		vertex_index = continuity_vertex_index;
	    }
	}

	if (vertex_index < 0) {
	    for (int candidate_index = 0;
		 candidate_index < brep->m_V.Count(); ++candidate_index)
	    {
		if (brep->m_V[candidate_index].m_vertex_index != candidate_index) {
		    continue;
		}
		if (brep->m_V[candidate_index].Point().DistanceTo(point) >
		    ON_ZERO_TOLERANCE)
		{
		    continue;
		}
		if (vertex_index >= 0 && vertex_index != candidate_index) {
		    return false;
		}
		vertex_index = candidate_index;
	    }
	}

	if (vertex_index < 0) {
	    vertex_index = brep->m_V.Count();
	    brep->NewVertex(point, 0.0);
	}

	for (size_t match_index = 0; match_index < matching_endpoints.size();
	     ++match_index)
	{
	    SharedSSIEndpointVertex &endpoint = m_endpoint_vertices[
		matching_endpoints[match_index]];
	    endpoint.m_vertex_index = vertex_index;
	}

	return true;
    }

    bool
    ReuseSharedEdge(
	ON_Brep *brep,
	const SharedSSICurveMatch &match,
	int source_face_index,
	ON_BrepLoop &loop,
	ON_Curve *&parameter_curve,
	ON_Curve *&edge_curve,
	int start_vertex_index,
	int end_vertex_index,
	double vertex_tolerance,
	bool &reused)
    {
	reused = false;
	if (brep == NULL || !match.IsSet() || parameter_curve == NULL ||
	    edge_curve == NULL)
	{
	    return true;
	}
	if (start_vertex_index < 0 ||
	    start_vertex_index >= brep->m_V.Count() || end_vertex_index < 0 ||
	    end_vertex_index >= brep->m_V.Count() ||
	    !(vertex_tolerance > 0.0) || !std::isfinite(vertex_tolerance))
	{
	    return false;
	}

	std::vector<std::pair<int, bool> > candidate_edges;
	for (size_t output_edge_index = 0;
	     output_edge_index < m_output_edges.size(); ++output_edge_index)
	{
	    const SharedSSIOutputEdge &output_edge =
		m_output_edges[output_edge_index];
	    if (output_edge.m_curve_index != match.m_curve_index ||
		output_edge.m_source_face_index == source_face_index ||
		output_edge.m_edge_index < 0 ||
		output_edge.m_edge_index >= brep->m_E.Count())
	    {
		continue;
	    }

	    const ON_BrepEdge &existing_edge =
		brep->m_E[output_edge.m_edge_index];
	    if (existing_edge.TrimCount() != 1 || existing_edge.m_ti.Count() != 1 ||
		existing_edge.m_c3i < 0 ||
		existing_edge.m_c3i >= brep->m_C3.Count() ||
		brep->m_C3[existing_edge.m_c3i] == NULL)
	    {
		continue;
	    }

	    bool curve_reversed = false;
	    if (!open_curve_orientation_from_shared_ssi(edge_curve,
		brep->m_C3[existing_edge.m_c3i], curve_reversed))
	    {
		continue;
	    }
	    curve_reversed = curve_reversed != existing_edge.ProxyCurveIsReversed();
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Boolean shared curve %d source face %d candidate edge %d "
		    "vertices %d/%d, curve reversed %d, proxy reversed %d, "
		    "trim reversed %d.\n", match.m_curve_index,
		    source_face_index, output_edge.m_edge_index,
		    existing_edge.m_vi[0], existing_edge.m_vi[1],
		    curve_reversed != existing_edge.ProxyCurveIsReversed(),
		    existing_edge.ProxyCurveIsReversed(), curve_reversed);
	    }
	    candidate_edges.push_back(std::make_pair(output_edge.m_edge_index,
		curve_reversed));
	}

	if (candidate_edges.size() != 1) {
	    return true;
	}

	const int edge_index = candidate_edges[0].first;
	const int first_trim_index = brep->m_E[edge_index].m_ti[0];
	if (first_trim_index < 0 || first_trim_index >= brep->m_T.Count()) {
	    return false;
	}
	const bool trim_reversed = candidate_edges[0].second;
	const int shared_start_vertex = brep->m_E[edge_index].m_vi[
	    trim_reversed ? 1 : 0];
	const int shared_end_vertex = brep->m_E[edge_index].m_vi[
	    trim_reversed ? 0 : 1];
	/* Curve coincidence alone does not prove that independently assembled
	 * endpoint clusters can be collapsed.  Preserve both edges when either
	 * endpoint lies outside the merge tolerance; the transactional shared-SSI
	 * and source-edge repair passes can then evaluate the complete topology. */
	if (brep->m_V[shared_start_vertex].Point().DistanceTo(
		brep->m_V[start_vertex_index].Point()) > vertex_tolerance ||
	    brep->m_V[shared_end_vertex].Point().DistanceTo(
		brep->m_V[end_vertex_index].Point()) > vertex_tolerance)
	{
	    return true;
	}
	if (!MergeVertices(brep, shared_start_vertex, start_vertex_index,
		vertex_tolerance) ||
	    !MergeVertices(brep, shared_end_vertex, end_vertex_index,
		vertex_tolerance))
	{
	    return false;
	}
	const int trim_curve_index = brep->AddTrimCurve(parameter_curve);
	if (trim_curve_index < 0) {
	    return false;
	}
	parameter_curve = NULL;
	ON_BrepTrim &trim = brep->NewTrim(brep->m_E[edge_index],
	    trim_reversed, loop, trim_curve_index);
	if (trim.m_vi[0] != shared_start_vertex ||
	    trim.m_vi[1] != shared_end_vertex)
	{
	    return false;
	}
	trim.m_tolerance[0] = trim.m_tolerance[1] = MAX_FASTF;
	brep->m_T[first_trim_index].m_type = ON_BrepTrim::mated;
	trim.m_type = ON_BrepTrim::mated;
	delete edge_curve;
	edge_curve = NULL;
	reused = true;
	return true;
    }

    void
    RecordSharedEdge(
	const SharedSSICurveMatch &match,
	int source_face_index,
	int edge_index)
    {
	if (match.IsSet() && source_face_index >= 0 && edge_index >= 0) {
	    m_output_edges.push_back(SharedSSIOutputEdge(match.m_curve_index,
		source_face_index, edge_index));
	}
    }

    bool
    CanonicalizeSharedBoundaryVertices(
	ON_Brep *brep,
	std::vector<bool> &used_curves,
	std::string &detail) const
    {
	used_curves.assign((size_t)m_shared_curves.Count(), false);
	if (brep == NULL) {
	    detail = "shared-boundary proxy has no B-Rep";
	    return false;
	}

	std::map<int, ON_3dPoint> assignments;
	for (int curve_index = 0; curve_index < m_shared_curves.Count();
	     ++curve_index)
	{
	    const SharedSSICurve &shared_curve = m_shared_curves[curve_index];
	    bool curve_used = false;
	    for (size_t output_index = 0;
		 output_index < m_output_edges.size(); ++output_index)
	    {
		const SharedSSIOutputEdge &output = m_output_edges[output_index];
		if (output.m_curve_index != curve_index)
		    continue;
		curve_used = true;
		if (shared_curve.m_curve == NULL ||
		    shared_curve.m_curve->IsClosed() ||
		    output.m_edge_index < 0 ||
		    output.m_edge_index >= brep->m_E.Count())
		{
		    detail = "shared-boundary proxy has an invalid open SSI edge";
		    return false;
		}

		ON_BrepEdge &edge = brep->m_E[output.m_edge_index];
		if (edge.m_vi[0] < 0 || edge.m_vi[0] >= brep->m_V.Count() ||
		    edge.m_vi[1] < 0 || edge.m_vi[1] >= brep->m_V.Count() ||
		    edge.m_vi[0] == edge.m_vi[1])
		{
		    detail = "shared-boundary proxy has an invalid SSI endpoint";
		    return false;
		}

		const ON_3dPoint shared_start = shared_curve.m_curve->PointAtStart();
		const ON_3dPoint shared_end = shared_curve.m_curve->PointAtEnd();
		const ON_3dPoint edge_start = brep->m_V[edge.m_vi[0]].Point();
		const ON_3dPoint edge_end = brep->m_V[edge.m_vi[1]].Point();
		const double tolerance = boolean_model_repair_tolerance(
		    shared_curve.m_curve->BoundingBox());
		const double direct_start = edge_start.DistanceTo(shared_start);
		const double direct_end = edge_end.DistanceTo(shared_end);
		const double reverse_start = edge_start.DistanceTo(shared_end);
		const double reverse_end = edge_end.DistanceTo(shared_start);
		const bool direct = direct_start <= tolerance &&
		    direct_end <= tolerance;
		const bool reverse = reverse_start <= tolerance &&
		    reverse_end <= tolerance;
		if (!shared_start.IsValid() || !shared_end.IsValid() ||
		    !edge_start.IsValid() || !edge_end.IsValid() ||
		    !(tolerance > 0.0) || !std::isfinite(tolerance) ||
		    direct == reverse)
		{
		    detail = "shared-boundary proxy cannot orient an SSI edge uniquely";
		    return false;
		}

		const ON_3dPoint canonical[2] = {
		    direct ? shared_start : shared_end,
		    direct ? shared_end : shared_start
		};
		for (int endpoint = 0; endpoint < 2; ++endpoint) {
		    const int vertex_index = edge.m_vi[endpoint];
		    const std::map<int, ON_3dPoint>::const_iterator existing =
			assignments.find(vertex_index);
		    if (existing != assignments.end() &&
			existing->second.DistanceTo(canonical[endpoint]) > tolerance)
		    {
			detail = "shared-boundary proxy has conflicting SSI endpoints";
			return false;
		    }
		    if (existing == assignments.end())
			assignments[vertex_index] = canonical[endpoint];
		}
	    }
	    used_curves[(size_t)curve_index] = curve_used;
	}

	for (std::map<int, ON_3dPoint>::const_iterator assignment =
		 assignments.begin(); assignment != assignments.end(); ++assignment)
	{
	    ON_BrepVertex &vertex = brep->m_V[assignment->first];
	    const double displacement = vertex.Point().DistanceTo(
		assignment->second);
	    if (!std::isfinite(displacement)) {
		detail = "shared-boundary proxy has a non-finite SSI displacement";
		return false;
	    }
	    vertex.point = assignment->second;
	    vertex.m_tolerance = std::max(vertex.m_tolerance, displacement);
	    for (int edge_offset = 0; edge_offset < vertex.m_ei.Count();
		 ++edge_offset)
	    {
		const int edge_index = vertex.m_ei[edge_offset];
		if (edge_index >= 0 && edge_index < brep->m_E.Count()) {
		    brep->m_E[edge_index].m_tolerance = std::max(
			brep->m_E[edge_index].m_tolerance, displacement);
		}
	    }
	}
	return true;
    }

private:
    const ON_ClassArray<SharedSSICurve> &m_shared_curves;
    std::vector<SharedSSIEndpointVertex> m_endpoint_vertices;
    std::vector<SharedSSIOutputEdge> m_output_edges;
};


static int
find_or_add_boolean_vertex(ON_Brep *brep, const ON_3dPoint &point)
{
    if (brep == NULL || !point.IsValid()) {
	return -1;
    }

    for (int vertex_index = 0; vertex_index < brep->m_V.Count();
	 ++vertex_index)
	{
	    if (brep->m_V[vertex_index].m_vertex_index != vertex_index) {
		continue;
	    }
	    if (brep->m_V[vertex_index].Point().DistanceTo(point) <
	ON_ZERO_TOLERANCE)
	    {
	return vertex_index;
	    }
	}

    const int vertex_index = brep->m_V.Count();
    brep->NewVertex(point, 0.0);
    return vertex_index;
}


static bool
normalize_boolean_polyline(ON_Curve *&curve)
{
    ON_PolylineCurve *polyline = ON_PolylineCurve::Cast(curve);
    if (polyline == NULL) {
	return curve != NULL;
    }
    if (polyline->m_pline.Count() < 2 ||
	polyline->m_t.Count() != polyline->m_pline.Count())
    {
	return false;
    }

    ON_3dPointArray points(polyline->m_pline);
    ON_SimpleArray<double> parameters(polyline->m_t);
    bool changed = false;
    for (int point_index = 1; point_index < points.Count();) {
	if (!points[point_index - 1].IsCoincident(points[point_index])) {
	    ++point_index;
	    continue;
	}

	// Preserve both topological endpoints.  At a coincident terminal pair,
	// discard the penultimate refinement sample; otherwise retain the
	// earlier sample and its curve parameter.
	const int remove_index = point_index == points.Count() - 1 ?
	    point_index - 1 : point_index;
	points.Remove(remove_index);
	parameters.Remove(remove_index);
	point_index = std::max(1, remove_index);
	changed = true;
    }
    if (!changed) {
	return curve->IsValid();
    }
    if (points.Count() < 2 || parameters.Count() != points.Count()) {
	return false;
    }

    ON_PolylineCurve *normalized = new ON_PolylineCurve(points, parameters);
    if (!normalized->ChangeDimension(polyline->Dimension()) ||
	!normalized->IsValid())
    {
	delete normalized;
	return false;
    }

    delete curve;
    curve = normalized;
    return true;
}


static bool
boolean_output_loop_is_valid(
    const ON_SimpleArray<ON_Curve *> &loop,
    const ON_Surface *surface)
{
    if (surface == NULL) {
	return false;
    }

    const BooleanLoopTolerance metric_tolerance =
	boolean_loop_tolerance_for_surface(surface, loop, loop);
    const double closure_tolerance =
	boolean_loop_closure_tolerance(metric_tolerance.point);
    const double model_tolerance =
	boolean_model_repair_tolerance(surface->BoundingBox());
    if (!loop_requires_gap_normalization(loop, closure_tolerance, surface,
	    model_tolerance))
    {
	return is_loop_valid(loop, ON_ZERO_TOLERANCE);
    }

    /* add_elements() makes adjacent trims share topology vertices and records
     * their measured endpoint deviations.  Validate a connector-normalized
     * copy here: some large-coordinate NURBS trims cannot encode an adjusted
     * endpoint more accurately than one floating-point unit, even after a
     * tolerance edge has been collapsed. */
    NormalizedBooleanLoop normalized;
    return normalized.Initialize(loop, closure_tolerance, surface,
	model_tolerance);
}


static bool
collapse_boolean_output_tolerance_edges(
    ON_SimpleArray<ON_Curve *> &loop,
    const ON_Surface *surface)
{
    if (surface == NULL) {
	return false;
    }

    // A valid Boolean boundary may consist of one closed curve or two
    // complementary curves.  There is no removable edge in either case,
    // and rejecting the loop here breaks otherwise valid through-cuts and
    // periodic-face trims.
    if (loop.Count() < 3) {
	return boolean_output_loop_is_valid(loop, surface);
    }

    const double collapse_tolerance =
	boolean_loop_closure_tolerance(INTERSECTION_TOL);
    bool changed = true;
    while (changed && loop.Count() >= 3) {
	changed = false;
	for (int curve_index = loop.Count() - 1; curve_index >= 0;
	     --curve_index)
	{
	    ON_Curve *curve = loop[curve_index];
	    if (curve == NULL || curve->IsClosed()) {
		continue;
	    }

	std::unique_ptr<ON_Curve> model_curve(
	    pushup_boolean_curve(surface, *curve));
	ON_Surface::ISO iso = ON_Surface::not_iso;
	if (model_curve && is_singular_boolean_trim_curve(*surface, *curve,
		*model_curve, iso))
	{
	    continue;
	}
	/* Pushup fitting can fail on a short curve crossing the parameter seam
	 * of a closed surface.  Direct surface evaluation is still sufficient to
	 * prove that its complete model-space locus is a removable tolerance
	 * connector.  Do not apply that fallback to an actual singular surface
	 * side, which must remain as a singular trim. */
	if (!model_curve) {
	    iso = surface->IsIsoparametric(*curve);
	    int singular_side = -1;
	    switch (iso) {
		case ON_Surface::S_iso: singular_side = 0; break;
		case ON_Surface::E_iso: singular_side = 1; break;
		case ON_Surface::N_iso: singular_side = 2; break;
		case ON_Surface::W_iso: singular_side = 3; break;
		default: break;
	    }
	    if (singular_side >= 0 && surface->IsSingular(singular_side)) {
		continue;
	    }
	}
	    const ON_Interval parameter_domain = curve->Domain();
	    const ON_3dPoint parameter_start = curve->PointAtStart();
	    const ON_3dPoint model_start = surface->PointAt(parameter_start.x,
		parameter_start.y);
	    bool within_tolerance = parameter_domain.IsIncreasing() &&
		parameter_start.IsValid() && model_start.IsValid();
	    for (int sample = 1; sample <= 32 && within_tolerance; ++sample) {
		const ON_3dPoint parameter_point = curve->PointAt(
		    parameter_domain.ParameterAt(
			static_cast<double>(sample) / 32.0));
		const ON_3dPoint model_point = surface->PointAt(parameter_point.x,
		    parameter_point.y);
		within_tolerance = parameter_point.IsValid() &&
		    model_point.IsValid() && model_point.DistanceTo(model_start) <=
		    collapse_tolerance;
	    }
	    if (!within_tolerance) {
		continue;
	    }

	    const int previous_index = curve_index == 0 ? loop.Count() - 1 :
		curve_index - 1;
	    ON_Curve *previous = loop[previous_index];
	    const ON_3dPoint replacement_endpoint = curve->PointAtEnd();
	    if (previous == NULL || !replacement_endpoint.IsValid() ||
		!previous->SetEndPoint(replacement_endpoint) ||
		!previous->IsValid())
	    {
		return false;
	    }

	    delete curve;
	    loop.Remove(curve_index);
	    changed = true;
	    break;
	}
    }

    return boolean_output_loop_is_valid(loop, surface);
}


/* A tangential face contact can leave a closed parameter-space loop whose
 * complete image on the surface is only one model-space point.  Such a loop
 * has no boundary locus to assemble: making an ordinary edge for it creates
 * a one-trim naked edge.  Certify the complete lifted curve loci rather than
 * relying on endpoints or samples, since a legitimate one-curve circular
 * loop also has coincident endpoints. */
static bool
boolean_loop_is_model_point(
    const ON_Surface *surface,
    const ON_SimpleArray<ON_Curve *> &loop)
{
    if (surface == NULL || loop.Count() < 1) {
	return false;
    }

    const double proof_tolerance =
	boolean_coordinate_roundoff_tolerance(surface->BoundingBox());
    if (!(proof_tolerance > 0.0) || !std::isfinite(proof_tolerance)) {
	return false;
    }

    std::vector<std::unique_ptr<ON_Curve> > lifted_curves;
    lifted_curves.reserve(static_cast<size_t>(loop.Count()));
    ON_3dPoint center = ON_3dPoint::UnsetPoint;
    for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	if (loop[curve_index] == NULL) {
	    return false;
	}

	std::unique_ptr<ON_Curve> lifted(
	    pushup_boolean_curve(surface, *loop[curve_index]));
	if (!lifted || !lifted->IsValid()) {
	    return false;
	}
	if (lifted_curves.empty()) {
	    center = lifted->PointAtStart();
	    if (!center.IsValid()) {
		return false;
	    }
	}
	lifted_curves.push_back(std::move(lifted));
    }

    for (const std::unique_ptr<ON_Curve> &lifted : lifted_curves) {
	const bool within_ball = brep_curve_locus_within_ball(*lifted, center,
		proof_tolerance);
	if (DEBUG_BREP_BOOLEAN && loop.Count() == 1) {
	    const ON_Interval domain = lifted->Domain();
	    double maximum_sample_distance = 0.0;
	    bool samples_valid = domain.IsIncreasing();
	    for (int sample = 0; sample <= 64 && samples_valid; ++sample) {
		const ON_3dPoint point = lifted->PointAt(domain.ParameterAt(
		    static_cast<double>(sample) / 64.0));
		const double distance = point.DistanceTo(center);
		samples_valid = point.IsValid() && std::isfinite(distance);
		if (samples_valid) {
		    maximum_sample_distance = std::max(maximum_sample_distance,
			distance);
		}
	    }
	    const ON_BoundingBox lifted_bounds = lifted->BoundingBox();
	    bu_log("Boolean point-loop proof: tolerance %.17g, lifted dimension "
		"%d, closed %d, bounds valid %d, diagonal %.17g, endpoint "
		"distance %.17g, sampled maximum %.17g (valid %d), certified "
		"%d.\n", proof_tolerance, lifted->Dimension(),
		lifted->IsClosed(), lifted_bounds.IsValid(),
		lifted_bounds.IsValid() ? lifted_bounds.Diagonal().Length() :
		ON_UNSET_VALUE,
		lifted->PointAtEnd().DistanceTo(center),
		maximum_sample_distance, samples_valid, within_ball);
	}
	if (!within_ball)
	{
	    return false;
	}
    }
    return true;
}


static bool
add_elements(
	ON_Brep *brep,
	ON_BrepFace &face,
	ON_SimpleArray<ON_Curve *> &loop,
	ON_BrepLoop::TYPE loop_type,
	BooleanSharedTopology &shared_topology,
	int source_face_index)
{
    const ON_Surface *srf = face.SurfaceOf();
    if (brep == NULL || srf == NULL) {
	return false;
    }

    if (!loop.Count()) {
	return true;
    }

    /* Source trims and independently constructed Boolean trims can represent
     * the same parameter-space vertex with adjacent floating-point values.
     * This is especially common for planar faces translated to very large
     * model coordinates, where a one-ULP UV gap is already larger than
     * ON_ZERO_TOLERANCE.  Normalize only gaps admitted by the surface metric
     * and by the model-space repair tolerance before rejecting the loop as
     * discontinuous.  The following tolerance-edge pass removes the inserted
     * connector when its complete lifted locus is negligible. */
    const BooleanLoopTolerance output_loop_tolerance =
	boolean_loop_tolerance_for_surface(srf, loop, loop);
    const double output_closure_tolerance =
	boolean_loop_closure_tolerance(output_loop_tolerance.point);
    const double output_model_tolerance =
	boolean_model_repair_tolerance(srf->BoundingBox());
    if (loop_requires_gap_normalization(loop, output_closure_tolerance, srf,
	    output_model_tolerance))
    {
	close_small_gaps(loop, output_closure_tolerance, srf,
	    output_model_tolerance);
    }

    if (!collapse_boolean_output_tolerance_edges(loop, srf)) {
	return false;
    }

    for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	if (!normalize_boolean_polyline(loop[curve_index])) {
	    const ON_PolylineCurve *polyline =
		ON_PolylineCurve::Cast(loop[curve_index]);
	    bu_log("Unable to normalize Boolean curve %d on source face %d "
		"(polyline points %d, curve valid %d).\n", curve_index,
		source_face_index,
		polyline != NULL ? polyline->m_pline.Count() : -1,
		loop[curve_index] != NULL ? loop[curve_index]->IsValid() :
		false);
	    return false;
	}
    }

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean diagnostic assembling source face %d loop with %d "
	    "curves.\n", source_face_index, loop.Count());
	for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	    SharedSSICurveMatch diagnostic_match;
	    shared_topology.FindSharedParameterCurve(face, source_face_index,
		*loop[curve_index], diagnostic_match);
	    const ON_PolyCurve *diagnostic_polycurve =
		multi_segment_polycurve(loop[curve_index]);
	    std::unique_ptr<ON_Curve> diagnostic_model_curve(
		pushup_boolean_curve(srf, *loop[curve_index]));
	    const ON_3dPoint model_start = diagnostic_model_curve ?
		diagnostic_model_curve->PointAtStart() : ON_3dPoint::UnsetPoint;
	    const ON_3dPoint model_end = diagnostic_model_curve ?
		diagnostic_model_curve->PointAtEnd() : ON_3dPoint::UnsetPoint;
	    const ON_3dPoint parameter_start = loop[curve_index]->PointAtStart();
	    const ON_3dPoint parameter_end = loop[curve_index]->PointAtEnd();
	    const ON_PolylineCurve *diagnostic_polyline =
		ON_PolylineCurve::Cast(loop[curve_index]);
	    bu_log("  curve %d polysegments %d polyline points %d match %d/%d, "
		"UV %.17g %.17g -> %.17g %.17g, model %.17g %.17g %.17g "
		"-> %.17g %.17g %.17g.\n", curve_index,
		diagnostic_polycurve ? diagnostic_polycurve->Count() : 0,
		diagnostic_polyline ? diagnostic_polyline->m_pline.Count() : 0,
		diagnostic_match.m_curve_index, diagnostic_match.m_reversed,
		parameter_start.x,
		parameter_start.y, parameter_end.x, parameter_end.y, model_start.x,
		model_start.y, model_start.z, model_end.x, model_end.y,
		model_end.z);
	}
    }

    bool expand_polycurve = false;
	for (int k = 0; k < loop.Count(); ++k) {
	    if (loop[k] != NULL && multi_segment_polycurve(loop[k]) != NULL &&
		!shared_topology.IsSharedParameterCurve(face, source_face_index,
		    *loop[k]))
	    {
	    expand_polycurve = true;
	    break;
	}
    }
    if (expand_polycurve) {
	ON_SimpleArray<ON_Curve *> expanded_loop;
	bool copied = true;
	for (int k = 0; k < loop.Count() && copied; ++k) {
	    const ON_PolyCurve *polycurve =
		multi_segment_polycurve(loop[k]);
	    if (polycurve != NULL &&
		!shared_topology.IsSharedParameterCurve(face, source_face_index,
		*loop[k]))
	    {
		for (int segment_index = 0;
		     segment_index < polycurve->Count(); ++segment_index) {
		    const ON_Curve *segment =
			polycurve->SegmentCurve(segment_index);
		    ON_Curve *copy = segment != NULL ? segment->Duplicate() : NULL;
		    if (copy == NULL) {
			copied = false;
			break;
		    }
		    expanded_loop.Append(copy);
		}
	    } else {
		ON_Curve *copy = loop[k] != NULL ? loop[k]->Duplicate() : NULL;
		if (copy == NULL) {
		    copied = false;
		    break;
		}
		expanded_loop.Append(copy);
	    }
	}

	const bool added = copied && add_elements(brep, face, expanded_loop,
	    loop_type, shared_topology, source_face_index);
	for (int k = 0; k < expanded_loop.Count(); ++k) {
	    if (expanded_loop[k] != NULL) {
		delete expanded_loop[k];
		expanded_loop[k] = NULL;
	    }
	}
	return added;
    }

    ON_BrepLoop &breploop = brep->NewLoop(loop_type, face);
    const double seam_model_tolerance = output_model_tolerance;

    // Determine whether a segment should be a seam trim, according to the
    // requirements in ON_Brep::IsValid() (See opennurbs_brep.cpp)
    for (int k = 0; k < loop.Count(); k++) {
	SharedSSICurveMatch shared_curve_match;
	if (loop[k] != NULL) {
	    shared_topology.FindSharedParameterCurve(face, source_face_index,
		*loop[k], shared_curve_match);
	}
	bool bClosed[2];
	bClosed[0] = srf->IsClosed(0);
	bClosed[1] = srf->IsClosed(1);
	if (bClosed[0] || bClosed[1]) {
	    ON_Surface::ISO iso1, iso2, iso_type;
	    int endpt_index = -1;
	    iso1 = srf->IsIsoparametric(*loop[k]);
	    if (ON_Surface::E_iso == iso1 && bClosed[0]) {
		iso_type = ON_Surface::W_iso;
		endpt_index = 1;
	    } else if (ON_Surface::W_iso == iso1 && bClosed[0]) {
		iso_type = ON_Surface::E_iso;
		endpt_index = 1;
	    } else if (ON_Surface::S_iso == iso1 && bClosed[1]) {
		iso_type = ON_Surface::N_iso;
		endpt_index = 0;
	    } else if (ON_Surface::N_iso == iso1 && bClosed[1]) {
		iso_type = ON_Surface::S_iso;
		endpt_index = 0;
	    }
	    if (endpt_index != -1) {
		ON_Interval side_interval;
		const double side_tol = 1.0e-4;
		double s0, s1;
		bool seamed = false;
		side_interval.Set(loop[k]->PointAtStart()[endpt_index], loop[k]->PointAtEnd()[endpt_index]);
		if (((ON_Surface::N_iso == iso_type || ON_Surface::W_iso == iso_type) && side_interval.IsIncreasing())
		    || ((ON_Surface::S_iso == iso_type || ON_Surface::E_iso == iso_type) && side_interval.IsDecreasing())) {
		    for (int i = 0; i < breploop.m_ti.Count(); i++) {
			ON_BrepTrim &trim = brep->m_T[breploop.m_ti[i]];
			if (ON_BrepTrim::boundary != trim.m_type) {
			    continue;
			}
			iso2 = srf->IsIsoparametric(trim);
			if (iso2 != iso_type) {
			    continue;
			}
			s1 = side_interval.NormalizedParameterAt(trim.PointAtStart()[endpt_index]);
			if (fabs(s1 - 1.0) > side_tol) {
			    continue;
			}
			s0 = side_interval.NormalizedParameterAt(trim.PointAtEnd()[endpt_index]);
			if (fabs(s0) > side_tol) {
			    continue;
			}

			// Certify the periodic identification in model space.  SSI
			// pullbacks can put the two UV endpoints at slightly different
			// parameters along opposite sides of a seam even though they map
			// to the same Boolean vertex within the intersection tolerance.
			if (srf->PointAt(trim.PointAtStart().x, trim.PointAtStart().y).DistanceTo(
				srf->PointAt(loop[k]->PointAtEnd().x, loop[k]->PointAtEnd().y)) > seam_model_tolerance) {
			    continue;
			}

			if (srf->PointAt(trim.PointAtEnd().x, trim.PointAtEnd().y).DistanceTo(
				srf->PointAt(loop[k]->PointAtStart().x, loop[k]->PointAtStart().y)) > seam_model_tolerance) {
			    continue;
			}

			// We add another checking, which is not included in ON_Brep::IsValid()
			// - they should be iso boundaries of the surface.
			double s2 = srf->Domain(1 - endpt_index).NormalizedParameterAt(loop[k]->PointAtStart()[1 - endpt_index]);
			double s3 = srf->Domain(1 - endpt_index).NormalizedParameterAt(trim.PointAtStart()[1 - endpt_index]);
			if ((fabs(s2 - 1.0) < side_tol && fabs(s3) < side_tol) ||
			    (fabs(s2) < side_tol && fabs(s3 - 1.0) < side_tol)) {
			    // Find a trim that should share the same edge
			    const int shared_edge_index = trim.m_ei;
			    const bool seam_trim_reversed = !trim.m_bRev3d;
			    const int previous_trim_index = breploop.m_ti.Count() > 0 ?
				*breploop.m_ti.Last() : -1;
			    const int first_trim_index = breploop.m_ti.Count() > 0 ?
				breploop.m_ti[0] : -1;
			    int ti = brep->AddTrimCurve(loop[k]);
			    if (ti < 0) {
				return false;
			    }
			    loop[k] = NULL;
			    ON_BrepTrim &newtrim = brep->NewTrim(
				brep->m_E[shared_edge_index], seam_trim_reversed,
				breploop, ti);
			    const int new_trim_index = newtrim.m_trim_index;
			    // newtrim.m_type = ON_BrepTrim::seam;
			    newtrim.m_tolerance[0] = newtrim.m_tolerance[1] = MAX_FASTF;

			    /* The paired parameter curves prove the periodic
			     * identification, but their independently evaluated
			     * endpoints can differ within the model tolerance.  Make
			     * that identification topological as well so the reused
			     * edge remains connected to its adjacent loop trims. */
			    if (previous_trim_index < 0 ||
				previous_trim_index >= brep->m_T.Count() ||
				new_trim_index < 0 || new_trim_index >= brep->m_T.Count() ||
				!shared_topology.MergeVertices(brep,
				    brep->m_T[new_trim_index].m_vi[0],
				    brep->m_T[previous_trim_index].m_vi[1],
				    seam_model_tolerance))
			    {
				return false;
			    }
			    if (k == loop.Count() - 1 &&
				(first_trim_index < 0 ||
				 first_trim_index >= brep->m_T.Count() ||
				 !shared_topology.MergeVertices(brep,
				     brep->m_T[new_trim_index].m_vi[1],
				     brep->m_T[first_trim_index].m_vi[0],
				     seam_model_tolerance)))
			    {
				return false;
			    }
			    if (brep->m_T[new_trim_index].m_vi[0] !=
				    brep->m_T[previous_trim_index].m_vi[1] ||
				(k == loop.Count() - 1 &&
				 brep->m_T[new_trim_index].m_vi[1] !=
				     brep->m_T[first_trim_index].m_vi[0]))
			    {
				return false;
			    }
			    seamed = true;
			    break;
			}
		    }
		    if (seamed) {
			continue;
		    }
		}
	    }
	}

	/* A shared SSI record already owns the certified model-space curve.
	 * Re-pushing its parameter curve can fit the endpoints accurately while
	 * moving the interior far off the intersection locus on large or strongly
	 * scaled revolution surfaces.  Preserve the exact SSI triplet and orient
	 * its model curve according to the matched parameter-curve endpoints. */
	ON_Curve *c3d =
	    shared_topology.DuplicateSharedModelCurve(shared_curve_match);
	if (c3d == NULL) {
	    c3d = pushup_boolean_curve(face.SurfaceOf(), *(loop[k]));
	}
	if (c3d == NULL) {
	    ON_3dPointArray ptarray(101);
	    for (int l = 0; l <= 100; l++) {
		ON_3dPoint pt2d;
		pt2d = loop[k]->PointAt(loop[k]->Domain().ParameterAt(l / 100.0));
		ptarray.Append(face.SurfaceOf()->PointAt(pt2d.x, pt2d.y));
	    }
	    c3d = new ON_PolylineCurve(ptarray);
	}

	ON_Surface::ISO iso = ON_Surface::not_iso;
	if (is_singular_boolean_trim_curve(*srf, *loop[k], *c3d, iso)) {
	    // A singular trim must represent a collapsed parameter-surface side.
	    int i;
	    ON_3dPoint vtx = c3d->PointAtStart();
	    for (i = brep->m_V.Count() - 1; i >= 0; i--) {
		if (brep->m_V[i].Point().DistanceTo(vtx) < ON_ZERO_TOLERANCE) {
		    break;
		}
	    }
	    if (i < 0) {
		i = brep->m_V.Count();
		brep->NewVertex(c3d->PointAtStart(), 0.0);
	    }
	    int ti = brep->AddTrimCurve(loop[k]);
	    if (ti < 0) {
		return false;
	    }
	    loop[k] = NULL;
	    ON_BrepTrim &trim = brep->NewSingularTrim(brep->m_V[i], breploop, iso, ti);
	    trim.m_tolerance[0] = trim.m_tolerance[1] = MAX_FASTF;
	    delete c3d;
	    continue;
	}

	ON_2dPoint start = loop[k]->PointAtStart(), end = loop[k]->PointAtEnd();
	const ON_3dPoint start_vertex_point = srf->PointAt(start.x, start.y);
	const ON_3dPoint end_vertex_point = srf->PointAt(end.x, end.y);
	// Shared endpoint matching is performed in model space.  A UV tolerance
	// can be much larger on a strongly scaled surface and would collapse
	// distinct, nearby sliver vertices into one invalid nonclosed edge.
	const double shared_vertex_tolerance = INTERSECTION_TOL +
	    ON_ZERO_TOLERANCE;

	int start_idx = -1;
	bool start_is_shared = false;
	int continuity_vertex_index = -1;
	if (breploop.m_ti.Count() > 0) {
	    const int previous_trim_index = *breploop.m_ti.Last();
	    if (previous_trim_index < 0 ||
		previous_trim_index >= brep->m_T.Count())
	    {
		delete c3d;
		return false;
	    }
	    continuity_vertex_index = brep->m_T[previous_trim_index].m_vi[1];
	}
	if (!shared_topology.ResolveSharedEndpointVertex(brep, source_face_index,
		start_vertex_point, shared_vertex_tolerance,
		continuity_vertex_index, start_idx, start_is_shared))
	{
	    delete c3d;
	    return false;
	}
	if (!start_is_shared) {
	    start_idx = continuity_vertex_index >= 0 ? continuity_vertex_index :
		find_or_add_boolean_vertex(brep, start_vertex_point);
	}
	if (start_idx < 0) {
	    delete c3d;
	    return false;
	}

	int end_idx = start_idx;
	bool end_is_shared = c3d->IsClosed();
	if (!c3d->IsClosed()) {
	    int closure_vertex_index = -1;
	    if (k == loop.Count() - 1 && breploop.m_ti.Count() > 0) {
		const int first_trim_index = breploop.m_ti[0];
		if (first_trim_index < 0 || first_trim_index >= brep->m_T.Count()) {
		    delete c3d;
		    return false;
		}
		closure_vertex_index = brep->m_T[first_trim_index].m_vi[0];
	    }
	    if (!shared_topology.ResolveSharedEndpointVertex(brep,
		    source_face_index, end_vertex_point, shared_vertex_tolerance,
		    closure_vertex_index, end_idx, end_is_shared))
	    {
		delete c3d;
		return false;
	    }
	    if (!end_is_shared) {
		end_idx = closure_vertex_index >= 0 ? closure_vertex_index :
		    find_or_add_boolean_vertex(brep, end_vertex_point);
	    }
	    if (end_idx < 0) {
		delete c3d;
		return false;
	    }
	}

	SharedSSICurveMatch topology_curve_match;
	if (start_is_shared && end_is_shared) {
	    topology_curve_match = shared_curve_match;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean output trim %d source face %d shared curve %d/%d, "
		"vertices %d/%d (shared %d/%d).\n", k, source_face_index,
		topology_curve_match.m_curve_index,
		topology_curve_match.m_reversed, start_idx, end_idx,
		start_is_shared, end_is_shared);
	}
	bool reused_shared_edge = false;
	if (!shared_topology.ReuseSharedEdge(brep, topology_curve_match,
		source_face_index, breploop, loop[k], c3d, start_idx, end_idx,
		shared_vertex_tolerance +
		boolean_loop_closure_tolerance(shared_vertex_tolerance),
		reused_shared_edge))
	{
	    delete c3d;
	    return false;
	}
	if (reused_shared_edge) {
	    continue;
	}
	if (!c3d->IsClosed() && start_idx == end_idx) {
	    if (start_vertex_point.DistanceTo(end_vertex_point) <=
		    boolean_loop_closure_tolerance(INTERSECTION_TOL) &&
		breploop.m_ti.Count() > 0)
	    {
		const int previous_trim_index = *breploop.m_ti.Last();
		ON_BrepTrim &previous_trim = brep->m_T[previous_trim_index];
		ON_Curve *previous_parameter_curve = previous_trim.m_c2i >= 0 &&
		    previous_trim.m_c2i < brep->m_C2.Count() ?
		    brep->m_C2[previous_trim.m_c2i] : NULL;
		const ON_3dPoint replacement_endpoint = loop[k]->PointAtEnd();
		if (previous_parameter_curve == NULL ||
		    !replacement_endpoint.IsValid() ||
		    !previous_parameter_curve->SetEndPoint(
			replacement_endpoint) ||
		    !previous_parameter_curve->IsValid())
		{
		    delete c3d;
		    return false;
		}
		delete c3d;
		delete loop[k];
		loop[k] = NULL;
		continue;
	    }
	    bu_log("Boolean trim %d on source face %d maps a nonclosed edge "
		"to vertex %d (endpoint distance %.17g, shared endpoints %d/%d).\n",
		k, source_face_index, start_idx,
		start_vertex_point.DistanceTo(end_vertex_point),
		start_is_shared, end_is_shared);
	}

	brep->AddEdgeCurve(c3d);
	int ti = brep->AddTrimCurve(loop[k]);
	if (ti < 0) {
	    return false;
	}
	loop[k] = NULL;
	ON_BrepEdge &edge = brep->NewEdge(brep->m_V[start_idx], brep->m_V[end_idx],
					  brep->m_C3.Count() - 1, (const ON_Interval *)0, MAX_FASTF);
	ON_BrepTrim &trim = brep->NewTrim(edge, 0, breploop, ti);
	trim.m_tolerance[0] = trim.m_tolerance[1] = MAX_FASTF;
	shared_topology.RecordSharedEdge(topology_curve_match, source_face_index,
	    edge.m_edge_index);
    }

    return true;
}


enum {
    INDETERMINATE_BREP = -1,
    OUTSIDE_BREP,
    INSIDE_BREP,
    ON_BREP_SURFACE
};


enum {
    INDETERMINATE_FACE = -1,
    OUTSIDE_FACE,
    INSIDE_FACE,
    ON_FACE_BOUNDARY
};


enum {
    INDETERMINATE_RAY = -1,
    OUTSIDE_RAY,
    INSIDE_RAY
};


static const double POINT_CONTAINMENT_RAY_LENGTH_MULTIPLIER = 2.0;
static const int POINT_CONTAINMENT_MINIMUM_VALID_RAYS = 2;
static const int POINT_CONTAINMENT_MINIMUM_SUPERMAJORITY_RAYS = 6;
static const int POINT_CONTAINMENT_SUPERMAJORITY_RATIO = 3;


static int
point_face_location(const ON_2dPoint &pt, const ON_BrepFace &face, const ON_Brep *brep)
{
    if (brep == NULL || face.m_li.Count() == 0) {
	return INDETERMINATE_FACE;
    }

    const ON_Surface *surface = face.SurfaceOf();
    if (surface == NULL) {
	return INDETERMINATE_FACE;
    }

    bool have_outer_loop = false;
    bool have_parameter_tolerance = true;
    double parameter_tolerance = INTERSECTION_TOL;
    ON_SimpleArray<ON_Curve *> outer_loop;
    ON_ClassArray<ON_SimpleArray<ON_Curve *> > inner_loops;
    for (int i = 0; i < face.m_li.Count(); ++i) {
	int loop_index = face.m_li[i];
	if (loop_index < 0 || loop_index >= brep->m_L.Count()) {
	    return INDETERMINATE_FACE;
	}
	const ON_BrepLoop &loop = brep->m_L[loop_index];
	if (loop.m_type != ON_BrepLoop::outer && loop.m_type != ON_BrepLoop::inner) {
	    return INDETERMINATE_FACE;
	}

	ON_SimpleArray<ON_Curve *> loop_curves;
	for (int j = 0; j < loop.m_ti.Count(); ++j) {
	    int trim_index = loop.m_ti[j];
	    if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
		return INDETERMINATE_FACE;
	    }
	    const ON_BrepTrim &trim = brep->m_T[trim_index];
	    if (trim.m_c2i < 0 || trim.m_c2i >= brep->m_C2.Count() ||
		brep->m_C2[trim.m_c2i] == NULL)
	    {
		return INDETERMINATE_FACE;
	    }
	    ON_Curve *curve = brep->m_C2[trim.m_c2i];
	    loop_curves.Append(curve);
	    double curve_intersection_tolerance = 0.0;
	    double curve_parameter_tolerance = 0.0;
	    if (!get_face_boundary_curve_tolerances(surface, curve,
		    curve_intersection_tolerance, curve_parameter_tolerance))
	    {
		have_parameter_tolerance = false;
	    } else {
		parameter_tolerance = std::min(parameter_tolerance,
		    curve_intersection_tolerance);
	    }
	}
	if (loop_curves.Count() == 0) {
	    return INDETERMINATE_FACE;
	}

	if (loop.m_type == ON_BrepLoop::outer) {
	    if (have_outer_loop) {
		return INDETERMINATE_FACE;
	    }
	    have_outer_loop = true;
	    outer_loop = loop_curves;
	} else {
	    inner_loops.Append(loop_curves);
	}
    }

    if (!have_outer_loop) {
	return INDETERMINATE_FACE;
    }

    if (!have_parameter_tolerance || !(parameter_tolerance > 0.0) ||
	!std::isfinite(parameter_tolerance))
    {
	// Preserve the historical behavior when the surface metric is unavailable.
	parameter_tolerance = INTERSECTION_TOL;
    }

    try {
	if (is_point_on_loop(pt, outer_loop, parameter_tolerance)) {
	    return ON_FACE_BOUNDARY;
	}
	if (!is_point_inside_loop(pt, outer_loop, parameter_tolerance)) {
	    return OUTSIDE_FACE;
	}
	for (int i = 0; i < inner_loops.Count(); ++i) {
	    if (is_point_on_loop(pt, inner_loops[i], parameter_tolerance)) {
		return ON_FACE_BOUNDARY;
	    }
	    if (!is_point_outside_loop(pt, inner_loops[i],
		    parameter_tolerance))
	    {
		return OUTSIDE_FACE;
	    }
	}
    } catch (InvalidGeometry &) {
	return INDETERMINATE_FACE;
    }

    return INSIDE_FACE;
}


static bool
point_is_near_brep_face_boundary(const ON_3dPoint &point,
    const ON_BrepFace &face, const ON_Brep *brep)
{
    if (!point.IsValid() || brep == NULL) {
	return false;
    }

    for (int loop_offset = 0; loop_offset < face.m_li.Count(); ++loop_offset) {
	const int loop_index = face.m_li[loop_offset];
	if (loop_index < 0 || loop_index >= brep->m_L.Count()) {
	    return false;
	}
	const ON_BrepLoop &loop = brep->m_L[loop_index];
	for (int trim_offset = 0; trim_offset < loop.m_ti.Count(); ++trim_offset) {
	    const int trim_index = loop.m_ti[trim_offset];
	    if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
		return false;
	    }
	    const ON_BrepTrim &trim = brep->m_T[trim_index];
	    if (trim.m_ei < 0) {
		continue;
	    }
	    if (trim.m_ei >= brep->m_E.Count()) {
		return false;
	    }

	    ON_ClassArray<ON_PX_EVENT> events;
	    if (ON_Intersect(point, brep->m_E[trim.m_ei], events,
		    INTERSECTION_TOL))
	    {
		return true;
	    }
	}
    }

    return false;
}


static bool
planar_brep_boundary_bounding_box(const ON_Brep *brep, ON_BoundingBox &bbox)
{
    if (brep == NULL || brep->m_F.Count() == 0 || brep->m_E.Count() == 0) {
	return false;
    }

    // A planar face reaches each coordinate extremum on a trim boundary.
    // The union of edge bounds therefore contains the entire planar B-Rep.
    for (int face_index = 0; face_index < brep->m_F.Count(); ++face_index) {
	const ON_BrepFace &face = brep->m_F[face_index];
	const ON_Surface *surface = face.SurfaceOf();
	ON_Plane plane;
	if (surface == NULL || !surface->IsPlanar(&plane)) {
	    return false;
	}
	for (int loop_index = 0; loop_index < face.LoopCount(); ++loop_index) {
	    const ON_BrepLoop *loop = face.Loop(loop_index);
	    if (loop == NULL) {
		return false;
	    }
	    for (int trim_index = 0; trim_index < loop->TrimCount(); ++trim_index) {
		const ON_BrepTrim *trim = loop->Trim(trim_index);
		if (trim == NULL || trim->m_ei < 0 ||
		    trim->m_ei >= brep->m_E.Count())
		{
		    return false;
		}
	    }
	}
    }

    ON_BoundingBox boundary_bbox;
    bool have_bounds = false;
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	ON_3dPoint minimum;
	ON_3dPoint maximum;
	if (!brep->m_E[edge_index].GetBoundingBox(minimum, maximum, false)) {
	    return false;
	}
	const ON_BoundingBox edge_bbox(minimum, maximum);
	if (!edge_bbox.IsValid()) {
	    return false;
	}
	if (have_bounds) {
	    boundary_bbox.Union(edge_bbox);
	} else {
	    boundary_bbox = edge_bbox;
	    have_bounds = true;
	}
    }

    for (int vertex_index = 0; vertex_index < brep->m_V.Count(); ++vertex_index) {
	const ON_3dPoint vertex = brep->m_V[vertex_index].point;
	if (!vertex.IsValid()) {
	    return false;
	}
	boundary_bbox.Set(vertex, have_bounds);
	have_bounds = true;
    }

    if (!have_bounds || !boundary_bbox.IsValid()) {
	return false;
    }

    bbox = boundary_bbox;
    return true;
}


static bool
boolean_brep_bounding_box(const ON_Brep *brep, ON_BoundingBox &bbox)
{
    if (brep == NULL) {
	return false;
    }

    if (planar_brep_boundary_bounding_box(brep, bbox)) {
	return true;
    }

    if (brep_GetTrimmedBoundingBox(*brep, bbox, false) && bbox.IsValid()) {
	return true;
    }

    /* Preserve conservative classification when trimmed bounds are unavailable. */
    const ON_BoundingBox support_bbox = brep->BoundingBox();
    if (!support_bbox.IsValid()) {
	return false;
    }

    bbox = support_bbox;
    return true;
}


static bool
boolean_brep_component_bounding_boxes(
    const ON_Brep *brep,
    std::vector<ON_BoundingBox> &component_bboxes,
    std::vector<std::vector<int> > *component_face_indices = NULL)
{
    component_bboxes.clear();
    if (component_face_indices != NULL) {
	component_face_indices->clear();
    }
    if (brep == NULL || !brep->IsSolid()) {
	return false;
    }

    const int face_count = brep->m_F.Count();
    if (face_count <= 0) {
	return false;
    }

    std::vector<std::vector<int> > adjacent_faces(
	static_cast<size_t>(face_count));
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	const ON_BrepEdge &edge = brep->m_E[edge_index];
	std::vector<int> edge_face_indices;
	for (int trim_offset = 0; trim_offset < edge.m_ti.Count(); ++trim_offset) {
	    const int trim_index = edge.m_ti[trim_offset];
	    if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
		return false;
	    }
	    const int face_index = brep->m_T[trim_index].FaceIndexOf();
	    if (face_index < 0 || face_index >= face_count) {
		return false;
	    }
	    if (std::find(edge_face_indices.begin(), edge_face_indices.end(),
		    face_index) == edge_face_indices.end())
	    {
		edge_face_indices.push_back(face_index);
	    }
	}
	for (size_t first_index = 0;
	     first_index < edge_face_indices.size();
	     ++first_index)
	{
	    for (size_t second_index = first_index + 1;
		 second_index < edge_face_indices.size();
		 ++second_index)
	    {
		adjacent_faces[edge_face_indices[first_index]].push_back(
		    edge_face_indices[second_index]);
		adjacent_faces[edge_face_indices[second_index]].push_back(
		    edge_face_indices[first_index]);
	    }
	}
    }

    std::vector<bool> face_visited(static_cast<size_t>(face_count), false);
    for (int first_face_index = 0;
	 first_face_index < face_count;
	 ++first_face_index)
    {
	if (face_visited[first_face_index]) {
	    continue;
	}

	ON_BoundingBox component_bbox;
	bool have_component_bbox = false;
	std::vector<int> component_faces;
	std::queue<int> pending_faces;
	pending_faces.push(first_face_index);
	face_visited[first_face_index] = true;
	while (!pending_faces.empty()) {
	    const int face_index = pending_faces.front();
	    pending_faces.pop();
	    component_faces.push_back(face_index);

	    ON_BoundingBox face_bbox;
	    if (!face_GetBoundingBox(brep->m_F[face_index], face_bbox, false) ||
		!face_bbox.IsValid())
	    {
		return false;
	    }
	    if (have_component_bbox) {
		component_bbox.Union(face_bbox);
	    } else {
		component_bbox = face_bbox;
		have_component_bbox = true;
	    }

	    const std::vector<int> &neighbors = adjacent_faces[face_index];
	    for (size_t neighbor_index = 0;
		 neighbor_index < neighbors.size();
		 ++neighbor_index)
	    {
		const int neighbor_face_index = neighbors[neighbor_index];
		if (!face_visited[neighbor_face_index]) {
		    face_visited[neighbor_face_index] = true;
		    pending_faces.push(neighbor_face_index);
		}
	    }
	}

	if (!have_component_bbox || !component_bbox.IsValid()) {
	    return false;
	}
	component_bboxes.push_back(component_bbox);
	if (component_face_indices != NULL) {
	    component_face_indices->push_back(component_faces);
	}
    }

    return !component_bboxes.empty();
}


static bool
boolean_face_is_disjoint_from_component_bounds(
    const ON_BrepFace &face,
    const std::vector<ON_BoundingBox> &component_bboxes)
{
    ON_BoundingBox face_bbox;
    if (component_bboxes.empty() ||
	!face_GetBoundingBox(face, face_bbox, false) || !face_bbox.IsValid())
    {
	return false;
    }

    for (size_t component_index = 0;
	 component_index < component_bboxes.size();
	 ++component_index)
    {
	if (face_bbox.MinimumDistanceTo(component_bboxes[component_index]) <=
	    INTERSECTION_TOL)
	{
	    return false;
	}
    }

    return true;
}


static bool
boolean_component_bounds_are_separated(
    const std::vector<ON_BoundingBox> &first_component_bboxes,
    const std::vector<ON_BoundingBox> &second_component_bboxes)
{
    if (first_component_bboxes.empty() || second_component_bboxes.empty()) {
	return false;
    }

    for (size_t first_index = 0;
	 first_index < first_component_bboxes.size();
	 ++first_index)
    {
	for (size_t second_index = 0;
	     second_index < second_component_bboxes.size();
	     ++second_index)
	{
	    if (first_component_bboxes[first_index].MinimumDistanceTo(
		second_component_bboxes[second_index]) <= ON_ZERO_TOLERANCE)
	    {
		return false;
	    }
	}
    }

    return true;
}


static double
bounding_interval_roundoff(
    double first_min,
    double first_max,
    double second_min,
    double second_max)
{
    // This is a roundoff guard, not a geometric intersection tolerance.
    // One machine epsilon at the coordinate scale absorbs conversion noise.
    const double minimum_coordinate_scale = 1.0;
    double coordinate_scale = minimum_coordinate_scale;
    coordinate_scale = std::max(coordinate_scale, fabs(first_min));
    coordinate_scale = std::max(coordinate_scale, fabs(first_max));
    coordinate_scale = std::max(coordinate_scale, fabs(second_min));
    coordinate_scale = std::max(coordinate_scale, fabs(second_max));

    return ON_EPSILON * coordinate_scale;
}


static bool
bounding_intervals_have_disjoint_interiors(
    double first_min,
    double first_max,
    double second_min,
    double second_max)
{
    const double roundoff = bounding_interval_roundoff(first_min, first_max,
	second_min, second_max);

    return first_max <= second_min + roundoff ||
	second_max <= first_min + roundoff;
}


static bool
bounding_box_interiors_are_disjoint(
    const ON_BoundingBox &first,
    const ON_BoundingBox &second)
{
    return bounding_intervals_have_disjoint_interiors(first.m_min.x,
	first.m_max.x, second.m_min.x, second.m_max.x) ||
	bounding_intervals_have_disjoint_interiors(first.m_min.y,
	first.m_max.y, second.m_min.y, second.m_max.y) ||
	bounding_intervals_have_disjoint_interiors(first.m_min.z,
	first.m_max.z, second.m_min.z, second.m_max.z);
}


static bool
nondegenerate_bounding_intervals_have_disjoint_interiors(
    double first_min,
    double first_max,
    double second_min,
    double second_max)
{
    const double roundoff = bounding_interval_roundoff(first_min, first_max,
	second_min, second_max);

    return first_max - first_min > roundoff &&
	second_max - second_min > roundoff &&
	(first_max <= second_min + roundoff ||
	 second_max <= first_min + roundoff);
}


static bool
planar_face_boundary_bounding_box(
    const ON_BrepFace &face,
    ON_BoundingBox &bbox)
{
    bool have_boundary = false;
    for (int loop_index = 0; loop_index < face.LoopCount(); ++loop_index) {
	const ON_BrepLoop *loop = face.Loop(loop_index);
	if (loop == NULL) {
	    return false;
	}

	for (int trim_index = 0;
	     trim_index < loop->TrimCount();
	     ++trim_index)
	{
	    const ON_BrepTrim *trim = loop->Trim(trim_index);
	    if (trim == NULL || trim->m_type == ON_BrepTrim::singular) {
		return false;
	    }

	    const ON_Curve *curve = trim->EdgeCurveOf();
	    ON_BoundingBox curve_bbox;
	    if (curve == NULL || !curve->GetTightBoundingBox(curve_bbox) ||
		!curve_bbox.IsValid())
	    {
		return false;
	    }

	    if (!have_boundary) {
		bbox = curve_bbox;
		have_boundary = true;
	    } else {
		bbox.Union(curve_bbox);
	    }
	}
    }

    return have_boundary && bbox.IsValid();
}


static bool
planar_face_boundaries_have_disjoint_interiors(
    const ON_BrepFace &first_face,
    const ON_BrepFace &second_face)
{
    ON_BoundingBox first_bbox;
    ON_BoundingBox second_bbox;
    if (!planar_face_boundary_bounding_box(first_face, first_bbox) ||
	!planar_face_boundary_bounding_box(second_face, second_bbox))
    {
	return false;
    }

    return nondegenerate_bounding_intervals_have_disjoint_interiors(
	first_bbox.m_min.x, first_bbox.m_max.x,
	second_bbox.m_min.x, second_bbox.m_max.x) ||
	nondegenerate_bounding_intervals_have_disjoint_interiors(
	    first_bbox.m_min.y, first_bbox.m_max.y,
	    second_bbox.m_min.y, second_bbox.m_max.y) ||
	nondegenerate_bounding_intervals_have_disjoint_interiors(
	    first_bbox.m_min.z, first_bbox.m_max.z,
	    second_bbox.m_min.z, second_bbox.m_max.z);
}


static int
point_brep_surface_location(const ON_3dPoint &pt, const ON_Brep *brep,
			    ON_SimpleArray<Subsurface *> &surf_tree,
			    const ON_BoundingBox &brep_bbox)
{
    if (brep == NULL || pt.IsUnset() || surf_tree.Count() != brep->m_S.Count()) {
	return INDETERMINATE_BREP;
    }

    ON_BoundingBox bbox = brep_bbox;
    if (!bbox.IsValid()) {
	return INDETERMINATE_BREP;
    }

    bbox.m_min -= ON_3dVector(INTERSECTION_TOL, INTERSECTION_TOL, INTERSECTION_TOL);
    bbox.m_max += ON_3dVector(INTERSECTION_TOL, INTERSECTION_TOL, INTERSECTION_TOL);
    if (!bbox.IsPointIn(pt)) {
	return OUTSIDE_BREP;
    }


    for (int i = 0; i < brep->m_F.Count(); ++i) {
	const ON_BrepFace &face = brep->m_F[i];
	if (face.m_si < 0 || face.m_si >= brep->m_S.Count() ||
	    surf_tree[face.m_si] == NULL)
	{
	    return INDETERMINATE_BREP;
	}
	const ON_Surface *surface = face.SurfaceOf();
	if (surface == NULL) {
	    return INDETERMINATE_BREP;
	}

	ON_ClassArray<ON_PX_EVENT> events;
	if (!ON_Intersect(pt, *surface, events, INTERSECTION_TOL, 0, 0,
		  surf_tree[face.m_si]))
	{
	    continue;
	}

	for (int j = 0; j < events.Count(); ++j) {
	    const ON_2dPoint uv(events[j].m_b[0], events[j].m_b[1]);
	    if (DEBUG_BREP_BOOLEAN) {
		const ON_3dPoint surface_point = uv.IsValid() ?
		    surface->PointAt(uv.x, uv.y) : ON_3dPoint::UnsetPoint;
		const int diagnostic_location = uv.IsValid() ?
		    point_face_location(uv, face, brep) : INDETERMINATE_FACE;
		bu_log("point_brep_surface_location: point (%.17g, %.17g, %.17g), "
		    "face %d event %d UV (%.17g, %.17g), residual %.17g, "
		    "face location %d.\n", pt.x, pt.y, pt.z, i, j, uv.x, uv.y,
		    surface_point.IsValid() ? surface_point.DistanceTo(pt) :
		    ON_UNSET_VALUE, diagnostic_location);
	    }
	    if (!uv.IsValid() ||
		surface->PointAt(uv.x, uv.y).DistanceTo(pt) > INTERSECTION_TOL)
	    {
		continue;
	    }
	    int location = point_face_location(uv, face, brep);
	    if (location == INDETERMINATE_FACE) {
		return INDETERMINATE_BREP;
	    }
	    if (location == INSIDE_FACE || location == ON_FACE_BOUNDARY) {
		return ON_BREP_SURFACE;
	    }
	    if (location == OUTSIDE_FACE &&
		point_is_near_brep_face_boundary(pt, face, brep))
	    {
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("point_brep_surface_location: projected point is within "
			"model tolerance of face %d boundary.\n", i);
		}
		return ON_BREP_SURFACE;
	    }
	}
    }

    return OUTSIDE_BREP;
}


static int
point_brep_ray_location(const ON_3dPoint &pt, const ON_Brep *brep,
			ON_SimpleArray<Subsurface *> &surf_tree,
			const ON_BoundingBox &bbox,
			const ON_3dVector &ray_direction)
{
    const auto indeterminate = [&](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("point_brep_ray_location: direction (%.17g, %.17g, %.17g) "
		"is indeterminate: %s.\n", ray_direction.x, ray_direction.y,
		ray_direction.z, reason);
	}
	return INDETERMINATE_RAY;
    };
    const double ray_length =
	bbox.Diagonal().Length() * POINT_CONTAINMENT_RAY_LENGTH_MULTIPLIER;
    if (ray_length <= INTERSECTION_TOL) {
	return indeterminate("ray is shorter than the intersection tolerance");
    }

    ON_LineCurve line(pt, pt + ray_direction * ray_length);
    ON_Interval line_domain = line.Domain();
    const double parameter_tolerance =
	INTERSECTION_TOL * line_domain.Length() / ray_length;
    if (parameter_tolerance * POINT_CONTAINMENT_RAY_LENGTH_MULTIPLIER >=
	line_domain.Length())
    {
	return indeterminate("ray parameter tolerance consumes its domain");
    }

    ON_SimpleArray<double> hit_parameters;
    for (int i = 0; i < brep->m_F.Count(); ++i) {
	const ON_BrepFace &face = brep->m_F[i];
	if (face.m_si < 0 || face.m_si >= brep->m_S.Count() ||
	    surf_tree[face.m_si] == NULL)
	{
	    return indeterminate("face has no valid surface tree");
	}
	const ON_Surface *surface = face.SurfaceOf();
	if (surface == NULL) {
	    return indeterminate("face has no surface");
	}

	ON_SimpleArray<ON_X_EVENT> events;
	int event_count = ON_Intersect(&line, surface, events, INTERSECTION_TOL,
		INTERSECTION_TOL, 0, 0, 0, 0, 0, surf_tree[face.m_si]);
	if (event_count == BREP_CSI_BUDGET_EXCEEDED) {
	    record_boolean_failure(
		BREP_BOOLEAN_FAILURE_STAGE_SURFACE_INTERSECTION,
		BREP_BOOLEAN_FAILURE_REASON_WORK_BUDGET, -1, -1, -1, -1,
		INTERSECTION_TOL);
	    throw BooleanBudgetExceeded(
		"Curve-surface intersection work limit exceeded.\n");
	}
	if (event_count < 0) {
	    return indeterminate("curve-surface intersection failed");
	}

	for (int j = 0; j < events.Count(); ++j) {
	    const ON_X_EVENT &event = events[j];
	    if (event.m_type == ON_X_EVENT::csx_overlap ||
		event.m_type != ON_X_EVENT::csx_point)
	    {
		return indeterminate("curve-surface intersection is not a point");
	    }
	    if (!event.m_A[0].IsValid() || !event.m_B[0].IsValid() ||
		event.m_A[0].DistanceTo(event.m_B[0]) > INTERSECTION_TOL)
	    {
		return indeterminate("curve-surface intersection residual is invalid");
	    }
	    const ON_2dPoint uv(event.m_b[0], event.m_b[1]);
	    int face_location = point_face_location(uv, face, brep);
	    if (face_location == INDETERMINATE_FACE ||
		face_location == ON_FACE_BOUNDARY)
	    {
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("point_brep_ray_location: face %d event %d at ray "
			"parameter %.17g and UV (%.17g, %.17g) has face "
			"location %d.\n", i, j, event.m_a[0], uv.x, uv.y,
			face_location);
		}
		return indeterminate(face_location == ON_FACE_BOUNDARY ?
		    "ray intersects a face boundary" :
		    "ray intersection cannot be classified on its face");
	    }
	    if (face_location == OUTSIDE_FACE) {
		continue;
	    }
	    if (event.m_a[0] <= line_domain.Min() + parameter_tolerance ||
		event.m_a[0] >= line_domain.Max() - parameter_tolerance)
	    {
		return indeterminate("curve-surface intersection is at a ray endpoint");
	    }

	    ON_3dPoint surface_point;
	    ON_3dVector surface_normal;
	    if (!surface_EvNormal(surface, uv.x, uv.y, surface_point,
			  surface_normal) ||
		ON_NearZero(surface_normal.Length()) ||
		surface_normal.IsPerpendicularTo(ray_direction, ANGLE_TOL))
	    {
		return indeterminate("ray intersection is tangential or has no normal");
	    }

	    for (int k = 0; k < hit_parameters.Count(); ++k) {
		if (fabs(hit_parameters[k] - event.m_a[0]) <= parameter_tolerance) {
		    return indeterminate("ray has duplicate face intersections");
		}
	    }
	    hit_parameters.Append(event.m_a[0]);
	}
    }

    return hit_parameters.Count() % 2 ? INSIDE_RAY : OUTSIDE_RAY;
}


/* Ray parity is unnecessarily fragile for convex polyhedra: a ray can miss a
 * very thin exit face even though the oriented planar halfspaces determine the
 * answer directly.  Use this path only after every face has certified the same
 * convex interior side for every B-Rep vertex. */
static int
convex_planar_brep_point_location(const ON_3dPoint &point,
    const ON_Brep *brep, const ON_BoundingBox &bounds)
{
    if (brep == NULL || !point.IsValid() || !bounds.IsValid() ||
	brep->m_F.Count() < 4 || brep->m_V.Count() < 4)
    {
	return INDETERMINATE_BREP;
    }

    struct OrientedPlane {
	ON_3dPoint origin;
	ON_3dVector normal;
    };
    std::vector<OrientedPlane> planes;
    planes.reserve(static_cast<size_t>(brep->m_F.Count()));
    const double tolerance = std::max(INTERSECTION_TOL,
	boolean_coordinate_roundoff_tolerance(bounds));

    for (int face_index = 0; face_index < brep->m_F.Count(); ++face_index) {
	const ON_BrepFace &face = brep->m_F[face_index];
	const ON_Surface *surface = face.SurfaceOf();
	ON_Plane plane;
	if (surface == NULL || !surface->IsPlanar(&plane)) {
	    return INDETERMINATE_BREP;
	}

	ON_3dVector normal = plane.zaxis;
	if (face.m_bRev)
	    normal = -normal;
	if (!normal.Unitize()) {
	    return INDETERMINATE_BREP;
	}

	bool have_strictly_interior_vertex = false;
	for (int vertex_index = 0; vertex_index < brep->m_V.Count();
	     ++vertex_index)
	{
	    const ON_3dPoint vertex = brep->m_V[vertex_index].point;
	    if (!vertex.IsValid()) {
		return INDETERMINATE_BREP;
	    }
	    const double distance = ON_DotProduct(vertex - plane.origin, normal);
	    if (!std::isfinite(distance) || distance > tolerance) {
		return INDETERMINATE_BREP;
	    }
	    if (distance < -tolerance)
		have_strictly_interior_vertex = true;
	}
	if (!have_strictly_interior_vertex) {
	    return INDETERMINATE_BREP;
	}
	planes.push_back({plane.origin, normal});
    }

    bool on_boundary = false;
    for (size_t plane_index = 0; plane_index < planes.size(); ++plane_index) {
	const double distance = ON_DotProduct(point - planes[plane_index].origin,
	    planes[plane_index].normal);
	if (!std::isfinite(distance)) {
	    return INDETERMINATE_BREP;
	}
	if (distance > tolerance) {
	    return OUTSIDE_BREP;
	}
	if (fabs(distance) <= tolerance)
	    on_boundary = true;
    }
    return on_boundary ? ON_BREP_SURFACE : INSIDE_BREP;
}


static int
point_brep_location(const ON_3dPoint &pt, const ON_Brep *brep,
		    ON_SimpleArray<Subsurface *> &surf_tree,
		    const ON_BoundingBox &brep_bbox)
{
    if (brep == NULL || pt.IsUnset() || surf_tree.Count() != brep->m_S.Count()) {
	return INDETERMINATE_BREP;
    }

    ON_BoundingBox bbox = brep_bbox;
    if (!bbox.IsValid()) {
	return INDETERMINATE_BREP;
    }

    bbox.m_min -= ON_3dVector(INTERSECTION_TOL, INTERSECTION_TOL, INTERSECTION_TOL);
    bbox.m_max += ON_3dVector(INTERSECTION_TOL, INTERSECTION_TOL, INTERSECTION_TOL);
    if (!bbox.IsPointIn(pt)) {
	return OUTSIDE_BREP;
    }

    const int convex_planar_location = convex_planar_brep_point_location(pt,
	brep, brep_bbox);
    if (convex_planar_location != INDETERMINATE_BREP) {
	return convex_planar_location;
    }

    static const ON_3dVector primary_ray_directions[] = {
	ON_3dVector(1.0, 0.0, 0.0),
	ON_3dVector(0.0, 1.0, 0.0),
	ON_3dVector(0.0, 0.0, 1.0)
    };
    static const ON_3dVector fallback_ray_directions[] = {
	ON_3dVector(-1.0, 0.0, 0.0),
	ON_3dVector(0.0, -1.0, 0.0),
	ON_3dVector(0.0, 0.0, -1.0),
	ON_3dVector(1.0, 1.0, 1.0),
	ON_3dVector(1.0, 1.0, -1.0),
	ON_3dVector(1.0, -1.0, 1.0),
	ON_3dVector(-1.0, 1.0, 1.0),
	// Pairwise-distinct prime components avoid the axes and equal-component
	// diagonals that commonly pass through symmetric model edges or vertices.
	ON_3dVector(2.0, 3.0, 5.0),
	ON_3dVector(3.0, -5.0, 7.0),
	ON_3dVector(-5.0, 7.0, 11.0),
	ON_3dVector(7.0, 11.0, -13.0),
	ON_3dVector(-2.0, -3.0, -5.0),
	ON_3dVector(-3.0, 5.0, -7.0),
	ON_3dVector(5.0, -7.0, -11.0),
	ON_3dVector(-7.0, -11.0, 13.0)
    };

    int location = INDETERMINATE_BREP;
    int valid_ray_count = 0;
    int inside_ray_count = 0;
    int outside_ray_count = 0;
    const auto add_ray_location = [&](const ON_3dVector &ray_direction) {
	ON_3dVector normalized_direction(ray_direction);
	if (!normalized_direction.Unitize()) {
	    return false;
	}

	const int ray_location = point_brep_ray_location(pt, brep, surf_tree,
	    bbox, normalized_direction);
	if (ray_location == INDETERMINATE_RAY) {
	    return true;
	}

	const int ray_brep_location = ray_location == INSIDE_RAY ?
	    INSIDE_BREP : OUTSIDE_BREP;
	if (location == INDETERMINATE_BREP) {
	    location = ray_brep_location;
	}
	if (ray_brep_location == INSIDE_BREP) {
	    ++inside_ray_count;
	} else {
	    ++outside_ray_count;
	}
	++valid_ray_count;
	return true;
    };

    for (size_t i = 0;
         i < sizeof(primary_ray_directions) / sizeof(primary_ray_directions[0]);
         ++i) {
	add_ray_location(primary_ray_directions[i]);
    }
    if (valid_ray_count < POINT_CONTAINMENT_MINIMUM_VALID_RAYS ||
	(inside_ray_count > 0 && outside_ray_count > 0))
    {
	for (size_t i = 0;
	     i < sizeof(fallback_ray_directions) /
	     sizeof(fallback_ray_directions[0]);
	     ++i) {
	    add_ray_location(fallback_ray_directions[i]);
	}
    }

    if (DEBUG_BREP_BOOLEAN && inside_ray_count > 0 &&
	outside_ray_count > 0)
    {
	bu_log("point_brep_location: point (%.17g, %.17g, %.17g) has "
	    "%d inside and %d outside ray classifications.\n", pt.x, pt.y,
	    pt.z, inside_ray_count, outside_ray_count);
    }
    if (inside_ray_count > 0 && outside_ray_count > 0) {
	const int majority_count = std::max(inside_ray_count,
	    outside_ray_count);
	const int minority_count = std::min(inside_ray_count,
	    outside_ray_count);
	if (valid_ray_count >= POINT_CONTAINMENT_MINIMUM_SUPERMAJORITY_RAYS &&
	    majority_count >= POINT_CONTAINMENT_SUPERMAJORITY_RATIO *
		minority_count)
	{
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("point_brep_location: resolving the divergent ray votes by "
		    "supermajority.\n");
	    }
	    return inside_ray_count > outside_ray_count ? INSIDE_BREP :
		OUTSIDE_BREP;
	}
	return INDETERMINATE_BREP;
    }

    return valid_ray_count >= POINT_CONTAINMENT_MINIMUM_VALID_RAYS ?
	location : INDETERMINATE_BREP;
}


bool
ON_BrepPointInside(const ON_3dPoint &point, const ON_Brep *brep)
{
    if (!brep || !brep->IsValid() || !brep->IsSolid() || point.IsUnset())
	return false;
    ON_BoundingBox brep_bbox;
    if (!boolean_brep_bounding_box(brep, brep_bbox)) {
	return false;
    }
    ON_SimpleArray<Subsurface *> surface_tree;
    for (int surface = 0; surface < brep->m_S.Count(); ++surface) {
	if (!brep->m_S[surface]) {
	    for (int created = 0; created < surface_tree.Count(); ++created)
		delete surface_tree[created];
	    return false;
	}
	surface_tree.Append(new Subsurface(brep->m_S[surface]->Duplicate()));
    }
	const int location = point_brep_location(point, brep, surface_tree,
				     brep_bbox);
    for (int surface = 0; surface < surface_tree.Count(); ++surface)
	delete surface_tree[surface];
    return location == INSIDE_BREP;
}


static bool
trimmed_face_loop_parameter_tolerance(
    const ON_Surface *surface,
    const ON_SimpleArray<ON_Curve *> &loop,
    double &intersection_tolerance)
{
    if (surface == NULL || loop.Count() < 1) {
	return false;
    }

    for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	double curve_intersection_tolerance = 0.0;
	double curve_parameter_tolerance = 0.0;
	if (!get_face_boundary_curve_tolerances(surface, loop[curve_index],
		curve_intersection_tolerance, curve_parameter_tolerance))
	{
	    return false;
	}
	intersection_tolerance = std::min(intersection_tolerance,
	    curve_intersection_tolerance);
    }

    return true;
}


static bool
trimmed_face_parameter_tolerance(
    const TrimmedFace *tface,
    double &intersection_tolerance)
{
    if (tface == NULL || tface->m_face == NULL ||
	tface->m_face->SurfaceOf() == NULL)
    {
	return false;
    }

    const ON_Surface *surface = tface->m_face->SurfaceOf();
    double face_intersection_tolerance = INTERSECTION_TOL;
    if (!trimmed_face_loop_parameter_tolerance(surface, tface->m_outerloop,
	face_intersection_tolerance))
    {
	return false;
    }
    for (size_t loop_index = 0; loop_index < tface->m_innerloop.size();
	 ++loop_index)
    {
	if (!trimmed_face_loop_parameter_tolerance(surface,
		tface->m_innerloop[loop_index], face_intersection_tolerance))
	{
	    return false;
	}
    }

    intersection_tolerance = face_intersection_tolerance;
    return true;
}


static const ON_SimpleArray<ON_Curve *> &
normalized_trimmed_face_loop(
    const TrimmedFace *tface,
    const ON_SimpleArray<ON_Curve *> &loop,
    NormalizedBooleanLoop &normalized_loop)
{
    double intersection_tolerance = INTERSECTION_TOL;

    const ON_Surface *surface = tface != NULL && tface->m_face != NULL ?
	tface->m_face->SurfaceOf() : NULL;
    if (surface != NULL && !trimmed_face_loop_parameter_tolerance(surface,
	    loop, intersection_tolerance)) {
	intersection_tolerance = INTERSECTION_TOL;
    }

    return normalized_loop_for_point_classification(loop,
	intersection_tolerance, normalized_loop, surface,
	boolean_model_repair_tolerance(surface ? surface->BoundingBox() :
	    ON_BoundingBox()));
}


static bool
trimmed_face_strict_interior_tolerance(
    const TrimmedFace *tface,
    double &intersection_tolerance)
{
    if (tface == NULL) {
	return false;
    }

    NormalizedBooleanLoop normalized_loop;
    const ON_SimpleArray<ON_Curve *> &classification_loop =
	normalized_trimmed_face_loop(tface, tface->m_outerloop,
	    normalized_loop);

    ON_PolyCurve outer_loop;


    if (!is_loop_valid(classification_loop, ON_ZERO_TOLERANCE,
	&outer_loop))
    {
	return false;
    }

    const ON_BoundingBox bounds = outer_loop.BoundingBox();
    if (!bounds.IsValid()) {
	return false;
    }

    // Interior witnesses must be separated from a boundary by more than
    // representation roundoff, not by the broader Boolean intersection band.
    intersection_tolerance = boolean_coordinate_roundoff_tolerance(bounds);
    return intersection_tolerance > 0.0;
}


static bool
is_point_inside_trimmed_face(const ON_2dPoint &pt, const TrimmedFace *tface)
{
    double intersection_tolerance = 0.0;
    if (!trimmed_face_parameter_tolerance(tface, intersection_tolerance)) {
	// Preserve existing classification behavior when UV metrics are unavailable.
	intersection_tolerance = INTERSECTION_TOL;
    }

    bool inside = false;
    // A model-space tolerance must be converted before it is used in UV.
    if (is_point_inside_loop(pt, tface->m_outerloop,
	    intersection_tolerance)) {
	inside = true;
	for (size_t i = 0; i < tface->m_innerloop.size(); ++i) {
	    if (!is_point_outside_loop(pt, tface->m_innerloop[i],
		intersection_tolerance)) {
		inside = false;
		break;
	    }
	}
    }
    return inside;
}


static bool
is_point_strictly_inside_trimmed_face(
    const ON_2dPoint &pt,
    const TrimmedFace *tface)
{
    double intersection_tolerance = 0.0;
    if (!trimmed_face_strict_interior_tolerance(tface,
	intersection_tolerance))
    {
	return false;
    }


    NormalizedBooleanLoop normalized_outer_loop;
    const ON_SimpleArray<ON_Curve *> &outer_loop =
	normalized_trimmed_face_loop(tface, tface->m_outerloop,
	    normalized_outer_loop);
    if (!is_point_inside_loop(pt, outer_loop,
	intersection_tolerance))
    {
	return false;
    }

    for (size_t loop_index = 0; loop_index < tface->m_innerloop.size();
	 ++loop_index)
    {
	NormalizedBooleanLoop normalized_inner_loop;
	const ON_SimpleArray<ON_Curve *> &inner_loop =
	    normalized_trimmed_face_loop(tface, tface->m_innerloop[loop_index],
		normalized_inner_loop);
	if (!is_point_outside_loop(pt, inner_loop,
		intersection_tolerance))
	{
	    return false;
	}
    }

    return true;
}


static double
boolean_interior_point_segment_distance(
    const ON_2dPoint &point,
    const ON_2dPoint &start,
    const ON_2dPoint &end)
{
    const double dx = end.x - start.x;
    const double dy = end.y - start.y;
    const double length_squared = dx * dx + dy * dy;
    if (!(length_squared > 0.0) || !std::isfinite(length_squared)) {
	return point.DistanceTo(start);
    }

    double parameter = ((point.x - start.x) * dx +
	(point.y - start.y) * dy) / length_squared;
    parameter = std::max(0.0, std::min(1.0, parameter));
    return point.DistanceTo(ON_2dPoint(start.x + parameter * dx,
	start.y + parameter * dy));
}


/* A positive-weight rational Bezier curve is contained in the convex hull of
 * its Euclidean control points.  Consequently the largest control-point
 * distance from the endpoint chord is a conservative bound on the distance
 * from the complete curve locus to that chord. */
static bool
append_boolean_interior_bezier_polygon(
    std::vector<ON_2dPoint> &points,
    const ON_BezierCurve &curve,
    double requested_error,
    unsigned int depth,
    size_t &subdivisions,
    double &maximum_error)
{
    const ON_3dPoint start3d = curve.PointAt(0.0);
    const ON_3dPoint end3d = curve.PointAt(1.0);
    if (!start3d.IsValid() || !end3d.IsValid()) {
	return false;
    }
    const ON_2dPoint start(start3d.x, start3d.y);
    const ON_2dPoint end(end3d.x, end3d.y);

    double flatness = 0.0;
    for (int control_index = 0; control_index < curve.CVCount();
	 ++control_index)
    {
	ON_3dPoint control3d;
	const double weight = curve.Weight(control_index);
	if (!(weight > 0.0) || !std::isfinite(weight) ||
	    !curve.GetCV(control_index, control3d) || !control3d.IsValid())
	{
	    return false;
	}
	const double distance = boolean_interior_point_segment_distance(
	    ON_2dPoint(control3d.x, control3d.y), start, end);
	if (!std::isfinite(distance)) {
	    return false;
	}
	flatness = std::max(flatness, distance);
    }

    if (flatness <= requested_error) {
	double segment_error = flatness;
	if (points.empty()) {
	    points.push_back(start);
	} else {
	    const double junction_gap = points.back().DistanceTo(start);
	    if (!std::isfinite(junction_gap) ||
		junction_gap > requested_error)
	    {
		return false;
	    }
	    /* The proxy uses the direct chord from the preceding endpoint to this
	     * span's endpoint.  Moving the chord start by junction_gap moves every
	     * corresponding chord point by no more than junction_gap, so the curve
	     * remains within flatness + junction_gap of the proxy.  Avoid inserting
	     * a microscopic connector vertex: roundoff-scale backtracking at NURBS
	     * span boundaries can otherwise make a simple loop appear self-
	     * intersecting to the constrained triangulator. */
	    segment_error += junction_gap;
	}
	maximum_error = std::max(maximum_error, segment_error);
	if (points.back().DistanceTo(end) > 0.0) {
	    points.push_back(end);
	}
	return true;
    }

    if (depth >= BOOLEAN_INTERIOR_POLYGON_MAXIMUM_DEPTH ||
	++subdivisions > BOOLEAN_INTERIOR_POLYGON_MAXIMUM_SUBDIVISIONS)
    {
	return false;
    }

    ON_BezierCurve left;
    ON_BezierCurve right;
    return curve.Split(0.5, left, right) &&
	append_boolean_interior_bezier_polygon(points, left,
	    requested_error, depth + 1, subdivisions, maximum_error) &&
	append_boolean_interior_bezier_polygon(points, right,
	    requested_error, depth + 1, subdivisions, maximum_error);
}


static bool
boolean_interior_curve_polygon(
    const ON_Curve *curve,
    double requested_error,
    size_t &subdivisions,
    std::vector<ON_2dPoint> &points,
    double &maximum_error)
{
    if (curve == NULL || !(requested_error > 0.0) ||
	!std::isfinite(requested_error))
    {
	return false;
    }

    ON_NurbsCurve nurbs;
    if (curve->GetNurbForm(nurbs) <= 0 || !nurbs.IsValid() ||
	nurbs.Dimension() < 2)
    {
	return false;
    }

    points.clear();
    maximum_error = 0.0;
    for (int span = 0; span <= nurbs.CVCount() - nurbs.Order(); ++span) {
	const int knot = span + nurbs.Order() - 2;
	if (!(nurbs.Knot(knot) < nurbs.Knot(knot + 1))) {
	    continue;
	}
	ON_BezierCurve bezier;
	if (++subdivisions > BOOLEAN_INTERIOR_POLYGON_MAXIMUM_SUBDIVISIONS ||
	    !nurbs.ConvertSpanToBezier(span, bezier) ||
	    !append_boolean_interior_bezier_polygon(points, bezier,
		requested_error, 0, subdivisions, maximum_error))
	{
	    return false;
	}
    }

    return points.size() >= 2;
}


static bool
boolean_interior_loop_polygon(
    const ON_SimpleArray<ON_Curve *> &loop,
    double requested_error,
    size_t &subdivisions,
    std::vector<ON_2dPoint> &polygon,
    double &maximum_error)
{
    polygon.clear();
    maximum_error = 0.0;
    for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	std::vector<ON_2dPoint> curve_points;
	double curve_error = 0.0;
	if (!boolean_interior_curve_polygon(loop[curve_index], requested_error,
		subdivisions, curve_points, curve_error))
	{
	    return false;
	}
	maximum_error = std::max(maximum_error, curve_error);
	if (polygon.empty()) {
	    polygon.insert(polygon.end(), curve_points.begin(),
		curve_points.end());
	    continue;
	}

	const double join_gap = polygon.back().DistanceTo(curve_points.front());
	if (!std::isfinite(join_gap) || join_gap > requested_error) {
	    return false;
	}
	maximum_error = std::max(maximum_error, join_gap);
	if (join_gap > 0.0) {
	    polygon.push_back(curve_points.front());
	}
	polygon.insert(polygon.end(), curve_points.begin() + 1,
	    curve_points.end());
    }

    if (polygon.size() < 4) {
	return false;
    }

    const double closure_gap = polygon.back().DistanceTo(polygon.front());
    if (!std::isfinite(closure_gap) || closure_gap > requested_error) {
	return false;
    }
    maximum_error = std::max(maximum_error, closure_gap);
    if (closure_gap == 0.0) {
	polygon.pop_back();
    }

    return polygon.size() >= 3;
}


static bool
append_boolean_interior_polygon(
    const std::vector<ON_2dPoint> &polygon,
    std::vector<ON_2dPoint> &points,
    std::vector<int> &indices)
{
    const size_t maximum_index =
	static_cast<size_t>(std::numeric_limits<int>::max());
    if (polygon.size() < 3 || points.size() > maximum_index ||
	polygon.size() > maximum_index - points.size())
    {
	return false;
    }

    const int first_index = static_cast<int>(points.size());
    for (size_t point_index = 0; point_index < polygon.size(); ++point_index) {
	points.push_back(polygon[point_index]);
	indices.push_back(first_index + static_cast<int>(point_index));
    }

    indices.push_back(first_index);
    return true;
}


static bool
boolean_interior_points_are_unique(const std::vector<ON_2dPoint> &points)
{
    std::set<std::pair<double, double> > unique_points;
    for (size_t point_index = 0; point_index < points.size(); ++point_index) {
	const ON_2dPoint &point = points[point_index];
	if (!point.IsValid() || !unique_points.insert(std::make_pair(point.x,
		point.y)).second)
	{
	    return false;
	}
    }

    return true;
}


static bool
boolean_interior_polygon_contains(
    const std::vector<ON_2dPoint> &polygon,
    const ON_2dPoint &point)
{
    if (polygon.size() < 3 || !point.IsValid()) {
	return false;
    }

    bool inside = false;
    for (size_t current = 0, previous = polygon.size() - 1;
	 current < polygon.size(); previous = current++)
    {
	const ON_2dPoint &first = polygon[previous];
	const ON_2dPoint &second = polygon[current];
	if (!first.IsValid() || !second.IsValid()) {
	    return false;
	}
	if ((first.y > point.y) != (second.y > point.y)) {
	    const double crossing = first.x +
		(point.y - first.y) * (second.x - first.x) /
		(second.y - first.y);
	    if (crossing > point.x) {
		inside = !inside;
	    }
	}
    }
    return inside;
}


static double
boolean_interior_polygon_clearance(
    const std::vector<ON_2dPoint> &polygon,
    const ON_2dPoint &point)
{
    if (polygon.size() < 3 || !point.IsValid()) {
	return 0.0;
    }

    double clearance = std::numeric_limits<double>::infinity();
    for (size_t current = 0, previous = polygon.size() - 1;
	 current < polygon.size(); previous = current++)
    {
	clearance = std::min(clearance,
	    boolean_interior_point_segment_distance(point, polygon[previous],
		polygon[current]));
    }
    return std::isfinite(clearance) ? clearance : 0.0;
}


static bool
certified_boolean_interior_polygon_point(
    const ON_2dPoint &point,
    const std::vector<ON_2dPoint> &outer_polygon,
    const std::vector<std::vector<ON_2dPoint> > &inner_polygons,
    double required_clearance,
    double &clearance)
{
    if (!(required_clearance > 0.0) ||
	!std::isfinite(required_clearance) ||
	!boolean_interior_polygon_contains(outer_polygon, point))
    {
	return false;
    }

    clearance = boolean_interior_polygon_clearance(outer_polygon, point);
    for (size_t loop_index = 0; loop_index < inner_polygons.size();
	 ++loop_index)
    {
	if (boolean_interior_polygon_contains(inner_polygons[loop_index], point)) {
	    return false;
	}
	clearance = std::min(clearance,
	    boolean_interior_polygon_clearance(inner_polygons[loop_index],
		point));
    }
    return std::isfinite(clearance) && clearance > required_clearance;
}


static bool
paired_boundary_trimmed_face_interior_point(
    const TrimmedFace *tface,
    const ON_SimpleArray<ON_Curve *> &outer_loop,
    ON_2dPoint &interior_point)
{
    if (tface == NULL || outer_loop.Count() != 2 ||
	outer_loop[0] == NULL || outer_loop[1] == NULL)
    {
	return false;
    }

    const ON_Interval first_domain = outer_loop[0]->Domain();
    const ON_Interval second_domain = outer_loop[1]->Domain();
    if (!first_domain.IsIncreasing() || !second_domain.IsIncreasing()) {
	return false;
    }

    // A two-curve loop is commonly a very thin lens or strip.  A bounding-box
    // grid can miss it, and a normal offset can jump completely across it.
    // Pair samples along the two boundaries instead; every proposed midpoint
    // is still accepted only by the strict loop-and-hole classifier.
    static const int maximum_divisions = 64;
    for (int divisions = 2; divisions <= maximum_divisions; divisions *= 2) {
	for (int numerator = 1; numerator < divisions; numerator += 2) {
	    const double fraction = static_cast<double>(numerator) / divisions;
	    const ON_3dPoint first_point = outer_loop[0]->PointAt(
		first_domain.ParameterAt(fraction));
	    if (!first_point.IsValid()) {
		continue;
	    }

	    for (int reverse_second = 0; reverse_second < 2; ++reverse_second) {
		const double second_fraction = reverse_second ?
		    1.0 - fraction : fraction;
		const ON_3dPoint second_point = outer_loop[1]->PointAt(
		    second_domain.ParameterAt(second_fraction));
		if (!second_point.IsValid()) {
		    continue;
		}

		const ON_2dPoint candidate(
		    0.5 * (first_point.x + second_point.x),
		    0.5 * (first_point.y + second_point.y));
		if (candidate.IsValid() &&
		    is_point_strictly_inside_trimmed_face(candidate, tface))
		{
		    interior_point = candidate;
		    return true;
		}
	    }
	}
    }

    if (DEBUG_BREP_BOOLEAN) {
	double strict_tolerance = 0.0;
	(void)trimmed_face_strict_interior_tolerance(tface, strict_tolerance);
	bu_log("Boolean paired-boundary interior search failed (tolerance %.17g).\n",
	    strict_tolerance);
	for (int curve_index = 0; curve_index < outer_loop.Count(); ++curve_index) {
	    const ON_Curve *curve = outer_loop[curve_index];
	    const ON_Interval domain = curve->Domain();
	    bu_log("  curve %d: span count %d, linear %d, domain [%.17g, %.17g].\n",
		curve_index, curve->SpanCount(),
		curve->IsLinear(ON_ZERO_TOLERANCE), domain.Min(), domain.Max());
	    for (int sample_index = 0; sample_index <= 4; ++sample_index) {
		const double fraction = sample_index / 4.0;
		const ON_3dPoint point = curve->PointAt(domain.ParameterAt(fraction));
		bu_log("    sample %.2f: (%.17g, %.17g).\n", fraction,
		    point.x, point.y);
	    }
	}
    }

    return false;
}


static bool
trimmed_face_has_collapsed_two_curve_outer_loop(
    const TrimmedFace *tface,
    bool allow_modeling_tolerance = false)
{
    if (tface == NULL || !tface->m_innerloop.empty() ||
	tface->m_outerloop.Count() != 2 ||
	tface->m_outerloop[0] == NULL || tface->m_outerloop[1] == NULL)
    {
	return false;
    }

    const ON_Curve *first = tface->m_outerloop[0];
    const ON_Curve *second = tface->m_outerloop[1];

    const ON_Interval first_domain = first->Domain();
    const ON_Interval second_domain = second->Domain();
    if (!first_domain.IsIncreasing() || !second_domain.IsIncreasing()) {
	return false;
    }

    std::unique_ptr<ON_Curve> first_lifted;
    std::unique_ptr<ON_Curve> second_lifted;
    const ON_Surface *surface = tface->m_face ?
	tface->m_face->SurfaceOf() : NULL;
    if (surface != NULL) {
	first_lifted.reset(pushup_boolean_curve(surface, *first));
	second_lifted.reset(pushup_boolean_curve(surface, *second));
    }
    const ON_Curve *first_test = first_lifted ? first_lifted.get() : first;
    const ON_Curve *second_test = second_lifted ? second_lifted.get() : second;

    ON_BoundingBox bounds = first_test->BoundingBox();
    const ON_BoundingBox second_bounds = second_test->BoundingBox();
    if (!bounds.IsValid() || !second_bounds.IsValid()) {
	return false;
    }
    bounds.Union(second_bounds);
    double tolerance = BOOLEAN_COLLAPSED_LOOP_ROUNDOFF_MULTIPLIER *
	boolean_coordinate_roundoff_tolerance(bounds);
    if (allow_modeling_tolerance) {
	tolerance = std::max(tolerance, INTERSECTION_TOL);
    }
    if (!(tolerance > 0.0)) {
	return false;
    }

    /* Repeated arrangement splitting can represent one boundary once as a
     * line and once as a higher-order subcurve.  The normal preclassification
     * check uses only a roundoff-derived tolerance so a merely thin region is
     * still eligible for classification.  If classification cannot find an
     * interior, its caller may allow the Boolean modeling tolerance and cull
     * only after this bidirectional whole-locus proof succeeds. */
    bool reversed = false;
    return brep_curves_coincident(*first_test, *second_test, tolerance,
	&reversed) && reversed;
}


static bool
triangulated_trimmed_face_interior_point(
    const TrimmedFace *tface,
    ON_2dPoint &interior_point)
{
    if (tface == NULL) {
	return false;
    }

    NormalizedBooleanLoop normalized_outer_loop;
    const ON_SimpleArray<ON_Curve *> *outer_loop = NULL;
    try {
	outer_loop = &normalized_trimmed_face_loop(tface, tface->m_outerloop,
	    normalized_outer_loop);
    } catch (InvalidGeometry &) {
	return false;
    }

    ON_PolyCurve outer_polycurve;
    if (!is_loop_valid(*outer_loop, ON_ZERO_TOLERANCE, &outer_polycurve)) {
	return false;
    }
    const ON_BoundingBox bounds = outer_polycurve.BoundingBox();
    if (!bounds.IsValid()) {
	return false;
    }
    const double u_length = bounds.m_max.x - bounds.m_min.x;
    const double v_length = bounds.m_max.y - bounds.m_min.y;
    const double minimum_dimension = std::min(u_length, v_length);
    const double roundoff_tolerance =
	boolean_coordinate_roundoff_tolerance(bounds);
    if (!(minimum_dimension > 0.0) ||
	!(roundoff_tolerance > 0.0) ||
	!std::isfinite(minimum_dimension))
    {
	return false;
    }

    /* Start fine enough to resolve a narrow face, then refine if a coarse
     * polygon does not leave a certifiable interior point.  This fallback is
     * intentionally independent of curve/ray intersections: every accepted
     * witness is farther from every polygon edge than the proven Bezier-to-
     * chord error plus coordinate roundoff.  Winding therefore cannot change
     * while each polygon chord is continuously deformed back to its curve. */
    static const int maximum_attempts = 6;
    const double minimum_requested_error = roundoff_tolerance;
    double requested_error = std::max(minimum_requested_error,
	minimum_dimension / 256.0);

    for (int attempt = 0; attempt < maximum_attempts; ++attempt) {
	std::vector<ON_2dPoint> points;
	std::vector<ON_2dPoint> outer_polygon;
	std::vector<int> outer_indices;
	std::vector<std::vector<ON_2dPoint> > inner_polygons(
	    tface->m_innerloop.size());
	std::vector<std::vector<int> > inner_indices(
	    tface->m_innerloop.size());
	size_t subdivisions = 0;
	double approximation_error = 0.0;
	double loop_error = 0.0;
	if (!boolean_interior_loop_polygon(*outer_loop, requested_error,
		subdivisions, outer_polygon, loop_error) ||
	    !append_boolean_interior_polygon(outer_polygon, points,
		outer_indices))
	{
	    return false;
	}
	approximation_error = std::max(approximation_error, loop_error);

	bool valid_polygons = true;
	for (size_t loop_index = 0;
	     loop_index < tface->m_innerloop.size(); ++loop_index)
	{
	    NormalizedBooleanLoop normalized_inner_loop;
	    const ON_SimpleArray<ON_Curve *> *inner_loop = NULL;
	    try {
		inner_loop = &normalized_trimmed_face_loop(tface,
		    tface->m_innerloop[loop_index], normalized_inner_loop);
	    } catch (InvalidGeometry &) {
		valid_polygons = false;
		break;
	    }
	    loop_error = 0.0;
	    if (!boolean_interior_loop_polygon(*inner_loop, requested_error,
		    subdivisions, inner_polygons[loop_index], loop_error) ||
		!append_boolean_interior_polygon(inner_polygons[loop_index],
		    points, inner_indices[loop_index]))
	    {
		valid_polygons = false;
		break;
	    }
	    approximation_error = std::max(approximation_error, loop_error);
	}
	if (!valid_polygons || !boolean_interior_points_are_unique(points)) {
	    return false;
	}

	std::vector<const int *> inner_arrays;
	std::vector<size_t> inner_sizes;
	for (size_t loop_index = 0; loop_index < inner_indices.size();
	     ++loop_index)
	{
	    inner_arrays.push_back(inner_indices[loop_index].data());
	    inner_sizes.push_back(inner_indices[loop_index].size());
	}

	point2d_t *triangulation_points = static_cast<point2d_t *>(bu_calloc(
	    points.size(), sizeof(point2d_t),
	    "Boolean interior triangulation points"));
	if (triangulation_points == NULL) {
	    return false;
	}
	for (size_t point_index = 0; point_index < points.size(); ++point_index) {
	    triangulation_points[point_index][X] = points[point_index].x;
	    triangulation_points[point_index][Y] = points[point_index].y;
	}

	int *triangles = NULL;
	int triangle_count = 0;
	const int triangulation_result = bg_nested_poly_triangulate(&triangles,
	    &triangle_count, NULL, NULL, outer_indices.data(),
	    outer_indices.size(), inner_arrays.empty() ? NULL :
	    inner_arrays.data(), inner_sizes.empty() ? NULL :
	    inner_sizes.data(), inner_arrays.size(), NULL, 0,
	    triangulation_points, points.size(), TRI_CONSTRAINED_DELAUNAY);
	if (triangulation_result != 0 || triangle_count < 1 ||
	    triangles == NULL)
	{
	    if (triangles != NULL) {
		bu_free(triangles, "Boolean interior triangles");
	    }
	    bu_free(triangulation_points,
		"Boolean interior triangulation points");
	    if (requested_error <= minimum_requested_error) {
		return false;
	    }
	    requested_error = std::max(minimum_requested_error,
		requested_error / 4.0);
	    continue;
	}

	const double required_clearance = approximation_error +
	    4.0 * roundoff_tolerance;
	bool found = false;
	double best_clearance = 0.0;
	ON_2dPoint best_point = ON_2dPoint::UnsetPoint;
	for (int triangle_index = 0; triangle_index < triangle_count;
	     ++triangle_index)
	{
	    const size_t triangle_offset =
		static_cast<size_t>(triangle_index) * 3;
	    const int first = triangles[triangle_offset];
	    const int second = triangles[triangle_offset + 1];
	    const int third = triangles[triangle_offset + 2];
	    if (first < 0 || second < 0 || third < 0 ||
		static_cast<size_t>(first) >= points.size() ||
		static_cast<size_t>(second) >= points.size() ||
		static_cast<size_t>(third) >= points.size())
	    {
		continue;
	    }

	    const ON_2dPoint &a = points[first];
	    const ON_2dPoint &b = points[second];
	    const ON_2dPoint &c = points[third];
	    const double twice_area = std::fabs((b.x - a.x) * (c.y - a.y) -
		(b.y - a.y) * (c.x - a.x));
	    if (!(twice_area > 0.0) || !std::isfinite(twice_area)) {
		continue;
	    }

	    ON_2dPoint candidates[2];
	    candidates[0] = ON_2dPoint((a.x + b.x + c.x) / 3.0,
		(a.y + b.y + c.y) / 3.0);
	    const double a_weight = b.DistanceTo(c);
	    const double b_weight = a.DistanceTo(c);
	    const double c_weight = a.DistanceTo(b);
	    const double weight_sum = a_weight + b_weight + c_weight;
	    candidates[1] = weight_sum > 0.0 && std::isfinite(weight_sum) ?
		ON_2dPoint((a_weight * a.x + b_weight * b.x +
		    c_weight * c.x) / weight_sum,
		    (a_weight * a.y + b_weight * b.y +
		    c_weight * c.y) / weight_sum) : candidates[0];

	    for (size_t candidate_index = 0; candidate_index < 2;
		 ++candidate_index)
	    {
		double clearance = 0.0;
		if (certified_boolean_interior_polygon_point(
			candidates[candidate_index], outer_polygon,
			inner_polygons, required_clearance, clearance) &&
		    (!found || clearance > best_clearance))
		{
		    found = true;
		    best_clearance = clearance;
		    best_point = candidates[candidate_index];
		}
	    }
	}

	bu_free(triangles, "Boolean interior triangles");
	bu_free(triangulation_points,
	    "Boolean interior triangulation points");
	if (found) {
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Boolean certified polygon interior point (%.17g, %.17g), "
		    "clearance %.17g, curve error %.17g.\n", best_point.x,
		    best_point.y, best_clearance, approximation_error);
	    }
	    interior_point = best_point;
	    return true;
	}

	if (requested_error <= minimum_requested_error) {
	    return false;
	}
	requested_error = std::max(minimum_requested_error,
	    requested_error / 4.0);
    }

    return false;
}


static bool
boundary_adjacent_trimmed_face_interior_point(
    const TrimmedFace *tface,
    const ON_SimpleArray<ON_Curve *> &outer_loop,
    const ON_BoundingBox &bounds,
    ON_2dPoint &interior_point)
{
    static const double boundary_parameters[] = {0.25, 0.5, 0.75};
    static const unsigned int maximum_offset_steps =
	std::numeric_limits<double>::digits;
    static const double maximum_offset_fraction = 0.25;

    double minimum_offset = 0.0;
    if (!trimmed_face_strict_interior_tolerance(tface, minimum_offset) ||
	!bounds.IsValid())
    {
	return false;
    }
    const double maximum_dimension = std::max(bounds.m_max.x - bounds.m_min.x,
	bounds.m_max.y - bounds.m_min.y);
    if (!(maximum_dimension > 0.0) || !std::isfinite(maximum_dimension)) {
	return false;
    }
    const double maximum_offset = std::max(minimum_offset,
	maximum_offset_fraction * maximum_dimension);

    for (int curve_index = 0; curve_index < outer_loop.Count();
	 ++curve_index)
    {
	const ON_Curve *curve = outer_loop[curve_index];
	const ON_Interval domain = curve ? curve->Domain() :
	    ON_Interval::EmptyInterval;
	if (!domain.IsValid() || !(domain.Length() > 0.0)) {
	    continue;
	}
	for (size_t parameter_index = 0;
	     parameter_index < sizeof(boundary_parameters) /
	     sizeof(boundary_parameters[0]); ++parameter_index)
	{
	    const double parameter = domain.ParameterAt(
		boundary_parameters[parameter_index]);
	    const ON_2dPoint boundary_point = curve->PointAt(parameter);
	    const ON_3dVector tangent = curve->TangentAt(parameter);
	    ON_2dVector normal(-tangent.y, tangent.x);
	    if (!boundary_point.IsValid() || !normal.Unitize()) {
		continue;
	    }
	    for (int direction = -1; direction <= 1; direction += 2) {
		for (unsigned int offset_step = 0;
		     offset_step < maximum_offset_steps;
		     ++offset_step)
		{
		    const double offset = std::ldexp(maximum_offset,
			-static_cast<int>(offset_step));
		    const ON_2dPoint candidate = boundary_point +
			normal * (direction * offset);
		    if (candidate.IsValid() &&
			is_point_strictly_inside_trimmed_face(candidate, tface))
		    {
			interior_point = candidate;
			return true;
		    }
		    if (offset <= minimum_offset) {
			break;
		    }
		}
	    }
	}
    }

    return false;
}


static bool
arrangement_segments_can_coalesce(const CurveSegment &first,
    const CurveSegment &second)
{
    if (first.from.source_loop != second.from.source_loop ||
	first.reversed != second.reversed ||
	!first.to.HasSameTopologyNode(second.from) ||
	first.from.loop_index != first.to.loop_index ||
	first.to.loop_index != second.from.loop_index ||
	second.from.loop_index != second.to.loop_index ||
	first.from.loop_index < 0 ||
	first.from.loop_index >= first.orig_loop.Count() ||
	second.from.loop_index < 0 ||
	second.from.loop_index >= second.orig_loop.Count() ||
	first.orig_loop[first.from.loop_index] == NULL ||
	first.orig_loop[first.from.loop_index] !=
	    second.orig_loop[second.from.loop_index])
    {
	return false;
    }

    const double parameter_tolerance = std::max(
	first.tolerance.curve_parameter, second.tolerance.curve_parameter);
    if (fabs(first.to.curve_t - second.from.curve_t) >
	parameter_tolerance)
    {
	return false;
    }

    return first.reversed ?
	second.to.curve_t <= first.to.curve_t + parameter_tolerance :
	second.to.curve_t + parameter_tolerance >= first.to.curve_t;
}


static bool
arrangement_node_allows_coalescing(
    const BooleanArrangement &arrangement,
    size_t node_id)
{
    std::map<size_t, std::vector<BooleanArrangement::EndpointIncidence> >
	::const_iterator incidences = arrangement.endpoint_incidences.find(
	    node_id);
    if (incidences == arrangement.endpoint_incidences.end()) {
	return false;
    }

    size_t selected_incoming = 0;
    size_t selected_outgoing = 0;
    std::vector<size_t> selected_edges;
    for (size_t incidence_index = 0;
	 incidence_index < incidences->second.size(); ++incidence_index)
    {
	const BooleanArrangement::EndpointIncidence &incidence =
	    incidences->second[incidence_index];
	if (incidence.edge_index >= arrangement.edges.size() ||
	    !arrangement.edges[incidence.edge_index].selected)
	{
	    continue;
	}
	selected_edges.push_back(incidence.edge_index);
	if (incidence.outgoing) {
	    ++selected_outgoing;
	} else {
	    ++selected_incoming;
	}
    }

    if (selected_incoming != 1 || selected_outgoing != 1) {
	return false;
    }

    // Coincident input boundaries add unselected incidences at every overlap
    // subdivision.  Ignore only incidences certified as members of the same
    // coincident group as a selected edge.  A noncoincident unselected edge is
    // a genuine arrangement transition (for example, the end of an SSI span)
    // and its topology node must survive output-curve coalescing.
    for (size_t incidence_index = 0;
	 incidence_index < incidences->second.size(); ++incidence_index)
    {
	const BooleanArrangement::EndpointIncidence &incidence =
	    incidences->second[incidence_index];
	if (incidence.edge_index >= arrangement.edges.size() ||
	    arrangement.edges[incidence.edge_index].selected)
	{
	    continue;
	}

	const size_t coincident_group =
	    arrangement.edges[incidence.edge_index].coincident_group;
	bool coincident_with_result = false;
	for (size_t selected_index = 0;
	     coincident_group != BooleanArrangement::UNSET_EDGE &&
	     selected_index < selected_edges.size();
	     ++selected_index)
	{
	    if (arrangement.edges[selected_edges[selected_index]].
		    coincident_group == coincident_group)
	    {
		coincident_with_result = true;
		break;
	    }
	}
	if (!coincident_with_result) {
	    return false;
	}
    }

    return true;
}


static bool
report_arrangement_construction_failure(
    const BooleanArrangement &arrangement,
    size_t current_edge,
    const char *reason)
{
    record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_TRIM_ARRANGEMENT,
	BREP_BOOLEAN_FAILURE_REASON_ARRANGEMENT_OPEN_LOOP, -1, -1,
	static_cast<int>(current_edge));
    size_t remaining = 0;
    size_t reported = 0;
    const size_t report_limit = 64;
    bu_log("loop_boolean: arrangement loop construction failed at edge %zu: "
	"%s.\n", current_edge, reason);
    for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	 ++edge_index)
    {
	const BooleanArrangement::Edge &edge = arrangement.edges[edge_index];
	if (!edge.selected || edge.consumed)
	    continue;
	++remaining;
	if (reported >= report_limit)
	    continue;
	++reported;
	bu_log("loop_boolean: unconsumed selected edge %zu: source loop %d "
	    "curve %d, node %zu -> %zu, parameter %.17g -> %.17g, next %zu, "
	    "coincident group %zu, reason %s.\n", edge_index,
	    edge.segment.from.source_loop, edge.segment.from.loop_index,
	    edge.segment.from.node_id, edge.segment.to.node_id,
	    edge.segment.from.curve_t, edge.segment.to.curve_t,
	    edge.next_edge, edge.coincident_group, edge.selection_reason);
    }
    if (reported < remaining) {
	bu_log("loop_boolean: %zu additional unconsumed selected arrangement "
	    "edges omitted from diagnostics.\n", remaining - reported);
    }
    return false;
}


static bool
construct_loops_from_arrangement(BooleanArrangement &arrangement,
    std::list<ON_SimpleArray<ON_Curve *> > &out)
{
    for (;;) {
	size_t first_edge = BooleanArrangement::UNSET_EDGE;
	for (size_t edge_index = 0; edge_index < arrangement.edges.size();
	     ++edge_index)
	{
	    if (arrangement.edges[edge_index].selected &&
		!arrangement.edges[edge_index].consumed)
	    {
		first_edge = edge_index;
		break;
	    }
	}
	if (first_edge == BooleanArrangement::UNSET_EDGE) {
	    return true;
	}

	std::vector<size_t> loop_edges;
	std::set<size_t> visited_edges;
	size_t current_edge = first_edge;
	loop_edges.push_back(current_edge);
	visited_edges.insert(current_edge);

	const CurvePoint start = arrangement.edges[current_edge].segment.from;
	bool closed = start.
	    HasSameTopologyNode(arrangement.edges[current_edge].segment.to);
	while (!closed) {
	    const size_t successor = arrangement.edges[current_edge].next_edge;
	    if (successor == BooleanArrangement::UNSET_EDGE ||
		successor >= arrangement.edges.size())
	    {
		free_constructed_boolean_loops(out);
		return report_arrangement_construction_failure(arrangement,
		    current_edge, "successor is missing or invalid");
	    }
	    const BooleanArrangement::Edge &successor_edge =
		arrangement.edges[successor];
	    if (!successor_edge.selected) {
		free_constructed_boolean_loops(out);
		return report_arrangement_construction_failure(arrangement,
		    current_edge, "successor is not selected");
	    }
	    if (successor_edge.consumed) {
		free_constructed_boolean_loops(out);
		return report_arrangement_construction_failure(arrangement,
		    current_edge, "successor belongs to an earlier result loop");
	    }
	    if (!arrangement.edges[current_edge].segment.to.HasSameTopologyNode(
		    successor_edge.segment.from))
	    {
		free_constructed_boolean_loops(out);
		return report_arrangement_construction_failure(arrangement,
		    current_edge, "successor endpoints do not share a topology node");
	    }
	    if (visited_edges.find(successor) != visited_edges.end()) {
		free_constructed_boolean_loops(out);
		return report_arrangement_construction_failure(arrangement,
		    current_edge, "transition cycle does not return to its start node");
	    }
	    current_edge = successor;
	    loop_edges.push_back(current_edge);
	    visited_edges.insert(current_edge);
	    closed = start.HasSameTopologyNode(
		arrangement.edges[current_edge].segment.to);
	}

	ON_SimpleArray<ON_Curve *> loop;
	size_t previous_output_edge = BooleanArrangement::UNSET_EDGE;
	size_t degree_blocked_coalesces = 0;
	size_t provenance_blocked_coalesces = 0;
	size_t coalesced_edges = 0;
	for (size_t edge_offset = 0; edge_offset < loop_edges.size();
	     ++edge_offset)
	{
	    CurveSegment segment = arrangement.edges[
		loop_edges[edge_offset]].segment;
	    size_t last_offset = edge_offset;
	    while (last_offset + 1 < loop_edges.size()) {
		if (!arrangement_node_allows_coalescing(arrangement,
			segment.to.node_id))
		{
		    ++degree_blocked_coalesces;
		    break;
		}
		if (!arrangement_segments_can_coalesce(segment,
			arrangement.edges[loop_edges[last_offset + 1]].segment))
		{
		    ++provenance_blocked_coalesces;
		    break;
		}
		++last_offset;
		++coalesced_edges;
		segment.to = arrangement.edges[loop_edges[last_offset]].segment.to;
	    }

	    ON_Curve *curve = NULL;
	    try {
		curve = segment.Curve();
	    } catch (...) {
		free_constructed_boolean_loop(loop);
		free_constructed_boolean_loops(out);
		return report_arrangement_construction_failure(arrangement,
		    loop_edges[edge_offset], "selected edge curve generation threw");
	    }
	    if (curve == NULL) {
		free_constructed_boolean_loop(loop);
		free_constructed_boolean_loops(out);
		return report_arrangement_construction_failure(arrangement,
		    loop_edges[edge_offset], "selected edge curve generation failed");
	    }
	    if (DEBUG_BREP_BOOLEAN && loop.Count() > 0) {
		const double gap = (*loop.Last())->PointAtEnd().DistanceTo(
		    curve->PointAtStart());
		if (gap >= ON_ZERO_TOLERANCE) {
		    const BooleanArrangement::Edge &previous_edge =
			arrangement.edges[previous_output_edge];
		    const BooleanArrangement::Edge &current_output_edge =
			arrangement.edges[loop_edges[edge_offset]];
		    bu_log("loop_boolean: generated output junction gap %.17g at "
			"topology node %zu/%zu, edges %zu/%zu, source loops %d/%d, "
			"curves %d/%d, parameters %.17g/%.17g.\n", gap,
			previous_edge.segment.to.node_id,
			current_output_edge.segment.from.node_id,
			previous_output_edge, loop_edges[edge_offset],
			previous_edge.segment.to.source_loop,
			current_output_edge.segment.from.source_loop,
			previous_edge.segment.to.loop_index,
			current_output_edge.segment.from.loop_index,
			previous_edge.segment.to.curve_t,
			current_output_edge.segment.from.curve_t);
		}
	    }
	    loop.Append(curve);
	    previous_output_edge = loop_edges[last_offset];
	    edge_offset = last_offset;
	}
	for (size_t edge_offset = 0; edge_offset < loop_edges.size();
	     ++edge_offset)
	{
	    arrangement.edges[loop_edges[edge_offset]].consumed = true;
	}
	if (loop_edges.size() > 64) {
	    bu_log("loop_boolean: result loop retained %d curves from %zu edges "
		"(%zu coalesced, %zu degree-blocked, %zu provenance-blocked).\n",
		loop.Count(), loop_edges.size(), coalesced_edges,
		degree_blocked_coalesces, provenance_blocked_coalesces);
	}
	out.push_back(loop);
    }
}


static ON_2dPoint
get_point_inside_trimmed_face(const TrimmedFace *tface)
{
    const int GP_MAX_STEPS = 8; // must be a power of two

    NormalizedBooleanLoop normalized_loop;
    const ON_SimpleArray<ON_Curve *> &outer_loop =
	normalized_trimmed_face_loop(tface, tface->m_outerloop,
	    normalized_loop);

    ON_PolyCurve polycurve;
    if (!is_loop_valid(outer_loop, ON_ZERO_TOLERANCE, &polycurve)) {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_Surface *surface = tface->m_face->SurfaceOf();
	    for (int curve_index = 0; curve_index < outer_loop.Count();
		 ++curve_index)
	    {
		const ON_Curve *curve = outer_loop[curve_index];
		const ON_Curve *next_curve = outer_loop[
		    (curve_index + 1) % outer_loop.Count()];
		if (curve == NULL || next_curve == NULL)
		    continue;
		const ON_3dPoint curve_end = curve->PointAtEnd();
		const ON_3dPoint next_start = next_curve->PointAtStart();
		const ON_3dPoint model_end = surface ? surface->PointAt(
		    curve_end.x, curve_end.y) : ON_3dPoint::UnsetPoint;
		const ON_3dPoint model_start = surface ? surface->PointAt(
		    next_start.x, next_start.y) : ON_3dPoint::UnsetPoint;
		bu_log("face_brep_location: outer curve %d gap %.17g, model "
		    "gap %.17g, UV (%.17g, %.17g) -> (%.17g, %.17g).\n",
		    curve_index, curve_end.DistanceTo(next_start),
		    model_end.DistanceTo(model_start), curve_end.x,
		    curve_end.y, next_start.x, next_start.y);
	    }
	}
	throw InvalidGeometry("face_brep_location(): invalid outerloop.\n");
    }
    ON_BoundingBox bbox =  polycurve.BoundingBox();
    double u_len = bbox.m_max.x - bbox.m_min.x;
    double v_len = bbox.m_max.y - bbox.m_min.y;

    ON_2dPoint test_pt2d;
    bool found = false;
    for (int steps = 1; steps <= GP_MAX_STEPS && !found; steps *= 2) {
	double u_halfstep = u_len / (steps * 2.0);
	double v_halfstep = v_len / (steps * 2.0);

	for (int i = 0; i < steps && !found; ++i) {
	    test_pt2d.x = bbox.m_min.x + u_halfstep * (1 + 2 * i);

	    for (int j = 0; j < steps && !found; ++j) {
		test_pt2d.y = bbox.m_min.y + v_halfstep * (1 + 2 * j);
		found = is_point_strictly_inside_trimmed_face(test_pt2d, tface);
	    }
	}
    }
    if (found) {
        return test_pt2d;
    }

    ON_2dPoint paired_boundary_point;
    if (paired_boundary_trimmed_face_interior_point(tface, outer_loop,
	paired_boundary_point))
    {
	return paired_boundary_point;
    }

    // A direct sample is sufficient for face classification and avoids
    // triangulating ordinary loops solely to obtain one interior point.
    ON_2dPoint triangulated_point;
    if (triangulated_trimmed_face_interior_point(tface, triangulated_point)) {
        return triangulated_point;
    }

    ON_2dPoint boundary_adjacent_point;
    if (boundary_adjacent_trimmed_face_interior_point(tface, outer_loop, bbox,
	boundary_adjacent_point))
    {
	return boundary_adjacent_point;
    }

    throw AlgorithmError("Cannot find a point inside this trimmed face. Aborted.\n");
}


// Returns the location of the face with respect to the brep.
//
// Throws InvalidGeometry if given invalid arguments.
// Throws AlgorithmError if a point inside the TrimmedFace can't be
// found for testing.
static int
trimmed_face_point_brep_location(const ON_2dPoint &parameter,
    const TrimmedFace *tface, const ON_Brep *brep,
    ON_SimpleArray<Subsurface *> &surf_tree,
    const ON_BoundingBox &brep_bbox)
{
    if (!parameter.IsValid() || tface == NULL || tface->m_face == NULL) {
	return INDETERMINATE_BREP;
    }

    const ON_3dPoint point = tface->m_face->PointAt(parameter.x, parameter.y);
    if (!point.IsValid()) {
	return INDETERMINATE_BREP;
    }

    const int surface_location = point_brep_surface_location(point, brep,
	 surf_tree, brep_bbox);
    if (surface_location != OUTSIDE_BREP) {
	return surface_location;
    }
    return point_brep_location(point, brep, surf_tree, brep_bbox);
}


static int
fallback_trimmed_face_brep_location(const TrimmedFace *tface,
    const ON_Brep *brep, ON_SimpleArray<Subsurface *> &surf_tree,
    const ON_BoundingBox &brep_bbox, const ON_BoundingBox &parameter_bbox,
    ON_2dPoint *classification_parameter)
{
    static const int maximum_grid_steps = 8;
    static const int required_consistent_samples = 2;
    int location = INDETERMINATE_BREP;
    int consistent_samples = 0;

    const double u_length = parameter_bbox.m_max.x - parameter_bbox.m_min.x;
    const double v_length = parameter_bbox.m_max.y - parameter_bbox.m_min.y;
    if (!(u_length > 0.0) || !(v_length > 0.0)) {
	return INDETERMINATE_BREP;
    }

    for (int steps = 2; steps <= maximum_grid_steps; steps *= 2) {
	const double u_half_step = u_length / (2.0 * steps);
	const double v_half_step = v_length / (2.0 * steps);
	for (int u_index = 0; u_index < steps; ++u_index) {
	    for (int v_index = 0; v_index < steps; ++v_index) {
		const ON_2dPoint parameter(
		    parameter_bbox.m_min.x + u_half_step * (1 + 2 * u_index),
		    parameter_bbox.m_min.y + v_half_step * (1 + 2 * v_index));
		if (!is_point_strictly_inside_trimmed_face(parameter, tface)) {
		    continue;
		}

		const int candidate_location = trimmed_face_point_brep_location(
		    parameter, tface, brep, surf_tree, brep_bbox);
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("face_brep_location: fallback UV (%.17g, %.17g) "
			"has location %d.\n", parameter.x, parameter.y,
			candidate_location);
		}
		if (candidate_location == INDETERMINATE_BREP) {
		    continue;
		}
		if (location != INDETERMINATE_BREP &&
		    candidate_location != location)
		{
		    return INDETERMINATE_BREP;
		}
		location = candidate_location;
		if (++consistent_samples >= required_consistent_samples) {
		    if (classification_parameter != NULL) {
			*classification_parameter = parameter;
		    }
		    return location;
		}
	    }
	}
    }

    return INDETERMINATE_BREP;
}


static int
face_brep_location(const TrimmedFace *tface, const ON_Brep *brep,
		   ON_SimpleArray<Subsurface *> &surf_tree,
		   const ON_BoundingBox &brep_bbox,
		   ON_2dPoint *classification_parameter)
{
    if (classification_parameter != NULL) {
	*classification_parameter = ON_2dPoint::UnsetPoint;
    }
    if (tface == NULL || brep == NULL) {
	throw InvalidGeometry("face_brep_location(): given NULL argument.\n");
    }

    const ON_BrepFace *bface = tface->m_face;
    if (bface == NULL) {
	throw InvalidGeometry("face_brep_location(): TrimmedFace has NULL face.\n");
    }

    ON_BoundingBox brep2box = brep_bbox;
    if (!brep2box.IsValid()) {
	return INDETERMINATE_BREP;
    }
    brep2box.m_min -= ON_3dVector(INTERSECTION_TOL, INTERSECTION_TOL, INTERSECTION_TOL);
    brep2box.m_max += ON_3dVector(INTERSECTION_TOL, INTERSECTION_TOL, INTERSECTION_TOL);
    if (!bface->BoundingBox().Intersection(brep2box)) {
	return OUTSIDE_BREP;
    }

    if (tface->m_outerloop.Count() == 0) {
	throw InvalidGeometry("face_brep_location(): the input TrimmedFace is not trimmed.\n");
    }

    NormalizedBooleanLoop normalized_loop;
    const ON_SimpleArray<ON_Curve *> &outer_loop =
	normalized_trimmed_face_loop(tface, tface->m_outerloop,
	    normalized_loop);

    ON_PolyCurve polycurve;
    if (!is_loop_valid(outer_loop, ON_ZERO_TOLERANCE, &polycurve)) {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_Surface *surface = tface->m_face->SurfaceOf();
	    for (int curve_index = 0; curve_index < outer_loop.Count();
		 ++curve_index)
	    {
		const ON_Curve *curve = outer_loop[curve_index];
		const ON_Curve *next_curve = outer_loop[
		    (curve_index + 1) % outer_loop.Count()];
		if (curve == NULL || next_curve == NULL)
		    continue;
		const ON_3dPoint curve_end = curve->PointAtEnd();
		const ON_3dPoint next_start = next_curve->PointAtStart();
		const ON_3dPoint model_end = surface ? surface->PointAt(
		    curve_end.x, curve_end.y) : ON_3dPoint::UnsetPoint;
		const ON_3dPoint model_start = surface ? surface->PointAt(
		    next_start.x, next_start.y) : ON_3dPoint::UnsetPoint;
		bu_log("face_brep_location: classification outer curve %d gap "
		    "%.17g, model gap %.17g, UV (%.17g, %.17g) -> "
		    "(%.17g, %.17g).\n", curve_index,
		    curve_end.DistanceTo(next_start),
		    model_end.DistanceTo(model_start), curve_end.x,
		    curve_end.y, next_start.x, next_start.y);
	    }
	}
	throw InvalidGeometry("face_brep_location(): invalid outerloop.\n");
    }
    ON_2dPoint test_pt2d = get_point_inside_trimmed_face(tface);
    ON_3dPoint test_pt3d = tface->m_face->PointAt(test_pt2d.x, test_pt2d.y);

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("valid test point: (%g, %g, %g)\n", test_pt3d.x, test_pt3d.y, test_pt3d.z);
    }

    const int location = trimmed_face_point_brep_location(test_pt2d, tface,
	brep, surf_tree, brep_bbox);
    if (location == ON_BREP_SURFACE) {
	// because the overlap parts will be split out as separated trimmed
	// faces, if one point on a trimmed face is on the brep's surface,
	// the whole trimmed face should be on the surface
	if (classification_parameter != NULL) {
	    *classification_parameter = test_pt2d;
	}
	return ON_BREP_SURFACE;
    }
    if (location != INDETERMINATE_BREP) {
	if (classification_parameter != NULL) {
	    *classification_parameter = test_pt2d;
	}
	return location;
    }

    return fallback_trimmed_face_brep_location(tface, brep, surf_tree,
	brep_bbox, polycurve.BoundingBox(), classification_parameter);
}


struct BooleanFaceClassification {
    std::set<int> m_final_faces;
    std::set<int> m_discarded_faces;
    std::set<int> m_preserved_faces;
    std::set<int> m_nonpreservable_faces;
};


struct BooleanPreservedComponent {
    const ON_Brep *m_brep;
    std::vector<int> m_face_indices;

    BooleanPreservedComponent(
	const ON_Brep *brep,
	const std::vector<int> &face_indices)
	: m_brep(brep),
	  m_face_indices(face_indices)
    {
    }
};


static void
classify_component_disjoint_boolean_face(
    BooleanFaceClassification &classification,
    int face_index,
    bool first_operand,
    op_type operation)
{
    switch (operation) {
	case BOOLEAN_UNION:
	case BOOLEAN_XOR:
	    classification.m_final_faces.insert(face_index);
	    break;
	case BOOLEAN_DIFF:
	    if (first_operand) {
		classification.m_final_faces.insert(face_index);
	    } else {
		classification.m_discarded_faces.insert(face_index);
	    }
	    break;
	case BOOLEAN_INTERSECT:
	    classification.m_discarded_faces.insert(face_index);
	    break;
	default:
	    throw InvalidBooleanOperation("Error - unknown boolean operation\n");
    }
}


static bool
boolean_face_requires_intersection(
    const BooleanFaceClassification &classification,
    int face_index)
{
    return classification.m_final_faces.find(face_index) ==
	classification.m_final_faces.end() &&
	classification.m_discarded_faces.find(face_index) ==
	classification.m_discarded_faces.end();
}


static bool
boolean_component_is_disjoint_from_bounds(
    const ON_BoundingBox &component_bbox,
    const std::vector<ON_BoundingBox> &other_component_bboxes)
{
    if (other_component_bboxes.empty()) {
	return false;
    }

    for (size_t component_index = 0;
	 component_index < other_component_bboxes.size();
	 ++component_index)
    {
	if (component_bbox.MinimumDistanceTo(
		other_component_bboxes[component_index]) <= INTERSECTION_TOL)
	{
	    return false;
	}
    }

    return true;
}


static bool
boolean_disjoint_component_is_preserved(
    bool first_operand,
    op_type operation)
{
    return operation == BOOLEAN_UNION || operation == BOOLEAN_XOR ||
	(operation == BOOLEAN_DIFF && first_operand);
}


static void
classify_disjoint_boolean_components(
    const ON_Brep *brep,
    const std::vector<ON_BoundingBox> &component_bboxes,
    const std::vector<std::vector<int> > &component_face_indices,
    const std::vector<ON_BoundingBox> &other_component_bboxes,
    int face_offset,
    bool first_operand,
    op_type operation,
    BooleanFaceClassification &classification,
    std::vector<BooleanPreservedComponent> &preserved_components)
{
    if (brep == NULL || component_bboxes.size() !=
	component_face_indices.size())
    {
	return;
    }

    for (size_t component_index = 0;
	 component_index < component_bboxes.size();
	 ++component_index)
    {
	if (!boolean_component_is_disjoint_from_bounds(
		component_bboxes[component_index], other_component_bboxes))
	{
	    continue;
	}

	const std::vector<int> &face_indices =
	    component_face_indices[component_index];
	bool valid_component = !face_indices.empty();
	for (size_t face_offset_index = 0;
	     face_offset_index < face_indices.size() && valid_component;
	     ++face_offset_index)
	{
	    valid_component = face_indices[face_offset_index] >= 0 &&
		face_indices[face_offset_index] < brep->m_F.Count();
	}
	if (!valid_component) {
	    continue;
	}

	const bool preserve = boolean_disjoint_component_is_preserved(
	    first_operand, operation);
	for (size_t face_offset_index = 0;
	     face_offset_index < face_indices.size();
	     ++face_offset_index)
	{
	    const int face_index = face_offset + face_indices[face_offset_index];
	    classify_component_disjoint_boolean_face(classification, face_index,
		first_operand, operation);
	    if (preserve) {
		classification.m_preserved_faces.insert(face_index);
	    }
	}
	if (preserve) {
	    preserved_components.push_back(BooleanPreservedComponent(brep,
		face_indices));
	}
    }
}


static bool
is_boolean_ssi_curve_event(const ON_SSX_EVENT &event)
{
    return event.m_type == ON_SSX_EVENT::ssx_tangent ||
	event.m_type == ON_SSX_EVENT::ssx_transverse ||
	event.m_type == ON_SSX_EVENT::ssx_overlap;
}


static bool
ssi_parameter_curves_share_locus(
    const ON_Curve *first,
    const ON_Curve *second,
    const ON_Surface *surface)
{
    if (first == NULL || second == NULL || surface == NULL) {
	return false;
    }

    std::unique_ptr<ON_Curve> first_parameter(
	boolean_surface_parameter_curve(*first));
    std::unique_ptr<ON_Curve> second_parameter(
	boolean_surface_parameter_curve(*second));
    if (!first_parameter || !second_parameter) {
	return false;
    }

    double first_point_tolerance = 0.0;
    double first_curve_tolerance = 0.0;
    double second_point_tolerance = 0.0;
    double second_curve_tolerance = 0.0;
    if (!get_face_boundary_curve_tolerances(surface, first_parameter.get(),
	    first_point_tolerance, first_curve_tolerance) ||
	!get_face_boundary_curve_tolerances(surface, second_parameter.get(),
	    second_point_tolerance, second_curve_tolerance))
    {
	return false;
    }

    const double parameter_tolerance = std::max(first_point_tolerance,
	second_point_tolerance);
    return curves_match_shared_parameter_curve(first_parameter.get(),
	second_parameter.get(), parameter_tolerance);
}


static double
ssi_event_triplet_lift_error(
    const ON_SSX_EVENT &event,
    const ON_Surface *first_surface,
    const ON_Surface *second_surface)
{
    if (event.m_curve3d == NULL || event.m_curveA == NULL ||
	event.m_curveB == NULL || first_surface == NULL ||
	second_surface == NULL)
    {
	return std::numeric_limits<double>::infinity();
    }

    std::unique_ptr<ON_Curve> first_parameter(
	boolean_surface_parameter_curve(*event.m_curveA));
    std::unique_ptr<ON_Curve> second_parameter(
	boolean_surface_parameter_curve(*event.m_curveB));
    if (!first_parameter || !second_parameter) {
	return std::numeric_limits<double>::infinity();
    }

    const double first_error = std::min(
	parameter_curve_lift_maximum_error(first_surface,
	    first_parameter.get(), event.m_curve3d, false),
	parameter_curve_lift_maximum_error(first_surface,
	    first_parameter.get(), event.m_curve3d, true));
    const double second_error = std::min(
	parameter_curve_lift_maximum_error(second_surface,
	    second_parameter.get(), event.m_curve3d, false),
	parameter_curve_lift_maximum_error(second_surface,
	    second_parameter.get(), event.m_curve3d, true));
    return std::max(first_error, second_error);
}


static std::vector<bool>
duplicate_closed_ssi_events(
    const ON_ClassArray<ON_SSX_EVENT> &events,
    const ON_Surface *first_surface,
    const ON_Surface *second_surface)
{
    std::vector<bool> duplicate(static_cast<size_t>(events.Count()), false);
    std::vector<double> lift_errors(static_cast<size_t>(events.Count()),
	std::numeric_limits<double>::infinity());
    for (int event_index = 0; event_index < events.Count(); ++event_index) {
	const ON_SSX_EVENT &event = events[event_index];
	if (!is_boolean_ssi_curve_event(event) || event.m_curve3d == NULL ||
	    event.m_curveA == NULL || event.m_curveB == NULL ||
	    !event.m_curve3d->IsClosed())
	{
	    continue;
	}
	lift_errors[event_index] = ssi_event_triplet_lift_error(event,
	    first_surface, second_surface);
    }

    for (int first_index = 0; first_index < events.Count(); ++first_index) {
	const ON_SSX_EVENT &first = events[first_index];
	if (duplicate[first_index] || !is_boolean_ssi_curve_event(first) ||
	    first.m_curve3d == NULL || first.m_curveA == NULL ||
	    first.m_curveB == NULL || !first.m_curve3d->IsClosed())
	{
	    continue;
	}

	for (int second_index = first_index + 1;
	     second_index < events.Count(); ++second_index)
	{
	    const ON_SSX_EVENT &second = events[second_index];
	    if (duplicate[second_index] || !is_boolean_ssi_curve_event(second) ||
		second.m_curve3d == NULL || second.m_curveA == NULL ||
		second.m_curveB == NULL || !second.m_curve3d->IsClosed())
	    {
		continue;
	    }

	    /* Two closed SSI records that trace the same parameter-space locus
	     * on either source surface describe one intersection.  Some solvers
	     * return both a faithful curve triplet and a lower-quality
	     * approximation at a trimmed-surface boundary.  Feeding both into
	     * face splitting creates artificial sliver loops, so retain the
	     * triplet whose two parameter curves best lift to its model curve. */
	    const bool first_parameter_locus =
		ssi_parameter_curves_share_locus(first.m_curveA,
		    second.m_curveA, first_surface);
	    const bool second_parameter_locus =
		ssi_parameter_curves_share_locus(first.m_curveB,
		    second.m_curveB, second_surface);
	    if (!first_parameter_locus && !second_parameter_locus)
	    {
		continue;
	    }

	    if (lift_errors[second_index] + ON_ZERO_TOLERANCE <
		lift_errors[first_index])
	    {
		duplicate[first_index] = true;
		break;
	    }
	    duplicate[second_index] = true;
	}
    }
    return duplicate;
}


/* General SSI refinement can become ill-conditioned when two spheres overlap
 * in a shallow cap: the true intersection is a resolved circle, but sampled
 * surface curves may converge to two distinct, interior circles.  OpenNURBS
 * can recognize exact spherical NURBS surfaces and intersect their analytic
 * representations directly.  Build synchronized parameter curves from that
 * authoritative circle so the Boolean splitter never has to classify an
 * unsplit whole sphere from a point inside the shallow overlap. */
static bool
append_exact_sphere_sphere_ssi_event(
    const ON_Surface *first_surface,
    const ON_Surface *second_surface,
    ON_ClassArray<ON_SSX_EVENT> &events)
{
    if (first_surface == NULL || second_surface == NULL)
	return false;

    const auto recognized_sphere = [](const ON_Surface *surface,
	ON_Sphere &sphere) {
	if (surface->IsSphere(&sphere, INTERSECTION_TOL) && sphere.IsValid())
	    return true;
	const ON_RevSurface *revolution = ON_RevSurface::Cast(surface);
	if (revolution != NULL &&
	    revolution->IsSpherical(&sphere, INTERSECTION_TOL) &&
	    sphere.IsValid())
	{
	    return true;
	}
	/* ON_RevSurface::IsSpherical() constructs its recognition plane from
	 * the profile midpoint.  The standard ON_BrepSphere profile has that
	 * midpoint on the revolution axis, so the constructed plane is
	 * degenerate even though the profile itself is an exact semicircle.
	 * Recognize that representation directly from its generating arc. */
	if (revolution != NULL && revolution->m_curve != NULL) {
	    ON_Arc profile;
	    ON_3dVector axis_direction = revolution->m_axis.Tangent();
	    const bool profile_arc = revolution->m_curve->IsArc(NULL,
		&profile, INTERSECTION_TOL);
	    const bool axis_valid = axis_direction.Unitize();
	    const bool profile_normal_valid = profile_arc &&
		profile.plane.zaxis.Unitize();
	    if (profile_arc && axis_valid && profile_normal_valid)
	    {
		const ON_3dPoint center = profile.Center();
		const ON_3dPoint axis_center =
		    revolution->m_axis.ClosestPointTo(center);
		const double plane_error = profile.Radius() * fabs(
		    ON_DotProduct(axis_direction, profile.plane.zaxis));
		if (center.DistanceTo(axis_center) <= INTERSECTION_TOL &&
		    plane_error <= INTERSECTION_TOL)
		{
		    sphere.plane.origin = center;
		    sphere.plane.zaxis = axis_direction;
		    sphere.plane.yaxis = profile.plane.zaxis;
		    sphere.plane.xaxis = ON_CrossProduct(
			sphere.plane.yaxis, sphere.plane.zaxis);
		    sphere.plane.UpdateEquation();
		    sphere.radius = profile.Radius();
		    if (sphere.IsValid())
			return true;
		}
	    }
	}
	ON_NurbsSurface nurbs;
	const bool nurbs_sphere = surface->GetNurbForm(nurbs) > 0 &&
	    nurbs.IsSphere(&sphere, INTERSECTION_TOL);
	return nurbs_sphere && sphere.IsValid();
    };

    ON_Sphere first_sphere;
    ON_Sphere second_sphere;
    if (!recognized_sphere(first_surface, first_sphere) ||
	!recognized_sphere(second_surface, second_sphere) ||
	!first_sphere.IsValid() || !second_sphere.IsValid())
    {
	return false;
    }

    ON_Circle intersection_circle;
    const int sphere_intersection = ON_Intersect(first_sphere, second_sphere,
	intersection_circle);
    if (sphere_intersection != 2 ||
	!intersection_circle.IsValid() ||
	intersection_circle.Radius() <= INTERSECTION_TOL)
    {
	return false;
    }

    std::unique_ptr<ON_Curve> model_curve(
	new ON_ArcCurve(intersection_circle));
    if (!model_curve || !model_curve->IsValid() || !model_curve->IsClosed() ||
	!model_curve->SetDomain(0.0, 1.0))
    {
	return false;
    }

    std::unique_ptr<ON_Curve> first_parameter(
	synchronized_surface_parameter_curve(first_surface, *model_curve,
	    INTERSECTION_TOL));
    std::unique_ptr<ON_Curve> second_parameter(
	synchronized_surface_parameter_curve(second_surface, *model_curve,
	    INTERSECTION_TOL));
    int first_orientation = -1;
    int second_orientation = -1;
    if (!first_parameter || !second_parameter ||
	!parameter_curve_lifts_to_model_curve(first_surface,
	    first_parameter.get(), model_curve.get(), INTERSECTION_TOL,
	    &first_orientation) ||
	!parameter_curve_lifts_to_model_curve(second_surface,
	    second_parameter.get(), model_curve.get(), INTERSECTION_TOL,
	    &second_orientation) ||
	first_orientation != second_orientation)
    {
	return false;
    }

    /* A closed model-space circle can cross a periodic surface seam.  Its
     * continuous, unwrapped parameter curve then necessarily leaves the
     * canonical surface domain.  Split at every such crossing and translate
     * each open piece back into the canonical domain; otherwise face clipping
     * retains only the half of the circle on one side of the seam. */
    const ON_PolylineCurve *first_polyline =
	ON_PolylineCurve::Cast(first_parameter.get());
    const ON_PolylineCurve *second_polyline =
	ON_PolylineCurve::Cast(second_parameter.get());
    if (first_polyline == NULL || second_polyline == NULL)
	return false;

    const ON_Interval model_domain = model_curve->Domain();
    const double model_parameter_tolerance = std::max(ON_ZERO_TOLERANCE,
	64.0 * ON_EPSILON * std::max(1.0, model_domain.Length()));
    std::vector<double> split_parameters;
    split_parameters.push_back(model_domain.Min());
    split_parameters.push_back(model_domain.Max());
    const auto collect_seam_crossings = [&split_parameters, &model_domain,
	model_parameter_tolerance](const ON_Surface *surface,
	    const ON_PolylineCurve *parameter_curve) {
	if (surface == NULL || parameter_curve == NULL ||
	    parameter_curve->m_pline.Count() != parameter_curve->m_t.Count() ||
	    parameter_curve->m_pline.Count() < 2)
	{
	    return false;
	}
	for (int direction = 0; direction < 2; ++direction) {
	    if (!surface->IsClosed(direction) &&
		!surface->IsPeriodic(direction))
	    {
		continue;
	    }
	    ON_Interval surface_domain = surface->Domain(direction);
	    surface_domain.MakeIncreasing();
	    const double period = surface_domain.Length();
	    if (!surface_domain.IsIncreasing() ||
		!(period > ON_ZERO_TOLERANCE))
	    {
		return false;
	    }
	    for (int point_index = 1;
		 point_index < parameter_curve->m_pline.Count(); ++point_index)
	    {
		const double first =
		    parameter_curve->m_pline[point_index - 1][direction];
		const double second =
		    parameter_curve->m_pline[point_index][direction];
		const double first_parameter =
		    parameter_curve->m_t[point_index - 1];
		const double second_parameter = parameter_curve->m_t[point_index];
		if (!std::isfinite(first) || !std::isfinite(second) ||
		    !std::isfinite(first_parameter) ||
		    !std::isfinite(second_parameter) ||
		    !(second_parameter > first_parameter))
		{
		    return false;
		}
		const double delta = second - first;
		if (fabs(delta) <= ON_ZERO_TOLERANCE)
		    continue;
		const double lower = std::min(first, second);
		const double upper = std::max(first, second);
		const double coordinate_scale = std::max(1.0, std::max(
		    fabs(lower), std::max(fabs(upper), period)));
		const double coordinate_tolerance = std::max(ON_ZERO_TOLERANCE,
		    64.0 * ON_EPSILON * coordinate_scale);
		const double minimum_multiple = std::ceil(
		    (lower - surface_domain.Min() - coordinate_tolerance) /
		    period);
		const double maximum_multiple = std::floor(
		    (upper - surface_domain.Min() + coordinate_tolerance) /
		    period);
		if (!std::isfinite(minimum_multiple) ||
		    !std::isfinite(maximum_multiple) ||
		    maximum_multiple - minimum_multiple > 16.0)
		{
		    return false;
		}
		for (int multiple = static_cast<int>(minimum_multiple);
		     multiple <= static_cast<int>(maximum_multiple); ++multiple)
		{
		    const double boundary = surface_domain.Min() +
			multiple * period;
		    const double fraction = (boundary - first) / delta;
		    if (fraction < 0.0 || fraction > 1.0)
			continue;
		    const double parameter = (1.0 - fraction) *
			first_parameter + fraction * second_parameter;
		    if (parameter > model_domain.Min() +
			    model_parameter_tolerance &&
			parameter < model_domain.Max() -
			    model_parameter_tolerance)
		    {
			split_parameters.push_back(parameter);
		    }
		}
	    }
	}
	return true;
    };
    if (!collect_seam_crossings(first_surface, first_polyline) ||
	!collect_seam_crossings(second_surface, second_polyline))
    {
	return false;
    }

    std::sort(split_parameters.begin(), split_parameters.end());
    std::vector<double> unique_parameters;
    for (double parameter : split_parameters) {
	if (unique_parameters.empty() || parameter - unique_parameters.back() >
		model_parameter_tolerance)
	{
	    unique_parameters.push_back(parameter);
	}
    }
    if (unique_parameters.size() < 2 || unique_parameters.size() > 18)
    {
	return false;
    }

    const auto canonicalize_parameter_curve = [](const ON_Surface *surface,
	ON_Curve *curve) {
	if (surface == NULL || curve == NULL || curve->Dimension() != 2)
	    return false;
	double point_tolerance = ON_ZERO_TOLERANCE;
	double curve_tolerance = ON_ZERO_TOLERANCE;
	get_face_boundary_curve_tolerances(surface, curve, point_tolerance,
	    curve_tolerance);
	const double first_shift = periodic_parameter_shift(surface, curve, 0,
	    point_tolerance);
	const double second_shift = periodic_parameter_shift(surface, curve, 1,
	    point_tolerance);
	if ((!ZERO(first_shift) || !ZERO(second_shift)) &&
	    !curve->Translate(ON_3dVector(first_shift, second_shift, 0.0)))
	{
	    return false;
	}
	const ON_BoundingBox bounds = curve->BoundingBox();
	if (!bounds.IsValid())
	    return false;
	for (int direction = 0; direction < 2; ++direction) {
	    ON_Interval domain = surface->Domain(direction);
	    domain.MakeIncreasing();
	    if (!domain.IsIncreasing() ||
		bounds.m_min[direction] < domain.Min() - point_tolerance ||
		bounds.m_max[direction] > domain.Max() + point_tolerance)
	    {
		return false;
	    }
	}
	return curve->IsValid();
    };

    ON_ClassArray<ON_SSX_EVENT> generated_events;
    for (size_t split_index = 1; split_index < unique_parameters.size();
	 ++split_index)
    {
	const ON_Interval segment_domain(unique_parameters[split_index - 1],
	    unique_parameters[split_index]);
	if (!segment_domain.IsIncreasing() || segment_domain.Length() <=
		model_parameter_tolerance)
	{
	    continue;
	}
	std::unique_ptr<ON_Curve> model_segment(model_curve->DuplicateCurve());
	std::unique_ptr<ON_Curve> first_segment(
	    first_parameter->DuplicateCurve());
	std::unique_ptr<ON_Curve> second_segment(
	    second_parameter->DuplicateCurve());
	const bool whole_curve = unique_parameters.size() == 2;
	if (!model_segment || !first_segment || !second_segment ||
	    (!whole_curve && (!model_segment->Trim(segment_domain) ||
		!first_segment->Trim(segment_domain) ||
		!second_segment->Trim(segment_domain))) ||
	    !canonicalize_parameter_curve(first_surface, first_segment.get()) ||
	    !canonicalize_parameter_curve(second_surface, second_segment.get()))
	{
	    return false;
	}
	int first_segment_orientation = -1;
	int second_segment_orientation = -1;
	if (!parameter_curve_lifts_to_model_curve(first_surface,
		first_segment.get(), model_segment.get(), INTERSECTION_TOL,
		&first_segment_orientation) ||
	    !parameter_curve_lifts_to_model_curve(second_surface,
		second_segment.get(), model_segment.get(), INTERSECTION_TOL,
		&second_segment_orientation) ||
	    first_segment_orientation != second_segment_orientation)
	{
	    return false;
	}

	ON_SSX_EVENT event;
	event.m_type = ON_SSX_EVENT::ssx_transverse;
	event.m_curve3d = model_segment.release();
	event.m_curveA = first_segment.release();
	event.m_curveB = second_segment.release();
	generated_events.Append(event);
	event.m_curve3d = NULL;
	event.m_curveA = NULL;
	event.m_curveB = NULL;
    }
    if (generated_events.Count() == 0)
	return false;
    for (int event_index = 0; event_index < generated_events.Count();
	 ++event_index)
    {
	events.Append(generated_events[event_index]);
	generated_events[event_index].m_curve3d = NULL;
	generated_events[event_index].m_curveA = NULL;
	generated_events[event_index].m_curveB = NULL;
    }
    return true;
}


static ON_ClassArray<ON_ClassArray<SSICurve> >
get_face_intersection_curves(
    ON_SimpleArray<Subsurface *> &surf_tree1,
    ON_SimpleArray<Subsurface *> &surf_tree2,
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    const ON_BoundingBox &brep1_bbox,
    const ON_BoundingBox &brep2_bbox,
    op_type operation,
    BooleanFaceClassification &classification,
    std::vector<BooleanPreservedComponent> &preserved_components,
    ON_ClassArray<SharedSSICurve> &shared_curves,
    ON_ClassArray<CoplanarFacePair> &coplanar_pairs)
{
    std::vector<Subsurface *> st1, st2;
    ON_ClassArray<ON_ClassArray<SSICurve> > curves_array;
    int face_count1 = brep1->m_F.Count();
    int face_count2 = brep2->m_F.Count();
    int surf_count1 = brep1->m_S.Count();
    int surf_count2 = brep2->m_S.Count();

    // We're not well set up currently to handle a situation where
    // one of the breps has no faces - don't try.  Also make sure
    // we don't have too many faces.
    if (!face_count1 || !face_count2 || ((face_count1 + face_count2) < 0))
	return curves_array;
    if (!surf_count1 || !surf_count2 || ((surf_count1 + surf_count2) < 0))
	return curves_array;

    std::vector<ON_BoundingBox> brep1_component_bboxes;
    std::vector<ON_BoundingBox> brep2_component_bboxes;
    std::vector<std::vector<int> > brep1_component_faces;
    std::vector<std::vector<int> > brep2_component_faces;
    const bool have_brep1_components = boolean_brep_component_bounding_boxes(
	brep1, brep1_component_bboxes, &brep1_component_faces);
    const bool have_brep2_components = boolean_brep_component_bounding_boxes(
	brep2, brep2_component_bboxes, &brep2_component_faces);
    if (!have_brep1_components) {
	brep1_component_bboxes.clear();
	brep1_component_faces.clear();
	brep1_component_bboxes.push_back(brep1_bbox);
    }
    if (!have_brep2_components) {
	brep2_component_bboxes.clear();
	brep2_component_faces.clear();
	brep2_component_bboxes.push_back(brep2_bbox);
    }
    if (have_brep1_components && have_brep2_components) {
	classify_disjoint_boolean_components(brep1, brep1_component_bboxes,
	    brep1_component_faces, brep2_component_bboxes, 0, true, operation,
	    classification, preserved_components);
	classify_disjoint_boolean_components(brep2, brep2_component_bboxes,
	    brep2_component_faces, brep1_component_bboxes, face_count1, false,
	    operation, classification, preserved_components);
    }

    /* Depending on the operation type and the bounding box behaviors, we
     * can sometimes decide immediately whether a face will end up in the
     * final brep or will have no role in the intersections - do that
     * categorization up front */
    for (int i = 0; i < face_count1 + face_count2; i++) {
	const ON_BrepFace &face = i < face_count1 ? brep1->m_F[i] : brep2->m_F[i - face_count1];
	const std::vector<ON_BoundingBox> &other_component_bboxes =
	    i < face_count1 ? brep2_component_bboxes : brep1_component_bboxes;
	if (boolean_face_is_disjoint_from_component_bounds(face,
		other_component_bboxes))
	{
	    classify_component_disjoint_boolean_face(classification, i,
		i < face_count1, operation);
	}
    }

    // For the faces that we can't rule out, there are several possible roles they can play:
    //
    // 1.  Fully utilized in the new brep
    // 2.  Changed into a new set of faces by intersections, each of which must be evaluated
    // 3.  Fully discarded by the new brep
    //
    // We won't be able to distinguish between 1 and 3 at this stage, but we can narrow in
    // on which faces might fall into category 2 and what faces they might interact with.
    std::set<std::pair<int, int> > intersection_candidates;
    for (int i = 0; i < face_count1; i++) {
	if (boolean_face_requires_intersection(classification, i)) {
	    for (int j = 0; j < face_count2; j++) {
		const int second_face_index = face_count1 + j;
		if (boolean_face_requires_intersection(classification,
			second_face_index))
		{
		    // If the two faces don't interact according to their bounding boxes,
		    // they won't be a source of events - otherwise, they must be checked.
		    fastf_t face_dist = brep1->m_F[i].BoundingBox().MinimumDistanceTo(brep2->m_F[j].BoundingBox());
		    if (face_dist <= INTERSECTION_TOL) {
			intersection_candidates.insert(std::pair<int, int>(i, j));
		    }
		}
	    }
	}
    }
    record_boolean_intersection_candidates(intersection_candidates.size());

    // For those not in category 2 an inside/outside test on the breps combined with the boolean op
    // should be enough to decide the issue, but there is a problem.  If *all* faces of a brep are
    // inside the other brep and the operation is a subtraction, we don't want a "floating" inside-out
    // brep volume inside the outer volume and topologically isolated.  Normally this is handled by
    // creating a face that connects the outer and inner shells, but this is potentially a non-trivial
    // operation.  The only thing that comes immediately to mind is to find the center point of the
    // bounding box of the inner brep, create a plane using that point and the z+ unit vector for a normal, and
    // cut both breps in half with that plane to form four new breps and two new subtraction problems.
    //
    // More broadly, this is a problem - unioning two half-spheres with a sphere subtracted out of their
    // respective centers will end up with isolated surfaces in the middle of the union unless the routines
    // know they must keep one of the coplanar faces in order to topologically connect the middle.  However,
    // in the case where there is no center sphere the central face should be removed.  It may be that the
    // condition to satisfy for removal is no interior trimming loops on the face.
    //
    //
    // Also worth thinking about - would it be possible to then do edge comparisons to
    // determine which of the "fully used/fully non-used" faces are needed?

    if (DEBUG_BREP_BOOLEAN) {
	//bu_log("Summary of Boolean face classifications: final %zd, discarded %zd, intersection_candidates(%zd):\n", classification.m_final_faces.size(), classification.m_discarded_faces.size(), intersection_candidates.size());
	for (std::set<std::pair<int, int> >::iterator it = intersection_candidates.begin(); it != intersection_candidates.end(); ++it) {
	    bu_log("     (%d, %d)\n", (*it).first, (*it).second);
	}
    }

    for (int i = 0; i < surf_count1; i++) {
	Subsurface *ss = new Subsurface(brep1->m_S[i]->Duplicate());
	st1.push_back(ss);
    }
    for (int i = 0; i < surf_count2; i++) {
	Subsurface *ss = new Subsurface(brep2->m_S[i]->Duplicate());
	st2.push_back(ss);
    }

    curves_array.SetCapacity(face_count1 + face_count2);

    curves_array.SetCount(curves_array.Capacity());

    // calculate intersection curves
    for (int i = 0; i < face_count1; i++) {

	if ((int)st1.size() < brep1->m_F[i].m_si + 1)
	    continue;

	for (int j = 0; j < face_count2; j++) {
	    if (intersection_candidates.find(std::pair<int, int>(i, j)) != intersection_candidates.end()) {
		BooleanFailureFaceScope failure_face_scope(i, face_count1 + j);
		ON_Surface *surf1, *surf2;
		ON_ClassArray<ON_SSX_EVENT> events;
		int results = 0;
		surf1 = brep1->m_S[brep1->m_F[i].m_si];
		surf2 = brep2->m_S[brep2->m_F[j].m_si];
		const bool coplanar = planar_surfaces_are_coplanar(surf1, surf2);
		const bool same_domain = coplanar &&
		    brep_faces_have_matching_planar_boundaries(brep1->m_F[i],
			brep2->m_F[j]);
		const bool disjoint_interiors = coplanar &&
		    planar_face_boundaries_have_disjoint_interiors(brep1->m_F[i],
			brep2->m_F[j]);
		const bool same_surface = !coplanar &&
		    is_same_surface(surf1, surf2);
		if (coplanar || same_surface) {
		    classification.m_nonpreservable_faces.insert(i);
		    classification.m_nonpreservable_faces.insert(face_count1 + j);
		}
		if (same_domain) {
		    continue;
		}
		if (disjoint_interiors) {
		    /* Coplanar exterior faces from solids which meet only at their
		     * boundaries still need a planar union.  Otherwise the shared
		     * boundary remains on both faces after the intervening solid face
		     * is removed, leaving overlapping naked edge partitions.  The
		     * replacement path below verifies matching orientation and that
		     * the loop union has one valid outer boundary, so merely nearby or
		     * oppositely oriented faces remain on the ordinary path. */
		    if (operation == BOOLEAN_UNION) {
			coplanar_pairs.Append(CoplanarFacePair(i,
			    face_count1 + j));
		    }
		    continue;
		}
		if (coplanar) {
		    coplanar_pairs.Append(CoplanarFacePair(i, face_count1 + j));
		    continue;
		}
		if (same_surface) {
		    continue;
		}
		if ((int)st2.size() < brep2->m_F[j].m_si + 1)
		    continue;

		// Possible enhancement: Some faces may share the same surface.
		// We can store the result of SSI to avoid re-computation.
		if (append_exact_sphere_sphere_ssi_event(surf1, surf2,
			events))
		{
		    results = events.Count();
		} else {
		    results = ON_Intersect(surf1,
				   surf2,
				   events,
				   INTERSECTION_TOL,
				   0.0,
				   0.0,
				   NULL,
				   NULL,
				   NULL,
				   NULL,
				   st1[brep1->m_F[i].m_si],
				   st2[brep2->m_F[j].m_si]);
		}
	if (results == BREP_SSI_BUDGET_EXCEEDED) {
	    record_boolean_failure(
		BREP_BOOLEAN_FAILURE_STAGE_SURFACE_INTERSECTION,
		BREP_BOOLEAN_FAILURE_REASON_WORK_BUDGET, i,
		face_count1 + j, -1, -1, INTERSECTION_TOL);
	    const ON_ClassId *first_class = surf1->ClassId();
	    const ON_ClassId *second_class = surf2->ClassId();
	    const ON_BoundingBox first_face_bounds =
		brep1->m_F[i].BoundingBox();
	    const ON_BoundingBox second_face_bounds =
		brep2->m_F[j].BoundingBox();
	    bu_log("Boolean surface intersection work limit exceeded for "
		"faces %d/%d (%s/%s); bounds "
		"{%g %g %g}-{%g %g %g} / {%g %g %g}-{%g %g %g}.\n",
		i, face_count1 + j,
		first_class ? first_class->ClassName() : "unknown",
		second_class ? second_class->ClassName() : "unknown",
		first_face_bounds.m_min.x, first_face_bounds.m_min.y,
		first_face_bounds.m_min.z, first_face_bounds.m_max.x,
		first_face_bounds.m_max.y, first_face_bounds.m_max.z,
		second_face_bounds.m_min.x, second_face_bounds.m_min.y,
		second_face_bounds.m_min.z, second_face_bounds.m_max.x,
		second_face_bounds.m_max.y, second_face_bounds.m_max.z);
	    for (size_t surface_index = 0;
			 surface_index < st1.size(); ++surface_index)
		    {
			delete st1[surface_index];
		    }
		    for (size_t surface_index = 0;
			 surface_index < st2.size(); ++surface_index)
		    {
			delete st2[surface_index];
		    }
		    throw BooleanBudgetExceeded(
			"Surface intersection work limit exceeded.\n");
		}
		if (results <= 0) {
		    continue;
		}
		record_boolean_intersection_events(static_cast<size_t>(results));
		const std::vector<bool> duplicate_closed_events =
		    duplicate_closed_ssi_events(events, surf1, surf2);
		classification.m_nonpreservable_faces.insert(i);
		classification.m_nonpreservable_faces.insert(face_count1 + j);

		//dplot->SSX(events, brep1, brep1->m_F[i].m_si, brep2, brep2->m_F[j].m_si);
		//dplot->WriteLog();

		for (int k = 0; k < events.Count(); k++) {
		    if (duplicate_closed_events[k]) {
			if (DEBUG_BREP_BOOLEAN) {
			    bu_log("Discarded duplicate closed SSI event %d for "
				"faces %d/%d.\n", k, i, face_count1 + j);
			}
			continue;
		    }
		    if (is_boolean_ssi_curve_event(events[k]))
		    {
			ON_SimpleArray<ON_Curve *> subcurves_3d, subcurves_on1;
			ON_SimpleArray<ON_Curve *> subcurves_on2;

			bool curve_covers_face1 = false;
			bool curve_covers_face2 = false;
			get_subcurves_inside_faces(subcurves_3d, subcurves_on1,
					   subcurves_on2, brep1, brep2, i, j, &events[k],
					   curve_covers_face1, curve_covers_face2);
			if (DEBUG_BREP_BOOLEAN) {
			    bu_log("Boolean SSI faces %d/%d event %d type %d closed %d "
				"coverage %d/%d subcurves %d/%d/%d.\n", i,
				face_count1 + j, k, events[k].m_type,
				events[k].m_curve3d != NULL &&
				events[k].m_curve3d->IsClosed(), curve_covers_face1,
				curve_covers_face2, subcurves_3d.Count(),
				subcurves_on1.Count(),
				subcurves_on2.Count());
			}
			const bool full_closed_event = is_full_closed_ssi_event(
			    events[k], curve_covers_face1, curve_covers_face2) &&
			    subcurves_3d.Count() == 1 && subcurves_on1.Count() == 1 &&
			    subcurves_on2.Count() == 1 && subcurves_3d[0] != NULL &&
			    subcurves_3d[0]->IsClosed() &&
			    subcurves_on1[0] != NULL && subcurves_on2[0] != NULL;
			if (full_closed_event) {
			    shared_curves.Append(SharedSSICurve(i, face_count1 + j,
					subcurves_3d[0]->Duplicate(),
					boolean_surface_parameter_curve(*subcurves_on1[0]),
					boolean_surface_parameter_curve(*subcurves_on2[0])));
			} else if (subcurves_3d.Count() == subcurves_on1.Count() &&
			    subcurves_on1.Count() == subcurves_on2.Count()) {
                // Each pair was clipped from the same 3D SSI interval.
                for (int subcurve_index = 0;
                     subcurve_index < subcurves_on1.Count();
                     ++subcurve_index)
                {
                    if (subcurves_on1[subcurve_index] == NULL ||
                        subcurves_on2[subcurve_index] == NULL)
                    {
                        continue;
                    }
				    append_shared_open_ssi_curve(shared_curves, i,
					face_count1 + j, brep1->m_F[i], brep2->m_F[j],
					*subcurves_3d[subcurve_index],
					*subcurves_on1[subcurve_index],
                        *subcurves_on2[subcurve_index]);
                }
            }

			for (int l = 0; l < subcurves_on1.Count(); ++l) {
			    SSICurve &curve = curves_array[i].AppendNew();
			    curve.Reset(subcurves_on1[l]);
			    curve.SetProvenance(i, face_count1 + j);
			}
			for (int l = 0; l < subcurves_on2.Count(); ++l) {
			    SSICurve &curve = curves_array[face_count1 + j].AppendNew();
			    curve.Reset(subcurves_on2[l]);
			    curve.SetProvenance(face_count1 + j, i);
			}
			for (int l = 0; l < subcurves_3d.Count(); ++l) {
			    delete subcurves_3d[l];
			}
		    }
		}

		if (DEBUG_BREP_BOOLEAN) {
		    // Look for coplanar faces
		    ON_Plane surf1_plane, surf2_plane;
		    if (surf1->IsPlanar(&surf1_plane) && surf2->IsPlanar(&surf2_plane)) {
			/* We already checked for disjoint above, so the only remaining question is the normals */
			if (surf1_plane.Normal().IsParallelTo(surf2_plane.Normal())) {
			    bu_log("Faces brep1->%d and brep2->%d are coplanar and intersecting\n", i, j);
			}
		    }
		}

	    }
	}
    }

    for (size_t i = 0; i < st1.size(); i++) {
	surf_tree1.Append(st1[i]);
    }

    for (size_t i = 0; i < st2.size(); i++) {
	surf_tree2.Append(st2[i]);
    }

    return curves_array;
}


static ON_SimpleArray<ON_Curve *>get_face_trim_loop(const ON_Brep *brep, int face_loop_index)
{
    const ON_BrepLoop &loop = brep->m_L[face_loop_index];
    const ON_SimpleArray<int> &trim_index = loop.m_ti;
    ON_SimpleArray<ON_Curve *> face_trim_loop;
    for (int i = 0; i < trim_index.Count(); ++i) {
	ON_Curve *curve2d = brep->m_C2[brep->m_T[trim_index[i]].m_c2i];
	face_trim_loop.Append(curve2d->Duplicate());
    }
    return face_trim_loop;
}


static ON_SimpleArray<TrimmedFace *>
get_trimmed_faces(const ON_Brep *brep)
{
    std::vector<TrimmedFace *> trimmed_faces;
    int face_count = brep->m_F.Count();
    for (int i = 0; i < face_count; i++) {
	const ON_BrepFace &face = brep->m_F[i];
	const ON_SimpleArray<int> &loop_index = face.m_li;
	if (loop_index.Count() <= 0) {
	    continue;
	}

	TrimmedFace *trimmed_face = new TrimmedFace();
	trimmed_face->m_face = &face;
	ON_SimpleArray<ON_Curve *> index_loop = get_face_trim_loop(brep, loop_index[0]);
	trimmed_face->m_outerloop = index_loop;
	for (int j = 1; j < loop_index.Count(); j++) {
	    index_loop = get_face_trim_loop(brep, loop_index[j]);
	    trimmed_face->m_innerloop.push_back(index_loop);
	}
	trimmed_faces.push_back(trimmed_face);
    }
    ON_SimpleArray<TrimmedFace *> tf;
    for (size_t i = 0; i < trimmed_faces.size(); i++) {
	tf.Append(trimmed_faces[i]);
    }
    return tf;
}


// Convert model-space Boolean tolerance into both UV and curve parameters.
static bool
get_face_boundary_curve_tolerances(
    const ON_Surface *surface,
    const ON_Curve *curve,
    double &intersection_tolerance,
    double &curve_parameter_tolerance)
{
    if (surface == NULL || curve == NULL) {
	return false;
    }

    ON_Interval curve_domain = curve->Domain();
    curve_domain.MakeIncreasing();
    if (!curve_domain.IsValid() || curve_domain.Length() <= ON_ZERO_TOLERANCE) {
	return false;
    }

    const double samples[] = {
	curve_domain.Min(),
	curve_domain.Mid(),
	curve_domain.Max()
    };
    double maximum_surface_scale = 0.0;
    double maximum_curve_speed = 0.0;
    for (size_t sample_index = 0;
	 sample_index < sizeof(samples) / sizeof(samples[0]);
	 ++sample_index)
    {
	ON_3dPoint parameter;
	ON_3dVector parameter_derivative;
	ON_3dPoint surface_point;
	ON_3dVector surface_u;
	ON_3dVector surface_v;
	if (!curve->Ev1Der(samples[sample_index], parameter,
		parameter_derivative) || !surface->Ev1Der(parameter.x,
		parameter.y, surface_point, surface_u, surface_v) ||
	    !parameter.IsValid() || !surface_point.IsValid())
	{
	    return false;
	}

	const double uu = ON_DotProduct(surface_u, surface_u);
	const double uv = ON_DotProduct(surface_u, surface_v);
	const double vv = ON_DotProduct(surface_v, surface_v);
	const double determinant = uu * vv - uv * uv;
	const double trace = uu + vv;
	if (!std::isfinite(uu) || !std::isfinite(uv) || !std::isfinite(vv) ||
	    !std::isfinite(determinant) || !std::isfinite(trace))
	{
	    return false;
	}

	const double discriminant = std::max(0.0, trace * trace -
	    4.0 * determinant);
	const double maximum_eigenvalue = 0.5 * (trace + sqrt(discriminant));
	if (!(maximum_eigenvalue > 0.0) ||
	    !std::isfinite(maximum_eigenvalue)) {
	    return false;
	}
	maximum_surface_scale = std::max(maximum_surface_scale,
	    sqrt(maximum_eigenvalue));

	const ON_3dVector lifted_derivative = surface_u *
	    parameter_derivative.x + surface_v * parameter_derivative.y;
	const double lifted_speed = lifted_derivative.Length();
	if (!std::isfinite(lifted_speed)) {
	    return false;
	}
	maximum_curve_speed = std::max(maximum_curve_speed, lifted_speed);
    }
    if (!(maximum_surface_scale > ON_ZERO_TOLERANCE) ||
	!(maximum_curve_speed > ON_ZERO_TOLERANCE))
    {
	return false;
    }

    // Keep UV intersections inside the model-space Boolean tolerance.
    intersection_tolerance = INTERSECTION_TOL / maximum_surface_scale;
    curve_parameter_tolerance = INTERSECTION_TOL / maximum_curve_speed;
    return std::isfinite(intersection_tolerance) &&
	std::isfinite(curve_parameter_tolerance) &&
	intersection_tolerance > 0.0 && curve_parameter_tolerance > 0.0;
}


static bool
append_unique_boundary_ssi_parameter(
    std::vector<double> &parameters,
    double parameter,
    const ON_Interval &domain,
    double parameter_tolerance)
{
    if (!std::isfinite(parameter) || !domain.Includes(parameter) ||
	!(parameter_tolerance > 0.0) || !std::isfinite(parameter_tolerance))
    {
	return false;
    }

    for (size_t parameter_index = 0; parameter_index < parameters.size();
	 ++parameter_index)
    {
	if (fabs(parameters[parameter_index] - parameter) <=
	    parameter_tolerance)
	{
	    return true;
	}
    }

    parameters.push_back(parameter);
    return true;
}


static std::vector<const ON_Curve *>
face_boundary_curves(const TrimmedFace &face)
{
    std::vector<const ON_Curve *> curves;
    for (int curve_index = 0; curve_index < face.m_outerloop.Count();
	 ++curve_index)
    {
	if (face.m_outerloop[curve_index] != NULL) {
	    curves.push_back(face.m_outerloop[curve_index]);
	}
    }
    for (size_t loop_index = 0; loop_index < face.m_innerloop.size();
	 ++loop_index)
    {
	for (int curve_index = 0;
	     curve_index < face.m_innerloop[loop_index].Count(); ++curve_index)
	{
	    if (face.m_innerloop[loop_index][curve_index] != NULL) {
		curves.push_back(face.m_innerloop[loop_index][curve_index]);
	    }
	}
    }
    return curves;
}


static void
append_boundary_curve_endpoint_parameters(
    std::vector<double> &ssi_parameters,
    const ON_Curve &ssi_curve,
    const ON_Curve &boundary_curve,
    const ON_Interval &ssi_domain,
    double parameter_space_tolerance,
    double ssi_curve_parameter_tolerance)
{
    std::unique_ptr<ON_Curve> boundary_parameter_curve(
	boolean_surface_parameter_curve(boundary_curve));
    if (!boundary_parameter_curve) {
	return;
    }

    const ON_3dPoint boundary_endpoints[] = {
	boundary_parameter_curve->PointAtStart(),
	boundary_parameter_curve->PointAtEnd()
    };
    for (size_t endpoint_index = 0;
	 endpoint_index < sizeof(boundary_endpoints) /
	 sizeof(boundary_endpoints[0]); ++endpoint_index)
    {
	double ssi_parameter = 0.0;
	if (boundary_endpoints[endpoint_index].IsValid() &&
	    point_3d_to_curve_parameter_with_tolerance(
		boundary_endpoints[endpoint_index], &ssi_curve,
		parameter_space_tolerance, ssi_parameter))
	{
	    append_unique_boundary_ssi_parameter(ssi_parameters,
		ssi_parameter, ssi_domain, ssi_curve_parameter_tolerance);
	}
    }
}


static bool
certified_boundary_curve_covers_ssi_interval(
    const ON_Curve &ssi_curve,
    const ON_Interval &ssi_interval,
    const ON_Curve &boundary_curve,
    const ON_Surface &surface,
    double parameter_space_tolerance,
    bool allow_complete_boundary_locus)
{
    if (!ssi_interval.IsIncreasing() || !(parameter_space_tolerance > 0.0) ||
	!std::isfinite(parameter_space_tolerance))
    {
	return false;
    }

    std::unique_ptr<ON_Curve> boundary_parameter_curve(
	boolean_surface_parameter_curve(boundary_curve));
    if (!boundary_parameter_curve) {
	return false;
    }

    double boundary_parameter_space_tolerance = 0.0;
    double boundary_curve_parameter_tolerance = 0.0;
    if (!get_face_boundary_curve_tolerances(&surface,
	boundary_parameter_curve.get(), boundary_parameter_space_tolerance,
	boundary_curve_parameter_tolerance))
    {
	return false;
    }
    const double equivalence_tolerance = std::min(parameter_space_tolerance,
	boundary_parameter_space_tolerance);
    if (!(equivalence_tolerance > 0.0) ||
	!std::isfinite(equivalence_tolerance))
    {
	return false;
    }

    std::unique_ptr<ON_Curve> ssi_subcurve;
    try {
	ssi_subcurve.reset(sub_curve(&ssi_curve, ssi_interval.Min(),
	    ssi_interval.Max()));
    } catch (InvalidInterval &) {
	return false;
    }
    if (!ssi_subcurve) {
	return false;
    }

    /* The candidate often spans one complete boundary arc.  Test that case
     * directly before projecting its endpoints back to the boundary curve.
     * Closest-point inversion of a planetary-scale rational conic can lose
     * the correct minimum even though the two curve loci are equivalent. */
    if (curves_match_shared_parameter_curve(ssi_subcurve.get(),
	    boundary_parameter_curve.get(), equivalence_tolerance) ||
	(allow_complete_boundary_locus &&
	 brep_curves_coincident(*ssi_subcurve, *boundary_parameter_curve,
	     equivalence_tolerance)))
    {
	return true;
    }

    const ON_3dPoint ssi_start = ssi_subcurve->PointAtStart();
    const ON_3dPoint ssi_end = ssi_subcurve->PointAtEnd();
    double boundary_start = 0.0;
    double boundary_end = 0.0;
    if (!ssi_start.IsValid() || !ssi_end.IsValid() ||
	!point_3d_to_curve_parameter_with_tolerance(ssi_start,
	    boundary_parameter_curve.get(), equivalence_tolerance,
	    boundary_start) ||
	!point_3d_to_curve_parameter_with_tolerance(ssi_end,
	    boundary_parameter_curve.get(), equivalence_tolerance,
	    boundary_end))
    {
	return false;
    }

    ON_Interval boundary_interval(boundary_start, boundary_end);
    boundary_interval.MakeIncreasing();
    if (!boundary_interval.IsIncreasing() || boundary_interval.Length() <=
	boundary_curve_parameter_tolerance)
    {
	return false;
    }

    std::unique_ptr<ON_Curve> boundary_subcurve;
    try {
	boundary_subcurve.reset(sub_curve(boundary_parameter_curve.get(),
	    boundary_interval.Min(), boundary_interval.Max()));
    } catch (InvalidInterval &) {
	return false;
    }
    if (!boundary_subcurve || !curves_match_shared_parameter_curve(
	ssi_subcurve.get(), boundary_subcurve.get(), equivalence_tolerance))
    {
	return false;
    }

    return true;
}


static bool
closed_ssi_matches_face_boundary_curve(
    const ON_Curve &ssi_curve,
    const ON_Curve &boundary_curve,
    double parameter_space_tolerance)
{
    std::unique_ptr<ON_Curve> boundary_parameter_curve(
	boolean_surface_parameter_curve(boundary_curve));
    if (!boundary_parameter_curve || !ssi_curve.IsClosed() ||
	!boundary_parameter_curve->IsClosed() ||
	!curves_match_shared_parameter_curve(&ssi_curve,
	boundary_parameter_curve.get(), parameter_space_tolerance))
    {
	return false;
    }

    return true;
}


static bool
parameter_curve_is_covered_by_boundary_curves(
    const ON_Curve &curve,
    const std::vector<const ON_Curve *> &boundary_curves,
    const ON_Surface &surface)
{
    if (boundary_curves.empty()) {
	return false;
    }

    std::unique_ptr<ON_Curve> parameter_curve(
	boolean_surface_parameter_curve(curve));
    if (!parameter_curve) {
	return false;
    }

    ON_Interval curve_domain = parameter_curve->Domain();
    curve_domain.MakeIncreasing();
    if (!curve_domain.IsIncreasing()) {
	return false;
    }

    double parameter_space_tolerance = 0.0;
    double curve_parameter_tolerance = 0.0;
    if (!get_face_boundary_curve_tolerances(&surface, parameter_curve.get(),
	parameter_space_tolerance, curve_parameter_tolerance))
    {
	return false;
    }

    if (parameter_isocurve_is_covered_by_boundary_curves(*parameter_curve,
	boundary_curves, surface, parameter_space_tolerance))
    {
	return true;
    }

    if (parameter_curve->IsClosed()) {
	for (size_t curve_index = 0; curve_index < boundary_curves.size();
	     ++curve_index)
	{
	    if (closed_ssi_matches_face_boundary_curve(*parameter_curve,
		*boundary_curves[curve_index],
		parameter_space_tolerance))
	    {
		return true;
	    }
	}
    }

    std::vector<double> split_parameters;
    if (!append_unique_boundary_ssi_parameter(split_parameters,
	curve_domain.Min(), curve_domain, curve_parameter_tolerance) ||
	!append_unique_boundary_ssi_parameter(split_parameters,
	curve_domain.Max(), curve_domain, curve_parameter_tolerance))
    {
	return false;
    }
    for (size_t curve_index = 0; curve_index < boundary_curves.size();
	 ++curve_index)
    {
	append_boundary_curve_endpoint_parameters(split_parameters,
	    *parameter_curve, *boundary_curves[curve_index], curve_domain,
	    parameter_space_tolerance, curve_parameter_tolerance);
    }

    std::sort(split_parameters.begin(), split_parameters.end());
    bool has_covered_interval = false;
    for (size_t parameter_index = 1;
	 parameter_index < split_parameters.size(); ++parameter_index)
    {
	const ON_Interval interval(split_parameters[parameter_index - 1],
	    split_parameters[parameter_index]);
	if (!interval.IsIncreasing() || interval.Length() <=
	    curve_parameter_tolerance)
	{
	    continue;
	}

	has_covered_interval = true;
	bool interval_is_covered = false;
	for (size_t curve_index = 0; curve_index < boundary_curves.size();
	     ++curve_index)
	{
	    if (certified_boundary_curve_covers_ssi_interval(*parameter_curve,
		interval, *boundary_curves[curve_index], surface,
		parameter_space_tolerance))
	    {
		interval_is_covered = true;
		break;
	    }
	}
	if (!interval_is_covered) {
	    return false;
	}
    }

    return has_covered_interval;
}


static bool
parameter_curve_is_covered_by_face_boundary(
    const ON_Curve &curve,
    const TrimmedFace &face)
{
    const ON_Surface *surface = face.m_face ? face.m_face->SurfaceOf() : NULL;
    if (surface == NULL) {
	return false;
    }

    const std::vector<const ON_Curve *> boundary_curves =
	face_boundary_curves(face);
    return parameter_curve_is_covered_by_boundary_curves(curve,
	boundary_curves, *surface);
}


static void
append_certified_boundary_interval(
    std::vector<ON_Interval> &intervals,
    ON_Interval interval,
    const ON_Interval &curve_domain,
    double curve_parameter_tolerance)
{
    interval.MakeIncreasing();
    interval.Set(std::max(interval.Min(), curve_domain.Min()),
	std::min(interval.Max(), curve_domain.Max()));
    if (interval.IsIncreasing() && interval.Length() >
	curve_parameter_tolerance)
    {
	intervals.push_back(interval);
    }
}


static bool
append_certified_face_boundary_intervals(
    std::vector<ON_Interval> &intervals,
    double &curve_parameter_tolerance,
    const ON_Curve &curve,
    const TrimmedFace &face)
{
    const ON_Surface *surface = face.m_face ? face.m_face->SurfaceOf() : NULL;
    if (surface == NULL) {
	return false;
    }

    std::unique_ptr<ON_Curve> parameter_curve(
	boolean_surface_parameter_curve(curve));
    if (!parameter_curve) {
	return false;
    }

    ON_Interval curve_domain = parameter_curve->Domain();
    curve_domain.MakeIncreasing();
    if (!curve_domain.IsIncreasing()) {
	return false;
    }

    double parameter_space_tolerance = 0.0;
    if (!get_face_boundary_curve_tolerances(surface, parameter_curve.get(),
	parameter_space_tolerance, curve_parameter_tolerance))
    {
	return false;
    }

    const std::vector<const ON_Curve *> boundary_curves =
	face_boundary_curves(face);
    for (size_t curve_index = 0; curve_index < boundary_curves.size();
	 ++curve_index)
    {
	const ON_Curve *boundary_curve = boundary_curves[curve_index];
	if (boundary_curve == NULL) {
	    continue;
	}

	if (!parameter_curve->IsClosed() &&
	    certified_boundary_curve_covers_ssi_interval(*parameter_curve,
		curve_domain, *boundary_curve, *surface,
		parameter_space_tolerance))
	{
	    append_certified_boundary_interval(intervals, curve_domain,
		curve_domain, curve_parameter_tolerance);
	    continue;
	}
	if (parameter_curve->IsClosed() &&
	    closed_ssi_matches_face_boundary_curve(*parameter_curve,
		*boundary_curve, parameter_space_tolerance))
	{
	    append_certified_boundary_interval(intervals, curve_domain,
		curve_domain, curve_parameter_tolerance);
	    continue;
	}

	ON_SimpleArray<ON_X_EVENT> events;
	intersect_boolean_curves(parameter_curve.get(), boundary_curve, events,
	    parameter_space_tolerance);
	for (int event_index = 0; event_index < events.Count(); ++event_index) {
	    const ON_X_EVENT &event = events[event_index];
	    if (event.m_type != ON_X_EVENT::ccx_overlap) {
		continue;
	    }

	    ON_Interval candidate(event.m_a[0], event.m_a[1]);
	    candidate.MakeIncreasing();
	    candidate.Set(std::max(candidate.Min(), curve_domain.Min()),
		std::min(candidate.Max(), curve_domain.Max()));
	    // Overlap events nominate candidate intervals; equivalence checks
	    // establish whether an interval is truly on a boundary.
	    if (candidate.IsIncreasing() && candidate.Length() >
		curve_parameter_tolerance)
	    {
		const bool certified = certified_boundary_curve_covers_ssi_interval(
		    *parameter_curve, candidate, *boundary_curve, *surface,
		    parameter_space_tolerance);
		if (certified) {
		    append_certified_boundary_interval(intervals, candidate,
			curve_domain, curve_parameter_tolerance);
		}
	    }
	}
    }

    return true;
}


static bool
append_nonboundary_ssi_subcurves(
    ON_ClassArray<SSICurve> &retained_curves,
    const SSICurve &source_curve,
    std::vector<ON_Interval> boundary_intervals,
    double curve_parameter_tolerance)
{
    const ON_Curve &curve = *source_curve.m_curve;
    ON_Interval curve_domain = curve.Domain();
    curve_domain.MakeIncreasing();
    if (!curve_domain.IsIncreasing() || boundary_intervals.empty() ||
	!(curve_parameter_tolerance > 0.0))
    {
	return false;
    }

    std::sort(boundary_intervals.begin(), boundary_intervals.end(),
	[](const ON_Interval &first, const ON_Interval &second) {
	    return first.Min() < second.Min();
	});
    std::vector<ON_Interval> merged_intervals;
    for (size_t interval_index = 0;
	 interval_index < boundary_intervals.size(); ++interval_index)
    {
	ON_Interval interval = boundary_intervals[interval_index];
	interval.MakeIncreasing();
	interval.Set(std::max(interval.Min(), curve_domain.Min()),
	    std::min(interval.Max(), curve_domain.Max()));
	if (!interval.IsIncreasing() || interval.Length() <=
	    curve_parameter_tolerance)
	{
	    continue;
	}
	if (merged_intervals.empty() || interval.Min() >
	    merged_intervals.back().Max() + curve_parameter_tolerance)
	{
	    merged_intervals.push_back(interval);
	} else {
	    ON_Interval &previous = merged_intervals.back();
	    previous.Set(previous.Min(), std::max(previous.Max(), interval.Max()));
	}
    }
    if (merged_intervals.empty()) {
	return false;
    }

    const auto append_subcurve = [&retained_curves, &source_curve,
	&curve](double start, double end) {
	if (!(end > start)) {
	    return false;
	}
	ON_Curve *subcurve = NULL;
	try {
	    subcurve = sub_curve(&curve, start, end);
	} catch (InvalidInterval &) {
	    return false;
	}
	if (subcurve == NULL) {
	    return false;
	}
	SSICurve &retained = retained_curves.AppendNew();
	retained.Reset(subcurve);
	retained.SetProvenance(source_curve.m_source_face_index,
	    source_curve.m_peer_face_index);
	return true;
    };

    double retained_start = curve_domain.Min();
    for (size_t interval_index = 0;
	 interval_index < merged_intervals.size(); ++interval_index)
    {
	const ON_Interval &boundary_interval = merged_intervals[interval_index];
	if (boundary_interval.Min() > retained_start +
	    curve_parameter_tolerance && !append_subcurve(retained_start,
	    boundary_interval.Min()))
	{
	    return false;
	}
	retained_start = std::max(retained_start, boundary_interval.Max());
    }
    return retained_start + curve_parameter_tolerance >= curve_domain.Max() ||
	append_subcurve(retained_start, curve_domain.Max());
}


static bool
ssi_curve_is_covered_by_face_boundary(
    const SSICurve &ssi_curve,
    const TrimmedFace &face)
{
    return ssi_curve.m_curve != NULL &&
	parameter_curve_is_covered_by_face_boundary(*ssi_curve.m_curve, face);
}


static void
remove_shared_face_boundary_ssi_curves(
    ON_ClassArray<SharedSSICurve> &shared_curves,
    const ON_SimpleArray<TrimmedFace *> &faces)
{
    const int original_curve_count = shared_curves.Count();
    for (int curve_index = shared_curves.Count() - 1;
	 curve_index >= 0; --curve_index)
    {
	const SharedSSICurve &shared_curve = shared_curves[curve_index];
	const int first_face_index = shared_curve.m_face_index[0];
	const int second_face_index = shared_curve.m_face_index[1];
	if (first_face_index < 0 || first_face_index >= faces.Count() ||
	    second_face_index < 0 || second_face_index >= faces.Count() ||
	    shared_curve.m_parameter_curve[0] == NULL ||
	    shared_curve.m_parameter_curve[1] == NULL ||
	    faces[first_face_index] == NULL || faces[second_face_index] == NULL)
	{
	    continue;
	}

	if (parameter_curve_is_covered_by_face_boundary(
		*shared_curve.m_parameter_curve[0], *faces[first_face_index]) &&
	    parameter_curve_is_covered_by_face_boundary(
		*shared_curve.m_parameter_curve[1], *faces[second_face_index]))
	{
	    shared_curves.Remove(curve_index);
	}
    }
    bu_log("Boolean shared SSI boundary filtering retained %d of %d "
	"curves.\n", shared_curves.Count(), original_curve_count);
}


static void
remove_face_boundary_ssi_curves(
    ON_ClassArray<SSICurve> &ssi_curves,
    const TrimmedFace &face)
{
    ON_ClassArray<SSICurve> retained_curves;
    for (int curve_index = 0; curve_index < ssi_curves.Count();
	 ++curve_index)
    {
	const SSICurve &ssi_curve = ssi_curves[curve_index];
	if (ssi_curve.m_curve == NULL) {
	    continue;
	}
	if (ssi_curve_is_covered_by_face_boundary(ssi_curve, face))
	{
	    continue;
	}

	std::vector<ON_Interval> boundary_intervals;
	double curve_parameter_tolerance = 0.0;
	if (!append_certified_face_boundary_intervals(boundary_intervals,
		curve_parameter_tolerance, *ssi_curve.m_curve, face) ||
	    boundary_intervals.empty())
	{
	    retained_curves.Append(ssi_curve);
	    continue;
	}

	ON_ClassArray<SSICurve> retained_subcurves;
	if (append_nonboundary_ssi_subcurves(retained_subcurves,
		ssi_curve, boundary_intervals,
		curve_parameter_tolerance))
	{
	    retained_curves.Append(retained_subcurves.Count(),
		retained_subcurves.Array());
	} else {
	    retained_curves.Append(ssi_curve);
	}
    }
    ssi_curves = retained_curves;
}


static void
free_boolean_loop(ON_SimpleArray<ON_Curve *> &loop)
{
    for (int curve_index = 0; curve_index < loop.Count(); ++curve_index) {
	delete loop[curve_index];
	loop[curve_index] = NULL;
    }
    loop.Empty();
}


static bool
transform_boolean_loop(
    const ON_SimpleArray<ON_Curve *> &source_loop,
    const ON_Xform &transform,
    ON_SimpleArray<ON_Curve *> &target_loop)
{
    for (int curve_index = 0; curve_index < source_loop.Count();
	 ++curve_index)
    {
	ON_Curve *curve = source_loop[curve_index] ?
	    source_loop[curve_index]->Duplicate() : NULL;
	if (curve == NULL || !curve->Transform(transform) || !curve->IsValid()) {
	    delete curve;
	    free_boolean_loop(target_loop);
	    return false;
	}
	target_loop.Append(curve);
    }

    return target_loop.Count() == source_loop.Count();
}


static bool
mapped_boolean_loop_matches_surface(
    const ON_SimpleArray<ON_Curve *> &original_loop,
    const ON_SimpleArray<ON_Curve *> &mapped_loop,
    const ON_Surface *original_surface,
    const ON_Surface *mapped_surface)
{
    if (original_surface == NULL || mapped_surface == NULL ||
	original_loop.Count() != mapped_loop.Count())
    {
	return false;
    }

    for (int curve_index = 0; curve_index < original_loop.Count();
	 ++curve_index)
    {
	const ON_Curve *original_curve = original_loop[curve_index];
	const ON_Curve *mapped_curve = mapped_loop[curve_index];
	if (original_curve == NULL || mapped_curve == NULL) {
	    return false;
	}

	ON_Interval original_domain = original_curve->Domain();
	ON_Interval mapped_domain = mapped_curve->Domain();
	original_domain.MakeIncreasing();
	mapped_domain.MakeIncreasing();
	if (!original_domain.IsValid() || !mapped_domain.IsValid()) {
	    return false;
	}

	const double original_samples[] = {
	    original_domain.Min(),
	    original_domain.Mid(),
	    original_domain.Max()
	};
	const double mapped_samples[] = {
	    mapped_domain.Min(),
	    mapped_domain.Mid(),
	    mapped_domain.Max()
	};
	for (size_t sample_index = 0;
	     sample_index < sizeof(original_samples) / sizeof(original_samples[0]);
	     ++sample_index)
	{
	    const ON_3dPoint original_parameter = original_curve->PointAt(
		original_samples[sample_index]);
	    const ON_3dPoint mapped_parameter = mapped_curve->PointAt(
		mapped_samples[sample_index]);
	    if (!original_parameter.IsValid() || !mapped_parameter.IsValid()) {
		return false;
	    }

	    const ON_3dPoint original_point = original_surface->PointAt(
		original_parameter.x, original_parameter.y);
	    const ON_3dPoint mapped_point = mapped_surface->PointAt(
		mapped_parameter.x, mapped_parameter.y);
	    if (!original_point.IsValid() || !mapped_point.IsValid() ||
		original_point.DistanceTo(mapped_point) > INTERSECTION_TOL)
	    {
		return false;
	    }
	}
    }

    return true;
}


static int
coplanar_face_peer_count(
    int face_index,
    const ON_ClassArray<CoplanarFacePair> &coplanar_pairs)
{
    int peer_count = 0;
    for (int pair_index = 0; pair_index < coplanar_pairs.Count();
	 ++pair_index)
    {
	const CoplanarFacePair &pair = coplanar_pairs[pair_index];
	if (face_index == pair.m_face_index[0] ||
	    face_index == pair.m_face_index[1])
	{
	    ++peer_count;
	}
    }
    return peer_count;
}


static bool
coplanar_faces_have_matching_orientation(
    const TrimmedFace &first,
    const TrimmedFace &second)
{
    if (first.m_face == NULL || second.m_face == NULL) {
	return false;
    }

    const ON_Surface *first_surface = first.m_face->SurfaceOf();
    const ON_Surface *second_surface = second.m_face->SurfaceOf();
    if (first_surface == NULL || second_surface == NULL) {
	return false;
    }

    const ON_Interval first_u = first_surface->Domain(0);
    const ON_Interval first_v = first_surface->Domain(1);
    const ON_Interval second_u = second_surface->Domain(0);
    const ON_Interval second_v = second_surface->Domain(1);
    if (!first_u.IsValid() || !first_v.IsValid() || !second_u.IsValid() ||
	!second_v.IsValid())
    {
	return false;
    }

    ON_3dVector first_normal;
    ON_3dVector second_normal;
    if (!first_surface->EvNormal(first_u.Mid(), first_v.Mid(), first_normal) ||
	!second_surface->EvNormal(second_u.Mid(), second_v.Mid(), second_normal) ||
	!first_normal.Unitize() || !second_normal.Unitize())
    {
	return false;
    }

    if (first.m_face->m_bRev) {
	first_normal = -1.0 * first_normal;
    }
    if (second.m_face->m_bRev) {
	second_normal = -1.0 * second_normal;
    }
    return ON_DotProduct(first_normal, second_normal) > 0.0;
}


static bool
point_is_inside_brep_face(
    const ON_BrepFace &face,
    const ON_2dPoint &point)
{
    if (!point.IsValid()) {
	return false;
    }

    bool inside_outer_loop = false;
    for (int loop_index = 0; loop_index < face.LoopCount(); ++loop_index) {
	const ON_BrepLoop *loop = face.Loop(loop_index);
	if (loop == NULL || loop->TrimCount() == 0) {
	    return false;
	}

	ON_SimpleArray<ON_Curve *> loop_curves;
	bool loop_valid = true;
	for (int trim_index = 0;
	     trim_index < loop->TrimCount() && loop_valid;
	     ++trim_index)
	{
	    const ON_BrepTrim *trim = loop->Trim(trim_index);
	    if (trim == NULL || trim->m_type == ON_BrepTrim::singular ||
		trim->TrimCurveOf() == NULL)
	    {
		loop_valid = false;
		break;
	    }

	    ON_Curve *curve = trim->TrimCurveOf()->Duplicate();
	    if (curve == NULL) {
		loop_valid = false;
		break;
	    }
	    loop_curves.Append(curve);
	}

	bool inside_loop = false;
	if (loop_valid) {
	    close_small_gaps(loop_curves);
	    inside_loop = is_point_inside_loop(point, loop_curves);
	}
	for (int curve_index = 0;
	     curve_index < loop_curves.Count();
	     ++curve_index)
	{
	    delete loop_curves[curve_index];
	    loop_curves[curve_index] = NULL;
	}
	if (!loop_valid) {
	    return false;
	}

	if (loop->m_type == ON_BrepLoop::outer) {
	    inside_outer_loop = inside_outer_loop || inside_loop;
	} else if (loop->m_type == ON_BrepLoop::inner) {
	    if (inside_loop) {
		return false;
	    }
	} else {
	    return false;
	}
    }

    return inside_outer_loop;
}


static void
clear_boolean_trimmed_faces(ON_SimpleArray<TrimmedFace *> &faces)
{
    for (int face_index = 0; face_index < faces.Count(); ++face_index) {
	delete faces[face_index];
	faces[face_index] = NULL;
    }
    faces.Empty();
}


static bool
collapse_coplanar_union_tolerance_edges(
    ON_SimpleArray<ON_Curve *> &loop,
    const ON_Surface *surface)
{
    if (surface == NULL || loop.Count() < 3) {
	return false;
    }

    bool changed = true;
    while (changed && loop.Count() >= 3) {
	changed = false;
	for (int curve_index = loop.Count() - 1; curve_index >= 0;
	     --curve_index)
	{
	    ON_Curve *curve = loop[curve_index];
	    if (curve == NULL || curve->IsClosed()) {
		continue;
	    }
	    const ON_3dPoint parameter_start = curve->PointAtStart();
	    const ON_3dPoint parameter_end = curve->PointAtEnd();
	    const ON_3dPoint model_start = surface->PointAt(parameter_start.x,
		parameter_start.y);
	    const ON_3dPoint model_end = surface->PointAt(parameter_end.x,
		parameter_end.y);
	    if (!model_start.IsValid() || !model_end.IsValid() ||
		model_start.DistanceTo(model_end) > INTERSECTION_TOL)
	    {
		continue;
	    }

	    const int previous_index = curve_index == 0 ? loop.Count() - 1 :
		curve_index - 1;
	    ON_Curve *previous = loop[previous_index];
	    if (previous == NULL || !previous->SetEndPoint(parameter_end) ||
		!previous->IsValid())
	    {
		return false;
	    }
	    delete curve;
	    loop.Remove(curve_index);
	    changed = true;
	    break;
	}
    }

    return is_loop_valid(loop, ON_ZERO_TOLERANCE);
}


static bool
coplanar_face_component(
    const CoplanarFacePair &seed,
    const ON_ClassArray<CoplanarFacePair> &coplanar_pairs,
    std::vector<int> &face_indices)
{
    if (seed.m_face_index[0] < 0 || seed.m_face_index[1] < 0 ||
	seed.m_face_index[0] == seed.m_face_index[1])
    {
	return false;
    }

    std::set<int> included_faces;
    included_faces.insert(seed.m_face_index[0]);
    included_faces.insert(seed.m_face_index[1]);
    face_indices.push_back(seed.m_face_index[0]);
    face_indices.push_back(seed.m_face_index[1]);

    bool expanded = true;
    while (expanded) {
	expanded = false;
	for (int pair_index = 0; pair_index < coplanar_pairs.Count();
	     ++pair_index)
	{
	    const CoplanarFacePair &pair = coplanar_pairs[pair_index];
	    const bool first_included = included_faces.find(
		pair.m_face_index[0]) != included_faces.end();
	    const bool second_included = included_faces.find(
		pair.m_face_index[1]) != included_faces.end();
	    if (first_included == second_included) {
		continue;
	    }

	    const int next_face = first_included ? pair.m_face_index[1] :
		pair.m_face_index[0];
	    if (next_face < 0) {
		return false;
	    }
	    if (included_faces.insert(next_face).second) {
		face_indices.push_back(next_face);
		expanded = true;
	    }
	}
    }

    return face_indices.size() > 1;
}


static bool
replace_partial_coplanar_union_component(
    ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    const ON_SimpleArray<TrimmedFace *> &original_faces,
    const std::vector<int> &face_indices)
{
    if (face_indices.size() < 2) {
	return false;
    }

    const int reference_index = face_indices[0];
    if (reference_index < 0 || reference_index >= original_faces.Count() ||
	reference_index >= trimmed_faces.Count())
    {
	return false;
    }

    const TrimmedFace *reference = original_faces[reference_index];
    if (reference == NULL || reference->m_face == NULL ||
	!reference->m_innerloop.empty())
    {
	return false;
    }

    ON_SimpleArray<ON_Curve *> union_loop;
    bool have_union_loop = false;
    for (size_t face_offset = 1; face_offset < face_indices.size();
	 ++face_offset)
    {
	const int face_index = face_indices[face_offset];
	if (face_index < 0 || face_index >= original_faces.Count() ||
	    face_index >= trimmed_faces.Count())
	{
	    free_boolean_loop(union_loop);
	    return false;
	}

	const TrimmedFace *face = original_faces[face_index];
	if (face == NULL || face->m_face == NULL || !face->m_innerloop.empty() ||
	    !coplanar_faces_have_matching_orientation(*reference, *face))
	{
	    free_boolean_loop(union_loop);
	    return false;
	}

	ON_Xform face_to_reference;
	if (!planar_surface_parameter_transform(face->m_face->SurfaceOf(),
		reference->m_face->SurfaceOf(), face_to_reference))
	{
	    free_boolean_loop(union_loop);
	    return false;
	}

	ON_SimpleArray<ON_Curve *> transformed_loop;
	if (!transform_boolean_loop(face->m_outerloop, face_to_reference,
		transformed_loop) || !mapped_boolean_loop_matches_surface(
		face->m_outerloop, transformed_loop, face->m_face->SurfaceOf(),
		reference->m_face->SurfaceOf()))
	{
	    free_boolean_loop(transformed_loop);
	    free_boolean_loop(union_loop);
	    return false;
	}

	const ON_SimpleArray<ON_Curve *> &current_loop = have_union_loop ?
	    union_loop : reference->m_outerloop;
	LoopBooleanResult union_loops = loop_boolean(current_loop,
	    transformed_loop, BOOLEAN_UNION,
	    boolean_loop_tolerance_for_surface(
		reference->m_face->SurfaceOf(), current_loop, transformed_loop));
	free_boolean_loop(transformed_loop);
	if (union_loops.outerloops.size() != 1 ||
	    !union_loops.innerloops.empty() || !is_loop_valid(
	    union_loops.outerloops[0], ON_ZERO_TOLERANCE))
	{
	    union_loops.ClearOuterloops();
	    union_loops.ClearInnerloops();
	    free_boolean_loop(union_loop);
	    return false;
	}

	free_boolean_loop(union_loop);
	union_loop.Append(union_loops.outerloops[0].Count(),
	    union_loops.outerloops[0].Array());
	union_loops.outerloops[0].Empty();
	union_loops.ClearOuterloops();
	union_loops.ClearInnerloops();
	have_union_loop = true;
    }

    if (!collapse_coplanar_union_tolerance_edges(union_loop,
	reference->m_face->SurfaceOf()))
    {
	free_boolean_loop(union_loop);
	return false;
    }

    TrimmedFace *merged = new TrimmedFace();
    merged->m_face = reference->m_face;
    merged->m_outerloop.Append(union_loop.Count(), union_loop.Array());
    union_loop.Empty();
    merged->m_belong_to_final = TrimmedFace::BELONG;
    merged->m_rev = false;

    for (size_t face_offset = 0; face_offset < face_indices.size();
	 ++face_offset)
    {
	clear_boolean_trimmed_faces(trimmed_faces[face_indices[face_offset]]);
    }
    trimmed_faces[reference_index].Append(merged);
    return true;
}


static void
replace_partial_coplanar_union_faces(
    ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    const ON_SimpleArray<TrimmedFace *> &original_faces,
    const ON_ClassArray<CoplanarFacePair> &coplanar_pairs,
    op_type operation)
{
    if (operation != BOOLEAN_UNION) {
	return;
    }

    std::set<int> processed_faces;
    for (int pair_index = 0; pair_index < coplanar_pairs.Count();
	 ++pair_index)
    {
	std::vector<int> face_indices;
	if (!coplanar_face_component(coplanar_pairs[pair_index],
		coplanar_pairs, face_indices))
	{
	    continue;
	}

	bool processed = false;
	for (size_t face_offset = 0; face_offset < face_indices.size();
	     ++face_offset)
	{
	    if (processed_faces.find(face_indices[face_offset]) !=
		processed_faces.end())
	    {
		processed = true;
		break;
	    }
	}
	if (processed) {
	    continue;
	}

	replace_partial_coplanar_union_component(trimmed_faces, original_faces,
	    face_indices);
	processed_faces.insert(face_indices.begin(), face_indices.end());
    }
}


static bool
replace_partial_coplanar_difference_pair(
    ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    const ON_SimpleArray<TrimmedFace *> &original_faces,
    const CoplanarFacePair &pair)
{
    const int first_index = pair.m_face_index[0];
    const int second_index = pair.m_face_index[1];
    if (first_index < 0 || second_index < 0 ||
	first_index >= original_faces.Count() ||
	second_index >= original_faces.Count() ||
	first_index >= trimmed_faces.Count() ||
	second_index >= trimmed_faces.Count())
    {
	return false;
    }

    const TrimmedFace *first = original_faces[first_index];
    const TrimmedFace *second = original_faces[second_index];
    if (first == NULL || second == NULL || first->m_face == NULL ||
	second->m_face == NULL || !first->m_innerloop.empty() ||
	!second->m_innerloop.empty() ||
	!coplanar_faces_have_matching_orientation(*first, *second))
    {
	return false;
    }

    ON_Xform second_to_first;
    if (!planar_surface_parameter_transform(second->m_face->SurfaceOf(),
	first->m_face->SurfaceOf(), second_to_first))
    {
	return false;
    }

    ON_SimpleArray<ON_Curve *> second_loop;
    if (!transform_boolean_loop(second->m_outerloop, second_to_first,
	second_loop) || !mapped_boolean_loop_matches_surface(
	second->m_outerloop, second_loop, second->m_face->SurfaceOf(),
	first->m_face->SurfaceOf()))
    {
	free_boolean_loop(second_loop);
	return false;
    }

    LoopBooleanResult difference_loops = loop_boolean(first->m_outerloop,
	second_loop, BOOLEAN_DIFF, boolean_loop_tolerance_for_surface(
	first->m_face->SurfaceOf(), first->m_outerloop, second_loop));
    free_boolean_loop(second_loop);

    ON_SimpleArray<TrimmedFace *> replacement;
    append_faces_from_loops(replacement, first, difference_loops);
    bool valid_replacement = true;
    for (int face_index = 0;
	 face_index < replacement.Count() && valid_replacement; ++face_index)
    {
	const TrimmedFace *face = replacement[face_index];
	if (face == NULL || !is_loop_valid(face->m_outerloop,
		ON_ZERO_TOLERANCE))
	{
	    valid_replacement = false;
	    break;
	}
	for (size_t loop_index = 0;
	     loop_index < face->m_innerloop.size();
	     ++loop_index)
	{
	    if (!is_loop_valid(face->m_innerloop[loop_index],
		ON_ZERO_TOLERANCE))
	    {
		valid_replacement = false;
		break;
	    }
	}
    }
    if (!valid_replacement) {
	clear_boolean_trimmed_faces(replacement);
	return false;
    }

    // The matching-oriented portion of a cutter coincides with the first
    // face and therefore cannot contribute to a solid subtraction boundary.
    clear_boolean_trimmed_faces(trimmed_faces[first_index]);
    clear_boolean_trimmed_faces(trimmed_faces[second_index]);
    for (int face_index = 0; face_index < replacement.Count(); ++face_index) {
	TrimmedFace *face = replacement[face_index];
	face->m_belong_to_final = TrimmedFace::BELONG;
	face->m_rev = false;
	trimmed_faces[first_index].Append(face);
	replacement[face_index] = NULL;
    }
    return true;
}


static void
replace_partial_coplanar_difference_faces(
    ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    const ON_SimpleArray<TrimmedFace *> &original_faces,
    const ON_ClassArray<CoplanarFacePair> &coplanar_pairs,
    op_type operation)
{
    if (operation != BOOLEAN_DIFF) {
	return;
    }

    std::set<int> processed_faces;
    for (int pair_index = 0; pair_index < coplanar_pairs.Count();
	 ++pair_index)
    {
	const CoplanarFacePair &pair = coplanar_pairs[pair_index];
	if (processed_faces.find(pair.m_face_index[0]) != processed_faces.end() ||
	    processed_faces.find(pair.m_face_index[1]) != processed_faces.end() ||
	    coplanar_face_peer_count(pair.m_face_index[0], coplanar_pairs) != 1 ||
	    coplanar_face_peer_count(pair.m_face_index[1], coplanar_pairs) != 1)
	{
	    continue;
	}

	const bool replaced = replace_partial_coplanar_difference_pair(
	    trimmed_faces, original_faces, pair);
	if (replaced)
	{
	    processed_faces.insert(pair.m_face_index[0]);
	    processed_faces.insert(pair.m_face_index[1]);
	}
    }
}


static bool
classify_coplanar_trimmed_face(
    TrimmedFace *tface,
    int face_index,
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    const ON_ClassArray<CoplanarFacePair> &coplanar_pairs,
    op_type operation)
{
    if (tface == NULL || brep1 == NULL || brep2 == NULL) {
	throw GeometryGenerationError("Unable to classify a coplanar Boolean face.\n");
    }

    const int face_count1 = brep1->m_F.Count();
    if (coplanar_face_peer_count(face_index, coplanar_pairs) != 1) {
	return false;
    }

    for (int pair_index = 0; pair_index < coplanar_pairs.Count(); ++pair_index) {
	const CoplanarFacePair &pair = coplanar_pairs[pair_index];
	const bool first_operand = face_index == pair.m_face_index[0];
	if (!first_operand && face_index != pair.m_face_index[1]) {
	    continue;
	}

	const int peer_index = first_operand ? pair.m_face_index[1] :
	    pair.m_face_index[0];
	const ON_BrepFace &source_face = first_operand ?
	    brep1->m_F[face_index] : brep2->m_F[face_index - face_count1];
	const ON_BrepFace &peer_face = first_operand ?
	    brep2->m_F[peer_index - face_count1] : brep1->m_F[peer_index];
	ON_Xform parameter_transform;
	if (!planar_surface_parameter_transform(source_face.SurfaceOf(),
		peer_face.SurfaceOf(), parameter_transform))
	{
	    return false;
	}

	const ON_2dPoint source_parameter = get_point_inside_trimmed_face(tface);
	ON_2dPoint peer_parameter;
	if (!map_planar_parameter(parameter_transform, source_parameter,
		peer_parameter))
	{
	    return false;
	}
	const ON_3dPoint source_point = source_face.PointAt(source_parameter.x,
	    source_parameter.y);
	const ON_3dPoint peer_point = peer_face.PointAt(peer_parameter.x,
	    peer_parameter.y);
	if (!source_point.IsValid() || !peer_point.IsValid() ||
	    source_point.DistanceTo(peer_point) > INTERSECTION_TOL)
	{
	    return false;
	}
	if (!point_is_inside_brep_face(peer_face, peer_parameter)) {
	    continue;
	}

	ON_3dVector source_normal;
	ON_3dVector peer_normal;
	if (!source_face.SurfaceOf()->EvNormal(source_parameter.x,
		source_parameter.y, source_normal) ||
		!peer_face.SurfaceOf()->EvNormal(peer_parameter.x,
		peer_parameter.y, peer_normal) || !source_normal.Unitize() ||
		!peer_normal.Unitize())
	{
	    return false;
	}
	if (source_face.m_bRev) {
	    source_normal = -1.0 * source_normal;
	}
	if (peer_face.m_bRev) {
	    peer_normal = -1.0 * peer_normal;
	}
	const bool same_direction = ON_DotProduct(source_normal, peer_normal) > 0.0;

	tface->m_rev = false;
	tface->m_belong_to_final = TrimmedFace::NOT_BELONG;
	switch (operation) {
	    case BOOLEAN_UNION:
	    case BOOLEAN_INTERSECT:
		if (first_operand && same_direction) {
		    tface->m_belong_to_final = TrimmedFace::BELONG;
		}
		break;
	    case BOOLEAN_DIFF:
		if (first_operand && !same_direction) {
		    tface->m_belong_to_final = TrimmedFace::BELONG;
		}
		break;
	    case BOOLEAN_XOR:
		break;
	    default:
		throw GeometryGenerationError("Unexpected Boolean operation.\n");
	}
	return true;
    }

    return false;
}


static void
categorize_trimmed_faces(
    ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    const ON_BoundingBox &brep1_bbox,
    const ON_BoundingBox &brep2_bbox,
    ON_SimpleArray<Subsurface *> &surf_tree1,
    ON_SimpleArray<Subsurface *> &surf_tree2,
    op_type operation,
    const ON_ClassArray<CoplanarFacePair> &coplanar_pairs)
{
    int face_count1 = brep1->m_F.Count();
    for (int i = 0; i < trimmed_faces.Count(); i++) {
	/* Perform inside-outside test to decide whether the trimmed face should
	 * be used in the final b-rep structure or not.
	 * Different operations should be dealt with accordingly.
	 * Use connectivity graphs (optional) which represents the topological
	 * structure of the b-rep. This can reduce time-consuming inside-outside
	 * tests.
	 */
	const ON_SimpleArray<TrimmedFace *> &splitted = trimmed_faces[i];
	const ON_Brep *another_brep = i >= face_count1 ? brep1 : brep2;
	const ON_BoundingBox &another_brep_bbox =
	    i >= face_count1 ? brep1_bbox : brep2_bbox;
	ON_SimpleArray<Subsurface *> &surf_tree = i >= face_count1 ? surf_tree1 : surf_tree2;
	for (int j = 0; j < splitted.Count(); j++) {
	    if (splitted[j]->m_belong_to_final != TrimmedFace::UNKNOWN) {
		// Visited before, don't need to test again
		continue;
	    }
	    if (trimmed_face_has_collapsed_two_curve_outer_loop(splitted[j])) {
		splitted[j]->m_rev = false;
		splitted[j]->m_belong_to_final = TrimmedFace::NOT_BELONG;
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean diagnostic classification face %d split %d: "
			"discarding collapsed two-curve outer loop.\n", i, j);
		}
		continue;
	    }

	    bool coplanar_handled = false;
	    int face_location = INDETERMINATE_BREP;
	    ON_2dPoint classification_parameter = ON_2dPoint::UnsetPoint;
	    if (DEBUG_BREP_BOOLEAN) {
		ON_BoundingBox parameter_bounds;
		bool have_parameter_bounds = false;
		for (int curve_index = 0;
		     curve_index < splitted[j]->m_outerloop.Count();
		     ++curve_index)
		{
		    const ON_Curve *curve = splitted[j]->m_outerloop[curve_index];
		    if (curve == NULL) {
			continue;
		    }
		    const ON_BoundingBox curve_bounds = curve->BoundingBox();
		    if (!curve_bounds.IsValid()) {
			continue;
		    }
		    if (have_parameter_bounds) {
			parameter_bounds.Union(curve_bounds);
		    } else {
			parameter_bounds = curve_bounds;
			have_parameter_bounds = true;
		    }
		}
		const ON_BoundingBox face_bounds = splitted[j]->m_face->BoundingBox();
		bu_log("Boolean diagnostic classifying face %d split %d/%d "
		    "(operand %d source face %d surface %d, loops %d/%zu), "
		    "UV bounds [(%.17g, %.17g), (%.17g, %.17g)], "
		    "3D diagonal %.17g.\n", i, j, splitted.Count(),
		    i < face_count1 ? 0 : 1,
		    splitted[j]->m_face->m_face_index,
		    splitted[j]->m_face->m_si,
		    splitted[j]->m_outerloop.Count(),
		    splitted[j]->m_innerloop.size(),
		    have_parameter_bounds ? parameter_bounds.m_min.x : ON_UNSET_VALUE,
		    have_parameter_bounds ? parameter_bounds.m_min.y : ON_UNSET_VALUE,
		    have_parameter_bounds ? parameter_bounds.m_max.x : ON_UNSET_VALUE,
		    have_parameter_bounds ? parameter_bounds.m_max.y : ON_UNSET_VALUE,
		    face_bounds.IsValid() ? face_bounds.Diagonal().Length() :
		    ON_UNSET_VALUE);
	    }
	    try {
		coplanar_handled = classify_coplanar_trimmed_face(splitted[j], i,
		    brep1, brep2, coplanar_pairs, operation);
		if (!coplanar_handled) {
		    face_location = face_brep_location(splitted[j], another_brep,
			surf_tree, another_brep_bbox,
			&classification_parameter);
		}
	    } catch (InvalidGeometry &e) {
		throw GeometryGenerationError(e.what());
	    } catch (AlgorithmError &e) {
		if (!trimmed_face_has_collapsed_two_curve_outer_loop(splitted[j],
			true))
		{
		    throw GeometryGenerationError(e.what());
		}
		splitted[j]->m_rev = false;
		splitted[j]->m_belong_to_final = TrimmedFace::NOT_BELONG;
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean diagnostic classification face %d split %d: "
			"discarding unclassifiable sub-tolerance two-curve "
			"outer loop.\n", i, j);
		}
		continue;
	    }
	    if (coplanar_handled) {
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean diagnostic classification face %d split %d: "
			"coplanar, selection %d.\n", i, j,
			splitted[j]->m_belong_to_final);
		}
		continue;
	    }
	    if (face_location == INDETERMINATE_BREP) {
		throw GeometryGenerationError("Unable to classify a trimmed Boolean face.\n");
	    }

	    splitted[j]->m_rev = false;
	    splitted[j]->m_belong_to_final = TrimmedFace::NOT_BELONG;
	    switch (face_location) {
		case INSIDE_BREP:
		    if (operation == BOOLEAN_INTERSECT ||
			operation == BOOLEAN_XOR ||
			(operation == BOOLEAN_DIFF && i >= face_count1))
		    {
			splitted[j]->m_belong_to_final = TrimmedFace::BELONG;
		    }
		    if (operation == BOOLEAN_DIFF || operation == BOOLEAN_XOR) {
			splitted[j]->m_rev = true;
		    }
		    break;
		case OUTSIDE_BREP:
		    if (operation == BOOLEAN_UNION ||
			operation == BOOLEAN_XOR ||
			(operation == BOOLEAN_DIFF && i < face_count1))
		    {
			splitted[j]->m_belong_to_final = TrimmedFace::BELONG;
		    }
		    break;
		case ON_BREP_SURFACE: {
		    // get a 3d point on the face
		    ON_2dPoint face_pt2d = classification_parameter.IsValid() ?
			classification_parameter :
			get_point_inside_trimmed_face(splitted[j]);
		    ON_3dPoint face_pt3d = splitted[j]->m_face->PointAt(face_pt2d.x, face_pt2d.y);

		    // find the matching point on the other brep
		    ON_2dPoint brep_pt2d = ON_2dPoint::UnsetPoint;
		    const ON_Surface *brep_surf = NULL;
		    const ON_BrepFace *brep_face = NULL;
		    bool found = false;
		    for (int fi = 0; fi < another_brep->m_F.Count(); ++fi) {
			const ON_BrepFace &face = another_brep->m_F[fi];
			brep_surf = face.SurfaceOf();
			ON_ClassArray<ON_PX_EVENT> px_event;

			if (ON_Intersect(face_pt3d, *brep_surf, px_event,
					 INTERSECTION_TOL, 0, 0, surf_tree[face.m_si]))
			{
			    for (int event_index = 0;
				 event_index < px_event.Count(); ++event_index)
			    {
				const ON_2dPoint parameter(px_event[event_index].m_b[0],
				    px_event[event_index].m_b[1]);
				if (!parameter.IsValid() ||
				    brep_surf->PointAt(parameter.x, parameter.y).
					DistanceTo(face_pt3d) > INTERSECTION_TOL)
				{
				    continue;
				}
				const int peer_location = point_face_location(parameter,
				    face, another_brep);
				if (peer_location != INSIDE_FACE &&
				    peer_location != ON_FACE_BOUNDARY)
				{
				    continue;
				}
				found = true;
				brep_pt2d = parameter;
				brep_face = &face;
				break;
			    }
			}
			if (found)
			    break;
		    }
		    if (found) {
			/* Compare oriented face normals, not merely the underlying
			 * surface parameterizations.  A cavity face and the solid that
			 * fills it have coincident surfaces but opposite material-side
			 * orientations. */
			ON_3dVector brep_norm, face_norm;
			if (!brep_surf->EvNormal(brep_pt2d.x, brep_pt2d.y, brep_norm) ||
			    !splitted[j]->m_face->SurfaceOf()->EvNormal(face_pt2d.x,
				face_pt2d.y, face_norm) || !brep_norm.Unitize() ||
			    !face_norm.Unitize())
			{
			    throw GeometryGenerationError("Unable to compare Boolean face normals.\n");
			}
			if (brep_face->m_bRev)
			    brep_norm = -1.0 * brep_norm;
			if (splitted[j]->m_face->m_bRev)
			    face_norm = -1.0 * face_norm;

			double dot = ON_DotProduct(brep_norm, face_norm);
			bool same_direction = false;
			if (dot > 0) {
			    // normals appear to have same direction
			    same_direction = true;
			}

			if ((operation == BOOLEAN_UNION && same_direction &&
				i < face_count1) ||
			    (operation == BOOLEAN_INTERSECT && same_direction &&
				i < face_count1) ||
			    (operation == BOOLEAN_DIFF && !same_direction && i < face_count1))
			{
			    splitted[j]->m_belong_to_final = TrimmedFace::BELONG;
			}
		    }
		    if (!found) {
			throw GeometryGenerationError("Unable to match overlapping Boolean faces.\n");
		    }
		    // Matching-oriented coincident faces have one owner.  Keeping
		    // both operands creates duplicate sheets or narrow open flaps.
		    break;
		}
		default:
		    throw GeometryGenerationError("Unexpected Boolean face location.\n");
	    }
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("The trimmed face is %s the other brep.",
		       (face_location == INSIDE_BREP) ? "inside" :
		       ((face_location == OUTSIDE_BREP) ? "outside" : "on the surface of"));
	    }
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Boolean diagnostic classification face %d split %d: "
		    "location %d, selection %d.\n", i, j, face_location,
		    splitted[j]->m_belong_to_final);
	    }
	}
    }
}


static bool
apply_boolean_face_classification(
    ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    const BooleanFaceClassification &classification)
{
    for (int face_index = 0; face_index < trimmed_faces.Count(); ++face_index) {
	const bool keep = classification.m_final_faces.find(face_index) !=
	    classification.m_final_faces.end();
	const bool discard = classification.m_discarded_faces.find(face_index) !=
	    classification.m_discarded_faces.end();
	const bool preserve = classification.m_preserved_faces.find(face_index) !=
	    classification.m_preserved_faces.end();
	if (!keep && !discard && !preserve) {
	    continue;
	}
	if ((keep && discard) || (preserve && (!keep || discard))) {
	    return false;
	}

	ON_SimpleArray<TrimmedFace *> &splitted = trimmed_faces[face_index];
	for (int split_index = 0; split_index < splitted.Count(); ++split_index) {
	    if (splitted[split_index] == NULL) {
		return false;
	    }
	    splitted[split_index]->m_belong_to_final = preserve ?
		TrimmedFace::NOT_BELONG : keep ?
		TrimmedFace::BELONG : TrimmedFace::NOT_BELONG;
	    splitted[split_index]->m_rev = false;
	}
    }

    return true;
}


static bool
boolean_component_is_unchanged(
    const std::vector<int> &face_indices,
    int face_offset,
    const BooleanFaceClassification &classification,
    const ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces)
{
    if (face_indices.empty()) {
	return false;
    }

    for (size_t face_offset_index = 0;
	 face_offset_index < face_indices.size();
	 ++face_offset_index)
    {
	const int face_index = face_indices[face_offset_index];
	if (face_index < 0) {
	    return false;
	}

	const int global_face_index = face_offset + face_index;
	if (global_face_index < 0 || global_face_index >= trimmed_faces.Count() ||
	    classification.m_nonpreservable_faces.find(global_face_index) !=
		classification.m_nonpreservable_faces.end() ||
	    classification.m_preserved_faces.find(global_face_index) !=
		classification.m_preserved_faces.end())
	{
	    return false;
	}

	const ON_SimpleArray<TrimmedFace *> &splitted =
	    trimmed_faces[global_face_index];
	if (splitted.Count() != 1 || splitted[0] == NULL ||
	    splitted[0]->m_belong_to_final != TrimmedFace::BELONG ||
	    splitted[0]->m_rev)
	{
	    return false;
	}
    }

    return true;
}


static void
preserve_unchanged_boolean_components(
    const ON_Brep *brep,
    int face_offset,
    const BooleanFaceClassification &classification,
    ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    std::vector<BooleanPreservedComponent> &preserved_components)
{
    if (brep == NULL) {
	return;
    }

    std::vector<ON_BoundingBox> component_bboxes;
    std::vector<std::vector<int> > component_face_indices;
    if (!boolean_brep_component_bounding_boxes(brep, component_bboxes,
	&component_face_indices))
    {
	return;
    }

    for (size_t component_index = 0;
	 component_index < component_face_indices.size();
	 ++component_index)
    {
	const std::vector<int> &face_indices =
	    component_face_indices[component_index];
	if (!boolean_component_is_unchanged(face_indices, face_offset,
		classification, trimmed_faces))
	{
	    continue;
	}

	/* Reuse the source topology only when every retained face is unchanged. */
	preserved_components.push_back(BooleanPreservedComponent(brep,
	    face_indices));
	for (size_t face_offset_index = 0;
	     face_offset_index < face_indices.size();
	     ++face_offset_index)
	{
	    const int face_index = face_offset + face_indices[face_offset_index];
	    trimmed_faces[face_index][0]->m_belong_to_final =
		TrimmedFace::NOT_BELONG;
	}
    }
}


struct BooleanManifoldRegionReference {
    int m_source_face_index;
    int m_split_face_index;

    BooleanManifoldRegionReference(int source_face_index, int split_face_index)
	: m_source_face_index(source_face_index),
	  m_split_face_index(split_face_index)
	{}
};


struct BooleanManifoldShadow {
    BooleanManifoldReport m_report;
    std::vector<BooleanManifoldRegionReference> m_regions[2];
    std::set<int> m_coplanar_faces;
    std::set<int> m_uncertified_faces;
    size_t m_certified_shared_boundaries = 0;
    bool m_requested = false;
    bool m_available = false;
    bool m_coplanar = false;
};


static void standardize_loop_orientations(ON_Brep *brep);
static bool merge_boolean_naked_edges(ON_Brep *brep);


static bool
boolean_manifold_shadow_requested()
{
    const char *setting = getenv("LIBBREP_BOOLEAN_MANIFOLD_SHADOW");
    return setting != NULL && setting[0] == '1' && setting[1] == '\0';
}


static bool
append_boolean_proxy_operand(
    ON_Brep &proxy,
    std::vector<BooleanManifoldRegionReference> &regions,
    const ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    int first_face,
    int face_count,
    const ON_ClassArray<SharedSSICurve> &shared_curves,
    std::vector<bool> &used_shared_curves,
    std::string &detail)
{
    const auto fail = [&detail](const char *message) {
	detail = message;
	return false;
    };
    BooleanSharedTopology shared_topology(shared_curves);
    for (int face_offset = 0; face_offset < face_count; ++face_offset) {
	const int source_face_index = first_face + face_offset;
	if (source_face_index < 0 || source_face_index >= trimmed_faces.Count()) {
	    return fail("split proxy source-face index is invalid");
	}
	const ON_SimpleArray<TrimmedFace *> &source_splits =
	    trimmed_faces[source_face_index];
	int surface_index = -1;
	for (int split_index = 0; split_index < source_splits.Count();
	     ++split_index)
	{
	    const TrimmedFace *source = source_splits[split_index];
	    const ON_Surface *surface = source && source->m_face ?
		source->m_face->SurfaceOf() : NULL;
	    if (surface == NULL) {
		return fail("split proxy region has no source surface");
	    }
	    if (boolean_loop_is_model_point(surface, source->m_outerloop)) {
		continue;
	    }

	    std::unique_ptr<TrimmedFace> copy(source->Duplicate());
	    if (!copy || copy->m_outerloop.Count() < 1) {
		return fail("split proxy region has no outer boundary");
	    }
	    if (surface_index < 0) {
		ON_Surface *surface_copy = surface->Duplicate();
		if (surface_copy == NULL) {
		    return fail("unable to duplicate a split proxy surface");
		}
		surface_index = proxy.AddSurface(surface_copy);
		if (surface_index < 0) {
		    delete surface_copy;
		    return fail("unable to add a split proxy surface");
		}
	    }

	    ON_BrepFace &face = proxy.NewFace(surface_index);
	    if (!add_elements(&proxy, face, copy->m_outerloop,
		    ON_BrepLoop::outer, shared_topology, source_face_index))
	    {
		return fail("unable to assemble a split proxy outer loop");
	    }
	    for (size_t loop_index = 0;
		 loop_index < copy->m_innerloop.size(); ++loop_index)
	    {
		if (boolean_loop_is_model_point(surface,
			copy->m_innerloop[loop_index]))
		{
		    continue;
		}
		if (!add_elements(&proxy, face, copy->m_innerloop[loop_index],
			ON_BrepLoop::inner, shared_topology, source_face_index))
		{
		    return fail("unable to assemble a split proxy inner loop");
		}
	    }
	    proxy.SetTrimIsoFlags(face);
	    if (source->m_face->m_bRev) {
		proxy.FlipFace(face);
	    }
	    face.m_face_user.i = proxy.m_F.Count();
	    regions.push_back(BooleanManifoldRegionReference(source_face_index,
		split_index));
	}
    }

    if (!shared_topology.CanonicalizeSharedBoundaryVertices(&proxy,
	    used_shared_curves, detail))
    {
	return false;
    }
    if (!proxy.m_F.Count()) {
	return fail("split proxy has no nondegenerate face regions");
    }
    proxy.ShrinkSurfaces();
    proxy.Compact();
    standardize_loop_orientations(&proxy);
    proxy.SetTrimBoundingBoxes(false);
    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    if (!proxy.IsValid(&validation_log)) {
	const ON_String message(validation_text);
	detail = "assembled split proxy is invalid before edge merging";
	if (message.Array() != NULL && message.Array()[0] != '\0') {
	    detail += ": ";
	    detail += message.Array();
	}
	return false;
    }
    if (!merge_boolean_naked_edges(&proxy)) {
	return fail("unable to merge coincident split proxy edges");
    }
    proxy.Compact();
    proxy.SetTrimBoundingBoxes(false);
    if (!proxy.IsValid()) {
	return fail("assembled split proxy is invalid");
    }
    if (static_cast<size_t>(proxy.m_F.Count()) != regions.size()) {
	return fail("split proxy face order changed during compaction");
    }
    for (int face_index = 0; face_index < proxy.m_F.Count(); ++face_index) {
	if (proxy.m_F[face_index].m_face_user.i != face_index + 1) {
	    return fail("split proxy face tags changed during compaction");
	}
    }
    return true;
}


static BooleanManifoldShadow
start_boolean_manifold_shadow(
    const ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    int first_face_count,
    int second_face_count,
    const ON_ClassArray<SharedSSICurve> &shared_curves,
    const ON_ClassArray<CoplanarFacePair> &coplanar_pairs,
    op_type operation)
{
    BooleanManifoldShadow shadow;
    shadow.m_requested = boolean_manifold_shadow_requested();
    if (!shadow.m_requested) {
	return shadow;
    }
    ++boolean_manifold_metrics.attempted_operations;
    shadow.m_coplanar = coplanar_pairs.Count() > 0;
    if (shadow.m_coplanar) {
	++boolean_manifold_metrics.coplanar_operations;
	for (int pair_index = 0; pair_index < coplanar_pairs.Count();
	     ++pair_index)
	{
	    shadow.m_coplanar_faces.insert(
		coplanar_pairs[pair_index].m_face_index[0]);
	    shadow.m_coplanar_faces.insert(
		coplanar_pairs[pair_index].m_face_index[1]);
	}
    }

    try {
	ON_Brep first;
	ON_Brep second;
	std::vector<bool> used_shared_curves[2];
	if (!append_boolean_proxy_operand(first, shadow.m_regions[0],
		trimmed_faces, 0, first_face_count, shared_curves,
		used_shared_curves[0], shadow.m_report.detail) ||
	    !append_boolean_proxy_operand(second, shadow.m_regions[1],
		trimmed_faces, first_face_count, second_face_count,
		shared_curves, used_shared_curves[1],
		shadow.m_report.detail))
	{
	    if (shadow.m_report.detail.empty()) {
		shadow.m_report.detail =
		    "unable to assemble a closed exact split-region proxy";
	    }
	    return shadow;
	}
	if (used_shared_curves[0].size() != used_shared_curves[1].size()) {
	    shadow.m_report.detail =
		"split proxies have inconsistent shared-boundary ledgers";
	    return shadow;
	}
	for (size_t curve_index = 0;
	     curve_index < used_shared_curves[0].size(); ++curve_index)
	{
	    if (used_shared_curves[0][curve_index] !=
		    used_shared_curves[1][curve_index])
	    {
		if (curve_index < (size_t)shared_curves.Count()) {
		    shadow.m_uncertified_faces.insert(
			shared_curves[(int)curve_index].m_face_index[0]);
		    shadow.m_uncertified_faces.insert(
			shared_curves[(int)curve_index].m_face_index[1]);
		}
		continue;
	    }
	    if (used_shared_curves[0][curve_index])
		++shadow.m_certified_shared_boundaries;
	}
	shadow.m_available = boolean_manifold_classify(first, second,
	    operation, shadow.m_report);
    } catch (const std::exception &error) {
	shadow.m_report.detail = error.what();
    } catch (...) {
	shadow.m_report.detail = "unexpected Manifold shadow failure";
    }
    return shadow;
}


static void
report_boolean_manifold_shadow(
    const BooleanManifoldShadow &shadow,
    const ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &trimmed_faces,
    bool exact_classification_complete)
{
    if (!shadow.m_requested) {
	return;
    }
    boolean_manifold_metrics.certified_shared_boundaries +=
	shadow.m_certified_shared_boundaries;
    if (!shadow.m_available) {
	++boolean_manifold_metrics.abstained_operations;
	bu_log("Boolean Manifold shadow abstained: %s.\n",
	    shadow.m_report.detail.empty() ? "no certified proxy result" :
	    shadow.m_report.detail.c_str());
	return;
    }

    for (int operand = 0; operand < 2; ++operand) {
	if (shadow.m_regions[operand].size() !=
		shadow.m_report.operand[operand].size())
	{
	    ++boolean_manifold_metrics.abstained_operations;
	    bu_log("Boolean Manifold shadow abstained: region map mismatch.\n");
	    return;
	}
    }

    size_t oracle_decisions = 0;
    size_t decisions = 0;
    size_t abstentions = 0;
    size_t uncompared_decisions = 0;
    size_t coplanar_abstentions = 0;
    size_t uncertified_abstentions = 0;
    size_t selection_agreements = 0;
    size_t selection_disagreements = 0;
    size_t orientation_agreements = 0;
    size_t orientation_disagreements = 0;
    for (int operand = 0; operand < 2; ++operand) {
	for (size_t region_index = 0;
	     region_index < shadow.m_regions[operand].size(); ++region_index)
	{
	    const BooleanManifoldRegionReference &reference =
		shadow.m_regions[operand][region_index];
	    const BooleanManifoldDecision &oracle =
		shadow.m_report.operand[operand][region_index];
	    if (oracle.selection != BOOLEAN_MANIFOLD_ABSTAIN)
		++oracle_decisions;
	    const bool coplanar_excluded = shadow.m_coplanar_faces.find(
		reference.m_source_face_index) != shadow.m_coplanar_faces.end();
	    const bool uncertified_excluded = shadow.m_uncertified_faces.find(
		reference.m_source_face_index) != shadow.m_uncertified_faces.end();
	    if (coplanar_excluded || uncertified_excluded)
	    {
		++abstentions;
		if (coplanar_excluded)
		    ++coplanar_abstentions;
		if (uncertified_excluded)
		    ++uncertified_abstentions;
		continue;
	    }
	    if (reference.m_source_face_index < 0 ||
		reference.m_source_face_index >= trimmed_faces.Count() ||
		reference.m_split_face_index < 0 ||
		reference.m_split_face_index >= trimmed_faces[
		    reference.m_source_face_index].Count())
	    {
		++abstentions;
		continue;
	    }
	    const TrimmedFace *face = trimmed_faces[
		reference.m_source_face_index][reference.m_split_face_index];
	    if (oracle.selection == BOOLEAN_MANIFOLD_ABSTAIN) {
		++abstentions;
		continue;
	    }
	    if (!exact_classification_complete || face == NULL ||
		face->m_belong_to_final == TrimmedFace::UNKNOWN)
	    {
		++uncompared_decisions;
		continue;
	    }

	    ++decisions;
	    const bool oracle_keeps = oracle.selection == BOOLEAN_MANIFOLD_KEEP;
	    const bool exact_keeps =
		face->m_belong_to_final == TrimmedFace::BELONG;
	    if (oracle_keeps != exact_keeps) {
		++selection_disagreements;
		continue;
	    }
	    ++selection_agreements;
	    if (oracle_keeps && oracle.orientation &&
		(oracle.orientation < 0) != face->m_rev)
	    {
		++orientation_disagreements;
	    } else if (oracle_keeps && oracle.orientation) {
		++orientation_agreements;
	    }
	}
    }

    ++boolean_manifold_metrics.classified_operations;
    if (shadow.m_coplanar)
	++boolean_manifold_metrics.coplanar_classified_operations;
    boolean_manifold_metrics.oracle_decisions += oracle_decisions;
    boolean_manifold_metrics.decisions += decisions;
    boolean_manifold_metrics.region_abstentions += abstentions;
    boolean_manifold_metrics.uncompared_decisions += uncompared_decisions;
    boolean_manifold_metrics.coplanar_region_abstentions +=
	coplanar_abstentions;
    boolean_manifold_metrics.uncertified_region_abstentions +=
	uncertified_abstentions;
    boolean_manifold_metrics.selection_agreements += selection_agreements;
    boolean_manifold_metrics.selection_disagreements +=
	selection_disagreements;
    boolean_manifold_metrics.orientation_agreements +=
	orientation_agreements;
    boolean_manifold_metrics.orientation_disagreements +=
	orientation_disagreements;
    boolean_manifold_metrics.input_triangles +=
	shadow.m_report.input_triangles;
    boolean_manifold_metrics.output_triangles +=
	shadow.m_report.output_triangles;

    bu_log("Boolean Manifold shadow: %zu decisions, %zu oracle decisions, "
	"%zu abstentions (%zu coplanar, %zu uncertified), %zu uncompared "
	"decisions, %zu selection agreements, %zu selection disagreements, "
	"%zu orientation agreements, %zu orientation disagreements, %zu "
	"certified shared boundaries, %zu input triangles, %zu output "
	"triangles.\n", decisions, oracle_decisions, abstentions,
	coplanar_abstentions, uncertified_abstentions, uncompared_decisions,
	selection_agreements, selection_disagreements, orientation_agreements,
	orientation_disagreements, shadow.m_certified_shared_boundaries,
	shadow.m_report.input_triangles, shadow.m_report.output_triangles);
}


static ON_ClassArray<ON_SimpleArray<TrimmedFace *> >
get_evaluated_faces(
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    const ON_BoundingBox &brep1_bbox,
    const ON_BoundingBox &brep2_bbox,
    op_type operation,
    ON_ClassArray<SharedSSICurve> &shared_curves,
    std::vector<BooleanPreservedComponent> &preserved_components)
{
    ON_SimpleArray<Subsurface *> surf_tree1, surf_tree2;

    int face_count1 = brep1->m_F.Count();
    int face_count2 = brep2->m_F.Count();

    // check for face counts high enough to cause overflow
    if ((face_count1 + face_count2) < 0)
	return ON_ClassArray<ON_SimpleArray<TrimmedFace *> > ();

    ON_ClassArray<CoplanarFacePair> coplanar_pairs;
    BooleanFaceClassification classification;
    ON_ClassArray<ON_ClassArray<SSICurve> > curves_array;
    try {
	curves_array = get_face_intersection_curves(surf_tree1, surf_tree2,
	    brep1, brep2, brep1_bbox, brep2_bbox, operation,
	    classification, preserved_components, shared_curves,
	    coplanar_pairs);
    } catch (...) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_SSI_PROCESSING,
	    BREP_BOOLEAN_FAILURE_REASON_SSI_PROCESSING);
	throw;
    }

    ON_SimpleArray<TrimmedFace *> brep1_faces, brep2_faces;
    brep1_faces = get_trimmed_faces(brep1);
    brep2_faces = get_trimmed_faces(brep2);

    ON_SimpleArray<TrimmedFace *> original_faces = brep1_faces;
    for (int i = 0; i < brep2_faces.Count(); ++i) {
	original_faces.Append(brep2_faces[i]);
    }

    if (original_faces.Count() != face_count1 + face_count2) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_FACE_SPLITTING,
	    BREP_BOOLEAN_FAILURE_REASON_FACE_SPLIT);
	throw GeometryGenerationError("ON_Boolean() Error: TrimmedFace"
				      " generation failed.\n");
    }

    remove_shared_face_boundary_ssi_curves(shared_curves, original_faces);

    ON_BoundingBox model_bounds = brep1_bbox;
    model_bounds.Union(brep2_bbox);

    // split the surfaces with the intersection curves
    ON_ClassArray<ON_SimpleArray<TrimmedFace *> > trimmed_faces;
    struct TrimmedFaceCleanup {
	ON_ClassArray<ON_SimpleArray<TrimmedFace *> > &faces;
	~TrimmedFaceCleanup()
	{
	    for (int face_index = 0; face_index < faces.Count(); ++face_index) {
		clear_boolean_trimmed_faces(faces[face_index]);
	    }
	}
    } trimmed_face_cleanup = {trimmed_faces};
    for (int i = 0; i < original_faces.Count(); i++) {
	BooleanFailureFaceScope failure_face_scope(i);
	TrimmedFace *first = original_faces[i];
	const int curves_before_boundary_filter = curves_array[i].Count();
	// A curve fully coincident with the trim boundary cannot partition a
	// face.  Keeping it can link that boundary segment to an interior cut.
	remove_face_boundary_ssi_curves(curves_array[i], *first);
	if (DEBUG_BREP_BOOLEAN && (i == 13 || i == 20)) {
	    bu_log("Boolean source face %d SSI curves before/after boundary "
		"filter %d/%d.\n", i, curves_before_boundary_filter,
		curves_array[i].Count());
	}
	normalize_periodic_ssi_parameter_curves(curves_array[i],
	    first->m_face ? first->m_face->SurfaceOf() : NULL, model_bounds);
	ON_ClassArray<LinkedCurve> linked_curves = link_curves(curves_array[i],
	    first, i, brep1, brep2, model_bounds);
	if (DEBUG_BREP_BOOLEAN && (i == 13 || i == 20)) {
	    bu_log("Boolean source face %d retained %d linked SSI curves.\n",
		i, linked_curves.Count());
	}
	//dplot->LinkedCurves(first->m_face->SurfaceOf(), linked_curves);
	//dplot->WriteLog();

	ON_SimpleArray<TrimmedFace *> splitted;
	try {
	    splitted = split_trimmed_face(first, linked_curves);
	} catch (...) {
	    record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_FACE_SPLITTING,
		BREP_BOOLEAN_FAILURE_REASON_FACE_SPLIT);
	    throw;
	}
	trimmed_faces.Append(splitted);

    }

    if (DEBUG_BREP_BOOLEAN) {
	for (int face_index = 0; face_index < trimmed_faces.Count();
	     ++face_index)
	{
	    bu_log("Boolean source face %d has %d splits before coplanar "
		"replacement.\n", face_index, trimmed_faces[face_index].Count());
	}
    }

    if (trimmed_faces.Count() != original_faces.Count()) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_FACE_SPLITTING,
	    BREP_BOOLEAN_FAILURE_REASON_FACE_SPLIT);
	throw GeometryGenerationError("ON_Boolean() Error: "
				      "trimmed_faces.Count() != original_faces.Count()\n");
    }

    /* Coplanar replacement may merge geometry from both operands into one
     * source-face slot.  Construct the diagnostic proxies while operand
     * provenance is still intact, and later exclude every coplanar source
     * face from comparison. */
    const BooleanManifoldShadow manifold_shadow =
	start_boolean_manifold_shadow(trimmed_faces, face_count1, face_count2,
	    shared_curves, coplanar_pairs, operation);

    replace_partial_coplanar_union_faces(trimmed_faces, original_faces,
	coplanar_pairs, operation);
    replace_partial_coplanar_difference_faces(trimmed_faces, original_faces,
	coplanar_pairs, operation);

    if (DEBUG_BREP_BOOLEAN) {
	for (int face_index = 0; face_index < trimmed_faces.Count();
	     ++face_index)
	{
	    bu_log("Boolean source face %d has %d splits after coplanar "
		"replacement.\n", face_index, trimmed_faces[face_index].Count());
	}
    }

    if (!apply_boolean_face_classification(trimmed_faces, classification)) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_FACE_CLASSIFICATION,
	    BREP_BOOLEAN_FAILURE_REASON_FACE_CLASSIFICATION);
	throw GeometryGenerationError("Unable to apply Boolean face classification.\n");
    }
    for (int i = 0; i < original_faces.Count(); i++) {
	delete original_faces[i];
	original_faces[i] = NULL;
    }

    try {
	categorize_trimmed_faces(trimmed_faces, brep1, brep2, brep1_bbox,
	    brep2_bbox, surf_tree1, surf_tree2, operation, coplanar_pairs);
    } catch (...) {
	report_boolean_manifold_shadow(manifold_shadow, trimmed_faces, false);
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_FACE_CLASSIFICATION,
	    BREP_BOOLEAN_FAILURE_REASON_FACE_CLASSIFICATION);
	throw;
    }
    report_boolean_manifold_shadow(manifold_shadow, trimmed_faces, true);

    if (DEBUG_BREP_BOOLEAN) {
	for (int face_index = 0; face_index < trimmed_faces.Count();
	     ++face_index)
	{
	    for (int split_index = 0;
		 split_index < trimmed_faces[face_index].Count(); ++split_index)
	    {
		const TrimmedFace *face = trimmed_faces[face_index][split_index];
		bu_log("Boolean source face %d split %d: selection %d, "
		    "reversed %d.\n", face_index, split_index,
		    face != NULL ? face->m_belong_to_final : -1,
		    face != NULL ? face->m_rev : false);
	    }
	}
    }

    preserve_unchanged_boolean_components(brep1, 0, classification,
	trimmed_faces, preserved_components);
    preserve_unchanged_boolean_components(brep2, face_count1, classification,
	trimmed_faces, preserved_components);

    //dplot->SplitFaces(trimmed_faces);
    //dplot->WriteLog();

    for (int i = 0; i < surf_tree1.Count(); i++) {
	delete surf_tree1[i];
    }

    for (int i = 0; i < surf_tree2.Count(); i++) {
	delete surf_tree2[i];
    }

    return trimmed_faces;
}


static void
standardize_loop_orientations(ON_Brep *brep)
{
    std::map<int, int> reversed_curve2d, reversed_edge;
    for (int face_idx = 0; face_idx < brep->m_F.Count(); ++face_idx) {
	const ON_BrepFace &eb_face = brep->m_F[face_idx];

	for (int loop_idx = 0; loop_idx < eb_face.LoopCount(); ++loop_idx) {
	    const ON_BrepLoop &face_loop = brep->m_L[eb_face.m_li[loop_idx]];
	    if (face_loop.m_type != ON_BrepLoop::outer &&
		face_loop.m_type != ON_BrepLoop::inner) {
		continue;
	    }

	    int loop_direction = brep->LoopDirection(face_loop);
	    if ((loop_direction == LOOP_DIRECTION_CCW && face_loop.m_type == ON_BrepLoop::inner) ||
		(loop_direction == LOOP_DIRECTION_CW && face_loop.m_type == ON_BrepLoop::outer))
	    {
		// found reversed loop
		int brep_li = eb_face.m_li[loop_idx];
		ON_BrepLoop &reversed_loop = brep->m_L[brep_li];

		// reverse all the loop's curves
		for (int trim_idx = 0; trim_idx < reversed_loop.TrimCount(); ++trim_idx) {
		    ON_BrepTrim *trim = reversed_loop.Trim(trim_idx);
		    if (trim->m_type == ON_BrepTrim::singular) {
			continue;
		    }

		    // Replace trim curve2d with a reversed copy.
		    // We'll use a previously made curve, or else
		    // make a new one.
		    if (reversed_curve2d.find(trim->m_c2i) != reversed_curve2d.end()) {
			trim->ChangeTrimCurve(reversed_curve2d[trim->m_c2i]);
		    } else {
			ON_Curve *curve_copy = trim->TrimCurveOf()->DuplicateCurve();
			int copy_c2i = brep->AddTrimCurve(curve_copy);

			reversed_curve2d[trim->m_c2i] = copy_c2i;

			trim->ChangeTrimCurve(copy_c2i);
			trim->Reverse();
		    }
		    // Replace trim edge with a reversed copy.
		    // We'll use a previously made edge, or else
		    // make a new one.
		    if (reversed_edge.find(trim->m_ei) != reversed_edge.end()) {
			trim->RemoveFromEdge(false, false);
			trim->AttachToEdge(reversed_edge[trim->m_ei], trim->m_bRev3d);
		    } else {
			ON_BrepEdge *edge = trim->Edge();
			ON_BrepVertex &v_start = *edge->Vertex(0);
			ON_BrepVertex &v_end = *edge->Vertex(1);
			ON_Interval dom = edge->ProxyCurveDomain();

			ON_Curve *curve_copy = trim->EdgeCurveOf()->DuplicateCurve();
			int copy_c3i = brep->AddEdgeCurve(curve_copy);
			ON_BrepEdge &edge_copy = brep->NewEdge(v_start,
							       v_end, copy_c3i, &dom, edge->m_tolerance);

			reversed_edge[trim->m_ei] = edge_copy.m_edge_index;

			trim->RemoveFromEdge(false, false);
			trim->AttachToEdge(edge_copy.m_edge_index, trim->m_bRev3d);
			trim->Edge()->Reverse();
		    }
		}
		// need to reverse the order of trims in the loop
		// too so they appear continuous
		reversed_loop.m_ti.Reverse();
	    }
	}
    }
}


static bool
is_active_boolean_naked_edge(const ON_Brep *brep, int edge_index)
{
    if (brep == NULL || edge_index < 0 || edge_index >= brep->m_E.Count()) {
	return false;
    }

    const ON_BrepEdge &edge = brep->m_E[edge_index];
    if (edge.m_edge_index != edge_index || edge.m_ti.Count() != 1 ||
	edge.m_vi[0] < 0 || edge.m_vi[1] < 0 ||
	edge.m_vi[0] == edge.m_vi[1])
    {
	return false;
    }

    const int trim_index = edge.m_ti[0];
    if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
	return false;
    }

    const ON_BrepTrim &trim = brep->m_T[trim_index];
    return trim.m_type == ON_BrepTrim::boundary &&
	trim.FaceIndexOf() >= 0 && trim.FaceIndexOf() < brep->m_F.Count();
}


static bool
is_active_boolean_closed_naked_edge(const ON_Brep *brep, int edge_index)
{
    if (brep == NULL || edge_index < 0 || edge_index >= brep->m_E.Count()) {
	return false;
    }

    const ON_BrepEdge &edge = brep->m_E[edge_index];
    if (edge.m_edge_index != edge_index || edge.m_ti.Count() != 1 ||
	edge.m_vi[0] < 0 || edge.m_vi[1] < 0 ||
	edge.m_vi[0] != edge.m_vi[1] || !edge.IsClosed())
    {
	return false;
    }

    const int trim_index = edge.m_ti[0];
    if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
	return false;
    }

    const ON_BrepTrim &trim = brep->m_T[trim_index];
    return trim.m_type == ON_BrepTrim::boundary &&
	trim.FaceIndexOf() >= 0 && trim.FaceIndexOf() < brep->m_F.Count();
}


static bool
boolean_naked_edges_overlap(
    const ON_Brep &brep,
    int first_edge_index,
    int second_edge_index,
    bool &reversed)
{
    reversed = false;
    if (!is_active_boolean_naked_edge(&brep, first_edge_index) ||
	!is_active_boolean_naked_edge(&brep, second_edge_index))
    {
	return false;
    }

    const ON_BrepEdge &first_edge = brep.m_E[first_edge_index];
    const ON_BrepEdge &second_edge = brep.m_E[second_edge_index];
    const int first_trim_index = first_edge.m_ti[0];
    const int second_trim_index = second_edge.m_ti[0];
    const ON_BrepTrim &first_trim = brep.m_T[first_trim_index];
    const ON_BrepTrim &second_trim = brep.m_T[second_trim_index];
    if (first_trim.FaceIndexOf() == second_trim.FaceIndexOf()) {
	return false;
    }

    const bool directly_aligned =
	first_edge.m_vi[0] == second_edge.m_vi[0] &&
	first_edge.m_vi[1] == second_edge.m_vi[1];
    const bool oppositely_aligned =
	first_edge.m_vi[0] == second_edge.m_vi[1] &&
	first_edge.m_vi[1] == second_edge.m_vi[0];
    if (!directly_aligned && !oppositely_aligned) {
	return false;
    }

    // Change topology only when the full curve overlap is independently
    // certified instead of relying on an intersection event.
    if (!ON_CurvesAreEquivalent(&first_edge, &second_edge,
	INTERSECTION_TOL, oppositely_aligned) &&
	!curves_have_matching_full_overlap(&first_edge, &second_edge))
    {
	return false;
    }

    reversed = oppositely_aligned;
    return true;
}


static bool
set_boolean_trim_edge_direction(
    ON_Brep *brep,
    ON_BrepTrim &trim,
    int edge_index,
    bool reversed)
{
    if (brep == NULL || edge_index < 0 || edge_index >= brep->m_E.Count()) {
	return false;
    }

    const ON_BrepEdge &edge = brep->m_E[edge_index];
    if (edge.m_vi[0] < 0 || edge.m_vi[0] >= brep->m_V.Count() ||
	edge.m_vi[1] < 0 || edge.m_vi[1] >= brep->m_V.Count())
    {
	return false;
    }

    trim.m_bRev3d = reversed;
    trim.m_vi[0] = edge.m_vi[reversed ? 1 : 0];
    trim.m_vi[1] = edge.m_vi[reversed ? 0 : 1];
    return true;
}


static bool
merge_shared_open_ssi_edge_vertices(
    ON_Brep *brep,
    const ON_BrepEdge &first_edge,
    const ON_BrepEdge &second_edge,
    bool reversed)
{
    if (brep == NULL) {
	return false;
    }

    for (int endpoint = 0; endpoint < 2; ++endpoint) {
	const int first_vertex_index = first_edge.m_vi[endpoint];
	const int second_vertex_index = second_edge.m_vi[reversed ?
	    1 - endpoint : endpoint];
	if (first_vertex_index < 0 || first_vertex_index >= brep->m_V.Count() ||
	    second_vertex_index < 0 || second_vertex_index >= brep->m_V.Count() ||
	    brep->m_V[first_vertex_index].Point().DistanceTo(
		brep->m_V[second_vertex_index].Point()) > INTERSECTION_TOL)
	{
	    return false;
	}

	if (first_vertex_index != second_vertex_index &&
	    !brep->CombineCoincidentVertices(brep->m_V[first_vertex_index],
		brep->m_V[second_vertex_index]))
	{
	    return false;
	}
    }

    return first_edge.m_vi[0] == second_edge.m_vi[reversed ? 1 : 0] &&
	first_edge.m_vi[1] == second_edge.m_vi[reversed ? 0 : 1];
}


static bool
merge_boolean_naked_edges(ON_Brep *brep)
{
    if (brep == NULL) {
	return false;
    }

    typedef std::pair<int, int> VertexPair;
    std::map<VertexPair, std::vector<int> > edges_by_vertices;
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	if (!is_active_boolean_naked_edge(brep, edge_index)) {
	    continue;
	}

	const ON_BrepEdge &edge = brep->m_E[edge_index];
	const VertexPair vertices(std::min(edge.m_vi[0], edge.m_vi[1]),
	    std::max(edge.m_vi[0], edge.m_vi[1]));
	edges_by_vertices[vertices].push_back(edge_index);
    }

    for (std::map<VertexPair, std::vector<int> >::iterator group =
	edges_by_vertices.begin(); group != edges_by_vertices.end(); ++group) {
	bool merged = true;
	while (merged) {
	    merged = false;
	    const std::vector<int> &edge_indices = group->second;
	    for (size_t first = 0;
		 first < edge_indices.size() && !merged;
		 ++first) {
		for (size_t second = first + 1;
		     second < edge_indices.size(); ++second) {
		    const int first_edge_index = edge_indices[first];
		    const int second_edge_index = edge_indices[second];
		    bool reversed = false;
		    if (!boolean_naked_edges_overlap(*brep, first_edge_index,
			    second_edge_index, reversed)) {
			continue;
		    }

		    ON_BrepEdge &first_edge = brep->m_E[first_edge_index];
		    ON_BrepEdge &second_edge = brep->m_E[second_edge_index];
		    const int first_trim_index = first_edge.m_ti[0];
		    const int second_trim_index = second_edge.m_ti[0];
		    ON_BrepTrim &first_trim = brep->m_T[first_trim_index];
		    ON_BrepTrim &second_trim = brep->m_T[second_trim_index];
		    const bool second_trim_reversed = second_trim.m_bRev3d != reversed;
		    if (!second_trim.RemoveFromEdge(false, false) ||
			!second_trim.AttachToEdge(first_edge_index,
			    second_trim_reversed)) {
			return false;
		    }
		    first_trim.m_type = ON_BrepTrim::mated;
		    second_trim.m_type = ON_BrepTrim::mated;
		    brep->DeleteEdge(second_edge, false);
		    merged = true;
		    break;
		}
	    }
	}
    }

    return true;
}


static bool
is_shared_ssi_edge_candidate(
    const ON_Brep *brep,
    int edge_index,
    int source_face_index)
{
    if (brep == NULL || edge_index < 0 || edge_index >= brep->m_E.Count()) {
	return false;
    }

	const ON_BrepEdge &edge = brep->m_E[edge_index];
    if (edge.TrimCount() != 1 || edge.m_ti.Count() != 1 ||
	edge.m_c3i < 0 || edge.m_c3i >= brep->m_C3.Count() ||
	brep->m_C3[edge.m_c3i] == NULL || edge.m_vi[0] < 0 ||
	edge.m_vi[0] >= brep->m_V.Count() || edge.m_vi[1] < 0 ||
	edge.m_vi[1] >= brep->m_V.Count())
    {
	return false;
    }

    const int trim_index = edge.m_ti[0];
    if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
	return false;
    }

    const int face_index = brep->m_T[trim_index].FaceIndexOf();
    if (face_index < 0 || face_index >= brep->m_F.Count()) {
	return false;
    }

    return brep->m_F[face_index].m_face_user.i ==
	source_face_index + FACE_SOURCE_TAG_OFFSET;
}


static bool
is_shared_closed_ssi_edge_candidate(
    const ON_Brep *brep,
    int edge_index,
    int source_face_index)
{
    if (!is_shared_ssi_edge_candidate(brep, edge_index,
	source_face_index))
    {
	return false;
    }

    const ON_BrepEdge &edge = brep->m_E[edge_index];
    return edge.m_vi[0] >= 0 && edge.m_vi[0] == edge.m_vi[1];
}


static bool
is_shared_open_ssi_edge_candidate(
    const ON_Brep *brep,
    int edge_index,
    int source_face_index)
{
    if (!is_active_boolean_naked_edge(brep, edge_index) ||
	!is_shared_ssi_edge_candidate(brep, edge_index, source_face_index))
    {
	return false;
    }

    return true;
}


static bool
shared_ssi_edge_matches_parameter_curve(
    const ON_Brep *brep,
    int edge_index,
    const SharedSSICurve &shared_curve,
    int parameter_curve_index)
{
    if (parameter_curve_index < 0 || parameter_curve_index > 1 ||
	!is_shared_ssi_edge_candidate(brep, edge_index,
	    shared_curve.m_face_index[parameter_curve_index]))
    {
	return false;
    }

    const ON_BrepEdge &edge = brep->m_E[edge_index];
    const int trim_index = edge.m_ti[0];
    if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
	return false;
    }

    const ON_BrepTrim &trim = brep->m_T[trim_index];
    const int face_index = trim.FaceIndexOf();
    if (face_index < 0 || face_index >= brep->m_F.Count() ||
	trim.m_c2i < 0 || trim.m_c2i >= brep->m_C2.Count())
    {
	return false;
    }

    const ON_Curve *trim_curve = brep->m_C2[trim.m_c2i];
    const ON_Curve *shared_parameter_curve =
	shared_curve.m_parameter_curve[parameter_curve_index];
    double parameter_tolerance = 0.0;
    double curve_parameter_tolerance = 0.0;
    if (trim_curve == NULL || shared_parameter_curve == NULL ||
	!get_face_boundary_curve_tolerances(
	    brep->m_F[face_index].SurfaceOf(), trim_curve,
	    parameter_tolerance, curve_parameter_tolerance))
    {
	return false;
    }
    if (!(parameter_tolerance > 0.0) ||
	!(curve_parameter_tolerance > 0.0)) {
	return false;
    }

    return curves_match_shared_parameter_curve(trim_curve,
	shared_parameter_curve, parameter_tolerance);
}


static bool
shared_open_ssi_edge_matches_curve(
    const ON_Brep *brep,
    int edge_index,
    const SharedSSICurve &shared_curve,
    int parameter_curve_index,
    bool &curve_reversed)
{
    curve_reversed = false;
    if (parameter_curve_index < 0 || parameter_curve_index > 1 ||
	!is_shared_open_ssi_edge_candidate(brep, edge_index,
	shared_curve.m_face_index[parameter_curve_index]) ||
	!shared_ssi_edge_matches_parameter_curve(brep, edge_index,
	shared_curve, parameter_curve_index))
    {
	return false;
    }

    const ON_BrepEdge &edge = brep->m_E[edge_index];
    const double model_tolerance = boolean_model_repair_tolerance(
	brep->BoundingBox());
    if (!open_curve_orientation_from_shared_ssi(brep->m_C3[edge.m_c3i],
	shared_curve.m_curve, curve_reversed, model_tolerance))
    {
	return false;
    }

    curve_reversed = curve_reversed != edge.ProxyCurveIsReversed();
    return true;
}


struct SharedSSIEdgePair {
    int m_first_edge_index;
    int m_second_edge_index;
    bool m_first_curve_reversed;
    bool m_second_curve_reversed;

    SharedSSIEdgePair(
	int first_edge_index,
	int second_edge_index,
	bool first_curve_reversed,
	bool second_curve_reversed)
	: m_first_edge_index(first_edge_index),
	  m_second_edge_index(second_edge_index),
	  m_first_curve_reversed(first_curve_reversed),
	  m_second_curve_reversed(second_curve_reversed)
	{}
};


static bool
closed_trim_vertex_seam(
    const ON_BrepTrim &trim,
    const ON_3dPoint &vertex_point,
    ON_2dPoint &vertex_parameter,
    double &seam_parameter,
    double &parameter_tolerance)
{
    const ON_Curve *trim_curve = trim.TrimCurveOf();
    const ON_Surface *surface = trim.SurfaceOf();
    if (trim_curve == NULL || surface == NULL || !trim_curve->IsClosed())
    {
	return false;
    }

    double curve_parameter_tolerance = 0.0;
    if (!get_face_boundary_curve_tolerances(surface, trim_curve,
	parameter_tolerance, curve_parameter_tolerance) ||
	!(parameter_tolerance > 0.0) ||
	!(curve_parameter_tolerance > 0.0))
    {
	return false;
    }

    const ON_Interval trim_domain = trim_curve->Domain();
    if (!trim_domain.IsIncreasing()) {
	return false;
    }

    const ON_BrepEdge *edge = trim.Edge();
    const ON_Curve *edge_curve = trim.EdgeCurveOf();
    if (edge == NULL || edge_curve == NULL || !edge_curve->IsValid()) {
	return false;
    }

    ON_Interval edge_domain = edge->Domain();
    ON_Interval trim_proxy_domain = trim.Domain();
    ON_Interval edge_curve_domain = edge_curve->Domain();
    edge_domain.MakeIncreasing();
    trim_proxy_domain.MakeIncreasing();
    edge_curve_domain.MakeIncreasing();
    if (!edge_domain.IsIncreasing() || !trim_proxy_domain.IsIncreasing() ||
	!edge_curve_domain.IsIncreasing())
    {
	return false;
    }

    double edge_curve_parameter = edge_curve_domain.Min();
    const ON_3dPoint edge_start = edge_curve->PointAtStart();
    const ON_3dPoint edge_end = edge_curve->PointAtEnd();
    if (!edge_start.IsValid() || !edge_end.IsValid()) {
	return false;
    }
    if (edge_start.DistanceTo(vertex_point) > INTERSECTION_TOL &&
	edge_end.DistanceTo(vertex_point) > INTERSECTION_TOL &&
	!point_3d_to_curve_parameter(vertex_point, edge_curve,
	edge_curve_parameter))
    {
	return false;
    }

    const double edge_parameter = edge->ThisCurveParameter(
	edge_curve_parameter);
    if (!std::isfinite(edge_parameter) || !edge_domain.Includes(
	edge_parameter))
    {
	return false;
    }

    double normalized_parameter = edge_domain.NormalizedParameterAt(
	edge_parameter);
    if (trim.m_bRev3d) {
	normalized_parameter = 1.0 - normalized_parameter;
    }
    const double trim_parameter = trim_proxy_domain.ParameterAt(
	normalized_parameter);
    seam_parameter = trim.RealCurveParameter(trim_parameter);
    if (!std::isfinite(seam_parameter) || !trim_domain.Includes(
	seam_parameter))
    {
	return false;
    }

    if (fabs(seam_parameter - trim_domain.Min()) <=
	curve_parameter_tolerance || fabs(seam_parameter - trim_domain.Max()) <=
	curve_parameter_tolerance)
    {
	seam_parameter = trim_domain.Min();
    }

    vertex_parameter = trim_curve->PointAt(seam_parameter);
    const ON_3dPoint surface_point = surface->PointAt(vertex_parameter.x,
	vertex_parameter.y);
    return vertex_parameter.IsValid() && surface_point.IsValid() &&
	surface_point.DistanceTo(vertex_point) <= INTERSECTION_TOL;
}


static bool
prepare_reseamed_closed_trim_curve(
    const ON_BrepTrim &trim,
    const ON_3dPoint &vertex_point,
    std::unique_ptr<ON_Curve> &reseamed_curve)
{
    ON_2dPoint vertex_parameter = ON_2dPoint::UnsetPoint;
    double seam_parameter = 0.0;
    double parameter_tolerance = 0.0;
    if (!closed_trim_vertex_seam(trim, vertex_point, vertex_parameter,
	seam_parameter, parameter_tolerance))
    {
	return false;
    }

    const ON_Curve *trim_curve = trim.TrimCurveOf();
    const ON_Surface *surface = trim.SurfaceOf();
    if (trim_curve == NULL || surface == NULL || seam_parameter ==
	trim_curve->Domain().Min())
    {
	return trim_curve != NULL && surface != NULL;
    }

    std::unique_ptr<ON_Curve> seam_curve(trim_curve->DuplicateCurve());
    if (!seam_curve || !seam_curve->ChangeClosedCurveSeam(seam_parameter) ||
	!seam_curve->IsClosed())
    {
	return false;
    }

    const ON_3dPoint seam_start = seam_curve->PointAtStart();
    const ON_3dPoint seam_end = seam_curve->PointAtEnd();
    if (!seam_start.IsValid() || !seam_end.IsValid() ||
	seam_start.DistanceTo(vertex_parameter) > parameter_tolerance ||
	seam_end.DistanceTo(vertex_parameter) > parameter_tolerance)
    {
	return false;
    }

    const ON_3dPoint lifted_seam = surface->PointAt(seam_start.x,
	seam_start.y);
    if (!lifted_seam.IsValid() ||
	lifted_seam.DistanceTo(vertex_point) > INTERSECTION_TOL)
    {
	return false;
    }

    reseamed_curve.reset(seam_curve.release());
    return true;
}


enum SharedSSIEdgeRepairResult {
    SHARED_SSI_EDGE_REPAIR_SKIPPED,
    SHARED_SSI_EDGE_REPAIR_COMPLETE,
    SHARED_SSI_EDGE_REPAIR_FAILURE
};


static SharedSSIEdgeRepairResult
repair_shared_closed_ssi_edge_pair(
    ON_Brep *brep,
    const SharedSSIEdgePair &edge_pair)
{
    if (brep == NULL || edge_pair.m_first_edge_index < 0 ||
	edge_pair.m_first_edge_index >= brep->m_E.Count() ||
	edge_pair.m_second_edge_index < 0 ||
	edge_pair.m_second_edge_index >= brep->m_E.Count() ||
	edge_pair.m_first_edge_index == edge_pair.m_second_edge_index)
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    ON_BrepEdge &first_edge = brep->m_E[edge_pair.m_first_edge_index];
    ON_BrepEdge &second_edge = brep->m_E[edge_pair.m_second_edge_index];
    if (first_edge.TrimCount() != 1 || second_edge.TrimCount() != 1 ||
	first_edge.m_ti.Count() != 1 || second_edge.m_ti.Count() != 1 ||
	first_edge.m_vi[0] != first_edge.m_vi[1] ||
	second_edge.m_vi[0] != second_edge.m_vi[1] || !first_edge.IsClosed() ||
	!second_edge.IsClosed())
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const int first_trim_index = first_edge.m_ti[0];
    const int second_trim_index = second_edge.m_ti[0];
    if (first_trim_index < 0 || first_trim_index >= brep->m_T.Count() ||
	second_trim_index < 0 || second_trim_index >= brep->m_T.Count())
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    ON_BrepTrim &first_trim = brep->m_T[first_trim_index];
    ON_BrepTrim &second_trim = brep->m_T[second_trim_index];
    const ON_Curve *first_trim_curve = first_trim.TrimCurveOf();
    const ON_Curve *second_trim_curve = second_trim.TrimCurveOf();
    if (first_trim_curve == NULL || second_trim_curve == NULL ||
	first_trim.m_ei != edge_pair.m_first_edge_index ||
	second_trim.m_ei != edge_pair.m_second_edge_index)
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const bool first_trim_closed = first_trim_curve->IsClosed();
    const bool second_trim_closed = second_trim_curve->IsClosed();
    if (!first_trim_closed && !second_trim_closed) {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    ON_BrepEdge &closed_edge = first_trim_closed ? first_edge : second_edge;
    ON_BrepEdge &canonical_edge = first_trim_closed ? second_edge : first_edge;
    ON_BrepTrim &closed_trim = first_trim_closed ? first_trim : second_trim;
    ON_BrepTrim &canonical_trim = first_trim_closed ? second_trim : first_trim;
    const ON_Surface *canonical_surface = canonical_trim.SurfaceOf();
    const bool closed_edge_reversed = first_trim_closed ?
	edge_pair.m_first_curve_reversed : edge_pair.m_second_curve_reversed;
    const bool canonical_edge_reversed = first_trim_closed ?
	edge_pair.m_second_curve_reversed : edge_pair.m_first_curve_reversed;
    if (canonical_edge.m_vi[0] < 0 ||
	canonical_edge.m_vi[0] >= brep->m_V.Count() ||
	closed_trim.m_vi[0] != closed_edge.m_vi[0] ||
	closed_trim.m_vi[1] != closed_edge.m_vi[1] ||
	canonical_trim.m_vi[0] != canonical_edge.m_vi[0] ||
	canonical_trim.m_vi[1] != canonical_edge.m_vi[1] ||
	canonical_surface == NULL || (!canonical_surface->IsClosed(0) &&
	!canonical_surface->IsClosed(1)))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const ON_BrepVertex &canonical_vertex = brep->m_V[canonical_edge.m_vi[0]];
    const ON_3dPoint canonical_start = canonical_edge.PointAtStart();
    const ON_3dPoint canonical_end = canonical_edge.PointAtEnd();
    if (!canonical_vertex.Point().IsValid() || !canonical_start.IsValid() ||
	!canonical_end.IsValid() || canonical_start.DistanceTo(
	canonical_vertex.Point()) > INTERSECTION_TOL || canonical_end.DistanceTo(
	canonical_vertex.Point()) > INTERSECTION_TOL)
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    std::unique_ptr<ON_Curve> reseamed_curve;
    if (!prepare_reseamed_closed_trim_curve(closed_trim,
	canonical_vertex.Point(), reseamed_curve))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    if (reseamed_curve) {
	const int curve_index = brep->AddTrimCurve(reseamed_curve.release());
	if (curve_index < 0 || !closed_trim.ChangeTrimCurve(curve_index)) {
	    return SHARED_SSI_EDGE_REPAIR_FAILURE;
	}
    }

    const bool closed_trim_vs_ssi = closed_trim.m_bRev3d !=
	closed_edge_reversed;
    const bool closed_trim_reversed = closed_trim_vs_ssi !=
	canonical_edge_reversed;
    if (!closed_trim.RemoveFromEdge(true, true) ||
	!closed_trim.AttachToEdge(canonical_edge.m_edge_index,
	    closed_trim_reversed))
    {
	return SHARED_SSI_EDGE_REPAIR_FAILURE;
    }

    closed_trim.m_type = ON_BrepTrim::mated;
    canonical_trim.m_type = ON_BrepTrim::mated;
    brep->DeleteEdge(closed_edge, false);
    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static bool
repair_shared_closed_ssi_edges(
    ON_Brep *brep,
    const ON_ClassArray<SharedSSICurve> &shared_curves)
{
    if (brep == NULL) {
	return false;
    }
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean closed SSI repair has %d shared curves.\n",
	    shared_curves.Count());
    }

    for (int curve_index = 0; curve_index < shared_curves.Count(); ++curve_index) {
	const SharedSSICurve &shared_curve = shared_curves[curve_index];
	if (shared_curve.m_curve == NULL || !shared_curve.m_curve->IsClosed()) {
	    continue;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean shared closed SSI %d faces %d/%d, domain %.17g -> "
		"%.17g, point %.17g %.17g %.17g.\n", curve_index,
		shared_curve.m_face_index[0], shared_curve.m_face_index[1],
		shared_curve.m_curve->Domain().Min(),
		shared_curve.m_curve->Domain().Max(),
		shared_curve.m_curve->PointAtStart().x,
		shared_curve.m_curve->PointAtStart().y,
		shared_curve.m_curve->PointAtStart().z);
	}
	std::vector<SharedSSIEdgePair> edge_pairs;
	for (int first_edge_index = 0; first_edge_index < brep->m_E.Count(); ++first_edge_index) {
	    if (!is_shared_closed_ssi_edge_candidate(brep, first_edge_index,
		    shared_curve.m_face_index[0]) ||
		!shared_ssi_edge_matches_parameter_curve(brep,
		    first_edge_index, shared_curve, 0))
	    {
		continue;
	    }

	    const ON_BrepEdge &first_edge = brep->m_E[first_edge_index];
	    bool first_curve_reversed = false;
	    const bool first_oriented = closed_curve_orientation_from_shared_ssi(
		brep->m_C3[first_edge.m_c3i], shared_curve.m_curve,
		first_curve_reversed);
	    if (!first_oriented) {
		continue;
	    }
	    first_curve_reversed = first_curve_reversed !=
		first_edge.ProxyCurveIsReversed();

	    for (int second_edge_index = 0; second_edge_index < brep->m_E.Count(); ++second_edge_index) {
		if (!is_shared_closed_ssi_edge_candidate(brep,
			second_edge_index, shared_curve.m_face_index[1]) ||
		    !shared_ssi_edge_matches_parameter_curve(brep,
			second_edge_index, shared_curve, 1))
		{
		    continue;
		}

		const ON_BrepEdge &second_edge = brep->m_E[second_edge_index];
		bool second_curve_reversed = false;
		const bool second_oriented = closed_curve_orientation_from_shared_ssi(
		    brep->m_C3[second_edge.m_c3i], shared_curve.m_curve,
		    second_curve_reversed);
		if (!second_oriented) {
		    continue;
		}
		second_curve_reversed = second_curve_reversed !=
		    second_edge.ProxyCurveIsReversed();
		edge_pairs.push_back(SharedSSIEdgePair(first_edge_index,
					       second_edge_index,
						       first_curve_reversed,
						       second_curve_reversed));
	    }
	}
	if (DEBUG_BREP_BOOLEAN || edge_pairs.size() != 1) {
	    bu_log("Boolean shared closed SSI %d produced %zu candidate pairs.\n",
		curve_index, edge_pairs.size());
	}
	if (edge_pairs.size() != 1) {
	    continue;
	}

	const SharedSSIEdgeRepairResult result =
	    repair_shared_closed_ssi_edge_pair(brep, edge_pairs[0]);
	if (result == SHARED_SSI_EDGE_REPAIR_FAILURE) {
	    return false;
	}
    }

    return true;
}


/* Limit sampling density without excluding any curve span from validation. */
static const int BOOLEAN_TOLERANCE_MAXIMUM_SAMPLES_PER_SPAN = 32;
static const int BOOLEAN_TOLERANCE_TARGET_SAMPLES = 1024;
static const double BOOLEAN_OUTPUT_TOLERANCE_SAFETY_FACTOR = 1.05;


template <typename SampleFunction>
static bool
for_each_boolean_curve_sample(
    const ON_Curve &curve,
    const SampleFunction &sample)
{
    const int span_count = curve.SpanCount();
    if (span_count < 1) {
	return false;
    }

    std::vector<double> span_parameters(static_cast<size_t>(span_count) + 1);
    if (!curve.GetSpanVector(span_parameters.data())) {
	return false;
    }

    const int samples_per_span = std::max(1, std::min(
	BOOLEAN_TOLERANCE_MAXIMUM_SAMPLES_PER_SPAN,
	BOOLEAN_TOLERANCE_TARGET_SAMPLES / span_count));
    for (int span_index = 0; span_index < span_count; ++span_index) {
	const ON_Interval span(span_parameters[span_index],
		span_parameters[span_index + 1]);
	if (!span.IsIncreasing()) {
	    return false;
	}

	for (int sample_index = 0;
	     sample_index < samples_per_span;
	     ++sample_index)
	{
	    const double fraction = static_cast<double>(sample_index) /
		samples_per_span;
	    const ON_3dPoint point = curve.PointAt(span.ParameterAt(fraction));
	    if (!point.IsValid() || !sample(point)) {
		return false;
	    }
	}
    }

    const ON_3dPoint endpoint = curve.PointAt(span_parameters[span_count]);
    return endpoint.IsValid() && sample(endpoint);
}


static bool
open_boolean_edge_has_matching_vertices(
    const ON_Brep &brep,
    const ON_BrepEdge &edge)
{
    if (edge.m_vi[0] < 0 || edge.m_vi[0] >= brep.m_V.Count() ||
	edge.m_vi[1] < 0 || edge.m_vi[1] >= brep.m_V.Count() ||
	edge.m_vi[0] == edge.m_vi[1])
    {
	return false;
    }

    const ON_3dPoint edge_start = edge.PointAtStart();
    const ON_3dPoint edge_end = edge.PointAtEnd();
    const ON_3dPoint vertex_start = brep.m_V[edge.m_vi[0]].Point();
    const ON_3dPoint vertex_end = brep.m_V[edge.m_vi[1]].Point();
    return edge_start.IsValid() && edge_end.IsValid() &&
	vertex_start.IsValid() && vertex_end.IsValid() &&
	edge_start.DistanceTo(vertex_start) <= INTERSECTION_TOL &&
	edge_end.DistanceTo(vertex_end) <= INTERSECTION_TOL;
}


static SharedSSIEdgeRepairResult
repair_shared_open_ssi_edge_pair(
    ON_Brep *brep,
    const SharedSSIEdgePair &edge_pair)
{
    if (brep == NULL || edge_pair.m_first_edge_index < 0 ||
	edge_pair.m_first_edge_index >= brep->m_E.Count() ||
	edge_pair.m_second_edge_index < 0 ||
	edge_pair.m_second_edge_index >= brep->m_E.Count() ||
	edge_pair.m_first_edge_index == edge_pair.m_second_edge_index ||
	!is_active_boolean_naked_edge(brep, edge_pair.m_first_edge_index) ||
	!is_active_boolean_naked_edge(brep, edge_pair.m_second_edge_index))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    ON_BrepEdge &first_edge = brep->m_E[edge_pair.m_first_edge_index];
    ON_BrepEdge &second_edge = brep->m_E[edge_pair.m_second_edge_index];
    if (first_edge.IsClosed() || second_edge.IsClosed() ||
	!open_boolean_edge_has_matching_vertices(*brep, first_edge) ||
	!open_boolean_edge_has_matching_vertices(*brep, second_edge))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const int first_trim_index = first_edge.m_ti[0];
    const int second_trim_index = second_edge.m_ti[0];
    if (first_trim_index < 0 || first_trim_index >= brep->m_T.Count() ||
	second_trim_index < 0 || second_trim_index >= brep->m_T.Count())
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const ON_BrepTrim &first_trim = brep->m_T[first_trim_index];
    const ON_BrepTrim &second_trim = brep->m_T[second_trim_index];
    if (first_trim.m_ei != edge_pair.m_first_edge_index ||
	second_trim.m_ei != edge_pair.m_second_edge_index ||
	first_trim.FaceIndexOf() == second_trim.FaceIndexOf())
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const bool edges_are_reversed = edge_pair.m_first_curve_reversed !=
	edge_pair.m_second_curve_reversed;
    const ON_3dPoint first_start = first_edge.PointAtStart();
    const ON_3dPoint first_end = first_edge.PointAtEnd();
    const ON_3dPoint second_matching_start = edges_are_reversed ?
	second_edge.PointAtEnd() : second_edge.PointAtStart();
    const ON_3dPoint second_matching_end = edges_are_reversed ?
	second_edge.PointAtStart() : second_edge.PointAtEnd();
    const int second_matching_start_vertex = edges_are_reversed ?
	second_edge.m_vi[1] : second_edge.m_vi[0];
    const int second_matching_end_vertex = edges_are_reversed ?
	second_edge.m_vi[0] : second_edge.m_vi[1];
    const ON_3dPoint first_start_vertex = brep->m_V[first_edge.m_vi[0]].Point();
    const ON_3dPoint first_end_vertex = brep->m_V[first_edge.m_vi[1]].Point();
    const ON_3dPoint second_start_vertex =
	brep->m_V[second_matching_start_vertex].Point();
    const ON_3dPoint second_end_vertex =
	brep->m_V[second_matching_end_vertex].Point();
    if (first_start.DistanceTo(second_matching_start) > INTERSECTION_TOL ||
	first_end.DistanceTo(second_matching_end) > INTERSECTION_TOL ||
	first_start_vertex.DistanceTo(second_start_vertex) > INTERSECTION_TOL ||
	first_end_vertex.DistanceTo(second_end_vertex) > INTERSECTION_TOL)
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }
    ON_Brep rollback(*brep);
    if (!merge_shared_open_ssi_edge_vertices(brep, first_edge, second_edge,
	edges_are_reversed))
    {
	*brep = rollback;
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    ON_BrepTrim &updated_first_trim = brep->m_T[first_trim_index];
    ON_BrepTrim &updated_second_trim = brep->m_T[second_trim_index];
    const bool second_trim_reversed = updated_second_trim.m_bRev3d !=
	edges_are_reversed;
    if (!updated_second_trim.RemoveFromEdge(false, false) ||
	!updated_second_trim.AttachToEdge(edge_pair.m_first_edge_index,
	second_trim_reversed) || !set_boolean_trim_edge_direction(brep,
	    updated_second_trim, edge_pair.m_first_edge_index,
	    second_trim_reversed))
    {
	*brep = rollback;
	return SHARED_SSI_EDGE_REPAIR_FAILURE;
    }

    updated_first_trim.m_type = ON_BrepTrim::mated;
    updated_second_trim.m_type = ON_BrepTrim::mated;
    brep->DeleteEdge(brep->m_E[edge_pair.m_second_edge_index], false);
    if (!brep->Compact() || !brep->IsValid()) {
	*brep = rollback;
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static bool
repair_shared_open_ssi_edges(
    ON_Brep *brep,
    const ON_ClassArray<SharedSSICurve> &shared_curves)
{
    if (brep == NULL) {
	return false;
    }
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean open SSI repair has %d shared curves.\n",
	    shared_curves.Count());
    }

    for (int curve_index = 0; curve_index < shared_curves.Count(); ++curve_index) {
	const SharedSSICurve &shared_curve = shared_curves[curve_index];
	if (shared_curve.m_curve == NULL || shared_curve.m_curve->IsClosed()) {
	    continue;
	}
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_3dPoint shared_start = shared_curve.m_curve->PointAtStart();
	    const ON_3dPoint shared_end = shared_curve.m_curve->PointAtEnd();
	    bu_log("Boolean shared open SSI %d faces %d/%d, domain %.17g -> "
		"%.17g, curve %.17g %.17g %.17g -> %.17g %.17g %.17g.\n",
		curve_index, shared_curve.m_face_index[0],
		shared_curve.m_face_index[1],
		shared_curve.m_curve->Domain().Min(),
		shared_curve.m_curve->Domain().Max(), shared_start.x,
		shared_start.y, shared_start.z, shared_end.x, shared_end.y,
		shared_end.z);
	}

	std::vector<std::pair<int, bool> > first_edge_matches;
	std::vector<std::pair<int, bool> > second_edge_matches;
	for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	    if (DEBUG_BREP_BOOLEAN) {
		for (int side = 0; side < 2; ++side) {
		    if (!is_shared_ssi_edge_candidate(brep, edge_index,
			    shared_curve.m_face_index[side]))
		    {
			continue;
		    }
		    const bool parameter_match =
			shared_ssi_edge_matches_parameter_curve(brep, edge_index,
			    shared_curve, side);
		    bool model_reversed = false;
		    const ON_BrepEdge &diagnostic_edge = brep->m_E[edge_index];
		    const bool model_match = diagnostic_edge.m_c3i >= 0 &&
			diagnostic_edge.m_c3i < brep->m_C3.Count() &&
			open_curve_orientation_from_shared_ssi(
			    brep->m_C3[diagnostic_edge.m_c3i],
			    shared_curve.m_curve, model_reversed);
		    const ON_3dPoint edge_start = diagnostic_edge.PointAtStart();
		    const ON_3dPoint edge_end = diagnostic_edge.PointAtEnd();
		    const ON_3dPoint shared_start =
			shared_curve.m_curve->PointAtStart();
		    const ON_3dPoint shared_end =
			shared_curve.m_curve->PointAtEnd();
		    const double direct_endpoint_distance = std::max(
			edge_start.DistanceTo(shared_start),
			edge_end.DistanceTo(shared_end));
		    const double reverse_endpoint_distance = std::max(
			edge_start.DistanceTo(shared_end),
			edge_end.DistanceTo(shared_start));
		    ON_NurbsCurve diagnostic_nurbs;
		    if (shared_curve.m_face_index[side] == 1 &&
			brep->m_C3[diagnostic_edge.m_c3i]->GetNurbForm(
			diagnostic_nurbs) > 0)
		    {
			double nearest_start = diagnostic_nurbs.Domain().Min();
			double nearest_end = diagnostic_nurbs.Domain().Max();
			if (ON_NurbsCurve_GetClosestPoint(&nearest_start,
				&diagnostic_nurbs, shared_start) &&
			    ON_NurbsCurve_GetClosestPoint(&nearest_end,
				&diagnostic_nurbs, shared_end))
			{
			    bu_log("    nearest shared endpoints parameters %.17g/"
				"%.17g, distances %.17g/%.17g.\n",
				diagnostic_nurbs.Domain().NormalizedParameterAt(
				    nearest_start),
				diagnostic_nurbs.Domain().NormalizedParameterAt(
				    nearest_end),
				diagnostic_nurbs.PointAt(nearest_start).DistanceTo(
				    shared_start),
				diagnostic_nurbs.PointAt(nearest_end).DistanceTo(
				    shared_end));
			}
		    }
		    if (std::min(direct_endpoint_distance,
			reverse_endpoint_distance) < 0.01)
		    {
			bool diagnostic_reversed = false;
			bu_log("    certified coincidence at 0.001/0.1/1.0: "
			    "%d/%d/%d.\n", brep_curves_coincident(
				*brep->m_C3[diagnostic_edge.m_c3i],
				*shared_curve.m_curve, 0.001,
				&diagnostic_reversed), brep_curves_coincident(
				*brep->m_C3[diagnostic_edge.m_c3i],
				*shared_curve.m_curve, 0.1,
				&diagnostic_reversed), brep_curves_coincident(
				*brep->m_C3[diagnostic_edge.m_c3i],
				*shared_curve.m_curve, 1.0,
				&diagnostic_reversed));
		    }
		    const ON_BrepTrim &diagnostic_trim =
			brep->m_T[diagnostic_edge.m_ti[0]];
		    const ON_Curve *diagnostic_parameter_curve =
			diagnostic_trim.TrimCurveOf();
		    const ON_Curve *shared_parameter_curve =
			shared_curve.m_parameter_curve[side];
		    double parameter_direct_start = -1.0;
		    double parameter_direct_end = -1.0;
		    double parameter_reverse_start = -1.0;
		    double parameter_reverse_end = -1.0;
		    if (diagnostic_parameter_curve != NULL &&
			shared_parameter_curve != NULL)
		    {
			parameter_direct_start = diagnostic_parameter_curve->
			    PointAtStart().DistanceTo(shared_parameter_curve->
				PointAtStart());
			parameter_direct_end = diagnostic_parameter_curve->
			    PointAtEnd().DistanceTo(shared_parameter_curve->
				PointAtEnd());
			parameter_reverse_start = diagnostic_parameter_curve->
			    PointAtStart().DistanceTo(shared_parameter_curve->
				PointAtEnd());
			parameter_reverse_end = diagnostic_parameter_curve->
			    PointAtEnd().DistanceTo(shared_parameter_curve->
				PointAtStart());
		    }
		    bu_log("  side %d edge %d face %d parameter %d model %d "
			"reversed %d, model endpoints %.17g/%.17g or "
			"%.17g/%.17g, parameter endpoints %.17g/%.17g or "
			"%.17g/%.17g, curve %.17g %.17g %.17g -> %.17g "
			"%.17g %.17g.\n", side, edge_index,
			brep->m_T[diagnostic_edge.m_ti[0]].FaceIndexOf(),
			parameter_match, model_match, model_reversed,
			edge_start.DistanceTo(shared_start),
			edge_end.DistanceTo(shared_end),
			edge_start.DistanceTo(shared_end),
			edge_end.DistanceTo(shared_start),
			parameter_direct_start, parameter_direct_end,
			parameter_reverse_start, parameter_reverse_end,
			edge_start.x, edge_start.y, edge_start.z, edge_end.x,
			    edge_end.y, edge_end.z);
		}
	    }
		bool curve_reversed = false;
		if (shared_open_ssi_edge_matches_curve(brep, edge_index,
			shared_curve, 0, curve_reversed))
		{
			first_edge_matches.push_back(std::make_pair(edge_index,
				curve_reversed));
		}

		curve_reversed = false;
		if (shared_open_ssi_edge_matches_curve(brep, edge_index,
			shared_curve, 1, curve_reversed))
		{
			second_edge_matches.push_back(std::make_pair(edge_index,
				curve_reversed));
		}
	}
	if (DEBUG_BREP_BOOLEAN || first_edge_matches.size() != 1 ||
	    second_edge_matches.size() != 1)
	{
	    bu_log("Boolean shared open SSI %d matched %zu/%zu edges.\n",
		curve_index, first_edge_matches.size(), second_edge_matches.size());
	}

	if (first_edge_matches.size() != 1 || second_edge_matches.size() != 1) {
	    continue;
	}

	const SharedSSIEdgePair edge_pair(first_edge_matches[0].first,
	    second_edge_matches[0].first, first_edge_matches[0].second,
	    second_edge_matches[0].second);
	const SharedSSIEdgeRepairResult result =
	    repair_shared_open_ssi_edge_pair(brep, edge_pair);
	if (result == SHARED_SSI_EDGE_REPAIR_FAILURE) {
	    return false;
	}
    }

    return true;
}


static void
record_boolean_remaining_ssi_failure(
    const ON_Brep *brep,
    const ON_ClassArray<SharedSSICurve> &shared_curves)
{
    if (boolean_failure_info == NULL ||
	boolean_failure_info->stage != BREP_BOOLEAN_FAILURE_STAGE_NONE ||
	brep == NULL)
    {
	return;
    }

    const double tolerance = boolean_model_repair_tolerance(
	brep->BoundingBox());
    for (int curve_index = 0; curve_index < shared_curves.Count();
	 ++curve_index)
    {
	const SharedSSICurve &shared_curve = shared_curves[curve_index];
	if (shared_curve.m_curve == NULL)
	    continue;

	const bool closed = shared_curve.m_curve->IsClosed();
	std::vector<int> parameter_matches[2];
	std::vector<int> model_matches[2];
	for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	    for (int side = 0; side < 2; ++side) {
		const bool candidate = closed ?
		    is_shared_closed_ssi_edge_candidate(brep, edge_index,
			shared_curve.m_face_index[side]) :
		    is_shared_open_ssi_edge_candidate(brep, edge_index,
			shared_curve.m_face_index[side]);
		if (!candidate || !shared_ssi_edge_matches_parameter_curve(
			brep, edge_index, shared_curve, side))
		{
		    continue;
		}
		parameter_matches[side].push_back(edge_index);

		const ON_BrepEdge &edge = brep->m_E[edge_index];
		bool reversed = false;
		const bool model_match = closed ?
		    closed_curve_orientation_from_shared_ssi(
			brep->m_C3[edge.m_c3i], shared_curve.m_curve,
			reversed) :
		    open_curve_orientation_from_shared_ssi(
			brep->m_C3[edge.m_c3i], shared_curve.m_curve,
			reversed, tolerance);
		if (model_match)
		    model_matches[side].push_back(edge_index);
	    }
	}

	for (int side = 0; side < 2; ++side) {
	    if (!parameter_matches[side].empty() &&
		model_matches[side].empty())
	    {
		const int peer_side = 1 - side;
		const int peer_edge = model_matches[peer_side].empty() ? -1 :
		    model_matches[peer_side][0];
		record_boolean_output_topology(brep);
		record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_SSI_PROCESSING,
		    BREP_BOOLEAN_FAILURE_REASON_CURVE_PROJECTION,
		    shared_curve.m_face_index[side],
		    shared_curve.m_face_index[peer_side],
		    parameter_matches[side][0], peer_edge, tolerance);
		return;
	    }
	}

	if (model_matches[0].empty() && model_matches[1].empty())
	    continue;

	const int populated_side = model_matches[0].empty() ? 1 : 0;
	const int peer_side = 1 - populated_side;
	const int edge_index = model_matches[populated_side][0];
	const int peer_edge_index = model_matches[peer_side].empty() ? -1 :
	    model_matches[peer_side][0];
	enum brep_boolean_failure_reason reason;
	if (model_matches[0].empty() || model_matches[1].empty()) {
	    reason = closed ?
		BREP_BOOLEAN_FAILURE_REASON_CLOSED_SSI_MISSING_MATE :
		BREP_BOOLEAN_FAILURE_REASON_OPEN_SSI_MISSING_MATE;
	} else if (model_matches[0].size() != 1 ||
	    model_matches[1].size() != 1)
	{
	    reason = BREP_BOOLEAN_FAILURE_REASON_SSI_EDGE_PARTITION;
	    record_boolean_ambiguous_edge_matches(static_cast<int>(
		model_matches[0].size() + model_matches[1].size()));
	} else {
	    reason = closed ? BREP_BOOLEAN_FAILURE_REASON_CLOSED_SSI_EDGE :
		BREP_BOOLEAN_FAILURE_REASON_OPEN_SSI_EDGE;
	}

	record_boolean_output_topology(brep);
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_EDGE_REPAIR, reason,
	    shared_curve.m_face_index[populated_side],
	    shared_curve.m_face_index[peer_side], edge_index, peer_edge_index,
	    tolerance);
	return;
    }
}


static bool
measure_curve_to_nurbs_distance(
    const ON_Curve *curve,
    const ON_NurbsCurve *nurbs,
    double &maximum_distance)
{
    if (curve == NULL || nurbs == NULL) {
	return false;
    }

    return for_each_boolean_curve_sample(*curve,
	[&](const ON_3dPoint &point) {
	    double closest_parameter = 0.0;
	    if (!ON_NurbsCurve_GetClosestPoint(&closest_parameter, nurbs, point)) {
		return false;
	    }
	    const ON_3dPoint closest_point = nurbs->PointAt(closest_parameter);
	    if (!closest_point.IsValid()) {
		return false;
	    }

	    maximum_distance = std::max(maximum_distance,
		point.DistanceTo(closest_point));
	    return true;
	});
}


static ON_Curve *
pushup_near_isoparametric_boolean_curve(
    const ON_Surface *surface,
    const ON_Curve &parameter_curve)
{
    if (surface == NULL || parameter_curve.Dimension() != 2 ||
	!parameter_curve.IsValid() || !parameter_curve.Domain().IsIncreasing())
    {
	return NULL;
    }

    double parameter_tolerance = 0.0;
    double curve_parameter_tolerance = 0.0;
    ON_BoundingBox bounds;
    if (!get_face_boundary_curve_tolerances(surface, &parameter_curve,
	    parameter_tolerance, curve_parameter_tolerance) ||
	!(parameter_tolerance > 0.0) ||
	!parameter_curve.GetTightBoundingBox(bounds) || !bounds.IsValid())
    {
	return NULL;
    }

    const ON_3dPoint start = parameter_curve.PointAtStart();
    const ON_3dPoint end = parameter_curve.PointAtEnd();
    if (!start.IsValid() || !end.IsValid()) {
	return NULL;
    }

    for (int constant_direction = 0; constant_direction < 2;
	 ++constant_direction)
    {
	const int varying_direction = 1 - constant_direction;
	const double constant_range = bounds.m_max[constant_direction] -
	    bounds.m_min[constant_direction];
	const double varying_range = bounds.m_max[varying_direction] -
	    bounds.m_min[varying_direction];
	if (!std::isfinite(constant_range) || !std::isfinite(varying_range) ||
	    constant_range > parameter_tolerance ||
	    !(varying_range > parameter_tolerance))
	{
	    continue;
	}

	const double constants[3] = {
	    start[constant_direction], end[constant_direction],
	    0.5 * (bounds.m_min[constant_direction] +
		bounds.m_max[constant_direction])
	};
	for (double constant : constants) {
	    ON_Interval constant_domain = surface->Domain(constant_direction);
	    ON_Interval varying_domain = surface->Domain(varying_direction);
	    constant_domain.MakeIncreasing();
	    varying_domain.MakeIncreasing();
	    if (!constant_domain.IsIncreasing() || !varying_domain.IsIncreasing() ||
		constant < constant_domain.Min() - parameter_tolerance ||
		constant > constant_domain.Max() + parameter_tolerance)
	    {
		continue;
	    }
	    constant = std::max(constant_domain.Min(),
		std::min(constant_domain.Max(), constant));

	    ON_3dPoint normalized_start(start);
	    ON_3dPoint normalized_end(end);
	    normalized_start[constant_direction] = constant;
	    normalized_end[constant_direction] = constant;
	    ON_LineCurve normalized_parameter(normalized_start, normalized_end);
	    if (!normalized_parameter.ChangeDimension(2) ||
		!normalized_parameter.SetDomain(parameter_curve.Domain().Min(),
		    parameter_curve.Domain().Max()) ||
		!normalized_parameter.IsValid() ||
		!brep_curves_coincident(parameter_curve, normalized_parameter,
		    parameter_tolerance))
	    {
		continue;
	    }

	    double varying_start = start[varying_direction];
	    double varying_end = end[varying_direction];
	    if (varying_start < varying_domain.Min() - parameter_tolerance ||
		varying_start > varying_domain.Max() + parameter_tolerance ||
		varying_end < varying_domain.Min() - parameter_tolerance ||
		varying_end > varying_domain.Max() + parameter_tolerance)
	    {
		continue;
	    }
	    varying_start = std::max(varying_domain.Min(),
		std::min(varying_domain.Max(), varying_start));
	    varying_end = std::max(varying_domain.Min(),
		std::min(varying_domain.Max(), varying_end));
	    if (fabs(varying_end - varying_start) <= parameter_tolerance) {
		continue;
	    }

	    std::unique_ptr<ON_Curve> lifted(
		surface->IsoCurve(varying_direction, constant));
	    ON_Interval lifted_domain = lifted ? lifted->Domain() :
		ON_Interval::EmptyInterval;
	    lifted_domain.MakeIncreasing();
	    ON_Interval retained(std::min(varying_start, varying_end),
		std::max(varying_start, varying_end));
	    if (!lifted || !lifted->IsValid() || !lifted_domain.IsIncreasing() ||
		retained.Min() < lifted_domain.Min() - parameter_tolerance ||
		retained.Max() > lifted_domain.Max() + parameter_tolerance)
	    {
		continue;
	    }
	    retained.Set(std::max(lifted_domain.Min(), retained.Min()),
		std::min(lifted_domain.Max(), retained.Max()));
	    if (!retained.IsIncreasing() ||
		(retained != lifted_domain && !lifted->Trim(retained)) ||
		(varying_end < varying_start && !lifted->Reverse()) ||
		!lifted->SetDomain(parameter_curve.Domain().Min(),
		    parameter_curve.Domain().Max()) || !lifted->IsValid())
	    {
		continue;
	    }

	    bool endpoints_match = true;
	    for (double fraction : {0.0, 0.5, 1.0}) {
		const double parameter = parameter_curve.Domain().ParameterAt(
		    fraction);
		const ON_3dPoint uv = parameter_curve.PointAt(parameter);
		const ON_3dPoint original = uv.IsValid() ?
		    surface->PointAt(uv.x, uv.y) : ON_3dPoint::UnsetPoint;
		const ON_3dPoint replacement = lifted->PointAt(parameter);
		if (!original.IsValid() || !replacement.IsValid() ||
		    original.DistanceTo(replacement) > INTERSECTION_TOL)
		{
		    endpoints_match = false;
		    break;
		}
	    }
	    if (endpoints_match) {
		return lifted.release();
	    }
	}
    }
    return NULL;
}


static ON_Curve *
pushup_boolean_trim_curve(const ON_Surface *surface, const ON_Curve &trim_curve)
{
    ON_Curve *lifted_curve = pushup_boolean_curve(surface, trim_curve);
    if (lifted_curve != NULL) {
	return lifted_curve;
    }

    lifted_curve = pushup_near_isoparametric_boolean_curve(surface,
	trim_curve);
    if (lifted_curve != NULL) {
	return lifted_curve;
    }

    const int span_count = trim_curve.SpanCount();
    if (span_count < 1)
	return NULL;
    std::vector<double> span_parameters(static_cast<size_t>(span_count) + 1);
    if (!trim_curve.GetSpanVector(span_parameters.data()))
	return NULL;

    ON_3dPointArray points;
    ON_SimpleArray<double> parameters;
    const int samples_per_span = std::max(1, std::min(
	BOOLEAN_TOLERANCE_MAXIMUM_SAMPLES_PER_SPAN,
	BOOLEAN_TOLERANCE_TARGET_SAMPLES / span_count));
    for (int span_index = 0; span_index < span_count; ++span_index) {
	const ON_Interval span(span_parameters[span_index],
	    span_parameters[span_index + 1]);
	if (!span.IsIncreasing())
	    return NULL;
	for (int sample_index = 0; sample_index < samples_per_span;
	     ++sample_index)
	{
	    const double parameter = span.ParameterAt(
		static_cast<double>(sample_index) / samples_per_span);
	    const ON_3dPoint point = boolean_surface_point_at(surface,
		trim_curve.PointAt(parameter));
	    if (!point.IsValid())
		return NULL;
	    points.Append(point);
	    parameters.Append(parameter);
	}
    }
    const double endpoint_parameter = span_parameters[span_count];
    const ON_3dPoint endpoint = boolean_surface_point_at(surface,
	trim_curve.PointAt(endpoint_parameter));
    if (!endpoint.IsValid())
	return NULL;

    points.Append(endpoint);
    parameters.Append(endpoint_parameter);

    if (points.Count() < 2)
	return NULL;
    ON_PolylineCurve *polyline = new ON_PolylineCurve(points, parameters);
    if (!polyline->IsValid()) {
	delete polyline;
	return NULL;
    }
    return polyline;
}


struct BooleanSourceEdgeUse {
    int m_edge_index = -1;
    int m_trim_index = -1;
    double m_source_start = ON_UNSET_VALUE;
    double m_source_end = ON_UNSET_VALUE;
};


static bool
boolean_curve_bounds_overlap(
    const ON_Curve &first,
    const ON_Curve &second,
    double tolerance)
{
    const ON_BoundingBox first_bounds = first.BoundingBox();
    const ON_BoundingBox second_bounds = second.BoundingBox();
    if (!first_bounds.IsValid() || !second_bounds.IsValid() ||
	!(tolerance >= 0.0) || !std::isfinite(tolerance))
    {
	return false;
    }

    return first_bounds.m_max.x + tolerance >= second_bounds.m_min.x &&
	second_bounds.m_max.x + tolerance >= first_bounds.m_min.x &&
	first_bounds.m_max.y + tolerance >= second_bounds.m_min.y &&
	second_bounds.m_max.y + tolerance >= first_bounds.m_min.y &&
	first_bounds.m_max.z + tolerance >= second_bounds.m_min.z &&
	second_bounds.m_max.z + tolerance >= first_bounds.m_min.z;
}


static bool
boolean_polyline_curves_are_coincident(
    const ON_Curve *first,
    const ON_Curve *second,
    double tolerance,
    bool &second_reverses_first)
{
    second_reverses_first = false;
    const ON_PolylineCurve *first_polyline = ON_PolylineCurve::Cast(first);
    const ON_PolylineCurve *second_polyline = ON_PolylineCurve::Cast(second);
    if (first_polyline == NULL || second_polyline == NULL ||
	first_polyline->m_pline.Count() < 2 ||
	second_polyline->m_pline.Count() < 2)
    {
	return false;
    }

	bool forward = true;
	bool reverse = true;
    const int first_point_count = first_polyline->m_pline.Count();
    const int second_point_count = second_polyline->m_pline.Count();
    if (first_point_count == second_point_count) {
	for (int point_index = 0; point_index < first_point_count; ++point_index) {
	    const ON_3dPoint &point = first_polyline->m_pline[point_index];
	    forward = forward && point.DistanceTo(
		second_polyline->m_pline[point_index]) <= tolerance;
	    reverse = reverse && point.DistanceTo(second_polyline->m_pline[
		second_point_count - point_index - 1]) <= tolerance;
	    if (!forward && !reverse) {
		break;
	    }
	}
	if (forward || reverse) {
	    second_reverses_first = !forward && reverse;
	    return true;
	}
    }

    if (std::max(first_point_count, second_point_count) <= 1024 ||
	!first->Domain().IsIncreasing() || !second->Domain().IsIncreasing())
    {
	return false;
    }

    const auto vertices_follow_normalized_parameter = [tolerance](
	    const ON_PolylineCurve &vertices,
	    const ON_PolylineCurve &curve,
	    bool reverse_parameter) {
	const ON_Interval vertex_domain = vertices.Domain();
	const ON_Interval curve_domain = curve.Domain();
	for (int point_index = 0; point_index < vertices.m_pline.Count();
	     ++point_index)
	{
	    double normalized = vertex_domain.NormalizedParameterAt(
		vertices.m_t[point_index]);
	    if (reverse_parameter) {
		normalized = 1.0 - normalized;
	    }
	    const ON_3dPoint comparison = curve.PointAt(
		curve_domain.ParameterAt(normalized));
	    if (!comparison.IsValid() || comparison.DistanceTo(
		    vertices.m_pline[point_index]) > tolerance)
	    {
		return false;
	    }
	}
	return true;
    };

    forward = vertices_follow_normalized_parameter(*first_polyline,
	*second_polyline, false) &&
	vertices_follow_normalized_parameter(*second_polyline, *first_polyline,
	    false);
    reverse = !forward && vertices_follow_normalized_parameter(*first_polyline,
	*second_polyline, true) &&
	vertices_follow_normalized_parameter(*second_polyline, *first_polyline,
	    true);
    second_reverses_first = reverse;
    return forward || reverse;
}


static int
boolean_active_naked_edge_count(const ON_Brep *brep)
{
    if (brep == NULL) {
	return -1;
    }

    int count = 0;
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	if (is_active_boolean_naked_edge(brep, edge_index)) {
	    ++count;
	}
    }
    return count;
}


static bool
project_boolean_edge_to_source_edge(
    const ON_Brep *brep,
    int edge_index,
    const ON_BrepEdge &source_edge,
    double tolerance,
    BooleanSourceEdgeUse &projected_use)
{
    projected_use = BooleanSourceEdgeUse();
	const bool result_is_open = is_active_boolean_naked_edge(brep,
	    edge_index);
	const bool result_is_closed = is_active_boolean_closed_naked_edge(brep,
	    edge_index);
    if ((!result_is_open && !result_is_closed) ||
	!source_edge.Domain().IsIncreasing())
    {
	return false;
    }

    const ON_BrepEdge &edge = brep->m_E[edge_index];
    if (!boolean_curve_bounds_overlap(edge, source_edge, tolerance)) {
	return false;
    }
    bool underlying_reversed = false;
    const bool exact_polyline_match = boolean_polyline_curves_are_coincident(
	edge.ProxyCurve(), source_edge.ProxyCurve(), tolerance,
	underlying_reversed);
    if (exact_polyline_match && (!result_is_closed || source_edge.IsClosed())) {
	const bool reversed = underlying_reversed != edge.ProxyCurveIsReversed() !=
	    source_edge.ProxyCurveIsReversed();
	projected_use.m_edge_index = edge_index;
	projected_use.m_trim_index = edge.m_ti[0];
	projected_use.m_source_start = reversed ? 1.0 : 0.0;
	projected_use.m_source_end = reversed ? 0.0 : 1.0;
	return true;
    }
    if (result_is_closed) {
	bool reversed = false;
	const bool same_seam = source_edge.IsClosed() &&
	    closed_curves_are_equivalent(&edge, &source_edge, tolerance,
		reversed);
	const bool same_locus = source_edge.IsClosed() &&
	    closed_curve_loci_coincident(edge, source_edge, tolerance);
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean closed result edge %d against source edge %d: "
		"same seam/locus %d/%d, seam distance %.17g.\n", edge_index,
		source_edge.m_edge_index, same_seam, same_locus,
		edge.PointAtStart().DistanceTo(source_edge.PointAtStart()));
	}
	if (!same_seam)
	{
	    return false;
	}
	projected_use.m_edge_index = edge_index;
	projected_use.m_trim_index = edge.m_ti[0];
	projected_use.m_source_start = reversed ? 1.0 : 0.0;
	projected_use.m_source_end = reversed ? 0.0 : 1.0;
	return true;
    }

    const ON_NurbsCurve *result_nurbs = ON_NurbsCurve::Cast(edge.ProxyCurve());
    const ON_NurbsCurve *source_nurbs =
	ON_NurbsCurve::Cast(source_edge.ProxyCurve());
    const bool exact_nurbs_match = result_nurbs != NULL &&
	source_nurbs != NULL && result_nurbs->SpanCount() < 1024 &&
	result_nurbs->IsDuplicate(*source_nurbs, true, 0.0);
    if (exact_nurbs_match)
    {
	const double same_endpoint_error = std::max(
	    edge.PointAtStart().DistanceTo(source_edge.PointAtStart()),
	    edge.PointAtEnd().DistanceTo(source_edge.PointAtEnd()));
	const double reversed_endpoint_error = std::max(
	    edge.PointAtStart().DistanceTo(source_edge.PointAtEnd()),
	    edge.PointAtEnd().DistanceTo(source_edge.PointAtStart()));
	if (std::min(same_endpoint_error, reversed_endpoint_error) <= tolerance) {
	    projected_use.m_edge_index = edge_index;
	    projected_use.m_trim_index = edge.m_ti[0];
	    projected_use.m_source_start =
		reversed_endpoint_error < same_endpoint_error ? 1.0 : 0.0;
	    projected_use.m_source_end =
		reversed_endpoint_error < same_endpoint_error ? 0.0 : 1.0;
	    return true;
	}
    }

    std::vector<double> normalized_parameters;
    const bool projected = for_each_boolean_curve_sample(edge,
	[&](const ON_3dPoint &point) {
	    double source_parameter = ON_UNSET_VALUE;
	    if (!point_3d_to_curve_parameter_with_tolerance(point, &source_edge,
		    tolerance, source_parameter))
	    {
		return false;
	    }

	    const double normalized = source_edge.Domain().NormalizedParameterAt(
		source_parameter);
	    if (!std::isfinite(normalized)) {
		return false;
	    }
	    normalized_parameters.push_back(normalized);
	    return true;
	});
    if (!projected || normalized_parameters.size() < 2) {
	return false;
    }

    /* Closest-point projection onto a closed edge may return either endpoint
     * of its normalized domain at the seam.  An open result edge ending at
     * that seam would then appear to jump almost one full period and reverse
     * direction.  Unwrap each sample to the nearest periodic representative,
     * and retain only intervals which can be shifted wholly into [0,1]. */
    if (source_edge.IsClosed()) {
	for (size_t parameter = 1; parameter < normalized_parameters.size();
	     ++parameter)
	{
	    while (normalized_parameters[parameter] -
		    normalized_parameters[parameter - 1] > 0.5)
	    {
		normalized_parameters[parameter] -= 1.0;
	    }
	    while (normalized_parameters[parameter] -
		    normalized_parameters[parameter - 1] < -0.5)
	    {
		normalized_parameters[parameter] += 1.0;
	    }
	}

	const std::pair<std::vector<double>::const_iterator,
	    std::vector<double>::const_iterator> extrema = std::minmax_element(
		normalized_parameters.begin(), normalized_parameters.end());
	const double periodic_guard = 4096.0 * ON_EPSILON;
	double shift = 0.0;
	if (*extrema.first < -periodic_guard) {
	    shift = 1.0;
	} else if (*extrema.second > 1.0 + periodic_guard) {
	    shift = -1.0;
	}
	for (double &parameter : normalized_parameters) {
	    parameter += shift;
	    if (fabs(parameter) <= periodic_guard) {
		parameter = 0.0;
	    } else if (fabs(parameter - 1.0) <= periodic_guard) {
		parameter = 1.0;
	    }
	    if (parameter < 0.0 || parameter > 1.0) {
		return false;
	    }
	}
    }

    const double source_start = normalized_parameters.front();
    const double source_end = normalized_parameters.back();
    const double source_range = fabs(source_end - source_start);
    const double parameter_scale = std::max(1.0,
	std::max(fabs(source_start), fabs(source_end)));
    const double numeric_guard = std::max(256.0 * ON_EPSILON *
	parameter_scale, 1.0e-5 * source_range);
    if (!(source_range > numeric_guard)) {
	return false;
    }

    const double direction = source_end > source_start ? 1.0 : -1.0;
    for (size_t parameter = 1; parameter < normalized_parameters.size();
	 ++parameter)
    {
	if (direction * (normalized_parameters[parameter] -
		normalized_parameters[parameter - 1]) < -numeric_guard)
	{
	    return false;
	}
    }

    projected_use.m_edge_index = edge_index;
    projected_use.m_trim_index = edge.m_ti[0];
    projected_use.m_source_start = source_start;
    projected_use.m_source_end = source_end;
    return true;
}


static bool
boolean_polyline_follows_linear_curve(
    const ON_PolylineCurve &polyline,
    const ON_Curve &linear_curve,
    double tolerance)
{
    if (polyline.m_pline.Count() < 2 || !(tolerance >= 0.0) ||
	!std::isfinite(tolerance) || !linear_curve.IsLinear(tolerance))
    {
	return false;
    }

    const ON_3dPoint line_start = linear_curve.PointAtStart();
    const ON_3dPoint line_end = linear_curve.PointAtEnd();
    const ON_3dVector line_delta = line_end - line_start;
    const double line_length_squared = line_delta.LengthSquared();
    if (!line_start.IsValid() || !line_end.IsValid() ||
	!(line_length_squared > tolerance * tolerance))
    {
	return false;
    }

    const double line_length = sqrt(line_length_squared);
    const double normalized_tolerance = tolerance / line_length;
    const double monotonic_guard = std::max(normalized_tolerance,
	4096.0 * ON_EPSILON);
    double first_parameter = ON_UNSET_VALUE;
    double previous_parameter = ON_UNSET_VALUE;
    double direction = 0.0;
    for (int point_index = 0; point_index < polyline.m_pline.Count();
	 ++point_index)
    {
	const ON_3dPoint &point = polyline.m_pline[point_index];
	if (!point.IsValid()) {
	    return false;
	}
	const double parameter = ((point - line_start) * line_delta) /
	    line_length_squared;
	if (parameter < -normalized_tolerance ||
	    parameter > 1.0 + normalized_tolerance ||
	    point.DistanceTo(line_start + parameter * line_delta) > tolerance)
	{
	    return false;
	}
	if (point_index == 0) {
	    first_parameter = parameter;
	} else if (point_index == 1) {
	    direction = parameter >= first_parameter ? 1.0 : -1.0;
	} else if (direction * (parameter - previous_parameter) <
	    -monotonic_guard)
	{
	    return false;
	}
	previous_parameter = parameter;
    }

    return fabs(previous_parameter - first_parameter) > monotonic_guard;
}


static bool
boolean_output_trim_follows_source_trim(
    const ON_Brep *brep,
    int edge_index,
    const ON_BrepFace &source_face,
    const ON_BrepTrim &source_trim)
{
	const bool output_is_open = is_active_boolean_naked_edge(brep,
	    edge_index);
	const bool output_is_closed = is_active_boolean_closed_naked_edge(brep,
	    edge_index);
    if ((!output_is_open && !output_is_closed) ||
	 source_face.SurfaceOf() == NULL || source_trim.TrimCurveOf() == NULL ||
	 source_trim.FaceIndexOf() != source_face.m_face_index)
    {
	return false;
    }

    const ON_BrepEdge &edge = brep->m_E[edge_index];
    if (edge.m_ti.Count() != 1 || edge.m_ti[0] < 0 ||
	 edge.m_ti[0] >= brep->m_T.Count())
    {
	return false;
    }

    const ON_BrepTrim &output_trim = brep->m_T[edge.m_ti[0]];
    const ON_Curve *output_curve = output_trim.TrimCurveOf();
    const ON_Curve *source_curve = source_trim.TrimCurveOf();
    ON_Interval source_domain = source_curve->Domain();
    source_domain.MakeIncreasing();
    if (output_curve == NULL || output_curve->Dimension() != 2 ||
	 source_curve->Dimension() != 2 || !source_domain.IsIncreasing())
    {
	return false;
    }

    double parameter_tolerance = 0.0;
    double source_curve_parameter_tolerance = 0.0;
    if (!get_face_boundary_curve_tolerances(source_face.SurfaceOf(),
	    source_curve, parameter_tolerance,
	    source_curve_parameter_tolerance))
    {
	return false;
    }
    if (!boolean_curve_bounds_overlap(*output_curve, *source_curve,
	    parameter_tolerance))
    {
	return false;
    }

    bool polyline_reversed = false;
    if (boolean_polyline_curves_are_coincident(output_curve, source_curve,
	    parameter_tolerance, polyline_reversed))
    {
	return true;
    }

    const ON_PolylineCurve *dense_output_polyline =
	ON_PolylineCurve::Cast(output_curve);
    const ON_PolylineCurve *dense_source_polyline =
	ON_PolylineCurve::Cast(source_curve);
    if (dense_output_polyline != NULL &&
	dense_output_polyline->m_pline.Count() > 1024 &&
	source_curve->IsLinear(parameter_tolerance))
    {
	return boolean_polyline_follows_linear_curve(*dense_output_polyline,
	    *source_curve, parameter_tolerance);
    }
    if (dense_output_polyline != NULL && dense_source_polyline != NULL &&
	std::max(dense_output_polyline->m_pline.Count(),
	    dense_source_polyline->m_pline.Count()) > 1024)
    {
	return false;
    }

    std::vector<double> normalized_parameters;
    if (!for_each_boolean_curve_sample(*output_curve,
	[&](const ON_3dPoint &parameter_point) {
	    double source_parameter = ON_UNSET_VALUE;
	    if (!point_3d_to_curve_parameter_with_tolerance(parameter_point,
		    source_curve, parameter_tolerance, source_parameter))
	    {
		return false;
	    }

	    const double normalized = source_domain.NormalizedParameterAt(
		source_parameter);
	    if (!std::isfinite(normalized)) {
		return false;
	    }
	    normalized_parameters.push_back(normalized);
	    return true;
	}))
    {
	return false;
    }
    if (normalized_parameters.size() < 2) {
	return false;
    }

    const double source_start = normalized_parameters.front();
    const double source_end = normalized_parameters.back();
    const double source_range = fabs(source_end - source_start);
    const double normalized_tolerance = source_curve_parameter_tolerance /
	 source_domain.Length();
    const double parameter_scale = std::max(1.0,
	std::max(fabs(source_start), fabs(source_end)));
    const double numeric_guard = std::max(256.0 * ON_EPSILON *
	parameter_scale, std::max(1.0e-5 * source_range,
	    normalized_tolerance));
    if (!(source_range > numeric_guard)) {
	return false;
    }

    const double direction = source_end > source_start ? 1.0 : -1.0;
    for (size_t parameter = 1; parameter < normalized_parameters.size();
	 ++parameter)
    {
	if (direction * (normalized_parameters[parameter] -
		normalized_parameters[parameter - 1]) < -numeric_guard)
	{
	    return false;
	}
    }

    return true;
}


static void
collect_boolean_source_edge_uses(
    const ON_Brep *brep,
    int source_face_index,
    const ON_BrepFace &source_face,
    const ON_BrepTrim &source_trim,
    const ON_BrepEdge &source_edge,
    double tolerance,
    std::vector<BooleanSourceEdgeUse> &uses)
{
    uses.clear();
    if (brep == NULL) {
	return;
    }

    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	if (!is_shared_open_ssi_edge_candidate(brep, edge_index,
		source_face_index) &&
	    !is_shared_closed_ssi_edge_candidate(brep, edge_index,
		source_face_index))
	{
	    continue;
	}
	if (!boolean_output_trim_follows_source_trim(brep, edge_index,
		source_face, source_trim))
	{
	    continue;
	}
	BooleanSourceEdgeUse use;
	if (project_boolean_edge_to_source_edge(brep, edge_index, source_edge,
		tolerance, use))
	{
	    uses.push_back(use);
	}
    }
}


static int
boolean_loop_trim_position(const ON_BrepLoop &loop, int trim_index)
{
    int position = -1;
    for (int i = 0; i < loop.m_ti.Count(); ++i) {
	if (loop.m_ti[i] != trim_index) {
	    continue;
	}
	if (position >= 0) {
	    return -1;
	}
	position = i;
    }
    return position;
}


static double
boolean_source_edge_normalized_tolerance(
    const ON_BrepEdge &source_edge,
    double model_tolerance)
{
    double source_length = 0.0;
    ON_3dPoint previous = ON_3dPoint::UnsetPoint;
    const bool measured = for_each_boolean_curve_sample(source_edge,
	[&](const ON_3dPoint &point) {
	    if (previous.IsValid()) {
		const double segment_length = previous.DistanceTo(point);
		if (!std::isfinite(segment_length) ||
		    !std::isfinite(source_length + segment_length))
		{
		    return false;
		}
		source_length += segment_length;
	    }
	    previous = point;
	    return true;
	});
    if (!measured || !(source_length > 0.0) || !std::isfinite(source_length))
    {
	source_length = source_edge.BoundingBox().Diagonal().Length();
    }
    if (!(source_length > 0.0) || !std::isfinite(source_length)) {
	return 0.0;
    }

    return std::min(0.05, std::max(1.0e-10,
	2.0 * model_tolerance / source_length));
}


static bool
find_boolean_trim_lift_parameter(
    const ON_BrepTrim &trim,
    const ON_3dPoint &target,
    double tolerance,
    double &parameter)
{
    const ON_Surface *surface = trim.SurfaceOf();
    const ON_Interval domain = trim.Domain();
    if (surface == NULL || trim.TrimCurveOf() == NULL || !target.IsValid() ||
	!domain.IsIncreasing())
    {
	return false;
    }

    static const int search_segments = 1024;
    double best_parameter = domain.Min();
    double best_distance = std::numeric_limits<double>::max();
    int best_sample = 0;
    const auto lifted_distance = [&trim, surface, &target](double candidate) {
	const ON_3dPoint uv = trim.PointAt(candidate);
	const ON_3dPoint lifted = uv.IsValid() ?
	    surface->PointAt(uv.x, uv.y) : ON_3dPoint::UnsetPoint;
	return lifted.IsValid() ? lifted.DistanceTo(target) :
	    std::numeric_limits<double>::max();
    };

    for (int sample = 0; sample <= search_segments; ++sample) {
	const double candidate = domain.ParameterAt(
	    static_cast<double>(sample) / search_segments);
	const double distance = lifted_distance(candidate);
	if (distance < best_distance) {
	    best_distance = distance;
	    best_parameter = candidate;
	    best_sample = sample;
	}
    }

    double minimum = domain.ParameterAt(static_cast<double>(
	std::max(0, best_sample - 1)) / search_segments);
    double maximum = domain.ParameterAt(static_cast<double>(
	std::min(search_segments, best_sample + 1)) / search_segments);
    for (int iteration = 0; iteration < 64; ++iteration) {
	const double first = minimum + (maximum - minimum) / 3.0;
	const double second = maximum - (maximum - minimum) / 3.0;
	if (lifted_distance(first) <= lifted_distance(second)) {
	    maximum = second;
	} else {
	    minimum = first;
	}
    }
    const double refined = 0.5 * (minimum + maximum);
    const double refined_distance = lifted_distance(refined);
    if (refined_distance < best_distance) {
	best_parameter = refined;
	best_distance = refined_distance;
    }

    const double domain_guard = std::max(ON_ZERO_TOLERANCE,
	domain.Length() * 1.0e-10);
    if (!(best_distance <= tolerance) ||
	best_parameter <= domain.Min() + domain_guard ||
	best_parameter >= domain.Max() - domain_guard)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_3dPoint best_uv = trim.PointAt(best_parameter);
	    const ON_3dPoint best_point = best_uv.IsValid() ?
		surface->PointAt(best_uv.x, best_uv.y) : ON_3dPoint::UnsetPoint;
	    bu_log("Boolean trim lift parameter rejected: domain %.17g -> "
		"%.17g, best %.17g, distance %.17g, guard %.17g, "
		"target %.17g %.17g %.17g, lift %.17g %.17g %.17g, "
		"tolerance %.17g.\n", domain.Min(), domain.Max(),
		best_parameter, best_distance, domain_guard, target.x, target.y,
		target.z, best_point.x, best_point.y, best_point.z, tolerance);
	}
	return false;
    }

    parameter = best_parameter;
    return true;
}


static bool
boolean_parameter_curve_follows_edge(
    const ON_Surface *surface,
    const ON_Curve *parameter_curve,
    const ON_BrepEdge &edge,
    bool reversed,
    double tolerance)
{
    if (surface == NULL || parameter_curve == NULL ||
	parameter_curve->Dimension() != 2 || !parameter_curve->IsValid() ||
	edge.Dimension() != 3 || !edge.IsValid() ||
	!parameter_curve->Domain().IsIncreasing() ||
	!edge.Domain().IsIncreasing())
    {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean parameter-curve validation has invalid inputs.\n");
	}
	return false;
    }

    const ON_3dPoint parameter_start = parameter_curve->PointAtStart();
    const ON_3dPoint parameter_end = parameter_curve->PointAtEnd();
    const ON_3dPoint lifted_start = parameter_start.IsValid() ?
	surface->PointAt(parameter_start.x, parameter_start.y) :
	ON_3dPoint::UnsetPoint;
    const ON_3dPoint lifted_end = parameter_end.IsValid() ?
	surface->PointAt(parameter_end.x, parameter_end.y) :
	ON_3dPoint::UnsetPoint;
    const ON_3dPoint edge_start = reversed ? edge.PointAtEnd() :
	edge.PointAtStart();
    const ON_3dPoint edge_end = reversed ? edge.PointAtStart() :
	edge.PointAtEnd();
    if (!lifted_start.IsValid() || !lifted_end.IsValid() ||
	!edge_start.IsValid() || !edge_end.IsValid() ||
	lifted_start.DistanceTo(edge_start) > tolerance ||
	lifted_end.DistanceTo(edge_end) > tolerance)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean parameter-curve endpoint validation failed: "
		"%.17g/%.17g versus tolerance %.17g.\n",
		lifted_start.IsValid() && edge_start.IsValid() ?
		lifted_start.DistanceTo(edge_start) : -1.0,
		lifted_end.IsValid() && edge_end.IsValid() ?
		lifted_end.DistanceTo(edge_end) : -1.0, tolerance);
	}
	return false;
    }

    std::vector<double> projected_parameters;
    if (!for_each_boolean_curve_sample(*parameter_curve,
	[&](const ON_3dPoint &uv) {
	    const ON_3dPoint lifted = surface->PointAt(uv.x, uv.y);
	    double edge_parameter = ON_UNSET_VALUE;
	    if (!lifted.IsValid() ||
		!point_3d_to_curve_parameter_with_tolerance(lifted, &edge,
		    tolerance, edge_parameter))
	    {
		return false;
	    }
	    const double normalized = edge.Domain().NormalizedParameterAt(
		edge_parameter);
	    if (!std::isfinite(normalized)) {
		return false;
	    }
	    projected_parameters.push_back(normalized);
	    return true;
	}))
    {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean parameter-curve samples could not be projected to "
		"the replacement edge.\n");
	}
	return false;
    }
    const double numeric_guard = std::max(256.0 * ON_EPSILON,
	1.0e-5 * fabs(projected_parameters.back() -
	    projected_parameters.front()));
    const double monotonic_guard = std::max(numeric_guard,
	boolean_source_edge_normalized_tolerance(edge, tolerance));
    const double direction = reversed ? -1.0 : 1.0;
    for (size_t projected = 1; projected < projected_parameters.size();
	 ++projected)
    {
	if (direction * (projected_parameters[projected] -
		projected_parameters[projected - 1]) < -monotonic_guard)
	{
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Boolean parameter-curve projection reverses between "
		    "samples %zu/%zu: %.17g -> %.17g (guard %.17g).\n",
		    projected - 1, projected,
		    projected_parameters[projected - 1],
		    projected_parameters[projected], monotonic_guard);
	    }
	    return false;
	}
    }

    std::unique_ptr<ON_Curve> lifted_curve(
	pushup_boolean_trim_curve(surface, *parameter_curve));
    ON_NurbsCurve lifted_nurbs;
    ON_NurbsCurve edge_nurbs;
    double maximum_distance = 0.0;
    if (!lifted_curve || lifted_curve->GetNurbForm(lifted_nurbs) <= 0 ||
	edge.GetNurbForm(edge_nurbs) <= 0 ||
	!measure_curve_to_nurbs_distance(lifted_curve.get(), &edge_nurbs,
	    maximum_distance) ||
	!measure_curve_to_nurbs_distance(&edge, &lifted_nurbs,
	    maximum_distance))
    {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean parameter-curve residual could not be measured.\n");
	}
	return false;
    }

    if (DEBUG_BREP_BOOLEAN && maximum_distance > tolerance) {
	bu_log("Boolean parameter-curve residual %.17g exceeds tolerance %.17g.\n",
	    maximum_distance, tolerance);
    }
    return maximum_distance <= tolerance;
}


static bool set_boolean_trim_tolerances(ON_Brep *brep);
static bool set_boolean_edge_tolerances(ON_Brep *brep);
static double boolean_measured_tolerance(double residual);


struct BooleanParameterEdgeMatch {
    int m_edge_position = -1;
    bool m_reversed = false;
};


static bool
split_boolean_curve_at_parameter(
    const ON_Curve &curve,
    double parameter,
    std::unique_ptr<ON_Curve> pieces[2])
{
    const ON_Interval domain = curve.Domain();
    const double parameter_scale = domain.IsIncreasing() ? std::max(1.0,
	std::max(fabs(domain.Min()), fabs(domain.Max()))) : 1.0;
    const double guard = std::max(ON_ZERO_TOLERANCE * parameter_scale,
	domain.IsIncreasing() ? 1.0e-10 * domain.Length() : 0.0);
    if (!domain.IsIncreasing() || !std::isfinite(parameter) ||
	parameter <= domain.Min() + guard ||
	parameter >= domain.Max() - guard)
    {
	return false;
    }

    std::unique_ptr<ON_Curve> duplicate(curve.DuplicateCurve());
    ON_Curve *first = NULL;
    ON_Curve *second = NULL;
    if (!duplicate || !duplicate->Split(parameter, first, second) ||
	first == NULL || second == NULL)
    {
	delete first;
	delete second;
	return false;
    }

    std::unique_ptr<ON_Curve> raw[2] = {
	std::unique_ptr<ON_Curve>(first),
	std::unique_ptr<ON_Curve>(second)
    };
    for (int piece = 0; piece < 2; ++piece) {
	std::unique_ptr<ON_NurbsCurve> detached(new ON_NurbsCurve());
	if (raw[piece]->GetNurbForm(*detached) <= 0 ||
	    !detached->IsValid() || !detached->Domain().IsIncreasing())
	{
	    return false;
	}
	pieces[piece].reset(detached.release());
    }
    return true;
}


static bool
find_boolean_parameter_edge_match(
    const ON_Surface *surface,
    const ON_Curve *parameter_curve,
    const ON_BrepEdge *edges[2],
    double tolerance,
    BooleanParameterEdgeMatch &match)
{
    match = BooleanParameterEdgeMatch();
    int match_count = 0;
    for (int edge_position = 0; edge_position < 2; ++edge_position) {
	if (edges[edge_position] == NULL) {
	    return false;
	}
	for (bool reversed : {false, true}) {
	    if (!boolean_parameter_curve_follows_edge(surface,
		    parameter_curve, *edges[edge_position], reversed,
		    tolerance))
	    {
		continue;
	    }
	    ++match_count;
	    match.m_edge_position = edge_position;
	    match.m_reversed = reversed;
	}
    }
    return match_count == 1;
}


static int
boolean_naked_edge_count(const ON_Brep *brep)
{
    if (brep == NULL) {
	return -1;
    }

    int count = 0;
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	const ON_BrepEdge &edge = brep->m_E[edge_index];
	if (edge.m_edge_index == edge_index && edge.m_ti.Count() == 1) {
	    ++count;
	}
    }
    return count;
}


static SharedSSIEdgeRepairResult
repair_boolean_offset_seam_closed_edge_pair(
    ON_Brep *brep,
    int first_edge_index,
    int second_edge_index,
    double tolerance)
{
    const auto skipped = [](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean offset-seam closed-edge repair skipped: %s.\n",
		reason);
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    };

    if (brep == NULL || first_edge_index < 0 ||
	first_edge_index >= brep->m_E.Count() || second_edge_index < 0 ||
	second_edge_index >= brep->m_E.Count() ||
	first_edge_index == second_edge_index || !(tolerance > 0.0) ||
	!std::isfinite(tolerance) ||
	!is_active_boolean_closed_naked_edge(brep, first_edge_index) ||
	!is_active_boolean_closed_naked_edge(brep, second_edge_index))
    {
	return skipped("candidate topology is invalid");
    }

    const ON_BrepEdge &first_edge = brep->m_E[first_edge_index];
    const ON_BrepEdge &second_edge = brep->m_E[second_edge_index];
    const int first_trim_index = first_edge.m_ti[0];
    const int second_trim_index = second_edge.m_ti[0];
    const ON_BrepTrim &first_trim = brep->m_T[first_trim_index];
    const ON_BrepTrim &second_trim = brep->m_T[second_trim_index];
    const int first_face_index = first_trim.FaceIndexOf();
    const int second_face_index = second_trim.FaceIndexOf();
    const int first_loop_index = first_trim.m_li;
    const int second_loop_index = second_trim.m_li;
    const int first_vertex_index = first_edge.m_vi[0];
    const int second_vertex_index = second_edge.m_vi[0];
    if (first_face_index < 0 || first_face_index >= brep->m_F.Count() ||
	second_face_index < 0 || second_face_index >= brep->m_F.Count() ||
	first_face_index == second_face_index || first_loop_index < 0 ||
	first_loop_index >= brep->m_L.Count() || second_loop_index < 0 ||
	second_loop_index >= brep->m_L.Count() ||
	first_loop_index == second_loop_index || first_vertex_index < 0 ||
	first_vertex_index >= brep->m_V.Count() || second_vertex_index < 0 ||
	second_vertex_index >= brep->m_V.Count() ||
	first_vertex_index == second_vertex_index ||
	first_trim.TrimCurveOf() == NULL || second_trim.TrimCurveOf() == NULL ||
	first_trim.SurfaceOf() == NULL || second_trim.SurfaceOf() == NULL)
    {
	return skipped("candidate face, loop, or vertex data is invalid");
    }

    const ON_3dPoint first_seam = brep->m_V[first_vertex_index].Point();
    const ON_3dPoint second_seam = brep->m_V[second_vertex_index].Point();
    if (!first_seam.IsValid() || !second_seam.IsValid() ||
	first_seam.DistanceTo(second_seam) <= tolerance ||
	!closed_curve_loci_coincident(first_edge, second_edge, tolerance))
    {
	return skipped("closed edge loci or seams are unsuitable");
    }

    double first_edge_split = ON_UNSET_VALUE;
    double first_trim_split = ON_UNSET_VALUE;
    double second_trim_split = ON_UNSET_VALUE;
    if (!point_3d_to_curve_parameter_with_tolerance(second_seam,
	    &first_edge, tolerance, first_edge_split, false) ||
	!find_boolean_trim_lift_parameter(first_trim, second_seam, tolerance,
	    first_trim_split) ||
	!find_boolean_trim_lift_parameter(second_trim, first_seam, tolerance,
	    second_trim_split))
    {
	return skipped("an opposite seam could not be located");
    }

    std::unique_ptr<ON_Curve> edge_pieces[2];
    std::unique_ptr<ON_Curve> trim_pieces[2][2];
    if (!split_boolean_curve_at_parameter(first_edge, first_edge_split,
	    edge_pieces) ||
	!split_boolean_curve_at_parameter(first_trim, first_trim_split,
	    trim_pieces[0]) ||
	!split_boolean_curve_at_parameter(second_trim, second_trim_split,
	    trim_pieces[1]))
    {
	return skipped("an edge or parameter curve could not be split");
    }

    const ON_3dPoint edge_endpoints[4] = {
	edge_pieces[0]->PointAtStart(), edge_pieces[0]->PointAtEnd(),
	edge_pieces[1]->PointAtStart(), edge_pieces[1]->PointAtEnd()
    };
    if (!edge_endpoints[0].IsValid() || !edge_endpoints[1].IsValid() ||
	!edge_endpoints[2].IsValid() || !edge_endpoints[3].IsValid() ||
	edge_endpoints[0].DistanceTo(first_seam) > tolerance ||
	edge_endpoints[1].DistanceTo(second_seam) > tolerance ||
	edge_endpoints[2].DistanceTo(second_seam) > tolerance ||
	edge_endpoints[3].DistanceTo(first_seam) > tolerance)
    {
	return skipped("split edge endpoints do not match both seams");
    }

    const int naked_before = boolean_naked_edge_count(brep);
    const int edge_count_before = brep->m_E.Count();
    const int trim_count_before = brep->m_T.Count();
    const int face_count_before = brep->m_F.Count();
    const int loop_count_before = brep->m_L.Count();
    const int surface_count_before = brep->m_S.Count();
    std::vector<int> old_loop_trims[2];
    const int loop_indices[2] = {first_loop_index, second_loop_index};
    const int old_trim_indices[2] = {first_trim_index, second_trim_index};
    const int old_edge_indices[2] = {first_edge_index, second_edge_index};
    const double old_trim_tolerances[2][2] = {
	{first_trim.m_tolerance[0], first_trim.m_tolerance[1]},
	{second_trim.m_tolerance[0], second_trim.m_tolerance[1]}
    };
    for (int side = 0; side < 2; ++side) {
	const ON_BrepLoop &loop = brep->m_L[loop_indices[side]];
	old_loop_trims[side].assign(loop.m_ti.Array(),
	    loop.m_ti.Array() + loop.m_ti.Count());
	if (std::count(old_loop_trims[side].begin(),
		old_loop_trims[side].end(), old_trim_indices[side]) != 1)
	{
	    return skipped("a source trim is not unique in its loop");
	}
    }

    ON_Brep repaired(*brep);
    int new_edge_indices[2] = {-1, -1};
    for (int piece = 0; piece < 2; ++piece) {
	const int curve_index = repaired.AddEdgeCurve(
	    edge_pieces[piece].release());
	if (curve_index < 0) {
	    return skipped("a split edge curve could not be installed");
	}
	const int start_vertex = piece == 0 ? first_vertex_index :
	    second_vertex_index;
	const int end_vertex = piece == 0 ? second_vertex_index :
	    first_vertex_index;
	ON_BrepEdge &edge = repaired.NewEdge(repaired.m_V[start_vertex],
	    repaired.m_V[end_vertex], curve_index, NULL, tolerance);
	new_edge_indices[piece] = edge.m_edge_index;
    }
    if (new_edge_indices[0] < 0 || new_edge_indices[1] < 0 ||
	new_edge_indices[0] == new_edge_indices[1])
    {
	return skipped("split edge topology could not be installed");
    }

    const ON_BrepEdge *new_edges[2] = {
	&repaired.m_E[new_edge_indices[0]],
	&repaired.m_E[new_edge_indices[1]]
    };
    BooleanParameterEdgeMatch matches[2][2];
    for (int side = 0; side < 2; ++side) {
	const ON_Surface *surface = repaired.m_F[
	    side == 0 ? first_face_index : second_face_index].SurfaceOf();
	for (int piece = 0; piece < 2; ++piece) {
	    if (!find_boolean_parameter_edge_match(surface,
		    trim_pieces[side][piece].get(), new_edges, tolerance,
		    matches[side][piece]))
	    {
		if (DEBUG_BREP_BOOLEAN) {
		    const ON_3dPoint start =
			trim_pieces[side][piece]->PointAtStart();
		    const ON_3dPoint end =
			trim_pieces[side][piece]->PointAtEnd();
		    const ON_Interval domain =
			trim_pieces[side][piece]->Domain();
		    bu_log("Boolean offset-seam side %d piece %d has iso %d, "
			"domain %.17g -> %.17g, UV %.17g %.17g -> %.17g "
			"%.17g.\n", side, piece,
			static_cast<int>(surface->IsIsoparametric(
			    *trim_pieces[side][piece], &domain)),
			domain.Min(), domain.Max(), start.x, start.y, end.x,
			end.y);
		}
		return skipped("a split parameter curve has no unique edge match");
	    }
	}
	if (matches[side][0].m_edge_position ==
		matches[side][1].m_edge_position)
	{
	    return skipped("split parameter curves select the same edge");
	}
    }

    for (int edge_position = 0; edge_position < 2; ++edge_position) {
	int piece_for_side[2] = {-1, -1};
	for (int side = 0; side < 2; ++side) {
	    for (int piece = 0; piece < 2; ++piece) {
		if (matches[side][piece].m_edge_position == edge_position) {
		    piece_for_side[side] = piece;
		}
	    }
	}
	if (piece_for_side[0] < 0 || piece_for_side[1] < 0) {
	    return skipped("a split edge is not used by both faces");
	}
	const bool first_effective_reversed =
	    matches[0][piece_for_side[0]].m_reversed ^
	    repaired.m_F[first_face_index].m_bRev;
	const bool second_effective_reversed =
	    matches[1][piece_for_side[1]].m_reversed ^
	    repaired.m_F[second_face_index].m_bRev;
	if (first_effective_reversed == second_effective_reversed) {
	    return skipped("the two faces traverse a split edge in the same direction");
	}
    }

    std::vector<int> new_trim_indices[2];
    bool installed = true;
    for (int side = 0; side < 2 && installed; ++side) {
	for (int piece = 0; piece < 2; ++piece) {
	    const BooleanParameterEdgeMatch &match = matches[side][piece];
	    const int curve_index = repaired.AddTrimCurve(
		trim_pieces[side][piece].release());
	    if (curve_index < 0) {
		installed = false;
		break;
	    }
	    ON_BrepTrim &created = repaired.NewTrim(
		repaired.m_E[new_edge_indices[match.m_edge_position]],
		match.m_reversed, repaired.m_L[loop_indices[side]],
		curve_index);
	    if (created.m_trim_index < 0) {
		installed = false;
		break;
	    }
	    created.m_type = ON_BrepTrim::mated;
	    created.m_tolerance[0] = old_trim_tolerances[side][0];
	    created.m_tolerance[1] = old_trim_tolerances[side][1];
	    const ON_Surface *surface = created.SurfaceOf();
	    const ON_Interval domain = created.Domain();
	    if (surface == NULL) {
		installed = false;
		break;
	    }
	    created.m_iso = surface->IsIsoparametric(created, &domain);
	    new_trim_indices[side].push_back(created.m_trim_index);
	}
    }
    if (!installed || new_trim_indices[0].size() != 2 ||
	new_trim_indices[1].size() != 2)
    {
	return skipped("split trims could not be installed");
    }

    for (int side = 0; side < 2; ++side) {
	ON_BrepLoop &loop = repaired.m_L[loop_indices[side]];
	loop.m_ti.SetCount(0);
	for (int trim_index : old_loop_trims[side]) {
	    if (trim_index != old_trim_indices[side]) {
		loop.m_ti.Append(trim_index);
		repaired.m_T[trim_index].m_li = loop_indices[side];
		continue;
	    }
	    for (int new_trim_index : new_trim_indices[side]) {
		loop.m_ti.Append(new_trim_index);
		repaired.m_T[new_trim_index].m_li = loop_indices[side];
	    }
	}
    }

    for (int side = 0; side < 2; ++side) {
	repaired.DeleteTrim(repaired.m_T[old_trim_indices[side]], false);
    }
    for (int side = 0; side < 2; ++side) {
	repaired.DeleteEdge(repaired.m_E[old_edge_indices[side]], false);
    }

    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    const bool compacted = repaired.Compact();
    if (compacted) {
	repaired.SetTrimBoundingBoxes(false);
    }
    const bool iso_flags_set = compacted && repaired.SetTrimIsoFlags();
    const bool trim_types_set = iso_flags_set &&
	repaired.SetTrimTypeFlags(false);
    const bool vertex_tolerances_set = trim_types_set &&
	repaired.SetVertexTolerances(false);
    const bool edge_tolerances_set = vertex_tolerances_set &&
	set_boolean_edge_tolerances(&repaired);
    const bool trim_tolerances_set = edge_tolerances_set &&
	set_boolean_trim_tolerances(&repaired);
    const bool valid = trim_tolerances_set &&
	repaired.IsValid(&validation_log);
    const int naked_after = boolean_naked_edge_count(&repaired);
    if (!valid || naked_before < 2 || naked_after != naked_before - 2 ||
	repaired.m_E.Count() != edge_count_before ||
	repaired.m_T.Count() != trim_count_before + 2 ||
	repaired.m_F.Count() != face_count_before ||
	repaired.m_L.Count() != loop_count_before ||
	repaired.m_S.Count() != surface_count_before)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_String message(validation_text);
	    bu_log("Boolean offset-seam closed-edge repair rolled back: "
		"valid %d, naked %d -> %d, edges %d -> %d, trims %d -> %d%s%s.\n",
		valid, naked_before, naked_after, edge_count_before,
		repaired.m_E.Count(), trim_count_before, repaired.m_T.Count(),
		message.Array() && message.Array()[0] ? ": " : "",
		message.Array() ? message.Array() : "");
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    *brep = repaired;
    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static bool
repair_boolean_offset_seam_closed_edges(ON_Brep *brep)
{
    if (brep == NULL) {
	return false;
    }

    const double requested_tolerance = 2.0 *
	boolean_model_repair_tolerance(brep->BoundingBox());
    if (!(requested_tolerance > 0.0) ||
	!std::isfinite(requested_tolerance))
    {
	return false;
    }

    int repaired_count = 0;
    while (true) {
	std::vector<int> candidates;
	for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	    if (is_active_boolean_closed_naked_edge(brep, edge_index)) {
		candidates.push_back(edge_index);
	    }
	}
	if (candidates.size() < 2) {
	    break;
	}

	std::vector<int> match_count(brep->m_E.Count(), 0);
	std::vector<std::pair<int, int> > pairs;
	for (size_t first = 0; first < candidates.size(); ++first) {
	    const ON_BrepEdge &first_edge = brep->m_E[candidates[first]];
	    const int first_face = brep->m_T[first_edge.m_ti[0]].FaceIndexOf();
	    const double first_extent = first_edge.BoundingBox().Diagonal().Length();
	    for (size_t second = first + 1; second < candidates.size(); ++second) {
		const ON_BrepEdge &second_edge = brep->m_E[candidates[second]];
		const int second_face =
		    brep->m_T[second_edge.m_ti[0]].FaceIndexOf();
		const double second_extent =
		    second_edge.BoundingBox().Diagonal().Length();
		const double tolerance = std::min(requested_tolerance,
		    0.01 * std::min(first_extent, second_extent));
		if (first_face == second_face || !(tolerance > 0.0) ||
		    !std::isfinite(tolerance) ||
		    !closed_curve_loci_coincident(first_edge, second_edge,
			tolerance))
		{
		    continue;
		}
		++match_count[candidates[first]];
		++match_count[candidates[second]];
		pairs.push_back(std::make_pair(candidates[first],
		    candidates[second]));
	    }
	}

	bool repaired = false;
	for (const std::pair<int, int> &pair : pairs) {
	    if (match_count[pair.first] != 1 || match_count[pair.second] != 1) {
		continue;
	    }
	    const ON_BrepEdge &first_edge = brep->m_E[pair.first];
	    const ON_BrepEdge &second_edge = brep->m_E[pair.second];
	    const double tolerance = std::min(requested_tolerance,
		0.01 * std::min(first_edge.BoundingBox().Diagonal().Length(),
		    second_edge.BoundingBox().Diagonal().Length()));
	    const SharedSSIEdgeRepairResult result =
		repair_boolean_offset_seam_closed_edge_pair(brep, pair.first,
		    pair.second, tolerance);
	    if (result == SHARED_SSI_EDGE_REPAIR_FAILURE) {
		return false;
	    }
	    if (result == SHARED_SSI_EDGE_REPAIR_COMPLETE) {
		++repaired_count;
		repaired = true;
		break;
	    }
	}
	if (!repaired) {
	    break;
	}
    }

    if (DEBUG_BREP_BOOLEAN && repaired_count > 0) {
	bu_log("Boolean offset-seam closed-edge repair completed %d pair%s.\n",
	    repaired_count, repaired_count == 1 ? "" : "s");
    }
    return true;
}


static bool
boolean_vertex_pair_has_other_edge(
    const ON_Brep *brep,
    int first_vertex,
    int second_vertex,
    int ignored_edge)
{
    if (brep == NULL || first_vertex < 0 || second_vertex < 0 ||
	first_vertex == second_vertex)
    {
	return true;
    }

    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	const ON_BrepEdge &edge = brep->m_E[edge_index];
	if (edge_index == ignored_edge || edge.m_edge_index != edge_index) {
	    continue;
	}
	if ((edge.m_vi[0] == first_vertex && edge.m_vi[1] == second_vertex) ||
	    (edge.m_vi[1] == first_vertex && edge.m_vi[0] == second_vertex))
	{
	    return true;
	}
    }
    return false;
}


static bool
combine_boolean_vertices(
    ON_Brep &brep,
    int keep_vertex,
    int remove_vertex,
    double tolerance)
{
    if (keep_vertex == remove_vertex) {
	return true;
    }
    if (keep_vertex < 0 || keep_vertex >= brep.m_V.Count() ||
	remove_vertex < 0 || remove_vertex >= brep.m_V.Count())
    {
	return false;
    }

    ON_BrepVertex &keep = brep.m_V[keep_vertex];
    ON_BrepVertex &remove = brep.m_V[remove_vertex];
    const double separation = keep.Point().DistanceTo(remove.Point());
    if (!keep.Point().IsValid() || !remove.Point().IsValid() ||
	!std::isfinite(separation) || separation > tolerance)
    {
	return false;
    }
    keep.m_tolerance = std::isfinite(keep.m_tolerance) &&
	keep.m_tolerance >= 0.0 ?
	std::max(keep.m_tolerance, separation) : separation;
    remove.m_tolerance = std::isfinite(remove.m_tolerance) &&
	remove.m_tolerance >= 0.0 ?
	std::max(remove.m_tolerance, separation) : separation;
    return brep.CombineCoincidentVertices(keep, remove);
}


static bool
close_boolean_endpoint_spike_gap(
    ON_Brep &brep,
    int adjusted_trim_index,
    int survivor_trim_index,
    bool adjust_end,
    const ON_3dPoint &collapse_center,
    double tolerance)
{
    if (adjusted_trim_index < 0 || adjusted_trim_index >= brep.m_T.Count() ||
	survivor_trim_index < 0 || survivor_trim_index >= brep.m_T.Count() ||
	adjusted_trim_index == survivor_trim_index)
    {
	return false;
    }

    ON_BrepTrim &adjusted = brep.m_T[adjusted_trim_index];
    const ON_BrepTrim &survivor = brep.m_T[survivor_trim_index];
    if (adjusted.m_trim_index != adjusted_trim_index ||
	survivor.m_trim_index != survivor_trim_index ||
	adjusted.m_li < 0 || adjusted.m_li != survivor.m_li ||
	adjusted.FaceIndexOf() != survivor.FaceIndexOf())
    {
	return false;
    }

    const ON_3dPoint endpoint = adjust_end ? adjusted.PointAtEnd() :
	adjusted.PointAtStart();
    const ON_3dPoint join = adjust_end ? survivor.PointAtStart() :
	survivor.PointAtEnd();
    const ON_Surface *surface = adjusted.SurfaceOf();
    if (surface == NULL || surface != survivor.SurfaceOf() ||
	!endpoint.IsValid() || !join.IsValid() || !collapse_center.IsValid())
    {
	return false;
    }

    const double parameter_gap = endpoint.DistanceTo(join);
    const ON_3dPoint endpoint_lift = surface->PointAt(endpoint.x, endpoint.y);
    const ON_3dPoint join_lift = surface->PointAt(join.x, join.y);
    if (!std::isfinite(parameter_gap) ||
	!endpoint_lift.IsValid() || !join_lift.IsValid() ||
	endpoint_lift.DistanceTo(collapse_center) > tolerance ||
	join_lift.DistanceTo(collapse_center) > tolerance ||
	endpoint_lift.DistanceTo(join_lift) > tolerance)
    {
	return false;
    }

    if (adjusted.m_c2i < 0 || adjusted.m_c2i >= brep.m_C2.Count() ||
	brep.m_C2[adjusted.m_c2i] == NULL)
    {
	return false;
    }
    for (int trim_index = 0; trim_index < brep.m_T.Count(); ++trim_index) {
	if (trim_index != adjusted_trim_index &&
	    brep.m_T[trim_index].m_trim_index == trim_index &&
	    brep.m_T[trim_index].m_c2i == adjusted.m_c2i)
	{
	    return false;
	}
    }

    ON_Curve *parameter_curve = brep.m_C2[adjusted.m_c2i];
    std::unique_ptr<ON_Curve> original_parameter_curve(
	parameter_curve->DuplicateCurve());
    if (!original_parameter_curve || !original_parameter_curve->IsValid()) {
	return false;
    }
    const bool set = adjust_end == adjusted.ProxyCurveIsReversed() ?
	parameter_curve->SetStartPoint(join) :
	parameter_curve->SetEndPoint(join);
    if (!set || !parameter_curve->IsValid()) {
	return false;
    }
    const double lift_error = parameter_curve_pair_lift_maximum_error(surface,
	original_parameter_curve.get(), surface, parameter_curve, false);
    if (!std::isfinite(lift_error) || lift_error > tolerance) {
	return false;
    }
    adjusted.DestroyPspaceInformation();
    const ON_Interval adjusted_domain = adjusted.Domain();
    adjusted.m_iso = surface->IsIsoparametric(adjusted, &adjusted_domain);
    const ON_3dPoint changed = adjust_end ? adjusted.PointAtEnd() :
	adjusted.PointAtStart();
    return changed.IsValid() && changed.DistanceTo(join) <= ON_ZERO_TOLERANCE;
}


static SharedSSIEdgeRepairResult
repair_boolean_source_edge_endpoint_spike(
    ON_Brep *brep,
    const BooleanSourceEdgeUse &single_use,
    const BooleanSourceEdgeUse &residual_use,
    const BooleanSourceEdgeUse &survivor_use,
    bool residual_precedes_survivor,
    double tolerance,
    const bool *certified_survivor_reversal = NULL)
{
    const auto skipped = [](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean source-edge endpoint spike skipped: %s.\n", reason);
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    };

    if (brep == NULL ||
	!is_active_boolean_naked_edge(brep, single_use.m_edge_index) ||
	!is_active_boolean_naked_edge(brep, residual_use.m_edge_index) ||
	!is_active_boolean_naked_edge(brep, survivor_use.m_edge_index) ||
	single_use.m_edge_index == residual_use.m_edge_index ||
	single_use.m_edge_index == survivor_use.m_edge_index ||
	residual_use.m_edge_index == survivor_use.m_edge_index)
    {
	return skipped("candidate edges are not three distinct naked edges");
    }

    const ON_BrepTrim &single_trim = brep->m_T[single_use.m_trim_index];
    const ON_BrepTrim &residual_trim = brep->m_T[residual_use.m_trim_index];
    const ON_BrepTrim &survivor_trim = brep->m_T[survivor_use.m_trim_index];
    const int single_face_index = single_trim.FaceIndexOf();
    const int survivor_face_index = survivor_trim.FaceIndexOf();
    if (single_face_index < 0 || single_face_index >= brep->m_F.Count() ||
	survivor_face_index < 0 || survivor_face_index >= brep->m_F.Count() ||
	single_face_index == survivor_face_index)
    {
	return skipped("surviving trims do not belong to distinct valid faces");
    }
    const int junction_vertex = residual_precedes_survivor ?
	residual_trim.m_vi[1] : residual_trim.m_vi[0];
    const int survivor_junction = residual_precedes_survivor ?
	survivor_trim.m_vi[0] : survivor_trim.m_vi[1];
    const int removed_vertex = residual_precedes_survivor ?
	residual_trim.m_vi[0] : residual_trim.m_vi[1];
    if (junction_vertex < 0 || junction_vertex >= brep->m_V.Count() ||
	removed_vertex < 0 || removed_vertex >= brep->m_V.Count() ||
	junction_vertex != survivor_junction ||
	junction_vertex == removed_vertex)
    {
	return skipped("residual edge is not attached to the survivor endpoint");
    }

    const ON_BrepEdge &single_edge = brep->m_E[single_use.m_edge_index];
    const ON_BrepEdge &residual_edge = brep->m_E[residual_use.m_edge_index];
    const ON_BrepEdge &survivor_edge = brep->m_E[survivor_use.m_edge_index];
    const bool preserve_single_endpoint =
	removed_vertex == single_edge.m_vi[0] ||
	removed_vertex == single_edge.m_vi[1];
    const int collapse_vertex = preserve_single_endpoint ?
	removed_vertex : junction_vertex;
    const int collapsed_vertex = preserve_single_endpoint ?
	junction_vertex : removed_vertex;
    const ON_3dPoint collapse_center =
	brep->m_V[collapse_vertex].Point();
    const ON_3dPoint removed_point =
	brep->m_V[collapsed_vertex].Point();
    const double removed_distance = collapse_center.IsValid() &&
	removed_point.IsValid() ? removed_point.DistanceTo(collapse_center) :
	ON_UNSET_VALUE;
    if (!(tolerance > 0.0) || !std::isfinite(tolerance) ||
	!collapse_center.IsValid() || !removed_point.IsValid())
    {
	return skipped("candidate tolerance or endpoint is invalid");
    }

    /* Find the smallest power-of-two tolerance that certifies both changes,
     * bounded by the model repair tolerance.  This avoids spending the full
     * global allowance on a much smaller endpoint artifact. */
    double match_tolerance = certified_survivor_reversal ? tolerance :
	std::min(tolerance, INTERSECTION_TOL);
    bool residual_locus_certified = false;
    bool surviving_edges_certified = false;
    bool survivor_reverses_single = false;
    const bool single_effective_reversal = single_trim.m_bRev3d !=
	brep->m_F[single_face_index].m_bRev;
    const bool survivor_effective_reversal = survivor_trim.m_bRev3d !=
	brep->m_F[survivor_face_index].m_bRev;
    const bool expected_reversal =
	single_effective_reversal == survivor_effective_reversal;
    while (true) {
	residual_locus_certified = removed_distance <= match_tolerance &&
	    brep_curve_locus_within_ball(residual_edge, collapse_center,
		match_tolerance);
	if (certified_survivor_reversal) {
	    survivor_reverses_single = *certified_survivor_reversal;
	    surviving_edges_certified = residual_locus_certified &&
		survivor_reverses_single == expected_reversal;
	} else {
	    survivor_reverses_single = false;
	    surviving_edges_certified = residual_locus_certified &&
		brep_curves_coincident(survivor_edge, single_edge,
		    match_tolerance, &survivor_reverses_single) &&
		survivor_reverses_single == expected_reversal;
	}
	if (surviving_edges_certified || match_tolerance >= tolerance) {
	    break;
	}
	match_tolerance = std::min(tolerance, 2.0 * match_tolerance);
    }
    if (!residual_locus_certified)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean endpoint-spike residual edge %d extent %.17g, "
		"survivor extent %.17g, endpoint distance %.17g, proof "
		"tolerance %.17g (requested %.17g).\n",
		residual_use.m_edge_index,
		residual_edge.BoundingBox().Diagonal().Length(),
		survivor_edge.BoundingBox().Diagonal().Length(),
		removed_distance, match_tolerance, tolerance);
	}
	return skipped("residual curve locus is not certified inside the endpoint ball");
    }
    if (!surviving_edges_certified)
    {
	return skipped("surviving edge is not certified coincident and opposite");
    }

    if (boolean_vertex_pair_has_other_edge(brep, junction_vertex,
	    removed_vertex, residual_use.m_edge_index))
    {
	return skipped("collapsing the residual would collapse another edge");
    }

    const int previous_trim_index = brep->PrevTrim(residual_use.m_trim_index);
    const int next_trim_index = brep->NextTrim(residual_use.m_trim_index);
    const int adjacent_trim_index = residual_precedes_survivor ?
	previous_trim_index : next_trim_index;
    const int adjusted_trim_index = preserve_single_endpoint ?
	survivor_use.m_trim_index : adjacent_trim_index;
    const int gap_peer_trim_index = preserve_single_endpoint ?
	adjacent_trim_index : survivor_use.m_trim_index;
    const bool adjust_end = preserve_single_endpoint ?
	!residual_precedes_survivor : residual_precedes_survivor;
    if (previous_trim_index < 0 || next_trim_index < 0 ||
	adjusted_trim_index < 0 ||
	(residual_precedes_survivor ? next_trim_index : previous_trim_index) !=
	    survivor_use.m_trim_index)
    {
	return skipped("residual trim does not border the expected survivor");
    }

    const int naked_before = boolean_active_naked_edge_count(brep);
    const int edge_count_before = brep->m_E.Count();
    const int trim_count_before = brep->m_T.Count();
    const int face_count_before = brep->m_F.Count();
    const int loop_count_before = brep->m_L.Count();
    const int surface_count_before = brep->m_S.Count();
    const int vertex_count_before = brep->m_V.Count();
    ON_Brep repaired(*brep);

    const double collapsed_vertex_separation = repaired.m_V[collapse_vertex].
	Point().DistanceTo(repaired.m_V[collapsed_vertex].Point());
    repaired.m_V[collapse_vertex].m_tolerance = std::max(
	repaired.m_V[collapse_vertex].m_tolerance,
	collapsed_vertex_separation);

    if (!repaired.CollapseEdge(residual_use.m_edge_index, false,
	    collapse_vertex))
    {
	return skipped("OpenNURBS could not collapse the certified residual edge");
    }
    if (!close_boolean_endpoint_spike_gap(repaired, adjusted_trim_index,
	    gap_peer_trim_index, adjust_end,
	    collapse_center, match_tolerance))
    {
	return skipped("collapsed residual trim gap could not be closed safely");
    }
    int merged_vertices = 1;

    for (int endpoint = 0; endpoint < 2; ++endpoint) {
	const int survivor_vertex =
	    repaired.m_E[survivor_use.m_edge_index].m_vi[endpoint];
	const int single_vertex = repaired.m_E[single_use.m_edge_index].m_vi[
	    survivor_reverses_single ? 1 - endpoint : endpoint];
	if (survivor_vertex == single_vertex) {
	    continue;
	}
	if (boolean_vertex_pair_has_other_edge(&repaired, survivor_vertex,
		single_vertex, -1) ||
	    !combine_boolean_vertices(repaired, survivor_vertex, single_vertex,
		match_tolerance))
	{
	    return skipped("surviving edge endpoints cannot be merged safely");
	}
	++merged_vertices;
    }

    ON_BrepEdge &repaired_survivor =
	repaired.m_E[survivor_use.m_edge_index];
    ON_BrepEdge &repaired_single = repaired.m_E[single_use.m_edge_index];
    if (survivor_reverses_single && !repaired_single.Reverse()) {
	return skipped("single edge could not be oriented with the survivor");
    }
    if (repaired_survivor.m_vi[0] != repaired_single.m_vi[0] ||
	repaired_survivor.m_vi[1] != repaired_single.m_vi[1] ||
	!repaired.CombineCoincidentEdges(repaired_survivor, repaired_single))
    {
	return skipped("certified coincident edges could not be combined");
    }

    ON_BrepTrim &repaired_single_trim = repaired.m_T[single_use.m_trim_index];
    ON_BrepTrim &repaired_survivor_trim =
	repaired.m_T[survivor_use.m_trim_index];
    if (repaired_single_trim.m_trim_index != single_use.m_trim_index ||
	repaired_survivor_trim.m_trim_index != survivor_use.m_trim_index ||
	repaired_single_trim.m_ei < 0 ||
	repaired_single_trim.m_ei != repaired_survivor_trim.m_ei ||
	repaired_single_trim.m_ei >= repaired.m_E.Count() ||
	repaired.m_E[repaired_single_trim.m_ei].m_ti.Count() != 2)
    {
	return skipped("combined edge did not acquire exactly the two expected trims");
    }
    repaired_single_trim.m_type = ON_BrepTrim::mated;
    repaired_survivor_trim.m_type = ON_BrepTrim::mated;

    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    const bool compacted = repaired.Compact();
    if (compacted) {
	repaired.SetTrimBoundingBoxes(false);
    }
    const bool trim_iso_flags_set = compacted && repaired.SetTrimIsoFlags();
    const bool trim_types_set = trim_iso_flags_set &&
	repaired.SetTrimTypeFlags(false);
    const bool vertex_tolerances_set = trim_types_set &&
	repaired.SetVertexTolerances(false);
    const bool edge_tolerances_set = vertex_tolerances_set &&
	set_boolean_edge_tolerances(&repaired);
    const bool trim_tolerances_set = edge_tolerances_set &&
	set_boolean_trim_tolerances(&repaired);
    const bool valid = trim_tolerances_set && repaired.IsValid(&validation_log);
    const int naked_after = boolean_active_naked_edge_count(&repaired);
    if (!valid || naked_before < 3 || naked_after != naked_before - 3 ||
	repaired.m_E.Count() != edge_count_before - 2 ||
	repaired.m_T.Count() != trim_count_before - 1 ||
	repaired.m_F.Count() != face_count_before ||
	repaired.m_L.Count() != loop_count_before ||
	repaired.m_S.Count() != surface_count_before ||
	repaired.m_V.Count() != vertex_count_before - merged_vertices)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_String message(validation_text);
	    bu_log("Boolean source-edge endpoint spike rolled back: valid %d, "
		"naked %d -> %d, edges %d -> %d, trims %d -> %d, "
		"vertices %d -> %d (expected %d)%s%s.\n", valid,
		naked_before, naked_after, edge_count_before,
		repaired.m_E.Count(), trim_count_before, repaired.m_T.Count(),
		vertex_count_before, repaired.m_V.Count(),
		vertex_count_before - merged_vertices,
		message.Array() && message.Array()[0] ? ": " : "",
		message.Array() ? message.Array() : "");
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    *brep = repaired;
    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static SharedSSIEdgeRepairResult
repair_boolean_source_edge_pair_endpoint_spike(
    ON_Brep *brep,
    const ON_BrepEdge &source_edge,
    const std::vector<BooleanSourceEdgeUse> &first_uses,
    const std::vector<BooleanSourceEdgeUse> &second_uses,
    double tolerance)
{
    const auto skipped = [](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean source-edge 1/1 repair skipped: %s.\n", reason);
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    };

    if (brep == NULL || first_uses.size() != 1 || second_uses.size() != 1) {
	return skipped("candidate cardinality changed");
    }
    if (source_edge.IsClosed()) {
	return skipped("closed source edges have no endpoint spike");
    }

    const BooleanSourceEdgeUse *uses[2] = {
	&first_uses[0], &second_uses[0]
    };
    if (!is_active_boolean_naked_edge(brep, uses[0]->m_edge_index) ||
	!is_active_boolean_naked_edge(brep, uses[1]->m_edge_index) ||
	uses[0]->m_edge_index == uses[1]->m_edge_index)
    {
	return skipped("candidate edges are not distinct naked edges");
    }

    const ON_BrepTrim &first_trim = brep->m_T[uses[0]->m_trim_index];
    const ON_BrepTrim &second_trim = brep->m_T[uses[1]->m_trim_index];
    const int face_indices[2] = {
	first_trim.FaceIndexOf(), second_trim.FaceIndexOf()
    };
    if (face_indices[0] < 0 || face_indices[0] >= brep->m_F.Count() ||
	face_indices[1] < 0 || face_indices[1] >= brep->m_F.Count() ||
	face_indices[0] == face_indices[1])
    {
	return skipped("candidate edges belong to the same face");
    }

    const double source_starts[2] = {
	first_trim.m_bRev3d ? uses[0]->m_source_end :
	    uses[0]->m_source_start,
	second_trim.m_bRev3d ? uses[1]->m_source_end :
	    uses[1]->m_source_start
    };
    const double source_ends[2] = {
	first_trim.m_bRev3d ? uses[0]->m_source_start :
	    uses[0]->m_source_end,
	second_trim.m_bRev3d ? uses[1]->m_source_start :
	    uses[1]->m_source_end
    };
    const double source_scale = std::max(1.0,
	std::max(std::max(fabs(source_starts[0]), fabs(source_ends[0])),
	    std::max(fabs(source_starts[1]), fabs(source_ends[1]))));
    const double strict_guard = 256.0 * ON_EPSILON * source_scale;
    const double progress[2] = {
	source_ends[0] - source_starts[0],
	source_ends[1] - source_starts[1]
    };
    const bool same_traversal =
	(progress[0] > 0.0) == (progress[1] > 0.0);
    const bool effective_forward[2] = {
	(progress[0] > 0.0) != brep->m_F[face_indices[0]].m_bRev,
	(progress[1] > 0.0) != brep->m_F[face_indices[1]].m_bRev
    };
    const double matching_second_start = same_traversal ?
	source_starts[1] : source_ends[1];
    const double matching_second_end = same_traversal ?
	source_ends[1] : source_starts[1];
    const double source_tolerance =
	boolean_source_edge_normalized_tolerance(source_edge,
	    std::min(tolerance, 2.0 * INTERSECTION_TOL));
    if (!(source_tolerance > 0.0) ||
	fabs(progress[0]) <= strict_guard ||
	fabs(progress[1]) <= strict_guard ||
	effective_forward[0] == effective_forward[1] ||
	fabs(source_starts[0] - matching_second_start) > source_tolerance ||
	fabs(source_ends[0] - matching_second_end) > source_tolerance)
    {
	return skipped("source intervals are not matching opposite effective traversals");
    }

    /* A fragmented intersection may leave one side of a source boundary as
     * a matching edge followed or preceded by a tiny return to the other
     * side's endpoint.  The UV provenance check deliberately excludes that
     * return from the source edge.  Look only at the two adjacent trims and
     * let the endpoint-spike repair certify the complete 3D curve locus,
     * endpoint topology, and opposite surviving edge before changing it. */
    for (int survivor_side = 0; survivor_side < 2; ++survivor_side) {
	const BooleanSourceEdgeUse &survivor = *uses[survivor_side];
	const BooleanSourceEdgeUse &single = *uses[1 - survivor_side];
	const int adjacent_trims[2] = {
	    brep->PrevTrim(survivor.m_trim_index),
	    brep->NextTrim(survivor.m_trim_index)
	};
	for (int adjacent = 0; adjacent < 2; ++adjacent) {
	    const int residual_trim_index = adjacent_trims[adjacent];
	    if (residual_trim_index < 0 ||
		residual_trim_index >= brep->m_T.Count())
	    {
		continue;
	    }

	    const ON_BrepTrim &residual_trim =
		brep->m_T[residual_trim_index];
	    if (residual_trim.m_ei < 0 ||
		residual_trim.m_ei == single.m_edge_index ||
		residual_trim.m_ei == survivor.m_edge_index ||
		!is_active_boolean_naked_edge(brep, residual_trim.m_ei))
	    {
		continue;
	    }

	    BooleanSourceEdgeUse residual;
	    residual.m_edge_index = residual_trim.m_ei;
	    residual.m_trim_index = residual_trim_index;
	    const SharedSSIEdgeRepairResult result =
		repair_boolean_source_edge_endpoint_spike(brep, single,
		    residual, survivor, adjacent == 0, tolerance);
	    if (result != SHARED_SSI_EDGE_REPAIR_SKIPPED) {
		return result;
	    }
	}
    }

    return skipped("no adjacent endpoint spike was certified");
}


static SharedSSIEdgeRepairResult
repair_boolean_source_edge_pair(
    ON_Brep *brep,
    const ON_BrepEdge &source_edge,
    const std::vector<BooleanSourceEdgeUse> &first_uses,
    const std::vector<BooleanSourceEdgeUse> &second_uses,
    double tolerance,
    const bool *certified_second_reversal = NULL,
    bool allow_batched_repair = false)
{
    const auto skipped = [](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean source-edge 1/1 mating skipped: %s.\n", reason);
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    };

    if (brep == NULL || first_uses.size() != 1 || second_uses.size() != 1) {
	return skipped("candidate cardinality changed");
    }

    const BooleanSourceEdgeUse &first_use = first_uses[0];
    const BooleanSourceEdgeUse &second_use = second_uses[0];
    if (!is_active_boolean_naked_edge(brep, first_use.m_edge_index) ||
	!is_active_boolean_naked_edge(brep, second_use.m_edge_index) ||
	first_use.m_edge_index == second_use.m_edge_index ||
	first_use.m_trim_index < 0 ||
	first_use.m_trim_index >= brep->m_T.Count() ||
	second_use.m_trim_index < 0 ||
	second_use.m_trim_index >= brep->m_T.Count())
    {
	return skipped("candidates are not two distinct naked edges");
    }

    const ON_BrepTrim &first_trim = brep->m_T[first_use.m_trim_index];
    const ON_BrepTrim &second_trim = brep->m_T[second_use.m_trim_index];
    const int first_face_index = first_trim.FaceIndexOf();
    const int second_face_index = second_trim.FaceIndexOf();
    if (first_trim.m_trim_index != first_use.m_trim_index ||
	second_trim.m_trim_index != second_use.m_trim_index ||
	first_face_index < 0 || first_face_index >= brep->m_F.Count() ||
	second_face_index < 0 || second_face_index >= brep->m_F.Count() ||
	first_face_index == second_face_index)
    {
	return skipped("candidate trim topology is invalid");
    }

    const double first_start = first_trim.m_bRev3d ?
	first_use.m_source_end : first_use.m_source_start;
    const double first_end = first_trim.m_bRev3d ?
	first_use.m_source_start : first_use.m_source_end;
    const double second_start = second_trim.m_bRev3d ?
	second_use.m_source_end : second_use.m_source_start;
    const double second_end = second_trim.m_bRev3d ?
	second_use.m_source_start : second_use.m_source_end;
    const double source_scale = std::max(1.0,
	std::max(std::max(fabs(first_start), fabs(first_end)),
	    std::max(fabs(second_start), fabs(second_end))));
    const double strict_guard = 256.0 * ON_EPSILON * source_scale;
    const double source_tolerance =
	boolean_source_edge_normalized_tolerance(source_edge,
	    std::min(tolerance, 2.0 * INTERSECTION_TOL));
    const bool same_traversal =
	(first_end > first_start) == (second_end > second_start);
    const bool first_effective_forward = (first_end > first_start) !=
	brep->m_F[first_face_index].m_bRev;
    const bool second_effective_forward = (second_end > second_start) !=
	brep->m_F[second_face_index].m_bRev;
    const double matching_second_start = same_traversal ? second_start :
	second_end;
    const double matching_second_end = same_traversal ? second_end :
	second_start;
    if (!(source_tolerance > 0.0) ||
	!std::isfinite(first_start) || !std::isfinite(first_end) ||
	!std::isfinite(second_start) || !std::isfinite(second_end) ||
	fabs(first_end - first_start) <= strict_guard ||
	fabs(second_end - second_start) <= strict_guard ||
	first_effective_forward == second_effective_forward ||
	fabs(first_start - matching_second_start) > source_tolerance ||
	fabs(first_end - matching_second_end) > source_tolerance)
    {
	return skipped("source intervals are not matching opposite effective traversals");
    }

    const ON_BrepEdge &first_edge = brep->m_E[first_use.m_edge_index];
    const ON_BrepEdge &second_edge = brep->m_E[second_use.m_edge_index];
    bool second_reverses_first = false;
    bool curves_certified = false;
    bool polyline_certified = false;
    const bool first_effective_reversal = first_trim.m_bRev3d !=
	brep->m_F[first_face_index].m_bRev;
    const bool second_effective_reversal = second_trim.m_bRev3d !=
	brep->m_F[second_face_index].m_bRev;
    const bool expected_reversal =
	first_effective_reversal == second_effective_reversal;
    double match_tolerance = certified_second_reversal ? tolerance :
	std::min(tolerance, INTERSECTION_TOL);
    if (certified_second_reversal != NULL) {
	second_reverses_first = *certified_second_reversal;
	curves_certified = second_reverses_first == expected_reversal;
    } else {
	bool underlying_reversed = false;
	const ON_PolylineCurve *first_polyline = ON_PolylineCurve::Cast(
	    first_edge.ProxyCurve());
	const ON_PolylineCurve *second_polyline = ON_PolylineCurve::Cast(
	    second_edge.ProxyCurve());
	if (boolean_polyline_curves_are_coincident(first_edge.ProxyCurve(),
		second_edge.ProxyCurve(), match_tolerance, underlying_reversed))
	{
	    second_reverses_first = underlying_reversed !=
		first_edge.ProxyCurveIsReversed() !=
		second_edge.ProxyCurveIsReversed();
	    curves_certified = second_reverses_first == expected_reversal;
	    polyline_certified = curves_certified;
	}
	if (!curves_certified && first_polyline != NULL &&
	    second_polyline != NULL &&
	    first_polyline->m_pline.Count() ==
		second_polyline->m_pline.Count() &&
	    first_polyline->m_pline.Count() > 1024)
	{
	    return skipped("dense corresponding polylines failed the linear coincidence certificate");
	}
	while (!curves_certified) {
	    second_reverses_first = false;
	    curves_certified = brep_curves_coincident(first_edge, second_edge,
		match_tolerance, &second_reverses_first) &&
		second_reverses_first == expected_reversal;
	    if (curves_certified || match_tolerance >= tolerance) {
		break;
	    }
	    match_tolerance = std::min(tolerance, 2.0 * match_tolerance);
	}
    }
    if (!curves_certified) {
	return skipped("curves are not certified coincident and opposite");
    }

    const int naked_before = boolean_active_naked_edge_count(brep);
    const int edge_count_before = brep->m_E.Count();
    const int trim_count_before = brep->m_T.Count();
    const int face_count_before = brep->m_F.Count();
    const int loop_count_before = brep->m_L.Count();
    const int surface_count_before = brep->m_S.Count();
    const int vertex_count_before = brep->m_V.Count();
    std::unique_ptr<ON_Brep> transaction;
    if (!allow_batched_repair) {
	transaction.reset(new ON_Brep(*brep));
    }
    ON_Brep &repaired = transaction ? *transaction : *brep;
    int merged_vertices = 0;

    for (int endpoint = 0; endpoint < 2; ++endpoint) {
	const int first_vertex =
	    repaired.m_E[first_use.m_edge_index].m_vi[endpoint];
	const int second_vertex = repaired.m_E[second_use.m_edge_index].m_vi[
	    second_reverses_first ? 1 - endpoint : endpoint];
	if (first_vertex == second_vertex) {
	    continue;
	}
	if (boolean_vertex_pair_has_other_edge(&repaired, first_vertex,
		second_vertex, -1) ||
	    !combine_boolean_vertices(repaired, first_vertex, second_vertex,
		match_tolerance))
	{
	    return transaction ? skipped("candidate endpoints cannot be merged safely") :
		SHARED_SSI_EDGE_REPAIR_FAILURE;
	}
	++merged_vertices;
    }

    ON_BrepEdge &repaired_first = repaired.m_E[first_use.m_edge_index];
    ON_BrepEdge &repaired_second = repaired.m_E[second_use.m_edge_index];
    if (second_reverses_first && !repaired_second.Reverse()) {
	return transaction ? skipped("second edge could not be oriented with the first") :
	    SHARED_SSI_EDGE_REPAIR_FAILURE;
    }
    if (repaired_first.m_vi[0] != repaired_second.m_vi[0] ||
	repaired_first.m_vi[1] != repaired_second.m_vi[1] ||
	!repaired.CombineCoincidentEdges(repaired_first, repaired_second))
    {
	return transaction ? skipped("certified coincident edges could not be combined") :
	    SHARED_SSI_EDGE_REPAIR_FAILURE;
    }

    ON_BrepTrim &repaired_first_trim =
	repaired.m_T[first_use.m_trim_index];
    ON_BrepTrim &repaired_second_trim =
	repaired.m_T[second_use.m_trim_index];
    if (repaired_first_trim.m_trim_index != first_use.m_trim_index ||
	repaired_second_trim.m_trim_index != second_use.m_trim_index ||
	repaired_first_trim.m_ei < 0 ||
	repaired_first_trim.m_ei != repaired_second_trim.m_ei ||
	repaired_first_trim.m_ei >= repaired.m_E.Count() ||
	repaired.m_E[repaired_first_trim.m_ei].m_ti.Count() != 2)
    {
	return transaction ? skipped("combined edge did not acquire exactly two trims") :
	    SHARED_SSI_EDGE_REPAIR_FAILURE;
    }
	else {
	    repaired_first_trim.m_type = ON_BrepTrim::mated;
	    repaired_second_trim.m_type = ON_BrepTrim::mated;
    }

    if (!transaction) {
	return SHARED_SSI_EDGE_REPAIR_COMPLETE;
    }

    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    const bool compacted = repaired.Compact();
    if (compacted) {
	repaired.SetTrimBoundingBoxes(false);
    }
    const bool trim_iso_flags_set = compacted && repaired.SetTrimIsoFlags();
    const bool trim_types_set = trim_iso_flags_set &&
	repaired.SetTrimTypeFlags(false);
    const bool vertex_tolerances_set = trim_types_set &&
	repaired.SetVertexTolerances(false);
    const bool edge_tolerances_set = vertex_tolerances_set &&
	set_boolean_edge_tolerances(&repaired);
    const bool trim_tolerances_set = edge_tolerances_set &&
	set_boolean_trim_tolerances(&repaired);
    const bool valid = trim_tolerances_set && repaired.IsValid(&validation_log);
    const int naked_after = boolean_active_naked_edge_count(&repaired);
    if (!valid || naked_before < 2 || naked_after != naked_before - 2 ||
	repaired.m_E.Count() != edge_count_before - 1 ||
	repaired.m_T.Count() != trim_count_before ||
	repaired.m_F.Count() != face_count_before ||
	repaired.m_L.Count() != loop_count_before ||
	repaired.m_S.Count() != surface_count_before ||
	repaired.m_V.Count() != vertex_count_before - merged_vertices)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_String message(validation_text);
	    bu_log("Boolean source-edge 1/1 mating rolled back: valid %d, "
		"naked %d -> %d, edges %d -> %d, trims %d -> %d, "
		"vertices %d -> %d (expected %d)%s%s.\n", valid,
		naked_before, naked_after, edge_count_before,
		repaired.m_E.Count(), trim_count_before, repaired.m_T.Count(),
		vertex_count_before, repaired.m_V.Count(),
		vertex_count_before - merged_vertices,
		message.Array() && message.Array()[0] ? ": " : "",
		message.Array() ? message.Array() : "");
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    *brep = repaired;
    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static SharedSSIEdgeRepairResult
repair_boolean_source_edge_partition(
    ON_Brep *brep,
    const ON_BrepEdge &source_edge,
    const std::vector<BooleanSourceEdgeUse> &single_uses,
    const std::vector<BooleanSourceEdgeUse> &chain_uses,
    double tolerance)
{
    const auto skipped = [](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean source-edge partition skipped: %s.\n", reason);
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    };

    if (brep == NULL || single_uses.size() != 1 || chain_uses.size() != 2) {
	return skipped("candidate cardinality changed");
    }

    const BooleanSourceEdgeUse &single_use = single_uses[0];
    const BooleanSourceEdgeUse *unordered_chain[2] = {
	&chain_uses[0], &chain_uses[1]
    };
    if (!is_active_boolean_naked_edge(brep, single_use.m_edge_index) ||
	!is_active_boolean_naked_edge(brep, unordered_chain[0]->m_edge_index) ||
	!is_active_boolean_naked_edge(brep, unordered_chain[1]->m_edge_index))
    {
	return skipped("candidate edge is no longer naked");
    }

    const ON_BrepTrim &unordered_first_trim =
	brep->m_T[unordered_chain[0]->m_trim_index];
    const ON_BrepTrim &unordered_second_trim =
	brep->m_T[unordered_chain[1]->m_trim_index];
    if (unordered_first_trim.FaceIndexOf() !=
	    unordered_second_trim.FaceIndexOf() ||
	unordered_first_trim.m_li < 0 ||
	unordered_first_trim.m_li != unordered_second_trim.m_li ||
	unordered_first_trim.m_li >= brep->m_L.Count())
    {
	return skipped("chain trims are not in one loop and face");
    }

    const ON_BrepLoop &chain_loop = brep->m_L[unordered_first_trim.m_li];
    const int first_position = boolean_loop_trim_position(chain_loop,
	unordered_chain[0]->m_trim_index);
    const int second_position = boolean_loop_trim_position(chain_loop,
	unordered_chain[1]->m_trim_index);
    if (first_position < 0 || second_position < 0 ||
	chain_loop.m_ti.Count() < 2)
    {
	return skipped("chain trim positions are invalid");
    }

    const BooleanSourceEdgeUse *chain[2] = {NULL, NULL};
    if ((first_position + 1) % chain_loop.m_ti.Count() == second_position) {
	chain[0] = unordered_chain[0];
	chain[1] = unordered_chain[1];
    } else if ((second_position + 1) % chain_loop.m_ti.Count() ==
	    first_position)
    {
	chain[0] = unordered_chain[1];
	chain[1] = unordered_chain[0];
    } else {
	return skipped("chain trims are not consecutive");
    }

    const ON_BrepTrim &single_trim = brep->m_T[single_use.m_trim_index];
    const ON_BrepTrim &first_chain_trim = brep->m_T[chain[0]->m_trim_index];
    const ON_BrepTrim &second_chain_trim = brep->m_T[chain[1]->m_trim_index];
    if (single_trim.m_li < 0 || single_trim.m_li >= brep->m_L.Count() ||
	single_trim.FaceIndexOf() == first_chain_trim.FaceIndexOf() ||
	first_chain_trim.m_vi[1] != second_chain_trim.m_vi[0] ||
	first_chain_trim.m_vi[0] == first_chain_trim.m_vi[1] ||
	second_chain_trim.m_vi[0] == second_chain_trim.m_vi[1] ||
	first_chain_trim.m_vi[0] == second_chain_trim.m_vi[1])
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_BrepTrim *trims[3] = {
		&single_trim, &first_chain_trim, &second_chain_trim
	    };
	    const BooleanSourceEdgeUse *uses[3] = {
		&single_use, chain[0], chain[1]
	    };
	    const char *labels[3] = {"single", "chain first", "chain second"};
	    for (int trim_number = 0; trim_number < 3; ++trim_number) {
		const ON_BrepTrim &trim = *trims[trim_number];
		const int first_vertex = trim.m_vi[0];
		const int second_vertex = trim.m_vi[1];
		const ON_3dPoint first_point = first_vertex >= 0 &&
		    first_vertex < brep->m_V.Count() ?
		    brep->m_V[first_vertex].Point() : ON_3dPoint::UnsetPoint;
		const ON_3dPoint second_point = second_vertex >= 0 &&
		    second_vertex < brep->m_V.Count() ?
		    brep->m_V[second_vertex].Point() : ON_3dPoint::UnsetPoint;
		bu_log("  %s trim %d edge %d loop %d face %d reversed %d, "
		    "vertices %d/%d, points %.17g %.17g %.17g / "
		    "%.17g %.17g %.17g.\n", labels[trim_number],
		    uses[trim_number]->m_trim_index,
		    uses[trim_number]->m_edge_index, trim.m_li,
		    trim.FaceIndexOf(), trim.m_bRev3d, first_vertex,
		    second_vertex, first_point.x, first_point.y, first_point.z,
		    second_point.x, second_point.y, second_point.z);
	    }
	    const auto vertex_distance = [brep](int first, int second) {
		if (first < 0 || first >= brep->m_V.Count() || second < 0 ||
		    second >= brep->m_V.Count())
		{
		    return ON_UNSET_VALUE;
		}
		return brep->m_V[first].Point().DistanceTo(
		    brep->m_V[second].Point());
	    };
	    bu_log("  expected vertex-pair distances junction %.17g, "
		"single-start/chain-end %.17g, single-end/chain-start %.17g "
		"(tolerance %.17g).\n",
		vertex_distance(first_chain_trim.m_vi[1],
		    second_chain_trim.m_vi[0]),
		vertex_distance(single_trim.m_vi[0],
		    second_chain_trim.m_vi[1]),
		vertex_distance(single_trim.m_vi[1],
		    first_chain_trim.m_vi[0]), tolerance);
	}
	return skipped("trim topology does not form an opposite 1/2 chain");
    }

    const double first_source_start = first_chain_trim.m_bRev3d ?
	chain[0]->m_source_end : chain[0]->m_source_start;
    const double first_source_end = first_chain_trim.m_bRev3d ?
	chain[0]->m_source_start : chain[0]->m_source_end;
    const double second_source_start = second_chain_trim.m_bRev3d ?
	chain[1]->m_source_end : chain[1]->m_source_start;
    const double second_source_end = second_chain_trim.m_bRev3d ?
	chain[1]->m_source_start : chain[1]->m_source_end;
    const double single_source_start = single_trim.m_bRev3d ?
	single_use.m_source_end : single_use.m_source_start;
    const double single_source_end = single_trim.m_bRev3d ?
	single_use.m_source_start : single_use.m_source_end;
    const double source_tolerance = boolean_source_edge_normalized_tolerance(
	source_edge, tolerance);
    const double chain_direction = second_source_end > first_source_start ?
	1.0 : -1.0;
    const double strict_guard = 256.0 * ON_EPSILON * std::max(1.0,
	std::max(fabs(first_source_start), fabs(second_source_end)));
    const double first_progress = chain_direction *
	(first_source_end - first_source_start);
    const double second_progress = chain_direction *
	(second_source_end - second_source_start);
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean source-edge partition candidate intervals single %.17g "
	    "-> %.17g, chain %.17g -> %.17g / %.17g -> %.17g, "
	    "tolerance %.17g.\n", single_source_start, single_source_end,
	    first_source_start, first_source_end, second_source_start,
	    second_source_end, source_tolerance);
    }
    if (!(source_tolerance > 0.0) ||
	chain_direction * (second_source_end - first_source_start) <= strict_guard ||
	chain_direction * (first_source_end - first_source_start) <
	    -source_tolerance ||
	chain_direction * (second_source_end - second_source_start) <
	    -source_tolerance ||
	chain_direction * (single_source_end - single_source_start) >= -strict_guard ||
	fabs(first_source_end - second_source_start) > source_tolerance ||
	fabs(single_source_start - second_source_end) > source_tolerance ||
	fabs(single_source_end - first_source_start) > source_tolerance)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean source-edge partition intervals single %.17g -> "
		"%.17g, chain %.17g -> %.17g / %.17g -> %.17g, "
		"tolerance %.17g.\n",
		single_source_start, single_source_end, first_source_start,
		first_source_end, second_source_start, second_source_end,
		source_tolerance);
	}
	return skipped("source intervals do not form one full opposite traversal");
    }

    const ON_BrepEdge &single_edge = brep->m_E[single_use.m_edge_index];
    const ON_BrepEdge &first_chain_edge = brep->m_E[chain[0]->m_edge_index];
    const ON_BrepEdge &second_chain_edge = brep->m_E[chain[1]->m_edge_index];
    const ON_3dPoint single_start = single_trim.m_bRev3d ?
	single_edge.PointAtEnd() : single_edge.PointAtStart();
    const ON_3dPoint single_end = single_trim.m_bRev3d ?
	single_edge.PointAtStart() : single_edge.PointAtEnd();
    const ON_3dPoint chain_start = first_chain_trim.m_bRev3d ?
	first_chain_edge.PointAtEnd() : first_chain_edge.PointAtStart();
    const ON_3dPoint chain_junction_first = first_chain_trim.m_bRev3d ?
	first_chain_edge.PointAtStart() : first_chain_edge.PointAtEnd();
    const ON_3dPoint chain_junction_second = second_chain_trim.m_bRev3d ?
	second_chain_edge.PointAtEnd() : second_chain_edge.PointAtStart();
    const ON_3dPoint chain_end = second_chain_trim.m_bRev3d ?
	second_chain_edge.PointAtStart() : second_chain_edge.PointAtEnd();
    if (!single_start.IsValid() || !single_end.IsValid() ||
	!chain_start.IsValid() || !chain_junction_first.IsValid() ||
	!chain_junction_second.IsValid() || !chain_end.IsValid() ||
	single_start.DistanceTo(chain_end) > tolerance ||
	single_end.DistanceTo(chain_start) > tolerance ||
	chain_junction_first.DistanceTo(chain_junction_second) > tolerance)
    {
	return skipped("model-space endpoints do not match");
    }

    const bool first_backtracks = first_progress < -strict_guard;
    const bool second_backtracks = second_progress < -strict_guard;
    /* The ordinary one-to-two partition changes no vertices.  Duplicate
     * endpoint vertices require the separately certified spike-collapse
     * path above rather than silently relaxing this topology invariant. */
    const bool ordinary_topology =
	single_trim.m_vi[0] == second_chain_trim.m_vi[1] &&
	single_trim.m_vi[1] == first_chain_trim.m_vi[0];
    if (!ordinary_topology) {
	if (first_backtracks != second_backtracks) {
	    const bool residual_is_first = first_backtracks;
	    const double survivor_start = residual_is_first ?
		second_source_start : first_source_start;
	    const double survivor_end = residual_is_first ?
		second_source_end : first_source_end;
	    const double survivor_progress = residual_is_first ?
		second_progress : first_progress;
	    if (survivor_progress <= strict_guard ||
		fabs(single_source_start - survivor_end) > source_tolerance ||
		fabs(single_source_end - survivor_start) > source_tolerance)
	    {
		return skipped("backtracking chain has no full surviving traversal");
	    }
	    return repair_boolean_source_edge_endpoint_spike(brep, single_use,
		*chain[residual_is_first ? 0 : 1],
		*chain[residual_is_first ? 1 : 0], residual_is_first,
		tolerance);
	}
	return skipped("ordinary partition endpoints are not identical");
    }

    const int junction_vertex = first_chain_trim.m_vi[1];
    if (junction_vertex < 0 || junction_vertex >= brep->m_V.Count()) {
	return skipped("chain junction vertex is invalid");
    }
    const ON_3dPoint junction = brep->m_V[junction_vertex].Point();
    if (!junction.IsValid() ||
	junction.DistanceTo(chain_junction_first) > tolerance ||
	junction.DistanceTo(chain_junction_second) > tolerance)
    {
	return skipped("chain junction geometry is inconsistent");
    }

    double split_parameter = ON_UNSET_VALUE;
    if (!find_boolean_trim_lift_parameter(single_trim, junction, tolerance,
	    split_parameter))
    {
	return skipped("single trim has no interior lift parameter at the junction");
    }

    std::unique_ptr<ON_Curve> single_parameter_curve(
	single_trim.DuplicateCurve());
    ON_Curve *first_piece_raw = NULL;
    ON_Curve *second_piece_raw = NULL;
    if (!single_parameter_curve || !single_parameter_curve->Split(
	    split_parameter, first_piece_raw, second_piece_raw))
    {
	delete first_piece_raw;
	delete second_piece_raw;
	return skipped("single parameter curve could not be split");
    }
    std::unique_ptr<ON_Curve> pieces[2] = {
	std::unique_ptr<ON_Curve>(first_piece_raw),
	std::unique_ptr<ON_Curve>(second_piece_raw)
    };
    for (int piece = 0; piece < 2; ++piece) {
	std::unique_ptr<ON_NurbsCurve> detached(new ON_NurbsCurve());
	if (!pieces[piece] || pieces[piece]->GetNurbForm(*detached) <= 0 ||
	    !detached->IsValid())
	{
	    return skipped("a split parameter curve could not be detached");
	}
	pieces[piece].reset(detached.release());
    }

    const int replacement_edges[2] = {
	chain[1]->m_edge_index, chain[0]->m_edge_index
    };
    const bool replacement_reversed[2] = {
	!second_chain_trim.m_bRev3d, !first_chain_trim.m_bRev3d
    };
    const ON_Surface *single_surface = single_trim.SurfaceOf();
    const bool piece_follows[2] = {
	boolean_parameter_curve_follows_edge(single_surface, pieces[0].get(),
	    brep->m_E[replacement_edges[0]], replacement_reversed[0], tolerance),
	boolean_parameter_curve_follows_edge(single_surface, pieces[1].get(),
	    brep->m_E[replacement_edges[1]], replacement_reversed[1], tolerance)
    };
    if (!piece_follows[0] || !piece_follows[1])
    {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean source-edge partition split %.17g follows edges "
		"%d/%d: %d/%d (reversed %d/%d).\n", split_parameter,
		replacement_edges[0], replacement_edges[1], piece_follows[0],
		piece_follows[1], replacement_reversed[0],
		replacement_reversed[1]);
	    for (int piece = 0; piece < 2; ++piece) {
		const ON_3dPoint uv_start = pieces[piece]->PointAtStart();
		const ON_3dPoint uv_end = pieces[piece]->PointAtEnd();
		const ON_3dPoint lifted_start = single_surface->PointAt(
		    uv_start.x, uv_start.y);
		const ON_3dPoint lifted_end = single_surface->PointAt(
		    uv_end.x, uv_end.y);
		const ON_BrepEdge &replacement_edge =
		    brep->m_E[replacement_edges[piece]];
		const ON_3dPoint edge_start = replacement_reversed[piece] ?
		    replacement_edge.PointAtEnd() : replacement_edge.PointAtStart();
		const ON_3dPoint edge_end = replacement_reversed[piece] ?
		    replacement_edge.PointAtStart() : replacement_edge.PointAtEnd();
		bu_log("  piece %d endpoint distances %.17g/%.17g.\n", piece,
		    lifted_start.DistanceTo(edge_start),
		    lifted_end.DistanceTo(edge_end));
	    }
	}
	return skipped("a split parameter curve does not follow its chain edge");
    }

    const int naked_before = boolean_active_naked_edge_count(brep);
    const int edge_count_before = brep->m_E.Count();
    const int trim_count_before = brep->m_T.Count();
    const int face_count_before = brep->m_F.Count();
    const int loop_count_before = brep->m_L.Count();
    const int surface_count_before = brep->m_S.Count();
    const int vertex_count_before = brep->m_V.Count();
    const int old_trim_index = single_use.m_trim_index;
    const int old_edge_index = single_use.m_edge_index;
    const int old_loop_index = single_trim.m_li;
    const double old_trim_tolerance[2] = {
	single_trim.m_tolerance[0], single_trim.m_tolerance[1]
    };
    std::vector<int> old_loop_trims(
	brep->m_L[old_loop_index].m_ti.Array(),
	brep->m_L[old_loop_index].m_ti.Array() +
	brep->m_L[old_loop_index].m_ti.Count());
    ON_Brep rollback(*brep);

    std::vector<int> new_trim_indices;
    bool installed = true;
    for (int piece = 0; piece < 2 && installed; ++piece) {
	const int curve_index = brep->AddTrimCurve(pieces[piece].release());
	if (curve_index < 0 || replacement_edges[piece] < 0 ||
	    replacement_edges[piece] >= brep->m_E.Count())
	{
	    installed = false;
	    break;
	}
	ON_BrepTrim &created = brep->NewTrim(
	    brep->m_E[replacement_edges[piece]], replacement_reversed[piece],
	    brep->m_L[old_loop_index], curve_index);
	if (created.m_trim_index < 0) {
	    installed = false;
	    break;
	}
	created.m_type = ON_BrepTrim::mated;
	created.m_tolerance[0] = old_trim_tolerance[0];
	created.m_tolerance[1] = old_trim_tolerance[1];
	const ON_Surface *created_surface = created.SurfaceOf();
	const ON_Interval created_domain = created.Domain();
	if (created_surface == NULL) {
	    installed = false;
	    break;
	}
	created.m_iso = created_surface->IsIsoparametric(created,
	    &created_domain);
	new_trim_indices.push_back(created.m_trim_index);
    }
    if (!installed || new_trim_indices.size() != 2) {
	*brep = rollback;
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    brep->m_T[chain[0]->m_trim_index].m_type = ON_BrepTrim::mated;
    brep->m_T[chain[1]->m_trim_index].m_type = ON_BrepTrim::mated;
    ON_BrepLoop &replacement_loop = brep->m_L[old_loop_index];
    replacement_loop.m_ti.SetCount(0);
    bool old_trim_replaced = false;
    for (std::vector<int>::const_iterator trim = old_loop_trims.begin();
	 trim != old_loop_trims.end(); ++trim)
    {
	if (*trim != old_trim_index) {
	    replacement_loop.m_ti.Append(*trim);
	    brep->m_T[*trim].m_li = old_loop_index;
	    continue;
	}
	if (old_trim_replaced) {
	    installed = false;
	    break;
	}
	for (std::vector<int>::const_iterator replacement =
		new_trim_indices.begin(); replacement != new_trim_indices.end();
	     ++replacement)
	{
	    replacement_loop.m_ti.Append(*replacement);
	    brep->m_T[*replacement].m_li = old_loop_index;
	}
	old_trim_replaced = true;
    }
    if (!installed || !old_trim_replaced) {
	*brep = rollback;
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    brep->DeleteTrim(brep->m_T[old_trim_index], false);
    brep->DeleteEdge(brep->m_E[old_edge_index], false);
    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    const bool compacted = brep->Compact();
    const bool trim_types_set = compacted && brep->SetTrimTypeFlags(false);
    const bool vertex_tolerances_set = trim_types_set &&
	brep->SetVertexTolerances(false);
    const bool edge_tolerances_set = vertex_tolerances_set &&
	set_boolean_edge_tolerances(brep);
    const bool trim_tolerances_set = edge_tolerances_set &&
	set_boolean_trim_tolerances(brep);
    const bool valid = trim_tolerances_set && brep->IsValid(&validation_log);
    const int naked_after = boolean_active_naked_edge_count(brep);
    if (!valid || naked_before < 3 || naked_after != naked_before - 3 ||
	brep->m_E.Count() != edge_count_before - 1 ||
	brep->m_T.Count() != trim_count_before + 1 ||
	brep->m_F.Count() != face_count_before ||
	brep->m_L.Count() != loop_count_before ||
	brep->m_S.Count() != surface_count_before ||
	brep->m_V.Count() != vertex_count_before)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_String message(validation_text);
	    bu_log("Boolean source-edge partition repair rolled back: valid %d, "
		"naked %d -> %d, edges %d -> %d, trims %d -> %d%s%s.\n",
		valid, naked_before, naked_after, edge_count_before,
		brep->m_E.Count(), trim_count_before, brep->m_T.Count(),
		message.Array() && message.Array()[0] ? ": " : "",
		message.Array() ? message.Array() : "");
	    for (int edge_index = 0; edge_index < brep->m_E.Count();
		 ++edge_index)
	    {
		ON_wString edge_validation_text;
		ON_TextLog edge_validation_log(edge_validation_text);
		if (!brep->IsValidEdge(edge_index, &edge_validation_log)) {
		    const ON_BrepEdge &edge = brep->m_E[edge_index];
		    const ON_String edge_message(edge_validation_text);
		    bu_log("  invalid edge %d vertices %d/%d curve %d trims %d: %s",
			edge_index, edge.m_vi[0], edge.m_vi[1], edge.m_c3i,
			edge.m_ti.Count(), edge_message.Array() ?
			edge_message.Array() : "");
		}
	    }
	}
	*brep = rollback;
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static SharedSSIEdgeRepairResult
collapse_boolean_partition_connector(
    ON_Brep &brep,
    int keep_vertex,
    int remove_vertex,
    const std::set<int> &partition_edges,
    double tolerance)
{
    if (keep_vertex == remove_vertex) {
	return SHARED_SSI_EDGE_REPAIR_COMPLETE;
    }
    if (keep_vertex < 0 || keep_vertex >= brep.m_V.Count() ||
	remove_vertex < 0 || remove_vertex >= brep.m_V.Count() ||
	!(tolerance > 0.0) || !std::isfinite(tolerance))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    int connector_edge_index = -1;
    for (int edge_index = 0; edge_index < brep.m_E.Count(); ++edge_index) {
	if (partition_edges.find(edge_index) != partition_edges.end() ||
	    !is_active_boolean_naked_edge(&brep, edge_index))
	{
	    continue;
	}
	const ON_BrepEdge &edge = brep.m_E[edge_index];
	if (!((edge.m_vi[0] == keep_vertex &&
	       edge.m_vi[1] == remove_vertex) ||
	      (edge.m_vi[1] == keep_vertex && edge.m_vi[0] == remove_vertex)))
	{
	    continue;
	}
	if (connector_edge_index >= 0) {
	    return SHARED_SSI_EDGE_REPAIR_SKIPPED;
	}
	connector_edge_index = edge_index;
    }
    if (connector_edge_index < 0 ||
	boolean_vertex_pair_has_other_edge(&brep, keep_vertex, remove_vertex,
	    connector_edge_index))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const ON_BrepEdge &connector = brep.m_E[connector_edge_index];
    const ON_3dPoint collapse_center = brep.m_V[keep_vertex].Point();
    const ON_3dPoint removed_point = brep.m_V[remove_vertex].Point();
    const ON_BoundingBox connector_bounds = connector.BoundingBox();
    if (!collapse_center.IsValid() || !removed_point.IsValid() ||
	!connector_bounds.IsValid() ||
	removed_point.DistanceTo(collapse_center) > tolerance ||
	connector_bounds.Diagonal().Length() > tolerance ||
	!brep_curve_locus_within_ball(connector, collapse_center, tolerance))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const int connector_trim_index = connector.m_ti[0];
    const int previous_trim_index = brep.PrevTrim(connector_trim_index);
    const int next_trim_index = brep.NextTrim(connector_trim_index);
    if (previous_trim_index < 0 || next_trim_index < 0 ||
	previous_trim_index == next_trim_index)
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const double separation = collapse_center.DistanceTo(removed_point);
    brep.m_V[keep_vertex].m_tolerance = std::max(
	brep.m_V[keep_vertex].m_tolerance, separation);
    if (!brep.CollapseEdge(connector_edge_index, false, keep_vertex) ||
	!close_boolean_endpoint_spike_gap(brep, previous_trim_index,
	    next_trim_index, true, collapse_center, tolerance))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean source-edge full partition collapsed connector edge %d "
	    "between vertices %d/%d at tolerance %.17g.\n",
	    connector_edge_index, keep_vertex, remove_vertex, tolerance);
    }
    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static SharedSSIEdgeRepairResult
merge_boolean_partition_endpoint_vertices(
    ON_Brep &brep,
    int keep_vertex,
    int remove_vertex,
    double tolerance)
{
    if (keep_vertex == remove_vertex) {
	return SHARED_SSI_EDGE_REPAIR_COMPLETE;
    }
    if (keep_vertex < 0 || keep_vertex >= brep.m_V.Count() ||
	remove_vertex < 0 || remove_vertex >= brep.m_V.Count() ||
	!(tolerance > 0.0) || !std::isfinite(tolerance) ||
	boolean_vertex_pair_has_other_edge(&brep, keep_vertex, remove_vertex,
	    -1))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const ON_3dPoint keep_point = brep.m_V[keep_vertex].Point();
    const ON_3dPoint remove_point = brep.m_V[remove_vertex].Point();
    const double separation = keep_point.DistanceTo(remove_point);
    if (!keep_point.IsValid() || !remove_point.IsValid() ||
	!std::isfinite(separation) || separation > tolerance ||
	!combine_boolean_vertices(brep, keep_vertex, remove_vertex, tolerance))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean source-edge full partition merged endpoint vertices "
	    "%d/%d separated by %.17g at tolerance %.17g.\n",
	    keep_vertex, remove_vertex, separation, tolerance);
    }
    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static SharedSSIEdgeRepairResult
repair_boolean_source_edge_full_partition(
    ON_Brep *brep,
    const ON_BrepEdge &source_edge,
    const std::vector<BooleanSourceEdgeUse> &single_uses,
    const std::vector<BooleanSourceEdgeUse> &chain_uses,
    double tolerance,
    bool allow_connector_collapse = true)
{
    const auto skipped = [](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean source-edge full partition skipped: %s.\n", reason);
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    };

    if (brep == NULL || single_uses.size() != 1 || chain_uses.size() < 2) {
	return skipped("candidate cardinality changed");
    }

    const BooleanSourceEdgeUse &single_use = single_uses[0];
    const bool single_is_open = is_active_boolean_naked_edge(brep,
	single_use.m_edge_index);
    const bool single_is_closed = is_active_boolean_closed_naked_edge(brep,
	single_use.m_edge_index);
    if ((!single_is_open && !single_is_closed) ||
	single_use.m_trim_index < 0 ||
	single_use.m_trim_index >= brep->m_T.Count())
    {
	return skipped("single candidate is no longer a naked edge");
    }

    const ON_BrepEdge &single_edge = brep->m_E[single_use.m_edge_index];
    const ON_BrepTrim &single_trim = brep->m_T[single_use.m_trim_index];
    const int single_face_index = single_trim.FaceIndexOf();
    if (single_trim.m_trim_index != single_use.m_trim_index ||
	single_trim.m_li < 0 || single_trim.m_li >= brep->m_L.Count() ||
	single_face_index < 0 || single_face_index >= brep->m_F.Count() ||
	single_trim.m_vi[0] < 0 || single_trim.m_vi[1] < 0 ||
	(single_trim.m_vi[0] == single_trim.m_vi[1]) != single_is_closed ||
	single_trim.m_vi[0] != single_edge.m_vi[0] ||
	single_trim.m_vi[1] != single_edge.m_vi[1])
    {
	return skipped("single trim topology is invalid");
    }

    const double source_tolerance = boolean_source_edge_normalized_tolerance(
	source_edge, tolerance);
    const double parameter_scale = std::max(1.0,
	std::max(fabs(single_use.m_source_start),
	    fabs(single_use.m_source_end)));
    const double strict_guard = 256.0 * ON_EPSILON * parameter_scale;
    if (!(source_tolerance > 0.0) || !std::isfinite(source_tolerance)) {
	return skipped("source tolerance is invalid");
    }

    std::vector<const BooleanSourceEdgeUse *> chain;
    chain.reserve(chain_uses.size());
    std::set<int> edge_indices;
    std::set<int> trim_indices;
    edge_indices.insert(single_use.m_edge_index);
    trim_indices.insert(single_use.m_trim_index);
    double chain_direction = 0.0;
    double chain_effective_direction = 0.0;
    for (const BooleanSourceEdgeUse &use : chain_uses) {
	if (!is_active_boolean_naked_edge(brep, use.m_edge_index) ||
	    use.m_trim_index < 0 || use.m_trim_index >= brep->m_T.Count() ||
	    !edge_indices.insert(use.m_edge_index).second ||
	    !trim_indices.insert(use.m_trim_index).second)
	{
	    return skipped("chain candidates are not distinct naked edges");
	}

	const ON_BrepTrim &trim = brep->m_T[use.m_trim_index];
	const int face_index = trim.FaceIndexOf();
	if (trim.m_trim_index != use.m_trim_index || trim.m_vi[0] < 0 ||
	    trim.m_vi[1] < 0 || trim.m_vi[0] == trim.m_vi[1] ||
	    face_index < 0 || face_index >= brep->m_F.Count() ||
	    face_index == single_face_index)
	{
	    return skipped("chain trim topology is invalid");
	}
	const double start = trim.m_bRev3d ? use.m_source_end :
	    use.m_source_start;
	const double end = trim.m_bRev3d ? use.m_source_start :
	    use.m_source_end;
	if (!std::isfinite(start) || !std::isfinite(end) ||
	    fabs(end - start) <= strict_guard)
	{
	    return skipped("a chain source interval is degenerate");
	}
	const double direction = end > start ? 1.0 : -1.0;
	const double effective_direction = brep->m_F[face_index].m_bRev ?
	    -direction : direction;
	if (chain_direction == 0.0) {
	    chain_direction = direction;
	} else if (direction != chain_direction) {
	    return skipped("chain source intervals have inconsistent directions");
	}
	if (chain_effective_direction == 0.0) {
	    chain_effective_direction = effective_direction;
	} else if (effective_direction != chain_effective_direction) {
	    return skipped("chain faces have inconsistent effective directions");
	}
	chain.push_back(&use);
    }

    std::sort(chain.begin(), chain.end(),
	[brep, chain_direction](const BooleanSourceEdgeUse *first,
	    const BooleanSourceEdgeUse *second) {
	    const ON_BrepTrim &first_trim = brep->m_T[first->m_trim_index];
	    const ON_BrepTrim &second_trim = brep->m_T[second->m_trim_index];
	    const double first_start = first_trim.m_bRev3d ?
		first->m_source_end : first->m_source_start;
	    const double second_start = second_trim.m_bRev3d ?
		second->m_source_end : second->m_source_start;
	    return chain_direction * first_start < chain_direction * second_start;
	});

    std::vector<double> chain_starts;
    std::vector<double> chain_ends;
    chain_starts.reserve(chain.size());
    chain_ends.reserve(chain.size());
    for (size_t chain_index = 0; chain_index < chain.size(); ++chain_index) {
	const BooleanSourceEdgeUse &use = *chain[chain_index];
	const ON_BrepTrim &trim = brep->m_T[use.m_trim_index];
	const double start = trim.m_bRev3d ? use.m_source_end :
	    use.m_source_start;
	const double end = trim.m_bRev3d ? use.m_source_start :
	    use.m_source_end;
	if (chain_direction * (end - start) <= strict_guard) {
	    return skipped("a sorted chain interval does not make progress");
	}
	if (chain_index > 0) {
	    if (fabs(chain_ends.back() - start) > source_tolerance)
	    {
		return skipped("chain intervals are not contiguous");
	    }
	}
	chain_starts.push_back(start);
	chain_ends.push_back(end);
    }

    const double single_source_start = single_trim.m_bRev3d ?
	single_use.m_source_end : single_use.m_source_start;
    const double single_source_end = single_trim.m_bRev3d ?
	single_use.m_source_start : single_use.m_source_end;
    const double single_progress = single_source_end - single_source_start;
    if (!std::isfinite(single_source_start) ||
	!std::isfinite(single_source_end) ||
	fabs(single_progress) <= strict_guard)
    {
	return skipped("single source interval is degenerate");
    }
    const double single_direction = single_progress > 0.0 ? 1.0 : -1.0;
    const double single_effective_direction =
	brep->m_F[single_face_index].m_bRev ?
	-single_direction : single_direction;
    if (single_effective_direction != -chain_effective_direction) {
	return skipped("partition has matching effective face directions");
    }

    /* Raw trim traversal can match when the two result faces have opposite
     * m_bRev values.  The topological seam condition is opposite effective
     * face traversal, while raw traversal determines the order in which the
     * single trim's parameter curve must be split and attached. */
    const bool same_traversal = single_direction == chain_direction;
    const double chain_match_start = same_traversal ?
	chain_starts.front() : chain_ends.back();
    const double chain_match_end = same_traversal ?
	chain_ends.back() : chain_starts.front();
    if (!std::isfinite(single_source_start) ||
	!std::isfinite(single_source_end) ||
	fabs(single_source_start - chain_match_start) > source_tolerance ||
	fabs(single_source_end - chain_match_end) > source_tolerance)
    {
	return skipped("source intervals do not form one full opposite traversal");
    }

    const ON_BrepTrim &first_chain_trim =
	brep->m_T[chain.front()->m_trim_index];
    const ON_BrepTrim &last_chain_trim =
	brep->m_T[chain.back()->m_trim_index];
    const int chain_start_vertex = same_traversal ?
	first_chain_trim.m_vi[0] : last_chain_trim.m_vi[1];
    const int chain_end_vertex = same_traversal ?
	last_chain_trim.m_vi[1] : first_chain_trim.m_vi[0];
    bool chain_topology_matches = single_is_closed ?
	(chain_start_vertex == chain_end_vertex &&
	 single_trim.m_vi[0] == chain_start_vertex) :
	(single_trim.m_vi[0] == chain_start_vertex &&
	 single_trim.m_vi[1] == chain_end_vertex);
    for (size_t chain_index = 1;
	 chain_index < chain.size() && chain_topology_matches; ++chain_index)
    {
	const ON_BrepTrim &previous =
	    brep->m_T[chain[chain_index - 1]->m_trim_index];
	const ON_BrepTrim &current =
	    brep->m_T[chain[chain_index]->m_trim_index];
	chain_topology_matches = previous.m_vi[1] == current.m_vi[0];
    }
    if (!chain_topology_matches && allow_connector_collapse) {
	ON_Brep normalized(*brep);
	bool collapsed = false;
	for (size_t chain_index = 1; chain_index < chain.size(); ++chain_index) {
	    const ON_BrepTrim &previous = normalized.m_T[
		chain[chain_index - 1]->m_trim_index];
	    const ON_BrepTrim &current = normalized.m_T[
		chain[chain_index]->m_trim_index];
	    if (previous.m_vi[1] == current.m_vi[0]) {
		continue;
	    }
	    if (collapse_boolean_partition_connector(normalized,
		    previous.m_vi[1], current.m_vi[0], edge_indices,
		    tolerance) != SHARED_SSI_EDGE_REPAIR_COMPLETE)
	    {
		return skipped("chain vertex gap has no certified connector");
	    }
	    collapsed = true;
	}

	const ON_BrepTrim &normalized_single =
	    normalized.m_T[single_use.m_trim_index];
	const ON_BrepTrim &normalized_first =
	    normalized.m_T[chain.front()->m_trim_index];
	const ON_BrepTrim &normalized_last =
	    normalized.m_T[chain.back()->m_trim_index];
	const int normalized_chain_start = same_traversal ?
	    normalized_first.m_vi[0] : normalized_last.m_vi[1];
	const int normalized_chain_end = same_traversal ?
	    normalized_last.m_vi[1] : normalized_first.m_vi[0];
	if (!single_is_closed && normalized_single.m_vi[0] !=
		normalized_chain_start)
	{
	    const int single_start_vertex = normalized_single.m_vi[0];
	    SharedSSIEdgeRepairResult endpoint_result =
		collapse_boolean_partition_connector(normalized,
		    single_start_vertex, normalized_chain_start, edge_indices,
		    tolerance);
	    if (endpoint_result != SHARED_SSI_EDGE_REPAIR_COMPLETE) {
		endpoint_result = merge_boolean_partition_endpoint_vertices(
		    normalized, single_start_vertex, normalized_chain_start,
		    tolerance);
	    }
	    if (endpoint_result != SHARED_SSI_EDGE_REPAIR_COMPLETE)
	    {
		return skipped("partition start gap cannot be certified and merged");
	    }
	    collapsed = true;
	}
	const ON_BrepTrim &updated_single =
	    normalized.m_T[single_use.m_trim_index];
	const ON_BrepTrim &updated_first =
	    normalized.m_T[chain.front()->m_trim_index];
	const ON_BrepTrim &updated_last =
	    normalized.m_T[chain.back()->m_trim_index];
	const int updated_chain_end = same_traversal ?
	    updated_last.m_vi[1] : updated_first.m_vi[0];
	if (!single_is_closed && updated_single.m_vi[1] != updated_chain_end) {
	    const int single_end_vertex = updated_single.m_vi[1];
	    SharedSSIEdgeRepairResult endpoint_result =
		collapse_boolean_partition_connector(normalized,
		    single_end_vertex, updated_chain_end, edge_indices,
		    tolerance);
	    if (endpoint_result != SHARED_SSI_EDGE_REPAIR_COMPLETE) {
		endpoint_result = merge_boolean_partition_endpoint_vertices(
		    normalized, single_end_vertex, updated_chain_end, tolerance);
	    }
	    if (endpoint_result != SHARED_SSI_EDGE_REPAIR_COMPLETE)
	    {
		return skipped("partition end gap cannot be certified and merged");
	    }
	    collapsed = true;
	}
	if (collapsed) {
	    const SharedSSIEdgeRepairResult normalized_result =
		repair_boolean_source_edge_full_partition(&normalized,
		    source_edge, single_uses, chain_uses, tolerance, false);
	    if (normalized_result == SHARED_SSI_EDGE_REPAIR_COMPLETE) {
		*brep = normalized;
	    }
	    return normalized_result;
	}
    }
    if (single_is_closed) {
	if (chain_start_vertex != chain_end_vertex ||
	    single_trim.m_vi[0] != chain_start_vertex)
	{
	    return skipped("closed partition endpoints are not identical");
	}
    } else if (single_trim.m_vi[0] != chain_start_vertex ||
	single_trim.m_vi[1] != chain_end_vertex)
    {
	return skipped("partition endpoints are not identical");
    }

    std::vector<double> split_parameters;
    split_parameters.reserve(chain.size() - 1);
    const ON_Interval single_domain = single_trim.Domain();
    if (!single_domain.IsIncreasing()) {
	return skipped("single trim domain is invalid");
    }
    const double domain_guard = std::max(ON_ZERO_TOLERANCE,
	single_domain.Length() * 1.0e-10);
    const auto chain_index_for_piece = [&chain, same_traversal](size_t piece) {
	return same_traversal ? piece : chain.size() - 1 - piece;
    };
    double previous_parameter = single_domain.Min();
    for (size_t piece = 0; piece + 1 < chain.size(); ++piece) {
	const size_t chain_index = chain_index_for_piece(piece);
	const ON_BrepTrim &replacement_trim =
	    brep->m_T[chain[chain_index]->m_trim_index];
	const int junction_vertex = same_traversal ?
	    replacement_trim.m_vi[1] : replacement_trim.m_vi[0];
	if (junction_vertex < 0 || junction_vertex >= brep->m_V.Count()) {
	    return skipped("chain junction vertex is invalid");
	}
	double split_parameter = ON_UNSET_VALUE;
	if (!find_boolean_trim_lift_parameter(single_trim,
		brep->m_V[junction_vertex].Point(), tolerance,
		split_parameter) ||
	    split_parameter <= previous_parameter + domain_guard ||
	    split_parameter >= single_domain.Max() - domain_guard)
	{
	    return skipped("single trim split parameters are not ordered");
	}
	split_parameters.push_back(split_parameter);
	previous_parameter = split_parameter;
    }

    std::vector<std::unique_ptr<ON_Curve> > pieces;
    pieces.reserve(chain.size());
    std::unique_ptr<ON_Curve> remaining(single_trim.DuplicateCurve());
    if (!remaining) {
	return skipped("single parameter curve could not be duplicated");
    }
    for (double split_parameter : split_parameters) {
	ON_Curve *first_piece = NULL;
	ON_Curve *remainder = NULL;
	if (!remaining->Split(split_parameter, first_piece, remainder) ||
	    first_piece == NULL || remainder == NULL)
	{
	    delete first_piece;
	    delete remainder;
	    return skipped("single parameter curve could not be split");
	}
	pieces.push_back(std::unique_ptr<ON_Curve>(first_piece));
	remaining.reset(remainder);
    }
    pieces.push_back(std::move(remaining));
    if (pieces.size() != chain.size()) {
	return skipped("single parameter curve produced the wrong piece count");
    }

    for (size_t piece = 0; piece < pieces.size(); ++piece) {
	std::unique_ptr<ON_NurbsCurve> detached(new ON_NurbsCurve());
	if (!pieces[piece] || pieces[piece]->GetNurbForm(*detached) <= 0 ||
	    !detached->IsValid())
	{
	    return skipped("a split parameter curve could not be detached");
	}
	pieces[piece].reset(detached.release());
    }

    const ON_Surface *single_surface = single_trim.SurfaceOf();
    if (single_surface == NULL) {
	return skipped("single trim has no surface");
    }
    for (size_t piece = 0; piece < pieces.size(); ++piece) {
	const BooleanSourceEdgeUse &replacement =
	    *chain[chain_index_for_piece(piece)];
	const ON_BrepTrim &replacement_trim =
	    brep->m_T[replacement.m_trim_index];
	const bool replacement_reversed = same_traversal ?
	    replacement_trim.m_bRev3d : !replacement_trim.m_bRev3d;
	const int replacement_face_index = replacement_trim.FaceIndexOf();
	const bool created_effective_reversed = replacement_reversed ^
	    brep->m_F[single_face_index].m_bRev;
	const bool replacement_effective_reversed =
	    replacement_trim.m_bRev3d ^
	    brep->m_F[replacement_face_index].m_bRev;
	if (created_effective_reversed == replacement_effective_reversed) {
	    return skipped("replacement trims do not have opposite effective directions");
	}
	if (!boolean_parameter_curve_follows_edge(single_surface,
		pieces[piece].get(), brep->m_E[replacement.m_edge_index],
		replacement_reversed, tolerance))
	{
	    return skipped("a split parameter curve does not follow its chain edge");
	}
    }

    const int naked_before = boolean_active_naked_edge_count(brep);
    /* Connector normalization intentionally leaves deleted topology slots in
     * the transactional copy until the completed partition is compacted.
     * Count live entries here so those already-certified deletions are not
     * mistaken for changes made by the partition replacement itself. */
    int edge_count_before = 0;
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	if (brep->m_E[edge_index].m_edge_index == edge_index) {
	    ++edge_count_before;
	}
    }
    int trim_count_before = 0;
    for (int trim_index = 0; trim_index < brep->m_T.Count(); ++trim_index) {
	if (brep->m_T[trim_index].m_trim_index == trim_index) {
	    ++trim_count_before;
	}
    }
    const int face_count_before = brep->m_F.Count();
    const int loop_count_before = brep->m_L.Count();
    const int surface_count_before = brep->m_S.Count();
    int vertex_count_before = 0;
    for (int vertex_index = 0; vertex_index < brep->m_V.Count();
	 ++vertex_index)
    {
	if (brep->m_V[vertex_index].m_vertex_index == vertex_index) {
	    ++vertex_count_before;
	}
    }
    const int old_trim_index = single_use.m_trim_index;
    const int old_edge_index = single_use.m_edge_index;
    const int old_loop_index = single_trim.m_li;
    const double old_trim_tolerance[2] = {
	single_trim.m_tolerance[0], single_trim.m_tolerance[1]
    };
    std::vector<int> old_loop_trims(
	brep->m_L[old_loop_index].m_ti.Array(),
	brep->m_L[old_loop_index].m_ti.Array() +
	brep->m_L[old_loop_index].m_ti.Count());
    ON_Brep repaired(*brep);

    std::vector<int> new_trim_indices;
    new_trim_indices.reserve(pieces.size());
    bool installed = true;
    for (size_t piece = 0; piece < pieces.size() && installed; ++piece) {
	const BooleanSourceEdgeUse &replacement =
	    *chain[chain_index_for_piece(piece)];
	const ON_BrepTrim &replacement_trim =
	    brep->m_T[replacement.m_trim_index];
	const bool replacement_reversed = same_traversal ?
	    replacement_trim.m_bRev3d : !replacement_trim.m_bRev3d;
	const int curve_index = repaired.AddTrimCurve(pieces[piece].release());
	if (curve_index < 0 || replacement.m_edge_index < 0 ||
	    replacement.m_edge_index >= repaired.m_E.Count())
	{
	    installed = false;
	    break;
	}
	ON_BrepTrim &created = repaired.NewTrim(
	    repaired.m_E[replacement.m_edge_index],
	    replacement_reversed, repaired.m_L[old_loop_index],
	    curve_index);
	if (created.m_trim_index < 0) {
	    installed = false;
	    break;
	}
	created.m_type = ON_BrepTrim::mated;
	created.m_tolerance[0] = old_trim_tolerance[0];
	created.m_tolerance[1] = old_trim_tolerance[1];
	const ON_Surface *created_surface = created.SurfaceOf();
	const ON_Interval created_domain = created.Domain();
	if (created_surface == NULL) {
	    installed = false;
	    break;
	}
	created.m_iso = created_surface->IsIsoparametric(created,
	    &created_domain);
	new_trim_indices.push_back(created.m_trim_index);
    }
    if (!installed || new_trim_indices.size() != chain.size()) {
	return skipped("replacement trims could not be installed");
    }

    for (const BooleanSourceEdgeUse *use : chain) {
	repaired.m_T[use->m_trim_index].m_type = ON_BrepTrim::mated;
    }
    ON_BrepLoop &replacement_loop = repaired.m_L[old_loop_index];
    replacement_loop.m_ti.SetCount(0);
    bool old_trim_replaced = false;
    for (int trim_index : old_loop_trims) {
	if (trim_index != old_trim_index) {
	    replacement_loop.m_ti.Append(trim_index);
	    repaired.m_T[trim_index].m_li = old_loop_index;
	    continue;
	}
	if (old_trim_replaced) {
	    return skipped("single trim occurs more than once in its loop");
	}
	for (int new_trim_index : new_trim_indices) {
	    replacement_loop.m_ti.Append(new_trim_index);
	    repaired.m_T[new_trim_index].m_li = old_loop_index;
	}
	old_trim_replaced = true;
    }
    if (!old_trim_replaced) {
	return skipped("single trim is absent from its loop");
    }

    repaired.DeleteTrim(repaired.m_T[old_trim_index], false);
    repaired.DeleteEdge(repaired.m_E[old_edge_index], false);
    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    const bool compacted = repaired.Compact();
    if (compacted) {
	repaired.SetTrimBoundingBoxes(false);
    }
    const bool trim_iso_flags_set = compacted && repaired.SetTrimIsoFlags();
    const bool trim_types_set = trim_iso_flags_set &&
	repaired.SetTrimTypeFlags(false);
    const bool vertex_tolerances_set = trim_types_set &&
	repaired.SetVertexTolerances(false);
    const bool edge_tolerances_set = vertex_tolerances_set &&
	set_boolean_edge_tolerances(&repaired);
    const bool trim_tolerances_set = edge_tolerances_set &&
	set_boolean_trim_tolerances(&repaired);
    const bool valid = trim_tolerances_set && repaired.IsValid(&validation_log);
    const int naked_after = boolean_active_naked_edge_count(&repaired);
    const int expected_naked = naked_before -
	static_cast<int>(chain.size()) - (single_is_closed ? 0 : 1);
    const int expected_trim_count = trim_count_before +
	static_cast<int>(chain.size()) - 1;
    if (!valid || naked_before < static_cast<int>(chain.size()) +
	    (single_is_closed ? 0 : 1) ||
	naked_after != expected_naked ||
	repaired.m_E.Count() != edge_count_before - 1 ||
	repaired.m_T.Count() != expected_trim_count ||
	repaired.m_F.Count() != face_count_before ||
	repaired.m_L.Count() != loop_count_before ||
	repaired.m_S.Count() != surface_count_before ||
	repaired.m_V.Count() != vertex_count_before)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_String message(validation_text);
	    bu_log("Boolean source-edge full partition rolled back: valid %d, "
		"naked %d -> %d (expected %d), edges %d -> %d, trims %d "
		"-> %d (expected %d)%s%s.\n", valid, naked_before,
		naked_after, expected_naked, edge_count_before,
		repaired.m_E.Count(), trim_count_before, repaired.m_T.Count(),
		expected_trim_count,
		message.Array() && message.Array()[0] ? ": " : "",
		message.Array() ? message.Array() : "");
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    *brep = repaired;
    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


/*
 * A coincident result seam may be assembled from source edges belonging to
 * different operands.  In that case source-edge provenance cannot expose the
 * partition, even though the output itself contains one naked edge opposite a
 * vertex-contiguous chain of naked edges.  Use the single result edge as the
 * reference curve and reuse the fully certified source-edge partition repair.
 *
 * This is deliberately conservative: candidates must project monotonically
 * onto the reference edge within the model repair tolerance, lie inside its
 * normalized span, and have the opposite effective face traversal.  The
 * repair routine then independently verifies complete interval coverage,
 * identical chain vertices, split-curve lift agreement, topology counts, and
 * full B-Rep validity before committing its copy.
 */
static bool
boolean_edges_share_open_ssi_provenance(
    const ON_Brep *brep,
    int first_edge_index,
    int second_edge_index,
    const ON_ClassArray<SharedSSICurve> &shared_curves)
{
    if (brep == NULL || first_edge_index == second_edge_index) {
	return false;
    }

    bool shared_face_pair = false;
    for (int curve_index = 0; curve_index < shared_curves.Count();
	 ++curve_index)
    {
	const SharedSSICurve &shared_curve = shared_curves[curve_index];
	if (shared_curve.m_curve == NULL || shared_curve.m_curve->IsClosed()) {
	    continue;
	}

	const bool first_on_first = is_shared_ssi_edge_candidate(brep,
	    first_edge_index, shared_curve.m_face_index[0]);
	const bool first_on_second = is_shared_ssi_edge_candidate(brep,
	    first_edge_index, shared_curve.m_face_index[1]);
	const bool second_on_first = is_shared_ssi_edge_candidate(brep,
	    second_edge_index, shared_curve.m_face_index[0]);
	const bool second_on_second = is_shared_ssi_edge_candidate(brep,
	    second_edge_index, shared_curve.m_face_index[1]);
	if ((first_on_first && second_on_second) ||
	    (first_on_second && second_on_first))
	{
	    shared_face_pair = true;
	}

	if ((first_on_first && second_on_second &&
	     shared_ssi_edge_matches_parameter_curve(brep, first_edge_index,
		 shared_curve, 0) &&
	     shared_ssi_edge_matches_parameter_curve(brep, second_edge_index,
		 shared_curve, 1)) ||
	    (first_on_second && second_on_first &&
	     shared_ssi_edge_matches_parameter_curve(brep, first_edge_index,
		 shared_curve, 1) &&
	     shared_ssi_edge_matches_parameter_curve(brep, second_edge_index,
		 shared_curve, 0)))
	{
	    return true;
	}
    }

    /* Periodic seam repair can slightly shorten a parameter curve before
     * topology reconciliation.  The source-face pair still supplies SSI
	 * provenance; callers must additionally certify complete bidirectional
	 * model-space coverage before changing topology. */
    return shared_face_pair;
}


struct BooleanNakedEdgePartitionEvidence {
    int reference_edge_index = -1;
    int peer_edge_index = -1;
    int reference_face_index = -1;
    int peer_face_index = -1;
    double tolerance = 0.0;
};


static SharedSSIEdgeRepairResult
repair_boolean_closed_edge_partial_partition(
    ON_Brep *brep,
    const ON_BrepEdge &reference_edge,
    const BooleanSourceEdgeUse &reference_use,
    const std::vector<BooleanSourceEdgeUse> &candidate_uses,
    double tolerance)
{
    const auto skipped = [](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean closed partial partition skipped: %s.\n", reason);
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    };
    if (brep == NULL || candidate_uses.size() != 2 ||
	!is_active_boolean_closed_naked_edge(brep, reference_use.m_edge_index))
    {
	return skipped("candidate cardinality or reference topology changed");
    }

    const double normalized_tolerance =
	boolean_source_edge_normalized_tolerance(reference_edge, tolerance);
    const BooleanSourceEdgeUse *low = &candidate_uses[0];
    const BooleanSourceEdgeUse *high = &candidate_uses[1];
    if (std::min(low->m_source_start, low->m_source_end) >
	    std::min(high->m_source_start, high->m_source_end))
    {
	std::swap(low, high);
    }
    const double low_min = std::min(low->m_source_start, low->m_source_end);
    const double low_max = std::max(low->m_source_start, low->m_source_end);
    const double high_min = std::min(high->m_source_start, high->m_source_end);
    const double high_max = std::max(high->m_source_start, high->m_source_end);
    if (low_min > normalized_tolerance ||
	high_max < 1.0 - normalized_tolerance ||
	high_min - low_max <= normalized_tolerance)
    {
	return skipped("candidates are not separated prefix and suffix intervals");
    }

    const ON_BrepEdge &low_edge = brep->m_E[low->m_edge_index];
    const ON_BrepEdge &high_edge = brep->m_E[high->m_edge_index];
    const ON_BrepTrim &reference_trim = brep->m_T[reference_use.m_trim_index];
    const ON_BrepTrim &low_trim = brep->m_T[low->m_trim_index];
    const ON_BrepTrim &high_trim = brep->m_T[high->m_trim_index];
    const int reference_face = reference_trim.FaceIndexOf();
    const int low_face = low_trim.FaceIndexOf();
    const int high_face = high_trim.FaceIndexOf();
    if (low_face < 0 || high_face != low_face ||
	low->m_edge_index == high->m_edge_index ||
	reference_face < 0 || reference_face == low_face)
    {
	return skipped("candidate faces or edges are not uniquely paired");
    }

    const int seam_vertex = reference_trim.m_vi[0];
    const bool low_increases = low->m_source_end > low->m_source_start;
    const bool high_increases = high->m_source_end > high->m_source_start;
    const int low_seam_vertex = low_edge.m_vi[low_increases ? 0 : 1];
    const int low_gap_vertex = low_edge.m_vi[low_increases ? 1 : 0];
    const int high_gap_vertex = high_edge.m_vi[high_increases ? 0 : 1];
    const int high_seam_vertex = high_edge.m_vi[high_increases ? 1 : 0];
    if (low_seam_vertex != seam_vertex || high_seam_vertex != seam_vertex ||
	low_gap_vertex == high_gap_vertex)
    {
	return skipped("candidate endpoints do not bound one interior gap");
    }

    const ON_3dPoint low_point = brep->m_V[low_gap_vertex].Point();
    const ON_3dPoint high_point = brep->m_V[high_gap_vertex].Point();
    double low_edge_parameter = ON_UNSET_VALUE;
    double high_edge_parameter = ON_UNSET_VALUE;
    double low_trim_parameter = ON_UNSET_VALUE;
    double high_trim_parameter = ON_UNSET_VALUE;
    if (!point_3d_to_curve_parameter_with_tolerance(low_point,
	    &reference_edge, tolerance, low_edge_parameter, false) ||
	!point_3d_to_curve_parameter_with_tolerance(high_point,
	    &reference_edge, tolerance, high_edge_parameter, false) ||
	!find_boolean_trim_lift_parameter(reference_trim, low_point, tolerance,
	    low_trim_parameter) ||
	!find_boolean_trim_lift_parameter(reference_trim, high_point, tolerance,
	    high_trim_parameter))
    {
	return skipped("gap endpoints could not be located on the reference");
    }
    if (!(low_edge_parameter < high_edge_parameter)) {
	return skipped("reference edge split parameters are not ordered");
    }

    std::unique_ptr<ON_Curve> middle_edge(reference_edge.DuplicateCurve());
    if (!middle_edge || !middle_edge->Trim(ON_Interval(low_edge_parameter,
	    high_edge_parameter)) || !middle_edge->IsValid())
    {
	return skipped("middle model curve could not be extracted");
    }

    const bool reference_reversed = reference_trim.m_bRev3d;
    const double first_trim_parameter = std::min(low_trim_parameter,
	high_trim_parameter);
    const double second_trim_parameter = std::max(low_trim_parameter,
	high_trim_parameter);
    const ON_Interval trim_domain = reference_trim.Domain();
    const ON_Interval trim_intervals[3] = {
	ON_Interval(trim_domain.Min(), first_trim_parameter),
	ON_Interval(first_trim_parameter, second_trim_parameter),
	ON_Interval(second_trim_parameter, trim_domain.Max())
    };
    std::unique_ptr<ON_Curve> trim_pieces[3];
    for (int piece = 0; piece < 3; ++piece) {
	trim_pieces[piece].reset(reference_trim.DuplicateCurve());
	if (!trim_pieces[piece] ||
	    !trim_pieces[piece]->Trim(trim_intervals[piece]) ||
	    !trim_pieces[piece]->IsValid())
	{
	    return skipped("a reference trim piece could not be extracted");
	}
    }

    const ON_Surface *reference_surface = reference_trim.SurfaceOf();
    const int low_trim_piece = reference_reversed ? 2 : 0;
    const int high_trim_piece = reference_reversed ? 0 : 2;
    const bool low_trim_reversed = low_increases == reference_reversed;
    const bool high_trim_reversed = high_increases == reference_reversed;
    if (reference_surface == NULL ||
	!boolean_parameter_curve_follows_edge(reference_surface,
	    trim_pieces[low_trim_piece].get(), low_edge, low_trim_reversed,
	    tolerance) ||
	!boolean_parameter_curve_follows_edge(reference_surface,
	    trim_pieces[high_trim_piece].get(), high_edge, high_trim_reversed,
	    tolerance))
    {
	return skipped("a covered trim piece does not follow its mate");
    }

    const int naked_before = boolean_active_naked_edge_count(brep);
    const int edge_count_before = brep->m_E.Count();
    const int trim_count_before = brep->m_T.Count();
    const int face_count_before = brep->m_F.Count();
    const int loop_count_before = brep->m_L.Count();
    const int surface_count_before = brep->m_S.Count();
    const int vertex_count_before = brep->m_V.Count();
    const int old_loop_index = reference_trim.m_li;
    std::vector<int> old_loop_trims(
	brep->m_L[old_loop_index].m_ti.Array(),
	brep->m_L[old_loop_index].m_ti.Array() +
	brep->m_L[old_loop_index].m_ti.Count());
    if (std::count(old_loop_trims.begin(), old_loop_trims.end(),
	    reference_use.m_trim_index) != 1)
    {
	return skipped("reference trim is not unique in its loop");
    }

    ON_Brep repaired(*brep);
    const int middle_curve_index = repaired.AddEdgeCurve(middle_edge.release());
    if (middle_curve_index < 0) {
	return skipped("middle model curve could not be installed");
    }
    ON_BrepEdge &middle = repaired.NewEdge(repaired.m_V[low_gap_vertex],
	repaired.m_V[high_gap_vertex], middle_curve_index, NULL, tolerance);
    const int native_edges[3] = {
	low->m_edge_index, middle.m_edge_index, high->m_edge_index
    };
    const bool native_increases[3] = {low_increases, true, high_increases};
    std::vector<int> new_trim_indices;
    for (int position = 0; position < 3; ++position) {
	const int native_piece = reference_reversed ? 2 - position : position;
	const bool trim_increases = !reference_reversed;
	const bool trim_reversed = native_increases[native_piece] !=
	    trim_increases;
	const int curve_index = repaired.AddTrimCurve(
	    trim_pieces[position].release());
	if (curve_index < 0) {
	    return skipped("a reference trim piece could not be installed");
	}
	ON_BrepTrim &created = repaired.NewTrim(
	    repaired.m_E[native_edges[native_piece]], trim_reversed,
	    repaired.m_L[old_loop_index], curve_index);
	created.m_type = native_piece == 1 ? ON_BrepTrim::boundary :
	    ON_BrepTrim::mated;
	created.m_tolerance[0] = reference_trim.m_tolerance[0];
	created.m_tolerance[1] = reference_trim.m_tolerance[1];
	new_trim_indices.push_back(created.m_trim_index);
    }
    repaired.m_T[low->m_trim_index].m_type = ON_BrepTrim::mated;
    repaired.m_T[high->m_trim_index].m_type = ON_BrepTrim::mated;

    ON_BrepLoop &loop = repaired.m_L[old_loop_index];
    loop.m_ti.SetCount(0);
    for (int trim_index : old_loop_trims) {
	if (trim_index != reference_use.m_trim_index) {
	    loop.m_ti.Append(trim_index);
	    repaired.m_T[trim_index].m_li = old_loop_index;
	    continue;
	}
	for (int new_trim_index : new_trim_indices) {
	    loop.m_ti.Append(new_trim_index);
	    repaired.m_T[new_trim_index].m_li = old_loop_index;
	}
    }
    repaired.DeleteTrim(repaired.m_T[reference_use.m_trim_index], false);
    repaired.DeleteEdge(repaired.m_E[reference_use.m_edge_index], false);

    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    const bool compacted = repaired.Compact();
    if (compacted)
	repaired.SetTrimBoundingBoxes(false);
    const bool valid = compacted && repaired.SetTrimIsoFlags() &&
	repaired.SetTrimTypeFlags(false) &&
	repaired.SetVertexTolerances(false) &&
	set_boolean_edge_tolerances(&repaired) &&
	set_boolean_trim_tolerances(&repaired) && repaired.IsValid(&validation_log);
    const int naked_after = boolean_active_naked_edge_count(&repaired);
    if (!valid || naked_after != naked_before - 1 ||
	repaired.m_E.Count() != edge_count_before ||
	repaired.m_T.Count() != trim_count_before + 2 ||
	repaired.m_F.Count() != face_count_before ||
	repaired.m_L.Count() != loop_count_before ||
	repaired.m_S.Count() != surface_count_before ||
	repaired.m_V.Count() != vertex_count_before)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean closed partial partition rolled back: valid %d, "
		"naked %d -> %d.\n", valid, naked_before, naked_after);
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    *brep = repaired;
    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static int
boolean_edge_source_face_index(const ON_Brep *brep, int edge_index)
{
    if (!is_active_boolean_naked_edge(brep, edge_index) &&
	!is_active_boolean_closed_naked_edge(brep, edge_index))
    {
	return -1;
    }
    const ON_BrepEdge &edge = brep->m_E[edge_index];
    const int trim_index = edge.m_ti[0];
    if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
	return -1;
    }
    const int face_index = brep->m_T[trim_index].FaceIndexOf();
    if (face_index < 0 || face_index >= brep->m_F.Count()) {
	return -1;
    }
    const int source_face_index = brep->m_F[face_index].m_face_user.i -
	FACE_SOURCE_TAG_OFFSET;
    return source_face_index >= 0 ? source_face_index : -1;
}


/* Certify that two result edges cover one another completely.  The ordinary
 * curve-equivalence predicate is sensitive to parameterization differences in
 * independently lifted SSI curves, so project dense samples in both
 * directions and require both normalized intervals to cover the full peer
 * edge monotonically. */
static bool
boolean_edges_have_matching_full_projection(
    const ON_Brep *brep,
    int first_edge_index,
    int second_edge_index,
    double tolerance,
    bool &reversed)
{
    reversed = false;
    if (!is_active_boolean_naked_edge(brep, first_edge_index) ||
	!is_active_boolean_naked_edge(brep, second_edge_index) ||
	first_edge_index == second_edge_index)
    {
	return false;
    }

    const ON_BrepEdge &first_edge = brep->m_E[first_edge_index];
    const ON_BrepEdge &second_edge = brep->m_E[second_edge_index];
    BooleanSourceEdgeUse first_on_second;
    BooleanSourceEdgeUse second_on_first;
    if (!project_boolean_edge_to_source_edge(brep, first_edge_index,
	    second_edge, tolerance, first_on_second) ||
	!project_boolean_edge_to_source_edge(brep, second_edge_index,
	    first_edge, tolerance, second_on_first))
    {
	return false;
    }

    const bool first_reversed = first_on_second.m_source_end <
	first_on_second.m_source_start;
    const bool second_reversed = second_on_first.m_source_end <
	second_on_first.m_source_start;
    if (first_reversed != second_reversed) {
	return false;
    }

    const double first_tolerance = boolean_source_edge_normalized_tolerance(
	second_edge, tolerance);
    const double second_tolerance = boolean_source_edge_normalized_tolerance(
	first_edge, tolerance);
    const auto covers_full_edge = [](const BooleanSourceEdgeUse &use,
	bool use_reversed, double normalized_tolerance) {
	const double expected_start = use_reversed ? 1.0 : 0.0;
	const double expected_end = use_reversed ? 0.0 : 1.0;
	return normalized_tolerance > 0.0 &&
	    std::isfinite(normalized_tolerance) &&
	    fabs(use.m_source_start - expected_start) <= normalized_tolerance &&
	    fabs(use.m_source_end - expected_end) <= normalized_tolerance;
    };
    if (!covers_full_edge(first_on_second, first_reversed,
	    first_tolerance) ||
	!covers_full_edge(second_on_first, second_reversed, second_tolerance))
    {
	return false;
    }

    reversed = first_reversed;
    return true;
}


static bool
repair_boolean_naked_edge_partitions(
    ON_Brep *brep,
    const ON_ClassArray<SharedSSICurve> &shared_curves,
    BooleanNakedEdgePartitionEvidence *unresolved_partition)
{
    if (brep == NULL) {
	return false;
    }
    if (unresolved_partition != NULL) {
	*unresolved_partition = BooleanNakedEdgePartitionEvidence();
    }

    const double tolerance = boolean_model_repair_tolerance(
	brep->BoundingBox());
    if (!(tolerance > 0.0) || !std::isfinite(tolerance)) {
	return true;
    }
    const double provenance_tolerance = 2.0 * tolerance;

    int repaired_count = 0;
    for (;;) {
	BooleanNakedEdgePartitionEvidence iteration_evidence;
	std::vector<int> naked_edges;
	for (int edge_index = 0; edge_index < brep->m_E.Count();
	     ++edge_index)
	{
	    if (is_active_boolean_naked_edge(brep, edge_index) ||
		is_active_boolean_closed_naked_edge(brep, edge_index)) {
		naked_edges.push_back(edge_index);
	    }
	}

	bool repaired = false;
	for (int single_edge_index : naked_edges) {
	    if (!is_active_boolean_naked_edge(brep, single_edge_index) &&
		!is_active_boolean_closed_naked_edge(brep, single_edge_index)) {
		continue;
	    }

	    const ON_BrepEdge &reference_edge =
		brep->m_E[single_edge_index];
	    const int single_trim_index = reference_edge.m_ti[0];
	    if (single_trim_index < 0 ||
		single_trim_index >= brep->m_T.Count())
	    {
		continue;
	    }
	    const ON_BrepTrim &single_trim = brep->m_T[single_trim_index];
	    const int single_face_index = single_trim.FaceIndexOf();
	    if (single_face_index < 0 ||
		single_face_index >= brep->m_F.Count())
	    {
		continue;
	    }

	    BooleanSourceEdgeUse single_use;
	    single_use.m_edge_index = single_edge_index;
	    single_use.m_trim_index = single_trim_index;
	    single_use.m_source_start = 0.0;
	    single_use.m_source_end = 1.0;
	    std::vector<BooleanSourceEdgeUse> single_uses(1, single_use);
	    const double single_direction = single_trim.m_bRev3d ? -1.0 : 1.0;
	    const double single_effective_direction =
		brep->m_F[single_face_index].m_bRev ?
		-single_direction : single_direction;

	    const auto attempt_partition = [&](double attempt_tolerance,
		bool require_shared_provenance) {
		const double normalized_tolerance =
		    boolean_source_edge_normalized_tolerance(reference_edge,
			attempt_tolerance);
		if (!(normalized_tolerance > 0.0) ||
		    !std::isfinite(normalized_tolerance))
		{
		    return SHARED_SSI_EDGE_REPAIR_SKIPPED;
		}

		std::vector<BooleanSourceEdgeUse> chain_uses;
		bool has_shared_provenance = false;
		for (int candidate_edge_index : naked_edges) {
		    if (candidate_edge_index == single_edge_index ||
			!is_active_boolean_naked_edge(brep,
			    candidate_edge_index))
		    {
			continue;
		    }

		    BooleanSourceEdgeUse candidate;
		    const bool candidate_projected =
			project_boolean_edge_to_source_edge(brep,
			    candidate_edge_index, reference_edge,
			    attempt_tolerance, candidate);
		    if (DEBUG_BREP_BOOLEAN && reference_edge.IsClosed()) {
			bu_log("Boolean closed partition reference %d candidate %d "
			    "face %d projected %d interval %.17g -> %.17g.\n",
			    single_edge_index, candidate_edge_index,
			    boolean_edge_source_face_index(brep,
				candidate_edge_index), candidate_projected,
			    candidate.m_source_start, candidate.m_source_end);
		    }
		    if (!candidate_projected)
		    {
			continue;
		    }
		    const double interval_min = std::min(
			candidate.m_source_start, candidate.m_source_end);
		    const double interval_max = std::max(
			candidate.m_source_start, candidate.m_source_end);
		    if (!std::isfinite(interval_min) ||
			!std::isfinite(interval_max) ||
			interval_max - interval_min <= normalized_tolerance ||
			interval_min < -normalized_tolerance ||
			interval_max > 1.0 + normalized_tolerance)
		    {
			continue;
		    }

		    const ON_BrepTrim &candidate_trim =
			brep->m_T[candidate.m_trim_index];
		    const int candidate_face_index = candidate_trim.FaceIndexOf();
		    if (candidate_face_index < 0 ||
			candidate_face_index >= brep->m_F.Count() ||
			candidate_face_index == single_face_index)
		    {
			continue;
		    }
		    const double candidate_start = candidate_trim.m_bRev3d ?
			candidate.m_source_end : candidate.m_source_start;
		    const double candidate_end = candidate_trim.m_bRev3d ?
			candidate.m_source_start : candidate.m_source_end;
		    if (!std::isfinite(candidate_start) ||
			!std::isfinite(candidate_end) ||
			candidate_start == candidate_end)
		    {
			continue;
		    }
		    const double candidate_direction = candidate_end >
			candidate_start ? 1.0 : -1.0;
		    const double candidate_effective_direction =
			brep->m_F[candidate_face_index].m_bRev ?
			-candidate_direction : candidate_direction;
		    if (candidate_effective_direction !=
			    -single_effective_direction)
		    {
			continue;
		    }

		    const bool candidate_has_shared_provenance =
			boolean_edges_share_open_ssi_provenance(brep,
			    single_edge_index, candidate_edge_index,
			    shared_curves);
		    has_shared_provenance = has_shared_provenance ||
			candidate_has_shared_provenance;
		    chain_uses.push_back(candidate);
		}

		if (chain_uses.size() == 1)
		{
		    /* Parameter seams can leave a tolerance-scale connector beside a
		     * unique pair of fully projecting, opposite-sense edges.  This is
		     * a one-to-one seam plus an endpoint spike rather than a genuine
		     * one-to-many partition.  The spike repair independently certifies
		     * the complete residual locus, endpoint topology, edge orientation,
		     * and the validity and topology counts of its transactional result. */
		    const BooleanSourceEdgeUse &survivor_use = chain_uses[0];
		    const ON_BrepTrim &survivor_trim =
			brep->m_T[survivor_use.m_trim_index];
		    bool survivor_reverses_single = false;
		    if (!boolean_edges_have_matching_full_projection(brep,
			    single_edge_index, survivor_use.m_edge_index,
			    attempt_tolerance, survivor_reverses_single))
		    {
			return SHARED_SSI_EDGE_REPAIR_SKIPPED;
		    }
		    for (int residual_edge_index : naked_edges) {
			if (residual_edge_index == single_edge_index ||
			    residual_edge_index == survivor_use.m_edge_index ||
			    !is_active_boolean_naked_edge(brep,
				residual_edge_index))
			{
			    continue;
			}

			const ON_BrepEdge &residual_edge =
			    brep->m_E[residual_edge_index];
			const int residual_trim_index = residual_edge.m_ti[0];
			if (residual_trim_index < 0 ||
			    residual_trim_index >= brep->m_T.Count())
			{
			    continue;
			}
			const ON_BrepTrim &residual_trim =
			    brep->m_T[residual_trim_index];
			if (residual_trim.m_li != survivor_trim.m_li ||
			    residual_trim.FaceIndexOf() !=
				survivor_trim.FaceIndexOf())
			{
			    continue;
			}

			const bool residual_precedes_survivor =
			    brep->NextTrim(residual_trim_index) ==
				survivor_use.m_trim_index;
			const bool residual_follows_survivor =
			    brep->PrevTrim(residual_trim_index) ==
				survivor_use.m_trim_index;
			if (residual_precedes_survivor ==
			    residual_follows_survivor)
			{
			    continue;
			}

			BooleanSourceEdgeUse residual_use;
			residual_use.m_edge_index = residual_edge_index;
			residual_use.m_trim_index = residual_trim_index;
			const SharedSSIEdgeRepairResult spike_result =
			    repair_boolean_source_edge_endpoint_spike(brep,
				single_use, residual_use, survivor_use,
				residual_precedes_survivor,
				attempt_tolerance,
				&survivor_reverses_single);
			if (spike_result != SHARED_SSI_EDGE_REPAIR_SKIPPED) {
			    if (DEBUG_BREP_BOOLEAN && spike_result ==
				    SHARED_SSI_EDGE_REPAIR_COMPLETE)
			    {
				bu_log("Boolean naked-edge SSI seam collapsed "
				    "endpoint spike %d beside edges %d/%d.\n",
				    residual_edge_index, single_edge_index,
				    survivor_use.m_edge_index);
			    }
			    return spike_result;
			}
		    }
		}
		if (chain_uses.size() < 2 ||
		    (require_shared_provenance && !has_shared_provenance))
		{
		    return SHARED_SSI_EDGE_REPAIR_SKIPPED;
		}
		std::vector<std::pair<double, double> > coverage;
		coverage.reserve(chain_uses.size());
		for (const BooleanSourceEdgeUse &use : chain_uses) {
		    coverage.push_back(std::make_pair(
			std::min(use.m_source_start, use.m_source_end),
			std::max(use.m_source_start, use.m_source_end)));
		}
		std::sort(coverage.begin(), coverage.end());
		bool complete_coverage = !coverage.empty() &&
		    coverage.front().first <= normalized_tolerance;
		double covered_end = complete_coverage ?
		    coverage.front().second : 0.0;
		for (size_t interval = 1;
		     interval < coverage.size() && complete_coverage; ++interval)
		{
		    if (coverage[interval].first > covered_end +
			normalized_tolerance)
		    {
			complete_coverage = false;
			break;
		    }
		    covered_end = std::max(covered_end,
			coverage[interval].second);
		}
		complete_coverage = complete_coverage &&
		    covered_end >= 1.0 - normalized_tolerance;
		if (complete_coverage &&
		    iteration_evidence.reference_edge_index < 0)
		{
		    iteration_evidence.reference_edge_index = single_edge_index;
		    iteration_evidence.peer_edge_index = chain_uses[0].m_edge_index;
		    iteration_evidence.reference_face_index =
			boolean_edge_source_face_index(brep, single_edge_index);
		    iteration_evidence.peer_face_index =
			boolean_edge_source_face_index(brep,
			    chain_uses[0].m_edge_index);
		    iteration_evidence.tolerance = attempt_tolerance;
		}

		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean naked-edge partition reference %d has %zu "
			"projected candidates at tolerance %.17g.\n",
			single_edge_index, chain_uses.size(), attempt_tolerance);
		    for (size_t candidate_index = 0;
			 candidate_index < chain_uses.size(); ++candidate_index)
		    {
			const BooleanSourceEdgeUse &candidate =
			    chain_uses[candidate_index];
			const ON_BrepTrim &candidate_trim =
			    brep->m_T[candidate.m_trim_index];
			bu_log("  candidate %zu edge %d trim %d face %d loop %d "
			    "vertices %d/%d interval %.17g -> %.17g reversed %d "
			    "face-reversed %d.\n", candidate_index,
			    candidate.m_edge_index, candidate.m_trim_index,
			    candidate_trim.FaceIndexOf(), candidate_trim.m_li,
			    candidate_trim.m_vi[0], candidate_trim.m_vi[1],
			    candidate.m_source_start, candidate.m_source_end,
			    candidate_trim.m_bRev3d,
			    brep->m_F[candidate_trim.FaceIndexOf()].m_bRev);
		    }
		}
		if (DEBUG_BREP_BOOLEAN && require_shared_provenance) {
		    bu_log("Boolean naked-edge partition using shared SSI "
			"provenance at tolerance %.17g.\n", attempt_tolerance);
		}
		if (!complete_coverage && reference_edge.IsClosed()) {
		    return repair_boolean_closed_edge_partial_partition(brep,
			reference_edge, single_use, chain_uses,
			attempt_tolerance);
		}
		return repair_boolean_source_edge_full_partition(brep,
		    reference_edge, single_uses, chain_uses, attempt_tolerance);
	    };

	    SharedSSIEdgeRepairResult result = attempt_partition(tolerance,
		false);
	    /* Stitching has already accepted this bounded uncertainty.  Retry at
	     * the same two-times bound only when an original open SSI parameter
	     * curve proves that one candidate on each operand came from the same
	     * intersection.  Complete curve projection, interval coverage,
	     * traversal, lift, topology, and validity checks still apply. */
	    if (result == SHARED_SSI_EDGE_REPAIR_SKIPPED &&
		provenance_tolerance > tolerance &&
		std::isfinite(provenance_tolerance))
	    {
		result = attempt_partition(provenance_tolerance, true);
	    }
	    if (result == SHARED_SSI_EDGE_REPAIR_FAILURE) {
		return false;
	    }
	    if (result == SHARED_SSI_EDGE_REPAIR_COMPLETE) {
		++repaired_count;
		repaired = true;
		break;
	    }
	}

	if (!repaired) {
	    if (unresolved_partition != NULL &&
		iteration_evidence.reference_edge_index >= 0)
	    {
		*unresolved_partition = iteration_evidence;
	    }
	    break;
	}
    }

    if (DEBUG_BREP_BOOLEAN && repaired_count > 0) {
	bu_log("Boolean naked-edge partition repair completed %d seam%s.\n",
	    repaired_count, repaired_count == 1 ? "" : "s");
    }
    return true;
}


static bool
repair_boolean_source_edge_partitions(
    ON_Brep *brep,
    const ON_Brep *brep1,
    const ON_Brep *brep2)
{
    if (brep == NULL || brep1 == NULL || brep2 == NULL) {
	return false;
    }

    ON_Brep *destination = brep;
    ON_Brep working(*brep);
    brep = &working;

    const ON_Brep *source_breps[2] = {brep1, brep2};
    const int source_face_offsets[2] = {0, brep1->m_F.Count()};
    const double tolerance = boolean_model_repair_tolerance(
	brep->BoundingBox());
    int repaired = 0;
    for (int operand = 0; operand < 2; ++operand) {
	const ON_Brep *source_brep = source_breps[operand];
	for (int source_edge_index = 0;
	     source_edge_index < source_brep->m_E.Count();
	     ++source_edge_index)
	{
	    const ON_BrepEdge &source_edge =
		source_brep->m_E[source_edge_index];
	    if (source_edge.m_edge_index != source_edge_index ||
		source_edge.m_ti.Count() != 2 || source_edge.m_vi[0] < 0 ||
		source_edge.m_vi[1] < 0 ||
		(source_edge.m_vi[0] == source_edge.m_vi[1]) !=
		    source_edge.IsClosed())
	    {
		continue;
	    }

	    const int source_trim_indices[2] = {
		source_edge.m_ti[0], source_edge.m_ti[1]
	    };
	    if (source_trim_indices[0] < 0 ||
		source_trim_indices[0] >= source_brep->m_T.Count() ||
		source_trim_indices[1] < 0 ||
		source_trim_indices[1] >= source_brep->m_T.Count())
	    {
		continue;
	    }
	    const int source_local_faces[2] = {
		source_brep->m_T[source_trim_indices[0]].FaceIndexOf(),
		source_brep->m_T[source_trim_indices[1]].FaceIndexOf()
	    };
	    const int source_faces[2] = {
		source_local_faces[0] +
		    source_face_offsets[operand],
		source_local_faces[1] +
		    source_face_offsets[operand]
	    };
	    if (source_faces[0] < source_face_offsets[operand] ||
		source_faces[1] < source_face_offsets[operand] ||
		source_local_faces[0] >= source_brep->m_F.Count() ||
		source_local_faces[1] >= source_brep->m_F.Count() ||
		source_faces[0] == source_faces[1])
	    {
		continue;
	    }

	    std::vector<BooleanSourceEdgeUse> uses[2];
	    collect_boolean_source_edge_uses(brep, source_faces[0],
		source_brep->m_F[source_local_faces[0]],
		source_brep->m_T[source_trim_indices[0]], source_edge, tolerance,
		uses[0]);
	    collect_boolean_source_edge_uses(brep, source_faces[1],
		source_brep->m_F[source_local_faces[1]],
		source_brep->m_T[source_trim_indices[1]], source_edge, tolerance,
		uses[1]);
	    if (DEBUG_BREP_BOOLEAN && (!uses[0].empty() || !uses[1].empty())) {
		bu_log("Boolean source-edge partition operand %d edge %d faces "
		    "%d/%d matched %zu/%zu naked uses.\n", operand,
		    source_edge_index, source_faces[0], source_faces[1],
		    uses[0].size(), uses[1].size());
	    }
	    if (DEBUG_BREP_BOOLEAN && (!uses[0].empty() || !uses[1].empty()))
	    {
		const ON_3dPoint source_start = source_edge.PointAtStart();
		const ON_3dPoint source_end = source_edge.PointAtEnd();
		bu_log("Boolean source-edge %zu/%zu candidate operand %d edge %d "
		    "vertices %d/%d, curve %.17g %.17g %.17g -> %.17g %.17g "
		    "%.17g.\n", uses[0].size(), uses[1].size(), operand,
		    source_edge_index, source_edge.m_vi[0], source_edge.m_vi[1],
		    source_start.x, source_start.y,
		    source_start.z, source_end.x, source_end.y, source_end.z);
		for (int source_side = 0; source_side < 2; ++source_side) {
		    const ON_BrepTrim &source_trim =
			source_brep->m_T[source_trim_indices[source_side]];
		    bu_log("  source side %d trim %d face %d reversed %d, "
			"vertices %d/%d.\n", source_side,
			source_trim_indices[source_side], source_faces[source_side],
			source_trim.m_bRev3d, source_trim.m_vi[0],
			source_trim.m_vi[1]);
		    for (size_t use_index = 0; use_index < uses[source_side].size();
			 ++use_index)
		    {
			const BooleanSourceEdgeUse &use =
			    uses[source_side][use_index];
			if (use.m_edge_index < 0 ||
			    use.m_edge_index >= brep->m_E.Count() ||
			    use.m_trim_index < 0 ||
			    use.m_trim_index >= brep->m_T.Count())
			{
			    continue;
			}
			const ON_BrepEdge &edge = brep->m_E[use.m_edge_index];
			const ON_BrepTrim &trim = brep->m_T[use.m_trim_index];
			const int result_face = trim.FaceIndexOf();
			const int face_reversed = result_face >= 0 &&
			    result_face < brep->m_F.Count() ?
			    (brep->m_F[result_face].m_bRev ? 1 : 0) : -1;
			const int effective_reversed = face_reversed >= 0 ?
			    ((trim.m_bRev3d ? 1 : 0) ^ face_reversed) : -1;
			const int result_source_face = result_face >= 0 &&
			    result_face < brep->m_F.Count() ?
			    brep->m_F[result_face].m_face_user.i -
				FACE_SOURCE_TAG_OFFSET : -1;
			const int loop_position = trim.m_li >= 0 &&
			    trim.m_li < brep->m_L.Count() ?
			    boolean_loop_trim_position(brep->m_L[trim.m_li],
				use.m_trim_index) : -1;
			const int previous_trim = brep->PrevTrim(use.m_trim_index);
			const int next_trim = brep->NextTrim(use.m_trim_index);
			const double oriented_start = trim.m_bRev3d ?
			    use.m_source_end : use.m_source_start;
			const double oriented_end = trim.m_bRev3d ?
			    use.m_source_start : use.m_source_end;
			const ON_3dPoint edge_start = trim.m_bRev3d ?
			    edge.PointAtEnd() : edge.PointAtStart();
			const ON_3dPoint edge_end = trim.m_bRev3d ?
			    edge.PointAtStart() : edge.PointAtEnd();
			const ON_3dPoint parameter_start = trim.PointAtStart();
			const ON_3dPoint parameter_end = trim.PointAtEnd();
			const ON_Surface *surface = trim.SurfaceOf();
			const ON_3dPoint lifted_start = surface &&
			    parameter_start.IsValid() ? surface->PointAt(
				parameter_start.x, parameter_start.y) :
			    ON_3dPoint::UnsetPoint;
			const ON_3dPoint lifted_end = surface &&
			    parameter_end.IsValid() ? surface->PointAt(
				parameter_end.x, parameter_end.y) :
			    ON_3dPoint::UnsetPoint;
			bu_log("    use %zu edge %d trim %d result face %d "
			    "(source %d), loop %d position %d/%d, previous/next "
			    "%d/%d, reversed %d, face reversed %d, effective "
			    "reversed %d, trim vertices %d/%d, edge "
			    "vertices %d/%d, source %.17g -> %.17g (oriented "
			    "%.17g -> %.17g).\n", use_index, use.m_edge_index,
			    use.m_trim_index, result_face, result_source_face,
			    trim.m_li, loop_position,
			    trim.m_li >= 0 && trim.m_li < brep->m_L.Count() ?
				brep->m_L[trim.m_li].m_ti.Count() : -1,
			    previous_trim, next_trim, trim.m_bRev3d, face_reversed,
			    effective_reversed, trim.m_vi[0], trim.m_vi[1],
			    edge.m_vi[0], edge.m_vi[1],
			    use.m_source_start, use.m_source_end, oriented_start,
			    oriented_end);
			bu_log("      edge %.17g %.17g %.17g -> %.17g %.17g "
			    "%.17g, parameter %.17g %.17g -> %.17g %.17g, "
			    "lift %.17g %.17g %.17g -> %.17g %.17g %.17g.\n",
			    edge_start.x, edge_start.y, edge_start.z, edge_end.x,
			    edge_end.y, edge_end.z, parameter_start.x,
			    parameter_start.y, parameter_end.x, parameter_end.y,
			    lifted_start.x, lifted_start.y, lifted_start.z,
			    lifted_end.x, lifted_end.y, lifted_end.z);
		    }
		}
	    }

	    const auto repair_uses = [&](const std::vector<BooleanSourceEdgeUse>
		    &first_uses,
		const std::vector<BooleanSourceEdgeUse> &second_uses,
		double attempt_tolerance) {
		SharedSSIEdgeRepairResult attempt =
		    SHARED_SSI_EDGE_REPAIR_SKIPPED;
		if (first_uses.size() == 1 && second_uses.size() == 1) {
		    attempt = repair_boolean_source_edge_pair_endpoint_spike(brep,
			source_edge, first_uses, second_uses, attempt_tolerance);
		    if (attempt == SHARED_SSI_EDGE_REPAIR_SKIPPED) {
			attempt = repair_boolean_source_edge_pair(brep, source_edge,
			    first_uses, second_uses, attempt_tolerance, NULL, true);
		    }
		    if (attempt == SHARED_SSI_EDGE_REPAIR_SKIPPED) {
			bool second_reverses_first = false;
			if (boolean_edges_have_matching_full_projection(brep,
				first_uses[0].m_edge_index,
				second_uses[0].m_edge_index, attempt_tolerance,
				second_reverses_first))
			{
			    attempt = repair_boolean_source_edge_pair(brep,
				source_edge, first_uses, second_uses,
				attempt_tolerance, &second_reverses_first, true);
			}
		    }
		} else if (first_uses.size() == 1 && second_uses.size() == 2) {
		    attempt = repair_boolean_source_edge_partition(brep,
			source_edge, first_uses, second_uses, attempt_tolerance);
		    if (attempt == SHARED_SSI_EDGE_REPAIR_SKIPPED) {
			attempt = repair_boolean_source_edge_full_partition(brep,
			    source_edge, first_uses, second_uses,
			    attempt_tolerance);
		    }
		} else if (first_uses.size() == 2 && second_uses.size() == 1) {
		    attempt = repair_boolean_source_edge_partition(brep,
			source_edge, second_uses, first_uses, attempt_tolerance);
		    if (attempt == SHARED_SSI_EDGE_REPAIR_SKIPPED) {
			attempt = repair_boolean_source_edge_full_partition(brep,
			    source_edge, second_uses, first_uses,
			    attempt_tolerance);
		    }
		} else if (first_uses.size() == 1 && second_uses.size() > 2) {
		    attempt = repair_boolean_source_edge_full_partition(brep,
			source_edge, first_uses, second_uses, attempt_tolerance);
		} else if (first_uses.size() > 2 && second_uses.size() == 1) {
		    attempt = repair_boolean_source_edge_full_partition(brep,
			source_edge, second_uses, first_uses, attempt_tolerance);
		}
		return attempt;
	    };

	    SharedSSIEdgeRepairResult result = repair_uses(uses[0], uses[1],
		tolerance);
	    /* A result edge may have been regenerated from an already evaluated
	     * operand and differ from its source edge by the accumulated endpoint
	     * tolerance.  The two source trims and their face tags provide exact
	     * topological provenance, so permit the same bounded two-times retry
	     * used by stitching.  All curve, traversal, topology, and transactional
	     * validity proofs in the repair routines still apply. */
	    const double provenance_tolerance = 2.0 * tolerance;
	    const double provenance_parameter_tolerance =
		boolean_source_edge_normalized_tolerance(source_edge,
		    provenance_tolerance);
	    const auto has_complete_use = [provenance_parameter_tolerance](
		const std::vector<BooleanSourceEdgeUse> &side_uses) {
		return side_uses.size() == 1 &&
		    std::min(side_uses[0].m_source_start,
			side_uses[0].m_source_end) <=
			provenance_parameter_tolerance &&
		    std::max(side_uses[0].m_source_start,
			side_uses[0].m_source_end) >=
			1.0 - provenance_parameter_tolerance;
	    };
	    const auto has_endpoint_offset_witness = [brep, &source_edge,
		tolerance, provenance_tolerance](int source_face_index) {
		for (int edge_index = 0; edge_index < brep->m_E.Count();
		     ++edge_index)
		{
		    if ((!is_shared_open_ssi_edge_candidate(brep, edge_index,
			    source_face_index) &&
			 !is_shared_closed_ssi_edge_candidate(brep, edge_index,
			    source_face_index)) ||
			!boolean_curve_bounds_overlap(brep->m_E[edge_index],
			    source_edge, provenance_tolerance))
		    {
			continue;
		    }
		    const ON_BrepEdge &edge = brep->m_E[edge_index];
		    double wide_start = ON_UNSET_VALUE;
		    double wide_end = ON_UNSET_VALUE;
		    if (!point_3d_to_curve_parameter_with_tolerance(
			    edge.PointAtStart(), &source_edge,
			    provenance_tolerance, wide_start) ||
			!point_3d_to_curve_parameter_with_tolerance(
			    edge.PointAtEnd(), &source_edge,
			    provenance_tolerance, wide_end))
		    {
			continue;
		    }
		    double tight_start = ON_UNSET_VALUE;
		    double tight_end = ON_UNSET_VALUE;
		    const bool tightly_matches =
			point_3d_to_curve_parameter_with_tolerance(
			    edge.PointAtStart(), &source_edge, tolerance,
			    tight_start) &&
			point_3d_to_curve_parameter_with_tolerance(
			    edge.PointAtEnd(), &source_edge, tolerance,
			    tight_end);
		    if (!tightly_matches) {
			return true;
		    }
		}
		return false;
	    };
	    const bool retry_has_provenance =
		(!uses[0].empty() && !uses[1].empty()) ||
		(has_complete_use(uses[0]) &&
		 has_endpoint_offset_witness(source_faces[1])) ||
		(has_complete_use(uses[1]) &&
		 has_endpoint_offset_witness(source_faces[0]));
	    if (result == SHARED_SSI_EDGE_REPAIR_SKIPPED &&
		retry_has_provenance &&
		provenance_tolerance > tolerance &&
		std::isfinite(provenance_tolerance))
	    {
		std::vector<BooleanSourceEdgeUse> provenance_uses[2];
		collect_boolean_source_edge_uses(brep, source_faces[0],
		    source_brep->m_F[source_local_faces[0]],
		    source_brep->m_T[source_trim_indices[0]], source_edge,
		    provenance_tolerance, provenance_uses[0]);
		collect_boolean_source_edge_uses(brep, source_faces[1],
		    source_brep->m_F[source_local_faces[1]],
		    source_brep->m_T[source_trim_indices[1]], source_edge,
		    provenance_tolerance, provenance_uses[1]);
		if (!provenance_uses[0].empty() &&
		    !provenance_uses[1].empty())
		{
		    if (DEBUG_BREP_BOOLEAN) {
			bu_log("Boolean source-edge partition retry operand %d "
			    "edge %d at provenance tolerance %.17g matched "
			    "%zu/%zu uses.\n", operand, source_edge_index,
			    provenance_tolerance, provenance_uses[0].size(),
			    provenance_uses[1].size());
		    }
		    result = repair_uses(provenance_uses[0],
			provenance_uses[1], provenance_tolerance);
		}
	    }
	    if (result == SHARED_SSI_EDGE_REPAIR_FAILURE) {
		return false;
	    }
	    if (result == SHARED_SSI_EDGE_REPAIR_COMPLETE) {
		++repaired;
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean source-edge partition repaired operand %d "
			"edge %d.\n", operand, source_edge_index);
		}
	    }
	}
    }

    if (DEBUG_BREP_BOOLEAN && repaired > 0) {
	bu_log("Boolean source-edge partition repair completed %d seam%s.\n",
	    repaired, repaired == 1 ? "" : "s");
    }
    if (repaired > 0) {
	ON_wString validation_text;
	ON_TextLog validation_log(validation_text);
	const bool compacted = working.Compact();
	if (compacted) {
	    working.SetTrimBoundingBoxes(false);
	}
	const bool valid = compacted && working.SetTrimIsoFlags() &&
	    working.SetTrimTypeFlags(false) &&
	    working.SetVertexTolerances(false) &&
	    set_boolean_edge_tolerances(&working) &&
	    set_boolean_trim_tolerances(&working) &&
	    working.IsValid(&validation_log);
	if (!valid) {
	    return false;
	}
	*destination = working;
    }
    return true;
}


/*
 * A Boolean intersection can represent a very short source-edge interval
 * twice: once by the retained source boundary and once by the adjoining
 * intersection boundary.  Both output edges then connect the same vertices,
 * but ordinary stitching may reject them because its relative tolerance is
 * intentionally much tighter than the model-scale repair tolerance.
 */
struct BooleanDegenerateSourceEdgePair {
    int m_canonical_edge_index = -1;
    int m_duplicate_edge_index = -1;
    int m_operand = -1;
    int m_source_edge_index = -1;
    bool m_reversed = false;
    double m_tolerance = 0.0;
};


/* A tolerance-scale connector can replace one side of a very short SSI.  It
 * has no source-edge trim provenance, but the other side still retains the
 * complete original SSI curve.  Accept that relationship only when exactly
 * one edge agrees with one shared SSI at the intersection tolerance and both
 * edges independently cover one another at the model repair tolerance. */
static bool
boolean_degenerate_pair_has_unique_ssi_witness(
    const ON_Brep *brep,
    int first_edge_index,
    int second_edge_index,
    const ON_ClassArray<SharedSSICurve> &shared_curves,
    double tolerance,
    bool oppositely_aligned,
    int &canonical_edge_index)
{
    canonical_edge_index = -1;
    if (brep == NULL || first_edge_index < 0 ||
	first_edge_index >= brep->m_E.Count() || second_edge_index < 0 ||
	second_edge_index >= brep->m_E.Count())
    {
	return false;
    }

    const ON_BrepEdge &first_edge = brep->m_E[first_edge_index];
    const ON_BrepEdge &second_edge = brep->m_E[second_edge_index];
    int witness_count = 0;
    for (int curve_index = 0; curve_index < shared_curves.Count();
	 ++curve_index)
    {
	const SharedSSICurve &shared_curve = shared_curves[curve_index];
	if (shared_curve.m_curve == NULL || shared_curve.m_curve->IsClosed()) {
	    continue;
	}

	const bool first_on_first = is_shared_ssi_edge_candidate(brep,
	    first_edge_index, shared_curve.m_face_index[0]);
	const bool first_on_second = is_shared_ssi_edge_candidate(brep,
	    first_edge_index, shared_curve.m_face_index[1]);
	const bool second_on_first = is_shared_ssi_edge_candidate(brep,
	    second_edge_index, shared_curve.m_face_index[0]);
	const bool second_on_second = is_shared_ssi_edge_candidate(brep,
	    second_edge_index, shared_curve.m_face_index[1]);
	if (!((first_on_first && second_on_second) ||
		(first_on_second && second_on_first)))
	{
	    continue;
	}

	bool first_reversed = false;
	bool second_reversed = false;
	const bool first_matches = open_curve_orientation_from_shared_ssi(
	    &first_edge, shared_curve.m_curve, first_reversed,
	    INTERSECTION_TOL);
	const bool second_matches = open_curve_orientation_from_shared_ssi(
	    &second_edge, shared_curve.m_curve, second_reversed,
	    INTERSECTION_TOL);
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean degenerate SSI witness edges %d/%d curve %d faces "
		"%d/%d matched %d/%d.\n", first_edge_index,
		second_edge_index, curve_index, shared_curve.m_face_index[0],
		shared_curve.m_face_index[1], first_matches, second_matches);
	}
	if (first_matches == second_matches) {
	    continue;
	}

	bool projection_reversed = false;
	if (!boolean_edges_have_matching_full_projection(brep,
		first_edge_index, second_edge_index, tolerance,
		projection_reversed) || projection_reversed != oppositely_aligned)
	{
	    continue;
	}

	++witness_count;
	canonical_edge_index = first_matches ? first_edge_index :
	    second_edge_index;
    }

    return witness_count == 1;
}


/* Independently fitted edge curves can disagree even when the two trims are
 * certified representations of the same model-space curve on their respective
 * surfaces.  Use those surface lifts as a topology witness when the endpoint
 * topology fixes one trim-to-trim orientation. */
static bool
boolean_degenerate_pair_has_surface_lift_witness(
    const ON_Brep *brep,
    int first_edge_index,
    int second_edge_index,
    const ON_ClassArray<SharedSSICurve> &shared_curves,
    double tolerance,
    bool edge_orientation_reversed,
    bool require_shared_ssi_witness,
    int &canonical_edge_index)
{
    canonical_edge_index = -1;
    if (brep == NULL || first_edge_index < 0 ||
	first_edge_index >= brep->m_E.Count() || second_edge_index < 0 ||
	second_edge_index >= brep->m_E.Count() ||
	first_edge_index == second_edge_index || !(tolerance > 0.0) ||
	!std::isfinite(tolerance))
    {
	return false;
    }

    const ON_BrepEdge &first_edge = brep->m_E[first_edge_index];
    const ON_BrepEdge &second_edge = brep->m_E[second_edge_index];
    if (first_edge.m_ti.Count() != 1 || second_edge.m_ti.Count() != 1) {
	return false;
    }

    const int first_trim_index = first_edge.m_ti[0];
    const int second_trim_index = second_edge.m_ti[0];
    if (first_trim_index < 0 || first_trim_index >= brep->m_T.Count() ||
	second_trim_index < 0 || second_trim_index >= brep->m_T.Count())
    {
	return false;
    }

    const ON_BrepTrim &first_trim = brep->m_T[first_trim_index];
    const ON_BrepTrim &second_trim = brep->m_T[second_trim_index];
    const int first_face_index = first_trim.FaceIndexOf();
    const int second_face_index = second_trim.FaceIndexOf();
    if (first_face_index < 0 || first_face_index >= brep->m_F.Count() ||
	second_face_index < 0 || second_face_index >= brep->m_F.Count() ||
	first_face_index == second_face_index ||
	first_trim.TrimCurveOf() == NULL ||
	second_trim.TrimCurveOf() == NULL || first_trim.SurfaceOf() == NULL ||
	second_trim.SurfaceOf() == NULL)
    {
	return false;
    }

    /* A trim runs opposite its edge when m_bRev3d is set.  Compose those two
     * reversals with the endpoint-defined relation between the edges to get
     * the only admissible relation between the two parameter curves. */
    const bool parameter_curves_reversed = first_trim.m_bRev3d !=
	edge_orientation_reversed != second_trim.m_bRev3d;
    const double expected_error = parameter_curve_pair_lift_maximum_error(
	first_trim.SurfaceOf(), &first_trim, second_trim.SurfaceOf(),
	&second_trim, parameter_curves_reversed);
    const double alternate_error = parameter_curve_pair_lift_maximum_error(
	first_trim.SurfaceOf(), &first_trim, second_trim.SurfaceOf(),
	&second_trim, !parameter_curves_reversed);
    const ON_3dPoint first_start = boolean_surface_point_at(
	first_trim.SurfaceOf(), first_trim.PointAtStart());
    const ON_3dPoint first_end = boolean_surface_point_at(
	first_trim.SurfaceOf(), first_trim.PointAtEnd());
    const ON_3dPoint second_start = boolean_surface_point_at(
	second_trim.SurfaceOf(), second_trim.PointAtStart());
    const ON_3dPoint second_end = boolean_surface_point_at(
	second_trim.SurfaceOf(), second_trim.PointAtEnd());
    if (!first_start.IsValid() || !first_end.IsValid() ||
	!second_start.IsValid() || !second_end.IsValid())
    {
	return false;
    }
    const double direct_endpoint_error = std::max(
	first_start.DistanceTo(second_start), first_end.DistanceTo(second_end));
    const double reverse_endpoint_error = std::max(
	first_start.DistanceTo(second_end), first_end.DistanceTo(second_start));
    const double expected_endpoint_error = parameter_curves_reversed ?
	reverse_endpoint_error : direct_endpoint_error;
    const double alternate_endpoint_error = parameter_curves_reversed ?
	direct_endpoint_error : reverse_endpoint_error;

    /* Synchronized samples are exact for matching parameter speeds.  If the
     * trims have been independently reparameterized, certify their complete
     * lifted loci instead and retain the endpoint test to make orientation
     * unambiguous. */
    const double paired_tolerance = 2.0 * tolerance;
    bool lifted_loci_reversed = false;
    std::unique_ptr<ON_Curve> first_lifted(pushup_boolean_trim_curve(
	first_trim.SurfaceOf(), first_trim));
    std::unique_ptr<ON_Curve> second_lifted(pushup_boolean_trim_curve(
	second_trim.SurfaceOf(), second_trim));
    const bool lifted_loci_match = first_lifted && second_lifted &&
	first_lifted->IsValid() && second_lifted->IsValid() &&
	brep_curves_coincident(*first_lifted, *second_lifted, paired_tolerance,
	    &lifted_loci_reversed) &&
	lifted_loci_reversed == parameter_curves_reversed;
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean degenerate surface-lift pair %d/%d errors %.17g/%.17g "
	    "for expected/alternate synchronized orientations, endpoint errors "
	    "%.17g/%.17g, loci matched/reversed %d/%d at tolerances "
	    "%.17g/%.17g.\n",
	    first_edge_index, second_edge_index, expected_error,
	    alternate_error, expected_endpoint_error, alternate_endpoint_error,
	    lifted_loci_match, lifted_loci_reversed, tolerance,
	    paired_tolerance);
    }
    if (!(paired_tolerance > tolerance) ||
	!std::isfinite(paired_tolerance) ||
	((!std::isfinite(expected_error) || expected_error > paired_tolerance) &&
	 !lifted_loci_match))
    {
	return false;
    }
    if (!std::isfinite(expected_endpoint_error) ||
	expected_endpoint_error > tolerance ||
	(std::isfinite(alternate_endpoint_error) &&
	 alternate_endpoint_error <= paired_tolerance))
    {
	return false;
    }

    if (!require_shared_ssi_witness) {
	bool projection_reversed = false;
	if (!lifted_loci_match ||
	    !boolean_edges_have_matching_full_projection(brep,
		first_edge_index, second_edge_index, paired_tolerance,
		projection_reversed) ||
	    projection_reversed != edge_orientation_reversed)
	{
	    return false;
	}
	const bool preserve_first =
	    std::isfinite(first_edge.m_tolerance) &&
	    first_edge.m_tolerance >= 0.0 &&
	    (!std::isfinite(second_edge.m_tolerance) ||
	     second_edge.m_tolerance < 0.0 ||
	     first_edge.m_tolerance <= second_edge.m_tolerance);
	canonical_edge_index = preserve_first ? first_edge_index :
	    second_edge_index;
	return true;
    }

    int witness_count = 0;
    for (int curve_index = 0; curve_index < shared_curves.Count();
	 ++curve_index)
    {
	const SharedSSICurve &shared_curve = shared_curves[curve_index];
	if (shared_curve.m_curve == NULL || shared_curve.m_curve->IsClosed()) {
	    continue;
	}

	int first_side = -1;
	int second_side = -1;
	if (is_shared_ssi_edge_candidate(brep, first_edge_index,
		shared_curve.m_face_index[0]) &&
	    is_shared_ssi_edge_candidate(brep, second_edge_index,
		shared_curve.m_face_index[1]))
	{
	    first_side = 0;
	    second_side = 1;
	} else if (is_shared_ssi_edge_candidate(brep, first_edge_index,
		shared_curve.m_face_index[1]) &&
	    is_shared_ssi_edge_candidate(brep, second_edge_index,
		shared_curve.m_face_index[0]))
	{
	    first_side = 1;
	    second_side = 0;
	}
	if (first_side < 0 || second_side < 0) {
	    continue;
	}

	int first_orientation = -1;
	int second_orientation = -1;
	const bool first_lifts = parameter_curve_lifts_to_model_curve(
	    first_trim.SurfaceOf(), &first_trim, shared_curve.m_curve,
	    tolerance, &first_orientation);
	const bool second_lifts = parameter_curve_lifts_to_model_curve(
	    second_trim.SurfaceOf(), &second_trim, shared_curve.m_curve,
	    tolerance, &second_orientation);
	const bool witness_orientation_reversed =
	    first_orientation != second_orientation;
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean degenerate surface-lift witness edges %d/%d "
		"curve %d faces %d/%d lifted %d/%d, orientations %d/%d.\n",
		first_edge_index, second_edge_index, curve_index,
		shared_curve.m_face_index[0], shared_curve.m_face_index[1],
		first_lifts, second_lifts, first_orientation,
		second_orientation);
	}
	if (!first_lifts || !second_lifts ||
	    witness_orientation_reversed != parameter_curves_reversed)
	{
	    continue;
	}

	++witness_count;
	/* Preserve the edge carried by the first SSI/source operand.  Its curve
	 * is an original source boundary in the degeneracies this repair handles;
	 * the peer intersection edge is the independently fitted approximation. */
	canonical_edge_index = first_side == 0 ? first_edge_index :
	    second_edge_index;
    }

    return witness_count == 1;
}


static bool
boolean_degenerate_source_edge_pair_candidate(
    const ON_Brep *brep,
    int first_edge_index,
    int second_edge_index,
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    const ON_ClassArray<SharedSSICurve> &shared_curves,
    double tolerance,
    BooleanDegenerateSourceEdgePair &candidate)
{
    candidate = BooleanDegenerateSourceEdgePair();
    if (brep == NULL || brep1 == NULL || brep2 == NULL ||
	first_edge_index == second_edge_index || !(tolerance > 0.0) ||
	!std::isfinite(tolerance) ||
	!is_active_boolean_naked_edge(brep, first_edge_index) ||
	!is_active_boolean_naked_edge(brep, second_edge_index))
    {
	return false;
    }

    const ON_BrepEdge &first_edge = brep->m_E[first_edge_index];
    const ON_BrepEdge &second_edge = brep->m_E[second_edge_index];
    const bool directly_aligned =
	first_edge.m_vi[0] == second_edge.m_vi[0] &&
	first_edge.m_vi[1] == second_edge.m_vi[1];
    const bool oppositely_aligned =
	first_edge.m_vi[0] == second_edge.m_vi[1] &&
	first_edge.m_vi[1] == second_edge.m_vi[0];
    if (directly_aligned == oppositely_aligned) {
	return false;
    }
    const auto rejected = [&](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean degenerate source-edge pair %d/%d rejected: %s.\n",
		first_edge_index, second_edge_index, reason);
	}
	return false;
    };

    const ON_BoundingBox first_bounds = first_edge.BoundingBox();
    const ON_BoundingBox second_bounds = second_edge.BoundingBox();
    if (!first_bounds.IsValid() || !second_bounds.IsValid())
    {
	return rejected("a curve locus has invalid bounds");
    }
    const bool sub_tolerance_loci =
	first_bounds.Diagonal().Length() <= tolerance &&
	second_bounds.Diagonal().Length() <= tolerance;

    bool curves_reversed = false;
    const bool edge_curves_certified = brep_curves_coincident(first_edge,
	second_edge, tolerance, &curves_reversed) &&
	curves_reversed == oppositely_aligned;
    const bool edge_orientation_reversed = oppositely_aligned;

    const ON_BrepTrim &first_trim = brep->m_T[first_edge.m_ti[0]];
    const ON_BrepTrim &second_trim = brep->m_T[second_edge.m_ti[0]];
    const int first_face_index = first_trim.FaceIndexOf();
    const int second_face_index = second_trim.FaceIndexOf();
    if (first_face_index < 0 || first_face_index >= brep->m_F.Count() ||
	second_face_index < 0 || second_face_index >= brep->m_F.Count() ||
	first_face_index == second_face_index)
    {
	return rejected("faces are invalid or identical");
    }

    const ON_BrepFace &first_face = brep->m_F[first_face_index];
    const ON_BrepFace &second_face = brep->m_F[second_face_index];
    const bool first_sense = first_trim.m_bRev3d != first_face.m_bRev;
    const bool attached_second_reversed = second_trim.m_bRev3d !=
	edge_orientation_reversed;
    const bool second_sense = attached_second_reversed != second_face.m_bRev;
    if (first_sense == second_sense) {
	return rejected("face-relative trim senses agree");
    }

    /* A complete long seam is not a degenerate edge and must not be joined
     * merely because two result curves happen to be close.  It is safe to
     * reconcile when exactly one edge follows a recorded SSI and both curves
     * cover one another completely with the required opposite traversal.
     * This addresses independently lifted representations of the same exact
     * intersection without weakening the generic feature-size stitch guard. */
    if (!sub_tolerance_loci) {
	int ssi_edge_index = -1;
	const bool edge_curve_witness = edge_curves_certified &&
	    boolean_degenerate_pair_has_unique_ssi_witness(brep,
		first_edge_index, second_edge_index, shared_curves, tolerance,
		edge_orientation_reversed, ssi_edge_index);
	if (!edge_curve_witness &&
	    !boolean_degenerate_pair_has_surface_lift_witness(brep,
		first_edge_index, second_edge_index, shared_curves, tolerance,
		edge_orientation_reversed, true, ssi_edge_index))
	{
	    if (!boolean_degenerate_pair_has_surface_lift_witness(brep,
		    first_edge_index, second_edge_index, shared_curves,
		    tolerance, edge_orientation_reversed, false,
		    ssi_edge_index))
	    {
		return rejected("a nondegenerate pair has no unique curve, SSI, or complete surface-lift witness");
	    }
	}
	candidate.m_canonical_edge_index = ssi_edge_index;
	candidate.m_duplicate_edge_index =
	    ssi_edge_index == first_edge_index ? second_edge_index :
	    first_edge_index;
	candidate.m_reversed = edge_orientation_reversed;
	candidate.m_tolerance = edge_curve_witness ? tolerance :
	    2.0 * tolerance;
	return true;
    }

    if (!edge_curves_certified) {
	int ssi_edge_index = -1;
	if (!boolean_degenerate_pair_has_surface_lift_witness(brep,
		first_edge_index, second_edge_index, shared_curves, tolerance,
		edge_orientation_reversed, true, ssi_edge_index))
	{
	    return rejected("curve loci disagree and no unique surface-lift SSI witness exists");
	}
	candidate.m_canonical_edge_index = ssi_edge_index;
	candidate.m_duplicate_edge_index =
	    ssi_edge_index == first_edge_index ? second_edge_index :
	    first_edge_index;
	candidate.m_reversed = edge_orientation_reversed;
	candidate.m_tolerance = 2.0 * tolerance;
	return true;
    }

    /* Require unique source provenance.  Exactly one output face must be an
     * original boundary face adjacent to the source edge, and both candidate
     * edges must cover the same interval of that source edge. */
    const int first_source_face = first_face.m_face_user.i -
	FACE_SOURCE_TAG_OFFSET;
    const int second_source_face = second_face.m_face_user.i -
	FACE_SOURCE_TAG_OFFSET;
    const ON_Brep *source_breps[2] = {brep1, brep2};
    const int source_face_offsets[2] = {0, brep1->m_F.Count()};
    int match_count = 0;
    for (int operand = 0; operand < 2; ++operand) {
	const ON_Brep *source_brep = source_breps[operand];
	for (int source_edge_index = 0;
	     source_edge_index < source_brep->m_E.Count();
	     ++source_edge_index)
	{
	    const ON_BrepEdge &source_edge =
		source_brep->m_E[source_edge_index];
	    if (source_edge.m_edge_index != source_edge_index ||
		source_edge.m_ti.Count() != 2 || source_edge.IsClosed() ||
		source_edge.m_vi[0] < 0 || source_edge.m_vi[1] < 0 ||
		source_edge.m_vi[0] == source_edge.m_vi[1])
	    {
		continue;
	    }

	    int adjacent_faces[2] = {-1, -1};
	    bool valid_source_edge = true;
	    for (int side = 0; side < 2; ++side) {
		const int source_trim_index = source_edge.m_ti[side];
		if (source_trim_index < 0 ||
		    source_trim_index >= source_brep->m_T.Count())
		{
		    valid_source_edge = false;
		    break;
		}
		const int local_face =
		    source_brep->m_T[source_trim_index].FaceIndexOf();
		if (local_face < 0 || local_face >= source_brep->m_F.Count()) {
		    valid_source_edge = false;
		    break;
		}
		adjacent_faces[side] = local_face + source_face_offsets[operand];
	    }
	    if (!valid_source_edge || adjacent_faces[0] == adjacent_faces[1]) {
		continue;
	    }

	    bool first_is_source_boundary = false;
	    bool second_is_source_boundary = false;
	    for (int side = 0; side < 2; ++side) {
		const int source_trim_index = source_edge.m_ti[side];
		const ON_BrepTrim &source_trim =
		    source_brep->m_T[source_trim_index];
		const ON_BrepFace &source_face =
		    source_brep->m_F[source_trim.FaceIndexOf()];
		if (first_source_face == adjacent_faces[side] &&
		    boolean_output_trim_follows_source_trim(brep,
			first_edge_index, source_face, source_trim))
		{
		    first_is_source_boundary = true;
		}
		if (second_source_face == adjacent_faces[side] &&
		    boolean_output_trim_follows_source_trim(brep,
			second_edge_index, source_face, source_trim))
		{
		    second_is_source_boundary = true;
		}
	    }
	    if (first_is_source_boundary == second_is_source_boundary) {
		continue;
	    }

	    BooleanSourceEdgeUse first_use;
	    BooleanSourceEdgeUse second_use;
	    const bool first_projected = project_boolean_edge_to_source_edge(brep,
		first_edge_index, source_edge, tolerance, first_use);
	    const bool second_projected = project_boolean_edge_to_source_edge(brep,
		second_edge_index, source_edge, tolerance, second_use);
	    if (!first_projected || !second_projected)
	    {
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean degenerate source-edge pair %d/%d operand %d "
			"edge %d projected %d/%d.\n", first_edge_index,
			second_edge_index, operand, source_edge_index,
			first_projected, second_projected);
		}
		continue;
	    }

	    const double normalized_tolerance =
		boolean_source_edge_normalized_tolerance(source_edge, tolerance);
	    const double second_start = edge_orientation_reversed ?
		second_use.m_source_end : second_use.m_source_start;
	    const double second_end = edge_orientation_reversed ?
		second_use.m_source_start : second_use.m_source_end;
	    if (!(normalized_tolerance > 0.0) ||
		fabs(first_use.m_source_start - second_start) >
		    normalized_tolerance ||
		fabs(first_use.m_source_end - second_end) >
		    normalized_tolerance)
	    {
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean degenerate source-edge pair %d/%d operand %d "
			"edge %d intervals %.17g -> %.17g and %.17g -> %.17g "
			"exceed %.17g.\n", first_edge_index, second_edge_index,
			operand, source_edge_index, first_use.m_source_start,
			first_use.m_source_end, second_start, second_end,
			normalized_tolerance);
		}
		continue;
	    }

	    ++match_count;
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Boolean degenerate source-edge pair %d/%d matched operand "
		    "%d edge %d through output edge %s, intervals %.17g -> "
		    "%.17g and %.17g -> %.17g.\n", first_edge_index,
		    second_edge_index, operand, source_edge_index,
		    first_is_source_boundary ? "first" : "second",
		    first_use.m_source_start, first_use.m_source_end,
		    second_start, second_end);
	    }
	    candidate.m_canonical_edge_index = first_is_source_boundary ?
		first_edge_index : second_edge_index;
	    candidate.m_duplicate_edge_index = first_is_source_boundary ?
		second_edge_index : first_edge_index;
	    candidate.m_operand = operand;
	    candidate.m_source_edge_index = source_edge_index;
	    candidate.m_reversed = edge_orientation_reversed;
	    candidate.m_tolerance = tolerance;
	}
    }
    if (match_count == 0) {
	int ssi_edge_index = -1;
	if (!boolean_degenerate_pair_has_unique_ssi_witness(brep,
		first_edge_index, second_edge_index, shared_curves, tolerance,
		oppositely_aligned, ssi_edge_index))
	{
	    return rejected("no unique source interval or SSI witness matched");
	}
	candidate.m_canonical_edge_index = ssi_edge_index;
	candidate.m_duplicate_edge_index = ssi_edge_index == first_edge_index ?
	    second_edge_index : first_edge_index;
	candidate.m_reversed = edge_orientation_reversed;
	candidate.m_tolerance = tolerance;
	return true;
    }
    if (match_count != 1) {
	return rejected("multiple source intervals matched");
    }
    return true;
}


static bool
repair_boolean_degenerate_source_edge_pairs(
    ON_Brep *brep,
    const ON_Brep *brep1,
    const ON_Brep *brep2,
    const ON_ClassArray<SharedSSICurve> &shared_curves)
{
    if (brep == NULL || brep1 == NULL || brep2 == NULL) {
	return false;
    }

    const double tolerance = 2.0 * boolean_model_repair_tolerance(
	brep->BoundingBox());
    if (!(tolerance > 0.0) || !std::isfinite(tolerance)) {
	return false;
    }

    std::vector<BooleanDegenerateSourceEdgePair> candidates;
    std::vector<int> match_counts(static_cast<size_t>(brep->m_E.Count()), 0);
    for (int first_edge_index = 0;
	 first_edge_index < brep->m_E.Count(); ++first_edge_index)
    {
	for (int second_edge_index = first_edge_index + 1;
	     second_edge_index < brep->m_E.Count(); ++second_edge_index)
	{
	    if (DEBUG_BREP_BOOLEAN &&
		is_active_boolean_naked_edge(brep, first_edge_index) &&
		is_active_boolean_naked_edge(brep, second_edge_index))
	    {
		const ON_BrepEdge &first_edge = brep->m_E[first_edge_index];
		const ON_BrepEdge &second_edge = brep->m_E[second_edge_index];
		const bool same_vertices =
		    (first_edge.m_vi[0] == second_edge.m_vi[0] &&
		     first_edge.m_vi[1] == second_edge.m_vi[1]) ||
		    (first_edge.m_vi[0] == second_edge.m_vi[1] &&
		     first_edge.m_vi[1] == second_edge.m_vi[0]);
		if (same_vertices) {
		    const ON_BrepTrim &first_trim =
			brep->m_T[first_edge.m_ti[0]];
		    const ON_BrepTrim &second_trim =
			brep->m_T[second_edge.m_ti[0]];
		    const int first_face = first_trim.FaceIndexOf();
		    const int second_face = second_trim.FaceIndexOf();
		    bu_log("Boolean degenerate source-edge probe edges %d/%d, "
			"vertices %d/%d and %d/%d, faces %d/%d (sources "
			"%d/%d), lengths %.17g/%.17g.\n", first_edge_index,
			second_edge_index, first_edge.m_vi[0], first_edge.m_vi[1],
			second_edge.m_vi[0], second_edge.m_vi[1], first_face,
			second_face, first_face >= 0 ?
			brep->m_F[first_face].m_face_user.i -
			    FACE_SOURCE_TAG_OFFSET : -1,
			second_face >= 0 ?
			brep->m_F[second_face].m_face_user.i -
			    FACE_SOURCE_TAG_OFFSET : -1,
			first_edge.BoundingBox().Diagonal().Length(),
			second_edge.BoundingBox().Diagonal().Length());
		}
	    }
	    BooleanDegenerateSourceEdgePair candidate;
	    if (!boolean_degenerate_source_edge_pair_candidate(brep,
		    first_edge_index, second_edge_index, brep1, brep2,
		    shared_curves, tolerance, candidate))
	    {
		continue;
	    }
	    candidates.push_back(candidate);
	    ++match_counts[static_cast<size_t>(first_edge_index)];
	    ++match_counts[static_cast<size_t>(second_edge_index)];
	}
    }

    /* Ambiguous candidates are left untouched.  Requiring one partner per
     * edge also makes all accepted repairs disjoint before topology changes
     * begin. */
    std::vector<BooleanDegenerateSourceEdgePair> repairs;
    for (size_t candidate_index = 0;
	 candidate_index < candidates.size(); ++candidate_index)
    {
	const BooleanDegenerateSourceEdgePair &candidate =
	    candidates[candidate_index];
	if (match_counts[static_cast<size_t>(candidate.m_canonical_edge_index)] ==
		1 &&
	    match_counts[static_cast<size_t>(candidate.m_duplicate_edge_index)] ==
		1)
	{
	    repairs.push_back(candidate);
	}
    }
    if (repairs.empty()) {
	return true;
    }

    /* Perform every repair on a copy and publish it only after topology and
     * tolerance validation succeeds. */
    const int naked_before = boolean_active_naked_edge_count(brep);
    const int edge_count_before = brep->m_E.Count();
    ON_Brep repaired(*brep);
    for (size_t repair_index = 0; repair_index < repairs.size();
	 ++repair_index)
    {
	const BooleanDegenerateSourceEdgePair &repair = repairs[repair_index];
	if (!(repair.m_tolerance > 0.0) ||
	    !std::isfinite(repair.m_tolerance))
	{
	    return false;
	}
	if (!is_active_boolean_naked_edge(&repaired,
		repair.m_canonical_edge_index) ||
	    !is_active_boolean_naked_edge(&repaired,
		repair.m_duplicate_edge_index))
	{
	    return false;
	}

	ON_BrepEdge &canonical_edge =
	    repaired.m_E[repair.m_canonical_edge_index];
	ON_BrepEdge &duplicate_edge =
	    repaired.m_E[repair.m_duplicate_edge_index];
	const int canonical_trim_index = canonical_edge.m_ti[0];
	const int duplicate_trim_index = duplicate_edge.m_ti[0];
	ON_BrepTrim &canonical_trim = repaired.m_T[canonical_trim_index];
	ON_BrepTrim &duplicate_trim = repaired.m_T[duplicate_trim_index];
	const bool duplicate_trim_reversed = duplicate_trim.m_bRev3d !=
	    repair.m_reversed;
	if (!duplicate_trim.RemoveFromEdge(false, false) ||
	    !duplicate_trim.AttachToEdge(repair.m_canonical_edge_index,
		duplicate_trim_reversed) ||
	    !set_boolean_trim_edge_direction(&repaired, duplicate_trim,
		repair.m_canonical_edge_index, duplicate_trim_reversed))
	{
	    return false;
	}

	canonical_trim.m_type = ON_BrepTrim::mated;
	duplicate_trim.m_type = ON_BrepTrim::mated;
	/* The full-curve proof above certifies this conservative bound. */
	canonical_edge.m_tolerance = boolean_measured_tolerance(
	    repair.m_tolerance);
	canonical_edge.m_edge_user.i = BOOLEAN_CERTIFIED_EDGE_TOLERANCE_TAG;
	repaired.DeleteEdge(duplicate_edge, false);
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean degenerate source-edge pair %d/%d uses operand %d "
		"edge %d at tolerance %.17g.\n",
		repair.m_canonical_edge_index, repair.m_duplicate_edge_index,
		repair.m_operand, repair.m_source_edge_index,
		repair.m_tolerance);
	}
    }

    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    const bool compacted = repaired.Compact();
    if (compacted) {
	repaired.SetTrimBoundingBoxes(false);
    }
    const bool trim_iso_flags_set = compacted && repaired.SetTrimIsoFlags();
    const bool trim_types_set = trim_iso_flags_set &&
	repaired.SetTrimTypeFlags(false);
    const bool vertex_tolerances_set = trim_types_set &&
	repaired.SetVertexTolerances(false);
    const bool edge_tolerances_set = vertex_tolerances_set &&
	set_boolean_edge_tolerances(&repaired);
    const bool trim_tolerances_set = edge_tolerances_set &&
	set_boolean_trim_tolerances(&repaired);
    const bool valid = trim_tolerances_set && repaired.IsValid(&validation_log);
    const int naked_after = boolean_active_naked_edge_count(&repaired);
    const bool final_pair_is_solid = naked_before != 2 ||
	(valid && naked_after == 0 && repaired.IsSolid());
    if (!valid || naked_before < 2 * static_cast<int>(repairs.size()) ||
	naked_after != naked_before - 2 * static_cast<int>(repairs.size()) ||
	!final_pair_is_solid ||
	repaired.m_E.Count() != edge_count_before -
	    static_cast<int>(repairs.size()))
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_String message(validation_text);
	    bu_log("Boolean degenerate source-edge repair rolled back: valid "
		"%d, naked %d -> %d, edges %d -> %d%s%s.\n", valid,
		naked_before, naked_after, edge_count_before, repaired.m_E.Count(),
		message.Array() && message.Array()[0] ? ": " : "",
		message.Array() ? message.Array() : "");
	}
	return true;
    }

    *brep = repaired;
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean degenerate source-edge repair completed %zu pair%s.\n",
	    repairs.size(), repairs.size() == 1 ? "" : "s");
    }
    return true;
}


static SharedSSIEdgeRepairResult
repair_boolean_naked_hairpin_pair(
    ON_Brep *brep,
    int first_trim_index,
    int second_trim_index,
    double tolerance)
{
    if (brep == NULL || first_trim_index < 0 ||
	first_trim_index >= brep->m_T.Count() || second_trim_index < 0 ||
	second_trim_index >= brep->m_T.Count() ||
	first_trim_index == second_trim_index)
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const ON_BrepTrim &first_trim = brep->m_T[first_trim_index];
    const ON_BrepTrim &second_trim = brep->m_T[second_trim_index];
    if (first_trim.m_trim_index != first_trim_index ||
	second_trim.m_trim_index != second_trim_index ||
	first_trim.m_li < 0 || first_trim.m_li != second_trim.m_li ||
	first_trim.FaceIndexOf() != second_trim.FaceIndexOf() ||
	first_trim.m_vi[0] < 0 || first_trim.m_vi[1] < 0 ||
	first_trim.m_vi[0] == first_trim.m_vi[1] ||
	first_trim.m_vi[0] != second_trim.m_vi[1] ||
	first_trim.m_vi[1] != second_trim.m_vi[0] ||
	first_trim.m_ei < 0 || second_trim.m_ei < 0 ||
	first_trim.m_ei == second_trim.m_ei ||
	!is_active_boolean_naked_edge(brep, first_trim.m_ei) ||
	!is_active_boolean_naked_edge(brep, second_trim.m_ei))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const ON_BrepLoop &loop = brep->m_L[first_trim.m_li];
    if (loop.m_loop_index != first_trim.m_li || loop.m_ti.Count() < 4 ||
	boolean_loop_trim_position(loop, first_trim_index) < 0 ||
	brep->NextTrim(first_trim_index) != second_trim_index)
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }
    const int previous_trim_index = brep->PrevTrim(first_trim_index);
    const int next_trim_index = brep->NextTrim(second_trim_index);
    if (previous_trim_index < 0 || next_trim_index < 0 ||
	previous_trim_index == first_trim_index ||
	previous_trim_index == second_trim_index ||
	next_trim_index == first_trim_index ||
	next_trim_index == second_trim_index ||
	previous_trim_index == next_trim_index)
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const int base_vertex = first_trim.m_vi[0];
    const int tip_vertex = first_trim.m_vi[1];
    if (base_vertex >= brep->m_V.Count() || tip_vertex >= brep->m_V.Count()) {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	const ON_BrepEdge &edge = brep->m_E[edge_index];
	if (edge.m_edge_index != edge_index ||
	    edge_index == first_trim.m_ei || edge_index == second_trim.m_ei)
	{
	    continue;
	}
	if (edge.m_vi[0] == tip_vertex || edge.m_vi[1] == tip_vertex) {
	    return SHARED_SSI_EDGE_REPAIR_SKIPPED;
	}
    }

    const ON_BrepEdge &first_edge = brep->m_E[first_trim.m_ei];
    const ON_BrepEdge &second_edge = brep->m_E[second_trim.m_ei];
    const ON_3dPoint center = brep->m_V[base_vertex].Point();
    const ON_3dPoint tip = brep->m_V[tip_vertex].Point();
    if (!(tolerance > 0.0) || !std::isfinite(tolerance) ||
	!center.IsValid() || !tip.IsValid())
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    double proof_tolerance = std::min(tolerance, INTERSECTION_TOL);
    bool certified = false;
    while (true) {
	bool curves_reversed = false;
	certified = tip.DistanceTo(center) <= proof_tolerance &&
	    brep_curve_locus_within_ball(first_edge, center,
		proof_tolerance) &&
	    brep_curve_locus_within_ball(second_edge, center,
		proof_tolerance) &&
	    brep_curves_coincident(first_edge, second_edge,
		proof_tolerance, &curves_reversed);
	if (certified || proof_tolerance >= tolerance) {
	    break;
	}
	proof_tolerance = std::min(tolerance, 2.0 * proof_tolerance);
    }
    if (!certified) {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    const int naked_before = boolean_active_naked_edge_count(brep);
    const int edge_count_before = brep->m_E.Count();
    const int trim_count_before = brep->m_T.Count();
    const int vertex_count_before = brep->m_V.Count();
    const int face_count_before = brep->m_F.Count();
    const int loop_count_before = brep->m_L.Count();
    const int surface_count_before = brep->m_S.Count();
    ON_Brep repaired(*brep);

    repaired.DeleteTrim(repaired.m_T[second_trim_index], false);
    repaired.DeleteTrim(repaired.m_T[first_trim_index], false);
    repaired.DeleteEdge(repaired.m_E[second_trim.m_ei], false);
    repaired.DeleteEdge(repaired.m_E[first_trim.m_ei], false);
    if (repaired.m_V[tip_vertex].m_vertex_index != tip_vertex ||
	repaired.m_V[tip_vertex].EdgeCount() != 0)
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }
    repaired.DeleteVertex(repaired.m_V[tip_vertex]);
    if (!close_boolean_endpoint_spike_gap(repaired, previous_trim_index,
	    next_trim_index, true, center, proof_tolerance))
    {
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    const bool compacted = repaired.Compact();
    if (compacted) {
	repaired.SetTrimBoundingBoxes(false);
    }
    const bool trim_iso_flags_set = compacted && repaired.SetTrimIsoFlags();
    const bool trim_types_set = trim_iso_flags_set &&
	repaired.SetTrimTypeFlags(false);
    const bool vertex_tolerances_set = trim_types_set &&
	repaired.SetVertexTolerances(false);
    const bool edge_tolerances_set = vertex_tolerances_set &&
	set_boolean_edge_tolerances(&repaired);
    const bool trim_tolerances_set = edge_tolerances_set &&
	set_boolean_trim_tolerances(&repaired);
    const bool valid = trim_tolerances_set && repaired.IsValid(&validation_log);
    const int naked_after = boolean_active_naked_edge_count(&repaired);
    if (!valid || naked_before < 2 || naked_after != naked_before - 2 ||
	repaired.m_E.Count() != edge_count_before - 2 ||
	repaired.m_T.Count() != trim_count_before - 2 ||
	repaired.m_V.Count() != vertex_count_before - 1 ||
	repaired.m_F.Count() != face_count_before ||
	repaired.m_L.Count() != loop_count_before ||
	repaired.m_S.Count() != surface_count_before)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_String message(validation_text);
	    bu_log("Boolean naked hairpin repair rolled back: valid %d, "
		"naked %d -> %d, edges %d -> %d, trims %d -> %d, "
		"vertices %d -> %d, faces %d -> %d, loops %d -> %d, "
		"surfaces %d -> %d%s%s.\n", valid,
		naked_before, naked_after, edge_count_before,
		repaired.m_E.Count(), trim_count_before, repaired.m_T.Count(),
		vertex_count_before, repaired.m_V.Count(), face_count_before,
		repaired.m_F.Count(), loop_count_before, repaired.m_L.Count(),
		surface_count_before, repaired.m_S.Count(),
		message.Array() && message.Array()[0] ? ": " : "",
		message.Array() ? message.Array() : "");
	}
	return SHARED_SSI_EDGE_REPAIR_SKIPPED;
    }

    *brep = repaired;
    return SHARED_SSI_EDGE_REPAIR_COMPLETE;
}


static bool
repair_boolean_naked_hairpins(ON_Brep *brep)
{
    if (brep == NULL) {
	return false;
    }

    /* Each independently fitted side of the isolated hairpin may carry the
     * model repair error.  The pair routine still requires both complete
     * loci inside one endpoint ball and validates its transactional result. */
    const double tolerance = 2.0 * boolean_model_repair_tolerance(
	brep->BoundingBox());
    int repaired_count = 0;
    while (true) {
	bool repaired_one = false;
	for (int loop_index = 0;
	     loop_index < brep->m_L.Count() && !repaired_one; ++loop_index)
	{
	    const ON_BrepLoop &loop = brep->m_L[loop_index];
	    if (loop.m_loop_index != loop_index || loop.m_ti.Count() < 4) {
		continue;
	    }
	    for (int trim_position = 0; trim_position < loop.m_ti.Count();
		 ++trim_position)
	    {
		const int first_trim_index = loop.m_ti[trim_position];
		const int second_trim_index = loop.m_ti[
		    (trim_position + 1) % loop.m_ti.Count()];
		const SharedSSIEdgeRepairResult result =
		    repair_boolean_naked_hairpin_pair(brep, first_trim_index,
			second_trim_index, tolerance);
		if (result == SHARED_SSI_EDGE_REPAIR_FAILURE) {
		    return false;
		}
		if (result == SHARED_SSI_EDGE_REPAIR_COMPLETE) {
		    repaired_one = true;
		    ++repaired_count;
		    break;
		}
	    }
	}
	if (!repaired_one) {
	    break;
	}
    }

    if (DEBUG_BREP_BOOLEAN && repaired_count > 0) {
	bu_log("Boolean naked hairpin repair completed %d pair%s.\n",
	    repaired_count, repaired_count == 1 ? "" : "s");
    }
    return true;
}


enum BooleanMissingCapRepairResult {
    BOOLEAN_MISSING_CAP_REPAIR_SKIPPED,
    BOOLEAN_MISSING_CAP_REPAIR_COMPLETE,
    BOOLEAN_MISSING_CAP_REPAIR_FAILURE
};


static const unsigned int BOOLEAN_CAP_MAX_SUBDIVISION_DEPTH = 48;
static const size_t BOOLEAN_CAP_MAX_SUBDIVISIONS = 4096;
static const size_t BOOLEAN_CAP_MAX_EDGES = 64;


static bool
boolean_bezier_locus_within_plane(const ON_BezierCurve &curve,
	const ON_Plane &plane, double tolerance, unsigned int depth,
	size_t &subdivisions)
{
    bool hull_is_inside = true;
    for (int control_index = 0; control_index < curve.CVCount();
	 ++control_index)
    {
	ON_3dPoint control;
	const double weight = curve.Weight(control_index);
	if (!(weight > 0.0) || !std::isfinite(weight) ||
	    !curve.GetCV(control_index, control) || !control.IsValid())
	{
	    return false;
	}
	const double distance = fabs(plane.DistanceTo(control));
	if (!std::isfinite(distance)) {
	    return false;
	}
	hull_is_inside = hull_is_inside && distance <= tolerance;
    }

    /* With positive rational weights the curve is contained in the convex
     * hull of its Euclidean control points.  A planar slab is convex, so this
     * proves containment of the complete locus rather than a point sample. */
    if (hull_is_inside) {
	return true;
    }

    if (depth >= BOOLEAN_CAP_MAX_SUBDIVISION_DEPTH ||
	++subdivisions > BOOLEAN_CAP_MAX_SUBDIVISIONS)
    {
	return false;
    }
    ON_BezierCurve left;
    ON_BezierCurve right;
    return curve.Split(0.5, left, right) &&
	boolean_bezier_locus_within_plane(left, plane, tolerance, depth + 1,
	    subdivisions) &&
	boolean_bezier_locus_within_plane(right, plane, tolerance, depth + 1,
	    subdivisions);
}


static bool
boolean_curve_locus_within_plane(const ON_Curve &curve,
	const ON_Plane &plane, double tolerance)
{
    if (!plane.IsValid() || !(tolerance > 0.0) ||
	!std::isfinite(tolerance) || curve.Dimension() != 3)
    {
	return false;
    }

    ON_NurbsCurve nurbs;
    if (curve.GetNurbForm(nurbs) <= 0 || !nurbs.IsValid() ||
	nurbs.Order() < 2 || nurbs.CVCount() < nurbs.Order())
    {
	return false;
    }

    bool found_span = false;
    size_t subdivisions = 0;
    for (int span = 0; span <= nurbs.CVCount() - nurbs.Order(); ++span) {
	const int knot = span + nurbs.Order() - 2;
	if (!(nurbs.Knot(knot) < nurbs.Knot(knot + 1))) {
	    continue;
	}
	found_span = true;
	ON_BezierCurve bezier;
	if (!nurbs.ConvertSpanToBezier(span, bezier) ||
	    !boolean_bezier_locus_within_plane(bezier, plane, tolerance, 0,
		subdivisions))
	{
	    return false;
	}
    }
    return found_span;
}


static bool
collect_boolean_naked_edge_cycle(const ON_Brep *brep,
	std::vector<int> &ordered_edges, std::vector<int> &ordered_vertices,
	std::vector<bool> &edge_reversed)
{
    ordered_edges.clear();
    ordered_vertices.clear();
    edge_reversed.clear();
    const int naked_edge_count = boolean_active_naked_edge_count(brep);
    if (brep == NULL || naked_edge_count < 3 ||
	static_cast<size_t>(naked_edge_count) > BOOLEAN_CAP_MAX_EDGES)
    {
	return false;
    }

    std::vector<int> naked_edges;
    std::set<int> trim_indices;
    std::set<int> vertex_indices;
    std::map<int, int> vertex_degrees;
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	if (!is_active_boolean_naked_edge(brep, edge_index)) {
	    continue;
	}
	const ON_BrepEdge &edge = brep->m_E[edge_index];
	if (!trim_indices.insert(edge.m_ti[0]).second) {
	    return false;
	}
	naked_edges.push_back(edge_index);
	vertex_indices.insert(edge.m_vi[0]);
	vertex_indices.insert(edge.m_vi[1]);
	++vertex_degrees[edge.m_vi[0]];
	++vertex_degrees[edge.m_vi[1]];
    }
    if (naked_edges.size() != static_cast<size_t>(naked_edge_count) ||
	trim_indices.size() != naked_edges.size() ||
	vertex_indices.size() != naked_edges.size())
    {
	return false;
    }
    for (std::map<int, int>::const_iterator degree = vertex_degrees.begin();
	 degree != vertex_degrees.end(); ++degree)
    {
	if (degree->second != 2) {
	    return false;
	}
    }

    /* Edge discovery is in index order.  Start with the lowest edge in its
     * native direction and thereafter take the sole unused incident edge. */
    std::set<int> unused(naked_edges.begin(), naked_edges.end());
    const int first_edge_index = naked_edges.front();
    const ON_BrepEdge &first_edge = brep->m_E[first_edge_index];
    const int first_vertex = first_edge.m_vi[0];
    int current_vertex = first_edge.m_vi[1];
    ordered_edges.push_back(first_edge_index);
    ordered_vertices.push_back(first_vertex);
    edge_reversed.push_back(false);
    unused.erase(first_edge_index);

    while (!unused.empty()) {
	int next_edge_index = -1;
	for (std::set<int>::const_iterator candidate = unused.begin();
	     candidate != unused.end(); ++candidate)
	{
	    const ON_BrepEdge &edge = brep->m_E[*candidate];
	    if (edge.m_vi[0] == current_vertex || edge.m_vi[1] == current_vertex) {
		if (next_edge_index >= 0) {
		    return false;
		}
		next_edge_index = *candidate;
	    }
	}
	if (next_edge_index < 0) {
	    return false;
	}

	const ON_BrepEdge &edge = brep->m_E[next_edge_index];
	const bool reversed = edge.m_vi[1] == current_vertex;
	const int next_vertex = edge.m_vi[reversed ? 0 : 1];
	if (next_vertex == first_vertex && unused.size() != 1) {
	    return false;
	}
	if (next_vertex != first_vertex &&
	    std::find(ordered_vertices.begin(), ordered_vertices.end(),
		next_vertex) != ordered_vertices.end())
	{
	    return false;
	}
	ordered_edges.push_back(next_edge_index);
	ordered_vertices.push_back(current_vertex);
	edge_reversed.push_back(reversed);
	current_vertex = next_vertex;
	unused.erase(next_edge_index);
    }

    return ordered_edges.size() == naked_edges.size() &&
	ordered_vertices.size() == naked_edges.size() &&
	edge_reversed.size() == naked_edges.size() &&
	current_vertex == first_vertex;
}


static double
boolean_point_segment_distance_2d(const ON_2dPoint &point,
	const ON_2dPoint &start, const ON_2dPoint &end)
{
    const double dx = end.x - start.x;
    const double dy = end.y - start.y;
    const double length_squared = dx * dx + dy * dy;
    if (!(length_squared > 0.0) || !std::isfinite(length_squared)) {
	return std::numeric_limits<double>::infinity();
    }
    double parameter = ((point.x - start.x) * dx +
	(point.y - start.y) * dy) / length_squared;
    parameter = std::max(0.0, std::min(1.0, parameter));
    return std::hypot(point.x - (start.x + parameter * dx),
	point.y - (start.y + parameter * dy));
}


static double
boolean_orient_2d(const ON_2dPoint &first, const ON_2dPoint &second,
	const ON_2dPoint &third)
{
    return (second.x - first.x) * (third.y - first.y) -
	(second.y - first.y) * (third.x - first.x);
}


static bool
boolean_segments_intersect_2d(const ON_2dPoint &first_start,
	const ON_2dPoint &first_end, const ON_2dPoint &second_start,
	const ON_2dPoint &second_end)
{
    const double first_second_start = boolean_orient_2d(first_start,
	first_end, second_start);
    const double first_second_end = boolean_orient_2d(first_start,
	first_end, second_end);
    const double second_first_start = boolean_orient_2d(second_start,
	second_end, first_start);
    const double second_first_end = boolean_orient_2d(second_start,
	second_end, first_end);
    if (((first_second_start > 0.0 && first_second_end < 0.0) ||
	 (first_second_start < 0.0 && first_second_end > 0.0)) &&
	((second_first_start > 0.0 && second_first_end < 0.0) ||
	 (second_first_start < 0.0 && second_first_end > 0.0)))
    {
	return true;
    }

    const double first_length = std::hypot(first_end.x - first_start.x,
	first_end.y - first_start.y);
    const double second_length = std::hypot(second_end.x - second_start.x,
	second_end.y - second_start.y);
    const double scale = std::max(1.0, first_length + second_length);
    const double distance_tolerance = 128.0 *
	std::numeric_limits<double>::epsilon() * scale;
    const double first_area_tolerance = distance_tolerance * first_length;
    const double second_area_tolerance = distance_tolerance * second_length;
    return (fabs(first_second_start) <= first_area_tolerance &&
	boolean_point_segment_distance_2d(second_start, first_start,
	    first_end) <= distance_tolerance) ||
	(fabs(first_second_end) <= first_area_tolerance &&
	 boolean_point_segment_distance_2d(second_end, first_start,
	     first_end) <= distance_tolerance) ||
	(fabs(second_first_start) <= second_area_tolerance &&
	 boolean_point_segment_distance_2d(first_start, second_start,
	     second_end) <= distance_tolerance) ||
	(fabs(second_first_end) <= second_area_tolerance &&
	 boolean_point_segment_distance_2d(first_end, second_start,
	     second_end) <= distance_tolerance);
}


static double
boolean_segment_distance_2d(const ON_2dPoint &first_start,
	const ON_2dPoint &first_end, const ON_2dPoint &second_start,
	const ON_2dPoint &second_end)
{
    if (boolean_segments_intersect_2d(first_start, first_end, second_start,
	second_end))
    {
	return 0.0;
    }
    return std::min(std::min(
	boolean_point_segment_distance_2d(first_start, second_start,
	    second_end),
	boolean_point_segment_distance_2d(first_end, second_start, second_end)),
	std::min(boolean_point_segment_distance_2d(second_start, first_start,
	    first_end),
	boolean_point_segment_distance_2d(second_end, first_start, first_end)));
}


static bool
certify_boolean_projected_bezier(const ON_BezierCurve &curve,
	const ON_2dPoint &segment_start, const ON_2dPoint &segment_end,
	double tolerance, double parameter_tolerance, unsigned int depth,
	size_t &subdivisions, double &last_projection,
	std::vector<ON_2dPoint> &controls)
{
    const double dx = segment_end.x - segment_start.x;
    const double dy = segment_end.y - segment_start.y;
    const double length_squared = dx * dx + dy * dy;
    bool hull_is_certified = length_squared > 0.0 &&
	std::isfinite(length_squared);
    std::vector<ON_2dPoint> local_controls;
    std::vector<double> local_projections;
    for (int control_index = 0; control_index < curve.CVCount();
	 ++control_index)
    {
	ON_3dPoint control;
	const double weight = curve.Weight(control_index);
	if (!(weight > 0.0) || !std::isfinite(weight) ||
	    !curve.GetCV(control_index, control) || !control.IsValid())
	{
	    return false;
	}
	const ON_2dPoint projected(control.x, control.y);
	const double parameter = ((projected.x - segment_start.x) * dx +
	    (projected.y - segment_start.y) * dy) / length_squared;
	if (!std::isfinite(parameter)) {
	    return false;
	}
	if (parameter < -parameter_tolerance ||
	    parameter > 1.0 + parameter_tolerance ||
	    (!local_projections.empty() && parameter + parameter_tolerance <
		local_projections.back()))
	{
	    hull_is_certified = false;
	}
	local_controls.push_back(projected);
	local_projections.push_back(parameter);
    }
    if (hull_is_certified && !local_projections.empty() &&
	local_projections.front() + parameter_tolerance >= last_projection)
    {
	controls.insert(controls.end(), local_controls.begin(),
	    local_controls.end());
	last_projection = local_projections.back();
	return true;
    }

    if (depth >= BOOLEAN_CAP_MAX_SUBDIVISION_DEPTH ||
	++subdivisions > BOOLEAN_CAP_MAX_SUBDIVISIONS)
    {
	return false;
    }
    ON_BezierCurve left;
    ON_BezierCurve right;
    return curve.Split(0.5, left, right) &&
	certify_boolean_projected_bezier(left, segment_start, segment_end,
	    tolerance, parameter_tolerance, depth + 1, subdivisions,
	    last_projection, controls) &&
	certify_boolean_projected_bezier(right, segment_start, segment_end,
	    tolerance, parameter_tolerance, depth + 1, subdivisions,
	    last_projection, controls);
}


static bool
certify_boolean_projected_curve(ON_NurbsCurve &curve,
	const ON_2dPoint &segment_start, const ON_2dPoint &segment_end,
	double tolerance, std::vector<ON_2dPoint> &controls)
{
    controls.clear();
    const double segment_length = std::hypot(segment_end.x - segment_start.x,
	segment_end.y - segment_start.y);
    if (!(segment_length > 2.0 * tolerance) ||
	!std::isfinite(segment_length) || !curve.IsValid() ||
	curve.Order() < 2 || curve.CVCount() < curve.Order())
    {
	return false;
    }
    const double parameter_tolerance = std::max(
	tolerance / segment_length,
	128.0 * std::numeric_limits<double>::epsilon());
    double last_projection = -std::numeric_limits<double>::infinity();
    size_t subdivisions = 0;
    bool found_span = false;
    for (int span = 0; span <= curve.CVCount() - curve.Order(); ++span) {
	const int knot = span + curve.Order() - 2;
	if (!(curve.Knot(knot) < curve.Knot(knot + 1))) {
	    continue;
	}
	found_span = true;
	ON_BezierCurve bezier;
	if (!curve.ConvertSpanToBezier(span, bezier) ||
	    !certify_boolean_projected_bezier(bezier, segment_start,
		segment_end, tolerance, parameter_tolerance, 0, subdivisions,
		last_projection, controls))
	{
	    return false;
	}
    }
    return found_span && !controls.empty() &&
	last_projection >= 1.0 - parameter_tolerance;
}


static bool
boolean_projected_bezier_bounds(const ON_BezierCurve &curve,
	ON_2dPoint &minimum, ON_2dPoint &maximum)
{
    minimum = ON_2dPoint(std::numeric_limits<double>::infinity(),
	std::numeric_limits<double>::infinity());
    maximum = ON_2dPoint(-std::numeric_limits<double>::infinity(),
	-std::numeric_limits<double>::infinity());
    if (curve.CVCount() < 2) {
	return false;
    }

    for (int control_index = 0; control_index < curve.CVCount();
	 ++control_index)
    {
	ON_3dPoint control;
	const double weight = curve.Weight(control_index);
	if (!(weight > 0.0) || !std::isfinite(weight) ||
	    !curve.GetCV(control_index, control) || !control.IsValid())
	{
	    return false;
	}
	minimum.x = std::min(minimum.x, control.x);
	minimum.y = std::min(minimum.y, control.y);
	maximum.x = std::max(maximum.x, control.x);
	maximum.y = std::max(maximum.y, control.y);
    }
    return minimum.IsValid() && maximum.IsValid() &&
	maximum.x >= minimum.x && maximum.y >= minimum.y;
}


static double
boolean_projected_bounds_separation(const ON_2dPoint &first_minimum,
	const ON_2dPoint &first_maximum,
	const ON_2dPoint &second_minimum,
	const ON_2dPoint &second_maximum)
{
    const double x_separation = std::max(0.0, std::max(
	first_minimum.x - second_maximum.x,
	second_minimum.x - first_maximum.x));
    const double y_separation = std::max(0.0, std::max(
	first_minimum.y - second_maximum.y,
	second_minimum.y - first_maximum.y));
    return std::hypot(x_separation, y_separation);
}


/* Positive-weight rational Bezier curves are contained in the convex hulls
 * of their Euclidean control points.  Recursively separated control boxes
 * therefore prove that two complete curve loci are disjoint. */
static bool
certify_boolean_projected_beziers_disjoint(
	const ON_BezierCurve &first, const ON_BezierCurve &second,
	double tolerance, unsigned int depth, size_t &subdivisions)
{
    ON_2dPoint first_minimum;
    ON_2dPoint first_maximum;
    ON_2dPoint second_minimum;
    ON_2dPoint second_maximum;
    if (!boolean_projected_bezier_bounds(first, first_minimum,
	    first_maximum) ||
	!boolean_projected_bezier_bounds(second, second_minimum,
	    second_maximum))
    {
	return false;
    }

    const double separation = boolean_projected_bounds_separation(
	first_minimum, first_maximum, second_minimum, second_maximum);
    if (std::isfinite(separation) && separation > tolerance) {
	return true;
    }
    if (depth >= BOOLEAN_CAP_MAX_SUBDIVISION_DEPTH ||
	++subdivisions > BOOLEAN_CAP_MAX_SUBDIVISIONS)
    {
	return false;
    }

    const double first_extent = std::hypot(
	first_maximum.x - first_minimum.x,
	first_maximum.y - first_minimum.y);
    const double second_extent = std::hypot(
	second_maximum.x - second_minimum.x,
	second_maximum.y - second_minimum.y);
    if (!std::isfinite(first_extent) || !std::isfinite(second_extent)) {
	return false;
    }

    ON_BezierCurve left;
    ON_BezierCurve right;
    if (first_extent >= second_extent) {
	return first.Split(0.5, left, right) &&
	    certify_boolean_projected_beziers_disjoint(left, second,
		tolerance, depth + 1, subdivisions) &&
	    certify_boolean_projected_beziers_disjoint(right, second,
		tolerance, depth + 1, subdivisions);
    }
    return second.Split(0.5, left, right) &&
	certify_boolean_projected_beziers_disjoint(first, left, tolerance,
	    depth + 1, subdivisions) &&
	certify_boolean_projected_beziers_disjoint(first, right, tolerance,
	    depth + 1, subdivisions);
}


static bool
certify_boolean_projected_curves_disjoint(ON_NurbsCurve &first,
	ON_NurbsCurve &second, double tolerance)
{
    if (!(tolerance > 0.0) || !std::isfinite(tolerance) ||
	!first.IsValid() || !second.IsValid() || first.Order() < 2 ||
	second.Order() < 2 || first.CVCount() < first.Order() ||
	second.CVCount() < second.Order())
    {
	return false;
    }

    size_t subdivisions = 0;
    bool found_first_span = false;
    bool found_second_span = false;
    for (int first_span = 0;
	 first_span <= first.CVCount() - first.Order(); ++first_span)
    {
	const int first_knot = first_span + first.Order() - 2;
	if (!(first.Knot(first_knot) < first.Knot(first_knot + 1))) {
	    continue;
	}
	found_first_span = true;
	ON_BezierCurve first_bezier;
	if (!first.ConvertSpanToBezier(first_span, first_bezier)) {
	    return false;
	}

	found_second_span = false;
	for (int second_span = 0;
	     second_span <= second.CVCount() - second.Order(); ++second_span)
	{
	    const int second_knot = second_span + second.Order() - 2;
	    if (!(second.Knot(second_knot) < second.Knot(second_knot + 1))) {
		continue;
	    }
	    found_second_span = true;
	    ON_BezierCurve second_bezier;
	    if (!second.ConvertSpanToBezier(second_span, second_bezier) ||
		!certify_boolean_projected_beziers_disjoint(first_bezier,
		    second_bezier, tolerance, 0, subdivisions))
	    {
		return false;
	    }
	}
	if (!found_second_span) {
	    return false;
	}
    }
    return found_first_span;
}


static ON_Xform
boolean_world_to_plane_xform(const ON_Plane &plane)
{
    ON_Xform transform;
    transform[0][0] = plane.xaxis.x;
    transform[0][1] = plane.xaxis.y;
    transform[0][2] = plane.xaxis.z;
    transform[0][3] = -(plane.xaxis * plane.origin);
    transform[1][0] = plane.yaxis.x;
    transform[1][1] = plane.yaxis.y;
    transform[1][2] = plane.yaxis.z;
    transform[1][3] = -(plane.yaxis * plane.origin);
    transform[2][0] = plane.zaxis.x;
    transform[2][1] = plane.zaxis.y;
    transform[2][2] = plane.zaxis.z;
    transform[2][3] = -(plane.zaxis * plane.origin);
    transform[3][0] = 0.0;
    transform[3][1] = 0.0;
    transform[3][2] = 0.0;
    transform[3][3] = 1.0;
    return transform;
}


static bool
certify_boolean_projected_cap_loop(
	const ON_Plane &plane,
	const std::vector<ON_3dPoint> &vertices,
	const std::vector<std::unique_ptr<ON_Curve> > &boundary,
	double plane_tolerance, double loop_tolerance,
	double &minimum_u, double &maximum_u,
	double &minimum_v, double &maximum_v)
{
    if (vertices.size() < 3 || vertices.size() != boundary.size() ||
	vertices.size() > BOOLEAN_CAP_MAX_EDGES ||
	!(plane_tolerance > 0.0) || !(loop_tolerance > 0.0))
    {
	if (DEBUG_BREP_BOOLEAN)
	    bu_log("Boolean cap projection rejected invalid inputs.\n");
	return false;
    }

    const ON_Xform world_to_plane = boolean_world_to_plane_xform(plane);
    std::vector<std::unique_ptr<ON_NurbsCurve> > projected(boundary.size());
    std::vector<ON_2dPoint> corners(boundary.size());
    std::vector<ON_2dPoint> projected_vertices(boundary.size());
    for (size_t edge = 0; edge < boundary.size(); ++edge) {
	if (!boundary[edge] ||
	    fabs(plane.DistanceTo(vertices[edge])) > plane_tolerance ||
	    !plane.ClosestPointTo(vertices[edge], &projected_vertices[edge].x,
		&projected_vertices[edge].y))
	{
	    if (DEBUG_BREP_BOOLEAN)
		bu_log("Boolean cap projection rejected vertex %zu.\n", edge);
	    return false;
	}
	projected[edge].reset(new ON_NurbsCurve());
	if (boundary[edge]->GetNurbForm(*projected[edge]) <= 0 ||
	    !projected[edge]->Transform(world_to_plane) ||
	    !projected[edge]->ChangeDimension(2))
	{
	    if (DEBUG_BREP_BOOLEAN)
		bu_log("Boolean cap projection rejected curve %zu conversion.\n",
		    edge);
	    return false;
	}
	const ON_3dPoint start = projected[edge]->PointAtStart();
	if (!start.IsValid()) {
	    if (DEBUG_BREP_BOOLEAN)
		bu_log("Boolean cap projection rejected curve %zu start.\n", edge);
	    return false;
	}
	corners[edge] = ON_2dPoint(start.x, start.y);
	if (std::hypot(corners[edge].x - projected_vertices[edge].x,
		corners[edge].y - projected_vertices[edge].y) > plane_tolerance)
	{
	    if (DEBUG_BREP_BOOLEAN)
		bu_log("Boolean cap projection rejected curve %zu vertex gap %.17g.\n",
		    edge, std::hypot(corners[edge].x - projected_vertices[edge].x,
			corners[edge].y - projected_vertices[edge].y));
	    return false;
	}
    }

    for (size_t edge = 0; edge < projected.size(); ++edge) {
	const size_t next = (edge + 1) % projected.size();
	const ON_3dPoint end = projected[edge]->PointAtEnd();
	if (!end.IsValid() ||
	    std::hypot(end.x - corners[next].x, end.y - corners[next].y) >
		2.0 * plane_tolerance ||
	    !projected[edge]->SetEndPoint(ON_3dPoint(corners[next].x,
		corners[next].y, 0.0)))
	{
	    if (DEBUG_BREP_BOOLEAN)
		bu_log("Boolean cap projection rejected curve %zu closure gap %.17g.\n",
		    edge, end.IsValid() ? std::hypot(end.x - corners[next].x,
			end.y - corners[next].y) : -1.0);
	    return false;
	}
    }

    double perimeter = 0.0;
    double twice_area = 0.0;
    ON_2dPoint center(0.0, 0.0);
    const double inverse_corner_count = 1.0 / corners.size();
    for (size_t vertex = 0; vertex < corners.size(); ++vertex) {
	center.x += inverse_corner_count * corners[vertex].x;
	center.y += inverse_corner_count * corners[vertex].y;
    }
    for (size_t vertex = 0; vertex < corners.size(); ++vertex) {
	const ON_2dPoint &first = corners[vertex];
	const ON_2dPoint &second = corners[(vertex + 1) % corners.size()];
	perimeter += std::hypot(second.x - first.x, second.y - first.y);
	twice_area += (first.x - center.x) * (second.y - center.y) -
	    (first.y - center.y) * (second.x - center.x);
    }
    const double numeric_area = 256.0 *
	std::numeric_limits<double>::epsilon() * perimeter * perimeter;
    const double tolerance_area = 2.0 * loop_tolerance * perimeter;
    if (!(perimeter > 0.0) || !std::isfinite(perimeter) ||
	!std::isfinite(twice_area) ||
	fabs(twice_area) <= numeric_area)
    {
	if (DEBUG_BREP_BOOLEAN)
	    bu_log("Boolean cap projection rejected area %.17g with perimeter "
		"%.17g and numeric threshold %.17g.\n", twice_area,
		perimeter, numeric_area);
	return false;
    }
    if (DEBUG_BREP_BOOLEAN && fabs(twice_area) <= tolerance_area) {
	bu_log("Boolean cap projection retained resolvable thin area %.17g "
	    "below modeling threshold %.17g.\n", twice_area,
	    tolerance_area);
    }

    std::vector<std::vector<ON_2dPoint> > controls(boundary.size());
    minimum_u = minimum_v = std::numeric_limits<double>::infinity();
    maximum_u = maximum_v = -std::numeric_limits<double>::infinity();
    for (size_t edge = 0; edge < projected.size(); ++edge) {
	const size_t next = (edge + 1) % projected.size();
	if (!certify_boolean_projected_curve(*projected[edge], corners[edge],
		corners[next], loop_tolerance, controls[edge]))
	{
	    if (DEBUG_BREP_BOOLEAN)
		bu_log("Boolean cap projection rejected curve %zu control hull.\n",
		    edge);
	    return false;
	}
	for (size_t control = 0; control < controls[edge].size(); ++control) {
	    minimum_u = std::min(minimum_u, controls[edge][control].x);
	    maximum_u = std::max(maximum_u, controls[edge][control].x);
	    minimum_v = std::min(minimum_v, controls[edge][control].y);
	    maximum_v = std::max(maximum_v, controls[edge][control].y);
	}
    }

    /* Monotone chord projection proves that each individual boundary curve
     * cannot double back onto itself.  For distinct non-adjacent boundaries,
     * certify the complete positive-weight control hulls as disjoint; endpoint
     * chords alone are not sufficient for strongly curved cap boundaries. */
    for (size_t first = 0; first < corners.size(); ++first) {
	for (size_t second = first + 1; second < corners.size(); ++second) {
	    if (second == first + 1 ||
		(first == 0 && second + 1 == corners.size()))
	    {
		continue;
	    }
	    const double separation = boolean_segment_distance_2d(corners[first],
		corners[(first + 1) % corners.size()], corners[second],
		corners[(second + 1) % corners.size()]);
	    ON_BoundingBox proof_bounds = projected[first]->BoundingBox();
	    const ON_BoundingBox second_bounds =
		projected[second]->BoundingBox();
	    if (proof_bounds.IsValid() && second_bounds.IsValid()) {
		proof_bounds.Union(second_bounds);
	    }
	    const double proof_tolerance =
		boolean_coordinate_roundoff_tolerance(proof_bounds);
	    if (proof_tolerance > 0.0 &&
		certify_boolean_projected_curves_disjoint(*projected[first],
		    *projected[second], proof_tolerance))
	    {
		if (DEBUG_BREP_BOOLEAN) {
		    bu_log("Boolean cap projection certified nonadjacent edges "
			"%zu/%zu as disjoint at tolerance %.17g (chord "
			"separation %.17g).\n", first, second,
			proof_tolerance, separation);
		}
		continue;
	    }
	    if (DEBUG_BREP_BOOLEAN) {
		ON_SimpleArray<ON_X_EVENT> events;
		const int event_count = ON_Intersect(projected[first].get(),
		    projected[second].get(), events, loop_tolerance);
		bu_log("Boolean cap projection rejected nonadjacent edges %zu/%zu "
		    "at separation %.17g: %.17g %.17g -> %.17g %.17g / "
		    "%.17g %.17g -> %.17g %.17g, orientations "
		    "%.17g %.17g %.17g %.17g, curve events %d/%d.\n", first,
		    second, separation,
		    corners[first].x, corners[first].y,
		    corners[(first + 1) % corners.size()].x,
		    corners[(first + 1) % corners.size()].y, corners[second].x,
		    corners[second].y,
		    corners[(second + 1) % corners.size()].x,
		    corners[(second + 1) % corners.size()].y,
		    boolean_orient_2d(corners[first],
			corners[(first + 1) % corners.size()],
			corners[second]),
		    boolean_orient_2d(corners[first],
			corners[(first + 1) % corners.size()],
			corners[(second + 1) % corners.size()]),
		    boolean_orient_2d(corners[second],
			corners[(second + 1) % corners.size()],
			corners[first]),
		    boolean_orient_2d(corners[second],
			corners[(second + 1) % corners.size()],
			corners[(first + 1) % corners.size()]), event_count,
		    events.Count());
		for (int event_index = 0; event_index < events.Count(); ++event_index) {
		    bu_log("  cap curve event %d type %d at %.17g %.17g / "
			"%.17g %.17g.\n", event_index,
			static_cast<int>(events[event_index].m_type),
			events[event_index].m_A[0].x,
			events[event_index].m_A[0].y,
			events[event_index].m_B[0].x,
			events[event_index].m_B[0].y);
		}
	    }
		return false;
	}
    }

    /* At each shared endpoint, separate the two adjacent positive-weight
     * control hulls by a line through the endpoint.  Controls within the
     * tolerance ball are the certified shared endpoint neighborhood. */
    for (size_t vertex = 0; vertex < corners.size(); ++vertex) {
	const size_t incoming = (vertex + corners.size() - 1) %
	    corners.size();
	const size_t outgoing = vertex;
	double incoming_x = corners[incoming].x - corners[vertex].x;
	double incoming_y = corners[incoming].y - corners[vertex].y;
	double outgoing_x = corners[(vertex + 1) % corners.size()].x -
	    corners[vertex].x;
	double outgoing_y = corners[(vertex + 1) % corners.size()].y -
	    corners[vertex].y;
	const double incoming_length = std::hypot(incoming_x, incoming_y);
	const double outgoing_length = std::hypot(outgoing_x, outgoing_y);
	if (!(incoming_length > 2.0 * loop_tolerance) ||
	    !(outgoing_length > 2.0 * loop_tolerance))
	{
	    if (DEBUG_BREP_BOOLEAN)
		bu_log("Boolean cap projection rejected vertex %zu adjacent lengths "
		    "%.17g/%.17g.\n", vertex, incoming_length,
		    outgoing_length);
	    return false;
	}
	incoming_x /= incoming_length;
	incoming_y /= incoming_length;
	outgoing_x /= outgoing_length;
	outgoing_y /= outgoing_length;
	double separator_x = incoming_x - outgoing_x;
	double separator_y = incoming_y - outgoing_y;
	const double separator_length = std::hypot(separator_x, separator_y);
	if (!(separator_length > 128.0 *
		std::numeric_limits<double>::epsilon()))
	{
	    if (DEBUG_BREP_BOOLEAN)
		bu_log("Boolean cap projection rejected vertex %zu separator %.17g.\n",
		    vertex, separator_length);
	    return false;
	}
	separator_x /= separator_length;
	separator_y /= separator_length;

	for (size_t control = 0; control < controls[incoming].size(); ++control) {
	    const double dx = controls[incoming][control].x - corners[vertex].x;
	    const double dy = controls[incoming][control].y - corners[vertex].y;
	    if (std::hypot(dx, dy) <= 2.0 * loop_tolerance) {
		continue;
	    }
	    if (separator_x * dx + separator_y * dy <= 0.0) {
		if (DEBUG_BREP_BOOLEAN)
		    bu_log("Boolean cap projection rejected vertex %zu incoming "
			"control %zu side %.17g.\n", vertex, control,
			separator_x * dx + separator_y * dy);
		return false;
	    }
	}
	for (size_t control = 0; control < controls[outgoing].size(); ++control) {
	    const double dx = controls[outgoing][control].x - corners[vertex].x;
	    const double dy = controls[outgoing][control].y - corners[vertex].y;
	    if (std::hypot(dx, dy) <= 2.0 * loop_tolerance) {
		continue;
	    }
	    if (separator_x * dx + separator_y * dy >= 0.0) {
		if (DEBUG_BREP_BOOLEAN)
		    bu_log("Boolean cap projection rejected vertex %zu outgoing "
			"control %zu side %.17g.\n", vertex, control,
			separator_x * dx + separator_y * dy);
		return false;
	    }
	}
    }

    return std::isfinite(minimum_u) && std::isfinite(maximum_u) &&
	std::isfinite(minimum_v) && std::isfinite(maximum_v) &&
	maximum_u > minimum_u && maximum_v > minimum_v;
}


static bool
prepare_boolean_cap_boundary(
	const ON_Plane &plane,
	const std::vector<ON_3dPoint> &vertices,
	const std::vector<std::unique_ptr<ON_Curve> > &source_boundary,
	double repair_tolerance,
	std::vector<ON_3dPoint> &cap_vertices,
	std::vector<std::unique_ptr<ON_Curve> > &cap_boundary)
{
    cap_vertices.clear();
    cap_boundary.clear();
    if (!plane.IsValid() || vertices.size() < 3 ||
	vertices.size() != source_boundary.size() ||
	!(repair_tolerance > 0.0) || !std::isfinite(repair_tolerance))
    {
	return false;
    }

    cap_boundary.reserve(source_boundary.size());
    for (size_t edge = 0; edge < source_boundary.size(); ++edge) {
	ON_Curve *curve = source_boundary[edge] ?
	    source_boundary[edge]->Duplicate() : NULL;
	if (curve == NULL || !curve->IsValid()) {
	    delete curve;
	    cap_boundary.clear();
	    return false;
	}
	cap_boundary.push_back(std::unique_ptr<ON_Curve>(curve));
    }

    /* The topological vertex is the canonical point shared by both incident
     * edges.  Independently fitted edge ends can lie on opposite sides of a
     * narrow loop; averaging those ends can turn an otherwise simple loop
     * into a bow tie.  Project the canonical vertex onto the certified support
     * plane and adjust only the duplicate cap-boundary curves. */
    cap_vertices.resize(cap_boundary.size());
    for (size_t vertex = 0; vertex < cap_vertices.size(); ++vertex) {
	const size_t incoming = (vertex + cap_vertices.size() - 1) %
	    cap_vertices.size();
	const ON_3dPoint incoming_end = cap_boundary[incoming]->PointAtEnd();
	const ON_3dPoint outgoing_start = cap_boundary[vertex]->PointAtStart();
	if (!incoming_end.IsValid() || !outgoing_start.IsValid() ||
	    incoming_end.DistanceTo(vertices[vertex]) > repair_tolerance ||
	    outgoing_start.DistanceTo(vertices[vertex]) > repair_tolerance ||
	    incoming_end.DistanceTo(outgoing_start) > 2.0 * repair_tolerance)
	{
	    cap_vertices.clear();
	    cap_boundary.clear();
	    return false;
	}
	cap_vertices[vertex] = plane.ClosestPointTo(vertices[vertex]);
	if (!cap_vertices[vertex].IsValid() ||
	    cap_vertices[vertex].DistanceTo(incoming_end) > repair_tolerance ||
	    cap_vertices[vertex].DistanceTo(outgoing_start) > repair_tolerance ||
	    cap_vertices[vertex].DistanceTo(vertices[vertex]) > repair_tolerance)
	{
	    cap_vertices.clear();
	    cap_boundary.clear();
	    return false;
	}
    }

    for (size_t edge = 0; edge < cap_boundary.size(); ++edge) {
	if (!cap_boundary[edge]->SetStartPoint(cap_vertices[edge]) ||
	    !cap_boundary[edge]->SetEndPoint(cap_vertices[
		(edge + 1) % cap_vertices.size()]) ||
	    !cap_boundary[edge]->IsValid() ||
	    !boolean_curve_locus_within_plane(*cap_boundary[edge], plane,
		repair_tolerance))
	{
	    cap_vertices.clear();
	    cap_boundary.clear();
	    return false;
	}
    }

    return true;
}


static bool
project_boolean_cap_boundary(
	const ON_Plane &plane,
	const std::vector<ON_3dPoint> &vertices,
	const std::vector<std::unique_ptr<ON_Curve> > &boundary,
	ON_SimpleArray<ON_Curve *> &projected_loop)
{
    projected_loop.Empty();
    if (!plane.IsValid() || vertices.size() != boundary.size()) {
	return false;
    }

    const ON_Xform world_to_plane = boolean_world_to_plane_xform(plane);
    for (size_t edge = 0; edge < boundary.size(); ++edge) {
	ON_NurbsCurve *projected = new ON_NurbsCurve();
	if (!boundary[edge] || boundary[edge]->GetNurbForm(*projected) <= 0 ||
	    !projected->Transform(world_to_plane) ||
	    !projected->ChangeDimension(2))
	{
	    delete projected;
	    free_boolean_loop(projected_loop);
	    return false;
	}
	double start_u = 0.0;
	double start_v = 0.0;
	double end_u = 0.0;
	double end_v = 0.0;
	if (!plane.ClosestPointTo(vertices[edge], &start_u, &start_v) ||
	    !plane.ClosestPointTo(vertices[(edge + 1) % vertices.size()],
		&end_u, &end_v) ||
	    !projected->SetStartPoint(ON_3dPoint(start_u, start_v, 0.0)) ||
	    !projected->SetEndPoint(ON_3dPoint(end_u, end_v, 0.0)) ||
	    !projected->IsValid())
	{
	    delete projected;
	    free_boolean_loop(projected_loop);
	    return false;
	}
	projected_loop.Append(projected);
    }

    return projected_loop.Count() == static_cast<int>(boundary.size());
}


static bool
add_boolean_cap_loop_reusing_edges(
	ON_Brep &brep,
	int face_index,
	const std::vector<int> &ordered_edges,
	const std::vector<bool> &edge_reversed,
	ON_SimpleArray<ON_Curve *> &projected_loop)
{
    if (face_index < 0 || face_index >= brep.m_F.Count() ||
	ordered_edges.size() < 3 ||
	ordered_edges.size() != edge_reversed.size() ||
	ordered_edges.size() != static_cast<size_t>(projected_loop.Count()))
    {
	return false;
    }

    std::vector<int> existing_trim_indices(ordered_edges.size(), -1);
    for (size_t position = 0; position < ordered_edges.size(); ++position) {
	const int edge_index = ordered_edges[position];
	if (edge_index < 0 || edge_index >= brep.m_E.Count() ||
	    !is_active_boolean_naked_edge(&brep, edge_index) ||
	    projected_loop[static_cast<int>(position)] == NULL ||
	    projected_loop[static_cast<int>(position)]->Dimension() != 2 ||
	    !projected_loop[static_cast<int>(position)]->IsValid())
	{
	    return false;
	}
	existing_trim_indices[position] = brep.m_E[edge_index].m_ti[0];
    }

    ON_BrepLoop &loop = brep.NewLoop(ON_BrepLoop::outer,
	brep.m_F[face_index]);
    if (loop.m_loop_index < 0 || loop.m_loop_index >= brep.m_L.Count()) {
	return false;
    }

    for (size_t position = 0; position < ordered_edges.size(); ++position) {
	ON_Curve *parameter_curve = projected_loop[static_cast<int>(position)];
	const int curve_index = brep.AddTrimCurve(parameter_curve);
	if (curve_index < 0) {
	    return false;
	}
	projected_loop[static_cast<int>(position)] = NULL;

	const int edge_index = ordered_edges[position];
	const int trim_index = brep.NewTrim(brep.m_E[edge_index],
	    edge_reversed[position], loop, curve_index).m_trim_index;
	if (trim_index < 0 || trim_index >= brep.m_T.Count()) {
	    return false;
	}
	ON_BrepTrim &trim = brep.m_T[trim_index];
	trim.m_type = ON_BrepTrim::mated;
	trim.m_tolerance[0] = trim.m_tolerance[1] = MAX_FASTF;
	brep.m_T[existing_trim_indices[position]].m_type =
	    ON_BrepTrim::mated;
    }

    const int direction = brep.LoopDirection(loop);
    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean cap loop direction before normalization %d.\n",
	    direction);
	std::set<int> boundary_loops;
	for (size_t position = 0; position < ordered_edges.size(); ++position) {
	    const int edge_index = ordered_edges[position];
	    const ON_BrepEdge &edge = brep.m_E[edge_index];
	    const int old_trim_index = existing_trim_indices[position];
	    const ON_BrepTrim &old_trim = brep.m_T[old_trim_index];
	    const ON_BrepTrim &new_trim = brep.m_T[loop.m_ti[(int)position]];
	    boundary_loops.insert(old_trim.m_li);
	    const ON_3dPoint traversal_start = edge.PointAt(
		edge_reversed[position] ? edge.Domain().Max() : edge.Domain().Min());
	    const ON_3dPoint traversal_end = edge.PointAt(
		edge_reversed[position] ? edge.Domain().Min() : edge.Domain().Max());
	    bu_log("  cap cycle position %zu edge %d vertices %d/%d traversal "
		"%d/%d reversed %d; old trim %d vertices %d/%d face %d loop "
		"%d reversed %d; new trim %d vertices %d/%d reversed %d; "
		"points %.17g %.17g %.17g -> %.17g %.17g %.17g.\n",
		position, edge_index, edge.m_vi[0], edge.m_vi[1],
		edge.m_vi[edge_reversed[position] ? 1 : 0],
		edge.m_vi[edge_reversed[position] ? 0 : 1],
		edge_reversed[position], old_trim_index, old_trim.m_vi[0],
		old_trim.m_vi[1], old_trim.FaceIndexOf(), old_trim.m_li,
		old_trim.m_bRev3d, new_trim.m_trim_index, new_trim.m_vi[0],
		new_trim.m_vi[1], new_trim.m_bRev3d, traversal_start.x,
		traversal_start.y, traversal_start.z, traversal_end.x,
		traversal_end.y, traversal_end.z);
	}
	for (std::set<int>::const_iterator loop_index = boundary_loops.begin();
	     loop_index != boundary_loops.end(); ++loop_index)
	{
	    const ON_BrepLoop &boundary_loop = brep.m_L[*loop_index];
	    bu_log("  existing boundary loop %d face %d type %d has %d trims:\n",
		*loop_index, boundary_loop.m_fi,
		static_cast<int>(boundary_loop.m_type), boundary_loop.m_ti.Count());
	    for (int position = 0; position < boundary_loop.m_ti.Count();
		 ++position)
	    {
		const ON_BrepTrim &trim = brep.m_T[boundary_loop.m_ti[position]];
		bu_log("    position %d trim %d edge %d vertices %d/%d reversed %d "
		    "type %d.\n", position, trim.m_trim_index, trim.m_ei,
		    trim.m_vi[0], trim.m_vi[1], trim.m_bRev3d,
		    static_cast<int>(trim.m_type));
	    }
	}
    }
    if (direction == 0) {
	return false;
    }
    if (direction < 0) {
	brep.FlipLoop(loop);
    }
    return brep.LoopDirection(loop) == 1;
}


static bool
boolean_cap_excludes_source_holes(
	const ON_Brep *source_brep,
	const ON_BrepFace &source_face,
	const ON_SimpleArray<ON_Curve *> &cap_loop,
	double parameter_tolerance)
{
    if (source_brep == NULL || cap_loop.Count() < 1 ||
	!(parameter_tolerance > 0.0) || !std::isfinite(parameter_tolerance))
    {
	return false;
    }

    try {
	for (int loop_position = 0;
	     loop_position < source_face.m_li.Count(); ++loop_position)
	{
	    const int loop_index = source_face.m_li[loop_position];
	    if (loop_index < 0 || loop_index >= source_brep->m_L.Count()) {
		return false;
	    }
	    const ON_BrepLoop &source_loop = source_brep->m_L[loop_index];
	    if (source_loop.m_type != ON_BrepLoop::inner) {
		continue;
	    }
	    if (source_loop.m_ti.Count() < 1) {
		return false;
	    }

	    bool sampled = false;
	    for (int trim_position = 0;
		 trim_position < source_loop.m_ti.Count(); ++trim_position)
	    {
		const int trim_index = source_loop.m_ti[trim_position];
		if (trim_index < 0 || trim_index >= source_brep->m_T.Count()) {
		    return false;
		}
		const ON_BrepTrim &trim = source_brep->m_T[trim_index];
		const ON_Curve *curve = trim.TrimCurveOf();
		ON_Interval domain = curve ? curve->Domain() :
		    ON_Interval::EmptyInterval;
		domain.MakeIncreasing();
		if (curve == NULL || !domain.IsIncreasing()) {
		    return false;
		}
		const double samples[] = {domain.Min(), domain.Mid(), domain.Max()};
		for (size_t sample = 0;
		     sample < sizeof(samples) / sizeof(samples[0]); ++sample)
		{
		    const ON_3dPoint point = curve->PointAt(samples[sample]);
		    if (!point.IsValid()) {
			return false;
		    }
		    sampled = true;
		    if (!is_point_outside_loop(ON_2dPoint(point.x, point.y),
			    cap_loop, parameter_tolerance))
		    {
			return false;
		    }
		}
	    }
	    if (!sampled) {
		return false;
	    }
	}
    } catch (const InvalidGeometry &) {
	return false;
    }

    return true;
}


static bool
boolean_source_face_contains_cap(
	const ON_Brep *source_brep,
	int source_face_index,
	const ON_Plane &plane,
	const std::vector<ON_3dPoint> &vertices,
	const std::vector<std::unique_ptr<ON_Curve> > &source_boundary,
	double repair_tolerance,
	double loop_tolerance,
	std::vector<ON_3dPoint> &cap_vertices,
	std::vector<std::unique_ptr<ON_Curve> > &cap_boundary,
	double &minimum_u,
	double &maximum_u,
	double &minimum_v,
	double &maximum_v,
	const char **reason)
{
    const auto rejected = [&](const char *message) {
	if (reason != NULL) {
	    *reason = message;
	}
	return false;
    };
    if (reason != NULL) {
	*reason = "unknown containment failure";
    }
    if (source_brep == NULL || source_face_index < 0 ||
	source_face_index >= source_brep->m_F.Count())
    {
	return rejected("invalid source face");
    }
    const ON_BrepFace &source_face = source_brep->m_F[source_face_index];
    const ON_Surface *source_surface = source_face.SurfaceOf();
    if (source_surface == NULL) {
	return rejected("missing source surface");
    }

    if (!prepare_boolean_cap_boundary(plane, vertices, source_boundary,
	    repair_tolerance, cap_vertices, cap_boundary))
    {
	return rejected("cycle boundary could not be reconciled");
    }
    if (!certify_boolean_projected_cap_loop(plane, cap_vertices, cap_boundary,
	    repair_tolerance, loop_tolerance, minimum_u, maximum_u, minimum_v,
	    maximum_v))
    {
	return rejected("projected cycle is not a certified simple loop");
    }

    const double domain_padding = std::max(loop_tolerance,
	boolean_coordinate_roundoff_tolerance(source_boundary.front()->BoundingBox()));
    ON_PlaneSurface cap_surface(plane);
    if (!cap_surface.SetDomain(0, minimum_u - domain_padding,
	    maximum_u + domain_padding) ||
	!cap_surface.SetDomain(1, minimum_v - domain_padding,
	    maximum_v + domain_padding) ||
	!cap_surface.SetExtents(0, cap_surface.Domain(0)) ||
	!cap_surface.SetExtents(1, cap_surface.Domain(1)))
    {
	return rejected("projected cap surface could not be initialized");
    }

    TrimmedFace projected_cap;
    projected_cap.m_face = &source_face;
    if (!project_boolean_cap_boundary(plane, cap_vertices, cap_boundary,
	    projected_cap.m_outerloop))
    {
	return rejected("cycle could not be projected into the cap plane");
    }

    ON_Xform parameter_transform;
    if (!planar_surface_parameter_transform(&cap_surface, source_surface,
	    parameter_transform))
    {
	return rejected("cap plane could not be mapped to the source surface");
    }
    TrimmedFace mapped_cap;
    mapped_cap.m_face = &source_face;
    if (!transform_boolean_loop(projected_cap.m_outerloop,
	    parameter_transform, mapped_cap.m_outerloop) ||
	!mapped_boolean_loop_matches_surface(projected_cap.m_outerloop,
	    mapped_cap.m_outerloop, &cap_surface, source_surface))
    {
	return rejected("mapped cycle does not reproduce the cap surface");
    }

    ON_ClassArray<ON_SimpleArray<ON_Curve *> > face_loops;
    if (!face_trim_loops(source_brep, source_face_index, face_loops)) {
	return rejected("source face trim loops are invalid");
    }
    double cap_parameter_tolerance =
	std::numeric_limits<double>::infinity();
    for (int edge = 0; edge < mapped_cap.m_outerloop.Count(); ++edge) {
	double parameter_tolerance = 0.0;
	double curve_parameter_tolerance = 0.0;
	if (!get_face_boundary_curve_tolerances(source_surface,
		mapped_cap.m_outerloop[edge], parameter_tolerance,
		curve_parameter_tolerance))
	{
	    return rejected("mapped cap tolerance could not be determined");
	}
	cap_parameter_tolerance = std::min(cap_parameter_tolerance,
	    parameter_tolerance);
	const ON_SimpleArray<ON_Interval> included =
	    get_curve_intervals_inside_or_on_face(mapped_cap.m_outerloop[edge],
		face_loops, source_surface, parameter_tolerance);
	if (!curve_intervals_cover_domain(included,
		mapped_cap.m_outerloop[edge]->Domain(),
		curve_parameter_tolerance))
	{
	    if (DEBUG_BREP_BOOLEAN) {
		ON_Interval domain = mapped_cap.m_outerloop[edge]->Domain();
		domain.MakeIncreasing();
		bu_log("Boolean mapped cap edge %d on source face %d has "
		    "domain %.17g -> %.17g, tolerance %.17g, and %d "
		    "included intervals", edge, source_face_index,
		    domain.Min(), domain.Max(), curve_parameter_tolerance,
		    included.Count());
		for (int interval_index = 0;
		     interval_index < included.Count(); ++interval_index)
		{
		    bu_log(" %.17g -> %.17g", included[interval_index].Min(),
			included[interval_index].Max());
		}
		bu_log(".\n");
		for (int sample = 0; sample <= 8; ++sample) {
		    const double parameter = domain.ParameterAt(sample / 8.0);
		    const ON_3dPoint point =
			mapped_cap.m_outerloop[edge]->PointAt(parameter);
		    bu_log("  mapped cap sample %d parameter %.17g uv %.17g "
			"%.17g location %d.\n", sample, parameter, point.x,
			point.y, point.IsValid() ? static_cast<int>(
			    point_face_location(ON_2dPoint(point.x, point.y),
				source_face, source_brep)) : -1);
		}
	    }
	    return rejected("a mapped cap edge leaves the trimmed source face");
	}
    }

    ON_2dPoint interior_point = ON_2dPoint::UnsetPoint;
    try {
	interior_point = get_point_inside_trimmed_face(&mapped_cap);
    } catch (const InvalidGeometry &) {
	return rejected("cap interior could not be classified");
    } catch (const AlgorithmError &) {
	return rejected("cap interior could not be located");
    }
    if (!interior_point.IsValid() || point_face_location(interior_point,
	    source_face, source_brep) != INSIDE_FACE)
    {
	return rejected("a strict cap interior point is outside the source face");
    }
    if (!boolean_cap_excludes_source_holes(source_brep, source_face,
	    mapped_cap.m_outerloop, cap_parameter_tolerance))
    {
	return rejected("the cap contains or touches a source-face hole");
    }

    if (reason != NULL) {
	*reason = NULL;
    }
    return true;
}


static bool
boolean_shared_cap_parameter_curve(
	const ON_Surface *surface,
	int source_face_index,
	const ON_Curve &model_curve,
	const ON_ClassArray<SharedSSICurve> &shared_curves,
	double repair_tolerance,
	std::unique_ptr<ON_Curve> &parameter_curve,
	int &shared_curve_index)
{
    parameter_curve.reset();
    shared_curve_index = -1;
    if (surface == NULL || source_face_index < 0 ||
	model_curve.Dimension() != 3 || !model_curve.IsValid() ||
	!(repair_tolerance > 0.0) || !std::isfinite(repair_tolerance))
    {
	return false;
    }

    for (int curve_index = 0; curve_index < shared_curves.Count();
	 ++curve_index)
    {
	const SharedSSICurve &shared = shared_curves[curve_index];
	int side = -1;
	if (shared.m_face_index[0] == source_face_index) {
	    side = 0;
	} else if (shared.m_face_index[1] == source_face_index) {
	    side = 1;
	}
	if (side < 0 || shared.m_curve == NULL ||
	    shared.m_parameter_curve[side] == NULL ||
	    shared.m_curve->Dimension() != 3 ||
	    shared.m_parameter_curve[side]->Dimension() != 2 ||
	    !shared.m_curve->IsValid() ||
	    !shared.m_parameter_curve[side]->IsValid())
	{
	    continue;
	}

	bool reversed = false;
	if (!brep_curves_coincident(model_curve, *shared.m_curve,
		repair_tolerance, &reversed))
	{
	    continue;
	}

	std::unique_ptr<ON_Curve> candidate(
	    shared.m_parameter_curve[side]->DuplicateCurve());
	if (!candidate || (reversed && !candidate->Reverse()) ||
	    !candidate->IsValid())
	{
	    continue;
	}
	int orientation = -1;
	if (!parameter_curve_lifts_to_model_curve(surface, candidate.get(),
		&model_curve, repair_tolerance, &orientation) ||
	    orientation != 0)
	{
	    continue;
	}

	/* Two independently generated SSI records may describe the same model
	 * locus.  Only use provenance when its source parameter curve is unique;
	 * an arbitrary choice between distinct trims would manufacture topology. */
	if (parameter_curve) {
	    parameter_curve.reset();
	    shared_curve_index = -2;
	    return false;
	}
	parameter_curve = std::move(candidate);
	shared_curve_index = curve_index;
    }

    return parameter_curve != NULL;
}


static bool
boolean_source_face_contains_nonplanar_cap(
	const ON_Brep *source_brep,
	int source_face_index,
	int combined_source_face_index,
	const std::vector<ON_3dPoint> &vertices,
	const std::vector<std::unique_ptr<ON_Curve> > &model_boundary,
	const ON_ClassArray<SharedSSICurve> &shared_curves,
	double repair_tolerance,
	std::vector<std::unique_ptr<ON_Curve> > &parameter_boundary,
	const char **reason)
{
    const auto rejected = [&](const char *message) {
	if (reason != NULL) {
	    *reason = message;
	}
	return false;
    };
    if (reason != NULL) {
	*reason = "unknown nonplanar containment failure";
    }
    parameter_boundary.clear();
    if (source_brep == NULL || source_face_index < 0 ||
	source_face_index >= source_brep->m_F.Count() || vertices.size() < 3 ||
	vertices.size() != model_boundary.size() ||
	!(repair_tolerance > 0.0) || !std::isfinite(repair_tolerance))
    {
	return rejected("invalid nonplanar cap candidate");
    }

    const ON_BrepFace &source_face = source_brep->m_F[source_face_index];
    const ON_Surface *surface = source_face.SurfaceOf();
    ON_Plane source_plane;
    if (surface == NULL || surface->IsPlanar(&source_plane)) {
	return rejected("the cap source surface is missing or planar");
    }

    std::vector<std::unique_ptr<ON_Curve> > candidate_boundary;
    candidate_boundary.reserve(model_boundary.size());
    for (size_t edge = 0; edge < model_boundary.size(); ++edge) {
	if (!model_boundary[edge] || model_boundary[edge]->Dimension() != 3 ||
	    !model_boundary[edge]->IsValid())
	{
	    return rejected("a model boundary curve is invalid");
	}

	std::unique_ptr<ON_Curve> parameter;
	int shared_curve_index = -1;
	const bool used_shared = boolean_shared_cap_parameter_curve(surface,
	    combined_source_face_index, *model_boundary[edge], shared_curves,
	    repair_tolerance, parameter, shared_curve_index);
	if (!used_shared) {
	    if (shared_curve_index == -2) {
		return rejected("a boundary edge has ambiguous SSI provenance");
	    }
	    std::string failure_reason;
	    PullbackFailureReason failure = PullbackFailureReason::None;
	    parameter.reset(brlcad::pullback_curve(surface,
		model_boundary[edge].get(), repair_tolerance,
		std::max(INTERSECTION_TOL, 0.25 * repair_tolerance),
		&failure_reason, &failure));
	    if (!parameter || !parameter->IsValid()) {
		record_boolean_projection_failure();
		parameter.reset(synchronized_surface_parameter_curve(surface,
		    *model_boundary[edge], repair_tolerance));
	    }
	}
	int orientation = -1;
	if (!parameter || parameter->Dimension() != 2 ||
	    !parameter->IsValid() ||
	    !parameter_curve_lifts_to_model_curve(surface, parameter.get(),
		model_boundary[edge].get(), repair_tolerance, &orientation))
	{
	    return rejected("a boundary edge has no certified surface parameter curve");
	}
	if (orientation != 0) {
	    if (!parameter->Reverse() ||
		!parameter_curve_lifts_to_model_curve(surface, parameter.get(),
		    model_boundary[edge].get(), repair_tolerance, &orientation) ||
		orientation != 0)
	    {
		return rejected("a boundary parameter curve has inconsistent orientation");
	    }
	}
	if (DEBUG_BREP_BOOLEAN) {
	    if (used_shared) {
		bu_log("Boolean nonplanar cap edge %zu uses shared SSI parameter "
		    "curve %d.\n", edge, shared_curve_index);
	    } else {
		bu_log("Boolean nonplanar cap edge %zu uses a certified projected "
		    "parameter curve.\n", edge);
	    }
	}
	candidate_boundary.push_back(std::move(parameter));
    }

    const ON_Interval surface_domains[2] = {
	surface->Domain(0), surface->Domain(1)
    };
    const bool surface_closed[2] = {
	surface->IsClosed(0) || surface->IsPeriodic(0),
	surface->IsClosed(1) || surface->IsPeriodic(1)
    };
    if (!surface_domains[0].IsIncreasing() ||
	!surface_domains[1].IsIncreasing())
    {
	return rejected("the cap source surface has invalid domains");
    }

    /* Make every pair of incident trims use one parameter-space vertex.
	 * Projecting the already canonical model vertex supplies that value while
	 * a nearby trim endpoint selects the correct branch of a closed surface. */
    brlcad::PullbackContext context;
    for (size_t vertex = 0; vertex < vertices.size(); ++vertex) {
	const size_t incoming = (vertex + vertices.size() - 1) % vertices.size();
	const ON_3dPoint incoming_end = candidate_boundary[incoming]->PointAtEnd();
	const ON_3dPoint outgoing_start = candidate_boundary[vertex]->PointAtStart();
	if (!incoming_end.IsValid() || !outgoing_start.IsValid()) {
	    return rejected("a boundary parameter endpoint is invalid");
	}

	ON_2dPoint aligned_incoming(incoming_end.x, incoming_end.y);
	const ON_2dPoint outgoing_reference(outgoing_start.x, outgoing_start.y);
	for (int direction = 0; direction < 2; ++direction) {
	    if (!surface_closed[direction]) {
		continue;
	    }
	    const double period = surface_domains[direction].Length();
	    aligned_incoming[direction] += std::round((outgoing_reference[direction] -
		aligned_incoming[direction]) / period) * period;
	}
	const ON_2dPoint reference(0.5 * (aligned_incoming.x +
		outgoing_reference.x), 0.5 * (aligned_incoming.y +
		outgoing_reference.y));
	ON_2dPoint common = ON_2dPoint::UnsetPoint;
	if (!synchronized_surface_parameter_at(context, surface, vertices[vertex],
		&reference, surface_closed, surface_domains, repair_tolerance,
		common))
	{
	    return rejected("a cycle vertex could not be projected to the source surface");
	}
	const ON_3dPoint common_parameter(common.x, common.y, 0.0);
	const ON_3dPoint common_model = surface->PointAt(common.x, common.y);
	if (!common_model.IsValid() ||
	    common_model.DistanceTo(vertices[vertex]) > repair_tolerance ||
	    !candidate_boundary[incoming]->SetEndPoint(common_parameter) ||
	    !candidate_boundary[vertex]->SetStartPoint(common_parameter) ||
	    !candidate_boundary[incoming]->IsValid() ||
	    !candidate_boundary[vertex]->IsValid())
	{
	    return rejected("a cycle vertex could not be synchronized in parameter space");
	}
    }

    TrimmedFace mapped_cap;
    mapped_cap.m_face = &source_face;
    for (size_t edge = 0; edge < candidate_boundary.size(); ++edge) {
	int orientation = -1;
	if (!parameter_curve_lifts_to_model_curve(surface,
		candidate_boundary[edge].get(), model_boundary[edge].get(),
		repair_tolerance, &orientation) || orientation != 0)
	{
	    return rejected("a synchronized cap trim does not reproduce its model edge");
	}
	ON_Curve *duplicate = candidate_boundary[edge]->DuplicateCurve();
	if (duplicate == NULL || !duplicate->IsValid()) {
	    delete duplicate;
	    return rejected("a cap parameter curve could not be duplicated");
	}
	mapped_cap.m_outerloop.Append(duplicate);
    }
    if (!is_loop_valid(mapped_cap.m_outerloop, ON_ZERO_TOLERANCE) ||
	loop_is_degenerate(mapped_cap.m_outerloop))
    {
	return rejected("the cap parameter curves do not form a resolved loop");
    }

    ON_ClassArray<ON_SimpleArray<ON_Curve *> > face_loops;
    if (!face_trim_loops(source_brep, source_face_index, face_loops)) {
	return rejected("source face trim loops are invalid");
    }
    double cap_parameter_tolerance = std::numeric_limits<double>::infinity();
    for (int edge = 0; edge < mapped_cap.m_outerloop.Count(); ++edge) {
	double parameter_tolerance = 0.0;
	double curve_parameter_tolerance = 0.0;
	if (!get_face_boundary_curve_tolerances(surface,
		mapped_cap.m_outerloop[edge], parameter_tolerance,
		curve_parameter_tolerance))
	{
	    return rejected("cap parameter tolerances could not be determined");
	}
	cap_parameter_tolerance = std::min(cap_parameter_tolerance,
	    parameter_tolerance);
	const ON_SimpleArray<ON_Interval> included =
	    get_curve_intervals_inside_or_on_face(mapped_cap.m_outerloop[edge],
		face_loops, surface, parameter_tolerance);
	if (!curve_intervals_cover_domain(included,
		mapped_cap.m_outerloop[edge]->Domain(),
		curve_parameter_tolerance))
	{
	    return rejected("a cap parameter curve leaves the trimmed source face");
	}
    }

    ON_2dPoint interior_point = ON_2dPoint::UnsetPoint;
    try {
	interior_point = get_point_inside_trimmed_face(&mapped_cap);
    } catch (const InvalidGeometry &) {
	return rejected("the cap interior could not be classified");
    } catch (const AlgorithmError &) {
	return rejected("the cap interior could not be located");
    }
    if (!interior_point.IsValid() || point_face_location(interior_point,
	    source_face, source_brep) != INSIDE_FACE)
    {
	return rejected("a strict cap interior point is outside the source face");
    }
    if (!boolean_cap_excludes_source_holes(source_brep, source_face,
	    mapped_cap.m_outerloop, cap_parameter_tolerance))
    {
	return rejected("the cap contains or touches a source-face hole");
    }

    parameter_boundary = std::move(candidate_boundary);
    if (reason != NULL) {
	*reason = NULL;
    }
    return true;
}


static BooleanMissingCapRepairResult
repair_boolean_missing_subtraction_cap(ON_Brep *brep,
	const ON_Brep *brep1, const ON_Brep *brep2, op_type operation,
	const ON_ClassArray<SharedSSICurve> &shared_curves)
{
    const auto skipped = [](const char *reason) {
	if (DEBUG_BREP_BOOLEAN) {
	    bu_log("Boolean missing subtraction cap skipped: %s.\n", reason);
	}
	return BOOLEAN_MISSING_CAP_REPAIR_SKIPPED;
    };
    const auto failed = [](const char *reason) {
	bu_log("Boolean missing subtraction cap repair failed: %s.\n", reason);
	return BOOLEAN_MISSING_CAP_REPAIR_FAILURE;
    };

    if (operation != BOOLEAN_DIFF && operation != BOOLEAN_UNION) {
	return skipped("the operation cannot have an omitted boundary face");
    }
    if (brep == NULL || brep1 == NULL || brep2 == NULL) {
	return skipped("candidate input is invalid");
    }

    std::vector<int> ordered_edges;
    std::vector<int> ordered_vertex_indices;
    std::vector<bool> edge_reversed;
    if (!collect_boolean_naked_edge_cycle(brep, ordered_edges,
	    ordered_vertex_indices, edge_reversed))
    {
	return skipped("the output does not have one bounded naked-edge cycle");
    }

    std::vector<ON_3dPoint> vertices;
    ON_3dPoint center(0.0, 0.0, 0.0);
    for (size_t vertex = 0; vertex < ordered_vertex_indices.size(); ++vertex) {
	const int vertex_index = ordered_vertex_indices[vertex];
	if (vertex_index < 0 || vertex_index >= brep->m_V.Count()) {
	    return skipped("a cycle vertex is invalid");
	}
	const ON_3dPoint point = brep->m_V[vertex_index].Point();
	if (!point.IsValid()) {
	    return skipped("a cycle vertex point is invalid");
	}
	vertices.push_back(point);
	center += (1.0 / ordered_vertex_indices.size()) * ON_3dVector(point);
    }

    double perimeter = 0.0;
    ON_3dVector twice_area(0.0, 0.0, 0.0);
    for (size_t vertex = 0; vertex < vertices.size(); ++vertex) {
	const ON_3dPoint &first = vertices[vertex];
	const ON_3dPoint &second = vertices[(vertex + 1) % vertices.size()];
	perimeter += first.DistanceTo(second);
	twice_area += ON_CrossProduct(first - center, second - center);
    }
    const double loop_tolerance = std::min(INTERSECTION_TOL,
	boolean_model_repair_tolerance(brep->BoundingBox()));
    const double area_magnitude = twice_area.Length();
    const double numeric_area = 256.0 *
	std::numeric_limits<double>::epsilon() * perimeter * perimeter;
    const double tolerance_area = 2.0 * loop_tolerance * perimeter;
    if (!(perimeter > 0.0) || !std::isfinite(perimeter) ||
	!std::isfinite(area_magnitude) ||
	area_magnitude <= numeric_area ||
	!twice_area.Unitize())
    {
	return skipped("the cycle has no numerically resolvable area");
    }
    if (DEBUG_BREP_BOOLEAN && area_magnitude <= tolerance_area) {
	bu_log("Boolean missing subtraction cap retained resolvable thin area "
	    "%.17g below modeling threshold %.17g.\n", area_magnitude,
	    tolerance_area);
    }

    /* The topological cycle vertices and each incident fitted edge endpoint
     * may independently carry the model repair error.  Use the same bounded
     * two-sided allowance as edge stitching; the cap is still required to
     * pass planar-locus, source-face containment, topology, and full B-Rep
     * validation before it is committed. */
    const double repair_tolerance = 2.0 * boolean_model_repair_tolerance(
	brep->BoundingBox());
    if (!(repair_tolerance > 0.0) || !std::isfinite(repair_tolerance)) {
	return skipped("the repair tolerance is invalid");
    }

    std::vector<std::unique_ptr<ON_Curve> > source_boundary;
    source_boundary.reserve(ordered_edges.size());
    for (size_t edge_position = 0; edge_position < ordered_edges.size();
	 ++edge_position)
    {
	const ON_BrepEdge &edge = brep->m_E[ordered_edges[edge_position]];
	std::unique_ptr<ON_Curve> curve(edge.DuplicateCurve());
	if (!curve || (edge_reversed[edge_position] && !curve->Reverse()) ||
	    !curve->IsValid())
	{
	    return skipped("a cycle curve could not be duplicated and oriented");
	}
	const ON_3dPoint curve_start = curve->PointAtStart();
	const ON_3dPoint curve_end = curve->PointAtEnd();
	const ON_3dPoint &expected_start = vertices[edge_position];
	const ON_3dPoint &expected_end = vertices[
	    (edge_position + 1) % vertices.size()];
	if (!curve_start.IsValid() || !curve_end.IsValid() ||
	    curve_start.DistanceTo(expected_start) > repair_tolerance ||
	    curve_end.DistanceTo(expected_end) > repair_tolerance)
	{
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Boolean missing subtraction cap cycle edge %d position "
		    "%zu reversed %d misses vertices %d/%d by %.17g/%.17g "
		    "at tolerance %.17g; curve %.17g %.17g %.17g -> %.17g "
		    "%.17g %.17g, vertices %.17g %.17g %.17g -> %.17g "
		    "%.17g %.17g.\n", ordered_edges[edge_position],
		    edge_position, edge_reversed[edge_position] ? 1 : 0,
		    ordered_vertex_indices[edge_position],
		    ordered_vertex_indices[(edge_position + 1) %
			ordered_vertex_indices.size()],
		    curve_start.DistanceTo(expected_start),
		    curve_end.DistanceTo(expected_end), repair_tolerance,
		    curve_start.x, curve_start.y, curve_start.z, curve_end.x,
		    curve_end.y, curve_end.z, expected_start.x,
		    expected_start.y, expected_start.z, expected_end.x,
		    expected_end.y, expected_end.z);
	    }
	    return skipped("an oriented cycle curve does not meet its vertices");
	}
	source_boundary.push_back(std::move(curve));
    }

    const ON_Brep *source_breps[2] = {brep1, brep2};
    const int source_face_offsets[2] = {0, brep1->m_F.Count()};
    int selected_operand = -1;
    int selected_face_index = -1;
    int selected_face_offset = -1;
    bool selected_nonplanar = false;
    ON_Plane selected_plane;
    std::vector<ON_3dPoint> cap_vertices;
    std::vector<std::unique_ptr<ON_Curve> > boundary;
    std::vector<std::unique_ptr<ON_Curve> > parameter_boundary;
    double minimum_u = 0.0;
    double maximum_u = 0.0;
    double minimum_v = 0.0;
    double maximum_v = 0.0;
    for (int operand = 0; operand < 2; ++operand) {
	const ON_Brep *source_brep = source_breps[operand];
	for (int face_index = 0; face_index < source_brep->m_F.Count();
	     ++face_index)
	{
	    const ON_BrepFace &source_face = source_brep->m_F[face_index];
	    const ON_Surface *surface = source_face.SurfaceOf();
	    ON_Plane plane;
	    if (source_face.m_face_index != face_index || surface == NULL) {
		continue;
	    }
	    if (!surface->IsPlanar(&plane)) {
		std::vector<std::unique_ptr<ON_Curve> > candidate_parameters;
		const char *containment_reason = NULL;
		const int combined_face_index = source_face_offsets[operand] +
		    face_index;
		const bool contains = boolean_source_face_contains_nonplanar_cap(
		    source_brep, face_index, combined_face_index, vertices,
		    source_boundary, shared_curves, repair_tolerance,
		    candidate_parameters, &containment_reason);
		if (DEBUG_BREP_BOOLEAN) {
		    const ON_ClassId *surface_class = surface->ClassId();
		    bu_log("Boolean missing subtraction cap nonplanar candidate "
			"operand %d face %d class %s: %s%s%s.\n", operand,
			face_index,
			surface_class ? surface_class->ClassName() : "unknown",
			contains ? "accepted" : "rejected",
			!contains && containment_reason ? ": " : "",
			!contains && containment_reason ? containment_reason : "");
		}
		if (!contains) {
		    continue;
		}
		if (selected_face_index >= 0) {
		    return skipped("more than one trimmed source face contains the cycle");
		}

		selected_operand = operand;
		selected_face_index = face_index;
		selected_face_offset = source_face_offsets[operand];
		selected_nonplanar = true;
		parameter_boundary = std::move(candidate_parameters);
		continue;
	    }
	    if (!plane.IsValid() ||
		plane.Normal().IsParallelTo(twice_area, ANGLE_TOL) == 0)
	    {
		continue;
	    }

	    bool coplanar = true;
	    for (size_t edge = 0;
		 edge < ordered_edges.size() && coplanar; ++edge)
	    {
		coplanar = boolean_curve_locus_within_plane(
		    brep->m_E[ordered_edges[edge]], plane, repair_tolerance);
	    }
	    if (!coplanar) {
		continue;
	    }

	    bool represented = false;
	    const int combined_face_index = source_face_offsets[operand] +
		face_index;
	    for (int result_face = 0; result_face < brep->m_F.Count();
		 ++result_face)
	    {
		if (brep->m_F[result_face].m_face_index == result_face &&
		    brep->m_F[result_face].m_face_user.i ==
			combined_face_index + FACE_SOURCE_TAG_OFFSET)
		{
		    represented = true;
		    break;
		}
	    }

	    std::vector<ON_3dPoint> candidate_vertices;
	    std::vector<std::unique_ptr<ON_Curve> > candidate_boundary;
	    double candidate_minimum_u = 0.0;
	    double candidate_maximum_u = 0.0;
	    double candidate_minimum_v = 0.0;
	    double candidate_maximum_v = 0.0;
	    const char *containment_reason = NULL;
	    const bool contains = boolean_source_face_contains_cap(source_brep,
		face_index, plane, vertices, source_boundary, repair_tolerance,
		loop_tolerance, candidate_vertices, candidate_boundary,
		candidate_minimum_u, candidate_maximum_u, candidate_minimum_v,
		candidate_maximum_v, &containment_reason);
	    if (DEBUG_BREP_BOOLEAN) {
		bu_log("Boolean missing subtraction cap candidate operand %d "
		    "face %d represented %d: %s%s%s.\n", operand, face_index,
		    represented, contains ? "accepted" : "rejected",
		    !contains && containment_reason ? ": " : "",
		    !contains && containment_reason ? containment_reason : "");
	    }
	    if (!contains) {
		continue;
	    }
	    if (selected_face_index >= 0) {
		return skipped("more than one trimmed source face contains the cycle");
	    }

	    selected_operand = operand;
	    selected_face_index = face_index;
	    selected_face_offset = source_face_offsets[operand];
	    selected_nonplanar = false;
	    selected_plane = plane;
	    cap_vertices = candidate_vertices;
	    boundary = std::move(candidate_boundary);
	    minimum_u = candidate_minimum_u;
	    maximum_u = candidate_maximum_u;
	    minimum_v = candidate_minimum_v;
	    maximum_v = candidate_maximum_v;
	}
    }
    if (selected_face_index < 0) {
	return skipped("no trimmed source face contains the cycle");
    }

    /* A missing cap is bounded by the side faces adjacent to the opening.
     * If every naked edge already belongs to one planar result face sourced
     * from the selected cap face, adding another face on the same cycle
     * merely creates a coincident, oppositely oriented sheet.  That can make
     * IsSolid() succeed without closing the intended material boundary (and
     * was observed when a sphere/ARB subtraction failed to trim the sphere
     * but retained the ARB's planar fragment). */
    int existing_cycle_face = -1;
    bool one_existing_cycle_face = true;
    for (size_t edge_position = 0; edge_position < ordered_edges.size();
	 ++edge_position)
    {
	const ON_BrepEdge &edge = brep->m_E[ordered_edges[edge_position]];
	if (edge.m_ti.Count() != 1) {
	    one_existing_cycle_face = false;
	    break;
	}
	const int trim_index = edge.m_ti[0];
	if (trim_index < 0 || trim_index >= brep->m_T.Count()) {
	    one_existing_cycle_face = false;
	    break;
	}
	const int face_index = brep->m_T[trim_index].FaceIndexOf();
	if (face_index < 0 || face_index >= brep->m_F.Count()) {
	    one_existing_cycle_face = false;
	    break;
	}
	if (existing_cycle_face < 0) {
	    existing_cycle_face = face_index;
	} else if (existing_cycle_face != face_index) {
	    one_existing_cycle_face = false;
	    break;
	}
    }
    if (!selected_nonplanar && one_existing_cycle_face &&
	existing_cycle_face >= 0)
    {
	const ON_BrepFace &cycle_face = brep->m_F[existing_cycle_face];
	ON_Plane cycle_plane;
	const ON_Surface *cycle_surface = cycle_face.SurfaceOf();
	const int selected_source_tag = selected_face_offset +
	    selected_face_index + FACE_SOURCE_TAG_OFFSET;
	if (cycle_surface != NULL && cycle_surface->IsPlanar(&cycle_plane) &&
	    cycle_plane.IsValid() &&
	    cycle_face.m_face_user.i == selected_source_tag)
	{
	    return skipped("the cycle already bounds its planar source face");
	}
    }

    const int naked_before = boolean_active_naked_edge_count(brep);
    const int surface_count_before = brep->m_S.Count();
    const int face_count_before = brep->m_F.Count();
    const int loop_count_before = brep->m_L.Count();
    const int trim_count_before = brep->m_T.Count();
    const int edge_count_before = brep->m_E.Count();
    const int vertex_count_before = brep->m_V.Count();
    ON_Brep repaired(*brep);

    const ON_BrepFace &source_face =
	source_breps[selected_operand]->m_F[selected_face_index];
    ON_Surface *surface = NULL;
    if (selected_nonplanar) {
	surface = source_face.SurfaceOf() ?
	    source_face.SurfaceOf()->DuplicateSurface() : NULL;
    } else {
	const double domain_padding = std::max(loop_tolerance,
	    boolean_coordinate_roundoff_tolerance(brep->BoundingBox()));
	ON_PlaneSurface *plane_surface = new ON_PlaneSurface(selected_plane);
	if (!plane_surface->SetDomain(0, minimum_u - domain_padding,
		maximum_u + domain_padding) ||
	    !plane_surface->SetDomain(1, minimum_v - domain_padding,
		maximum_v + domain_padding) ||
	    !plane_surface->SetExtents(0, plane_surface->Domain(0)) ||
	    !plane_surface->SetExtents(1, plane_surface->Domain(1)))
	{
	    delete plane_surface;
	    return failed("the cap surface domain could not be initialized");
	}
	surface = plane_surface;
    }
    if (surface == NULL || !surface->IsValid()) {
	delete surface;
	return failed("the cap source surface could not be duplicated");
    }
    const int surface_index = repaired.AddSurface(surface);
    if (surface_index != surface_count_before) {
	return failed("the cap surface could not be added");
    }
    ON_BrepFace &new_face = repaired.NewFace(surface_index);
    const int new_face_index = new_face.m_face_index;
    new_face.m_face_user.i = selected_face_offset + selected_face_index +
	FACE_SOURCE_TAG_OFFSET;

    ON_SimpleArray<ON_Curve *> projected_loop;
    if (selected_nonplanar) {
	for (size_t edge = 0; edge < parameter_boundary.size(); ++edge) {
	    projected_loop.Append(parameter_boundary[edge].release());
	}
    } else if (!project_boolean_cap_boundary(selected_plane, cap_vertices,
	    boundary, projected_loop))
    {
	return failed("the cap boundary could not be projected");
    }
    const bool loop_added = add_boolean_cap_loop_reusing_edges(repaired,
	new_face_index, ordered_edges, edge_reversed, projected_loop);
    free_boolean_loop(projected_loop);
    if (!loop_added) {
	return failed("the cap loop could not reuse its boundary edges");
    }

    const bool flip_face = source_face.m_bRev ^
	(operation == BOOLEAN_DIFF && selected_operand == 1);
    if (flip_face) {
	repaired.FlipFace(repaired.m_F[new_face_index]);
    }
    if (!repaired.SetTrimIsoFlags(repaired.m_F[new_face_index])) {
	return failed("the cap trim isoparametric flags could not be set");
    }

    if (boolean_active_naked_edge_count(&repaired) != 0) {
	return failed("the cap did not mate every boundary edge");
    }
    if (DEBUG_BREP_BOOLEAN) {
	for (size_t position = 0; position < ordered_edges.size(); ++position) {
	    const int edge_index = ordered_edges[position];
	    const ON_BrepEdge &edge = repaired.m_E[edge_index];
	    if (edge.m_ti.Count() != 2) {
		bu_log("Boolean cap orientation edge %d has %d trims.\n",
		    edge_index, edge.m_ti.Count());
		continue;
	    }
	    const ON_BrepTrim &first_trim = repaired.m_T[edge.m_ti[0]];
	    const ON_BrepTrim &second_trim = repaired.m_T[edge.m_ti[1]];
	    const int first_face = first_trim.FaceIndexOf();
	    const int second_face = second_trim.FaceIndexOf();
	    const int first_sense = first_trim.m_bRev3d ^
		repaired.m_F[first_face].m_bRev;
	    const int second_sense = second_trim.m_bRev3d ^
		repaired.m_F[second_face].m_bRev;
	    bu_log("Boolean cap orientation edge %d position %zu: trim %d "
		"face %d reversed %d/%d sense %d; trim %d face %d "
		"reversed %d/%d sense %d; relation %d.\n", edge_index,
		position, first_trim.m_trim_index, first_face,
		first_trim.m_bRev3d, repaired.m_F[first_face].m_bRev,
		first_sense, second_trim.m_trim_index, second_face,
		second_trim.m_bRev3d, repaired.m_F[second_face].m_bRev,
		second_sense, first_sense ^ second_sense ^ 1);
	}
    }
    if (!brep_orient_faces(repaired)) {
	return failed("the capped result could not be oriented consistently");
    }

    ON_wString validation_text;
    ON_TextLog validation_log(validation_text);
    const bool compacted = repaired.Compact();
    if (compacted) {
	repaired.SetTrimBoundingBoxes(false);
    }
    const bool iso_flags_set = compacted && repaired.SetTrimIsoFlags();
    const bool trim_types_set = iso_flags_set &&
	repaired.SetTrimTypeFlags(false);
    const bool vertex_tolerances_set = trim_types_set &&
	repaired.SetVertexTolerances(false);
    const bool edge_tolerances_set = vertex_tolerances_set &&
	set_boolean_edge_tolerances(&repaired);
    const bool trim_tolerances_set = edge_tolerances_set &&
	set_boolean_trim_tolerances(&repaired);
    const bool valid = trim_tolerances_set && repaired.IsValid(&validation_log);
    const bool solid = valid && repaired.IsSolid();
    const int naked_after = boolean_active_naked_edge_count(&repaired);

    if (DEBUG_BREP_BOOLEAN && naked_after > 0) {
	for (int edge_index = 0; edge_index < repaired.m_E.Count(); ++edge_index) {
	    if (!is_active_boolean_naked_edge(&repaired, edge_index)) {
		continue;
	    }
	    const ON_BrepEdge &edge = repaired.m_E[edge_index];
	    const int trim_index = edge.m_ti[0];
	    int face_index = -1;
	    if (trim_index >= 0 && trim_index < repaired.m_T.Count()) {
		const int loop_index = repaired.m_T[trim_index].m_li;
		if (loop_index >= 0 && loop_index < repaired.m_L.Count()) {
		    face_index = repaired.m_L[loop_index].m_fi;
		}
	    }
	    const ON_3dPoint edge_start = edge.PointAtStart();
	    const ON_3dPoint edge_end = edge.PointAtEnd();
	    size_t best_position = source_boundary.size();
	    double best_endpoint_distance =
		std::numeric_limits<double>::infinity();
	    bool best_reversed = false;
	    for (size_t source_position = 0;
		 source_position < source_boundary.size(); ++source_position)
	    {
		const double forward_distance = std::max(
		    edge_start.DistanceTo(
			source_boundary[source_position]->PointAtStart()),
		    edge_end.DistanceTo(
			source_boundary[source_position]->PointAtEnd()));
		const double reverse_distance = std::max(
		    edge_start.DistanceTo(
			source_boundary[source_position]->PointAtEnd()),
		    edge_end.DistanceTo(
			source_boundary[source_position]->PointAtStart()));
		const double endpoint_distance = std::min(forward_distance,
		    reverse_distance);
		if (endpoint_distance < best_endpoint_distance) {
		    best_endpoint_distance = endpoint_distance;
		    best_position = source_position;
		    best_reversed = reverse_distance < forward_distance;
		}
	    }
	    bool coincident_reversed = false;
	    const bool coincident = best_position < source_boundary.size() &&
		brep_curves_coincident(edge, *source_boundary[best_position],
		    repair_tolerance, &coincident_reversed);
	    const bool coincident_twice = best_position < source_boundary.size() &&
		brep_curves_coincident(edge, *source_boundary[best_position],
		    2.0 * repair_tolerance, NULL);
	    bu_log("  remaining naked edge %d face %d%s trim %d vertices %d/%d "
		"endpoints %.17g %.17g %.17g -> %.17g %.17g %.17g best "
		"source %zu endpoint %.17g reversed %d coincident %d/%d curve "
		"reversed %d.\n", edge_index, face_index,
		face_index == new_face_index ? " (cap)" : "", trim_index,
		edge.m_vi[0], edge.m_vi[1], edge_start.x, edge_start.y,
		edge_start.z, edge_end.x, edge_end.y, edge_end.z, best_position,
		best_endpoint_distance, best_reversed, coincident,
		coincident_twice, coincident_reversed);
	}
    }
    const bool topology_matches =
	repaired.m_S.Count() == surface_count_before + 1 &&
	repaired.m_F.Count() == face_count_before + 1 &&
	repaired.m_L.Count() == loop_count_before + 1 &&
	repaired.m_T.Count() == trim_count_before +
	    static_cast<int>(ordered_edges.size()) &&
	repaired.m_E.Count() == edge_count_before &&
	repaired.m_V.Count() == vertex_count_before;
    const int cycle_edge_count = static_cast<int>(ordered_edges.size());
    if (!valid || !solid || !topology_matches ||
	naked_before != cycle_edge_count || naked_after != 0)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_String message(validation_text);
	    bu_log("Boolean missing subtraction cap rolled back: valid %d, "
		"solid %d, topology %d, naked %d -> %d%s%s.\n",
		valid, solid, topology_matches, naked_before, naked_after,
		message.Array() && message.Array()[0] ? ": " : "",
		message.Array() ? message.Array() : "");
	}
	return BOOLEAN_MISSING_CAP_REPAIR_FAILURE;
    }

    if (DEBUG_BREP_BOOLEAN) {
	bu_log("Boolean missing subtraction cap repaired from operand %d face %d "
	    "at tolerance %.17g.\n", selected_operand, selected_face_index,
	    repair_tolerance);
    }
    *brep = repaired;
    return BOOLEAN_MISSING_CAP_REPAIR_COMPLETE;
}


static double
boolean_measured_tolerance(double residual)
{
    return residual > ON_ZERO_TOLERANCE ?
	residual * BOOLEAN_OUTPUT_TOLERANCE_SAFETY_FACTOR : 0.0;
}


static bool
align_boolean_surface_parameter(
    const ON_Surface *surface,
    const ON_2dPoint &surface_parameter,
    const ON_3dPoint &trim_parameter,
    ON_2dPoint &aligned_parameter)
{
    if (surface == NULL || !surface_parameter.IsValid() ||
	!trim_parameter.IsValid())
    {
	return false;
    }

    aligned_parameter = surface_parameter;
    if (surface->IsClosed(0)) {
	const double period = surface->Domain(0).Length();
	if (!(period > ON_ZERO_TOLERANCE) || !std::isfinite(period)) {
	    return false;
	}
	aligned_parameter.x += std::round((trim_parameter.x -
		aligned_parameter.x) / period) * period;
    }
    if (surface->IsClosed(1)) {
	const double period = surface->Domain(1).Length();
	if (!(period > ON_ZERO_TOLERANCE) || !std::isfinite(period)) {
	    return false;
	}
	aligned_parameter.y += std::round((trim_parameter.y -
		aligned_parameter.y) / period) * period;
    }

    return aligned_parameter.IsValid();
}


static bool
measure_boolean_trim_parameter_distance(
    const ON_Surface *surface,
    const ON_2dPoint &surface_parameter,
    const ON_3dPoint &trim_parameter,
    double &maximum_u_distance,
    double &maximum_v_distance)
{
    ON_2dPoint aligned_parameter = ON_2dPoint::UnsetPoint;
    if (!align_boolean_surface_parameter(surface, surface_parameter,
	trim_parameter, aligned_parameter))
    {
	return false;
    }

    maximum_u_distance = std::max(maximum_u_distance,
	fabs(aligned_parameter.x - trim_parameter.x));
    maximum_v_distance = std::max(maximum_v_distance,
	fabs(aligned_parameter.y - trim_parameter.y));
    return std::isfinite(maximum_u_distance) &&
	std::isfinite(maximum_v_distance);
}


static bool
project_boolean_point_to_surface(
    brlcad::PullbackContext &context,
    const ON_Surface *surface,
    const ON_3dPoint &point,
    double maximum_distance,
    ON_2dPoint &surface_parameter,
    double *projected_distance = NULL)
{
    ON_3dPoint lifted_point = ON_3dPoint::UnsetPoint;
    double distance = MAX_FASTF;

    const bool projected = context.SurfaceClosestPoint(surface, point, surface_parameter,
	lifted_point, distance, 0, BREP_SAME_POINT_TOLERANCE,
	maximum_distance) && surface_parameter.IsValid() &&
	lifted_point.IsValid() && std::isfinite(distance);
    if (projected_distance != NULL) {
	*projected_distance = distance;
    }
    return projected;
}


static bool
measure_boolean_trim_endpoint_tolerance(
    const ON_BrepTrim &trim,
    int endpoint_index,
    brlcad::PullbackContext &context,
    double &maximum_u_distance,
    double &maximum_v_distance)
{
    const ON_BrepVertex *vertex = trim.Vertex(endpoint_index);
    const ON_Surface *surface = trim.SurfaceOf();
    const ON_3dPoint trim_parameter = endpoint_index == 0 ?
	trim.PointAtStart() : trim.PointAtEnd();
    if (vertex == NULL || surface == NULL || !trim_parameter.IsValid()) {
	return false;
    }

    const ON_3dPoint trim_point = surface->PointAt(trim_parameter.x,
	trim_parameter.y);
    const double vertex_tolerance = vertex->m_tolerance;
    if (!trim_point.IsValid() || !(vertex_tolerance >= 0.0)) {
	return false;
    }
    if (trim_point.DistanceTo(vertex->Point()) <= vertex_tolerance +
	ON_ZERO_TOLERANCE)
    {
	return true;
    }

    ON_2dPoint surface_parameter = ON_2dPoint::UnsetPoint;
    double projected_distance = MAX_FASTF;
    if (!project_boolean_point_to_surface(context, surface, vertex->Point(),
	std::max(vertex_tolerance, BREP_EDGE_MISS_TOLERANCE),
	surface_parameter, &projected_distance) ||
	projected_distance > vertex_tolerance + ON_ZERO_TOLERANCE)
    {
	return false;
    }

    return measure_boolean_trim_parameter_distance(surface, surface_parameter,
	trim_parameter, maximum_u_distance, maximum_v_distance);
}


static bool
boolean_closest_polyline_point(
    const ON_PolylineCurve &polyline,
    const ON_3dPoint &point,
    ON_3dPoint &closest)
{
    if (!point.IsValid() || polyline.m_pline.Count() < 2) {
	return false;
    }

    /* A polyline has an exact piecewise-linear closest-point calculation.
     * Avoid converting it to a many-span NURBS and invoking a global solver
     * once for every tolerance sample. */
    double closest_distance_squared = std::numeric_limits<double>::max();
    closest = ON_3dPoint::UnsetPoint;
    for (int point_index = 1;
	 point_index < polyline.m_pline.Count(); ++point_index)
    {
	const ON_3dPoint start = polyline.m_pline[point_index - 1];
	const ON_3dPoint end = polyline.m_pline[point_index];
	if (!start.IsValid() || !end.IsValid()) {
	    return false;
	}

	const ON_3dVector segment = end - start;
	const double length_squared = segment * segment;
	if (!std::isfinite(length_squared)) {
	    return false;
	}
	double fraction = 0.0;
	if (length_squared > 0.0) {
	    fraction = ((point - start) * segment) / length_squared;
	    fraction = std::max(0.0, std::min(1.0, fraction));
	}
	const ON_3dPoint candidate = start + fraction * segment;
	const ON_3dVector separation = point - candidate;
	const double distance_squared = separation * separation;
	if (!candidate.IsValid() || !std::isfinite(distance_squared)) {
	    return false;
	}
	if (distance_squared < closest_distance_squared) {
	    closest_distance_squared = distance_squared;
	    closest = candidate;
	}
    }

    return closest.IsValid();
}


static bool
set_boolean_trim_tolerance(
    ON_BrepTrim &trim,
    brlcad::PullbackContext &context)
{
    const ON_Curve *trim_curve = trim.TrimCurveOf();
    const ON_Surface *surface = trim.SurfaceOf();
    if (trim_curve == NULL || surface == NULL) {
	return false;
    }

    double maximum_u_distance = 0.0;
    double maximum_v_distance = 0.0;
    const bool start_measured = measure_boolean_trim_endpoint_tolerance(trim,
	0, context, maximum_u_distance, maximum_v_distance);
    const bool end_measured = start_measured &&
	measure_boolean_trim_endpoint_tolerance(trim, 1, context,
	    maximum_u_distance, maximum_v_distance);
    if (!start_measured || !end_measured)
    {
	if (DEBUG_BREP_BOOLEAN) {
	    const ON_BrepVertex *start_vertex = trim.Vertex(0);
	    const ON_BrepVertex *end_vertex = trim.Vertex(1);
	    const ON_3dPoint start_parameter = trim.PointAtStart();
	    const ON_3dPoint end_parameter = trim.PointAtEnd();
	    const ON_3dPoint start_point = start_parameter.IsValid() ?
		 surface->PointAt(start_parameter.x, start_parameter.y) :
		 ON_3dPoint::UnsetPoint;
	    const ON_3dPoint end_point = end_parameter.IsValid() ?
		 surface->PointAt(end_parameter.x, end_parameter.y) :
		 ON_3dPoint::UnsetPoint;
	    bu_log("Boolean trim %d endpoint tolerance failed at %s: "
		"distances %.17g/%.17g, vertex tolerances %.17g/%.17g.\n",
		trim.m_trim_index, start_measured ? "end" : "start",
		start_vertex && start_point.IsValid() ?
		start_point.DistanceTo(start_vertex->Point()) : -1.0,
		end_vertex && end_point.IsValid() ?
		end_point.DistanceTo(end_vertex->Point()) : -1.0,
		start_vertex ? start_vertex->m_tolerance : -1.0,
		end_vertex ? end_vertex->m_tolerance : -1.0);
	}
	return false;
    }

    if (trim.m_type != ON_BrepTrim::singular) {
	const ON_Curve *edge_curve = trim.EdgeCurveOf();
	const ON_BrepEdge *edge = trim.Edge();
	if (edge_curve == NULL || edge == NULL || !(edge->m_tolerance >= 0.0)) {
	    return false;
	}

	std::unique_ptr<ON_Curve> lifted_trim(
	    pushup_boolean_trim_curve(surface, *trim_curve));
	/* A trim copied from its source edge often lifts to the exact same NURBS.
	 * In that case endpoint measurements already provide the parameter-space
	 * tolerance, and no interior closest-point searches are needed. */
	if (lifted_trim && brep_curves_coincident(*edge_curve, *lifted_trim,
		0.0))
	{
	    trim.m_tolerance[0] =
		boolean_measured_tolerance(maximum_u_distance);
	    trim.m_tolerance[1] =
		boolean_measured_tolerance(maximum_v_distance);
	    return true;
	}

	ON_NurbsCurve trim_nurbs;
	if (trim_curve->GetNurbForm(trim_nurbs) <= 0) {
	    return false;
	}
	const ON_PolylineCurve *trim_polyline =
	    ON_PolylineCurve::Cast(trim_curve);

	const double projection_tolerance = std::max(edge->m_tolerance,
	    BREP_EDGE_MISS_TOLERANCE);
	if (!for_each_boolean_curve_sample(*edge_curve,
	    [&](const ON_3dPoint &edge_point) {
		ON_2dPoint surface_parameter = ON_2dPoint::UnsetPoint;
		if (!project_boolean_point_to_surface(context, surface, edge_point,
			projection_tolerance, surface_parameter))
		{
		    return false;
		}

		const ON_3dPoint target(surface_parameter.x, surface_parameter.y,
		    0.0);
		ON_3dPoint closest_trim_parameter = ON_3dPoint::UnsetPoint;
		if (trim_polyline != NULL) {
		    if (!boolean_closest_polyline_point(*trim_polyline, target,
			    closest_trim_parameter))
		    {
			return false;
		    }
		} else {
		    double trim_curve_parameter = 0.0;
		    if (!ON_NurbsCurve_GetClosestPoint(&trim_curve_parameter,
			    &trim_nurbs, target))
		    {
			return false;
		    }
		    closest_trim_parameter = trim_nurbs.PointAt(
			trim_curve_parameter);
		}
		return measure_boolean_trim_parameter_distance(surface,
		    surface_parameter, closest_trim_parameter,
		    maximum_u_distance, maximum_v_distance);
	    }))
	{
	    return false;
	}
    }

    trim.m_tolerance[0] = boolean_measured_tolerance(maximum_u_distance);
    trim.m_tolerance[1] = boolean_measured_tolerance(maximum_v_distance);
    return true;
}


static bool
set_boolean_trim_tolerances(ON_Brep *brep)
{
    if (brep == NULL) {
	return false;
    }

    brlcad::PullbackContext context;
    for (int trim_index = 0; trim_index < brep->m_T.Count(); ++trim_index) {
	if (!set_boolean_trim_tolerance(brep->m_T[trim_index], context)) {
	    bu_log("Unable to measure Boolean output trim tolerance %d.\n",
		trim_index);
	    return false;
	}
    }

    return true;
}


static bool
set_boolean_edge_tolerance(ON_BrepEdge &edge, double proof_tolerance)
{
    if (edge.m_edge_user.i == BOOLEAN_CERTIFIED_EDGE_TOLERANCE_TAG) {
	return edge.TrimCount() == 2 && std::isfinite(edge.m_tolerance) &&
	    edge.m_tolerance >= 0.0;
    }

    if (edge.TrimCount() < 1) {
	edge.m_tolerance = 0.0;
	return true;
    }

    const ON_Curve *edge_curve = edge.EdgeCurveOf();
    if (edge_curve == NULL) {
	bu_log("Boolean output edge has no 3-D curve.\n");
	return false;
    }

    ON_NurbsCurve edge_nurbs;
    if (edge_curve->GetNurbForm(edge_nurbs) <= 0) {
	bu_log("Boolean output edge cannot be converted to a NURBS curve.\n");
	return false;
    }

    double maximum_distance = 0.0;
    for (int trim_position = 0; trim_position < edge.TrimCount(); ++trim_position) {
	const ON_BrepTrim *trim = edge.Trim(trim_position);
	if (trim == NULL || trim->m_type == ON_BrepTrim::singular) {
	    bu_log("Boolean output edge has an invalid trim.\n");
	    return false;
	}

	const ON_Surface *surface = trim->SurfaceOf();
	if (surface == NULL) {
	    bu_log("Boolean output edge trim has no surface.\n");
	    return false;
	}

	ON_Curve *trim_curve = pushup_boolean_trim_curve(surface, *trim);
	if (trim_curve == NULL) {
	    bu_log("Boolean output edge trim cannot be lifted.\n");
	    return false;
	}

	/* First try bounded full-curve proofs.  Dense polyline trims can otherwise
	 * trigger thousands of unbounded global closest-point solves below. */
	double certified_tolerance = 0.0;
	if (brep_curves_coincident(*edge_curve, *trim_curve,
		INTERSECTION_TOL))
	{
	    certified_tolerance = INTERSECTION_TOL;
	} else if (proof_tolerance > INTERSECTION_TOL &&
	    brep_curves_coincident(*edge_curve, *trim_curve,
		proof_tolerance))
	{
	    certified_tolerance = proof_tolerance;
	}
	if (certified_tolerance > 0.0) {
	    maximum_distance = std::max(maximum_distance,
		certified_tolerance);
	    delete trim_curve;
	    continue;
	}

	ON_NurbsCurve trim_nurbs;
	const bool trim_nurbs_set = trim_curve->GetNurbForm(trim_nurbs) > 0;
	const bool edge_to_trim_measured = trim_nurbs_set &&
	    measure_curve_to_nurbs_distance(edge_curve, &trim_nurbs, maximum_distance);
	const bool trim_to_edge_measured = edge_to_trim_measured &&
	    measure_curve_to_nurbs_distance(trim_curve, &edge_nurbs, maximum_distance);
	delete trim_curve;
	if (!trim_to_edge_measured) {
	    bu_log("Boolean output edge and trim residual cannot be measured.\n");
	    return false;
	}
    }

    if (!(maximum_distance >= 0.0)) {
	return false;
    }

    edge.m_tolerance = boolean_measured_tolerance(maximum_distance);
    return true;
}


static bool
set_boolean_edge_tolerances(ON_Brep *brep)
{
    if (brep == NULL) {
	return false;
    }

    const double proof_tolerance = 2.0 * boolean_model_repair_tolerance(
	brep->BoundingBox());
    if (!(proof_tolerance > 0.0) || !std::isfinite(proof_tolerance)) {
	return false;
    }

    /* Certified repaired edges retain their proven bound; all others are
     * measured normally. */
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	if (!set_boolean_edge_tolerance(brep->m_E[edge_index],
		proof_tolerance)) {
	    bu_log("Unable to measure Boolean output edge tolerance %d.\n",
		   edge_index);
	    return false;
	}
    }

    return true;
}


// Coplanar union loops can legitimately reach beyond an input face domain.
static bool
expand_boolean_planar_output_support(
    ON_Surface *surface,
    const ON_SimpleArray<TrimmedFace *> &faces)
{
    if (surface == NULL) {
	return false;
    }

    bool have_bounds = false;
    ON_BoundingBox parameter_bounds;
    for (int face_index = 0; face_index < faces.Count(); ++face_index) {
	const TrimmedFace *face = faces[face_index];
	if (face == NULL || face->m_belong_to_final != TrimmedFace::BELONG) {
	    continue;
	}

	for (int curve_index = 0;
	     curve_index < face->m_outerloop.Count(); ++curve_index)
	{
	    const ON_Curve *curve = face->m_outerloop[curve_index];
	    ON_BoundingBox curve_bounds;
	    if (curve == NULL || !curve->GetTightBoundingBox(curve_bounds) ||
		!curve_bounds.IsValid())
	    {
		return false;
	    }
	    if (have_bounds) {
		parameter_bounds.Union(curve_bounds);
	    } else {
		parameter_bounds = curve_bounds;
		have_bounds = true;
	    }
	}
    }

    if (!have_bounds || !parameter_bounds.IsValid()) {
	return false;
    }

    ON_Interval u_domain = surface->Domain(0);
    ON_Interval v_domain = surface->Domain(1);
    if (!u_domain.IsValid() || !v_domain.IsValid()) {
	return false;
    }
    const bool extend_u = parameter_bounds.Min().x < u_domain.Min() ||
	parameter_bounds.Max().x > u_domain.Max();
    const bool extend_v = parameter_bounds.Min().y < v_domain.Min() ||
	parameter_bounds.Max().y > v_domain.Max();
    if (!extend_u && !extend_v) {
	return true;
    }
    if (!surface->IsPlanar(NULL)) {
	return true;
    }

    u_domain.Set(std::min(u_domain.Min(), parameter_bounds.Min().x),
	std::max(u_domain.Max(), parameter_bounds.Max().x));
    v_domain.Set(std::min(v_domain.Min(), parameter_bounds.Min().y),
	std::max(v_domain.Max(), parameter_bounds.Max().y));
    return (!extend_u || surface->Extend(0, u_domain)) &&
	(!extend_v || surface->Extend(1, v_domain));
}


static int
finalize_boolean_output(ON_Brep *brep)
{
    if (brep == NULL) {
	return BREP_BOOLEAN_INVALID_INPUT;
    }

    /* Edge merging, trim-gap closure, and source-partition repair can change
     * a trim after its face was first assembled.  Recompute derived trim
     * metadata from the final curves before asking OpenNURBS to validate it. */
    brep->SetTrimBoundingBoxes(false);
    const bool trim_iso_flags_set = brep->SetTrimIsoFlags();
    const bool trim_type_flags_set = trim_iso_flags_set &&
	brep->SetTrimTypeFlags(false);
    const bool vertex_tolerances_set = trim_type_flags_set &&
	brep->SetVertexTolerances(false);
    const bool edge_tolerances_set = set_boolean_edge_tolerances(brep);
    const bool trim_tolerances_set = set_boolean_trim_tolerances(brep);
    if (!trim_iso_flags_set || !trim_type_flags_set ||
	!edge_tolerances_set || !trim_tolerances_set || !vertex_tolerances_set)
    {
	record_boolean_output_topology(brep);
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_OUTPUT_VALIDATION,
	    BREP_BOOLEAN_FAILURE_REASON_TOLERANCE_UPDATE);
	bu_log("Unable to determine Boolean output tolerances.\n");
	brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }

    ON_wString ws;
    ON_TextLog log(ws);
    const bool valid = brep->IsValid(&log);
    const bool solid = valid && brep->IsSolid();
    if (!valid || !solid) {
	record_boolean_output_topology(brep);
	enum brep_boolean_failure_reason reason =
	    valid ? BREP_BOOLEAN_FAILURE_REASON_OUTPUT_NOT_SOLID :
	    BREP_BOOLEAN_FAILURE_REASON_OUTPUT_INVALID;
	if (boolean_failure_info != NULL &&
	    boolean_failure_info->output_nonmanifold_edges > 0)
	{
	    reason = BREP_BOOLEAN_FAILURE_REASON_NONMANIFOLD_EDGE;
	} else if (boolean_failure_info != NULL &&
	    boolean_failure_info->ambiguous_edge_matches > 0)
	{
	    reason = BREP_BOOLEAN_FAILURE_REASON_AMBIGUOUS_EDGE_MATCH;
	} else if (boolean_failure_info != NULL &&
	    boolean_failure_info->output_naked_edges > 0)
	{
	    reason = BREP_BOOLEAN_FAILURE_REASON_UNMATCHED_EDGE;
	}
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_OUTPUT_VALIDATION,
	    reason);
	bu_log("Boolean output finalization failed: valid %d, solid %d.\n",
	    valid, solid);
	if (valid && !solid) {
	    static const int maximum_reported_naked_edges = 32;
	    int reported_naked_edges = 0;
	    int naked_edge_count = 0;
	    for (int edge_index = 0; edge_index < brep->m_E.Count();
		 ++edge_index)
	    {
		const ON_BrepEdge &edge = brep->m_E[edge_index];
		if (edge.TrimCount() == 2) {
		    continue;
		}
		++naked_edge_count;
		if (!DEBUG_BREP_BOOLEAN && reported_naked_edges >=
			maximum_reported_naked_edges)
		{
		    continue;
		}
		int face_index = -1;
		if (edge.m_ti.Count() == 1 && edge.m_ti[0] >= 0 &&
		    edge.m_ti[0] < brep->m_T.Count())
		{
		    face_index = brep->m_T[edge.m_ti[0]].FaceIndexOf();
		}
		const ON_3dPoint start = edge.PointAtStart();
		const ON_3dPoint end = edge.PointAtEnd();
		const int source_face = face_index >= 0 ?
		    brep->m_F[face_index].m_face_user.i - FACE_SOURCE_TAG_OFFSET : -1;
		bu_log("  edge %d has %d trims on face %d (source %d), vertices %d -> %d, "
		    "tolerance %.17g, curve %.17g %.17g %.17g -> %.17g "
		    "%.17g %.17g.\n", edge_index, edge.TrimCount(), face_index,
		    source_face, edge.m_vi[0], edge.m_vi[1], edge.m_tolerance, start.x,
		    start.y, start.z, end.x, end.y, end.z);
		if (DEBUG_BREP_BOOLEAN && edge.m_ti.Count() == 1) {
		    const ON_BrepTrim &trim = brep->m_T[edge.m_ti[0]];
		    const ON_BrepLoop *loop = trim.m_li >= 0 &&
			trim.m_li < brep->m_L.Count() ? &brep->m_L[trim.m_li] : NULL;
		    const ON_3dPoint uv_start = trim.PointAtStart();
		    const ON_3dPoint uv_end = trim.PointAtEnd();
		    bu_log("    trim %d loop %d type %d (%d trims), type %d, "
			"reversed %d, vertices %d -> %d, uv %.17g %.17g -> "
			"%.17g %.17g.\n", trim.m_trim_index, trim.m_li,
			loop ? static_cast<int>(loop->m_type) : -1,
			loop ? loop->m_ti.Count() : -1,
			static_cast<int>(trim.m_type), trim.m_bRev3d,
			trim.m_vi[0], trim.m_vi[1], uv_start.x, uv_start.y,
			uv_end.x, uv_end.y);
		}
		++reported_naked_edges;
	    }
	    if (reported_naked_edges < naked_edge_count) {
		bu_log("  ... %d additional naked edges omitted.\n",
		    naked_edge_count - reported_naked_edges);
	    }
	}
        if (ON_String(ws).Array()) {
	    bu_log("%s", ON_String(ws).Array());
	}
	brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    /* m_edge_user is internal scratch storage only; never expose the
     * tolerance-certification marker in a returned B-rep. */
    for (int edge_index = 0; edge_index < brep->m_E.Count(); ++edge_index) {
	if (brep->m_E[edge_index].m_edge_user.i ==
		BOOLEAN_CERTIFIED_EDGE_TOLERANCE_TAG)
	{
	    brep->m_E[edge_index].m_edge_user.i = 0;
	}
    }
    if (ON_String(ws).Array()) {
	bu_log("%s", ON_String(ws).Array());
    }

    return BREP_BOOLEAN_SUCCESS;
}


static int
stitch_boolean_output_edges(ON_Brep *brep, double tolerance,
    brep_assembly_result *report)
{
    if (brep == NULL)
	return -1;
    std::vector<int> source_tags;
    source_tags.reserve(brep->m_F.Count());
    for (int face_index = 0; face_index < brep->m_F.Count(); ++face_index)
	source_tags.push_back(brep->m_F[face_index].m_face_user.i);

    const int status = brep_stitch_naked_edges(*brep, tolerance, report);
    if (status < 0)
	return status;
    if (brep->m_F.Count() != static_cast<int>(source_tags.size()))
	return -1;
    for (int face_index = 0; face_index < brep->m_F.Count(); ++face_index)
	brep->m_F[face_index].m_face_user.i = source_tags[face_index];
    return status;
}


static bool
compact_boolean_output(ON_Brep *brep)
{
    if (brep == NULL)
	return false;
    std::vector<int> source_tags;
    source_tags.reserve(brep->m_F.Count());
    for (int face_index = 0; face_index < brep->m_F.Count(); ++face_index)
	source_tags.push_back(brep->m_F[face_index].m_face_user.i);
    if (!brep->Compact() ||
	brep->m_F.Count() != static_cast<int>(source_tags.size()))
    {
	return false;
    }
    for (int face_index = 0; face_index < brep->m_F.Count(); ++face_index)
	brep->m_F[face_index].m_face_user.i = source_tags[face_index];
    return true;
}


static bool
append_boolean_preserved_components(
    ON_Brep *brep,
    const std::vector<BooleanPreservedComponent> &preserved_components)
{
    if (brep == NULL) {
	return false;
    }

    for (size_t component_index = 0;
	 component_index < preserved_components.size();
	 ++component_index)
    {
	const BooleanPreservedComponent &component =
	    preserved_components[component_index];
	if (component.m_brep == NULL || component.m_face_indices.empty()) {
	    return false;
	}

	std::unique_ptr<ON_Brep> copy(component.m_brep->DuplicateFaces(
	    static_cast<int>(component.m_face_indices.size()),
	    component.m_face_indices.data(), false));
	if (!copy || !copy->IsValid() || !copy->IsSolid()) {
	    return false;
	}
	brep->Append(*copy);
    }

    return true;
}


static int
evaluate_boolean(ON_Brep *evaluated_brep, const ON_Brep *brep1,
    const ON_Brep *brep2, op_type operation)
{
    static int calls = 0;
    ++calls;
    evaluated_brep->Destroy();
    std::ostringstream prefix;
    prefix << "bool" << calls;
    //dplot = new DebugPlot(prefix.str().c_str());
    //dplot->Surfaces(brep1, brep2);
    //dplot->WriteLog();

    ON_ClassArray<ON_SimpleArray<TrimmedFace *> > trimmed_faces;
    ON_ClassArray<SharedSSICurve> shared_curves;
    std::vector<BooleanPreservedComponent> preserved_components;
	const bool brep1_empty = brep1->m_F.Count() == 0;
	const bool brep2_empty = brep2->m_F.Count() == 0;
	if (brep1_empty || brep2_empty) {
	    switch (operation) {
		case BOOLEAN_UNION:
		case BOOLEAN_XOR:
		    if (!brep1_empty) {
			evaluated_brep->Append(*brep1);
		    }
		    if (!brep2_empty) {
			evaluated_brep->Append(*brep2);
		    }
		    break;
		case BOOLEAN_DIFF:
		    if (!brep1_empty) {
			evaluated_brep->Append(*brep1);
		    }
		    break;
		case BOOLEAN_INTERSECT:
		    break;
		default:
		    throw InvalidBooleanOperation("Error - unknown boolean operation\n");
	    }

	    if (evaluated_brep->m_F.Count() == 0) {
		return BREP_BOOLEAN_EMPTY;
	    }

	    evaluated_brep->ShrinkSurfaces();
	    evaluated_brep->Compact();
	    return finalize_boolean_output(evaluated_brep);
	}

	ON_BoundingBox brep1_bbox;
	ON_BoundingBox brep2_bbox;
	if (!boolean_brep_bounding_box(brep1, brep1_bbox) ||
	    !boolean_brep_bounding_box(brep2, brep2_bbox)) {
	    record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_OPERAND_BOUNDS,
		BREP_BOOLEAN_FAILURE_REASON_OPERAND_BOUNDS);
	    throw GeometryGenerationError("Unable to determine Boolean operand bounds.\n");
	}

	// A shared boundary cannot contribute volume to a solid difference or
	// intersection.  Keep boundary-contact union handling on the general path.
	if (bounding_box_interiors_are_disjoint(brep1_bbox, brep2_bbox)) {
	    if (operation == BOOLEAN_DIFF) {
		evaluated_brep->Append(*brep1);
		evaluated_brep->ShrinkSurfaces();
		evaluated_brep->Compact();
		return finalize_boolean_output(evaluated_brep);
	    }
	    if (operation == BOOLEAN_INTERSECT) {
		return BREP_BOOLEAN_EMPTY;
	    }
	}

	/* Deal with the trivial cases up front */
	bool component_bounds_are_separated =
	    brep1_bbox.MinimumDistanceTo(brep2_bbox) > ON_ZERO_TOLERANCE;
	if (!component_bounds_are_separated) {
	    std::vector<ON_BoundingBox> brep1_component_bboxes;
	    std::vector<ON_BoundingBox> brep2_component_bboxes;
	    if (boolean_brep_component_bounding_boxes(brep1,
		brep1_component_bboxes) &&
		boolean_brep_component_bounding_boxes(brep2,
		    brep2_component_bboxes))
	    {
		component_bounds_are_separated =
		    boolean_component_bounds_are_separated(brep1_component_bboxes,
			brep2_component_bboxes);
	    }
	}
	if (component_bounds_are_separated) {
	    switch (operation) {
		case BOOLEAN_UNION:
		case BOOLEAN_XOR:
		    evaluated_brep->Append(*brep1);
		    evaluated_brep->Append(*brep2);
		    break;
		case BOOLEAN_DIFF:
		    evaluated_brep->Append(*brep1);
		    break;
		case BOOLEAN_INTERSECT:
		    return BREP_BOOLEAN_EMPTY;
		default:
		    throw InvalidBooleanOperation("Error - unknown boolean operation\n");
	    }
	    evaluated_brep->ShrinkSurfaces();
	    evaluated_brep->Compact();
	    //dplot->WriteLog();
	    return finalize_boolean_output(evaluated_brep);
	}
	try {
	    trimmed_faces = get_evaluated_faces(brep1, brep2, brep1_bbox,
		brep2_bbox, operation, shared_curves, preserved_components);
	} catch (...) {
	    record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_SSI_PROCESSING,
		BREP_BOOLEAN_FAILURE_REASON_SSI_PROCESSING);
	    throw;
	}

    int face_count1 = brep1->m_F.Count();
    int face_count2 = brep2->m_F.Count();

    // check for face counts high enough to cause overflow
    if ((face_count1 + face_count2) < 0) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INTERNAL,
	    BREP_BOOLEAN_FAILURE_REASON_INTERNAL_ERROR);
	return BREP_BOOLEAN_INTERNAL_ERROR;
    }

    BooleanSharedTopology shared_topology(shared_curves);
    bool assembled = true;
    for (int i = 0; i < trimmed_faces.Count() && assembled; i++) {
	const ON_SimpleArray<TrimmedFace *> &splitted = trimmed_faces[i];
	const ON_Surface *surf = splitted.Count() ? splitted[0]->m_face->SurfaceOf() : NULL;
	bool added = false;
	for (int j = 0; j < splitted.Count() && assembled; j++) {
	    TrimmedFace *t_face = splitted[j];
	    if (t_face->m_belong_to_final == TrimmedFace::BELONG) {
		if (boolean_loop_is_model_point(surf,
			t_face->m_outerloop))
		{
		    if (DEBUG_BREP_BOOLEAN) {
			bu_log("Boolean omitted source face %d split %d with a "
			    "point-sized outer loop.\n", i, j);
		    }
		    continue;
		}

		// Add the surfaces, faces, loops, trims, vertices, edges, etc.
		// to the brep structure.
		if (!added) {
		    ON_Surface *new_surf = surf ? surf->Duplicate() : NULL;
		    if (new_surf == NULL || !expand_boolean_planar_output_support(
			new_surf, splitted))
		    {
			delete new_surf;
			assembled = false;
			break;
		    }
		    evaluated_brep->AddSurface(new_surf);
		    added = true;
		}
		ON_BrepFace &new_face = evaluated_brep->NewFace(evaluated_brep->m_S.Count() - 1);
		new_face.m_face_user.i = i + FACE_SOURCE_TAG_OFFSET;

		if (!add_elements(evaluated_brep, new_face, t_face->m_outerloop,
			ON_BrepLoop::outer, shared_topology, i)) {
		    assembled = false;
		    break;
		}
		// ON_BrepLoop &loop = evaluated_brep->m_L[evaluated_brep->m_L.Count() - 1];
		for (unsigned int k = 0;
		     k < t_face->m_innerloop.size() && assembled; k++) {
		    if (boolean_loop_is_model_point(new_face.SurfaceOf(),
			    t_face->m_innerloop[k]))
		    {
			if (DEBUG_BREP_BOOLEAN) {
			    bu_log("Boolean omitted point-sized inner loop %u on "
				"source face %d split %d.\n", k, i, j);
			}
			continue;
		    }
		    if (!add_elements(evaluated_brep, new_face,
			    t_face->m_innerloop[k], ON_BrepLoop::inner,
			    shared_topology, i)) {
			assembled = false;
		    }
		}
		if (!assembled) {
		    break;
		}

		evaluated_brep->SetTrimIsoFlags(new_face);
		const ON_BrepFace &original_face = i >= face_count1 ? brep2->m_F[i - face_count1] : brep1->m_F[i];
		if (original_face.m_bRev ^ t_face->m_rev) {
		    evaluated_brep->FlipFace(new_face);
		}
	    }
	}
    }

    for (int i = 0; i < face_count1 + face_count2; i++) {
	for (int j = 0; j < trimmed_faces[i].Count(); j++) {
	    if (trimmed_faces[i][j]) {
		delete trimmed_faces[i][j];
		trimmed_faces[i][j] = NULL;
	    }
	}
    }

    if (!assembled) {
	record_boolean_output_topology(evaluated_brep);
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_OUTPUT_ASSEMBLY,
	    BREP_BOOLEAN_FAILURE_REASON_OUTPUT_ASSEMBLY);
	bu_log("Unable to assemble Boolean output.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }

    if (!append_boolean_preserved_components(evaluated_brep,
	preserved_components))
    {
	record_boolean_output_topology(evaluated_brep);
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_OUTPUT_ASSEMBLY,
	    BREP_BOOLEAN_FAILURE_REASON_PRESERVED_COMPONENT);
	bu_log("Unable to preserve disjoint Boolean components.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }

    if (evaluated_brep->m_F.Count() == 0) {
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_EMPTY;
    }

    evaluated_brep->ShrinkSurfaces();
    if (!compact_boolean_output(evaluated_brep))
	return BREP_BOOLEAN_INDETERMINATE;
    standardize_loop_orientations(evaluated_brep);
    /* standardize_loop_orientations() may replace and reverse trim curves.
     * Their cached parameter-space boxes still describe the old proxies. */
    evaluated_brep->SetTrimBoundingBoxes(false);

    ON_wString assembly_log_text;
    ON_TextLog assembly_log(assembly_log_text);
    if (!evaluated_brep->IsValid(&assembly_log)) {
	record_boolean_output_topology(evaluated_brep);
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_OUTPUT_VALIDATION,
	    BREP_BOOLEAN_FAILURE_REASON_PRE_REPAIR_INVALID);
	bu_log("Boolean output is invalid before edge repair.\n");
	if (ON_String(assembly_log_text).Array()) {
	    bu_log("%s", ON_String(assembly_log_text).Array());
	}
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    if (!merge_boolean_naked_edges(evaluated_brep)) {
	record_boolean_edge_repair_failure(
	    BREP_BOOLEAN_FAILURE_REASON_EDGE_MERGE, evaluated_brep);
	bu_log("Unable to merge matching Boolean output edges.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    if (!compact_boolean_output(evaluated_brep))
	return BREP_BOOLEAN_INDETERMINATE;
    if (!repair_shared_open_ssi_edges(evaluated_brep, shared_curves)) {
	record_boolean_edge_repair_failure(
	    BREP_BOOLEAN_FAILURE_REASON_OPEN_SSI_EDGE, evaluated_brep);
	bu_log("Unable to repair matching open Boolean edges.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    if (!compact_boolean_output(evaluated_brep))
	return BREP_BOOLEAN_INDETERMINATE;
    if (!repair_shared_closed_ssi_edges(evaluated_brep, shared_curves)) {
	record_boolean_edge_repair_failure(
	    BREP_BOOLEAN_FAILURE_REASON_CLOSED_SSI_EDGE, evaluated_brep);
	bu_log("Unable to repair matching closed Boolean edges.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    if (!evaluated_brep->IsSolid()) {
	brep_assembly_result stitch_report;
	const double stitch_tolerance = 2.0 *
	    boolean_model_repair_tolerance(evaluated_brep->BoundingBox());
	const int stitch_status = stitch_boolean_output_edges(evaluated_brep,
	    stitch_tolerance, &stitch_report);
	record_boolean_ambiguous_edge_matches(stitch_report.ambiguous_edges);
	if (stitch_status < 0)
	{
	    bu_log("Deferred failed generic Boolean edge stitch to "
		"provenance-based repairs.\n");
	} else {
	    bu_log("Boolean edge stitch at tolerance %.17g merged %d edges; "
		"%d naked and %d ambiguous remain.\n", stitch_tolerance,
		stitch_report.merged_edges, stitch_report.remaining_naked_edges,
		stitch_report.ambiguous_edges);
	    if (!compact_boolean_output(evaluated_brep))
		return BREP_BOOLEAN_INDETERMINATE;
	}
    }
    if (!evaluated_brep->IsSolid() &&
	!repair_boolean_offset_seam_closed_edges(evaluated_brep))
    {
	record_boolean_edge_repair_failure(
	    BREP_BOOLEAN_FAILURE_REASON_OFFSET_SEAM, evaluated_brep);
	bu_log("Unable to reconcile offset seams on closed Boolean edges.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    if (!compact_boolean_output(evaluated_brep))
	return BREP_BOOLEAN_INDETERMINATE;
    if (!evaluated_brep->IsSolid() &&
	!repair_boolean_source_edge_partitions(evaluated_brep, brep1, brep2))
    {
	record_boolean_edge_repair_failure(
	    BREP_BOOLEAN_FAILURE_REASON_SOURCE_EDGE_PARTITION,
	    evaluated_brep);
	bu_log("Unable to reconcile split source-edge uses in Boolean output.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    if (!evaluated_brep->IsSolid() &&
	!repair_boolean_degenerate_source_edge_pairs(evaluated_brep, brep1,
	    brep2, shared_curves))
    {
	record_boolean_edge_repair_failure(
	    BREP_BOOLEAN_FAILURE_REASON_DEGENERATE_EDGE_PAIR,
	    evaluated_brep);
	bu_log("Unable to reconcile degenerate source-edge pairs in Boolean "
	    "output.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    if (!evaluated_brep->IsSolid()) {
	brep_assembly_result restitch_report;
	const double stitch_tolerance =
	    boolean_loop_closure_tolerance(INTERSECTION_TOL);
	const int restitch_status = stitch_boolean_output_edges(evaluated_brep,
	    stitch_tolerance, &restitch_report);
	record_boolean_ambiguous_edge_matches(restitch_report.ambiguous_edges);
	if (restitch_status < 0)
	{
	    bu_log("Deferred failed generic Boolean edge restitch to "
		"remaining provenance-based repairs.\n");
	} else if (DEBUG_BREP_BOOLEAN && restitch_report.merged_edges > 0) {
	    bu_log("Boolean edge restitch at tolerance %.17g merged %d edges; "
		"%d naked and %d ambiguous remain.\n", stitch_tolerance,
		restitch_report.merged_edges,
		restitch_report.remaining_naked_edges,
		restitch_report.ambiguous_edges);
	}
	if (restitch_status >= 0)
	    if (!compact_boolean_output(evaluated_brep))
		return BREP_BOOLEAN_INDETERMINATE;
    }
    /* Restitching can remove an ambiguous naked-edge candidate and thereby
     * leave a unique pair of sub-tolerance source/intersection fragments.
     * Re-run the provenance-qualified repair after that ambiguity has been
     * resolved; the repair is idempotent and still requires matching curve
     * loci, interval coverage, orientation, and unique source-edge ancestry. */
    if (!evaluated_brep->IsSolid() &&
	!repair_boolean_degenerate_source_edge_pairs(evaluated_brep, brep1,
	    brep2, shared_curves))
    {
	record_boolean_edge_repair_failure(
	    BREP_BOOLEAN_FAILURE_REASON_DEGENERATE_EDGE_PAIR,
	    evaluated_brep);
	bu_log("Unable to reconcile post-stitch degenerate source-edge pairs in "
	    "Boolean output.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    BooleanNakedEdgePartitionEvidence unresolved_partition;
    if (!evaluated_brep->IsSolid() &&
	!repair_boolean_naked_edge_partitions(evaluated_brep, shared_curves,
	    &unresolved_partition))
    {
	record_boolean_edge_repair_failure(
	    BREP_BOOLEAN_FAILURE_REASON_NAKED_EDGE_PARTITION,
	    evaluated_brep);
	bu_log("Unable to reconcile partitioned Boolean output seams.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    if (!evaluated_brep->IsSolid() &&
	!repair_boolean_naked_hairpins(evaluated_brep))
    {
	record_boolean_edge_repair_failure(
	    BREP_BOOLEAN_FAILURE_REASON_NAKED_HAIRPIN, evaluated_brep);
	bu_log("Unable to reconcile certified naked hairpins in Boolean output.\n");
	evaluated_brep->Destroy();
	return BREP_BOOLEAN_INDETERMINATE;
    }
    if (!evaluated_brep->IsSolid()) {
	const BooleanMissingCapRepairResult cap_repair =
	    repair_boolean_missing_subtraction_cap(evaluated_brep, brep1, brep2,
		operation, shared_curves);
	if (cap_repair == BOOLEAN_MISSING_CAP_REPAIR_FAILURE) {
	    record_boolean_edge_repair_failure(
		BREP_BOOLEAN_FAILURE_REASON_MISSING_CAP, evaluated_brep);
	    evaluated_brep->Destroy();
	    return BREP_BOOLEAN_INDETERMINATE;
	}
    }
    if (!evaluated_brep->IsSolid()) {
	/* Source-face tags and shared SSI triplets are still available here.
	 * Preserve the first provable edge-ledger distinction before finalization
	 * clears the internal provenance tags and reports only a generic naked
	 * edge.  This inspection does not modify the candidate B-Rep. */
	record_boolean_remaining_ssi_failure(evaluated_brep, shared_curves);
	if (boolean_failure_info != NULL &&
	    boolean_failure_info->stage == BREP_BOOLEAN_FAILURE_STAGE_NONE &&
	    unresolved_partition.reference_edge_index >= 0)
	{
	    record_boolean_output_topology(evaluated_brep);
	    record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_EDGE_REPAIR,
		BREP_BOOLEAN_FAILURE_REASON_NAKED_EDGE_PARTITION,
		unresolved_partition.reference_face_index,
		unresolved_partition.peer_face_index,
		unresolved_partition.reference_edge_index,
		unresolved_partition.peer_edge_index,
		unresolved_partition.tolerance);
	}
    }
    for (int face_index = 0; face_index < evaluated_brep->m_F.Count();
	 ++face_index)
    {
	evaluated_brep->m_F[face_index].m_face_user.i = 0;
    }
    evaluated_brep->Compact();

    //dplot->WriteLog();
    //delete dplot;
    //dplot = NULL;

    return finalize_boolean_output(evaluated_brep);
}


static int
boolean_failure(ON_Brep *evaluated_brep, int status, const char *detail)
{
    if (evaluated_brep != NULL) {
	evaluated_brep->Destroy();
    }
    bu_log("%s%s%s\n", ON_BooleanStatusDescription(status),
	detail != NULL && detail[0] != '\0' ? ": " : "",
	detail != NULL ? detail : "");
    return status;
}


int
ON_Boolean(ON_Brep *evaluated_brep, const ON_Brep *brep1,
    const ON_Brep *brep2, op_type operation,
    struct brep_boolean_failure_info *failure)
{
    BooleanFailureScope failure_scope(failure);
    if (evaluated_brep == NULL) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INPUT_VALIDATION,
	    BREP_BOOLEAN_FAILURE_REASON_INVALID_INPUT);
	return boolean_failure(NULL, BREP_BOOLEAN_INVALID_INPUT,
	    "output B-Rep is null");
    }
    if (brep1 == NULL || brep2 == NULL) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INPUT_VALIDATION,
	    BREP_BOOLEAN_FAILURE_REASON_INVALID_INPUT);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_INVALID_INPUT,
	    "input B-Rep is null");
    }
    if (evaluated_brep == brep1 || evaluated_brep == brep2) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INPUT_VALIDATION,
	    BREP_BOOLEAN_FAILURE_REASON_INVALID_INPUT);
	return boolean_failure(NULL, BREP_BOOLEAN_INVALID_INPUT,
	    "output B-Rep aliases an input");
    }
    if (operation < BOOLEAN_UNION || operation > BOOLEAN_XOR) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INPUT_VALIDATION,
	    BREP_BOOLEAN_FAILURE_REASON_UNSUPPORTED_OPERATION);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_UNSUPPORTED,
	    "unknown operation");
    }

    evaluated_brep->Destroy();
    try {
	if (!brep1->IsValid() || !brep2->IsValid()) {
	    record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INPUT_VALIDATION,
		BREP_BOOLEAN_FAILURE_REASON_INVALID_INPUT);
	    return boolean_failure(evaluated_brep, BREP_BOOLEAN_INVALID_INPUT,
		"input B-Rep is invalid");
	}

	const int status = evaluate_boolean(evaluated_brep, brep1, brep2,
	    operation);
	if (status < BREP_BOOLEAN_SUCCESS) {
	    if (status == BREP_BOOLEAN_BUDGET_EXCEEDED) {
		record_boolean_failure(
		    BREP_BOOLEAN_FAILURE_STAGE_SURFACE_INTERSECTION,
		    BREP_BOOLEAN_FAILURE_REASON_WORK_BUDGET);
	    } else if (status == BREP_BOOLEAN_INTERNAL_ERROR) {
		record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INTERNAL,
		    BREP_BOOLEAN_FAILURE_REASON_INTERNAL_ERROR);
	    } else {
		record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_SSI_PROCESSING,
		    BREP_BOOLEAN_FAILURE_REASON_SSI_PROCESSING);
	    }
	    evaluated_brep->Destroy();
	}
	return status;
    } catch (const BooleanBudgetExceeded &e) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_SURFACE_INTERSECTION,
	    BREP_BOOLEAN_FAILURE_REASON_WORK_BUDGET);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_BUDGET_EXCEEDED,
	    e.what());
    } catch (const InvalidBooleanOperation &e) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INPUT_VALIDATION,
	    BREP_BOOLEAN_FAILURE_REASON_UNSUPPORTED_OPERATION);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_UNSUPPORTED,
	    e.what());
    } catch (const InvalidGeometry &e) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_SSI_PROCESSING,
	    BREP_BOOLEAN_FAILURE_REASON_SSI_PROCESSING);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_INDETERMINATE,
	    e.what());
    } catch (const AlgorithmError &e) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INTERNAL,
	    BREP_BOOLEAN_FAILURE_REASON_INTERNAL_ERROR);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_INDETERMINATE,
	    e.what());
    } catch (const GeometryGenerationError &e) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_OUTPUT_ASSEMBLY,
	    BREP_BOOLEAN_FAILURE_REASON_OUTPUT_ASSEMBLY);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_INDETERMINATE,
	    e.what());
    } catch (const IntervalGenerationError &e) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_SSI_PROCESSING,
	    BREP_BOOLEAN_FAILURE_REASON_SSI_CLIPPING);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_INDETERMINATE,
	    e.what());
    } catch (const InvalidInterval &e) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_SSI_PROCESSING,
	    BREP_BOOLEAN_FAILURE_REASON_SSI_CLIPPING);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_INDETERMINATE,
	    e.what());
    } catch (const std::invalid_argument &e) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INPUT_VALIDATION,
	    BREP_BOOLEAN_FAILURE_REASON_INVALID_INPUT);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_INVALID_INPUT,
	    e.what());
    } catch (const std::exception &e) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INTERNAL,
	    BREP_BOOLEAN_FAILURE_REASON_INTERNAL_ERROR);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_INTERNAL_ERROR,
	    e.what());
    } catch (...) {
	record_boolean_failure(BREP_BOOLEAN_FAILURE_STAGE_INTERNAL,
	    BREP_BOOLEAN_FAILURE_REASON_INTERNAL_ERROR);
	return boolean_failure(evaluated_brep, BREP_BOOLEAN_INTERNAL_ERROR,
	    "unexpected non-standard exception");
    }
}


int
ON_Boolean(ON_Brep *evaluated_brep, const ON_Brep *brep1,
    const ON_Brep *brep2, op_type operation)
{
    return ON_Boolean(evaluated_brep, brep1, brep2, operation, NULL);
}


